	('aboutus_getactive', 'ru', 'messages', 'Вам нравится эта идея? Подключайтесь!', '2007-12-16 14:48:11', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 79),
	('aboutus_getactive', 'sl', 'messages', 'Ti je ideja všeč? Aktiviraj se!', '2019-03-30 23:13:30', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 106553),
	('aboutus_getactive', 'sr', 'messages', 'Допада ти се идеја? Активирај се!', '2012-12-19 00:15:53', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('aboutus_getactive', 'sv', 'messages', 'Du gillar tanken? Bli aktiv!', '2012-04-08 19:35:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 23263),
	('aboutus_getactive', 'tr', 'messages', 'Düşüncemizi beğendiniz mi? Daha etkin olun!', '2012-11-30 14:35:12', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 35699),
	('aboutus_getactive', 'uk', 'messages', 'Сподобалася ідея? Почніть діяти!', '2026-04-01 20:16:51', '2026-04-01 20:16:51', '2026-04-01 20:16:51', 'no', '', 5, NULL, 573491),
	('aboutus_getactive', 'vi', 'messages', 'Bạn thích ý tưởng này? Hành động thôi!', '2021-07-04 19:20:00', '2021-07-04 19:20:00', '2021-07-04 19:20:00', 'no', '', 5, NULL, 293926),
	('aboutus_getactive', 'zh-hans', 'messages', '觉得不错？那就加入吧！', '2010-03-04 05:15:23', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11819),
	('aboutus_getactive', 'zh-hant', 'messages', '你喜歡這個想法嗎？那就積極參與吧！', '2010-03-04 05:15:23', '2025-05-31 16:31:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 53422),
	('aboutus_getactivetext', 'ar', 'messages', 'انضم إلى أحد فرقنا: شارك العمل و ابدع و أمرح! نحن الان نبحث عن: <ul class="bullet"><li> مطورون</li><li> مصممون </li><li> مختبرون </li><li> عضو للدعم </li><li> مترجمين </li><li> متطوعين محليين </li> </ul><a href="about/getactive"> اتشعر انك تريد المساعدة؟ انقر هنا و اختر فريقك.</a>', '2014-04-11 09:27:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48359),
	('aboutus_getactivetext', 'ca', 'messages', 'Uneix-te a un dels nostres equips: compartir feina, compromís i passar-ho bé! Actualment estem buscant:\r\n<ul class="bullet"><li>Desenvolupament</li><li>Disseny</li><li>Proves</li><li>Suport als membres</li><li>Traducció</li><li>Voluntariat local</li> </ul>\r\n<a href="http://www.bewelcome.org/about/getactive">Tens ganes d\'ajudar? Clica aquí i tria el teu equip</a>', '2013-01-31 05:11:20', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 12861),
	('aboutus_getactivetext', 'cs', 'messages', 'Přidej se k nám: sdílej naše pracovní nasazení, odhodlání a potěšení!\r\nMomentálně hledáme:<ul class="bullet"><li>Vývojáře</li><li>Designéry</li><li>Testery</li><li>Členskou podporu</li><li>Překladatele</li><li>Lokální dobrovolníky</li> </ul><a href="about/getactive">Chce se ti pomáhat? Klikni sem a vyber si tým.</a>', '2008-08-07 16:35:38', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('aboutus_getactivetext', 'de', 'messages', 'Werde Mitglied in einem unserer Teams: Teile die Arbeit, das Engagement und die Freude! <br/>Derzeit suchen wir:<ul class="bullet"><li>Entwickler</li><li>Designer</li><li>Tester</li><li>Mitglieder-Support</li><li>Übersetzer</li><li>Helfer vor Ort</li></ul><a href="about/getactive">Lust mitzuhelfen? Dann klicke hier und wähle ein Team.</a>', '2007-12-12 18:59:52', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('aboutus_getactivetext', 'el', 'messages', 'Γίνε μέλος σε μία από τις ομάδες μας: μοιράσου τη δουλειά, την αφοσίωση και τη διασκέδαση! Αυτή τη στιγμή ψάχνουμε για:<ul class="bullet"><li>Προγραμματιστές,</li><li> Σχεδιαστές</li><li>Ελεγκτές</li><li>Υποστήριξη Μελών</li><li> Μεταφραστές</li><li> Τοπικούς Εθελοντές</li> </ul> <a href="http://www.bewelcome.org/about/getactive">Θέλεις να βοηθήσεις; Κάνε κλίκ εδώ και επίλεξε ομάδα</a>', '2013-02-28 13:29:42', '2020-09-02 09:05:17', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('aboutus_getactivetext', 'en', 'messages', 'Join one of our teams: Share the work, commitment and fun! We are currently looking for:<ul class="bullet"><li>Developers</li><li>Designers</li><li>Testers</li><li>Member Support</li><li>Translators</li><li>Local volunteers</li> </ul><a href="about/getactive">Feel like helping? Click here and choose your team.</a>', '2007-12-06 14:10:12', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', 'List of current volunteer options and link to get active', 5, NULL, 15240),
	('aboutus_getactivetext', 'eo', 'messages', 'Aliĝu al unu el niaj teamoj: dividu laboron, enagaĝiĝin kaj ĝojon! Aktuale ni serĉas: \r\n<ul class="bullet"><li>Programistojn</li><li>Dizajnistojn</li><li>Testantojn</li><li>Helpantojn</li><li>Tradukistojn</li><li>Lokajn volontulojn</li> </ul> \r\n<a href="http://www.bewelcome.org/about/getactive">Ĉu vi emas helpi? Klaku ĉi tie kaj elektu vian teamon.</a>', '2013-03-14 17:29:51', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 47220),
	('aboutus_getactivetext', 'es', 'messages', 'Ingresa a uno de nuestros grupos ¡Comparte el trabajo, el compromiso y la diversión! \r\nActualmente estamos buscando personas voluntarias para:\r\n<ul class="bullet"><li>Programación</li><li>Diseño</li><li>Testers</li><li>Soporte</li><li>Traducción</li><li>Voluntariado local</li> </ul>\r\n<a href="http://www.bewelcome.org/about/getactive">¿Quieres echarnos una mano? ¡Pincha aquí y elige tu equipo!</a>', '2007-12-31 03:15:26', '2020-11-30 18:27:12', '0000-00-00 00:00:00', 'no', '', 5, NULL, 25548),
	('aboutus_getactivetext', 'eu', 'messages', 'Gure taldeetariko baten parte hartu ezazu: lana, konpromezua eta dibertimendua konpartitu itzazu! Une honetan hurrengoen bila gabiltza:\r\n<ul class="bullet"><li>Garatzaileak</li><li>Diseinatzaileak</li><li>Aztertzaileak</li><li>Kide-laguntzaileak</li><li>Itzultzaileak</li><li>Boluntario lokalak</li> </ul>\r\n<a href="http://www.bewelcome.org/about/getactive">Laguntzeko gogorik? Sakatu hemen eta zeure taldea aukerazazu</a>.', '2008-06-09 10:25:35', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11907),
	('aboutus_getactivetext', 'fr', 'messages', 'Rejoignez l\'une de nos équipes&nbsp;: participez, engagez-vous et faites-vous plaisir&nbsp;! En ce moment nous cherchons des&nbsp;:\r\n<ul class="bullet"><li>développeurs&nbsp;;</li><li>designers&nbsp;;</li><li>testeurs&nbsp;;</li><li>membres pour l’équipe d’assistance&nbsp;;</li><li>traducteurs&nbsp;;</li><li>volontaires locaux.</li> </ul><a href="about/getactive">Vous avez envie de contribuer au projet&nbsp;? Cliquez ici pour rejoindre un groupe.</a>', '2012-12-31 18:52:20', '2020-12-28 13:39:56', '0000-00-00 00:00:00', 'no', '', 5, NULL, 168499),
	('aboutus_getactivetext', 'gl', 'messages', '<p>Únete a un dos nosos equipos: Comparte traballo, compromiso e diversión! Actualmente estamos buscando persoas:</p><ul><li>Desenvolvedoras</li><li>Deseñadoras</li><li>Probadoras de Software</li><li>Apoio á comunidade</li><li>Tradutoras</li><li>Voluntariado local</li></ul><p><a href="about/getactive">Cres que podes axudar? Pincha aquí e atopa o teu equipo.</a></p>', '2021-01-14 09:58:33', '2025-10-20 19:02:55', '2021-01-14 09:58:33', 'no', '', 5, NULL, 210880),
	('aboutus_getactivetext', 'he', 'messages', 'הצטרף אחד הצוותים שלנו: קח חלק בעבודה ,במסירות ובכיף!  היות ואנחנו עדיין בשלב ב של הפרויקט, אנו מחפשים בדחיפות: <br/> \r\n* (PHP, MySQL)מתכנתים<br/>\r\n* ((X)HTML/CSS)מעצבי אתרים<br/>  \r\n*   מתרגמים לשפות שונות<br/>  \r\n*BeWelcome יזמים ל <br/>\r\n* \r\nחברים שרוצים להתחיל קהילות מקומיות <br/> ', '2008-06-11 13:50:46', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 4454),
	('aboutus_getactivetext', 'hr', 'messages', 'Pridruži se nekoj od naših ekipa: podijelimo posao, predanost i zabavu!  Trenutačno tražimo: \r\n<ul class="bullet"><li>Developere</li><li>Dizajnere</li><li>Testere</li><li>Podršku za članove</li><li>Prevoditelje</li><li>lokalne volontere</li> </ul>\r\n<a href="http://www.bewelcome.org/about/getactive">Želiš pomoći? Klikni ovdje i odaberi ekipu</a>', '2009-09-03 17:11:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('aboutus_getactivetext', 'hy', 'messages', '<p>Միացե՛ք մեր թիմերից մեկին։ Կիսեք մեզ հետ աշխատանքը, նվիրվածությունն ու զվարճանքը: Մենք այս պահին փնտրում ենք՝</p><ul><li>Մշակողներ</li><li>Դիզայներներ</li><li>Փորձարկողներ</li><li>Անդամների աջակցություն</li><li>Թարգմանիչներ</li><li>Տեղացի կամավորներ</li></ul><p><br>Ուզո՞ւմ եք օգնել: Սեղմե՛ք <a href="https://beta.bewelcome.org/about/getactive">այստեղ </a>և ընտրե՛ք ձեր թիմը:</p>', '2014-03-03 17:39:36', '2025-04-06 11:21:19', '0000-00-00 00:00:00', 'no', '', 5, NULL, 519603),
	('aboutus_getactivetext', 'it', 'messages', 'Iscriviti ad uno dei nostri tema: condividi il lavoro, la committenza e il divertimento. Attualmente stiamo cercando:<ul class="bullet"><li>Sviluppatori</li><li>Designers</li><li>Testers</li><li>Supportatori dei Membri</li><li>Traduttori</li><li>Volontari Locali</li> </ul>\r\n<a href="http://www.bewelcome.org/about/getactive"> Ti senti di poter aiutare? Clicca qui e scegli la tua squadra!</a>', '2012-12-11 11:26:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('aboutus_getactivetext', 'nl', 'messages', 'Sluit je aan bij één van onze teams: deel het werk, het engagement en het plezier! Op dit moment zoeken we:<ul class="bullet"><li>Webontwikkelaars</li><li>Designers</li><li>Testers</li><li>Ledenondersteuning</li><li>Vertalers</li><li>Lokale vrijwilligers</li></ul><a href="about/getactive">Wil je graag helpen? Klik hier en kies jouw team.</a>', '2013-01-05 10:41:05', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 42397),
	('aboutus_getactivetext', 'pl', 'messages', 'Dołącz do jednego z naszych zespołów: dziel pracę z zaangażowaniem i dobrą zabawą! Obecnie poszukujemy:\r\n<ul class="bullet"><li>Deweloperów</li><li>Projektantów</li><li>Testerów</li><li>Osób Do Obsługi Pomocy</li><li>Tłumaczy</li><li>Lokalnych wolontariuszy</li> </ul> \r\n<a href="http://www.bewelcome.org/about/getactive">Czujesz, że chcesz i możesz pomóc? Kliknij tutaj i wybierz odpowiedni zespół</a>', '2012-12-17 02:46:10', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 35248),
	('aboutus_getactivetext', 'pt', 'messages', 'Junte-se a uma das nossas equipas: partilhe o trabalho, o empenho e a diversão! Estamos à procura de:<ul class="bullet"><li>Programadores</li><li>Designers</li><li>Testers</li><li>Apoio aos membros</li><li>Tradutores</li><li>Voluntários locais</li> </ul> \r\n<a href="http://www.bewelcome.org/about/getactive">Acha que pode ajudar? clique aqui e escolha a sua equipa</a>', '2012-12-09 09:14:25', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('aboutus_getactivetext', 'pt-BR', 'messages', 'Junte-se a uma das equipes: divida o trabalho, o comprometimento e divirta-se. Estamos atuando buscando:\r\n<ul class="bullet"><li>Desenvolvedores</li><li>Designers</li><li>Verificadores (Testers)</li><li>Atendimento a usuário</li><li>Tradutores</li><li>Voluntários Locais</li> </ul> \r\n<a href="http://www.bewelcome.org/about/getactive">Quer ajudar? Clique aqui e escolha uma equipe</a>', '2013-05-21 19:54:22', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 50982),
	('aboutus_getactivetext', 'ru', 'messages', '<p>Присоединяйтесь к одной из наших команд: разделите с нами нашу работу, задачи и удовольствие! Сейчас нам нужны:</p><ul><li>Разработчи_цы</li><li>Дизайнер_ки</li><li>Тестировщи_цы</li><li>Поддержка участвующих</li><li>Переводчи_цы</li><li>Местные волонтёр_ки</li></ul><p><a href="about/getactive">Готовы помочь? Кликните здесь и выберите свою команду.</a></p>', '2014-04-06 18:52:35', '2025-03-24 15:54:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 519603),
	('aboutus_getactivetext', 'sl', 'messages', 'Pridruži se eni izmed naših ekip: Deli delo, odgovornost in zabavo! Trenutno iščemo:<ul class="bullet"><li>razvijalce</li><li>oblikovalce</li><li>testerje</li><li>podporo uporabnikom</li><li>prevajalce</li><li>lokalne prostovoljce</li> </ul><a href="about/getactive">Feel like helping? Click here and choose your team.</a>\r\n', '2019-03-30 23:15:34', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 106553),
	('aboutus_getactivetext', 'sr', 'messages', 'Придружите се неком од наших тимова: поделимо рад, посвећеност и забаву! Тренутно су нам потребни: <ul class="bullet"><li>Програмери</li> <li>Дизајнери</li> <li>Тестери</li: <li>Подршка</li> <li>Преводиоци</li> <li>Локални волонтери</li> </ul>\r\n<a href="http://www.bewelcome.org/about/getactive"> Желите да помогнете? Кликните овде и одаберите свој тим</a>', '2013-01-20 00:42:28', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 35032),
	('aboutus_getactivetext', 'sv', 'messages', 'Hjälp en av våra team: dela arbetet, engagemang och ha det roligt! Just nu söker vi efter: <ul class="bullet"><li>Utvecklare</li><li>Designer</li><li>Testare</li><li>Medlem Support</li><li>Översättare</li><li>Lokala Volontärer</li> </ul> \r\n<a href="http://www.bewelcome.org/about/getactive">Har du lust att hjälpa? Klicka här och välj ditt team.</a>', '2013-01-16 10:30:41', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 23263),
	('aboutus_getactivetext', 'tr', 'messages', 'Takımlarımızdan birine katılın: Emeği, sorumlulukları ve eğlenceyi paylaşın! Bügünlerde ihtiyaç duyduklarımız: \r\n<ul class="bullet"><li>Geliştiriciler</li><li>Tasarımcılar</li><li>Test uzmanları</li><li>Üyelere Destek</li><li>Çevirmenler</li><li>Yerel gönüllüler</li> </ul> \r\n<a href="http://www.bewelcome.org/about/getactive">Yardım edebilir misiniz? Buraya tıklayın ve takımınızı seçin.</a>', '2012-11-30 14:21:57', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 64652),
	('aboutus_getactivetext', 'uk', 'messages', '<p>Приєднайтесь до однієї з наших команд: поділіться роботою, зобов\'язанням та задоволенням! Наразі ми шукаємо:</p><ul><li>Розробників</li><li>Дизайнерів</li><li>Тестувальників</li><li>Фахівців з підтримки учасників</li><li>Перекладачів</li><li>Місцевих волонтерів</li></ul><p><a href="about/getactive">Хочете допомогти? Натисніть тут і виберіть свою команду.</a></p>', '2026-04-01 20:11:57', '2026-04-01 20:11:57', '2026-04-01 20:11:57', 'no', '', 5, NULL, 573491),
	('aboutus_getactivetext', 'vi', 'messages', '<p>Tham gia một trong các nhóm của chúng mình: Chia sẻ công việc, cam kết và niềm vui! &nbsp;Chúng mình hiện đang tìm kiếm:&lt;ul class="bullet"&gt;&lt;li&gt;Developers&lt;/li&gt;&lt;li&gt;Designers&lt;/li&gt;&lt;li&gt;Testers&lt;/li&gt;&lt;li&gt;Member Support&lt;/li&gt;&lt;li&gt;Biên dịch viên&lt;/li&gt;&lt;li&gt;Hỗ trợ thành viên&lt;/li&gt; &lt;/ul&gt;&lt;a href="about/getactive"&gt;Muốn giúp chúng mình một tay? Click vào đây và chọn nhóm phù hợp với mình.&lt;/a&gt;</p>', '2021-07-04 19:33:53', '2021-07-04 19:33:53', '2021-07-04 19:33:53', 'no', '', 5, NULL, 293926),
	('aboutus_getactivetext', 'zh-hans', 'messages', '加入我们的团队：分享工作、承诺和快乐！我们目前寻找：<ul class="bullet"><li>开发人员</li><li>设计师</li><li>测试人员</li><li>会员支持</li><li>翻译</li><li>当地自愿者</li> </ul> \r\n<a href="about/getactive">能帮到我们吗？点击链接选择感兴趣的团队加入我们吧！</a>', '2013-03-25 11:07:17', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 46333),
	('aboutus_getactivetext', 'zh-hant', 'messages', '加入我們其中一個團隊：一齊分享對工作的承諾和樂趣！我們現在在找：<ulclass="bullet"><li>開發家</li><li>設計家</li><li>測試家</li><li>會員協助家</li><li>翻譯家</li><li>當地志願者</li> </ul><a href="about/getactive">想幫忙嗎？立即在這裏選擇您的團隊吧。', '2014-09-03 07:28:04', '2021-05-02 07:48:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 68078),
	('aboutus_givefeedback', 'ar', 'messages', 'رأيك, لو سمحت!', '2008-02-11 20:08:23', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 2702),
	('aboutus_givefeedback', 'ca', 'messages', 'Opina!', '2008-02-15 19:20:19', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 177),
	('aboutus_givefeedback', 'cs', 'messages', 'Prosíme o Váš názor!', '2008-08-02 21:51:19', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 5010),
