	('aboutus_givefeedbacktext', 'ar', 'messages', 'نحن نعمل باستمرار على تحسين بي ويلكم. لو لديك اقتراح لتحسين الموقع نرجوك ان<a href="forums"> تخبرنا </a>', '2008-02-11 20:09:40', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48359),
	('aboutus_givefeedbacktext', 'ca', 'messages', 'Treballem contínuament per millorar BeWelcome. Si tens cap suggeriment de millora del lloc, <a href="http://www.bewelcome.org/forums">fes-nos-ho saber</a>.', '2008-02-29 11:31:39', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 122),
	('aboutus_givefeedbacktext', 'cs', 'messages', 'Neustále pracujeme na zdokonalování BeWelcome. Pokud máš jakékoliv nápady, <a href="http://www.bewelcome.org/forums">dej nám prosím vědět.</a>', '2008-08-07 16:28:02', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('aboutus_givefeedbacktext', 'da', 'messages', 'Vi arbejder konstant på at forbedre BeWelcome. Hvis du har et forslag til hvordan sitet kan forbedres, så <a href="http://www.bewelcome.org/forums">lad os det vide</a>.', '2008-08-15 08:32:33', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 74),
	('aboutus_givefeedbacktext', 'de', 'messages', 'Wir arbeiten ununterbrochen daran, BeWelcome zu verbessern. Wenn du Vorschläge hast, <a href="/about/feedback?IdCategory=7">lass es uns wissen</a>.', '2007-12-12 18:56:11', '2021-05-02 17:29:24', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1223),
	('aboutus_givefeedbacktext', 'el', 'messages', 'Δουλεύουμε συνεχώς για τη βελτίωση του BeWelcome. Αν έχεις κάποια πρόταση, <a href="http://www.bewelcome.org/forums">ενημέρωσέ μας</a>.', '2013-03-01 02:40:09', '2020-09-02 10:01:56', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('aboutus_givefeedbacktext', 'en', 'messages', 'We are constantly working on the improvement of BeWelcome. If you have a suggestion, please <a href="https://www.bewelcome.org/about/feedback?IdCategory=7">let us know</a>.', '2007-12-06 14:12:03', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', 'This is in the about us page', 5, NULL, 1223),
	('aboutus_givefeedbacktext', 'eo', 'messages', 'Ni konstante laboras por plibonigi BeWelcome. Se vi deziras sugesti plibonigon, bonvolu <a href="http://www.bewelcome.org/forums">sciigi nin</a>. ', '2008-09-16 14:23:03', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 47220),
	('aboutus_givefeedbacktext', 'es', 'messages', 'Estamos dedicados a mejorar BeWelcome constantemente. Si tienes alguna sugerencia para ayudarnos, <a href="http://www.bewelcome.org/forums">por favor contáctanos :-)</a>.', '2007-12-10 03:53:13', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 554),
	('aboutus_givefeedbacktext', 'eu', 'messages', 'BeWelcomeren hobetzean buru-belarri ari gara beti. Webgunea hobetzeko iradokizunik baduzu, <a href="http://www.bewelcome.org/forums">jakinarazi iezazkiguzu!</a>', '2008-06-09 10:28:22', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11907),
	('aboutus_givefeedbacktext', 'fa', 'messages', 'ما به طور متداول در حال توسعه دادن Bewelcome می باشیم .\r\nاگر پیشنهادی دارید ،<a href="http://www.bewelcome.org/forums">لطفاً ما را از نظرات خود مطلع سازید.</a> ', '2009-09-09 17:08:56', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 7897),
	('aboutus_givefeedbacktext', 'fi', 'messages', 'Kehitämme BeWelcomea jatkuvasti. Jos sinulla on parannusehdotuksia, <a href="forums">kerro meille</a>. ', '2009-05-18 21:21:59', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 72),
	('aboutus_givefeedbacktext', 'fr', 'messages', 'Nous travaillons en permanence pour améliorer BeWelcome. Si vous avez une suggestion, <a href="forums">faites-nous signe</a>.', '2007-12-07 13:52:33', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('aboutus_givefeedbacktext', 'gl', 'messages', 'Estamos traballando de xeito permanente na mellora de BeWelcome. Se tes algunha suxestión, por favor <a href="https://www.bewelcome.org/about/feedback?IdCategory=7">fáinolo saber</a>.', '2021-01-14 10:16:25', '2021-01-14 10:16:25', '2021-01-14 10:16:25', 'no', '', 5, NULL, 210880),
	('aboutus_givefeedbacktext', 'he', 'messages', 'BeWelcome אנו עובדים כמיטב כוחנו לשיפור של \r\nאם יש לך הצעות איך לשפר את האתר אנא <a href="http://www.bewelcome.org/forums">ידע אותנו</a> ', '2008-06-11 16:56:53', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 4454),
	('aboutus_givefeedbacktext', 'hr', 'messages', 'Stalno radimo na poboljšavanju BeWelcomea. Ako imaš prijedlog kako poboljšati naše stranice, molimo te,  <a href="forums">piši nam</a>. ', '2009-09-03 15:41:05', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('aboutus_givefeedbacktext', 'hu', 'messages', 'Folyamatosan dolgozunk a BeWelcome fejlesztésén, írd meg nekünk <a href="https://www.bewelcome.org/about/feedback?IdCategory=7">javaslataidat</a>.', '2017-10-19 21:20:39', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15734),
	('aboutus_givefeedbacktext', 'hy', 'messages', '<p>Մենք մշտապես աշխատում ենք ԲիՎելքոմի բարելավման վրա։ Եթե ​​ունես առաջարկ, խնդրում ենք <a href="https://www.bewelcome.org/about/feedback?IdCategory=7">իմաց տալ մեզ։</a></p>', '2025-04-29 14:53:42', '2025-05-09 16:17:42', '2025-04-29 14:53:42', 'no', '', 5, NULL, 519603),
	('aboutus_givefeedbacktext', 'it', 'messages', 'Lavoriamo costantemente per migliorare BeWelcome. Se hai suggerimenti, <a href="https://www.bewelcome.org/about/feedback?IdCategory=7">facceli sapere</a>. ', '2007-12-24 13:42:10', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 13993),
	('aboutus_givefeedbacktext', 'lt', 'messages', 'Mes nuolat tobuliname BeWelcome. Tavo pastabos bei mintys yra <a href="http://www.bewelcome.org/forums">ypač laukiamos</a>.', '2007-12-14 04:54:30', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('aboutus_givefeedbacktext', 'nl', 'messages', 'We werken constant aan het verbeteren van BeWelcome. Als je een suggestie hebt, <a href="https://www.bewelcome.org/about/feedback?IdCategory=7">laat het ons alsjeblieft weten</a>.', '2008-03-29 16:13:56', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40169),
	('aboutus_givefeedbacktext', 'pl', 'messages', 'Zależy nam na ciągłym tworzeniu i poprawianiu BeWelcome. Jeśli masz jakieś sugestie na temat projektu, <a href="http://www.bewelcome.org/forums">powiedz nam</a>. ', '2008-01-31 16:30:04', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 90),
	('aboutus_givefeedbacktext', 'pt', 'messages', 'Estamos constantemente a trabalhar para melhorar o BeWelcome. Se tem uma sugestão, por favor, <a href="https://www.bewelcome.org/about/feedback?IdCategory=7">diga-nos</a>.', '2012-12-09 18:05:03', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('aboutus_givefeedbacktext', 'pt-BR', 'messages', 'Estamos constantemente procurando melhorar o BeWelcome. Se você tiver alguma sugestão, por favor, <a href="http://www.bewelcome.org/forums">conte para a gente</a>.', '2013-05-21 19:55:46', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15566),
	('aboutus_givefeedbacktext', 'ru', 'messages', 'Мы стремимся постоянно улучшать BeWelcome. Если у вас есть идея, как сделать BeWelcome лучше, пожалуйста, <a href="http://www.bewelcome.org/forums">поделитесь ею с нами :)</a>.', '2007-12-16 14:54:08', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 79),
	('aboutus_givefeedbacktext', 'sl', 'messages', 'Ves čas se trudimo na izboljšavah BeWelcome. Če imaš predlog, nam ga prosim <a href="https://www.bewelcome.org/about/feedback?IdCategory=7">zaupaj</a>.\r\n', '2019-03-30 23:16:55', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 106553),
	('aboutus_givefeedbacktext', 'sr', 'messages', 'Стално радимо на унапређењу BeWelcome-а. Ако имате предлог, <a href="http://www.bewelcome.org/forums">стави нам до знања</a>.', '2013-01-20 00:43:46', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 35032),
	('aboutus_givefeedbacktext', 'sv', 'messages', 'Vi arbetar ständigt på att förbättra BeWelcome. Om du har ett förslag, vänligen <a href="http://www.bewelcome.org/forums">kontakta oss</ a>.', '2012-04-08 19:40:51', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 23263),
	('aboutus_givefeedbacktext', 'tr', 'messages', 'Sürekli olarak BeWelcome\'ı geliştirmeye çalışıyoruz. Önerileriniz olursa, lütfen bize <a href="http://www.bewelcome.org/forums">billdirin</a>.', '2012-11-30 14:19:54', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 64652),
	('aboutus_givefeedbacktext', 'uk', 'messages', '<p>Ми постійно працюємо над покращенням BeWelcome. Якщо у вас є пропозиція, будь ласка, <a href="https://www.bewelcome.org/about/feedback?IdCategory=7">повідомте нас</a>.</p>', '2026-04-03 18:23:50', '2026-04-03 18:23:50', '2026-04-03 18:23:50', 'no', '', 5, NULL, 573491),
	('aboutus_givefeedbacktext', 'vi', 'messages', '<p>Chúng mình không ngừng nỗ lực cải thiện BeWelcome. Nếu bạn có góp ý gì thêm, vui lòng &lt;a href="https://www.bewelcome.org/about/feedback?IdCategory=7"&gt; cho chúng mình biết nhé &lt;/a&gt;.</p>', '2021-07-04 22:01:28', '2021-07-04 22:01:49', '2021-07-04 22:01:28', 'no', '', 5, NULL, 293926),
	('aboutus_givefeedbacktext', 'zh-hans', 'messages', '我们一直在努力改善 BeWelcome，如果你有好的意见或建议，请<a href="https://www.bewelcome.org/about/feedback?IdCategory=7">告诉我们</a>。', '2010-03-04 05:03:17', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37722),
	('aboutus_givefeedbacktext', 'zh-hant', 'messages', '<p>我們持續致力於改進 BeWelcome。如果您有任何建議，請告訴我們。</p>', '2010-03-04 05:03:17', '2025-05-31 16:25:18', '0000-00-00 00:00:00', 'no', '', 5, NULL, 53422),
