	('activities.rules.headline', 'en', 'messages', 'Activity Guidelines', '2021-01-28 18:46:06', '2021-01-28 18:46:06', '2021-01-28 18:46:06', 'no', 'Headline of the activity guidelines', 5, NULL, 1223),
