	('admin.translation.no_right', 'ca', 'messages+intl-icu', 'Necessites els drets de ‘Paraula’ per a ajudar a traduir. Si us plau, revisa els detalls al ‘Grup de traductors de BeWelcome’.', '2022-05-29 12:47:37', '2022-05-29 12:47:37', '2022-05-29 12:47:37', 'no', '', 5, NULL, 26748),
	('admin.translation.no_right', 'de', 'messages+intl-icu', 'Du benötigst die Berechtigung "Words" wenn du uns beim Übersetzen unterstützen möchtest. Bitte frage in der "Bewelcome Translator" Gruppe nach mehr Infos.', '2020-06-06 20:26:22', '2020-06-06 20:26:22', '2020-06-06 20:26:22', 'no', '', 5, NULL, 111),
	('admin.translation.no_right', 'el', 'messages+intl-icu', 'Χρειάζεσαι την εξουσιοδότηση \'Λέξεων\' για να συνεισφέρεις μεταφραστικά.  Έλεγχε την \'Ομάδα Μετάφρασης Bewelcome\' για λεπτομέρειες.', '2020-08-13 16:09:37', '2020-08-13 16:09:37', '2020-08-13 16:09:37', 'no', '', 5, NULL, 266544),
	('admin.translation.no_right', 'en', 'messages+intl-icu', 'You need the ‘Words’ right if you want to support translating. Please check the ‘Bewelcome Translator Group’ for details.', '2020-05-17 18:49:13', '2021-01-23 11:20:44', '2020-05-17 18:49:13', 'no', 'Shown when someone tries to access the translation tool without proper rights.', 5, 0, 21169),
	('admin.translation.no_right', 'es', 'messages+intl-icu', 'Necesitas tener los permisos adecuados si deseas ayudar con la traducción. Revisa el Grupo \'BeWelcome Translators" para más detalles.', '2020-12-02 02:14:09', '2023-06-01 11:01:26', '2020-12-02 02:14:09', 'no', '', 5, NULL, 25548),
	('admin.translation.no_right', 'fr', 'messages+intl-icu', 'Vous ne disposez pas des droits pour accéder à l’outil de traduction. Veuillez vous renseigner auprès du groupe « BeWelcome Translator Group » pour plus de détails.', '2020-05-24 14:12:11', '2021-07-16 20:49:10', '2020-05-24 14:12:11', 'no', '', 5, NULL, 168499),
	('admin.translation.no_right', 'gl', 'messages+intl-icu', 'Necesitas do dereito de "Palabras" se queres apoiar ao equipo de tradución. Por favor conta co "Grupo de Tradución de Bewelcome" para máis detalles.', '2021-01-22 15:19:47', '2021-01-22 15:19:47', '2021-01-22 15:19:47', 'no', '', 5, NULL, 210880),
	('admin.translation.no_right', 'hu', 'messages+intl-icu', 'Először megfelelő fordítási jogokkal kell rendelkezned. További részletekért keresd fel a "BeWelcome Translator Group" csoportot!', '2020-05-27 22:04:19', '2020-05-27 22:04:19', '2020-05-27 22:04:19', 'no', '', 5, NULL, 36939),
	('admin.translation.no_right', 'it', 'messages+intl-icu', 'Hai bisogno degli appositi permessi se vuoi supportare la traduzione. Per i dettagli, consulta il "Bewelcome Translator Group".', '2020-05-26 09:48:10', '2020-05-26 09:48:10', '2020-05-26 09:48:10', 'no', '', 5, NULL, 261434),
	('admin.translation.no_right', 'nl', 'messages+intl-icu', 'Je hebt het recht ‘Woorden’ nodig als je wil helpen met vertalen.  Ga naar de groep ‘BeWelcome Translators’ voor details.', '2020-05-19 18:56:09', '2025-11-17 13:20:18', '2020-05-19 18:56:09', 'no', '', 5, NULL, 21169),
	('admin.translation.no_right', 'pl', 'messages+intl-icu', 'Jeśli chcesz pomóc w tłumaczeniu, potrzebujesz uzyskać szczególne uprawnienia. Sprawdź szczegóły na grupie BeWelcome Translators.', '2021-01-17 10:20:46', '2021-01-17 10:20:46', '2021-01-17 10:20:46', 'no', '', 5, NULL, 116789),
	('admin.translation.no_right', 'pt', 'messages+intl-icu', 'Precisa da autorização  \'Words\' para suportar a tradução. Por favor, veja o grupo \'Bewelcome Translator Group\' para mais detalhes.', '2020-05-18 05:24:55', '2020-05-18 05:24:55', '2020-05-18 05:24:55', 'no', '', 5, NULL, 38787),
