	('anytime', 'it', 'messages', 'Sì, in qualsiasi momento.', '2020-05-25 19:24:32', '2020-05-25 19:24:32', '2020-05-25 19:24:32', 'no', '', 5, NULL, 261434),
	('anytime', 'lt', 'messages', 'Taip, bet  kuriuo metu.', '2021-02-24 12:41:07', '2021-02-24 12:41:07', '2021-02-24 12:41:07', 'no', '', 5, NULL, 285578),
	('anytime', 'nl', 'messages', 'Ja, altijd.', '2020-06-08 18:24:02', '2020-06-08 18:24:02', '2020-06-08 18:24:02', 'no', '', 5, NULL, 21169),
	('anytime', 'pl', 'messages', 'Tak, kiedykolwiek.', '2020-05-29 08:39:36', '2020-05-29 08:39:36', '2020-05-29 08:39:36', 'no', '', 5, NULL, 37896),
	('anytime', 'pt', 'messages', 'Sim, a qualquer altura.', '2020-05-23 15:11:29', '2020-05-23 15:11:29', '2020-05-23 15:11:29', 'no', '', 5, NULL, 38787),
	('anytime', 'rm', 'messages', 'Gea, adina', '2020-05-24 23:22:47', '2020-05-24 23:22:47', '2020-05-24 23:22:47', 'no', '', 5, NULL, 662),
	('anytime', 'ru', 'messages', 'Да, в любое время.', '2020-05-27 07:52:22', '2020-05-27 07:52:22', '2020-05-27 07:52:22', 'no', '', 5, NULL, 134997),
	('anytime', 'tr', 'messages', 'Evet, her zaman.', '2024-04-29 10:32:15', '2024-04-29 10:32:15', '2024-04-29 10:32:15', 'no', '', 5, NULL, 318142),
	('anytime', 'uk', 'messages', 'Так, у будь-який час.', '2026-04-04 00:41:47', '2026-04-04 00:41:47', '2026-04-04 00:41:47', 'no', '', 5, NULL, 573491),
	('anytime', 'zh-hant', 'messages', '是的，任何時間', '2020-06-25 21:48:40', '2021-05-02 07:48:37', '2020-06-25 21:48:40', 'no', '', 5, NULL, 53422),
	('applicationnotyetvalid', 'ca', 'messages', 'Hauràs de tenir una mica més de paciència. Els voluntaris encara no han revisat la teva petició.', '2007-08-30 21:33:35', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 177),
	('applicationnotyetvalid', 'de', 'messages', 'Nicht so schnell! Um eine sichere Umgebung zu gewährleisten, wird zuerst noch einer unserer Helfer deinen Antrag überprüfen. Aber keine Sorge, es wird nicht sehr lange dauern.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 3050),
	('applicationnotyetvalid', 'en', 'messages', 'Not so fast!  In order to provide a secure environment for our members, our volunteers must first review your application.  But don\'t worry, this will not take long.', '2007-10-29 20:25:45', '2019-04-23 18:16:49', '2008-04-13 16:16:26', 'no', 'This is the message which is displayed when a member try to log without having his application validated by a volunteer accepter', 5, 1, 612),
	('applicationnotyetvalid', 'es', 'messages', '¡No tan rápido! De manera de garantizar seguridad para nuestros miembros, los voluntarios deben revisar primero tu aplicación. Pero no te preocupes, esto no tardará mucho.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1328),
	('applicationnotyetvalid', 'fi', 'messages', 'Sinun täytyy odottaa hieman, vapaaehtoiset eivät ole vielä käsitelleet hakemustasi ', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 72),
	('applicationnotyetvalid', 'fr', 'messages', 'Vous devez attendre un peu, votre demande d\'inscription n\'a pas encore été prise en compte par nos volontaires', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('applicationnotyetvalid', 'hr', 'messages', 'Ne tako brzo! U svrhu stvaranja i održavanja što veće sigurnosti naših članova, najprije naši volonteri moraju pregledati tvoju prijavu. Ali ne brini, oni su brzi.', '2010-01-15 21:13:53', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 8197),
	('applicationnotyetvalid', 'it', 'messages', 'Sei troppo veloce! Per provvedere a creare un ambiente sicuro per i nostri membri, i nostri volontari devono rivedere la tua richiesta. Ma non ti preoccupare, non ci vorrà molto tempo.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
	('applicationnotyetvalid', 'lt', 'messages', 'Ei, ne taip greitai! Tam, kad užtikrinti BeWelcome nariams saugų naudojimąsi svetaine, mūsų savanoriai iš pradžių turi peržiūrėti jūsų duomenis. Tačiau nesijaudinkite (nėr čia ko) -  tai neužims daug laiko.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 227),
	('applicationnotyetvalid', 'lv', 'messages', 'Ne tik ātri! Lai nodrošinātu mūsu biedriem drošu vidi, vispirms mūsu brīvprātīgajiem ir jāpārskata tava reģistrācijas lapa. Bet neuztraucies, tas neaizņems daudz laika.\r\n', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 375),
	('applicationnotyetvalid', 'nl', 'messages', 'Gelieve wat te wachten aub. Je aanvraag werd nog niet nagezien door onze vrijwilligers', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 273),
	('applicationnotyetvalid', 'pl', 'messages', 'Musisz troche poczekać, nasi wolontariusze jeszcze nie przejrzeli Twojego zgłoszenia.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 90),
