	('bewelcome.slogan', 'es', 'messages', 'El mundo está a sólo un paso de aquí', '2020-12-03 20:44:16', '2020-12-03 20:44:16', '2020-12-03 20:44:16', 'no', '', 5, NULL, 25548),
	('bewelcome.slogan', 'fr', 'messages', 'Le reste du monde n\'est plus très loin', '2020-05-26 00:09:52', '2020-05-26 00:09:52', '2020-05-26 00:09:52', 'no', '', 5, NULL, 29128),
