	('bewelcomelv', 'ca', 'messages', 'Voluntaris Locals', '2009-06-23 18:21:44', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 5533),
	('bewelcomelv', 'en', 'messages', 'Local Volunteers', '2009-06-20 10:34:24', '2019-04-23 18:16:49', '2010-02-28 14:35:39', 'yes', ' *** this is probably something obsolete Group translation ***', 5, 1, 111),
	('bewelcomelv', 'fr', 'messages', 'Volontaires Locaux', '2009-07-30 16:28:52', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 68),
	('bewelcomelv', 'pt', 'messages', 'Voluntários Locais', '2009-09-01 13:09:11', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 9030),
	('bewelcomeowner', 'cs', 'messages', 'BeWelcome je vlastnictvím <a href="http://www.bevolunteer.org">BeVolunteer</a>, francouzské neziskové asociace.', '2013-10-18 21:28:29', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('bewelcomeowner', 'de', 'messages', 'BeWelcome ist ein Projekt und daher das Eigentum von <a href="http://www.bevolunteer.org">BeVolunteer</a>, einem gemeinnützigen französischen Verein. BeVolunteer wurde in Frankreich gegründet und ist im Vereinsregister der Préfecture Rennes unter Nr. W353003546 registriert. Es ist ein Verein gemäß des französischen Gesetzes vom 1. Juli 1901 und der Verordnung vom 16. August 1901. ', '2013-07-03 14:14:34', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 174),
	('bewelcomeowner', 'el', 'messages', 'Το BeWelcome είναι ιδιοκτησία του <a href="https://www.bevolunteer.org">BeVolunteer</a>, μιας ΜΚΟ σύμφωνης με τις διατάξεις του Γαλλικού Νόμου της 1ης Ιουλίου, 1901 και του διατάγματος της 16ης Αυγούστου, 1901. Το BeVolunteer είναι εγγεγραμμένο στο νομό της Ρεν με αριθμό RNA W353003546.', '2013-07-30 14:17:34', '2020-09-02 11:02:46', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('bewelcomeowner', 'en', 'messages', 'BeWelcome is a project and thus the property of <a href="http://www.bevolunteer.org">BeVolunteer</a>, a non-profit organisation ruled according to the French law of July 1, 1901 and the decree of August 16, 1901. BeVolunteer is registered at the Préfecture de Rennes under RNA number W353003546.', '2013-06-27 06:52:24', '2019-12-26 09:49:40', '2015-12-02 17:27:18', 'no', 'Text on impressum page.', 5, NULL, 1223),
	('bewelcomeowner', 'es', 'messages', 'BeWelcome es un proyecto y la propiedad de <a href="http://www.bevolunteer.org">BeVolunteer</a>, una asociación sin fines de lucro registrada en Francia.', '2013-07-04 12:11:34', '2021-02-19 19:14:32', '0000-00-00 00:00:00', 'no', '', 5, NULL, 2208),
	('bewelcomeowner', 'fr', 'messages', 'BeWelcome est la propriété de <a href="http://www.bevolunteer.org">BeVolunteer</a>, une association française à but non lucratif de type loi 1901. L\'association BeVolunteer est enregistrée à la Préfecture de Rennes sous le numéro RNA W353003546.', '2013-09-28 14:30:21', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('bewelcomeowner', 'gl', 'messages', 'BeWelcome é un proxecto e polo tanto propiedade de <a href="http://www.bevolunteer.org">BeVolunteer</a>, unha organización sen ánimo de lucro rexida pola lei francesa do 1 Xullo de 1901 e o decreto de 16 de agosto de 1901. BeVolunteer está rexistrada na Prefectura de Rennes con número de rexistro W353003546.', '2021-02-26 15:31:59', '2021-02-26 15:31:59', '2021-02-26 15:31:59', 'no', '', 5, NULL, 210880),
	('bewelcomeowner', 'hr', 'messages', 'BeWelcome je vlasništvo francuskog neprofitnog udruženja <a href="http://www.bevolunteer.org">BeVolunteer</a>.', '2013-09-29 19:00:13', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('bewelcomeowner', 'it', 'messages', 'BeWelcome è un progetto e quindi di proprietà di <a href="http://www.bevolunteer.org">BeVolunteer</a>, un\'associazione senza scopo di lucro secondo la legge francese del 1.07.1901 e il decreto del 16.08.1901. BeVolunteer è registrata alla Prefettura di Rennes sotto il numero RNA W353003546.', '2013-07-07 22:19:20', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('bewelcomeowner', 'ja', 'messages', '<p>BeWelcome がプロジェクトであり、1901年フランス法の1901年7月1日の法令に基いて設立と運営される非営利団体(NPO)である<a href="http://www.bevolunteer.org/">BeVolunteer</a>が所有しています。BeVolunteerは、レンヌ県にRNA番号W353003546で登録されています。</p>', '2025-04-16 01:37:08', '2025-04-16 01:39:37', '2025-04-16 01:37:08', 'no', '', 5, NULL, 292473),
	('bewelcomeowner', 'nl', 'messages', 'BeWelcome is een project en dus eigendom van <a href="http://www.bevolunteer.org">BeVolunteer</a>, een vereniging zonder winstoogmerk die valt onder de Franse wetgeving van 1 juli 1901 en het decreet van 16 augustus 1901.  BeVolunteer is geregistreerd in de prefectuur van Rennes onder RNA-nummer W353003546.', '2013-07-04 09:22:40', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('bewelcomeowner', 'pl', 'messages', 'BeWelcome to projekt, a co za tym idzie, własność <a href="http://www.bevolunteer.org"> BeVolunteer </a>, organizacji non-profit działającej zgodnie z francuskim prawem ustanowionym 1 lipca 1901 r. oraz dekretem z 16 sierpnia 1901. BeVolunteer jest zarejestrowana w prefekturze Rennes pod numerem RNA W353003546.', '2021-01-16 19:37:27', '2021-01-16 19:37:53', '2021-01-16 19:37:27', 'no', '', 5, NULL, 116789),
	('bewelcomeowner', 'pt', 'messages', 'O BeWelcome é um projeto propriedade da <a href="http://www.bevolunteer.org">BeVolunteer</a>, uma organização sem fins lucrativos criada ao abrigo da lei francesa de 1 de julho de 1901 e do decreto de 16 de agosto de 1901. A BeVolunteer está registada na prefeitura de Ronnes sob o RNA W353003546.', '2013-08-12 15:53:30', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('bewelcomeowner', 'pt-BR', 'messages', 'BeWelcome é um projeto e consequentemente uma propriedade da <a href="http://www.bevolunteer.org">BeVolunteer</a>, uma organização sem fins lucrativos, administrada de acordo com as leis Francesas de 01 de Julho de 1901, e decreto de 16 de Agosto de 1901. BeVolunteer está registrada na Prefeitura de Rennes sobre o registro número W353003546.', '2016-12-17 21:50:04', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160059),
	('bewelcomeowner', 'ru', 'messages', 'BeWelcome собственность <a href="http://www.bevolunteer.org">BeVolunteer</a>, французской некоммерческой организации.', '2014-04-26 12:00:37', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('bewelcomeowner', 'sr', 'messages', 'BeWelcome је власништво француске непрофитне организације <a href="http://www.bevolunteer.org">BeVolunteer</a>.\r\n', '2013-07-19 17:11:11', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 52973),
	('bewelcomeowner', 'uk', 'messages', '<p>BeWelcome є проектом і, отже, власністю <a href="http://www.bevolunteer.org">BeVolunteer</a>, неприбуткової організації, що діє відповідно до закону Франції від 1 липня 1901 року та указу від 16 серпня 1901 року. BeVolunteer зареєстрований в Префектурі Ренна під номером RNA W353003546.</p>', '2026-04-03 19:21:54', '2026-04-03 19:21:54', '2026-04-03 19:21:54', 'no', '', 5, NULL, 573491),
