	('bod (board of directors)', 'en', 'messages', 'BoD (Board of Directors)', '2009-07-21 17:07:02', '2019-04-23 18:16:49', '2010-02-28 14:35:39', 'yes', 'This is the name of the BeVolunteer Bod Group *** this is probably something obsolete Group translation ***', 5, 1, 68),
	('bod (board of directors)', 'fr', 'messages', 'Bureau de BeVolunteer', '2009-07-21 17:07:38', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 68),
	('bod_financingtext', 'ar', 'messages', 'بي ويلكم و بي فولنتيير ممولين من قبل الحفاظ على عدم تبذير الميزانية على قد المستطاع. بعض المصروفات الادارية تتطلب ان نصرف على أي نحن سعداء لتلقي %sتبرعك هذا%s', '2008-02-21 12:09:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 2702),
	('bod_financingtext', 'ca', 'messages', 'BeWelcome i BeVolunteer es financien reduint les despeses al mínim imprescindible. Tanmateix, sempre tenim algunes despeses administratives i t\'estarem molt agraïts per una %sdonació%s.', '2008-04-02 11:50:11', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 3236),
	('bod_financingtext', 'de', 'messages', 'BeWelcome und BeVolunteer finanzieren sich durch Sparsamkeit. Einige  Verwaltungskosten lassen sich allerdings nicht vermeiden, deshalb sind wir für %sSpenden%s sehr dankbar.', '2008-02-07 19:55:02', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 15240),
	('bod_financingtext', 'en', 'messages', 'BeWelcome and BeVolunteer are financed through keeping expenses as low as possible. Some administrative costs, however, occur and we are happy for %syour donation%s.', '2008-01-16 05:11:25', '2019-04-23 18:16:49', '2008-01-16 05:11:33', 'no', '', 5, 1, 71),
	('bod_financingtext', 'eo', 'messages', 'BeWelcome kaj BeVolunteer estas monata ĉefe per limigi elspezojn. Kelkaj administraj gastoj jes ja estas, kaj bonvene %sdonacu vi%s', '2008-09-09 08:58:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1769),
	('bod_financingtext', 'es', 'messages', 'BeWelcome y BeVolunteer son financiados manteniendo los costos lo más bajo posible. Algunos gastos administrativos, como sea, ocurre y nos alegra %stu donación%s.', '2008-02-28 12:52:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1328),
	('bod_financingtext', 'fr', 'messages', 'BeWelcome et BeVolunteer sont gérés de façon à garder les dépenses à leur minimum. Certaines dépenses administratives, elles, ne peuvent pas être évitées, et nous sommes heureux de %svos dons%s.', '2008-02-09 09:51:13', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 452),
	('bod_financingtext', 'it', 'messages', 'BeWelcome e BeVolunteer sono finanziate cercando di mantenere le spese le più basse possibili. Ovviamente ci sono dei costi amministrativi, e siamo felici per %sle vostre donazioni%s.', '2008-03-28 16:31:36', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
	('bod_financingtext', 'lt', 'messages', 'BeWelcome ir BeVolunteer yra finansuojami besilaikant kuo mažesnių išlaidų principo. Kadangi neimanoma išvengti kai kurių administracinių išlaidų, esame laimingi susilaukti %sjūsų aukojimų%s, kad ir pačių smulkiausių.', '2008-02-08 17:46:31', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 227),
	('bod_financingtext', 'pt', 'messages', 'O BeWelcome e a BeVolunteer são financiados mantendo as despesas tão baixas quanto possível. Existem alguns custos administrativos, no entanto, e agradecemos %sos seus donativos%s.', '2013-08-12 19:40:53', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 38787),
	('bod_financingtext', 'ru', 'messages', 'Мы стараемся удерживать расходы BeWelcome и BeVolunteer на как можно более низком уровне. Тем не менее, определенные расходы существуют, и мы будем очень рады %sвашим добровольным взносам%s.', '2008-02-11 11:04:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 79),
	('bod_financingtitle', 'ar', 'messages', 'تمويل المنظمة', '2008-02-21 11:50:21', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 2702),
