	('broadcast_body_testformassmailwithimage', 'en', 'messages', 'Please translate with just any text you want. This wordcode is irrelevant, except that it distorts the translation statistics...\r\n\r\n<img src="http://www.bewelcome.org/images/logo_index_top.png"> The normal logo\r\n\r\n<img src="http://www.bewelcome.org/images/logo_index_top.png" widht="238" height="66"> 2 times the size\r\n\r\nText with <img src="http://www.bewelcome.org/images/logo_index_top.png" align="middle"> middle alignment\r\n\r\n<img src="http://www.bewelcome.org/images/logo_index_top.png" style="float: right"> Check to see if CSS works', '2016-11-22 21:27:16', '2020-05-16 15:27:03', '2016-11-22 21:27:16', 'no', 'Please translate is with whatever text you want. Sorry to distort the translation statistics. This will not be sent to anyone except a testing group', 5, 1, 42397),
