	('broadcast_body_testformassmailwithimage', 'nl', 'messages', 'Vertaalstatistieken!\r\n\r\n<img src="http://www.bewelcome.org/images/logo_index_top.png"> Het normale logo\r\n\r\n<img src="http://www.bewelcome.org/images/logo_index_top.png" widht="238" height="66"> dubbele grote\r\n\r\nText with <img src="http://www.bewelcome.org/images/logo_index_top.png" align="middle"> gesentreert\r\n\r\n<img src="http://www.bewelcome.org/images/logo_index_top.png" style="float: right"> eens zien of CSS wertk', '2017-01-18 09:08:34', '2020-12-04 19:21:51', '0000-00-00 00:00:00', 'no', '', 5, 1, 21169),
	('broadcast_body_testformassmailwithimage', 'pt', 'messages', 'Este texto deve ser traduzido à vontade. O conteúdo é irrelevante, exceto pelo facto de destruir as estatísticas de tradução...\r\n\r\n<img src="http://www.bewelcome.org/images/logo_index_top.png"> O logótipo normal\r\n\r\n<img src="http://www.bewelcome.org/images/logo_index_top.png" widht="238" height="66"> O dobro do tamanho\r\n\r\nTexto com <img src="http://www.bewelcome.org/images/logo_index_top.png" align="middle"> alinhamento central\r\n\r\n<img src="http://www.bewelcome.org/images/logo_index_top.png" style="float: right"> Teste para ver se as CSS funcionam.', '2016-11-24 14:27:18', '2020-12-04 19:21:51', '0000-00-00 00:00:00', 'no', '', 5, 1, 38787),
