	('broadcast_body_testsending', 'de', 'messages+intl-icu', '<p>Dies ist ein Test.</p>', '2024-10-13 18:07:58', '2024-10-13 18:07:58', '2024-10-13 18:07:58', 'no', '', 5, NULL, 25410),
