	('changepasswordintro', 'en', 'messages', 'Here you can change your password.  Make sure it is not too simple.', '2008-04-04 18:29:02', '2019-04-23 18:16:49', '2008-04-04 18:29:38', 'no', '', 5, NULL, 97),
