	('chatcannotentermailtoconfirm', 'ca', 'messages', 'Primer has de confirmar el correu electrònic que t\'hem enviat fent clic a l\'enllaç de confirmació abans de poder utilitzar totes les funcions de BeWelcome.', '2009-08-24 12:35:04', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 5533),
	('chatcannotentermailtoconfirm', 'de', 'messages', 'Tut uns leid %s, du kannst den Chat noch nicht verwenden.\r\n\r\nDu musst zuerst die E-Mail bestätigen (den Link in der E-Mail anklicken), die wir dir geschickt haben, bevor du alle Funktionen von BeWellcome verwenden kannst.', '2009-02-03 17:24:25', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 15240),
	('chatcannotentermailtoconfirm', 'en', 'messages', 'Sorry %s, you cannot yet use this chat.\r\n\r\nYou must first confirm the mail we have sent you by clicking on the confirmation link before being able to fully use BeWelcome. ', '2009-01-12 21:09:25', '2019-04-23 18:16:49', '2009-01-12 21:09:25', 'no', 'This is the message which is display when a member who has not yet confirmed his mail try to enter the chat', 5, 1, 1),
	('chatcannotentermailtoconfirm', 'es', 'messages', 'Lo sentimos %s, aún no puede utilizar este chat. Debe primero confirmar el correo que le hemos enviado haciendo clic en el enlace de confirmación; luego podrá hacer pleno uso de BeWelcome.', '2011-11-19 09:10:58', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 8437),
	('chatcannotentermailtoconfirm', 'fr', 'messages', 'Désolé %s, vous ne pouvez pas encore utiliser ce chat.\r\n\r\nIl vous faut, auparavant, confirmer votre adresse mail en cliquant sur le lien dans le message que nous vous avons envoyé .', '2009-01-12 21:11:02', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('chatcannotentermailtoconfirm', 'it', 'messages', 'Ci dispiace %s, non puoi ancora usare la chat.\r\nDevi prima confermare l\'email che ti abbiamo mandato cliccato sul link di conferma prima di potere usare tutte le funzioni di BeWelcome.', '2009-01-25 15:21:04', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
	('chatcannotentermailtoconfirm', 'sr', 'messages', 'Тек након што потврдите мејл који смо Вам послали тако што кликнете на линк за потврду, моћи ћете да користите све могућности сајта BeWelcome.', '2013-07-19 16:02:51', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 52973),
