	('comment.new.experience.yes', 'zh-hant', 'messages', '是', '2010-09-11 03:50:25', '2021-05-02 07:48:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11819),
	('comment.notification.new.body', 'de', 'messages', '<p>Hallo %1$s,</p><p>%2$s hat einen %3$s Kommentar über dich geschrieben. Der Kommentar lautet:</p><p><i>"%4$s"</i></p><p><a href="%5$s">Den Kommentar auf deinem Profil sehen</a><br><a href="%6$s">Schreibe oder aktualisiere</a> Deinen Kommentar über %2$s</p><p>Wir wünschen Dir eine gute Zeit!<br>das BeWelcome Team</p><p>PS. Solltest Du mit diesem Kommentar ein Problem haben, dann <a href="%7$s">kontaktiere uns</a></p><p>bitte.</p>', '2016-02-06 13:12:03', '2023-07-11 20:26:17', '0000-00-00 00:00:00', 'no', '', 5, NULL, 2208),
	('comment.notification.new.body', 'el', 'messages', '<p>Γεια %1$s,</p>\r\n<p>%2$s σου άφησε ένα %3$s σχόλιο. Το σχόλιο λέει:</p>\r\n<p><i>"%4$s"</i></p>\r\n<p><a href="%5$s">Διάβασε περισσότερα</a> σχετικά με το σχόλιο.<br />\r\n<a href="%6$s">Γράψε ή ενημέρωσε</a> το σχόλιο σου σχετικά με %2$s</p>\r\n<p>Να περάσεις καλά!<br />\r\nΗ ομάδα του BeWelcome</p>\r\n<p>Y.Γ. Σε περίπτωση που υπάρχει πρόβλημα με αυτό το σχόλιο <a href="%7$s">επικοινώνησε μαζί μας</a></p>', '2020-08-19 20:41:37', '2020-08-28 11:46:03', '2020-08-19 20:41:37', 'no', '', 5, NULL, 266544),
	('comment.notification.new.body', 'en', 'messages', '<p>Hi %1$s,</p><p>%2$s has written a %3$s comment about you. The comment says:</p><p><i>"%4$s"</i></p><p><a href="%5$s">View the comment on your profile</a><br><a href="%6$s">Write or update</a> your comment about %2$s</p><p>We wish you many good BeWelcome experiences.<br>The BeWelcome Team</p><p>PS. In case you have a problem with this comment please <a href="%7$s">contact us</a></p>', '2014-10-07 21:22:19', '2023-07-11 20:36:20', '0000-00-00 00:00:00', 'no', 'Text of notification for a member who receives a comment', 5, 0, 2208),
	('comment.notification.new.body', 'es', 'messages', '<p>Hola %1$s,</p><p>%2$s ha escrito un comentario %3$s sobre ti . El comentario dice:</p><p><i>"%4$s"</i></p><p><a href="%5$s">Leer más</a> sobre el comentario.<br><a href="%6$s">Escribir o actualizar</a> tu comentario sobre %2$s</p><p>¡Que lo pases bien!<br>El equipo de BeWelcome</p><p>PD: Si tienes algún problema con este comentario <a href="%7$s">ponte en contacto con nosotros</a></p>', '2014-12-20 10:46:41', '2025-10-14 07:41:39', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37896),
	('comment.notification.new.body', 'fr', 'messages', '<p>Bonjour %1$s,</p><p>%2$s vous a laissé un commentaire %3$s&nbsp;:</p><p><i>«&nbsp;%4$s&nbsp;»</i></p><p><a href="%5$s">Voir le commentaire sur votre profil</a>.<br><a href="%6$s">Ecrire ou actualiser</a> votre commentaire concernant %2$s</p><p>Nous vous souhaitons de belles expériences sur BeWelcome&nbsp;!<br>L’équipe bénévole</p><p>PS&nbsp;: si ce commentaire ne respecte pas la charte BeWelcome, merci de <a href="%7$s">nous contacter</a></p>', '2015-07-27 20:33:03', '2023-12-30 10:28:54', '0000-00-00 00:00:00', 'no', '', 5, NULL, 168499),
	('comment.notification.new.body', 'gl', 'messages', '<p>Ola %1$s,</p><p>%2$s escribiu un comentario %3$s sobre ti. O comentario di:</p><p><i>"%4$s"</i></p><p><a href="https://beta.bewelcome.org/%255$s">Mira o comentario no teu perfil</a><br><a href="%6$s">Escrebe ou actualiza</a> o teu comentario sobre %2$s</p><p>Desexámosche moitas boas experiencias en BeWelcome.<br>O equipo de BeWelcome</p><p>P.D. No caso de que teñas un problema con este comentario, por favor, <a href="%7$s">contáctanos</a></p>', '2021-02-04 16:30:50', '2023-10-26 07:45:51', '2021-02-04 16:30:50', 'no', '', 5, NULL, 210880),
	('comment.notification.new.body', 'hy', 'messages', '<p>Բարև %1$s,</p><p>%2$s-ը գրել է %3$s մեկնաբանություն քո մասին։ Մեկնաբանությունում ասվում է.</p><p>«%4$s»</p><p><a href="https://www.bewelcome.org/%255$s">Դիտել մեկնաբանությունը պրոֆիլումդ</a><br><a href="https://www.bewelcome.org/%256$s">Գրել կամ խմբագրել </a>մեկնաբանությունը %2$s-ի մասին</p><p>Մաղթում ենք &nbsp;բազմաթիվ լավ Բիվելքմ փորձառություններ։<br>Բիվելքմ &nbsp;թիմ</p><p>Հ.Գ. Այս մեկնաբանության հետ խնդիր ունենալու դեպքում, խնդրում ենք կապվել <a href="https://www.bewelcome.org/%257$s">մեզ հետ</a></p>', '2026-05-24 08:05:28', '2026-05-24 08:14:36', '2026-05-24 08:05:28', 'no', '', 5, NULL, 519603),
	('comment.notification.new.body', 'it', 'messages', '<p>Ciao %1$s,</p><p>%2$s ha scritto un %3$s commento su di te. Ecco cosa ha scritto:</p><p><i>"%4$s"</i></p><p><a href="%5$s">Vedi il commento sul tuo profilo</a><br><a href="%6$s">Scrivi o aggiorna</a> il tuo commento su %2$s</p><p>Ti auguriamo tante belle esperienze BeWelcome!<br>The BeWelcome Team</p><p>PS. Se dovessi avere un problema con questo commento, scrivici una mail a <a href="%7$s">contact us</a></p>', '2015-01-05 12:49:15', '2023-07-11 20:42:32', '0000-00-00 00:00:00', 'no', '', 5, NULL, 2208),
	('comment.notification.new.body', 'nl', 'messages', '<p>Hallo %1$s,</p><p>%2$s heeft een %3$s commentaar over je geschreven. Het commentaar is:</p><p><i>"%4$s"</i></p><p><a href="%5$s">Bekijk het commentaar op je profiel</a><br><a href="%6$s">Schrijf of ververs</a> jouw commentaar over %2$s</p><p>Het beste gewenst!<br>Het BeWelcome Team</p><p>PS. In het geval dat je een probleem hebt met dit commentaar <a href="%7$s">neem alsjeblieft contact met ons op</a></p>', '2015-03-31 17:06:27', '2023-07-11 20:44:44', '0000-00-00 00:00:00', 'no', '', 5, NULL, 2208),
	('comment.notification.new.body', 'pl', 'messages', '<p>Cześć %1$s,</p>\r\n<p>%2$s napisał(a) Ci %3$s komentarz o treści:</p>\r\n<p><i>"%4$s"</i></p>\r\n<p><a href="%5$s">Przeczytaj więcej</a> o komentarzu.<br />\r\n<a href="%6$s">Napisz albo zaktualizuj</a> Twój komentarz o %2$s</p>\r\n<p>Pozdrawiamy!<br />\r\nZespół BeWelcome</p>\r\n<p>PS. W przypadku problemów z tym komentarzem prosimy, <a href="%7$s">skontaktuj się z nami</a></p>', '2021-01-14 20:53:50', '2021-01-14 20:59:04', '2021-01-14 20:53:50', 'no', '', 5, NULL, 116789),
	('comment.notification.new.body', 'pt', 'messages', '<p>Olá %1$s,</p><p>%2$s deixou-lhe um comentário %3$s. O comentário diz:</p><p><i>"%4$s"</i></p><p><a href="%5$s">Leia</a> o comentário no seu perfil<br><a href="%6$s">Escrever ou atualizar</a> o seu comentário sobre %2$s</p><p>Divirta-se à grande!<br>A Equipa BeWelcome</p><p>PS. Caso tenha algum problema com este comentário, por favor, <a href="%7$s">contacte-nos</a></p>', '2014-10-23 10:39:15', '2023-07-11 20:47:42', '0000-00-00 00:00:00', 'no', '', 5, NULL, 2208),
	('comment.notification.new.body', 'pt-BR', 'messages', '<p>Olá %1$s,</p>\r\n<p>%2$s deixou uma avaliação %3$s para você. A mensagem diz:</p>\r\n<p><i>"%4$s"</i></p>\r\n<p><a href="%5$s">Leia mais</a> sobre a avalização.<br />\r\n<a href="%6$s">Escreva ou atualize</a> sua avaliação sobre %2$s</p>\r\n<p>Tenha um ótimo dia!<br />\r\nEquipe BeWelcome</p>\r\n<p>PS: Caso você tenha algum problema com essa avaliação, por favor <a href="%7$s">entre em contato</a></p>', '2016-12-20 14:03:52', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160059),
	('comment.notification.new.body', 'ru', 'messages', '<p>Привет %1$s,</p>\r\n<p>%2$s оставил Вам %3$s комментарий. В нём сказано:</p>\r\n<p><i>"%4$s"</i></p>\r\n<p><a href="%5$s">Читать ещё</a> о комментарии.<br />\r\n<a href="%6$s">Написать или обновить</a> Ваш комментарий о %2$s</p>\r\n<p>Удачи!<br />\r\nКоманда BeWelcome</p>\r\n<p>PS. В том случае, если у Вас есть проблемы с комментарием, пожалуйста,  <a href="%7$s">свяжитесь с нами</a></p>', '2014-12-06 06:21:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('comment.notification.new.body', 'sr', 'messages', '<p>Здраво %1$s,</p>\r\n<p>%2$s је написао %3$s коментар. Коментар гласи:</p>\r\n<p><i>"%4$s"</i></p>\r\n<p><a href="%5$s">Прочитај више</a> о коментару.<br>\r\n<a href="%6$s">Напиши или ажурирај</a> свој коментар о %2$s</p>\r\n<p>Уживај!<br />\r\nBeWelcome тим</p>\r\n<p>PS. У случају да имаш проблеме са овим коментаром <a href="%7$s">контактирај нас</a></p>', '2014-11-20 11:35:46', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('comment.notification.new.body', 'uk', 'messages', '<p>Привіт %1$s,</p><p>%2$s написав %3$s коментар про вас. В коментарі написано:</p><p><i>"%4$s"</i></p><p><a href="%5$s">Переглянути коментар на вашому профілі</a><br><a href="%6$s">Написати або оновити</a> ваш коментар про %2$s</p><p>Бажаємо вам багато хороших вражень з BeWelcome.<br>Команда BeWelcome</p><p>P.S. Якщо у вас виникла проблема з цим коментарем, будь ласка, <a href="%7$s">зв\'яжіться з нами</a></p>', '2026-04-05 00:38:38', '2026-04-05 00:38:38', '2026-04-05 00:38:38', 'no', '', 5, NULL, 573491),
