	('comment.reminder.guest.subject', 'es', 'messages+intl-icu', '¿Cómo fue tu estancia con {username}?', '2024-02-21 19:08:53', '2024-02-21 19:08:53', '2024-02-21 19:08:53', 'no', '', 5, NULL, 25548),
