	('comment.report.header', 'en', 'messages', 'Report a comment', '2019-01-25 19:35:11', '2019-01-25 19:35:11', '0000-00-00 00:00:00', 'no', 'The header of the page where someone can report a (false) comment', 5, NULL, 1),
	('comment.report.header', 'es', 'messages', 'Reportar comentario', '2020-12-03 19:26:39', '2020-12-03 19:26:39', '2020-12-03 19:26:39', 'no', '', 5, NULL, 25548),
	('comment.report.header', 'fr', 'messages', 'Signaler un commentaire', '2019-02-19 13:11:24', '2019-02-19 13:11:24', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
