	('commentguidelinespage', 'fr', 'messages', 'Rédiger un commentaire sur le profil d\'un membre', '2013-11-11 15:38:23', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('commentguidelinespage', 'gl', 'messages', 'Comentarios nos perfís', '2021-01-13 16:01:27', '2021-01-13 16:01:27', '2021-01-13 16:01:27', 'no', '', 5, NULL, 210880),
	('commentguidelinespage', 'hr', 'messages', 'Smjernice za komentiranje', '2013-10-03 20:04:56', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('commentguidelinespage', 'hu', 'messages', 'Fórum irányelvek', '2014-08-21 22:58:03', '2020-05-25 19:41:02', '0000-00-00 00:00:00', 'no', '', 5, NULL, 36939),
