	('commentguidelinesremoveheading', 'en', 'messages', 'We may remove a comment completely, especially if', '2013-09-29 21:59:29', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', 'Subheading on about/commentguidlines page.', 5, NULL, 15240),
	('commentguidelinesremoveheading', 'es', 'messages', 'Podemos eliminar comentarios en su totalidad, especialmente si', '2013-11-09 14:52:51', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40088),
	('commentguidelinesremoveheading', 'fr', 'messages', 'Nous nous réservons le droit de supprimer complètement un commentaire si :', '2016-10-29 13:23:16', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('commentguidelinesremoveheading', 'gl', 'messages', 'Podemos quitar un comentario completamente, especialmente si', '2021-01-26 18:05:43', '2021-01-26 18:05:43', '2021-01-26 18:05:43', 'no', '', 5, NULL, 210880),
	('commentguidelinesremoveheading', 'it', 'messages', 'Potremmo rimuovere del tutto un commento, in special modo se', '2013-10-24 19:16:39', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('commentguidelinesremoveheading', 'nl', 'messages', 'We kunnen een commentaar volledig verwijden, in het bijzonder als', '2013-10-20 11:53:15', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('commentguidelinesremoveheading', 'pl', 'messages', 'Możemy całkowicie usunąć komentarz, zwłaszcza jeśli', '2020-06-09 11:54:33', '2020-06-09 11:54:33', '2020-06-09 11:54:33', 'no', '', 5, NULL, 37896),
	('commentguidelinesremoveheading', 'pt', 'messages', 'Podemos remover um comentário completamente, especialmente se', '2013-10-01 15:19:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('commentguidelinesremoveheading', 'pt-BR', 'messages', 'Nós poderemos excluir uma avaliação, especialmente se ', '2016-12-22 00:43:53', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160059),
	('commentguidelinesremoveheading', 'ru', 'messages', 'Мы можем удалить комментарий полностью, особенно если:', '2014-04-13 06:24:23', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('commentguidelinesremoveheading', 'sr', 'messages', 'Можемо у потпуности уклонити коментар, посебно ако', '2014-03-28 03:21:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 35032),
	('commentguidelinesremoveheading', 'uk', 'messages', 'Ми можемо повністю видалити коментар, особливо якщо', '2026-04-03 20:58:08', '2026-04-03 20:58:08', '2026-04-03 20:58:08', 'no', '', 5, NULL, 573491),
	('commentguidelinesremoveheading', 'zh-hant', 'messages', '我們可能會完全刪除評價，特別是如果', '2020-06-23 21:02:19', '2021-05-02 07:48:37', '2020-06-23 21:02:19', 'no', '', 5, NULL, 53422),
	('commentguidelinesremovetext', 'de', 'messages', '<ul><li>er Spam enthält;</li><li>die Person für jemand anderes schreibt;</li><li>der Verfasser offensichtlich nie persönlichen Kontakt mit dem anderen Mitglied hatte;</li><li>der Kommentar wiederholt und unnötigerweise aktualisiert wird;</li><li>der Kommentar anonym verfasst wurde oder ein Profil extra angelegt wurde, um den Kommentar zu verfassen;</li><li>der Kommentar die Arbeit eines BeWelcome Volunteers betrifft.</li></ul>', '2013-11-30 20:47:54', '2023-01-03 18:26:16', '0000-00-00 00:00:00', 'no', '', 5, NULL, 350193),
	('commentguidelinesremovetext', 'el', 'messages', '<ul class="bullet"><li>είναι «ανεπιθύμητο» ·</li><li>το άτομο γράφει εκ μέρους κάποιου άλλου·</li><li>ο δημιουργός είναι προφανές ότι δεν έχει αλληλεπιδράσει καθόλου με το άλλο μέλος·</li><li>το σχόλιο ανανεώνεται συνεχώς και χωρίς λόγο·</li><li>το σχόλιο έχει γραφεί ανώνυμα, ή από ένα προφίλ που δημιουργήθηκε μόνο και μόνο για να αφήσει αυτό το σχόλιο.·</li><li>Το σχόλιο αφορά στη δουλειά ενός εθελοντή του BeWelcome.</li></ul>', '2015-08-19 10:16:37', '2020-08-26 11:43:43', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('commentguidelinesremovetext', 'en', 'messages', '<ul class="bullet"><li>it is a spam comment;</li><li>the person is writing on behalf of somebody else;</li><li>the writer obviously never interacted with the other member at all;</li><li>the comment is repeatedly and unnecessarily updated;</li><li>the comment is written anonymously or by a profile set up merely to leave this comment;</li><li>the comment is about the work of a BeWelcome volunteer.</li></ul>', '2013-09-29 22:00:40', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', 'Text on about/commentguidlines page.', 5, NULL, 15240),
	('commentguidelinesremovetext', 'es', 'messages', '<ul class="bullet"><li>es spam;</li><li>la persona escribe de parte de otra persona;</li><li>es obvio que ambos usuarios nunca han interactuado;</li><li>el comentario es editado de forma repetiva e innecesaria;</li><li>el comentario es escrito de forma anónima o por un perfil creado explícitamente para este fin;</li><li>el comentario es sobre el trabajo de un voluntario de BeWelcome y no sobre la experiencia con este miembro.</li></ul>', '2013-11-09 14:55:40', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40088),
	('commentguidelinesremovetext', 'fr', 'messages', '<ul class="bullet"><li>le commentaire est un spam ;</li><li>le commentaire est écrit par une personne tierce ;</li><li>l\'auteur n\'a clairement pas interagi avec le membre concerné par le commentaire ;</li><li>le commentaire est mis à jour de manière continue et injustifiée ;</li><li>le commentaire est écrit de manière anonyme ou le profil de l\'auteur n\'a été créé que pour laisser ce commentaire ;</li><li>le commentaire concerne le travail du membre en tant que bénévole BeWelcome.</li></ul>', '2016-10-29 13:26:33', '2020-06-09 19:23:53', '0000-00-00 00:00:00', 'no', '', 5, NULL, 168499),
	('commentguidelinesremovetext', 'gl', 'messages', '<ul class="bullet"><li>é un comentario de spam;</li><li>a persoa está escribindo no nome doutra;</li><li>a persoa que escribe obviamente nunca interactuou coa outra  persoa membro;</li><li>o comentario é repetido e actualizado innecesariamente;</li><li>o comentario é anónimo o dun perfil feito só para deixar este comentario;</li><li>o comentario é sobre o traballo do voluntariado de unha persoa de BeWelcome.</li></ul>', '2021-01-27 09:44:56', '2021-01-27 09:44:56', '2021-01-27 09:44:56', 'no', '', 5, NULL, 210880),
	('commentguidelinesremovetext', 'it', 'messages', '<ul class="bullet"><li>è un commento spam;</li><li>la persona scrive per conto di qualcun altro;</li><li>risulta evidente che l\'autore non ha mai interagito con l\'altro membro;</li><li>il commento è aggiornato ripetutamente e senza motivo;</li><li>il commento è scritto in forma anonima o da un profilo creato appositamente per lasciare il commento;</li><li>il commento riguarda il lavoro di un volontario di BeWelcome.</li></ul>', '2013-10-24 19:39:13', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('commentguidelinesremovetext', 'nl', 'messages', '<ul class="bullet"><li>het een spam-commentaar is;</li><li>de persoon in naam van iemand anders schrijft;</li><li>het duidelijk is dat de schrijver nooit contact heeft gehad met het andere lid;</li><li>het commentaar herhaaldelijk en onnodig wordt bijgewerkt;</li><li>het commentaar anoniem is geschreven of met een profiel dat aangemaakt is speciaal om dit commentaar te plaatsen;</li><li>het commentaar gaat over het werk van een vrijwilliger van BeWelcome.</li></ul> \r\n', '2013-10-20 12:06:51', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('commentguidelinesremovetext', 'pl', 'messages', '<ul class = "bullet"> <li> jeśli komentarz to spam; </li> <li> osoba pisze w imieniu kogoś innego; </li> <li> jest oczywiste, że piszący nidy nie wszedł w interakcję z danym członkiem; </li> <li> komentarz jest wielokrotnie i niepotrzebnie aktualizowany; </li> <li> komentarz jest zostawiony anonimowo lub przez profil skonfigurowany wyłącznie w celu pozostawienia tego komentarza; </li> <li> komentarz dotyczy pracy wolontariusza BeWelcome. </li> </ul>', '2020-06-09 11:59:53', '2020-06-09 11:59:53', '2020-06-09 11:59:53', 'no', '', 5, NULL, 37896),
	('commentguidelinesremovetext', 'pt', 'messages', '<ul class="bullet"><li>é um comentário sem conteúdo útil;</li><li>a pessoa está a escrever em nome de outrem;</li><li>o escritor claramente nunca interagiu com o outro membro;</li><li>o comentário é repetida e desnecessariamente atualizado;</li><li>o comentário é escrito de forma anónima ou por um perfil criado de propósito para escrever este comentário;</li><li>o comentário é sobre o trabalho de um voluntário BeWelcome.</li></ul>', '2014-01-02 22:20:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('commentguidelinesremovetext', 'ru', 'messages', '<ul class="bullet"><li>этот комментарий — спам;</li><li>автор пишет не от своего имени;</li><li>автор, очевидно, никогда не встречался с другими участниками;</li><li>комментарий многократно без необходимости обновлялся;</li><li>комментарий оставлен анонимно или от имени профиля, созданного только затем, чтобы оставить данный комментарий;</li><li>комментарий посвящен работе волонтера BeWelcome.</li></ul>', '2014-04-12 13:49:13', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('commentguidelinesremovetext', 'sr', 'messages', '<ul class="bullet"><li>је у питању спам</li><li>особа пише у име неког другог</li><li>члан очигледно никад није био у контакту са другим члановима</li><li>коментар је више пута и непотребно измењен</li><li>коментар је анонимно написан, или са профила намењеним само да остави овај коментар</li><li>коментар се односи на рад BeWelcome волонтера.</li></ul>', '2014-12-24 13:26:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('commentguidelinesremovetext', 'uk', 'messages', '<ul><li>це спам-коментар;</li><li>особа пише від імені когось іншого;</li><li>автор явно ніколи не взаємодіяв з іншим учасником;</li><li>коментар повторно і без потреби оновлюється;</li><li>коментар написаний анонімно або профілем, створеним лише для того, щоб залишити цей коментар;</li><li>коментар стосується роботи волонтера BeWelcome.</li></ul>', '2026-04-03 20:58:17', '2026-04-03 20:58:17', '2026-04-03 20:58:17', 'no', '', 5, NULL, 573491),
	('commentguidelinesremovetext', 'zh-hant', 'messages', '<ul class="bullet"> <li>這是垃圾評價； </li> <li>此人代表他人寫作； </li> <li>評價人顯然從未與其他成員進行過互動； </li> <li>評價被重複地和不必要地更新； </li><li>評論是匿名撰寫的，或者是通過僅用於保留此評價的個人資料撰寫的。</li> <li> 評價是關於BeWelcome志工的工作。</li></ul>', '2020-06-23 21:04:35', '2021-05-02 07:48:37', '2020-06-23 21:04:35', 'no', '', 5, NULL, 53422),
	('commentguidlineslink', 'ar', 'messages', 'الرجاء قراءة <b><a href="about/commentguidelines"> دليل التعليق على الملفات الشخصية </a></b> قبل كتابة التعليقات.', '2014-01-24 23:11:22', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48359),
	('commentguidlineslink', 'ca', 'messages', '<p>Si us plau, llegeix les <a href="https://bewelcome.org/about/commentguidelines">directrius dels comentaris </a>abans d\'escriure un comentari.</p>', '2024-02-23 13:07:40', '2024-02-23 13:07:40', '2024-02-23 13:07:40', 'no', '', 5, NULL, 306997),
	('commentguidlineslink', 'cs', 'messages', 'Přečti si, prosím, naše <b><a href="about/commentguidelines">pokyny ohledně komentářů profilu</a></b> předtím, než začneš psát komentáře. ', '2013-10-16 20:14:21', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('commentguidlineslink', 'da', 'messages', '<p>Læs venligst vores <a href="about/commentguidelines">guidelines for kommentarer</a>, før du skriver kommentarer.</p>', '2022-08-14 21:08:25', '2022-08-14 21:08:25', '2022-08-14 21:08:25', 'no', '', 5, NULL, 274594),
	('commentguidlineslink', 'de', 'messages', 'Bitte lies unsere  <b><a href="about/commentguidelines">Kommentar-Richtlinien</a></b>  bevor du einen Kommentar schreibst.', '2013-11-20 09:06:46', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('commentguidlineslink', 'el', 'messages', 'Διάβασε τις <b><a href="about/commentguidelines">Οδηγίες Σχολιασμού Προσώπων</a></b> πριν γράψεις κάποιο σχόλιο.', '2013-11-26 00:07:24', '2020-08-26 06:52:33', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('commentguidlineslink', 'en', 'messages', 'Please read our <b><a href="about/commentguidelines">Profile Comment Guidelines</a></b> before writing comments.', '2013-09-29 22:09:06', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', 'Link to comment guidelines on profile comments page.', 5, NULL, 15240),
	('commentguidlineslink', 'eo', 'messages', '<p>Bonvolu legi nian <a href="about/commentguidelines"><strong>Gvidilon pri Komentoj sur Profiloj</strong></a> antaŭ ol vi verkas komentojn.<br>&nbsp;</p>', '2022-05-10 08:18:57', '2022-05-10 08:20:32', '2022-05-10 08:18:57', 'no', '', 5, NULL, 47526),
	('commentguidlineslink', 'es', 'messages', 'Por favor toma un instante para <b><a href="about/commentguidelines">leer la Guía para los comentarios de perfil</a></b> antes de escribir el tuyo.', '2013-12-01 20:42:53', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 554),
	('commentguidlineslink', 'fi', 'messages', 'Perehdy <b><a href="about/commentguidelines">profiilin kommentointiohjeistoon</a></b> ennenkuin kirjoitat kommentteja.', '2014-06-15 13:10:31', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 72),
	('commentguidlineslink', 'fr', 'messages', 'Lire le <b><a href="about/commentguidelines">guide pour la rédaction des commentaires</a></b> avant d\'ajouter un commentaire sur le profil d\'un membre.', '2013-10-04 21:30:58', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('commentguidlineslink', 'gl', 'messages', '<p>Por favor le as nosas <a href="about/commentguidelines"><strong>Pautas de Comentarios no Perfil</strong></a> antes de escribir comentarios.</p>', '2021-01-26 18:17:42', '2021-07-29 11:02:47', '2021-01-26 18:17:42', 'no', '', 5, NULL, 210880),
	('commentguidlineslink', 'hr', 'messages', 'Prije komentiranja, molimo te, pročitaj naše <b><a href="about/commentguidelines">Naputke za komentiranje profila</a></b>.', '2015-08-02 16:59:31', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('commentguidlineslink', 'it', 'messages', 'Per favore leggi le <b><a href="about/commentguidelines">Linee guida dei Commenti</a></b> prima di scriverne uno', '2013-10-07 12:28:21', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15318),
	('commentguidlineslink', 'ku', 'messages', 'Lava, <b><a href="about/commentguidelines"> Rêdan bikaranîna têbîna kurtjîyannamê </a></b> bixweîne berî ku tu binivsînî.', '2013-11-24 10:32:06', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48359),
	('commentguidlineslink', 'lt', 'messages', '<p>Prašome perskaityti mūsų &lt;b&gt;&lt;a href="about/commentguidelines"&gt;Profilio Komentarų Gaires&lt;/a&gt;&lt;/b&gt; prieš rašant komentarus.</p>', '2023-01-20 09:15:54', '2023-01-20 09:18:54', '2023-01-20 09:15:54', 'no', '', 5, NULL, 285578),
	('commentguidlineslink', 'nl', 'messages', 'Lees alsjeblieft onze <b><a href="about/commentguidelines">richtlijnen voor profielcommentaren</a></b> voor je een commentaar schrijft. ', '2013-10-05 20:26:11', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40169),
	('commentguidlineslink', 'pl', 'messages', '<p>Przeczytaj <a href="about/commentguidelines"><strong>Wytyczne na temat komentarzy</strong></a> przed napisaniem swojego.</p>', '2020-05-29 08:42:24', '2021-06-13 23:17:05', '2020-05-29 08:42:24', 'no', '', 5, NULL, 116789),
