	('commentnocomment', 'zh-hant', 'messages', '尚未評價', '2020-06-23 20:24:55', '2021-05-02 07:48:37', '2020-06-23 20:24:55', 'no', '', 5, NULL, 53422),
	('commentnotificationmessagenew', 'de', 'messages', '<p>Hallo %1$s,</p>\r\n<p>%2$s hat einen %3$s Kommentar über dich geschrieben. Der Kommentar lautet:</p>\r\n<p><i>"%4$s"</i></p>\r\n<p><a href="%5$s">Lies mehr</a> über den Kommentar.<br />\r\n<a href="%6$s">Schreibe oder aktualisiere</a> Deinen Kommentar über %2$s</p>\r\n<p>Wir wünschen Dir eine gute Zeit!<br />\r\ndas BeWelcome Team</p>\r\n<p>PS. Solltest Du mit diesem Kommentar ein Problem haben, dann <a href="%7$s">kontaktiere uns</a></p> bitte.', '2016-02-06 13:12:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 174),
	('commentnotificationmessagenew', 'el', 'messages', '<p>Γεια %1$s,</p>\r\n<p>%2$s σου άφησε ένα %3$s σχόλιο. Το σχόλιο λέει:</p>\r\n<p><i>"%4$s"</i></p>\r\n<p><a href="%5$s">Διάβασε περισσότερα</a> σχετικά με το σχόλιο.<br />\r\n<a href="%6$s">Γράψε ή ενημέρωσε</a> το σχόλιο σου σχετικά με %2$s</p>\r\n<p>Να περάσεις καλά!<br />\r\nΗ ομάδα του BeWelcome</p>\r\n<p>Y.Γ. Σε περίπτωση που υπάρχει πρόβλημα με αυτό το σχόλιο <a href="%7$s">επικοινώνησε μαζί μας</a></p>', '2020-08-19 20:41:37', '2020-08-28 11:46:03', '2020-08-19 20:41:37', 'no', '', 5, NULL, 266544),
	('commentnotificationmessagenew', 'en', 'messages', '<p>Hi %1$s,</p>\n<p>%2$s has left you a %3$s comment. The comment says:</p>\n<p><i>"%4$s"</i></p>\n<p><a href="%5$s">Read more</a> about the comment.<br />\n<a href="%6$s">Write or update</a> your comment about %2$s</p>\n<p>Have a great time!<br />\nThe BeWelcome Team</p>\n<p>PS. In case you have a problem with this comment please <a href="%7$s">contact us</a></p>', '2014-10-07 21:22:19', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', 'Text of notification for a member who receives a comment', 5, NULL, 1),
	('commentnotificationmessagenew', 'es', 'messages', '<p>Hola %1$s,</p>\r\n<p>%2$s te ha dejado un %3$s comentario. El comentario dice:</p>\r\n<p><i>"%4$s"</i></p>\r\n<p><a href="%5$s">Leer más</a> sobre el comentario.<br />\r\n<a href="%6$s">Escribir o actualizar</a> tu comentario sobre %2$s</p>\r\n<p>¡Que lo pases bien!<br />\r\nEl equipo de BeWelcome</p>\r\n<p>PD: Si tienes algún problema con este comentario <a href="%7$s">ponte en contacto con nosotros</a></p>', '2014-12-20 10:46:41', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 85785),
	('commentnotificationmessagenew', 'fr', 'messages', '<p>Bonjour %1$s,</p>\r\n<p>%2$s vous a laissé un commentaire %3$s&nbsp;:</p>\r\n<p><i>«&nbsp;%4$s&nbsp;»</i></p>\r\n<p><a href="%5$s">Lire l\'intégralité</a> du commentaire.<br />\r\n<a href="%6$s">Ecrire ou actualiser</a> votre commentaire concernant %2$s</p>\r\n<p>Nous vous souhaitons de belles expériences sur BeWelcome&nbsp;!<br />\r\nL’équipe bénévole</p>\r\n<p>PS&nbsp;: si ce commentaire ne respecte pas la charte BeWelcome, merci de <a href="%7$s">nous contacter</a></p>\r\n', '2015-07-27 20:33:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('commentnotificationmessagenew', 'gl', 'messages', '<p>Ola %1$s,</p>\r\n<p>%2$s deixouche un %3$s comentario. O comentario di:</p>\r\n<p><i>"%4$s"</i></p>\r\n<p><a href="%5$s">Read more</a> sobre o comentario.<br />\r\n<a href="%6$s">Escrebe ou actualiza</a> o teu comentario sobre %2$s</p>\r\n<p>Pásao ben<br />\r\nO equipo de BeWelcome</p>\r\n<p>P.D. No caso de que teñas un problema con este comentario, por favor, <a href="%7$s">contáctanos</a></p>', '2021-02-04 16:30:50', '2021-02-04 16:30:50', '2021-02-04 16:30:50', 'no', '', 5, NULL, 210880),
	('commentnotificationmessagenew', 'it', 'messages', '<p>Ciao %1$s,</p>\r\n<p>%2$s ti ha lasciato un %3$s commento. Ecco cosa ha detto:</p>\r\n<p><i>"%4$s"</i></p>\r\n<p><a href="%5$s">Continua</a> a leggere il commento.<br />\r\n<a href="%6$s">Scrivi o aggiorna</a> il tuo commento su %2$s</p>\r\n<p>Divertiti!<br />\r\nThe BeWelcome Team</p>\r\n<p>PS. Se dovessi avere un problema con questo commento, scrivici una mail a <a href="%7$s">contact us</a></p>', '2015-01-05 12:49:15', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('commentnotificationmessagenew', 'nl', 'messages', '<p>Hallo %1$s,</p>\r\n<p>%2$s heeft een %3$s commentaar over je geschreven. Het commentaar is:</p>\r\n<p><i>"%4$s"</i></p>\r\n<p><a href="%5$s">Lees meer</a> over het commentaar.<br />\r\n<a href="%6$s">Schrijf of ververs</a> jouw commentaar over %2$s</p>\r\n<p>Het beste gewenst!<br />\r\nHet BeWelcome Team</p>\r\n<p>PS. In het geval dat je een probleem hebt met dit commentaar <a href="%7$s">neem alsjeblieft contact met ons op</a></p>', '2015-03-31 17:06:27', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40169),
	('commentnotificationmessagenew', 'pl', 'messages', '<p>Cześć %1$s,</p>\r\n<p>%2$s napisał(a) Ci %3$s komentarz o treści:</p>\r\n<p><i>"%4$s"</i></p>\r\n<p><a href="%5$s">Przeczytaj więcej</a> o komentarzu.<br />\r\n<a href="%6$s">Napisz albo zaktualizuj</a> Twój komentarz o %2$s</p>\r\n<p>Pozdrawiamy!<br />\r\nZespół BeWelcome</p>\r\n<p>PS. W przypadku problemów z tym komentarzem prosimy, <a href="%7$s">skontaktuj się z nami</a></p>', '2021-01-14 20:53:50', '2021-01-14 20:59:04', '2021-01-14 20:53:50', 'no', '', 5, NULL, 116789),
	('commentnotificationmessagenew', 'pt', 'messages', '<p>Olá %1$s,</p>\r\n<p>%2$s deixou-lhe um comentário %3$s. O comentário diz:</p>\r\n<p><i>"%4$s"</i></p>\r\n<p><a href="%5$s">Leia mais</a> sobre o comentário.<br />\r\n<a href="%6$s">Escrever ou atualizar</a> o seu comentário sobre %2$s</p>\r\n<p>Divirta-se à grande!<br />\r\nA Equipa BeWelcome</p>\r\n<p>PS. Caso tenha algum problema com este comentário, por favor, <a href="%7$s">contacte-nos</a></p>', '2014-10-23 10:39:15', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('commentnotificationmessagenew', 'pt-BR', 'messages', '<p>Olá %1$s,</p>\r\n<p>%2$s deixou uma avaliação %3$s para você. A mensagem diz:</p>\r\n<p><i>"%4$s"</i></p>\r\n<p><a href="%5$s">Leia mais</a> sobre a avalização.<br />\r\n<a href="%6$s">Escreva ou atualize</a> sua avaliação sobre %2$s</p>\r\n<p>Tenha um ótimo dia!<br />\r\nEquipe BeWelcome</p>\r\n<p>PS: Caso você tenha algum problema com essa avaliação, por favor <a href="%7$s">entre em contato</a></p>', '2016-12-20 14:03:52', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160059),
	('commentnotificationmessagenew', 'ru', 'messages', '<p>Привет %1$s,</p>\r\n<p>%2$s оставил Вам %3$s комментарий. В нём сказано:</p>\r\n<p><i>"%4$s"</i></p>\r\n<p><a href="%5$s">Читать ещё</a> о комментарии.<br />\r\n<a href="%6$s">Написать или обновить</a> Ваш комментарий о %2$s</p>\r\n<p>Удачи!<br />\r\nКоманда BeWelcome</p>\r\n<p>PS. В том случае, если у Вас есть проблемы с комментарием, пожалуйста,  <a href="%7$s">свяжитесь с нами</a></p>', '2014-12-06 06:21:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('commentnotificationmessagenew', 'sr', 'messages', '<p>Здраво %1$s,</p>\r\n<p>%2$s је написао %3$s коментар. Коментар гласи:</p>\r\n<p><i>"%4$s"</i></p>\r\n<p><a href="%5$s">Прочитај више</a> о коментару.<br>\r\n<a href="%6$s">Напиши или ажурирај</a> свој коментар о %2$s</p>\r\n<p>Уживај!<br />\r\nBeWelcome тим</p>\r\n<p>PS. У случају да имаш проблеме са овим коментаром <a href="%7$s">контактирај нас</a></p>', '2014-11-20 11:35:46', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('commentnotificationmessageupdate', 'de', 'messages', '<p>Hallo %1$s,</p>\r\n<p>%2$s hat seinen %3$s Kommentar über Dich aktualisiert. Der Kommentar ist nun %3$s und lautet:</p>\r\n<p><i>"%4$s"</i></p>\r\n<p><a href="%5$s">Lies mehr</a> über den Kommentar.<br />\r\n<a href="%6$s">Schreibe oder aktualisiere</a> Deinen Kommentar über %2$s</p>\r\n<p>Wir wünschen Dir eine gute Zeit!<br />\r\ndas BeWelcome Team</p>\r\n<p>PS. Solltest Du mit diesem Kommentar ein Problem haben, dann <a href="%7$s">kontaktiere uns</a></p> bitte.', '2016-02-06 13:13:53', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 174),
	('commentnotificationmessageupdate', 'el', 'messages', '<p>Γεια%1$s,</p>\r\n<p>%2$s έχει ενημερώσει το σχόλιο του σχετικά με σένα. Πρόκειται για %3$s σχόλιο που λέει:</p>\r\n<p><i>"%4$s"</i></p>\r\n<p><a href="%5$s">Διάβασε περισσότερα</a> για το σχόλιο.<br>\r\n<a href="%6$s">Γράψε ή ενημέρωσε</a> το σχόλιο σου σχετικά με %2$s</p>\r\n<p>Να περνάς καλά!<br />\r\nΗ ομάδα του BeWelcome</p>\r\n<p>PS. Σε περίπτωση που υπάρχει πρόβλημα με το σχόλιο <a href="%7$s">επικοινώνησε μαζί μας</a></p>', '2020-08-20 08:07:38', '2020-08-28 17:52:33', '2020-08-20 08:07:38', 'no', '', 5, NULL, 266544),
	('commentnotificationmessageupdate', 'en', 'messages', '<p>Hi %1$s,</p>\n<p>%2$s has updated the comment about you. This is now a %3$s comment and says:</p>\n<p><i>"%4$s"</i></p>\n<p><a href="%5$s">Read more</a> about the comment.<br>\n<a href="%6$s">Write or update</a> your comment about %2$s</p>\n<p>Have a great time!<br />\nThe BeWelcome Team</p>\n<p>PS. In case you have a problem with this comment please <a href="%7$s">contact us</a></p>', '2014-10-07 21:22:19', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', 'Text of notification for a member when a comment is updated', 5, NULL, 1),
	('commentnotificationmessageupdate', 'es', 'messages', '<p>Hola %1$s,</p>\r\n<p>%2$s ha actualizado un comentario sobre ti. Ahora es un %3$s comentario y dice:</p>\r\n<p><i>"%4$s"</i></p>\r\n<p><a href="%5$s">Leer más</a> sobre este comentario.<br>\r\n<a href="%6$s">Escribir o actualizar</a> tu comentario sobre %2$s</p>\r\n<p>¡Pásalo bien!<br />\r\nEl equipo de BeWelcome</p>\r\n<p>PD: Si tienes algún problema con este comentario <a href="%7$s">ponte en contacto con nosotros</a></p>', '2014-12-20 10:50:16', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 85785),
	('commentnotificationmessageupdate', 'fr', 'messages', '<p>Bonjour %1$s,</p>\r\n<p>%2$s a actualisé son commentaire %3$s sur vous&nbsp;:</p>\r\n<p><i>«&nbsp;%4$s&nbsp;»</i></p>\r\n<p><a href="%5$s">Lire l\'intégralité</a> du commentaire.<br />\r\n<a href="%6$s">Écrire ou actualiser</a> votre commentaire concernant %2$s.</p>\r\n<p>Nous vous souhaitons des belles expériences sur BeWelcome&nbsp;!<br />\r\nL’équipe bénévole</p>\r\n<p>PS&nbsp;: si ce commentaire ne respecte pas la charte BeWelcome, merci de <a href="%7$s">nous contacter</a></p>\r\n', '2015-07-27 20:36:11', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('commentnotificationmessageupdate', 'gl', 'messages', '<p>Ola %1$s,</p>\r\n<p>%2$s actualizou o comentario sobre ti. Ë agora un comentario  %3$s e di:</p>\r\n<p><i>"%4$s"</i></p>\r\n<p><a href="%5$s">Ler máis</a> sobre o comentario.<br>\r\n<a href="%6$s">Escrebe o actualiza </a> tu comentario sobre  %2$s</p>\r\n<p>Pásao ben!<br />\r\nO Equipo de BeWelcome</p>\r\n<p>P.D. No caso de que teñas un problema con este comentario por favor <a href="%7$s">contáctanos</a></p>', '2021-02-04 16:34:36', '2021-02-04 16:34:36', '2021-02-04 16:34:36', 'no', '', 5, NULL, 210880),
	('commentnotificationmessageupdate', 'it', 'messages', '<p>Ciao %1$s,</p>\r\n<p>%2$s ha aggiornato il suo commento su di te. Questo è il nuovo commento di %3$s:</p>\r\n<p><i>"%4$s"</i></p>\r\n<p><a href="%5$s">Continua</a> a leggerlo.<br>\r\n<a href="%6$s">Scrivi o aggiorna</a> il tuo commento su%2$s</p>\r\n<p>Divertiti!<br />\r\nThe BeWelcome Team</p>\r\n<p>PS. Se dovessi avere un problema con questo commento, <a href="%7$s">contattaci</a></p>', '2015-01-05 13:03:05', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('commentnotificationmessageupdate', 'nl', 'messages', '<p>Hoi %1$s,</p>\r\n<p>%2$s heeft zijn commentaar over jou ververst. Dit is nu een %3$s commentaar en is:</p>\r\n<p><i>"%4$s"</i></p>\r\n<p><a href="%5$s">Lees meer</a> over het commentaar.<br>\r\n<a href="%6$s">Schrijf of ververs</a> jouw commentaar over %2$s</p>\r\n<p>Het beste gewenst!<br />\r\nHet BeWelcome Team</p>\r\n<p>PS. In het geval je een probleem hebt met dit commentaar <a href="%7$s">neem alsjeblieft contact met ons op</a>.</p>', '2015-03-31 17:12:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40169),
	('commentnotificationmessageupdate', 'pl', 'messages', '<p>Cześć %1$s,</p>\r\n<p>%2$s napisał(a) Ci komentarz. To %3$s komentarz, który brzmi:</p>\r\n<p><i>"%4$s"</i></p>\r\n<p><a href="%5$s">Przeczytaj więcej</a> o komentarzu.<br>\r\n<a href="%6$s">Napisz lub zaktualizuj</a> twój komentarz o %2$s</p>\r\n<p>Pozdrawiamy!<br />\r\nZespół BeWelcome</p>\r\n<p>PS. Jeśli masz problem z tym komentarzem, prosimy <a href="%7$s">skontaktuj się z nami</a></p>.', '2021-01-14 20:58:35', '2021-01-14 20:58:35', '2021-01-14 20:58:35', 'no', '', 5, NULL, 116789),
	('commentnotificationmessageupdate', 'pt', 'messages', '<p>Olá %1$s,</p>\r\n<p>%2$s atualizou o comentário sobre si. É agora um comentário %3$s e diz:</p>\r\n<p><i>"%4$s"</i></p>\r\n<p><a href="%5$s">Leia mais</a> sobre o comentário.<br />\r\n<a href="%6$s">Escrever ou atualizar</a> o seu comentário sobre %2$s</p>\r\n<p>Divirta-se à grande!<br />\r\nA Equipa BeWelcome</p>\r\n<p>PS. Caso tenha algum problema com este comentário, por favor, <a href="%7$s">contacte-nos</a></p>', '2014-10-23 10:40:16', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('commentnotificationmessageupdate', 'pt-BR', 'messages', '<p>Olá %1$s,</p>\r\n<p>%2$s atualizou uma avaliação sobre você. Agora é uma avaliação %3$s e a mensagem diz:</p>\r\n<p><i>"%4$s"</i></p>\r\n<p><a href="%5$s">Leia mais</a> sobre a avalização.<br />\r\n<a href="%6$s">Escreva ou atualize</a> sua avaliação sobre %2$s</p>\r\n<p>Tenha um ótimo dia!<br />\r\nEquipe BeWelcome</p>\r\n<p>PS: Caso você tenha algum problema com essa avaliação, por favor <a href="%7$s">entre em contato</a></p>', '2016-12-20 14:06:05', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160059),
	('commentnotificationmessageupdate', 'ru', 'messages', '<p>Привет %1$s,</p>\r\n<p>%2$s обновил комментарий о Вас. Теперь это %3$s комментарий, в котором сказано:</p>\r\n<p><i>"%4$s"</i></p>\r\n<p><a href="%5$s">Читать ещё</a> о комментарии.<br />\r\n<a href="%6$s">Написать или обновить</a> Ваш комментарий о %2$s</p>\r\n<p>Удачи!<br />\r\nКоманда BeWelcome</p>\r\n<p>PS. В том случае, если у Вас есть проблемы с комментарием, пожалуйста,  <a href="%7$s">свяжитесь с нами</a></p>', '2014-12-06 06:29:46', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('commentnotificationmessageupdate', 'sr', 'messages', '<p>Здраво %1$s,</p>\r\n<p>%2$s је ажирирао/ла коментар о теби. Ово је нов коментар који гласи:</p>\r\n<p><i>"%4$s"</i></p>\r\n<p><a href="%5$s">Прочитај више</a> о коментару.<br>\r\n<a href="%6$s">Напиши или ажурирај</a> свој коментар о %2$s</p>\r\n<p>Уживај!<br />\r\nBeWelcome тим</p>\r\n<p>PS. У случају да имаш проблеме са овим коментаром <a href="%7$s">контактирај нас</a></p>', '2014-11-20 11:32:40', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('commentofthemomentexplanation', 'en', 'messages', 'This Comment has been chosen by the BeWelcome members as and intersting comment.\r\nThis is subject to change (it depends on members), the purpose is demonstrate the interest of BeWelcome activity', '2009-05-23 08:32:14', '2019-04-23 18:16:49', '2009-05-23 08:32:14', 'no', 'Explanation for the page comment of the moment', 5, 1, 1),
	('commentofthemomentexplanation', 'es', 'messages', 'Este comentario fue considerado de interés para los miembros de BeWelcome.\r\nEstá sujeto a cambios (depende del miembro), el propósito es demostrar el interés de la actividad de BeWelcome ', '2009-07-09 11:52:55', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1328),
	('commentofthemomentexplanation', 'fr', 'messages', 'Ce commentaire a été choisi par les membres de BeWelcome en tant que commentaire "Intéressant".\r\nCela est sujet à évolution et demeure bien sur très subjectif,le seul but est d\'illustrer l\'intérêt et l\'activité de BeWelcome.', '2009-09-05 08:07:04', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 68),
	('commentofthemomentexplanation', 'it', 'messages', 'Questo commento è stato selezionato dai membri di BeWelcome come interessante. Questo risultato è soggetto a cambiamenti (dipende dai membri).', '2011-12-20 10:35:08', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 16084),
