	('commentscommenterdescription', 'ar', 'messages', 'أوصف العضو/العضوة %s فتسهل على من سيقوم بأستضافته/أستضافتها ان يعلم من هو/هى', '2008-02-11 15:50:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 2702),
	('commentscommenterdescription', 'bg', 'messages', 'Опиши член %s така че другите членове, които ще го подслоняват, ще разберат що за човек е той.', '2007-07-04 18:13:32', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 851),
	('commentscommenterdescription', 'ca', 'messages', 'Descriu %s. Així els altres membres que l\'allotgin podran saber com és.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11944),
	('commentscommenterdescription', 'cs', 'messages', 'Prosím popiš svou zkušenost s <b>%s</b>, aby další členové mohli posoudit, zda oni sami by rádi interagovali s touto členkou/tímto členem.', '2014-01-16 22:29:11', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('commentscommenterdescription', 'da', 'messages', 'Beskriv %s så andre medlemmer kan få en ide om hvem han eller hun er.', '2008-06-28 08:57:59', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 74),
	('commentscommenterdescription', 'de', 'messages', 'Bitte beschreibe hier deine Erfahrung mit <b>%s</b>, damit andere Mitglieder abschätzen können, ob sie selbst auch gerne Kontakt mit diese Mitglied haben wollen. ', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('commentscommenterdescription', 'el', 'messages', 'Μίλησε μας για την εμπειρία σου με τον/την <b>%s</b> έτσι ώστε άλλα μέλη να μπορούν να αξιολογήσουν αν θα απολάμβαναν τη γνωριμία με αυτό το μέλος.', '2013-10-03 20:12:25', '2020-08-25 16:37:38', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('commentscommenterdescription', 'en', 'messages', 'Please describe your experience with <b>%s</b> so that other members can assess whether they themselves would enjoy interacting with this member.', '2007-08-06 14:42:40', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', 'This sentence is displayed when someone is about to set a comment about another member. %s stands for the username.', 5, NULL, 15240),
	('commentscommenterdescription', 'eo', 'messages', 'Priskribu la membron <b>%s</b> por ke aliaj gastigantoj sciu kia tiu persono estas.', '2007-09-10 21:05:09', '2020-05-24 23:16:33', '0000-00-00 00:00:00', 'no', '', 5, NULL, 261823),
	('commentscommenterdescription', 'es', 'messages', 'Describe tu experiencia con <b>%s</b> para que otros miembros puedan decidir si quieren interactuar com este miembro.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40088),
	('commentscommenterdescription', 'eu', 'messages', '<b>%s</b> kidea deskribatu, gainontzeko kideak jakin dezaten nolakoa den.', '2012-12-23 17:06:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11907),
	('commentscommenterdescription', 'fi', 'messages', 'Kuvaile jäsentä %s siten, että muut jäsenet, jotka tulevat hänet majoittamaan tietävät kuka hän on.', '2007-08-04 20:19:15', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 72),
	('commentscommenterdescription', 'fr', 'messages', 'Décrivez votre expérience avec %s, pour permettre aux autres membres d\'en savoir plus sur ce membre.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('commentscommenterdescription', 'gl', 'messages', 'Por favor describe a túa experiencia con <b>%s</b> de modo que outras persoas da comunidade podan valorar se elas mesmas podería gozar interactuando con esta persoa.', '2021-01-26 17:51:29', '2021-01-26 17:51:29', '2021-01-26 17:51:29', 'no', '', 5, NULL, 210880),
	('commentscommenterdescription', 'he', 'messages', '<p>נא לתאר את החוויה שלך עם %s כך שחברים אחרים יוכלו להחליט אם הם יהנו מהתחברות אליו</p>', '2022-07-11 18:10:14', '2022-07-11 18:10:14', '2022-07-11 18:10:14', 'no', '', 5, NULL, 290109),
	('commentscommenterdescription', 'hr', 'messages', 'Opiši svoje iskustvo s <b>%s</b> kako bi drugi članovi mogli procijeniti bi li im ta osoba bila zanimljiva za druženje. ', '2009-08-20 19:46:39', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('commentscommenterdescription', 'hu', 'messages', 'Jellemezd %s tagot, hogy a többi tag aki később esetleg szállást ad neki megismerhesse.', '2007-09-05 18:35:13', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 805),
	('commentscommenterdescription', 'id', 'messages', 'Jelaskan tentang anggota ini %s sebagai rekomendasi bagi anggota lainnya ', '2007-11-07 15:22:15', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 2019),
	('commentscommenterdescription', 'it', 'messages', 'Racconta la tua esperienza con <b>%s</b>, così che gli altri membri possano farsi un\'idea se avrebbero piacere ad incontrarlo o meno. ', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('commentscommenterdescription', 'ja', 'messages', '%sをホストとして迎えるメンバーたちのために、本人について書いてください。', '2007-11-06 09:11:10', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1834),
	('commentscommenterdescription', 'ku', 'messages', 'Lava tecrûba xwe bi <b>%s</b> re bêjê û binivsîne ku endamên din wî/wê baştir nasbikin.', '2014-04-11 10:26:12', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48359),
	('commentscommenterdescription', 'lt', 'messages', 'Aprašyk %s tam, kad kiti BeWelcome nariai matytų daugiau objektyvios informacijos apie šį narį.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('commentscommenterdescription', 'lv', 'messages', 'Apraksti biedru %s lai citi biedri, kuri hostos viņu, zinātu, kas viņa/viņš ir.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 375),
	('commentscommenterdescription', 'nl', 'messages', 'Beschrijf je ervaring met <b>%s</b> zo dat andere leden kunnen bepalen of zij zelf graag met hem/haar in contact zouden willen komen.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40169),
	('commentscommenterdescription', 'no', 'messages', 'Beskriv %s slik at andre verter eller gjester kan finne ut hvordan vedkommende er.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 573),
	('commentscommenterdescription', 'pl', 'messages', 'Opisz tę osobę żeby inni wiedzieli z kim mają się spotkać.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 90),
	('commentscommenterdescription', 'pt', 'messages', 'Descreva a sua experiência com <b>%s</b> de forma a que outros membros possam avaliar se gostariam de interagir com esta pessoa.', '2007-06-29 12:11:38', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('commentscommenterdescription', 'pt-BR', 'messages', 'Por favor, descreva sua experiência com <b>%s</b> para que outros membros que possam saber se vão apreciar a interação com este membro.', '2007-08-06 14:44:57', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160059),
	('commentscommenterdescription', 'ro', 'messages', 'Descrie pe %s în aşa fel încât alţi membri care îl/o vor găzdui vor şti cine şi cum este.', '2007-07-25 14:10:56', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1081),
	('commentscommenterdescription', 'ru', 'messages', 'Опишите ваш  опыт общения с <b>%s</b> так, чтобы другие участники могли самостоятельно сделать вывод насколько им будет интересно взаимодействие с ним(ней).', '0000-00-00 00:00:00', '2020-06-09 19:44:04', '0000-00-00 00:00:00', 'no', '', 5, NULL, 134997),
	('commentscommenterdescription', 'sk', 'messages', 'Popíš prosím <b>%s</b>, aby ostatní, ktorí ho/ju budú hosťovať, vedeli čo je zač.', '2013-03-25 19:38:27', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48253),
	('commentscommenterdescription', 'sr', 'messages', 'Опишите своје искуство са <b>%s</b>, како би други чланови одлучили да ли они сами желе интеракцију са овим чланом.', '2013-01-17 03:11:48', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 60746),
	('commentscommenterdescription', 'sv', 'messages', 'Beskriv medlemmen <b>%s</b> så att andra medlemmar som kommer att vara värd åt honom/henne vet vem han/hon är.', '2013-03-18 14:20:24', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 93341),
