	('commentslabel', 'zh-hant', 'messages', '标题（可选）', '2010-01-24 07:05:00', '2021-05-02 07:48:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 9518),
	('commentsomethingwentwrong', 'de', 'messages', 'Leider ist etwas schief gegangen, Dein Kommentar wurde nicht gespeichert. Versuch es bitte noch einmal, und wenn es weiterhin Probleme gibt, verständige das Support-Team.', '2016-01-23 21:18:57', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 25410),
	('commentsomethingwentwrong', 'el', 'messages', 'Κάτι πήγε στραβά με την ανάρτηση του σχολίου σου. Δοκίμασε ξανά. Αν το πρόβλημα επιμείνει, επικοινώνησε με την ομάδα υποστήριξης.', '2015-09-14 15:30:02', '2020-08-26 12:20:56', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('commentsomethingwentwrong', 'en', 'messages', 'Sorry, something went wrong with your comment post. Please try again. If the problem persists please contact the support team.', '2015-09-02 19:29:34', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', 'Used on the comment page if someone tries to spam.', 5, NULL, 1),
	('commentsomethingwentwrong', 'es', 'messages', 'Lo sentimos, algo no salió como esperabamos en tu comentario. Intentalo otra vez, por favor. Si el problema persiste, contacta con el equipo de soporte.', '2016-02-09 08:28:57', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40088),
	('commentsomethingwentwrong', 'fr', 'messages', 'Désolé, il y a eu une erreur avec la publication de votre message. Veuillez réessayer. Si le problème persiste, merci de contacter l\'équipe technique. ', '2015-09-17 23:15:30', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('commentsomethingwentwrong', 'gl', 'messages', 'Sentímolo, algo non funcionou co teu comentario. Por favor, téntao de novo. Se o problema persiste contacta co equipo de apoio', '2021-01-31 10:35:33', '2021-01-31 10:35:33', '2021-01-31 10:35:33', 'no', '', 5, NULL, 210880),
	('commentsomethingwentwrong', 'it', 'messages', 'Scusaci, qualcosa è andato storto nell\'inserimento del tuo commento. Per favore prova di nuovo. Se il problema persiste, gentilmente contatta la Squadra di supporto.', '2016-01-25 08:13:12', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 44692),
	('commentsomethingwentwrong', 'nl', 'messages', 'Het spijt ons, er ging iets mis met je commentaar.  Probeer het opnieuw.  Contacteer het ondersteuningsteam als het probleem blijft bestaan.', '2015-09-16 09:33:55', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('commentsomethingwentwrong', 'pl', 'messages', 'Niestety, coś poszło nie tak z Twoim komentarzem. Spróbuj jeszcze raz. Jeśli problem nie zniknie, skontaktuj się z naszym wsparciem technicznym.', '2021-01-14 15:07:22', '2021-01-14 15:08:16', '2021-01-14 15:07:22', 'no', '', 5, NULL, 116789),
	('commentsomethingwentwrong', 'pt', 'messages', 'Desculpe, mas algo correu mal com a publicação do seu comentário. Por favor, tente novamente. Se o problema persistir, por favor contacte a equipa de suporte.', '2015-09-06 11:49:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('commentsomethingwentwrong', 'pt-BR', 'messages', 'Desculpe, alguma coisa deu errado na publicação de seu comentário. Por favor, tente novamente. Se o problema persistir, entre em contato com o suporte.', '2016-12-18 01:32:09', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160059),
	('commentsomethingwentwrong', 'sr', 'messages', 'Жао нам је, али нешто је лоше десило током објаве твог коментара. Молимо да покушаш поново. Ако проблем и даље траје, контактирај тим подршке.', '2015-10-28 23:34:18', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
