	('contactlistcategorychooseoradd', 'pt', 'messages', 'Aqui pode escolher uma categoria para esta nota. Pode escolher da lista ou escrever uma nova categoria à sua escolha. Isto ajuda a organizar as suas notas de forma eficiente.', '2013-01-06 23:29:30', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
