	('credits.jetbrains', 'pt', 'messages', '<p>A Jetbrains ofereceu-nos algumas licenças OpenSource de <a href="https://www.jetbrains.com/phpstorm">PHPStorm</a> o que facilita o desenvolvimento com PHP e symfony.</p>', '2021-10-19 12:40:15', '2021-10-19 12:40:15', '2021-10-19 12:40:15', 'no', '', 5, NULL, 38787),
	('credits.jetbrains', 'uk', 'messages', '<p>Jetbrains надав нам кілька ліцензій OpenSource для <a href="https://www.jetbrains.com/phpstorm">PHPStorm</a>, що робить розробку з PHP та symfony справжнім задоволенням.</p>', '2026-04-03 15:33:59', '2026-04-03 15:33:59', '2026-04-03 15:33:59', 'no', '', 5, NULL, 573491),
	('credits.jetbrains', 'zh-hant', 'messages', '<p>Jetbrains 為我們提供了一些 &lt;a href="https://www.jetbrains.com/phpstorm"&gt;PHPStorm&lt;/a&gt; 的開源許可證，這使得使用 PHP 和 symfony 進行開發變得很有趣。</p>', '2022-10-18 17:55:19', '2022-10-18 17:55:19', '2022-10-18 17:55:19', 'no', '', 5, NULL, 53422),
	('credits.jitsi.meet', 'ca', 'messages+intl-icu', 'Una plataforma de video conferències amb codi obert, que permeten trobades entre els voluntaris des de qualsevol part del món.', '2022-05-29 11:32:30', '2022-05-29 11:32:30', '2022-05-29 11:32:30', 'no', '', 5, NULL, 26748),
	('credits.jitsi.meet', 'el', 'messages+intl-icu', 'Μια πλατφόρμα τηλεδιάσκεψης ανοιχτού κώδικα, που επιτρέπει σε εθελοντές από κάθε μέρος του κόσμου να συναντώνται μεταξύ τους.', '2022-06-21 19:00:22', '2022-06-21 19:00:22', '2022-06-21 19:00:22', 'no', '', 5, NULL, 266502),
	('credits.jitsi.meet', 'en', 'messages+intl-icu', 'An open source videoconferencing platform, letting volunteers from every part of the world meet each other.', '2022-05-22 14:34:51', '2022-05-22 14:34:51', '2022-05-22 14:34:51', 'no', 'No description given.', 5, NULL, 1),
	('credits.jitsi.meet', 'es', 'messages+intl-icu', 'Una plataforma de código abierto para videoconferencias, permitiendo al voluntariado de diferentes partes del mundo conocerse.', '2022-07-17 16:12:51', '2022-07-17 16:12:51', '2022-07-17 16:12:51', 'no', '', 5, NULL, 25548),
	('credits.jitsi.meet', 'fr', 'messages+intl-icu', 'Une plateforme de vidéoconférence open source, pour permettre aux bénévoles du monde entier de se rencontrer.', '2022-05-22 16:06:04', '2022-05-22 16:06:04', '2022-05-22 16:06:04', 'no', '', 5, NULL, 168499),
	('credits.jitsi.meet', 'gl', 'messages+intl-icu', 'Unha plataforma de videoconferencias de código aberto, que permite reunirse ao voluntariado de calquera parte do mundo.', '2022-05-24 08:21:22', '2022-05-24 08:21:22', '2022-05-24 08:21:22', 'no', '', 5, NULL, 210880),
	('credits.jitsi.meet', 'it', 'messages+intl-icu', 'Una piattaforma per videoconferenze a sorgenti aperti, che consente ai volontari da ogni parte del mondo di incontrarsi.', '2022-05-22 21:08:01', '2022-05-22 21:08:01', '2022-05-22 21:08:01', 'no', '', 5, NULL, 160610),
	('credits.jitsi.meet', 'nl', 'messages+intl-icu', 'Een opensource videoconferentieplatform, dat het vrijwilligers van over de hele wereld mogelijk maakt elkaar te ontmoeten.', '2022-11-19 16:49:33', '2022-11-19 16:49:33', '2022-11-19 16:49:33', 'no', '', 5, NULL, 21169),
	('credits.jitsi.meet', 'pl', 'messages+intl-icu', 'Platforma do wideokonferencji oparta na wolnym oprogramowaniu, która pozwala wolontariuszom i wolontariuszkom z całego świata spotykać się.', '2023-04-14 17:10:14', '2023-04-14 17:10:14', '2023-04-14 17:10:14', 'no', '', 5, NULL, 116789),
	('credits.jitsi.meet', 'pt', 'messages+intl-icu', 'Uma plataforma open source de vídeo conferência, que permite a voluntários de todo o mundo encontrarem-se uns com os outros.', '2022-06-13 01:43:30', '2022-06-13 01:43:30', '2022-06-13 01:43:30', 'no', '', 5, NULL, 38787),
	('credits.jitsi.meet', 'uk', 'messages+intl-icu', 'Відкрита платформа для відеоконференцій, що дозволяє волонтерам з усіх куточків світу зустрічатися один з одним.', '2026-04-03 15:35:07', '2026-04-03 15:35:07', '2026-04-03 15:35:07', 'no', '', 5, NULL, 573491),
	('credits.jitsi.meet', 'zh-hans', 'messages+intl-icu', '一个开源的视频会议平台，让在世界不同角落的志愿者们得以相聚。', '2022-09-18 20:22:21', '2022-09-18 20:22:21', '2022-09-18 20:22:21', 'no', '', 5, NULL, 37722),
	('credits.jitsi.meet', 'zh-hant', 'messages+intl-icu', '一個開放源碼的視訊會議平台，允許讓來自世界各地的志工相互用視訊對談。', '2022-10-18 17:59:50', '2022-10-18 17:59:50', '2022-10-18 17:59:50', 'no', '', 5, NULL, 53422),
	('credits.osm', 'ca', 'messages', 'Sense OpenStreetMap i els seus col·laboradors, el nostre lloc web seria bastant avorrit. Confiem en la base de dades d\'ubicacions i fitxes per als mapes.', '2022-04-11 22:35:10', '2022-04-11 22:35:10', '2022-04-11 22:35:10', 'no', '', 5, NULL, 304193),
	('credits.osm', 'el', 'messages', 'Χωρίς το OpenStreetMap και τους εθελοντές του που συνεισφέρουν, ο ιστότοπός μας θα ήταν αρκετά βαρετός. Βασιζόμαστε στη βάση δεδομένων για τοποθεσίες και στα πλακίδια για τους χάρτες.', '2022-10-22 15:37:22', '2022-10-22 15:37:22', '2022-10-22 15:37:22', 'no', '', 5, NULL, 266502),
	('credits.osm', 'en', 'messages', 'Without OpenStreetMap and its contributors our website would be pretty dull. We rely on the database for locations and tiles for the maps.', '2021-10-07 19:09:10', '2021-10-07 19:09:10', '2021-10-07 19:09:10', 'no', 'No description given.', 5, NULL, 1),
	('credits.osm', 'es', 'messages', 'Sin OpenStreetMap y sus donantes, nuestra web sería mucho más aburrida. Necesitamos su base de datos para las ubicaciones y representaciones de los mapas.', '2021-11-25 14:04:12', '2022-04-02 09:17:23', '2021-11-25 14:04:12', 'no', '', 5, NULL, 48548),
	('credits.osm', 'fr', 'messages', 'Sans OpenStreetMap et ses contributeurs, notre site ne serait pas très pratique ! Nous utilisons cette base de données pour les noms de lieux et la carte.', '2022-05-22 13:28:15', '2022-05-22 13:28:15', '2022-05-22 13:28:15', 'no', '', 5, NULL, 168499),
	('credits.osm', 'gl', 'messages', 'Sen OpenStreetMap e as persoas que o fixeron á nosa páxina web sería bastante  aburrida. Confiamos na súa base de datos para as localizacións e  as pocións dos mapas.', '2021-10-28 13:38:34', '2021-10-28 13:39:42', '2021-10-28 13:38:34', 'no', '', 5, NULL, 210880),
	('credits.osm', 'it', 'messages', 'Senza OpenStreetMap e i suoi contributori il nostro sito sarebbe piuttosto monotono. Facciamo affidamento sulla loro base di dati per i luoghi e le mappe.', '2021-10-09 13:44:21', '2021-10-09 13:44:21', '2021-10-09 13:44:21', 'no', '', 5, NULL, 160610),
	('credits.osm', 'nl', 'messages', 'Zonder OpenStreetMap en zijn bijdragers zou onze website nogal saai zijn.  We vertrouwen op de gegevensbank voor locaties en tegels voor de kaarten.', '2021-11-18 19:06:32', '2021-11-18 19:06:32', '2021-11-18 19:06:32', 'no', '', 5, NULL, 21169),
	('credits.osm', 'pl', 'messages', 'Bez OpenStreetMap nasza strona byłaby marna. Polegamy na ich bazie danych dla lokalizacji i map.', '2023-04-14 16:46:42', '2023-04-14 16:46:42', '2023-04-14 16:46:42', 'no', '', 5, NULL, 116789),
	('credits.osm', 'pt', 'messages', 'Sem o OpenStreetMap e as pessoas que para ele contribuem o nosso website seria muito monótono. Confiamos nessa base de dados para locais e fragmentos de mapas.', '2021-10-17 10:46:55', '2021-10-17 10:46:55', '2021-10-17 10:46:55', 'no', '', 5, NULL, 38787),
	('credits.osm', 'ru', 'messages', 'Без OpenStreetMap и их контрибьюторов наш сайт был бы довольно скучным. Мы полагаемся на базу данных для определения местоположений и фрагментов для карт.', '2025-03-22 18:21:32', '2025-03-22 18:21:32', '2025-03-22 18:21:32', 'no', '', 5, NULL, 519603),
	('credits.osm', 'uk', 'messages', 'Без OpenStreetMap та його учасників наш веб-сайт був би досить нудним. Ми покладаємося на базу даних для місць та плиток для карт.', '2026-04-03 15:34:32', '2026-04-03 15:34:32', '2026-04-03 15:34:32', 'no', '', 5, NULL, 573491),
	('credits.osm', 'zh-hant', 'messages', '如果沒有 OpenStreetMap 和它的貢獻者，我們的網站將會非常乏味。我們依靠數據庫來獲取地圖的位置和標示。', '2022-10-18 17:54:10', '2022-10-18 17:54:10', '2022-10-18 17:54:10', 'no', '', 5, NULL, 53422),
	('credits.symfony', 'ca', 'messages', 'El marc PHP responsable de què la pàgina web funcioni meravellosament ràpida i sigui segura.', '2022-05-29 11:41:15', '2022-05-29 11:41:15', '2022-05-29 11:41:15', 'no', '', 5, NULL, 26748),
	('credits.symfony', 'de', 'messages', 'Die PHP Grundstruktur sorgt dafür, daß die Webseite superschnell und sicher ist.', '2022-10-27 19:47:32', '2022-10-27 19:47:32', '2022-10-27 19:47:32', 'no', '', 5, NULL, 29715),
	('credits.symfony', 'el', 'messages', 'Το πλαίσιο PHP που διασφαλίζει ότι ο ιστότοπος είναι απίστευτα γρήγορος και ασφαλής.', '2022-10-22 15:37:52', '2022-10-22 15:37:52', '2022-10-22 15:37:52', 'no', '', 5, NULL, 266502),
	('credits.symfony', 'en', 'messages', 'The PHP framework that makes sure the website is blazingly fast and secure.', '2021-10-07 19:09:10', '2021-10-07 19:09:10', '2021-10-07 19:09:10', 'no', 'No description given.', 5, NULL, 1),
	('credits.symfony', 'es', 'messages', 'La estructura PHP que asegura que esta web sea segura y rápida como el rayo.', '2021-11-25 14:09:06', '2021-11-25 14:09:06', '2021-11-25 14:09:06', 'no', '', 5, NULL, 25548),
	('credits.symfony', 'fr', 'messages', 'Le framework PHP qui permet à notre site d’être sûr et rapide.', '2022-05-22 13:31:57', '2022-05-22 13:31:57', '2022-05-22 13:31:57', 'no', '', 5, NULL, 168499),
	('credits.symfony', 'gl', 'messages', 'A estrutura PHP que garantiza que a páxina web sexa incribelmente rápida e segura.', '2021-10-28 13:48:50', '2021-10-28 13:48:50', '2021-10-28 13:48:50', 'no', '', 5, NULL, 210880),
	('credits.symfony', 'it', 'messages', 'Il framework PHP che rende il sito incredibilmente veloce e sicuro.', '2021-10-09 13:45:19', '2021-10-09 13:45:19', '2021-10-09 13:45:19', 'no', '', 5, NULL, 160610),
	('credits.symfony', 'nl', 'messages', 'Het PHP-framework dat ervoor zorgt dat de website flitsend snel en veilig is.', '2021-11-18 19:07:49', '2021-11-18 19:07:49', '2021-11-18 19:07:49', 'no', '', 5, NULL, 21169),
	('credits.symfony', 'pt', 'messages', 'A framework PHP que garante que o nosso website é super rápido e seguro.', '2021-10-17 10:47:22', '2021-10-17 10:47:22', '2021-10-17 10:47:22', 'no', '', 5, NULL, 38787),
