	('dashboard.notifications.none', 'es', 'messages', 'Sin notificaciones', '2020-12-04 01:16:40', '2020-12-04 01:16:40', '2020-12-04 01:16:40', 'no', '', 5, NULL, 25548),
	('dashboard.notifications.none', 'fr', 'messages', 'Pas de notifications', '2019-02-19 12:37:49', '2019-02-19 12:37:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('dashboard.notifications.none', 'gl', 'messages', 'Sen notificacións', '2021-01-28 11:52:20', '2021-01-28 11:52:20', '2021-01-28 11:52:20', 'no', '', 5, NULL, 210880),
	('dashboard.notifications.none', 'hy', 'messages', 'Ծանուցումներ չկան', '2025-06-03 05:49:57', '2025-06-03 05:49:57', '2025-06-03 05:49:57', 'no', '', 5, NULL, 519603),
