	('default_meta_description', 'ru', 'messages', 'Присоединяйтесь к BeWelcome, крупнейшему бесплатному сообществу гостеприимства. Останавливайтесь у местных, принимайте путешествующих у себя дома, знакомьтесь, заводите новых друзей по всему миру и делитесь настоящими впечатлениями от путешествий.', '2007-09-06 18:57:22', '2025-03-23 15:22:00', '0000-00-00 00:00:00', 'no', '', 5, NULL, 519603),
