	('donate_bar_annual', 'de', 'messages', '<p>Dieses Jahr wurden <strong>%s €</strong> gespendet. </p><p>Hilf uns <strong>%s €</strong> zu erreichen, um unsere Jahresausgaben zu decken.</p>', '2012-04-20 10:35:26', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('donate_bar_annual', 'el', 'messages', '<p>Φέτος<strong>%s  €</strong>έχουν δωριθεί μέχρι τώρα. </p><p>Βοήθησε μας να φτάσουμε τα 1000 ευρώ για να καλύψουμε τα ετήσια έξοδά μας!', '2012-06-29 23:52:36', '2020-09-02 08:17:39', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('donate_bar_annual', 'en', 'messages', '<p>This year <strong>%s  €</strong> have been contributed so far. </p><p>Help us to reach <strong>%s €</strong> to cover our costs for the whole year!</p>', '2012-02-24 17:14:08', '2019-04-23 18:16:49', '2012-02-24 17:14:08', 'no', '', 5, NULL, 202),
	('donate_bar_annual', 'es', 'messages', '<p>Este año las donaciones recibidas ascienden a <strong>%s €</strong>.</p> <p>Ayúdanos a alcanzar los <strong>%s €</strong> para cubrir nuestros gastos anuales!</p>', '2012-02-29 19:47:32', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 554),
	('donate_bar_annual', 'eu', 'messages', '<p>Aurten <strong>%s €</strong> eman dira gogo onez. </p><p>Lagun gaitzazu <strong>%s €</strong> lortzen, gure gastuak urte oso baten zehar estaltzeko!</p>', '2012-11-21 16:58:26', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11907),
	('donate_bar_annual', 'fr', 'messages', '<p><strong>%s €</strong> ont été donnés par les membres à BeWelcome jusqu’à maintenant.</p> <p>Aidez-nous à atteindre l’objectif de <strong>%s €</strong> pour couvrir les frais annuels d’utilisation du site&nbsp;!</p>', '2012-02-29 18:45:57', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 9823),
	('donate_bar_annual', 'gl', 'messages', '<p>Este ano <strong>%s  €</strong> foron doados ata o momento. </p><p>Axúdanos a alcanzar <strong>%s €</strong> para cubrir o nosos custos para todo o ano!</p>', '2021-03-11 17:32:13', '2021-03-11 17:32:13', '2021-03-11 17:32:13', 'no', '', 5, NULL, 210880),
	('donate_bar_annual', 'hr', 'messages', '<p>Do sada je prikupljeno <strong>%s €</strong> ove godine.</p> <p>Pomozi nam dostići <strong>%s €</strong> potrebnih za pokrivanje godišnjih troškova!</p>', '2012-09-19 15:42:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 24014),
	('donate_bar_annual', 'hu', 'messages', '<p>Ebben az évben <strong>%s €</strong>adományt kaptunk ami kevés. </p><p>Segíts hogy elérjük az <strong>%s €</strong>, hogy fedezzhessük az éves kiadásainkat!</p>', '2012-09-21 22:13:55', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34314),
	('donate_bar_annual', 'it', 'messages', '<p>Quest\'anno sono stati donati <strong>%s €</strong>. </p><p>Aiutaci a raggiungere <strong>%s €</strong>per coprire i costi per tutto l\'anno!</p>', '2013-01-15 18:27:34', '2021-02-28 19:21:44', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160610),
	('donate_bar_annual', 'nl', 'messages', '<p>Dit jaar werd er <strong>%s €</strong> gecontribueerd.</p> <p>Help ons om <strong>%s €</strong> te halen, om onze kosten voor het hele jaar te dekken!</p>', '2012-02-29 20:48:36', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('donate_bar_annual', 'pl', 'messages', '<p> W tym roku zebraliśmy jak dotąd <strong>%s €</strong>. </p><p>Pomóż nam osiągnąć <strong>%s €</strong>, aby pokryć nasze całoroczne wydatki!</p>', '2012-05-17 23:36:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 392),
	('donate_bar_annual', 'pt', 'messages', '<p>Este ano já angariámos <strong>%s €</strong>.</p><p>Ajude-nos a atingir a meta de <strong>%s €</strong> para cobrir os custos para o ano inteiro!</p> ', '2012-12-09 08:59:21', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('donate_bar_annual', 'pt-BR', 'messages', '<p>Neste ano contribuíram com <strong>%s €</strong> até o momento. </p><p>Nos ajude a alcançar <strong>%s €</strong> para cobrir nossos gastos pelo ano inteiro!</p>', '2012-05-18 06:39:44', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15566),
	('donate_bar_annual', 'ru', 'messages', 'В данном году было пожертвовано <strong>%s €</strong>. Помогите нам достичь суммы в strong>%s €</strong>, чтобы покрыть наши расходы на весь год!', '2014-05-16 18:41:55', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('donate_bar_annual', 'sr', 'messages', '<p>Ове године је до сад прикупљено <strong>%s €</strong>. </p><p>Помозите нам да сакупимо <strong>%s €</strong> за покривање трошкова за целу годину!</p>', '2015-01-24 13:52:47', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('donate_bar_annual', 'tr', 'messages', '<p>Bu yıl  şimdiye kadar <strong>%s â�¬</strong> katkı sağlanmıştır. </p><p> Bize  <strong>%s â�¬</strong> hedefine giderlerimizi karşılamak için hedefimize ulaşmamıza  yardım edin!</p>\r\n', '2012-05-25 19:57:53', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 95),
	('donate_bar_annual', 'zh-hans', 'messages', '<p>今年已筹集得了 <strong>%s € </strong>的捐助.</p><p>请略尽绵力, 帮我们筹集够今年所需的 <strong>%s € </strong> 营运成本吧! </p> \r\n', '2013-02-11 16:01:38', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37722),
	('donate_bar_annual', 'zh-hant', 'messages', '<p>今年已筹集得了 <strong>%s € </strong>的捐助.</p><p>请略尽绵力, 帮我们筹集够今年所需的 <strong>%s € </strong> 营运成本吧! </p> \r\n', '2013-02-11 16:01:38', '2021-05-02 07:48:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37722),
	('donate_bar_annual_2013', 'ar', 'messages', 'تم التبرع بــ <strong>&euro; %s</strong> حتى الآن.\r\nشكراً لمساعدتنا للوصول إلى ساعدنا للوصول إلى <strong>&euro; %s</strong> لتغطية التكاليف لعام 2018/2019!', '2013-10-31 20:54:38', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 69),
	('donate_bar_annual_2013', 'cs', 'messages', 'V této kampani bylo zatím přispěno <strong>%s €</strong>.\r\n\r\nPomož nám dosáhnout <strong>&euro; %s</strong> pro pokrytí výdajů za rok 2018/2019! ', '2014-01-09 18:37:37', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 69),
	('donate_bar_annual_2013', 'de', 'messages', 'Bisher wurden <b>%s €</b> gespendet. \r\n\r\nHilf uns, das Spendenziel von <b>%s €</b> zu erreichen, um unsere Kosten für 2018/2019 zu decken.', '2012-11-25 21:59:22', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '<p>This term <strong>%s  €</strong> have been contributed so far. </p><p>Help us to reach <strong>%s €</strong> to cover our costs for 2012-2013! </p>', 5, NULL, 69),
	('donate_bar_annual_2013', 'el', 'messages', 'Από τότε που ξεκίνησε αυτή η καμπάνια, λάβαμε <strong>&euro;&nbsp;%s</strong> ως δωρεές.\r\n\r\nΕυχαριστούμε για τη βοήθειά σας να φτάσουμε τα  <strong>&euro;&nbsp;%s</strong> ώστε να καλύψουμε τα έξοδά μας για το 2018/2019!', '2014-02-04 14:53:02', '2020-09-02 12:23:33', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('donate_bar_annual_2013', 'en', 'messages', 'Since the beginning of this campaign, we received <strong>&euro; %s</strong> as donations.\r\n\r\nThank you for helping us to reach the goal of <strong>&euro; %s</strong> in order to cover our expenses for 2018/2019!', '2012-11-20 16:13:46', '2019-12-26 09:49:40', '2015-11-25 20:08:45', 'no', 'this text appears by the donation bar and shows how much money has been received and how much is needed for the current donation campaign using %s as a reference for those values', 5, NULL, 69),
	('donate_bar_annual_2013', 'eo', 'messages', 'En tiu ĉi periodo <b>€ %s</b> estis ĝis nun donacitaj.\r\n\r\nHelpu atingi <b>€ %s</b> por kovri niajn elspezojn en 2018-2019.', '2014-06-10 15:28:09', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 69),
	('donate_bar_annual_2013', 'es', 'messages', 'Hemos recaudado <b>%s €</b> en esta campaña de donaciones.\r\n\r\nPor favor considera ayudarnos para alcanzar el objetivo de <b>%s €</b> para cubrir los costos de 2018/2019.', '2012-12-14 15:13:59', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 69),
	('donate_bar_annual_2013', 'fa', 'messages', 'یورو در قالب همیاری مالی دریافت کردیم %s از آغاز این کارزار ما مبلغ \r\n\r\nیورو برای پوشش هزینه‌های ۲۰۱۵مان برسیم %s لطفن ما را یاری کنید تا به سقف ', '2014-01-08 00:38:44', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 41992),
	('donate_bar_annual_2013', 'fi', 'messages', 'Tällä kaudella on tähän mennessä lahjoitettu <b>%s€</b>.\r\n\r\nAuta meitä saavuttamaan <b>%s€</b>, jolla katamma kulut kaudelle 2018-2019.', '2014-01-10 11:52:56', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 69),
	('donate_bar_annual_2013', 'fr', 'messages', 'Depuis le début de cette campagne, il y a eu <b>%s&nbsp;€</b> de dons.\r\n\r\nAidez-nous à atteindre les <b>%s&nbsp;€</b> nécessaires pour couvrir nos dépenses de 2018/2019&nbsp;!', '2014-01-10 17:03:08', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 69),
	('donate_bar_annual_2013', 'gl', 'messages', 'Dende o comezo desta campaña, recibimos <strong>&euro; %s</strong> como doazóns.\r\n\r\nGrazas por axudarnos a alcanzar o obxectivo de  <strong>&euro; %s</strong> para cubrir nosos gastos!', '2021-03-10 11:21:33', '2021-03-10 11:21:33', '2021-03-10 11:21:33', 'no', '', 5, NULL, 210880),
	('donate_bar_annual_2013', 'hr', 'messages', 'Od početka kampanje, primili smo <strong>&eura; %s</strong> kroz donacije.\r\n\r\nHvala vam na pomoći da prikupimo   <strong> %s eura</strong>  i pokrijemo troškove za 2018/2019!', '2014-04-14 11:24:47', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 69),
	('donate_bar_annual_2013', 'hu', 'messages', 'A kampány kezdete óta <strong>&euro; %s</strong> támogatás érkezett.\r\n\r\nKöszönjük, hogy segítetek elérni a  <strong>&euro; %s</strong>-es célt, ami fedezi a 2018/2019-as évi költségeket!', '2017-10-21 13:34:49', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 69),
	('donate_bar_annual_2013', 'hy', 'messages', 'Այս քարոզարշավի սկզբից մինչև այժմ մենք արդեն ստացել ենք <strong>&euro; %s</strong> ֆինանսական աջակցություն:\r\n\r\nԽնդրում ենք օգնեք մեզ հատել <strong>&euro; %s</strong> շեմը՝ մեր 2018/2019 թվականի ծախսերը հոգալու համար:\r\n\r\n', '2015-03-14 11:50:25', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 69),
	('donate_bar_annual_2013', 'it', 'messages', 'Dall\'inizio di questa campagna, abbiamo ricevuto <strong>%s &euro;</strong> di donazioni. \r\n\r\nGrazie per averci aiutato a raggiungere l\'obiettivo di <strong>%s &euro;</strong> per coprire le nostre spese per il 2018/2019!', '2014-01-14 23:04:14', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 13993),
	('donate_bar_annual_2013', 'ku', 'messages', 'Di vê demê de <b>%s €</b> me komkir.\r\nAlîkarîya me bike ku em bi <b>%s €</b> gînin, ji sala 2018-2019 re!', '2014-04-14 10:27:33', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 69),
	('donate_bar_annual_2013', 'nl', 'messages', 'Sinds het begin van deze campagne hebben we <strong>&euro; %s</strong> aan schenkingen ontvangen.\r\n\r\nBedankt om te helpen het doel van <strong>&euro; %s</strong> bij elkaar te krijgen om onze kosten voor 2018–19 te dekken!\r\n', '2014-01-08 22:31:19', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 69),
	('donate_bar_annual_2013', 'pl', 'messages', 'W tym okresie darowizny wynoszą już <b>%s €</b>.\r\nPomóż nam dotrzeć do <b>%s €</b> aby pokryć koszty na 2018/19.', '2014-05-04 14:57:46', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37896),
	('donate_bar_annual_2013', 'pt', 'messages', 'Desde o início desta campanha recebemos <strong>&euro; %s</strong> em donativos.\r\n\r\nObrigado por nos ajudar a atingir o objetivo de <strong>&euro; %s</strong> para cobrir as nossas despesas em 2018/2019!', '2014-01-02 21:45:26', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('donate_bar_annual_2013', 'pt-BR', 'messages', 'Desde o início desta campanha, recebemos <strong>&euro; %s</strong> em doações. \r\n\r\nObrigado por nos ajudar a alcançar a meta de <strong>&euro; %s</strong> para cobrir nossos gastos para 2018/2019!', '2014-02-19 17:33:17', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 69),
	('donate_bar_annual_2013', 'ru', 'messages', 'С начала этой кампании мы получили <strong>&euro; %s</strong> в качестве пожертвований.\r\nСпасибо за вашу помощь в достижении нашей цели  - суммы в <strong>&euro; %s</strong> на покрытие наших затрат на 2018/2019 годы. ', '2014-03-30 17:31:56', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('donate_bar_annual_2013', 'sl', 'messages', 'Od začetka te akcije smo uspeli zbrati <strong>%s &euro;</strong> donacij. \r\n\r\nHvala za vašo pomoč pri doseganju cilja <strong>%s &euro;</strong> z namenom pokritja naših stroškov v sezoni 2018/2019!', '2019-03-21 21:33:46', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 106553),
	('donate_bar_annual_2013', 'sr', 'messages', 'Од почетка кампање, прикупили смо <strong>%s &euro;</strong> донација.\r\n\r\nЗахваљујемо вам се на помоћи да прикупимо <strong>%s &euro;</strong> да би смо покрили трошкове за 2018/2019!', '2012-12-19 10:02:17', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('donate_bar_annual_2013', 'sv', 'messages', 'Sedan början av kampanjen har vi fått <strong>&euro; %s</strong> i donationer.\r\n\r\nTack för att du hjälper oss att nå vårt mål <strong>&euro; %s</strong> att täcka våra utgifter för 2016/2017!', '2016-02-27 15:23:34', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('donate_bar_annual_2013', 'tr', 'messages', 'Başlangıçtan beri <b>%s €</b> kadar bağış aldık.\r\n2017/2018 döneminde masraflarımızı karşılamak amacıyla <b>%s €</b> hedefine ulaşmaya yardım ettiğiniz için teşekkür ederiz.!', '2014-01-09 12:45:59', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 35699),
	('donate_bar_annual_2013', 'zh-hans', 'messages', '本活动开始至今, 我们已收到 <strong>&euro; %s</strong> 的捐助.  \r\n众志成城, 请帮我们筹得2018/2019年度的 <strong>&euro; %s</strong> 营运成本吧! ', '2014-01-16 12:00:35', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37722),
