	('donate_donationneeded', 'tr', 'messages', 'Bağıs İçin 2017/2018', '2008-07-23 17:40:19', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 35699),
	('donate_donationneeded', 'zh-hans', 'messages', '2018/2019 年度筹款活动', '2010-09-09 11:09:24', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37722),
	('donate_donationneeded', 'zh-hant', 'messages', '我們需要資助！', '2010-09-09 11:09:24', '2021-05-02 07:48:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 68078),
	('donate_donetext', 'ca', 'messages', 'Gràcies per la donació!<br><br>Comprova si la pots veure a <a href="https://www.bewelcome.org/donate/list">Donacions recents</a>; si no, espera una estona, ja que hem d\'actualitzar la pàgina manualment.', '2008-05-29 07:52:56', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('donate_donetext', 'da', 'messages', 'Tak for din donation! Hvis du er interesseret kan du <a href="https://www.bewelcome.org/donate/list">tjekke listen med donationer</a> - din donation er allerede på (hvis du ikke kan finde den, så prøv igen lidt senere).', '2009-05-16 08:30:46', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 74),
	('donate_donetext', 'de', 'messages', 'Danke für deine Spende !\r\n\r\nSchaue doch gleich mal unter <a href="https://www.bewelcome.org/donate/list">Recent Spenden</a> nach, ob du sie sehen kannst. Falls nicht, warte einen Moment uns schaue später noch einmal vorbei. Manche Transaktionen müssen wir auch manuell aktualisieren.', '2008-06-03 09:44:07', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3050),
	('donate_donetext', 'el', 'messages', 'Ευχαριστούμε για τη δωρεά! Εάν θέλεις ρίξε μια ματιά αν εμφανίζεται ήδη στη λίστα με τις <a href="https://www.bewelcome.org/donate/list">τελευταίες δωρεές</a>. Εάν όχι, μην ανησυχείς, ξαναδές το πιο μετά!', '2013-01-24 22:50:33', '2020-09-02 09:14:00', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('donate_donetext', 'en', 'messages', 'Thanks for your donation! You can have a look if it already shows in our list of <a href="https://www.bewelcome.org/donate/list">recent donations</a>. If not, don\'t worry and check back soon!', '2008-05-26 21:18:36', '2020-06-06 12:35:15', '2008-09-04 09:34:21', 'no', 'This is the text display after a donation', 5, NULL, 91),
	('donate_donetext', 'eo', 'messages', 'Dankon pro ia donaco! Se vi volas, vi povas kontroli ĉu via doanco jam eperis en <a href="https://www.bewelcome.org/donate/list">la listo de lastaj donacoj</a>. Se ankoraŭ ne, ne ĉagreniĝu kaj kontrolu poste.', '2013-03-15 07:05:34', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 47220),
	('donate_donetext', 'es', 'messages', '<p>¡Gracias por tu donación! Puedes mirar si apareces en nuestra lista de <a href="https://www.bewelcome.org/donate/list">Donaciones Recientes</a>. Si no es así, no te preocupes y revisa pasado un tiempo.</p>', '2008-05-27 11:43:38', '2023-06-18 14:44:31', '0000-00-00 00:00:00', 'no', '', 5, NULL, 25548),
	('donate_donetext', 'fi', 'messages', 'Kiitos lahjoituksesta! Jos haluat katsoa, lahjoituksesi pitäisi näkyä jo <a href="https://www.bewelcome.org/donate/list">viimeisimmissä lahjoituksissa</a>. Jos ei, älä huoli vaan tarkasta myöhemmin uudestaan!', '2009-05-18 21:50:15', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 72),
	('donate_donetext', 'fr', 'messages', 'Merci pour votre contribution !\r\n\r\nVérifiez si celle-ci apparaît dans la <a href="http://www.bewelcome.org/donate/list">liste des contributeurs récents</a>. Il faut parfois attendre un peu quand nous devons faire une mise à jour manuelle. Sinon, pas d’inquiétude, revenez bientôt et tout sera en ordre.', '2008-05-26 21:20:28', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('donate_donetext', 'gl', 'messages', '<p>Grazas pola túa doazón! Podes mirar se xa se amosa na nosa lista de <a href="https://www.bewelcome.org/donate/list">doazóns recentes</a>. Senón, non te preocupes e verifícalo de novo máis tarde!</p>', '2021-12-27 09:11:53', '2021-12-27 09:11:53', '2021-12-27 09:11:53', 'no', '', 5, NULL, 210880),
	('donate_donetext', 'it', 'messages', 'Grazie per la tua donazione!\r\n\r\nControlla se la vedi sotto le <a href="https://www.bewelcome.org/donate/list">donazioni recenti</a>. Se non è visibile, non ti preoccupare e ricontrolla tra un po\'!', '2008-06-01 12:11:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('donate_donetext', 'lt', 'messages', 'Dėkojame už tavo paramą! Gali dabar žvilgtelti į <a href="https://www.bewelcome.org/donate/list">Paskutinių aukų</a> sąrašą, kur žinutė apie tavo įmoką turi pasirodyti netrukus.', '2009-09-03 01:12:02', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('donate_donetext', 'nl', 'messages', '<p>Bedankt voor je donatie! &nbsp;Als je wil, kan je kijken of deze al in onze lijst met <a href="https://www.bewelcome.org/donate/list">recente donaties</a> staat. &nbsp;Zo niet, geen zorgen; kijk binnenkort nog eens!</p>', '2014-01-11 11:20:23', '2026-03-10 14:23:33', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('donate_donetext', 'pl', 'messages', 'Dziękujemy za Twoją wpłatę! Możesz zajrzeć, czy jest już widoczna na naszej liście <a href="https://www.bewelcome.org/donate/list">ostatnich wpłat</a>. Jeśli nie, nie martw się i sprawdź raz jeszcze wkrótce!', '2021-01-12 23:55:23', '2021-01-12 23:55:23', '2021-01-12 23:55:23', 'no', '', 5, NULL, 116789),
	('donate_donetext', 'pt', 'messages', 'Obrigado pela doação! Se quiser, dê uma vista de olhos à nossa lista de<a href="https://www.bewelcome.org/donate/list"> doações recentes</a>. Se o seu nome ainda não se encontra lá, não se preocupe e verifique novamente em breve!', '2013-01-16 20:14:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('donate_donetext', 'pt-BR', 'messages', 'Obrigado pela sua doação! Se você quiser, dê uma olhada se já consta na nossa lista de  <a href="https://www.bewelcome.org/donate/list">doações recentes</a>. Se não, não se preocupe e confira de novo daqui a pouco!', '2014-02-19 23:56:13', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15566),
	('donate_donetext', 'ru', 'messages', 'Спасибо за Ваше пожертвование! Если есть желание, то можно увидеть его в списке <a href="https://www.bewelcome.org/donate/list">последних пожертвований</a>. Если его там нет, не беспокойтесь и проверьте через пару минут!', '2014-05-18 19:20:11', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('donate_donetext', 'sr', 'messages', 'Хвала за донацију! Ако желиш, погледај да ли је у списаку <a href="https://www.bewelcome.org/donate/list">скорашњих донација</a>. Ако није, без бриге, можеш проверити касније!', '2015-02-19 09:13:05', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('donate_furtherinfo', 'ar', 'messages', 'أسئلة أخرى؟', '2014-04-11 09:45:26', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48359),
