	('donatelist', 'zh-hant', 'messages', '近期捐款', '2010-10-14 23:26:19', '2021-05-02 07:48:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11819),
	('donatethanks', 'ca', 'messages', 'T\'agraïm moltíssim la donació!<br>I, sobretot, esperem que gaudeixis utilitzant el lloc web BeWelcome, gestionat completament per voluntaris no remunerats.', '2008-03-03 14:23:42', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('donatethanks', 'de', 'messages', 'Vielen Dank für deine Spende!\r\nWir wünschen uns sehr, dass du dich auf unseren Seiten wohl fühlst. Sie wird ausschließlich von ehrenamtlichen, freiwilligen Helfern betrieben.', '2007-11-28 17:58:42', '2008-12-04 08:29:48', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3050),
	('donatethanks', 'el', 'messages', 'Ευχαριστούμε για τη δωρεά.\r\nΜα πάνω απ\'όλα ευχόμαστε να απολαύσεις την ιστοσελίδα του BeWelcome του οποίου η διαχείριση στηρίζεται σε ελεύθερους, άμισθους εθελοντές.', '2020-08-16 18:54:06', '2020-08-16 18:54:06', '2020-08-16 18:54:06', 'no', '', 5, NULL, 266544),
	('donatethanks', 'en', 'messages', 'We thank you for this donation!\r\nMost of all we hope you will greatly enjoy using the BeWelcome website which is completely managed by free, unpaid volunteers.', '2007-11-25 18:27:11', '2008-03-29 16:02:12', '2008-03-29 16:02:12', 'no', 'This is the thank you message the user receive when he has donated', 5, NULL, 97),
	('donatethanks', 'es', 'messages', '¡Te agradecemos tu donación!\r\nEsperamos que saques provecho y le des un buen uso a BeWelcome, que es administrado por voluntarios no pagados', '2008-01-02 16:40:30', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1328),
	('donatethanks', 'fr', 'messages', 'Nous vous remercions pour ce don&nbsp;!\r\nNous espérons avant tout que l\'utilisation du site BeWelcome, géré uniquement par des volontaires bénévoles, continuera à vous satisfaire.\r\n', '2007-11-27 17:44:38', '2017-01-24 14:04:35', '0000-00-00 00:00:00', 'no', '', 5, NULL, 32568),
	('donatethanks', 'gl', 'messages', 'Agradecemos a túa doazón!\r\nSobre todo agardamos que goces moito usando a páxina web de BeWelcome que é xestionada completamente por persoas voluntarias de xeito gratuíto.', '2022-02-14 15:35:46', '2022-02-14 15:35:46', '2022-02-14 15:35:46', 'no', '', 5, NULL, 210880),
	('donatethanks', 'it', 'messages', 'Ti ringraziamo per questa donazione! Ma specialmente speriamo che di divertirai usando il sito di BeWelcome, che è amministrato completamente da volontari non pagati.', '2007-12-29 15:21:32', '2008-06-12 12:40:11', '0000-00-00 00:00:00', 'no', '', 5, NULL, 103),
	('donatethanks', 'lt', 'messages', 'Ačiū už jūsų įnašą!\r\nMes tikimės, kad jums bus nemažai naudos iš naudojimąsi BeWelcome svetaine, kuri yra pilnai tvarkoma atsidavusiais svetingumo idėjai savanoriais.\r\n', '2007-12-17 04:34:50', '2007-12-17 04:36:52', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('donatethanks', 'nl', 'messages', 'Dank je voor je donatie!\r\nWe hopen van harte dat je geniet van de website van BeWelcome. Ze wordt volledig door onbetaalde vrijwilligers draaiend gehouden.', '2008-06-25 19:52:37', '2013-03-18 16:35:29', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40169),
	('donatethanks', 'pl', 'messages', 'Dziękujemy za tę darowiznę!\r\nPrzede wszystkim mamy nadzieję, że spodoba ci się korzystanie z witryny BeWelcome, która jest całkowicie zarządzana przez wolontariuszy.', '2020-06-22 12:32:28', '2020-06-22 12:32:28', '2020-06-22 12:32:28', 'no', '', 5, NULL, 37896),
	('donatethanks', 'pt', 'messages', 'Agradecemos-te por esta doação! \r\nAcima de tudo esperamos que aproveites ao melhor o BeWelcome website que é totalmente operado gratuitamente por voluntários.  ', '2013-01-16 19:54:43', '2013-01-16 19:54:43', '0000-00-00 00:00:00', 'no', '', 5, NULL, 36712),
	('donatethanks', 'ru', 'messages', 'Спасибо Вам за Ваше пожертвование!\r\nИ больше всего мы надеемся, что Вы получаете большое удовольствие, пользуясь сайтом BeWelcome, который администрируется волонтерами-добровольцами.', '2014-05-23 16:44:01', '2014-05-23 16:44:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('donatethanks', 'sr', 'messages', 'Захвални смо ти на донацији! \r\nНадамо се да ћеш уживати у коришћењу BeWelcome сајта, којег у потпуности покрећу добровољци.', '2015-02-11 21:18:07', '2015-02-11 21:18:07', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('donatetobewelcome', 'ca', 'messages', 'Donacions per al projecte BeWelcome', '2007-10-20 17:44:29', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, NULL, 177),
