	('donation.needed', 'pt', 'messages', 'Donativos necessários', '2020-05-23 15:04:27', '2020-05-23 15:04:27', '2020-05-23 15:04:27', 'no', '', 5, NULL, 38787),
	('donation.needed', 'vi', 'messages', 'Sự ủng hộ cần thiết', '2021-09-09 08:11:16', '2021-09-09 08:11:16', '2021-09-09 08:11:16', 'no', '', 5, NULL, 293926),
	('donation.needed', 'zh-hans', 'messages', '所需捐赠', '2022-05-12 03:05:58', '2022-05-12 03:05:58', '2022-05-12 03:05:58', 'no', '', 5, NULL, 329622),
	('donation.needed', 'zh-hant', 'messages', '捐款目標', '2020-06-22 17:56:11', '2021-05-02 07:48:37', '2020-06-22 17:56:11', 'no', '', 5, NULL, 53422),
	('donation.thank.you', 'ca', 'messages+intl-icu', 'Ja hem aconseguit l\'objectiu de {amount} anual. Qualsevol donació addicional, però, serà més que benvinguda.', '2021-10-04 21:07:56', '2021-10-04 21:07:56', '2021-10-04 21:07:56', 'no', '', 5, NULL, 304193),
	('donation.thank.you', 'de', 'messages+intl-icu', 'Wir haben unser jährliches Spendenziel von {amount} erreicht. Alle zusätzlichen Spenden sind natürlich mehr als willkommen.', '2020-06-05 21:55:23', '2020-06-13 19:48:47', '2020-06-05 21:55:23', 'no', '', 5, NULL, 111),
	('donation.thank.you', 'el', 'messages+intl-icu', '<p>Έχουμε φτάσει τον ετήσιο στόχο δωρεών των {amount}. Εξακολουθούμε να δεχόμαστε δωρεές, αλλά μπορείτε επίσης να εξετάσετε το ενδεχόμενο να υποστηρίξετε ένα από τα<a href="https://www.bewelcome.org/about/credits"> δωρεάν λογισμικό που χρησιμοποιούμε</a> για να συνεχίσει να λειτουργεί ο ιστότοπός μας!</p>', '2020-07-24 09:15:19', '2024-07-09 06:13:33', '2020-07-24 09:15:19', 'no', '', 5, NULL, 266502),
	('donation.thank.you', 'en', 'messages+intl-icu', '<p>We have reached our yearly donation goal of {amount}. We still accept donations, but you may also consider supporting one of <a href="https://www.bewelcome.org/about/credits">the free software we’re using</a> to keep our site running!</p>', '2020-05-22 14:18:33', '2022-12-12 15:42:55', '2022-05-22 16:33:50', 'no', 'Shown on the landing page after the donation goal is reached. Make sure to include the {amount} in the text.', 5, 0, 21169),
	('donation.thank.you', 'es', 'messages+intl-icu', '<p>Hemos alcanzado nuestro objetivo anual de donaciones de {amount}. Seguimos aceptando donaciones, pero quizás quieras considerar también apoyar al <a href="https://www.bewelcome.org/about/credits">software libre que usamos</a> para mantener nuestra web.</p>', '2020-11-30 13:59:59', '2023-05-29 10:53:07', '2020-11-30 13:59:59', 'no', '', 5, NULL, 25548),
	('donation.thank.you', 'fr', 'messages+intl-icu', '<p>Nous avons atteint notre objectif annuel de {amount}. Nous acceptons encore les dons, mais vous pouvez aussi soutenir <a href="https://www.bewelcome.org/about/credits">l’un des logiciels libres que nous utilisons</a> pour faire tourner le site !</p>', '2020-05-24 11:18:12', '2023-12-30 10:59:43', '2020-05-24 11:18:12', 'no', '', 5, NULL, 168499),
	('donation.thank.you', 'gl', 'messages+intl-icu', '<p>Alcanzamos o noso obxectivo de doazóns anuais de {amount}. Aínda aceptamos doazóns, mais tamén podes tomar en consideración o apoio &nbsp;<a href="https://www.bewelcome.org/about/credits">ao software libre que estamos usando </a>para manter a nosa web funcionando!</p>', '2021-01-21 17:56:07', '2023-12-29 08:52:00', '2021-01-21 17:56:07', 'no', '', 5, NULL, 210880),
	('donation.thank.you', 'he', 'messages+intl-icu', 'הגענו ליעד השנתי של תרומות בסך {amount}. כל תרומה נוספת כמובן מבורכת.', '2022-03-24 14:06:38', '2022-03-24 14:06:38', '2022-03-24 14:06:38', 'no', '', 5, NULL, 290109),
	('donation.thank.you', 'hu', 'messages+intl-icu', 'Elértük az idén szükséges összeget, {amount}-t. Amennyiben szeretnél ezen felül hozzájárulni kitűzött céljaink eléréséhez, hálásan köszönjük támogatásodat!', '2020-05-25 09:58:50', '2020-05-25 19:04:05', '2020-05-25 09:58:50', 'no', '', 5, NULL, 36939),
	('donation.thank.you', 'it', 'messages+intl-icu', '<p>&lt;p&gt;Abbiamo raggiunto il nostro obiettivo annuale di donazioni, ammontante a {amount}. Accettiamo ancora donazioni, ma potremmo valutare di supportare uno dei <a href="https://www.bewelcome.org/about/credits">software gratuiti</a> che usiamo per far funzionare il nostro sito!&lt;/p&gt;</p>', '2020-05-25 19:52:25', '2022-06-06 21:55:52', '2020-05-25 19:52:25', 'no', '', 5, NULL, 160610),
	('donation.thank.you', 'lt', 'messages+intl-icu', 'Pasiekėme savo metinį {amount} piniginių aukų tikslą! Kas be ko, visos papildomos aukos vis dar labai laukiamos.', '2021-03-25 16:16:19', '2021-03-25 16:16:19', '2021-03-25 16:16:19', 'no', '', 5, NULL, 285578),
	('donation.thank.you', 'nl', 'messages+intl-icu', '<p>We hebben ons jaarlijks giftendoel van {amount} bereikt. &nbsp;Bijkomende giften zijn nog steeds welkom, maar je kan ook overwegen om één van de <a href="https://www.bewelcome.org/about/credits">vrijesoftware-projecten die we gebruiken</a> om onze site te doen draaien te ondersteunen!</p>', '2020-06-08 18:25:44', '2023-10-01 13:00:00', '2020-06-08 18:25:44', 'no', '', 5, NULL, 21169),
	('donation.thank.you', 'pl', 'messages+intl-icu', 'Osiągnęliśmy nasz roczny cel {amount}. Dodatkowe darowizny są oczywiście mile widziane.', '2020-06-01 17:00:58', '2020-06-01 17:00:58', '2020-06-01 17:00:58', 'no', '', 5, NULL, 37896),
	('donation.thank.you', 'pt', 'messages+intl-icu', '<p>Atingimos o nosso objetivo anual de donativos de {amount}. Continuamos a aceitar donativos mas talvez queira também suportar algum do <a href="https://www.bewelcome.org/about/credits">software livre que usamos</a> para manter o nosso website a funcionar!</p>', '2020-05-23 15:06:54', '2022-06-13 02:14:42', '2020-05-23 15:06:54', 'no', '', 5, NULL, 38787),
	('donation.thank.you', 'ru', 'messages+intl-icu', '<p>Целевая сумма за год {amount} набрана. Но мы будем очень благодарны если вы хотите пополнить её.</p>', '2020-06-04 20:46:33', '2023-06-05 10:46:20', '2020-06-04 20:46:33', 'no', '', 5, NULL, 134997),
	('donation.thank.you', 'vi', 'messages+intl-icu', 'Chúng mình đã đạt được mục tiêu trong năm với {amount}. Bất kỳ khoảng ủng hộ bổ sung nào tất nhiên vẫn rất được đánh giá cao.', '2021-09-09 08:16:17', '2021-09-09 08:16:17', '2021-09-09 08:16:17', 'no', '', 5, NULL, 293926),
	('donation.thank.you', 'zh-hant', 'messages+intl-icu', '我們已經達到了年度捐贈目標{amount}。 任何額外的捐贈當然都非常受歡迎。', '2020-06-22 18:08:19', '2021-05-02 07:48:37', '2020-06-22 18:08:19', 'no', '', 5, NULL, 53422),
	('donationcancelled', 'ar', 'messages', 'تم احباط عملية التبرع', '2008-02-15 07:32:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 2702),
