	('donationcancelled', 'sr', 'messages', 'Донација поништена', '2013-01-14 13:00:12', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 39772),
	('donationpubliclistsummary', 'da', 'messages', 'Nylige donationer sorteret efter dato, beløb og land (personlige detaljer vises kun hvis de eksplicit bedes om)', '2008-10-11 12:13:08', '2023-09-19 18:11:33', '0000-00-00 00:00:00', 'no', '', 5, NULL, 74),
	('donationpubliclistsummary', 'de', 'messages', 'Die letzten Spenden mit Datum, Betrag und Land (Persönliche Informationen werden nur angezeigt, wenn der Spender es ausdrücklich wünscht.):', '2008-05-26 13:48:56', '2023-09-19 18:11:33', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('donationpubliclistsummary', 'el', 'messages', 'Πρόσφατες δωρεές ανά ημερομηνία, ποσό και χώρα (τα προσωπικά στοιχεία δεν εμφανίζονται εκτός εάν ζητηθεί ρητά).\r\nΟι δωρεές δεν ενημερώνονται σε πραγματικό χρόνο. Μην ανησυχείτε αν δεν τις βλέπετε αμέσως.', '2022-06-23 20:41:34', '2023-05-13 16:34:45', '2022-06-23 20:41:34', 'no', '', 5, NULL, 266502),
	('donationpubliclistsummary', 'en', 'messages', 'Recent donations by date, amount and country (personal details are not shown unless explicitly asked for).\r\nThe donations are not updated in real-time. Do not worry if you do not see them immediately.', '2007-10-29 21:25:30', '2022-12-18 08:18:41', '2022-12-18 08:18:41', 'no', 'This is the text above the list showing recent donations', 5, 0, 69),
	('donationpubliclistsummary', 'eo', 'messages', 'Lastaj donacoj laux dato, monkvanto kaj lando (personaj detaloj ne montrigxas se oni ne petas):', '2009-01-23 05:11:58', '2023-09-19 18:11:33', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1769),
	('donationpubliclistsummary', 'es', 'messages', 'Donaciones recientes según fecha, cantidad y país (los detalles personales no se muestran, salvo que se solicite explícitamente).\r\nLas donaciones no se actualizan en tiempo real. No te preocupes si no las ves reflejadas inmediatamente.', '2020-12-02 03:20:29', '2023-05-23 10:06:42', '2020-12-02 03:20:29', 'no', '', 5, NULL, 25548),
	('donationpubliclistsummary', 'fi', 'messages', 'Päiväys, summa ja maa viimeisimmistä lahjoituksista (henkilötietoja ei näytetä kuin erillisestä pyynnöstä)', '2009-05-18 21:29:13', '2023-09-19 18:11:33', '0000-00-00 00:00:00', 'no', '', 5, NULL, 72),
	('donationpubliclistsummary', 'fr', 'messages', 'Dons récents par date, montant et pays (les informations personnelles ne sont pas affichées sauf en cas de demande explicite).\r\nLes dons ne sont pas mis à jour en temps réel : ne vous inquiétez pas si vous ne les voyez pas immédiatement.', '2008-05-26 08:50:00', '2023-09-19 18:11:33', '0000-00-00 00:00:00', 'no', '', 5, NULL, 168499),
	('donationpubliclistsummary', 'gl', 'messages', 'Doazóns recentes por data, cantidade e país (os detalles persoais non se mostran a menos que se pida explicitamente). \r\nAs doazóns non se actualizan en tempo real. Non te preocupes se non as ves inmediatamente.', '2021-01-20 09:42:49', '2022-12-22 09:58:13', '2021-01-20 09:42:49', 'no', '', 5, NULL, 210880),
	('donationpubliclistsummary', 'hr', 'messages', 'Posljednje donacije po datumu i državi (osobni podaci su sakriveni osim ako osoba izričito ne traži da budu vidljivi):', '2009-09-01 16:39:10', '2023-09-19 18:11:33', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('donationpubliclistsummary', 'it', 'messages', 'Donazioni recenti per data, importo e nazione (dettagli personali non sono visualizzati se non richiesto esplicitamente).\r\nLe donazioni non sono aggiornate in tempo reale. Non preoccuparti se non le vedi immediatamente.', '2008-06-01 11:58:51', '2023-09-19 18:11:33', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160610),
	('donationpubliclistsummary', 'lt', 'messages', 'Naujausi pervedimai surūšiuoti pagal datą, sumą ir šalį (asmeniniai rėmėjų duomenys nėra pateikiami išskyrus kai rėmėjas pats to pageidauja):', '2009-08-10 01:12:59', '2023-09-19 18:11:33', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('donationpubliclistsummary', 'nl', 'messages', 'Recente donaties gesorteerd op datum, bedrag en land (persoonlijke gegevens worden niet getoond, tenzij hier expliciet om gevraagd werd).  De donaties worden niet in real-time bijgewerkt.  Maak je geen zorgen als je ze niet onmiddellijk ziet.', '2013-03-27 19:41:45', '2023-01-19 21:53:03', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('donationpubliclistsummary', 'pl', 'messages', 'Najnowsze darowizny wg daty, kwoty i kraju (dane osobowe nie są pokazywane, chyba że na wyraźną prośbę):', '2020-06-09 11:08:54', '2020-10-20 21:00:56', '2020-06-09 11:08:54', 'no', '', 5, NULL, 116789),
	('donationpubliclistsummary', 'pt', 'messages', 'Doações recentes por data, quantia e país (dados pessoais não são exibidos excepto quando pedido explicitamente). As doações não são atualizadas em tempo real. Não se preocupe se não as vir refletidas imediatamente.', '2009-07-27 21:23:13', '2023-09-19 18:11:33', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('donationpubliclistsummary', 'ru', 'messages', 'Последние пожертвования по дате, сумме и стране (личные данные не отображаются, если их конкретно не запросили).\r\nПожертвования не обновляются в режиме реального времени. Не беспокойтесь, если вы не видите их сразу.', '2025-03-24 16:47:16', '2025-03-24 16:47:16', '2025-03-24 16:47:16', 'no', '', 5, NULL, 519603),
	('donationpubliclistsummary', 'sr', 'messages', 'Последње донације поређане по датуму, своти и земљи (лични подаци нису приказани, осим ако супротно није изрзчито тражено):', '2013-01-09 23:01:33', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 35032),
	('donationpubliclistsummary', 'uk', 'messages', 'Останні пожертви за датою, сумою та країною (особисті дані не показуються, якщо не запитано явно).  \r\nПожертви не оновлюються в реальному часі. Не хвилюйтеся, якщо ви не бачите їх відразу.', '2026-04-03 16:07:29', '2026-04-03 16:07:29', '2026-04-03 16:07:29', 'no', '', 5, NULL, 573491),
	('donationpubliclistsummary', 'zh-hans', 'messages', '近期捐款：按日期，数目，国家列出。（除非明确要求，否则不会显示个人信息。）', '2011-04-10 06:14:30', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11819),
	('donationpubliclistsummary', 'zh-hant', 'messages', '最近的捐款會顯示日期、金額及國家（個人資料不會顯示，除非明確要求）。\r\n這些捐款資訊並非即時更新，因此若您尚未立即看到，請不用擔心。', '2011-04-10 06:14:30', '2025-05-31 17:36:34', '0000-00-00 00:00:00', 'no', '', 5, NULL, 53422),
