	('email.password.request', 'gl', 'messages', 'Alguén solicitou restaurar o teu contrasinal. Se fuches ti por favor pincha no botón de abaixo para comezar o proceso de restauración do teu contrasinal.', '2021-01-22 11:27:08', '2021-01-22 11:27:08', '2021-01-22 11:27:08', 'no', '', 5, NULL, 210880),
	('email.password.request', 'hy', 'messages', 'Ինչ-որ մեկը խնդրել է վերականգնել քո գաղտնաբառը։ Եթե այդ մեկը դու ես եղել, խնդրում ենք սեղմել ստորև նշված կոճակը՝ գաղտնաբառդ վերականգնելու գործընթացը սկսելու համար։', '2026-01-30 03:40:59', '2026-01-30 03:40:59', '2026-01-30 03:40:59', 'no', '', 5, NULL, 519603),
