	('errorbadkey', 'ar', 'messages', 'أخ, يبدو ان هناك مشكلة\r\nمفتاح التحقق فى الرابط غير صالح نرجو التاكد انك قمت بنسخ الرابط من الايميل جيدا', '2008-02-10 20:23:39', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 2702),
	('errorbadkey', 'bg', 'messages', 'Опа, май има проблем:', '2007-08-05 21:35:54', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 401),
	('errorbadkey', 'ca', 'messages', 'La clau d\'autenticació de l\'URL no és vàlida. Comprova que has copiat l\'URL correctament!', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('errorbadkey', 'de', 'messages', 'Ups, hier scheint es ein Problem zu geben:\r\n\r\nDu hast einen ungültigen Authentifizierungsschlüssel angegebenen. Kontrolliere bitte ob du die Internetadresse (den HTTP-Link) aus der E-Mail richtig übernommen hast!', '2007-07-12 11:04:33', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('errorbadkey', 'el', 'messages', 'Ωχ, φαίνεται πως υπάρχει κάποιο πρόβλημα:\r\n\r\nΜη έγκυρο κλειδί πιστοποίησης στη διεύθυνση URL. Έλεγξε αν αντέγραψες το url από το μήνυμα ηλεκτρονικού ταχυδρομείου σωστά!', '2013-11-19 20:07:39', '2020-09-02 11:15:22', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('errorbadkey', 'en', 'messages', 'Oops, there seems to be a problem:\r\n\r\nInvalid authentication key in the URL. Please check that you have copied the url from the email correctly!', '2007-07-11 12:51:04', '2019-04-23 18:16:49', '2008-04-13 16:16:26', 'no', 'This is the error message which is displayed when a member who just subscribed to BeWelcome wants to confirm his application through the wrong url', 5, NULL, 69),
	('errorbadkey', 'eo', 'messages', 'Ve, ŝajnas ke estas problemo:\r\n\r\nMalĝusta aŭtentiga ŝlosilo en la URL. Bonvole kontrolu ke vi korekte kopiis la URL-on de la retpoŝtmesaĝo!', '2007-09-10 21:26:35', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1769),
	('errorbadkey', 'es', 'messages', 'Oops, parece que hay un problema:\r\n\r\nLlave de validación incorrecta en el URL. Por favor confirma que has copiado el URL del mensaje electrónico correcto.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1328),
	('errorbadkey', 'eu', 'messages', 'Arazo bat dagoela dirudi:\r\n\r\nURL-ko egiaztatze-giltza baliogabea da. Posta elektronikotik ondo kopiatu duzula egiazta ezazu!', '2012-12-23 17:21:34', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11907),
	('errorbadkey', 'fi', 'messages', 'Hups, tässä näyttää olevan ongelma:\r\n\r\nEpäkelpo vahvistaminen. Tarkistathan kopioimasi osoitteen (urlin) sähköpostistasi!', '2007-09-06 19:30:43', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 525),
	('errorbadkey', 'fr', 'messages', 'Désolé&nbsp;! \r\n\r\nLa clef d\'activation de votre URL semble incorrecte. Merci de vérifier que vous avez correctement copié l\'adresse de confirmation.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('errorbadkey', 'gl', 'messages', 'Vaia, parece que houbo un problema:\r\n\r\nChave de autenticación inválida na URL. Por favor, verifique que copiaches o url do correo electrónico correctamente!', '2022-09-12 08:08:37', '2022-09-12 08:08:37', '2022-09-12 08:08:37', 'no', '', 5, NULL, 210880),
	('errorbadkey', 'he', 'messages', 'אופס, נראה שיש בעיה:\r\nמפתח אימות לא תקין בכתובת URL. נא לוודא שהכתובת הועתק כמו שצריך מהדוא"ל!', '2022-07-11 18:00:57', '2022-07-11 18:00:57', '2022-07-11 18:00:57', 'no', '', 5, NULL, 290109),
	('errorbadkey', 'hr', 'messages', 'Uf,  imamo problemčić: \r\n\r\nNetočni URL. Provjeri jesi li dobro utipkao/la web-adresu (url) iz e-maila! ', '2009-09-19 16:56:44', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('errorbadkey', 'hu', 'messages', 'Nem jó linket adtál meg', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 338),
	('errorbadkey', 'id', 'messages', 'Maaf, ada kesalahan teknis', '2007-11-07 21:00:16', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 2019),
	('errorbadkey', 'it', 'messages', 'Oops, sembra che ci sia un problema:\r\nChiave di autentificayione errata della URL. Per favore controlla se hai copiato correttamente la URL dalla mail!', '2007-08-19 15:44:52', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 103),
	('errorbadkey', 'lt', 'messages', 'Oi... atrodo, kad iškilo šiokia tokia problema:\r\n\r\nNetinkamas autentiškumo raktas pateiktoje nuorodoje; patikrink, ar teisingai nukopijavai nuorodos adresą iš el.laiško.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('errorbadkey', 'lv', 'messages', 'Oops, izskatās ka ir problēma:\r\n\r\nNederīga autentiskuma atslēga iekš URL. Lūdzu pārbaudi, vai tu esi pareizi iekopējis url no epasta!', '2007-09-02 13:45:05', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 375),
	('errorbadkey', 'nl', 'messages', 'Oeps, er is een probleem opgetreden : \r\nVerkeerde sleutel in de URL. Controleer of je de juiste URL uit de e-mail hebt gekopieerd!', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40169),
	('errorbadkey', 'no', 'messages', 'Beklager, men det er noe galt med linken.\r\nFor å kunne bekrefte din konto må du benytte hele linken du fikk tilsendt på e-post.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 573),
	('errorbadkey', 'pl', 'messages', 'Ups, kod URL  jest nieprawidłowy! Sprawdź, czy poprawnie przekopiowałeś URL z emaila.', '2007-08-03 11:30:19', '2020-10-19 23:03:06', '0000-00-00 00:00:00', 'no', '', 5, NULL, 116789),
	('errorbadkey', 'pt', 'messages', 'Oops, parece haver um problema:\r\n\r\nChave errada no endereço. Por favor, confirme que copiou o endereço corretamente!\r\no seu link está errado', '2007-06-29 12:43:12', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('errorbadkey', 'pt-BR', 'messages', 'Opa, parece haver um problema:\r\n\r\nChave de autenticação inválida na URL. Por favor confira se você copiou o endereço corretamente do email.', '2007-08-06 17:04:14', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 144),
	('errorbadkey', 'ro', 'messages', 'Ups, se pare că e o problemă:\r\n\r\nCod de autentificare incorect în URL. Te rugăm verifică dacă ai copiat corect adresa din mesajul email!', '2007-07-25 16:33:21', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1081),
	('errorbadkey', 'ru', 'messages', 'Упс, вы вводите неверный код подтверждения. Пожалуйста, проверьте, правильно ли вы скопировали код из электронного письма ', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 79),
	('errorbadkey', 'sr', 'messages', 'Оп оп, чини се да имамо проблем:\r\n\r\nПогрешна потврдна шифра у УРЛ. Молимо вас, провертие да ли сте добро прекопирали урл добијен у мејлу!', '2013-01-17 13:53:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 35032),
	('errorbadkey', 'tr', 'messages', 'Anlaşılan bir hata var: \r\n\r\nLinkinizdeki doğrulama anahtarı doğru değil. Lütfen linki doğru kopyalayıp kopyalamadığınızı kontrol ediniz.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 64652),
	('errorbadpictureformat', 'ar', 'messages', 'نأسف <b>%s</b>  هذا النوع من الملفات لا يصلح', '2008-02-13 14:51:28', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 2702),
	('errorbadpictureformat', 'bg', 'messages', 'Съжаляваме, <b>%s</b>  е неподходящ формат. Само .jpg или .png файлове са разрешени. Опитайте отново с файл в подходящ формат. ', '2007-07-04 20:00:22', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 851),
	('errorbadpictureformat', 'ca', 'messages', 'El format <b>%s</b> no és admès.\r\n\r\nNomés pots pujar arxius .jpg o .png. Intenta-ho una altra vegada amb un format correcte.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('errorbadpictureformat', 'da', 'messages', '<b>%s</b> er desværre et forkert format.\r\nKun .jpg og .png filer kan uploades; prøv igen med en fil i et af de formater.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1),
	('errorbadpictureformat', 'de', 'messages', 'Das Bildformat <b>%s</b> wird leider nicht unterstützt.\r\n\r\nErlaubt sind .jpg- und .png-Dateien. Bitte versuch es erneut mit einer Datei in diesem Format.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('errorbadpictureformat', 'el', 'messages', 'Λυπούμαστε, <b>%s</b> δεν είναι καλό φορμάτ.\r\n\r\nΗ μεταφόρτωση είναι συμβατή μόνο με αρχεία .jpg ή .png. Προσπάθησε ξανά με ένα αρχείο σωστού φορμάτ.', '2013-10-29 19:52:35', '2020-09-02 11:11:06', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('errorbadpictureformat', 'en', 'messages', 'Sorry <b>%s</b> is a bad format.\r\n\r\nOnly .jpg or .png files are allowed to be uploaded. Try again with a file of the correct format', '2007-07-25 21:52:36', '2019-04-23 18:16:49', '2008-04-13 16:16:26', 'no', '', 5, NULL, 612),
	('errorbadpictureformat', 'eo', 'messages', 'Ni pardonpetas, <b>%s</b> estas neakceptita formato.\r\n\r\nNur .jpg aŭ .png dosieroj estas akceptotaj. Provu denove kun taŭg-formata dosiero.', '2007-09-10 21:30:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1769),
	('errorbadpictureformat', 'es', 'messages', 'Lo sentimos, <b>%s</b> es un formato incorrecto.\r\nSólo se permiten archivos .jpg o .png. Intenta de nuevo con un formato de archivo correcto.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1328),
	('errorbadpictureformat', 'eu', 'messages', '<b>%s</b> formatua ez da onartzen.\r\n\r\nSoilik .jpg edo .png fitxategi motak igo ditzakezu. Saiatu zaitez berriro formatu egokiko fitxategi batekin.', '2012-12-23 17:23:30', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11907),
	('errorbadpictureformat', 'fi', 'messages', 'Valitettavasti <b>%s</b> ei ole sallittu tiedostotyyppi\r\n\r\nvain .jpg tai .png ovat sallittuja, yritä uudelleen oikean tyyppisellä tiedostolla', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 72),
	('errorbadpictureformat', 'fr', 'messages', 'Désolé, <b>%s</b> est un format non supporté.<br>\r\n\r\nSeuls les fichiers .jpg ou .png sont acceptés. Merci de réessayer avec un fichier au format supporté.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('errorbadpictureformat', 'gl', 'messages', '<p>Síntoo <strong>%s</strong> está en un formato non válido.</p><p>Só se permite subir arquivos .jpg ou .png. Téntao de novo con un formato apropiado.&nbsp;</p>', '2022-03-29 10:41:29', '2022-03-29 10:41:29', '2022-03-29 10:41:29', 'no', '', 5, NULL, 210880),
	('errorbadpictureformat', 'he', 'messages', '<p>סליחה, אבל %s הוא פורמט לא חוקי.</p><p>ניתן להעלות רק קבצי jpg או png.</p><p>נא לנסות שוב עם פורמט מתאים.</p>', '2022-07-11 18:35:16', '2022-07-11 18:35:16', '2022-07-11 18:35:16', 'no', '', 5, NULL, 290109),
	('errorbadpictureformat', 'hr', 'messages', 'Dopušteno je postavljati datoteke samo u .jpg i .png formatu. Pokušaj ponovno s jednim od ta dva formata.', '2009-09-19 14:28:13', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('errorbadpictureformat', 'hu', 'messages', 'Bocs, de nem jó a fájl formátum\r\ncsak .jpg vagy .png kiterjesztésű fájlt tudsz feltölteni, kérlek változtasd a képeket a megfelelő formátumra', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 338),
	('errorbadpictureformat', 'id', 'messages', 'Maaf <b>%s</b> kesalahat format', '2007-11-07 21:00:39', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 2019),
	('errorbadpictureformat', 'it', 'messages', 'Ci dispiace <b>%s</b> è un formato sbagliato. \r\n\r\nPossono essere caricati solo file .jpg o .png, riprova di nuovo con un file nel formato corretto', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 103),
	('errorbadpictureformat', 'lt', 'messages', 'Atsiprašome, <b>%s</b> yra netinkamas formatas. \r\n\r\nNaudoti leidžiama tik .jpg arba .png failus. Pamėgink dar kartą naudojant tinkamo formato failą.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('errorbadpictureformat', 'lv', 'messages', 'Atvaino <b>%s</b> ir nepareizs formāts.\r\n\r\nTikai .jpg vai .png failus var ielādēt. Mēģini vēlreiz ar atbilstoša formāta failu', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 375),
	('errorbadpictureformat', 'nl', 'messages', 'Sorry, <b>%s</b> is het verkeerde formaat\r\n\r\nAlleen .jpg en .png bestanden zijn toegestaan. Probeer opnieuw met een bestand van het juiste formaat.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 97),
	('errorbadpictureformat', 'no', 'messages', 'Beklager, men du kan bare laste opp bilder i formatene .jpg eller .png.\r\nBilder i andre formater kan ikke vises på internett.\r\n\r\nVennligst konverter bildet til et format vi støtter, eller bruk et annet bilde.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 573),
	('errorbadpictureformat', 'pl', 'messages', 'Przykro nam, <b>%s</b> jest błędnym formatem\r\n\r\ntylko pliki .jpg lub .png są dozwolone, spróbuj jeszcze raz', '0000-00-00 00:00:00', '2020-10-19 21:57:07', '0000-00-00 00:00:00', 'no', '', 5, NULL, 116789),
	('errorbadpictureformat', 'pt', 'messages', 'Desculpe, <b>%s</b> é um formato inválido.\r\n\r\nApenas pode enviar ficheiros no formato .jpg e .png. Por favor, tente novamente com um formato de ficheiro adequado', '2007-06-29 12:44:18', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('errorbadpictureformat', 'pt-BR', 'messages', 'Desculpe, <b>%s</b> é um formato inválido.\r\n\r\nApenas arquivos .jpg ou .png são permitidos. Tente novamente com um arquivo do formato correto.', '2007-08-06 17:06:59', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 144),
	('errorbadpictureformat', 'ro', 'messages', 'Ne pare rău, <b>%s</b> este într-un format incorect.\r\n\r\nNumai fişierele în format .jpg sau .png sunt acceptate pentru upload, încearcă din nou cu un astfel de fişier', '2007-07-25 16:34:42', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1081),
	('errorbadpictureformat', 'ru', 'messages', 'К сожалению, мы не работаем с форматом <b>%s</b> \r\n\r\nВы можете загружать только файлы с расширением .jpg или .png, повторите попытку с файлом подходящего формата. \r\n', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('errorbadpictureformat', 'sr', 'messages', 'Жао нам је, <b>%s</b> је лош формат.\r\n\r\nСамо .jpg или .png фајлове је могуће окачити. Покушајте поново са фајлом у коректном формату.', '2013-01-17 13:54:42', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 35032),
	('errorbadpictureformat', 'tr', 'messages', 'Özür dileriz, <b>%s</b> formatı uygun değil ancak .jpg yada .png tipi dosyaların yüklenmesine izin verilmiştir. Uygun formatla tekrar deneyiniz!', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 64652),
	('errormailallreadyconfimed', 'ar', 'messages', 'يبدو ان عنوان بريدك الالكترونى قد تم تأكيده. حالة طلبك <b>%s</b>. \r\nفى حالة <b>عدم التأكيد</b>. يعنى ان ملفك يجب ان يراجع من قبل متطوعينا قبل ان يسمح لك بالدخول الكامل للموقع.\r\n', '2008-02-13 14:55:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 2702),
	('errormailallreadyconfimed', 'bg', 'messages', 'Вашият Е-мейл е потвърден, статусът на Вашето заявление е <b>%s</b> \r\n Ако заявлението Ви е още с <b>Pending</b> статус, то предстои да бъде прегледано от нашите доброволци, преди да получите пълен достъп  до този сайт.', '2007-07-04 20:11:05', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 851),
	('errormailallreadyconfimed', 'ca', 'messages', 'Sembla ser que el teu email ja ha estat confirmat, l\'estat de la teva petició és <b>%s</b>.\r\n\r\nSi l\'estat del teu perfil és <b>pendent</b>, vol dir que el ha de ser revisat pels voluntaris abans de poder obtenir l\'accés complet.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 177),
	('errormailallreadyconfimed', 'de', 'messages', 'Offenbar wurde deine E-Mail-Adresse bereits bestätigt. Zur Zeit ist dein Anmeldestatus <b>%s</b>.\r\n\r\nFalls der Status <b>Pending</b> ist, bedeutet das, dass dein Profil noch von einem freiwilligen Helfer überprüft werden muss, bevor du vollständigen Zugang zur Seite erhältst.\r\n', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 15240),
	('errormailallreadyconfimed', 'el', 'messages', 'Φαίνεται οτι το email σας έχει ήδη επιβεβαιωθεί. Το καθεστώς της αίτησης είναι <b>%s</b>. \r\n\r\nΣε περίπτωση που <b>Εκκρεμεί</b>, σημαίνει οτι το προφίλ σας χρειάζεται να αξιολογηθεί απο εθελοντές πριν να μπορείτε να έχετε πλήρη πρόσβαση στη σελίδα.', '2013-10-29 19:55:31', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 25930),
	('errormailallreadyconfimed', 'en', 'messages', 'It seems that your mail has already been confirmed. Your application status is <b>%s</b>.\r\n\r\nIn case it\'s <b>Pending</b>, it means that your profile needs to be reviewed by our volunteers before you can have full access to this site.', '2007-07-25 21:53:38', '2019-04-23 18:16:49', '2008-04-13 16:16:26', 'no', '', 5, 1, 612),
	('errormailallreadyconfimed', 'eo', 'messages', 'Ŝajnas ke via retpoŝtmesaĝo jam estis konfirmita. Via statuso estas <b>%s</b>.\r\n\r\nEn la kazo <b>Pritraktata</b>, tio signifas ke la profilon devas revizii niaj voluntuloj antaŭ vi povas havi tutan aliron al ĉi-tiu retpaĝaro.', '2007-09-10 21:33:57', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1769),
	('errormailallreadyconfimed', 'es', 'messages', 'Parece que tu e-mail fue confirmado, tu estado es <b>%s</b>.\r\n\r\nEn caso que veas <b>Pendiente</b>, significa que tu perfil necesita ser revisado por nuestros voluntarios antes de tener acceso completo en este sitio web.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1328),
	('errormailallreadyconfimed', 'fi', 'messages', 'Näyttää siltä, että viestisi on jo vahvistettu. Hakemuksesi on <b>%</b>.\r\n\r\nJos hakemuksesi <b>Odottaa</b>, se tarkoittaa sitä, että vapaaehtoistemme täytyy tarkistaa hakemuksesi ennen kuin pääset täysin selaamaan tätä sivustoa.', '2007-09-06 19:34:11', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 525),
	('errormailallreadyconfimed', 'fr', 'messages', 'Il semble que votre e-mail a déjà été confirmé, votre statut d\'enregistrement est: <b>%s</b>. Dans le cas où ce statut est "<b>Pending</b>", cela signifie que votre profil doit être vérifier par nos volontaires avant que vous ayez un accès complet à ce site. ', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 68),
	('errormailallreadyconfimed', 'hr', 'messages', 'Čini se da je tvoja e-mail adresa već potvrđena. Status tvoje prijave je <b>%s</b>. \r\n\r\nU slučaju da je  <b>na čekanju</b>, ito znači da tvoj profil još čeka volontera da ga pregleda i odobri potpuni pristup ovim stranicama. ', '2009-09-19 16:52:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 8197),
	('errormailallreadyconfimed', 'hu', 'messages', 'Úgy tűnik, hogy a leveledet már visszagazoltuk. Bejelentkezési állapotod <b>%s</b>.\r\nAbban az esetben ha ez <b>Függőben</b>, akkor a profilodat az önkénteseinknek meg kell tekinteniük mielőtt szabad elérhetést biztosítunk az oldalra.', '2007-09-05 18:51:35', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 805),
	('errormailallreadyconfimed', 'id', 'messages', 'Email anda telah disetujui. Status aplikasi anda <b>%s</b>. \r\n\r\nJika anda menerima keterangan <b>Pending</b>, berarti biodata anda akan memerlukan waktu untuk dikaji sebelum anda dapat melanjutkan.', '2007-11-07 21:02:13', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 2019),
	('errormailallreadyconfimed', 'it', 'messages', 'Sembra che il tuo indirizzo e-mail sia giá stato confermato, la tua richiesta é nello stato di <b>%s</b>. Se é in Pending, significa che il tuo profilo deve essere rivisto dai nostri volontari prima che tu possa avere accesso completo al sito.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
	('errormailallreadyconfimed', 'lt', 'messages', 'Tavo el. pašto adresas jau yra patvirtintas. Tavo paraiškos statusas yra <b>%s</b>.\r\n\r\nJei statusas yra <b>Laukianti sprendimo</b> (Pending), tai reiškia, kad pateiktus duomenis turi peržiūrėti vienas iš mūsų savanorių; tik po to galėsi naudotis visomis svetainės teikiamomis paslaugomis.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 227),
	('errormailallreadyconfimed', 'lv', 'messages', 'Izskatās, ka tavs epasts ir jau apstiprināts. Tavs reģistrācijas statuss ir <b>%s</b> \r\n\r\nGadījumā, ja tas ir <b>Pending</b> , tas nozīmē, ka pirms tu vari iegūt pilnībā piekļuvi mājas lapai, brīvprātīgajiem ir jāpārbauda tavs profils.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 375),
	('errormailallreadyconfimed', 'nl', 'messages', 'Het lijkt erop dat je e-mail adres reeds bevestigd is. De status van je aanvraag is <b>%s</b>\r\n\r\nIn het geval dat de status \'<b>Pending</b>\' is betekent dit dat je profiel nog gecontroleerd moet worden door onze vrijwilligers voordat je volledige toegang krijgt tot deze website.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 273),
	('errormailallreadyconfimed', 'no', 'messages', 'Du har allerede bekreftet ditt medlemskap, din status er <b>%s</b>\r\n\r\nHvis status er <b>Pending</b> må du vente til en av våre frivillige hjelpere har godkjent din konto før du får full tilgang.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 573),
	('errormailallreadyconfimed', 'pl', 'messages', 'Twój mail został już potwierdzony, status Twojego członkostwa to <b>%s</b>.\r\n\r\nJeśli Twój status to <b>nierozstrzygnięty</b> to znaczy, że Twój profil musi zostać zaakceptowany przez wolontariuszy, zanim będziesz miał pełny dostęp do strony.', '2007-07-07 08:58:29', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 90),
	('errormailallreadyconfimed', 'pt', 'messages', 'Parece que o seu endereço de correio eletrónico já foi confirmado, o estado da sua inscrição é <b>%s</b>\r\n\r\nCaso esteja em <b>Pendente<b>, o seu perfil ainda tem de ser revisto pelos nossos voluntários antes de obter acesso total a este site.', '2007-06-29 12:45:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 38787),
	('errormailallreadyconfimed', 'pt-BR', 'messages', 'Parece que seu mail já foi confirmado. O status da sua aplicacao é <b>%s</b>.\r\n\r\nNo caso de estar <b>Pendente</b>, significa que seu perfil precisa ser revisto por nossos voluntários antes que voce tenha acesso completo a este sítio.', '2007-08-13 16:52:58', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, 1, 421),
	('errormailallreadyconfimed', 'ro', 'messages', 'Se pare că adresa ta de email a fost deja confirmată, statusul aplicaţiei tale este <b>%s</b>\r\n\r\nÎn caz că este încă în <b>Prelucrare</b>, înseamnă că profilul tău necesită o aprobare din partea voluntarilor noştri înainte ca tu să poţi avea acces complet la acest site.', '2007-07-25 16:36:51', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1081),
	('errormailallreadyconfimed', 'ru', 'messages', 'Очевидно, вы уже подтвердили регистрацию по ссылке, отправленной на ваш почтовый адрес. Статус вашей заявки: <b>%s</b>.\r\n\r\nЕсли статус <b>в ожидании</b>, это значит, что необходимо, чтобы ваш профиль проверил волонтер, прежде чем вы получите полный доступ к инструментам сайта.', '2007-09-09 07:03:40', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 79),
	('errormailallreadyconfimed', 'sr', 'messages', 'Изгледа да је ваш мејл већ био потврђен. Статус ваше апликације је <b>%s</b>.\r\n\r\nУ случају да је статус <b>нерешен</b>, то значи да ваш профил треба да буде прегледан од стране наших волонтера пре него што добијете пун приступ сајту.', '2013-01-17 14:08:41', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 35032),
	('errormailallreadyconfimed', 'tr', 'messages', 'E-posta adresiniz zaten teyid edilmiş, başvurunuz <b>%s</b> durumunda. \r\n\r\n<b>Bekleme</b> durumunda iseniz profiliniz gönüllüler tarafından onaylandıktan sonra siteye erişebileceksiniz.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 64652),
	('errormustbeindentified', 'ar', 'messages', 'لا يمكن استخدام هذه الوظيفة بواسطة عضو لم يقم بالتعريف عن نفسه', '2008-02-10 20:14:16', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 2702),
	('errormustbeindentified', 'bg', 'messages', 'Тази функция не е достъпна за анонимни членове.', '2007-07-04 20:12:22', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 851),
	('errormustbeindentified', 'ca', 'messages', 'Els membres no identificats no poden accedir a aquesta funció', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 11944),
	('errormustbeindentified', 'de', 'messages', 'Diese Funktion kann nur von identifizierten Mitgliedern aufgerufen werden.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 15240),
	('errormustbeindentified', 'el', 'messages', 'Αυτή η λειτουργία δεν μπορεί να πραγματοποιηθεί απο ένα μη ταυτοποιημένο μέλος', '2013-11-19 20:08:16', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 25930),
	('errormustbeindentified', 'en', 'messages', 'This function cannot be accessed by an unidentified member', '2008-04-13 16:15:10', '2019-04-23 18:16:49', '2008-04-13 16:16:26', 'no', '', 5, 1, 1),
	('errormustbeindentified', 'eo', 'messages', 'Tiun funkcion ne alireblas senidentigita membro', '2007-09-10 21:35:18', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1769),
	('errormustbeindentified', 'es', 'messages', 'No es possible acceder a esta función sin identificarse antes.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('errormustbeindentified', 'fi', 'messages', 'Kirjautumaton käyttäjä ei voi käyttää tätä toimintoa', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 72),
	('errormustbeindentified', 'fr', 'messages', 'Cette fonction n\'est pas accessible à un membre non identifié', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('errormustbeindentified', 'hr', 'messages', 'Neidentificirani članovi nemaju pristup ovoj funkciji', '2009-09-08 13:14:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 8197),
	('errormustbeindentified', 'hu', 'messages', 'Azonosítatlan felhasználó számára ez a funkció nem elérhető', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 338),
	('errormustbeindentified', 'id', 'messages', 'Fungsi ini tidak dapat digunakan oleh anggota yang tidak dikenal.', '2007-11-07 21:02:41', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 2019),
	('errormustbeindentified', 'it', 'messages', 'Un membro non identificato non può accedere a questa funzione', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
	('errormustbeindentified', 'lt', 'messages', 'Ši funkcija prieinama tik nariams', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 227),
	('errormustbeindentified', 'lv', 'messages', 'Šai funkcijai nevar piekļūt neidentificēti biedri.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 375),
	('errormustbeindentified', 'nl', 'messages', 'Deze functie is niet beschikbaar voor een niet geïdentificeerd  lid', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 22382),
	('errormustbeindentified', 'no', 'messages', 'Du må vente til din konto er godkjent. Vennligst prøv igjen senere.\r\n\r\nDette er et tiltak for å kvalitetssikre nye brukere, og forhindrer bl.a. søppelpost/spam.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 573),
