	('errorneedright', 'tr', 'messages', '%s yetkisine gerek var. Bunu yapamazsın.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1),
	('errornocommentonyourself', 'ar', 'messages', 'اسفون فانت لا تستطيع ان تضع تعليقا لنفسك فى حالة وجود مشكلة راسل\r\n<a href="http://www.bewelcome.org/feedback.php">قسم افادة التعليقات</a> ', '2008-02-10 20:25:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 2702),
	('errornocommentonyourself', 'bg', 'messages', 'Съжаляваме, не можете да пишете коментар на себе си. В случай на проблем, ни пишете на <a href="http://www.bewelcome.org/feedback.php">feedback category comment</a>', '2007-07-04 18:58:07', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 851),
	('errornocommentonyourself', 'ca', 'messages', 'No pots escriure\'t un comentari a tu mateix.\r\nSi tens cap problema, envia\'ns <a href="http://www.bewelcome.org/feedback.php">un comentari</a>.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('errornocommentonyourself', 'cs', 'messages', '<p>Omlouváme se, ale není možné okomentovat svůj vlastní profil. V případě problému můžete přidat komentář do <a href="http://www.bewelcome.org/feedback.php">kategorie feedbacku</a>.</p>', '2023-01-03 15:44:35', '2023-01-03 15:44:35', '2023-01-03 15:44:35', 'no', '', 5, NULL, 389575),
	('errornocommentonyourself', 'da', 'messages', 'Du kan ikke skrive kommentarer om dig selv.\r\nI tilfælde af problemer med dine kommentarer skal du notificere <a href="http://www.bewelcome.org/feedback.php">feedback</a>.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 74),
	('errornocommentonyourself', 'de', 'messages', 'Es ist leider nicht möglich, einen Kommentar über sich selbst zu posten. Solltest du ein Problem mit der Kommentar-Funktion haben, sende bitte eine <a href="http://www.bewelcome.org/feedback.php">Nachricht in der Kategorie "Problem mit Kommentaren"</a> an uns.\r\n', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('errornocommentonyourself', 'el', 'messages', 'Συγνώμη, δεν μπορείς να θέσεις σχόλιο στον εαυτό σου.\r\nΣε περίπτωση προβλήματος στείλε ένα <a href="https://www.bewelcome.org/feedback.php">σχόλιο </a>', '2013-11-19 20:11:10', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 16526),
	('errornocommentonyourself', 'en', 'messages', 'Sorry you cannot put a comment on yourself.\r\nIn case of problem send a <a href="http://www.bewelcome.org/feedback.php">feedback category comment</a>', '2007-02-28 12:38:43', '2019-04-23 18:16:49', '2008-04-13 16:16:26', 'no', 'This is a error message typically displayed when a member try to put a comment ion himself', 5, NULL, 91),
	('errornocommentonyourself', 'eo', 'messages', 'Bedaŭrinde, vi ne povas proponi komenton pri vi mem. Se estas problemo, sendu <a href="http://www.bewelcome.org/feedback.php">sondilkategoria komento</a>', '2007-09-10 21:37:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1769),
	('errornocommentonyourself', 'es', 'messages', 'Lo sentimos pero no puedes escribir un comentario sobre ti mismo. En caso de que haya algún problema, envía un <a href="http://www.bewelcome.org/feedback.php">comentario de tipo feedback</a>.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1328),
	('errornocommentonyourself', 'fi', 'messages', 'Valitettavasti et voi kirjoittaa kommenttia itsestäsi. Ongelmatapauksessa lähetä palautetta kommenteista <a href="http://www.bewelcome.org/feedback.php">palautesivun</a> kautta.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 72),
	('errornocommentonyourself', 'fr', 'messages', 'Désolé&nbsp;! Vous ne pouvez pas ajouter de commentaires sur votre propre profil.\r\nEn cas de problème, veuillez nous <a href="http://www.bewelcome.org/feedback.php">signaler un bug</a>.\r\n', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('errornocommentonyourself', 'gl', 'messages', '<p>Síntoo, pero non podes poñer un comentario sobre a túa persoa. No caso de que haxa algún problema envía un <a href="http://www.bewelcome.org/feedback.php">comentario para contactar con nós</a></p>', '2022-09-13 08:06:25', '2022-09-13 08:06:25', '2022-09-13 08:06:25', 'no', '', 5, NULL, 210880),
	('errornocommentonyourself', 'he', 'messages', '<p>מצטערים, לא ניתן לכתוב הערה על עצמך. אם יש בעיה, ניתן להגיב כאן - <a href="http://www.bewelcome.org/feedback.php">http://www.bewelcome.org/feedback.php</a></p>', '2022-07-11 16:58:22', '2022-07-11 16:58:22', '2022-07-11 16:58:22', 'no', '', 5, NULL, 290109),
	('errornocommentonyourself', 'hr', 'messages', 'Hej, pa ne možeš komentirati samog/u sebe.\r\nAko imaš problem pošalji <a href="http://www.bewelcome.org/feedback.php">komentar u kategoriju povratne informacije</a> ', '2010-01-15 20:53:29', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('errornocommentonyourself', 'hu', 'messages', 'Bocs, de nem írhatsz véleményt magadról. Ha hibát észleltél,<a href="http://www.bewelcome.org/feedback.php">vedd fel velünk a kapcsolatot</a>!', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 338),
	('errornocommentonyourself', 'id', 'messages', 'Maaf, anda tidak dapat memberi komentar kepada diri anda sendiri. Lebih lanjut hubungi kami di <a href="http://www.bewelcome.org/feedback.php">Kategori Tanggapan Komentar</a>', '2007-11-09 16:49:28', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 2019),
	('errornocommentonyourself', 'it', 'messages', 'Ci dispiace, ma non puoi scrivere un commento per te stesso/a.\r\nSe hai problemi manda una segnalazione a <a href="http://www.bewelcome.org/feedback.php">categoria feedback commenti</a>\r\n', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 103),
	('errornocommentonyourself', 'lt', 'messages', 'Deja, palikti sau komentarą nėra leidžiama.\r\nJei susidūrei su keblumais, susisiek su mumis <a href="http://www.bewelcome.org/feedback.php">čia</a> pasirenkant kategoriją „Problema su komentaru“, ačiū!', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('errornocommentonyourself', 'lv', 'messages', 'Atvaino, bet tu nevari ierakstīt komentāru pats sev. Problēmu gadījumā ziņot <a href="http://www.bewelcome.org/feedback.php">feedback category comment</a>', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 375),
	('errornocommentonyourself', 'nl', 'messages', 'Sorry maar je kan geen commentaar over jezelf schrijven. Indien je een probleem hebt, kan je een <a href="http://www.bewelcome.org/feedback.php">feedback category commentaar</a> sturen\r\n', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 69),
	('errornocommentonyourself', 'no', 'messages', 'Det er ikke mulig å legge igjen en kommentar på din egen side.\r\n\r\n<a href="http://www.bewelcome.org/feedback.php">Tilbakemeldinger til BeWelcome? Klikk her.</a>', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 573),
	('errornocommentonyourself', 'pl', 'messages', 'Niestety, nie możesz wystawić sobie komentarza.\r\nW razie problemów skontaktuj się z Nami <a href="http://www.bewelcome.org/feedback.php">feedback category comment</a>', '0000-00-00 00:00:00', '2020-10-19 22:05:30', '0000-00-00 00:00:00', 'no', '', 5, NULL, 116789),
	('errornocommentonyourself', 'pt', 'messages', 'Lamentamos mas não pode deixar um comentário sobre si mesmo.\r\nEm caso de problemas, envie um <a href="http://www.bewelcome.org/feedback.php">comentário genérico</a>', '2007-07-02 21:53:24', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('errornocommentonyourself', 'pt-BR', 'messages', 'Desculpe, você não pode postar um comentário para si mesmo.\r\nEm caso de problema, <a href="http://www.bewelcome.org/feedback.php">entre em contato</a>.', '2007-08-06 17:39:25', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 144),
	('errornocommentonyourself', 'ro', 'messages', 'Ne pare rău, dar nu poţi adăuga un comentariu la profilul tău.\r\nDacă  vorba de o problemă, trimite <a href="http://www.bewelcome.org/feedback.php">un comentariu de tip feedback</a>', '2007-07-25 16:39:56', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1081),
	('errornocommentonyourself', 'ru', 'messages', 'Извините, но вы не можете оставить отзыв о самом себе. В случае проблемы, <a href="http://www.bewelcome.org/feedback.php">сообщите нам</a>\r\n', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 79),
	('errornocommentonyourself', 'sr', 'messages', 'Жао нам је, али не можете коментарисати себе.\r\nУ случају проблема, пошаљите <a href="http://www.bewelcome.org/feedback.php">коментар на "фидбек" категорију</a>', '2013-01-17 14:13:24', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 35032),
	('errornocommentonyourself', 'tr', 'messages', 'Üzgünüz, kendiniz için yorum yazamazsınız, bir problem halinde geri bildirim için <a href="http://www.bewelcome.org/feedback.php">geri bildirim</a> formundan yorum gönderin seçeneğini seçiniz.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 95),
	('errornorelationonyourself', 'ar', 'messages', 'عفوا و لكنك لا تستطيع اضافة نفسك كشخص على علاقة به\r\nفى حالة ما اذا واجهتك مشكلة نرجو ان ترسل <a href="http://www.bewelcome.org/feedback.php">افادة</a>', '2008-02-16 17:48:40', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 2702),
	('errornorelationonyourself', 'ca', 'messages', 'No pots afegir-te una relació amb tu mateix(a). Si tens cap problema, <a href="http://www.bewelcome.org/feedback.php">avisa\'ns</a>.', '2007-10-01 10:49:45', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 177),
	('errornorelationonyourself', 'de', 'messages', 'Es ist nicht möglich, eine Beziehung zu sich selbst einzurichten', '2007-07-08 12:54:27', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 70),
	('errornorelationonyourself', 'el', 'messages', 'Δεν μπορείς να δηλώσεις σχέση με τον εαυτό σου.\r\nΣε περίπτωση σφάλματος στείλε ένα  <a href="http://www.bewelcome.org/feedback.php">σχόλιο</a>', '2020-08-20 13:12:23', '2020-08-20 13:12:23', '2020-08-20 13:12:23', 'no', '', 5, NULL, 266544),
	('errornorelationonyourself', 'en', 'messages', 'Sorry you cannot put a relation on yourself.\r\nIn case of problem send a <a href="http://www.bewelcome.org/feedback.php">feedback </a>', '2007-07-02 21:18:36', '2019-04-23 18:16:49', '2007-07-02 21:18:36', 'no', 'This is a error message typically displayed when a member try to put a relation with himself', 5, NULL, 1),
	('errornorelationonyourself', 'es', 'messages', 'Lo siento, no puedes colocar una relación contigo.\r\nEn caso de problemas <a href="http://www.bewelcome.org/feedback.php">escríbenos</a>', '2007-10-28 07:49:46', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1328),
	('errornorelationonyourself', 'fr', 'messages', 'Désolé, vous ne pouvez pas indiquer que vous faites partie de vos proches. En cas de problème, n\'hésitez pas à <a href="http://www.bewelcome.org/feedback.php">nous contacter</a>.', '2007-07-02 21:31:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('errornorelationonyourself', 'gl', 'messages', '<p>Síntoo pero non podes poñer unha relación contigo mesma. Se hai algún problema envíanos un <a href="http://www.bewelcome.org/feedback.php">comentario</a></p>', '2022-09-12 08:16:14', '2022-09-12 08:16:14', '2022-09-12 08:16:14', 'no', '', 5, NULL, 210880),
	('errornorelationonyourself', 'he', 'messages', '<p>לא ניתן לייצר יחסים על עצמך. במקרה שיש בעיה, דווח בקישור - <a href="http://www.bewelcome.org/feedback.php">http://www.bewelcome.org/feedback.php</a></p>', '2022-07-11 18:04:18', '2022-07-11 18:04:18', '2022-07-11 18:04:18', 'no', '', 5, NULL, 290109),
	('errornorelationonyourself', 'hr', 'messages', 'Nažalost ne možes postaviti vezu na sebe samog/samu. \r\nU slucaju problema posalji <a href="http://www.bewelcome.org/feedback.php"> povratnu informaciju </a>', '2012-09-19 17:34:58', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 24014),
	('errornorelationonyourself', 'it', 'messages', 'Ci disipiace, ma non puoi mettere una relazione a te stesso. \r\nSe hai problemi manda un <a href="http://www.bewelcome.org/feedback.php">feedback </a>', '2007-08-18 19:29:08', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 103),
	('errornorelationonyourself', 'lt', 'messages', 'Atsiprašome, bet negalite apibrėžti santykį su savimi.\r\nJei turite klausimų dėl iškilusių problemų, <a href="http://www.bewelcome.org/feedback.php">susisiekite su mumis</a>.', '2007-08-29 04:20:25', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('errornorelationonyourself', 'lv', 'messages', 'Atvaino, tu nevari pievienot attiecības pats sev.\r\nProblēmu gadījumā atsūti <a href="http://www.bewelcome.org/feedback.php">feedback </a>', '2007-08-05 14:09:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 375),
	('errornorelationonyourself', 'nl', 'messages', 'Sorry, je kan geen relatie leggen met jezelf.\r\nAls je een probleem hebt kan je een <a href="http://www.bewelcome.org/feedback.php">feedback </a> sturen\r\n', '2007-09-15 20:53:13', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 69),
	('errornorelationonyourself', 'pl', 'messages', 'Wystąpił błąd - nie możesz ustanowić relacji sam z sobą. W razie problemów wyślij nam <a href="http://www.bewelcome.org/feedback.php">komentarz</a>', '2012-12-17 02:54:44', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 35248),
	('errornorelationonyourself', 'pt', 'messages', 'Desculpe mas não pode criar uma relação consigo próprio/a.\r\nEm caso de problemas <a href="http://www.bewelcome.org/feedback.php">contacte-nos</a>.', '2013-01-14 12:03:16', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('errornorelationonyourself', 'ro', 'messages', 'Ne pare rău dar nu poţi relaţiona cu tine însăţi. Dacă e vorba de o problemă, te rugăm <a href="http://www.bewelcome.org/feedback.php">trimite un mesaj</a>.', '2007-09-20 22:35:02', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1081),
	('errornorelationonyourself', 'ru', 'messages', 'Сожалеем, но невозможно настроить связь с самим собой.\r\nВ случае какой-либо проблемы, оставьте <a href="http://www.bewelcome.org/feedback.php">сообщение </a>', '2014-05-24 06:41:21', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('errornosuchmember', 'ar', 'messages', 'لا يوجد أعضاء <b>%s</b>', '2008-02-13 14:56:38', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 2702),
