	('faqq_ifoundapronlink', 'hr', 'messages', 'Naišao/la sam na profil koji nije u skladu s pravilima i vrijednostima ovih stranica (npr. poveznica na pornografske sadržaje). Možete li to ukloniti?', '2009-09-20 14:18:06', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
