	('faqq_isitsafe', 'id', 'messages', '<p>Apakah BeWelcome aman?</p>', '2007-11-13 06:09:08', '2022-02-21 19:01:19', '0000-00-00 00:00:00', 'no', '', 5, NULL, 328151),
	('faqq_isitsafe', 'it', 'messages', '<p>BeWelcome è sicuro?</p>', '0000-00-00 00:00:00', '2021-10-20 19:47:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160610),
	('faqq_isitsafe', 'ja', 'messages', '新規のメンバーです。どうやってBeWelcome上にいる他のメンバーを信用できますか？', '2007-11-09 08:01:05', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1834),
	('faqq_isitsafe', 'lt', 'messages', 'Kaip galiu žinoti, kad kiti BeWelcome nariai yra patikimi? Kaip galiu gauti informaciją apie potencialius šeimininkus ar svečius? Kokią apsaugą turiu, kad pas mane neatvyks nusikaltėliai?', '0000-00-00 00:00:00', '2021-02-24 14:30:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 285578),
	('faqq_isitsafe', 'lv', 'messages', 'Es esmu jauns biedrs. Kā es varu būt pārliecināts, ka citi BeWelcome biedri ir uzticami?', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 375),
	('faqq_isitsafe', 'nl', 'messages', '<p>Is BeWelcome veilig?</p>', '0000-00-00 00:00:00', '2021-12-17 19:34:38', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
