	('faqq_isitsafe', 'pt', 'messages', '<p>O BeWelcome é seguro?</p>', '2007-07-16 12:38:49', '2021-10-17 11:04:56', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('faqq_isitsafe', 'pt-BR', 'messages', 'Sou um membro novo. Como posso ter certeza de que os outros membros do BeWelcome são confiáveis?', '2011-09-06 15:48:29', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15566),
	('faqq_isitsafe', 'ro', 'messages', '<p>Sunt în siguranță cu BeWelcome?</p>', '2007-08-28 18:42:50', '2024-01-26 00:54:34', '0000-00-00 00:00:00', 'no', '', 5, NULL, 471388),
	('faqq_isitsafe', 'ru', 'messages', '<p>Безопасно ли в BeWelcome?</p>', '0000-00-00 00:00:00', '2025-04-01 09:30:18', '0000-00-00 00:00:00', 'no', '', 5, NULL, 519603),
	('faqq_isitsafe', 'sl', 'messages', 'Kako sem lahko prepričan, da so drugi uporabniki BeWelcome vredni zaupanja? Kako pridobim informacije o mojem potencialnem gostu ali gostitelju? Kaj je moja zaščite pred kriminalci, ki bi me radi obiskali?', '2019-03-31 22:12:27', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 106553),
	('faqq_isitsafe', 'sr', 'messages', 'Како могу да будем сигуран/сигурна да су други чланови BeWelcome поуздани? Како могу да дођем до информација о свом потенцијалном домаћину или госту? Која је моја заштита од тога да ми криминалац дође у посету?', '2012-12-18 11:14:16', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 60746),
	('faqq_isitsafe', 'sv', 'messages', 'Jag är ett nytt medlem. Hur kan jag vara säker att andra medlemmar på BeWelcome är trovärdiga?', '2012-08-16 11:50:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 23263),
	('faqq_isitsafe', 'tr', 'messages', 'Buradaki insanların güvenirliliğinden nasıl emin olabilirim? Kimlerin host isteklerini kabul etmeliyim ve kimlere misafir olmalıyım? Evimde kalan kişilere dair nasıl önlemler alabilirim?', '2012-11-29 23:25:55', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 64652),
	('faqq_isitsafe', 'uk', 'messages', '<p>Чи є BeWelcome безпечним?</p>', '2026-04-05 22:19:17', '2026-04-05 22:19:17', '2026-04-05 22:19:17', 'no', '', 5, NULL, 573491),
	('faqq_isitsafe', 'zh-hans', 'messages', '我是新成员，如何确定其他BeWelcome成员是可信的？', '2010-09-20 06:43:33', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11819),
