	('faqq_isjoiningfree', 'ar', 'messages', 'هل الانضمام مجانى؟ كيف توفرون خدمة كهذه دون رسوم اشتراك؟', '2008-02-18 17:44:12', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 2702),
