	('faqq_isjoiningfree', 'es', 'messages', '¿Es gratis suscribirse? ¿Se pueden ofrecer servicios como éstos sin cobrar una cuota de inscripción?', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 65289),
	('faqq_isjoiningfree', 'fi', 'messages', 'Onko liittyminen ilmaista? Kuinka pystytte tarjoamaan tällaista palvelua ilman jäsenmaksuja?', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 72),
	('faqq_isjoiningfree', 'fr', 'messages', 'L\'adhésion est-elle vraiment gratuite ?', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 9823),
	('faqq_isjoiningfree', 'hr', 'messages', 'je li članstvo besplatno? Kako možete pružati ovakve usluge bez članarine?', '2009-08-19 18:55:19', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 8197),
	('faqq_isjoiningfree', 'hu', 'messages', 'A csatlakozás ingyenes? Hogyan tudok hasonló szolgáltatás nyújtani tagdíj nélkül?', '2007-08-17 11:54:20', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 34314),
	('faqq_isjoiningfree', 'id', 'messages', 'Jika keanggotaan diberikan cuma-cuma, bagaimana BeWelcome dapat menyediakan pelayanan ini tanpa biaya apapun', '2007-11-13 06:10:04', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 2019),
	('faqq_isjoiningfree', 'it', 'messages', 'Iscriversi è gratuito? Come fate ad offire un servizio del genere senza una quota d\'iscrizione?', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 16084),
	('faqq_isjoiningfree', 'ja', 'messages', '入会は無料ですか？どうして会費をを取らないでこのようなサービスを提供することができるんですか？', '2007-11-09 08:03:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1834),
	('faqq_isjoiningfree', 'lt', 'messages', 'Prisijungti nieko nekainuoja? Kaip jūs galite teikti tokias paslaugas neimdami jokio nario mokesčio?', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 227),
	('faqq_isjoiningfree', 'lv', 'messages', 'Vai pievienošanās ir bezmaksas? Kā jūs varat nodrošināt šādu servisu bez dalības maksas?', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 375),
	('faqq_isjoiningfree', 'nl', 'messages', 'Is lid worden echt gratis?  Hoe kan je een dienst als deze aanbieden zonder een lidmaatschapsbijdrage?', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 21169),
	('faqq_isjoiningfree', 'pl', 'messages', 'Czy to naprawdę nic nie kosztuje?', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('faqq_isjoiningfree', 'pt', 'messages', 'A inscrição é gratuita? Como vocês conseguem fornecer um serviço como este sem cobrar uma taxa?', '2007-07-03 18:57:25', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 15566),
	('faqq_isjoiningfree', 'pt-BR', 'messages', 'A adesão é gratuita? Como vocês podem prover um serviço como este sem que as pessoas paguem uma taxa?', '2011-09-15 02:19:09', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, 1, 15566),
	('faqq_isjoiningfree', 'ro', 'messages', 'Pot deveni membru gratuit? Cum este posibil să oferiţi un astfel de serviciu fără o taxă de membru?', '2007-08-28 18:42:06', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1081),
	('faqq_isjoiningfree', 'ru', 'messages', 'Нужно ли платить за регистрацию?', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('faqq_isjoiningfree', 'sr', 'messages', 'Да ли је учлањење бесплатно? Како можете обезбедити такав сервис без наплаћивања чланарина?', '2012-12-18 16:43:56', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 39772),
	('faqq_isjoiningfree', 'sv', 'messages', 'Är medlemskapet gratis? Hur kan ni erbjuda en tjänst som denna utan medlemsavgift?', '2012-08-16 12:03:37', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 23263),
	('faqq_isjoiningfree', 'tr', 'messages', 'Katılım ücretsiz mi? Böyle bir servisi, üyelik ücreti olmadan nasıl sağlıyorsunuz?', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 28341),
	('faqq_isjoiningfree', 'zh-hans', 'messages', '过时：免费加入？', '2010-09-20 06:46:19', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, 1, 25117),
	('faqq_isjoiningfree', 'zh-hant', 'messages', '免费加入？你们如何提供这种不收会费的服务？', '2010-09-20 06:46:19', '2021-05-02 07:48:37', '0000-00-00 00:00:00', 'no', '', 5, 1, 11819),
	('faqq_iwascontactedbutthememberforgetme', 'ar', 'messages', 'عضو اتصل بي و حدد ميعاد لاقامته عندى, لم يتصل مرة اخرى ليخبرنى عن اى تغييرات.', '2008-03-05 17:56:08', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 2702),
	('faqq_iwascontactedbutthememberforgetme', 'ca', 'messages', 'Un(a) membre s\'ha posat en contacte amb mi i hem quedat perquè l\'aculli. Aquesta persona, però, no s\'ha presentat ni m\'ha avisat d\'un canvi de plans. ', '2007-08-01 19:02:42', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 177),
	('faqq_iwascontactedbutthememberforgetme', 'cs', 'messages', 'Kontaktoval mě člen a dohodl se se mnou na datu pobytu u mě. Nikdy se ale neukázal(a) a ani mě neinfromoval(a) o změně plánu. Co mám dělat?', '2014-02-09 21:31:33', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('faqq_iwascontactedbutthememberforgetme', 'de', 'messages', 'Ein Mitglied hat mich kontaktiert und eine Ankunftszeit mit mir vereinbart. Er/sie tauchte jedoch nie bei mir auf und hat mich auch nicht über eine Planänderung informiert. Was soll ich tun?', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('faqq_iwascontactedbutthememberforgetme', 'el', 'messages', 'Ένα μέλος κανόνισε  να μείνει σε μένα αλλά δεν εμφανίστηκε ποτέ. Τι πρέπει να κάνω;', '2015-08-13 10:17:50', '2023-08-07 21:08:24', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266502),
	('faqq_iwascontactedbutthememberforgetme', 'en', 'messages', 'A member arranged to stay with me but never turned up. What should I do?', '2008-04-13 16:15:10', '2022-05-29 18:34:57', '2013-03-25 17:01:21', 'no', 'This is a question for a Faq', 5, 0, 168499),
	('faqq_iwascontactedbutthememberforgetme', 'es', 'messages', 'Una persona acordó quedarse en mi casa pero nunca apareció. ¿Qué debo hacer?', '0000-00-00 00:00:00', '2023-05-30 13:06:10', '0000-00-00 00:00:00', 'no', '', 5, NULL, 25548),
	('faqq_iwascontactedbutthememberforgetme', 'fi', 'messages', 'Jäsen otti yhteyttä ja järjestin hänelle paikan kotoani. Hän ei koskaan tullut eikä ilmoittanut suunnitelmiensa muutoksista. ', '2009-06-21 09:35:53', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 525),
	('faqq_iwascontactedbutthememberforgetme', 'fr', 'messages', 'Un membre qui devait séjourner chez moi n’est jamais venu. Que dois-je faire ?', '0000-00-00 00:00:00', '2022-05-31 20:57:48', '0000-00-00 00:00:00', 'no', '', 5, NULL, 168499),
	('faqq_iwascontactedbutthememberforgetme', 'gl', 'messages', 'Unha persoa arranxou unha estancia comigo pero nunca apareceu. Que debo facer?', '2021-01-21 16:58:50', '2024-08-06 08:28:50', '2021-01-21 16:58:50', 'no', '', 5, NULL, 210880),
	('faqq_iwascontactedbutthememberforgetme', 'hr', 'messages', 'Član me kontaktirao i dogovorio datum dolaska, ali nikada se nije pojavio niti me obavijestio o promjeni planova.', '2009-09-19 09:57:13', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('faqq_iwascontactedbutthememberforgetme', 'hu', 'messages', 'Egy tag felvette velem a kapcsolatot, és megbeszéltünk egy időpontot az érkezésére. Azonban nem jött el és nem is értesített, hogy változás történt a terveiben. ', '2007-08-18 13:19:29', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 805),
	('faqq_iwascontactedbutthememberforgetme', 'it', 'messages', 'Un membro mi ha contattato ed abbiamo concordato quando starà da me. Però non si è mai fatto vivo, né mi ha comunicato di aver cambiato idea. Cosa devo fare?', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('faqq_iwascontactedbutthememberforgetme', 'ja', 'messages', 'あるメンバーから連絡があったので、泊めてあげる日時を打ち合わせました。だが、本人は姿を見せず、計画を変更したとの連絡もしてきませんでした。', '2007-11-09 08:09:32', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1834),
	('faqq_iwascontactedbutthememberforgetme', 'lt', 'messages', 'Klubo narys susisiekė su manimi ir susitarė, kada galės pas mane pernakvoti, bet taip ir nepasirodė ir nepranešė, kad jo planai pasikeitė.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1),
	('faqq_iwascontactedbutthememberforgetme', 'lv', 'messages', 'Biedrs sazinājās ar mani un norunāja, kad pie manis paliek. Viņš ne vien neparādījās, bet arī nepainformēja mani par savām izmaiņām plānos.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 375),
	('faqq_iwascontactedbutthememberforgetme', 'nl', 'messages', 'Een lid had afgesproken om bij mij te logeren, maar is nooit komen opdagen.  Wat moet ik doen?', '0000-00-00 00:00:00', '2025-07-29 20:57:23', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('faqq_iwascontactedbutthememberforgetme', 'pl', 'messages', 'Ktoś skontaktował się ze mną i ustaliliśmy datę jego pobytu. Jednak ta osoba nigdy się u mnie nie zjawiła ani nie powiadomiła mnie o zmianie planów.', '2007-07-24 09:48:26', '2021-03-22 08:13:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 116789),
	('faqq_iwascontactedbutthememberforgetme', 'pt', 'messages', 'Um membro contactou-me e marcámos o período em que estaria comigo. Ele não apareceu e nem me avisou de qualquer mudança de planos. O que devo fazer?', '2007-07-04 13:23:12', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('faqq_iwascontactedbutthememberforgetme', 'pt-BR', 'messages', 'Um membro entrou em contato comigo para ficar hospedado em minha casa. Entretanto, ele nunca apareceu e não avisou de nenhuma mudança de planos. O que eu devo fazer?', '2016-12-26 13:09:18', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160059),
	('faqq_iwascontactedbutthememberforgetme', 'ro', 'messages', 'Un membru m-a contactat şi am stabilit o dată pentru ca el să vină şi să stea la mine. În final nu a mai ajuns şi nici nu m-a anunţat dacă şi-a modificat planurile.', '2007-08-28 18:41:23', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1081),
	('faqq_iwascontactedbutthememberforgetme', 'ru', 'messages', 'Со мной связался человек, и мы договорились, что я приму его в гости. В результате он так и не появился, и даже не позаботился предупредить меня об изменившихся планах. Что я должен сделать?', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('faqq_iwascontactedbutthememberforgetme', 'sr', 'messages', 'Члан ме је контактирао и договорили смо дан за његов/њен останак код мене. Он/она се није појавио/ла, нити обавестио/ла о својим променама у плану. Шта да радим?', '2015-02-21 23:14:41', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('faqq_iwascontactedbutthememberforgetme', 'uk', 'messages', 'Користувач організував зустріч зі мною, але так і не з\'явився. Що мені робити?', '2026-04-11 20:15:00', '2026-04-11 20:15:00', '2026-04-11 20:15:00', 'no', '', 5, NULL, 573491),
