	('faqq_pleasesignmeupquickly', 'cs', 'messages', 'Právě jsem se zapsal(a) na BeWelcome, ale nepřišel mi ověřovací e-mail a nemůžu se přihlásit na svůj účet. Můžete mi pomoci?', '2014-01-16 19:16:36', '2023-09-20 05:40:14', '0000-00-00 00:00:00', 'no', '', 5, 1, 34292),
	('faqq_pleasesignmeupquickly', 'da', 'messages', 'Er der en måde at sætte fart på optagelsesprocessen? Jeg vil gerne bruge siderne så hurtigt som muligt.', '0000-00-00 00:00:00', '2023-09-20 05:40:14', '0000-00-00 00:00:00', 'no', '', 5, 1, 74),
	('faqq_pleasesignmeupquickly', 'de', 'messages', 'Ich habe mich gerade für BeWelcome registriert, aber noch keine Bestätigung per E-Mail erhalten und kann mich daher nicht anmelden. Könnt ihr mir helfen?', '0000-00-00 00:00:00', '2023-09-20 05:40:14', '0000-00-00 00:00:00', 'no', '', 5, 1, 15240),
	('faqq_pleasesignmeupquickly', 'el', 'messages', 'Μόλις έκανα εγγραφή στο BeWelcome αλλά δεν έλαβα e-mail επιβεβαίωσης και δεν μπορώ να συνδεθώ στο λογαριασμό μου. Μπορείτε να με βοηθήσετε;', '2010-05-04 22:59:14', '2023-09-20 05:40:14', '0000-00-00 00:00:00', 'no', '', 5, 1, 16526),
