	('feedbackemailneeded', 'ar', 'messages', 'من فضلك زودنا بعنوان بريدك الالكترونى كى تحصل على اجابة', '2008-02-11 05:23:39', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 2702),
	('feedbackemailneeded', 'bg', 'messages', 'Посочете Е-мейл за обратна връзка', '2008-02-23 17:02:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 851),
	('feedbackemailneeded', 'ca', 'messages', 'Si us plau, proporciona\'ns una adreça d\'email si vols que et responem', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11944),
