	('feedbackemailneeded', 'de', 'messages', 'Wenn du eine Antwort per E-Mail haben möchtest, gib bitte deine E-Mail-Adresse an.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3050),
