	('feedbacksent', 'ar', 'messages', 'شكرا لاستخدامكم استمارة الافادة هذه. طلبك سيتم فحصه بواسطة المتطوعين بأسرع وقت', '2008-03-12 15:47:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 2702),
	('feedbacksent', 'ca', 'messages', 'Gràcies per fer servir el formulari de <i>feedback</i>.<br><br>Els nostres voluntaris processaran la teva petició tan aviat com puguin.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('feedbacksent', 'da', 'messages', 'Tak fordi du brugte feedback-funktionen.\r\n\r\nDin forespørgsel vil blive behandlet hurtigst muligt af vores frivillige.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 74),
	('feedbacksent', 'de', 'messages', 'Danke für dein Feedback! Deine Anfrage wird durch frewillige Mitarbeiter bearbeitet und so schnell wie möglich beantwortet.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('feedbacksent', 'el', 'messages', 'Ευχαριστούμε που χρησιμοποίησες τη φόρμα επικοινωνίας. \r\n\r\nΤο αίτημά σου θα δρομολογηθεί από τους εθελοντές μας όσο πιο σύντομα γίνεται.', '2013-07-22 16:33:15', '2020-09-02 11:02:07', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('feedbacksent', 'en', 'messages', 'Thanks for using this feedback form.\r\n\r\nYour request is going to be processed by our volunteers as soon as possible.', '2007-06-28 09:45:55', '2019-04-23 18:16:49', '2008-04-13 16:16:26', 'no', 'This is the message which is display to the member when he has  filled and submitted a feedback (using the Contact Us page)', 5, NULL, 91),
	('feedbacksent', 'eo', 'messages', 'Dankon pro uzo de tiu opinia formularo.\r\n\r\nVia peto estos prizorgata de niaj vonlontuloj plej rapide laŭ nia eblo.', '2007-09-12 02:23:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1769),
	('feedbacksent', 'es', 'messages', 'Gracias por usar esta forma de contacto.\r\n\r\nLa solicitud será procesada por voluntarios lo más pronto posible.', '2007-11-17 02:34:57', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1328),
	('feedbacksent', 'eu', 'messages', 'Eskerrik asko gurekin harremanetan jartzeagatik.\r\n\r\nGure boluntarioek zure eskaera ahal bezain pronto prozesatuko dute.', '2013-05-10 21:50:16', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11907),
	('feedbacksent', 'fi', 'messages', 'Kiitoksia palautteesta! \r\n\r\nVapaaehtoistyöntekijät tulevat käsittelemään sen mahdollisimman pian.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 72),
	('feedbacksent', 'fr', 'messages', 'Merci de votre message.\r\n\r\nVotre demande / remarque sera traitée dès que possible par l\'un de nos volontaires.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 67),
	('feedbacksent', 'gl', 'messages', 'Grazas por usar o formulario de contacto. \r\nA túa solicitude vai ser procesada polas persoas voluntarias tan pronto como sexa posible.', '2022-09-12 08:20:48', '2022-09-12 08:30:42', '2022-09-12 08:20:48', 'no', '', 5, NULL, 210880),
	('feedbacksent', 'he', 'messages', 'תודה שהשתמש בטופס המשוב.\r\nהבקשה שלך תטופל על-ידי המתנדבים שלנו בהקדם.', '2022-07-11 18:06:15', '2022-07-11 18:06:15', '2022-07-11 18:06:15', 'no', '', 5, NULL, 290109),
	('feedbacksent', 'hr', 'messages', 'Zahvaljujemo na korištenju obrasca za povratne informacije.\r\n\r\nTvoj zahtjev volonteri će pregledati čim stignu.', '2010-01-05 10:34:35', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('feedbacksent', 'hu', 'messages', 'Köszönjük, hogy használtad a visszajelzés funkciót. Kérelmedet amint lehet feldolgozzák az önkéntesek.', '2007-08-24 07:22:20', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 805),
	('feedbacksent', 'it', 'messages', 'Grazie per avere usato questo modulo di contatto.\r\n\r\nLa tua richiesta sarà evasa nel più breve tempo possibile da parte dei nostri volontari.', '0000-00-00 00:00:00', '2020-12-18 08:22:53', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160610),
	('feedbacksent', 'ja', 'messages', 'フィードバック、ありがとうございます<br><br>私たちのボランティア。メンバーができるだけ早く、あなたのリクエストへ対応します。\r\n', '2007-11-09 09:13:23', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1834),
	('feedbacksent', 'lt', 'messages', 'Ačiū, kad netingi išsiųsti mums savo atsiliepimą/pasiūlymą. \r\n\r\nAtsakingi BeWelcome savanoriai greitu metu peržiūrės tavo žinutę. ', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('feedbacksent', 'lv', 'messages', 'Paldies, ka izmantoji komentāru formu.\r\n\r\nTavu lūgumu cik ātri vien iespējams izskatīs mūsu brīvprātīgais.', '2007-08-05 14:16:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 375),
	('feedbacksent', 'nl', 'messages', 'Dank je voor je feedback.\r\n\r\nJe aanvraag wordt zo snel mogelijk behandeld door onze vrijwilligers.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('feedbacksent', 'pl', 'messages', 'Dziekujemy za wypełnienie tego formularza. Nasi wolontariusze zajmą się Twoim zgłoszeniem najszybciej jak to tylko możliwe.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1),
	('feedbacksent', 'pt', 'messages', 'Obrigado por utilizar o formulário de contacto.\r\n\r\nO seu pedido será processado pelos nossos voluntários assim que possível.', '2007-07-16 12:40:15', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('feedbacksent', 'ro', 'messages', 'Mulţumim că foloseşti acest formular de feedback.\r\n\r\nCererea ta va fi procesată de unul din voluntarii noştri cât de curând.', '2007-08-30 17:34:32', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1081),
	('feedbacksent', 'ru', 'messages', 'Спасибо за обратную связь! \r\nНаши волонтеры постараются обработать ваш запрос как можно скорее', '2007-09-09 08:03:54', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 79),
	('feedbacksent', 'sv', 'messages', 'Tack för att använda denna feedback form.\r\n\r\nDin begäran kommer att behandlas av våra volontärer så snart som möjligt.', '2012-07-07 21:39:48', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 23263),
	('feedbacksent', 'tr', 'messages', 'Geri Bildirim formunu kullandığınız için teşekkür ederiz. İsteğiniz en kısa zamanda gönüllülerimiz tarafından işleme alınacaktır.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 140),
