	('forumnotloggedin', 'pt', 'messages', 'Os fóruns apenas estão acessíveis a membros do BeWelcome. Por favor, autentique-se para os ver.', '2015-06-29 00:40:42', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
