	('forumnotloggedinornotingroup', 'fr', 'messages', 'Vous n\'êtes pas membre de ce groupe ou vous devez vous connecter pour voir cette conversation.', '2015-07-27 20:43:59', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
