	('forumnotloggedinornotingroup', 'pt-BR', 'messages', 'Você não é membro deste grupo ou precisa estar logado para visualizar este tópico.', '2016-12-20 15:54:46', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160059),
	('forumnotloggedinornotingroup', 'ru', 'messages', 'Либо Вы не являетесь участником данной группы, либо Вам необходимо войти под своей учетной записью, чтобы смотреть эту тему. ', '2014-04-20 16:47:47', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('forumnotloggedinornotingroup', 'sr', 'messages', 'Или ниси члан групе или се мораш пријавити да би видео ову тему.', '2014-06-12 10:05:26', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('forumnotloggedinornotingroup', 'tr', 'messages', 'Ya bu grubun üyesi değilsiniz ya da bu başlığı görüntülemek için giriş yapmanız gerekiyor.', '2014-07-24 00:15:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21566),
	('forumonlyforbewelcomemember', 'ca', 'messages', 'Has d\'haver iniciat la sessió com a membre de BeWelcome per utilitzar el contingut complet del fòrum', '2009-06-23 13:28:29', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 5533),
	('forumonlyforbewelcomemember', 'de', 'messages', 'Du musst als BeWelcome Mitglied <a href="login">angemeldet</a> sein oder dich als neues Mitglied  <a href="signup">registrieren</a>, um den gesamten Inhalt dieses Forums zu sehen und alle Funktionen nutzen zu können. ', '2009-02-03 17:18:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('forumonlyforbewelcomemember', 'el', 'messages', 'Πρέπει να είσαι  <a href="login">συνδεδεμένος</a> ως μέλος του BeWelcome ή <a href="signup">να εγγραφείς</a>για να μπορείς να δεις ολόκληρο το περιεχόμενο αυτού του φόρουμ', '2020-08-21 20:35:09', '2020-08-21 20:35:09', '2020-08-21 20:35:09', 'no', '', 5, NULL, 266544),
	('forumonlyforbewelcomemember', 'en', 'messages', 'You must be <a href="login">logged in</a> as a BeWelcome member or <a href="signup">signup</a> to be able to use the whole content of this forum', '2009-01-22 16:33:09', '2019-04-23 18:16:49', '2010-01-06 17:03:39', 'no', 'This is the message the not logged in people can read when they browse the main page of the BW forum', 5, NULL, 347),
	('forumonlyforbewelcomemember', 'es', 'messages', 'Usted debe conectarse como miembro BeWelcome o registrarse para poder utilizar el contenido completo de este foro', '2011-11-19 09:08:05', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8437),
	('forumonlyforbewelcomemember', 'fr', 'messages', 'Pour pouvoir utiliser l\'ensemble des fonctions du forum, vous devez vous <a href="login">identifier</a> en tant que membre BeWelcome.', '2009-01-22 16:33:55', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('forumonlyforbewelcomemember', 'gl', 'messages', '<p>Tes que <a href="https://beta.bewelcome.org/login">acceder</a> como persoa membro de BeWelcome ou <a href="https://beta.bewelcome.org/signup">rexistrarte </a>para poder usar todo o contido de este foro</p>', '2021-11-29 08:42:51', '2021-11-29 08:42:51', '2021-11-29 08:42:51', 'no', '', 5, NULL, 210880),
	('forumonlyforbewelcomemember', 'it', 'messages', 'Devi fare <a href="login">login</a>come membro di BeWelcome o <a href="signup">registrarti</a> per accedere agli interi contenuti del forum', '2009-01-25 15:14:48', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 16084),
	('forumonlyforbewelcomemember', 'nl', 'messages', 'Je moet <a href="login">aangemeld</a> zijn als lid van BeWelcome of <a href="signup">je inschrijven</a> om de hele inhoud van dit forum te kunnen gebruiken.', '2013-05-17 18:53:22', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('forumonlyforbewelcomemember', 'pl', 'messages', 'Musisz się <a href="login">zalogować</a> do BeWelcome albo <a href="signup">zarejestrować,</a> Żeby móc korzystać z wszystkich funkcji forum.', '2021-01-14 17:46:07', '2021-01-14 17:46:07', '2021-01-14 17:46:07', 'no', '', 5, NULL, 116789),
	('forumonlyforbewelcomemember', 'pt', 'messages', 'Tem de estar <a href="login">identificado</a> como membro BeWelcome ou <a href="signup">inscrever-se</a> para poder usar todo o conteúdo deste fórum', '2014-01-08 18:44:58', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('forumonlyforbewelcomemember', 'ru', 'messages', 'Вы должны <a href="login">войти на сайт</a>, чтобы имет возможность видеть все содержание Форума.', '2014-05-17 17:36:40', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
