	('forumrulescharterheadline2', 'es', 'messages', 'Esta Normativa se aplica a los Foros y Grupos', '2008-01-09 23:25:16', '2022-07-24 11:13:18', '0000-00-00 00:00:00', 'no', '', 5, NULL, 25548),
	('forumrulescharterheadline2', 'fr', 'messages', 'Cette charte s\'applique au forum et aux groupes', '2007-12-01 21:42:12', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('forumrulescharterheadline2', 'gl', 'messages', 'Estes estatutos se aplican ao Foro e ao Foro dos Grupos', '2021-01-25 10:52:03', '2021-01-25 10:52:03', '2021-01-25 10:52:03', 'no', '', 5, NULL, 210880),
	('forumrulescharterheadline2', 'hr', 'messages', 'Ova Povelja', '2010-04-14 13:52:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('forumrulescharterheadline2', 'it', 'messages', ' Questa carta si applica al Forum e ai gruppi del forum.', '2007-12-31 13:15:55', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('forumrulescharterheadline2', 'lt', 'messages', 'Ši Chartija', '2007-12-17 05:07:24', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('forumrulescharterheadline2', 'nl', 'messages', 'Dit charter heeft betrekking op het forum en de groepen', '2012-11-27 20:54:57', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11040),
	('forumrulescharterheadline2', 'pl', 'messages', 'Poniższy rozdział dotyczy forum i grup', '2013-01-03 01:23:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 35248),
	('forumrulescharterheadline2', 'pt', 'messages', 'Estas Normas aplicam-se ao Fórum e aos Fóruns de Grupos', '2013-08-13 16:44:51', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('forumrulescharterheadline2', 'ru', 'messages', 'Этот Устав применяется к Форуму и Группам на Форуме', '2014-05-11 08:02:07', '2025-03-25 15:22:23', '0000-00-00 00:00:00', 'no', '', 5, NULL, 519603),
	('forumrulescharterheadline2', 'sr', 'messages', 'Ово поглавље се односи на Форум и Форуме група.', '2015-02-12 18:32:40', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('forumrulescharterheadline2', 'zh-hans', 'messages', '此章程适用于论坛及群组论坛', '2013-02-13 17:53:41', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37722),
	('forumrulescharterheadline2', 'zh-hant', 'messages', '本章程適用於論壇和群組論壇', '2013-02-13 17:53:41', '2025-05-31 22:41:52', '0000-00-00 00:00:00', 'no', '', 5, NULL, 53422),
	('forumruleschartertext1', 'ca', 'messages', 'Tothom pot expressar l\'opinió de com fer que BeWelcome sigui un web millor i una comunitat més forta. Si tens cap problema amb BW o vols fer una suggerència constructiva, t\'animem que en parlis aquí al fòrum. En alguns casos, potser és millor que ens enviïs directament un missatge mitjançant la <a href="bw/feedback.php">pàgina de contacte</a> (per exemple, si tens problemes amb el teu compte personal). De totes maneres, en molts casos és millor iniciar un debat al fòrum per a veure què en pensen la resta de membres. Una vegada hi hagi un consens entre els participants del fòrum, ens pots enviar un missatge amb el resultat de la discussió.<br>Tothom pot parlar sobre funcions noves que voldria veure al web, ja que creiem que les bones idees no haurien de mantenir-se en secret. Si a altres comunitats els agraden les funcions que discutim aquí, que les facin servir! Servirà per a enfortir l\'intercanvi d\'hospitalitat. Això no obstant, recorda que simplement pel fet de voler una cosa, això no implica que tinguem la capacitat de poder-la proporcionar.', '2008-05-15 10:23:54', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11944),
	('forumruleschartertext1', 'de', 'messages', 'Mitglieder dürfen frei darüber diskutieren, wie BeWelcome verbessert und die Gemeinschaft gestärkt werden kann. Falls du Probleme mit BeWelcome hast oder konstruktive Vorschläge machen möchtest, bist du herzlich willkommen, diese im Forum zu diskutieren. Manchmal kann es nützlicher sein, uns eine kurze Nachricht zu schicken (benutze hierfür das <a href="bw/feedback.php">"Kontaktformular"</a>), zum Beispiel bei Problemen mit dem persönlichen Profil. Bei anderen Themen kann es jedoch besser sein, diese erst im Forum anzusprechen und zu erfahren, was andere Mitglieder darüber denken. Gibt es in einer Diskussion Konsens zu wichtigen Fragen, so kannst du uns im nächsten Schritt mit den Ergebnissen der Diskussion kontaktieren.\r\nBesonders Ideen für neue Werkzeuge ("Features") dürfen und sollen im Forum zusammengetragen und diskutiert werden, denn gute Vorschläge sollten nicht geheim bleiben! Falls andere Netzwerke dieselben Features dann auch gut finden - umso besser, denn wir wollen Gastfreundschaft und Austausch fördern, auch über die Grenzen von BeWelcome hinaus. Bitte sei dir aber im Klaren, dass deine Idee oder Wunsch nach einem neuen Feature nicht automatisch bedeutet, dass unsere ehrenamtlichen Helfer dieses auch realisieren können.', '2007-12-14 08:02:43', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('forumruleschartertext1', 'el', 'messages', 'Σε όλους επιτρέπεται να μιλούν για το πώς θα γίνει το BeWelcome ένας καλύτερος ιστότοπος και μια δυνατότερη κοινότητα. Αν έχεις κάποιο θέμα με το BW, ή θέλεις να κάνεις εποικοδομητικές προτάσεις, είσαι ευπρόσδεκτος να μιλήσεις για αυτά εδώ στο φόρουμ. Σε κάποιες περιπτώσεις ίσως είναι καλύτερο να μας στείλεις απ\' ευθείας ένα μήνυμα μέσω της φόρμας <a href="feedback">«Επικοινωνία»</a> (σε περίπτωση προβλήματος με τον προσωπικό σου λογαριασμό, για παράδειγμα). Όμως σε άλλες περιπτώσεις ίσως είναι καλύτερο να ξεκινήσεις μία συζήτηση εδώ στο φόρουμ ώστε να δεις τι πιστεύουν τα υπόλοιπα μέλη. Όταν υπάρξει μια επικρατούσα άποψη ανάμεσα στους αναγνώστες του φόρουμ, μπορείς να επικοινωνήσεις μαζί μας ευθέως με τα αποτελέσματα της συζήτησης.\r\nΌλοι μπορούν να συζητούν για καινούρια χαρακτηριστικά, αφού πιστεύουμε ότι οι καλές ιδέες δεν πρέπει να μένουν μυστικές. Αν τα χαρακτηριστικά που προτείνονται εδώ αρέσουν και σε άλλες κοινότητες, ας τα χρησιμοποιήσουν! Αυτό μόνο δυνατότερη μπορεί  να κάνει την Ανταλλαγή Φιλοξενίας. Παρόλα αυτά, να θυμάσαι ότι επειδή κάτι το θέλεις, δε σημαίνει και ότι μπορούμε να το παρέχουμε.', '2017-07-24 19:04:19', '2020-09-02 15:55:21', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('forumruleschartertext1', 'en', 'messages', '<p>Everybody is allowed to talk about making BeWelcome a better website and a stronger community. If you have any issues with BW, or want to make constructive suggestions, you are more than welcome to talk about them here on the forum. In some cases it might be better to send us directly a message through the “<a href="feedback">contact us”</a> form (in case of a problem with your personal account, for example). But in other cases, it might be better to start a discussion here on the forum to see what other members feel. Once there is a consensus amongst the other readers of this forum, you could then contact us directly with the results of the discussion. Everybody can discuss new features, since we believe that good ideas should not be kept a secret. If other communities like the features discussed here, let them use it! It can only make Hospitality Exchange stronger. However, please remember that because you want something, it doesn’t necessarily mean we can provide it.</p>', '2007-11-29 20:58:32', '2025-01-18 21:02:55', '2010-02-28 10:33:08', 'no', 'Forum rules', 5, 0, 21169),
	('forumruleschartertext1', 'es', 'messages', '<p>Cualquier persona puede opinar sobre cómo hacer de BeWelcome un mejor sitio web y una comunidad más fuerte. Si tienes algún problema con BW o deseas hacer sugerencias constructivas, te animamos a comentarlas aquí en el foro. En algunos casos podría ser mejor enviarnos un mensaje directo a través del <a href="https://www.bewelcome.org/feedback">Formulario de Contacto</a> (por ejemplo, si tienes algún problema con tu cuenta personal). Pero, en otros casos, puede ser mejor iniciar un tema en los foros para saber qué opinan otras personas. Cuando exista un consenso entre las personas que participen del foro, puedes remitirnos las conclusiones. Cualquier persona puede proponer nuevas funcionalidades, creemos que las buenas ideas deben ser compartidas. Si a otras comunidades les gustan las ideas que vean por aquí ¡que las usen! De esa forma se fortalecerán aún más los intercambios de hospitalidad. En cualquier caso, recuerda que el hecho de que quieras algo no significa necesariamente que lo podamos ofrecer.</p>', '2007-12-31 04:12:11', '2025-05-03 16:51:27', '0000-00-00 00:00:00', 'no', '', 5, NULL, 25548),
	('forumruleschartertext1', 'fr', 'messages', 'Chacun peut intervenir pour améliorer BeWelcome et renforcer la communauté. Si ces sujets vous préoccupent, ou si vous avez des suggestions constructives, nous vous invitons à le faire sur le forum.\r\nIl est parfois plus efficace de nous envoyer un message via le <a href="bw/feedback.php">formulaire de contact</a> (en cas de problème personnel par exemple). Dans la plupart des cas, il est plus intéressant de confronter ses idées à celles des autres membres. Une fois qu’un consensus est trouvé et que l\'idée est claire, veuillez nous contacter directement.\r\nToute bonne idée gagne à être partagée et nous invitons tout les membres à échanger au sujet de nouvelles fonctionnalités. Si d\'autres communautés similaires apprécient nos idées, nous partageons ! Cela ne peut qu\'améliorer le concept d’échange d’hospitalité.\r\nRappelez-vous cependant que nous ne pouvons pas réaliser toutes les bonnes idées.\r\n', '2007-12-06 22:11:34', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('forumruleschartertext1', 'gl', 'messages', 'Calquera pode falar sobre como facer un mellor sitio web para BeWelcome e unha comunidade máis forte. Se tes algún problema con BW, ou queres facer suxestións construtivas, dámosche a benvida para falar sobre iso aquí no foro. Nalgún caso, pode que sexa mellor enviarnos unha mensaxe directamente a través do formulario de <a href="feedback">"contáctanos"</a> (por exemplo no caso dun problema coa túa conta persoal). Mais en outros casos pode ser mellor iniciar unha discusión aquí no foro para ver que é o que outras persoas da comunidade senten. Cando haxa un consenso entre outras persoas lectoras do foro, ti podes poñerte en contacto con nós cos resultados da discusión. \r\nCalquera pode propoñer novas características, pois cremos que as boas ideas non deben manterse en segredo. Se outras comunidades gustan das características que se discutan aquí, que as usen! Iso só facer que o Intercambio de Hospitalidade sexa máis forte. Porén, lembra que porque ti queiras algo, iso non significa necesariamente que podamos proporcionalo.', '2021-01-25 11:15:23', '2021-01-25 11:15:23', '2021-01-25 11:15:23', 'no', '', 5, NULL, 210880),
	('forumruleschartertext1', 'hr', 'messages', 'Svakome je dopušteno razgovarati kako učiniti BeWelcome stranice boljima i ojačati zajednicu. ako imaš problema s BW ili želiš dati konstruktivni prijedlog, dobrodošao/la si rasporavljati o tome ovdje na forumu.Ponekad je bolje izravno nam poslati poruku preko <a href="feedback">"contact us"</a> formulara (npr. u slučaju da se radi o problemu s tvojim korisničkim računom). U ostalim slučajevima, možda je bolje započeti raspravu ovdje na forumu da vidiš što drugi forumaši misle o tome. Kada ste postigli konsensus pošalji nam izravno zaključak rasprave.\r\nSvatko može raspravljati o novitetima, vjerujemo da da dobre zamisli ne bi trebale biti tajnom. Ako se drugim zajednicama svide naši noviteti, neka ih koriste! To će još više ojačati razmjenu gostoprimstva. Imaj samo na umu da zato što ti nešto želiš ne znači nužno da ti mi tu želju možemo ostvariti.', '2009-08-31 15:24:34', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('forumruleschartertext1', 'it', 'messages', 'Ognuno è autorizzato a discutere su come fare diventare BeWelcome un miglior sito ed una comunità più forte. Se avete un problema con BW, o volete fare un suggerimento costruttivo, siete benvenuti a parlarne qui nel forum. In alcuni casi potrebbe essere meglio scriverci direttamente un messaggio tramite il modulo “contattaci” ( per esempio in caso di un problema con il tuo account personale). Però in altri casi può essere meglio iniziare una discussione qui nel forum per vedere cosa ne pensano altri membri. Se ci dovesse essere un consenso anche tra gli altri lettori di questo forum, potresti poi contattarci direttamente con i risultati della discussione. Ognuno può discutere nuovi strumenti, perché crediamo che le buone idee non debbano essere tenute segrete. Se gli strumenti discussi qui dovessero piacere ad altre comunità, lasciamo che le usino! Ciò può solo rendere lo scambio d’ospitalità più forte. Però per favore ricorda che il fatto di volere qualcosa non vuole dire che possiamo anche mettere tale cosa a disposizione.', '2007-12-27 19:28:32', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 13861),
	('forumruleschartertext1', 'lt', 'messages', 'Kiekvienas gali kalbėtis ir tartis dėl BeWelcome svetainės tobulinimo bei šio projekto bendruomenės stiprinimo. Jei jūs turite kokių nors problemų su BeWelcome ar norite pateikti konstruktyvų pasiūlymą, jūs galite parašyti apie tai šiame forume. Tam tikrais atvejais būtų efektingiau, jei rašytumėte mums tiesiogiai per <a href="bw/feedback.php">"Susisiekite su mumis"</a> formą (pavyzdžiui, tuo atveju, jei turėsite problemų su savo asmenine anketa). Tačiau kitais atvejais būtų geriau pradėti diskusiją šiame forume, kai norima sulaukti ir kitų narių nuomonių. Kai bus pasiektas bendras susitarimas tarp pasisakančiųjų forume, jūs galėtumėte tada susisiekti su mumis tiesiogiai, pateikdami diskusijos rezultatus. \r\nKiekvienas narys gali aptarinėti kiek egzistuojančias, tiek potencialias BeWelcome ypatybes/funkcijas; mes manome, kad geros idėjos neturi būti laikomos paslaptyje. Jei kitoms bendruomenėms patiktų funkcijos, aptartos forume, leiskime ir joms naudotis šiomis ypatybėmis! Tai tik sustiprintų globalinį apsikeitimą svetingumu! Tačiau atsiminkite: tik todėl, kad jūs norite kažko, ne būtinai reiškia, kad mes galime aprūpinti jus tuo.', '2007-12-31 00:02:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('forumruleschartertext1', 'nl', 'messages', '<p>Het is iedereen toegestaan om te praten over hoe we van BeWelcome een betere website en een hechtere gemeenschap kunnen maken. &nbsp;Als je zaken over BW te bespreken of constructieve suggesties hebt, voel je dan vrij ze hier op het forum te bespreken. &nbsp;In sommige gevallen is het beter ons een bericht te sturen via het formulier <a href="feedback">“contacteer ons”</a> (bijvoorbeeld bij problemen met je eigen profiel). &nbsp;Maar in andere gevallen is het beter dingen op het forum te plaatsen, om te zien wat andere leden hierover denken. &nbsp;Als er een consensus is bereikt onder de lezers van dit forum, kan je ons contacteren met de resultaten van de discussie. &nbsp;Iedereen kan nieuwe ideeën aanbrengen, want we geloven dat goede ideeën niet geheim mogen blijven. &nbsp;Als andere gemeenschappen deze ideeën leuk vinden, laat hen ze gebruiken! &nbsp;Het zal de idee van gastvrijheidsuitwisseling ten goede komen. &nbsp;Hou er wel rekening mee dat niet alles wat je wil door ons kan aangeboden worden.</p>', '2012-12-15 12:38:45', '2025-01-30 20:13:51', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('forumruleschartertext1', 'pl', 'messages', 'Każdy jest zaproszony do dyskusji o tym, jak ulepszać stronę BeWelcome i wzmacniać jego społeczność. Jeśli masz problemy z BW lub chcesz przedstawić konstruktywne sugestie, możesz porozmawiać o nich na forum. Czasem wygodniej jest wysłać nam wiadomość bezpośrednio przez formularz <a href="feedback">„napisz do nas”</a> (np. w przypadku problemu z kontem osobistym). W innych przypadkach lepiej rozpocząć dyskusję na forum i porównać swoje odczucia z tymi innych członków. Po osiągnięciu konsensusu z czytelnikami forum możesz skontaktować się bezpośrednio z nami w sprawie wyników dyskusji.\r\nKażdy może omówić nowe funkcje, ponieważ uważamy, że dobre pomysły nie powinny być trzymane w tajemnicy. Jeśli inne społeczności uznają omawiane tu funkcje za użyteczne też dla siebie, pozwól im z nich korzystać! Takie działanie może tylko pomóc wzmocnić idee hospex (wielokierunkowej gościnności). Pamiętaj jednak, że fakt iż czegoś chcesz, nie oznacza od razu, że możemy to zapewnić.', '2021-01-17 00:42:23', '2021-01-17 00:42:23', '2021-01-17 00:42:23', 'no', '', 5, NULL, 116789),
	('forumruleschartertext1', 'pt', 'messages', 'Todos podem discutir sobre como melhorar o sitio BeWelcome e fortalecer a comunidade. Se têm algum problema com o BW, ou deseja realizar criticas construtivas ou sugestões, é mais do que bem vindo para falar no fórum. Em alguns casos pode ser preferível enviar uma mensagem diretamente para nós através do formulário <a href="feedback">"contate-nos"</a> (no caso de problemas com a sua conta por exemplo).\r\nMas noutros casos é melhor começar uma discussão no fórum para averiguar o que outros membros pensam. Uma vez que exista um consenso entre os outros leitores deste fórum, pode então contatar-nos diretamente com as conclusões.\r\nTodos podem discutir novas funcionalidades, visto que acreditamos que as boas ideias não devem ser segredo. Se outra comunidade gostar das funcionalidades discutidas aqui, deixem-nos usa-las, só pode fortalecer a Troca de Hospitalidade. No entanto lembre-se que por querer algo não significa que lho possamos fornecer.', '2013-01-29 09:29:28', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 30452),
	('forumruleschartertext1', 'pt-BR', 'messages', 'Todos nós podemos falar a respeito do BeWelcome e fazer com que essa comunidade se torne cada vez mais forte.Se você tem algo a acrescentar ao BW ou deseja fazer uma sugestão construtiva, você é mais do que bem vindo para falar aqui no fórum.Talvez em alguns casos seja melhor que nos envie diretamente uma mensagem a <a href="feedback"> "contato" </a> (em caso de problema com sua conta pessoal por exemplo).Mas de outra forma seria melhor começar uma discussão aqui mesmo no fórum assim você poderá receber opiniões de outros membros também. Uma vez que todos os membros do fórum cheguem a um consenso você certamente  poderá entrar diretamente em contato conosco com os resultados da discussão.\r\nNovas caracteristícas e apresentações podem ser discutidas por todos,até porque acreditamos que boas idéias nao deveriam ser mantidas em segredo.Se outras comunidades gostarem das apresentaçoes discutidas aqui, deixe eles usarem isso também! Assim, Hospitalidade ficará cada vez melhor. Entretanto lembre-se por favor que náo é porque você deseja algo, que isso necessariamente significa que podemos providenciar .\r\n', '2010-05-28 15:05:50', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 7626),
	('forumruleschartertext1', 'ru', 'messages', 'Каждому позволено говорить о том, как сделать BeWelcome лучшим сайтом и более сильным Сообществом. Если у Вас есть какие-либо замечания к BW или Вы хотите внести конструктивное предложение, мы будем очень рады, если Вы сделаете это здесь, на Форуме. В некоторых случаях будет более разумно отправить нам сообщение при помощи формы <a href="feedback">"Свяжитесь с нами"</a> (например, в случае проблемы с Вашим персональным аккаунтом). Но в других случаях будет лучше начать обсуждение на Форуме, чтобы увидеть, что думают другие участники. Как только будет достигнуто согласие с другими читателями Форума, Вы можете связаться с нами напрямую и сообщить результаты этого обсуждения. \r\nКаждый может начать обсуждение нового функционала, потому что мы уверены, что хорошие идеи не должны храниться в секрете. Если другим сообществам понравится обсуждаемый здесь функционал, пусть смело его используют! Это поможет нам сделать Обмен Гостеприимством прочнее. Помните, однако, что если Вы чего-то хотите, мы не всегда сможем это обеспечить.', '2014-05-17 17:25:35', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('forumruleschartertext1', 'sr', 'messages', 'Свима је дозвољено да причају о прављењу BeWelcome-а бољим местом и снажнијом заједницом. Ако имаш икаквих проблема са BW, или желиш да даш конструктиван предлог, више си него добродошао да причаш о њима овде на форуму. У неким случајевима је боље послати директну поруку <a href="feedback">овде</a> (нпр. за проблеме са своим налогом). А у другим случајевима, можда је боље започети дискусију на форуму, да би се видело шта други чланови мисле. Када се појави концензус међу другим читаоцима форума, онда би могао да нас директно контактираш са резултатима дискусије. \r\nСви треба да дискутују о новим својствима, јер верујемо да добре идеје не треба држати у тајности. Ако се другим заједницама свиђа својство о ком је дискутовано, нека га користе! То само може направити мрежу за размену гостопримства јачом. Ипак, имај на уму да ако ко има нешто што желиш, то не значи да ми то можемо обезбедити.', '2015-02-20 23:13:08', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('forumruleschartertext1', 'zh-hant', 'messages', '<p>歡迎大家討論如何讓 BeWelcome 成為更好的網站和更強大的社群。如果您對 BeWelcome 有任何疑問，或想提出建設性的建議，非常歡迎您在論壇上提出。</p><p>在某些情況下，直接透過「聯絡我們」表單發送訊息可能會更好（例如，您的個人帳戶有問題時）。但在其他情況下，最好是在論壇上發起討論，看看其他成員的感受。一旦論壇成員們達成共識，您就可以直接將討論結果傳達給我們。</p><p>每個人都可以討論新功能，因為我們相信好的想法不應該保密。如果其他社群喜歡這裡討論的功能，就讓他們使用吧！這只會讓換宿交流變得更強大。不過，請記住，您想要的東西，我們不一定能夠提供。</p>', '2025-05-31 22:33:00', '2025-05-31 22:33:00', '2025-05-31 22:33:00', 'no', '', 5, NULL, 53422),
	('forumruleschartertext2', 'ca', 'messages', 'La honestedat és un valor important en aquest fòrum, però pot ésser que el que tu consideris com a cert no ho sigui per als altres. Per això, ens comprometem que siguin visibles per a tothom el casos que els moderadors del fòrum editin o esborrin un article. En el cas infreqüent que haguem posat algú sota premoderació per incompliment reincident de les normes, informarem aquesta persona.', '2008-05-13 08:38:48', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('forumruleschartertext2', 'de', 'messages', 'Ehrlichkeit ist ein wichtiger Wert in diesem Forum, doch was du für wahr und richtig hältst ist nicht unbedingt dasselbe, was andere für wahr und richtig halten. Daher versprechen wir, dass wir es für alle sichtbar machen, wenn und falls die Moderatoren eine Nachricht ändern oder löschen. In den selten Fällen, wo wir jemaden wegen wiederholter Verstöße gegen die Regeln vom Forum und den Gruppen ausschließen müssen, informieren wir das betroffene Mitglied über den Ausschluss und die Dauer.', '2007-12-14 08:17:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('forumruleschartertext2', 'el', 'messages', 'Η ειλικρίνεια είναι σημαντική αξία σε αυτό το φόρουμ, όμως το τι πιστεύεις εσύ πως είναι αλήθεια μπορεί να μην είναι αυτό που πιστεύουν οι άλλοι. Συνεπώς, υποσχόμαστε να το κάνουμε ορατό σε όλους αν και όποτε οι συντονιστές του φόρουμ επεξεργάζονται ή διαγράφουν μια ανάρτηση. Στη σπάνια περίπτωση που θα αναγκαστούμε να αποκλείσουμε κάποιον για επανειλημμένη παραβίαση των κανόνων, θα τον ενημερώνουμε ότι έγινε ο αποκλεισμός του, καθώς και για το πότε θα αρθεί.', '2017-07-25 09:02:21', '2020-09-02 15:56:30', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('forumruleschartertext2', 'en', 'messages', 'Honesty is an important value on this forum, but what you believe to be the truth might not be what others believe. Therefore we promise to make it visible to everybody if and when the forum moderators edit or delete a post. In the rare case that we have to ban someone for repeated breaking of the rules, we will inform that person that the ban has been imposed and when it will expire.', '2007-11-29 20:58:32', '2019-04-23 18:16:49', '2012-11-18 06:59:09', 'no', '', 5, NULL, 26819),
	('forumruleschartertext2', 'es', 'messages', 'La honestidad es un importante valor en este foro, pero lo que para ti puede ser cierto no necesariamente lo es para otras personas. Por lo tanto, si la moderación del foro edita o elimina un mensaje, nos comprometemos a hacerlo visible para todo el mundo. En el raro caso de que tengamos que expulsar a alguien romper las normas reiteradamente, informaremos del hecho a esa persona y de la duración de la medida.', '2008-01-03 14:38:10', '2022-07-24 11:46:02', '0000-00-00 00:00:00', 'no', '', 5, NULL, 25548),
	('forumruleschartertext2', 'fr', 'messages', 'L\'honnêteté est une valeur importante du forum, mais chacun peut penser différemment. Aussi, nous promettons de rendre visible toute suppression ou modification de message de la part des modérateurs. Dans les rares cas où un membre deviendrait «&nbsp;pré-modéré&nbsp;», suite à des contributions répétées contrevenant aux règles, ce membre en sera informé.', '2007-12-06 22:45:47', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('forumruleschartertext2', 'gl', 'messages', 'A honestidade é un valor importante neste foro, pero o que ti cres que é a verdade pode non ser o que outras persoas crean. Polo tanto prometemos facer visible se e cando as moderadoras/es do foro editan ou borran unha mensaxe. No raro caso no que teñamos que  excluír a alguén do foro por incumprir as regras repetidamente, informaremos a esa persoa de que foi excluída e de cando terminará a súa exclusión.', '2021-01-25 11:23:42', '2021-01-25 11:27:03', '2021-01-25 11:23:42', 'no', '', 5, NULL, 210880),
	('forumruleschartertext2', 'hr', 'messages', 'Iskrenost je važna i ima veliku vrijednost na ovom forumu. Znaj, ono što ti smatraš istinom drugi o tome mogu imati drugačije mišljenje. Stoga obećajemo da će svima biti vidljivo ako i kada moderatori foruma odluče izmijeniti ili izbrisati neku poruku. U malo vjerojatnom slučaju da nekog moramo staviti na popis članova čije se poruke pregledavaju zbog opetovanog kršenja pravila, o tome ćemo tog člana i obavijestiti.', '2009-08-31 15:32:47', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('forumruleschartertext2', 'it', 'messages', 'L’onestà è un valore importante in questo forum, però quello che tu credi sia la verità può essere diverso da quello che credono altre persone. Per questo motivo promettiamo che renderemo visibile a tutti se e quando i moderatori modificheranno o cancelleranno un messaggio. Nel raro caso che dovessimo bannare qualcuno per avere ripetutamente violato le regole, informeremo di ciò la persona interessata del bando e della sua durata.', '2007-12-27 19:35:13', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('forumruleschartertext2', 'lt', 'messages', 'Sąžiningumas yra svarbus šiame forume, bet tai, kas yra tiesa jums, galbūt nėra visai tiesa kitiems nariams. Todėl mes žadame, kad BeWelcome nariai galės matyti moderatorių atliekamus pranešimų redagavimo arba šalinimo veiksmus. Tais retais atvejais, kai mes turėsime premoderuoti (t.y. tikrinti prieš viešinant) tam tikro nario pranešimus dėl pakartotinio taisyklių laužymo, tas narys bus apie tai informuotas.', '2007-12-30 18:31:29', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('forumruleschartertext2', 'nl', 'messages', 'Eerlijkheid is een hoge waarde op dit forum, maar de waarheid voor de ene persoon is daarom niet die van de andere.  Daarom beloven we je dat het zichtbaar zal zijn als de moderators een bericht veranderen of verwijderen.  In de uitzonderlijke gelegenheden dat we iemand moeten verbannen voor het herhaaldelijk overtreden van de regels, zullen we die persoon over de verbanning en de duur ervan inlichten.', '2012-12-15 12:44:24', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('forumruleschartertext2', 'pl', 'messages', 'Szczerość jest istotną wartością naszego forum ale nie zapominaj, że to, co Ty uznajesz za prawdę, może nią nie być w optyce innych użytkowników i użytkowniczek forum. Dlatego zobowiązujemy się do pełnej widoczności działań moderatorów - w szczególności sytuacji gdy edytują lub usuwają posty. W rzadkich przypadkach, gdy musimy kogoś zbanować za wielokrotne łamanie zasad, będziemy informować tę osobę o nałożeniu na nią bana i kiedy on wygasa.', '2021-01-15 10:16:25', '2021-01-15 10:16:25', '2021-01-15 10:16:25', 'no', '', 5, NULL, 116789),
	('forumruleschartertext2', 'pt', 'messages', 'A honestidade é um valor importante neste fórum, mas aquilo que acredita ser a verdade pode não ser aquilo em que outros acreditam. Portanto prometemos deixar visível para toda a gente quando um moderador altera ou apaga uma mensagem. No caso de termos de afastar alguém dos fóruns por quebrar repetidamente as regras, informaremos a pessoa que o afastamento está em vigor e quando termina.', '2012-12-28 16:19:31', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('forumruleschartertext2', 'pt-BR', 'messages', 'Honestidade é bem importante no fórum más as coisas que você acha verdade não sempre são o mesmo com outros membros. Por isso prometemos fazer tudo evidente pra tudo mundo se e quando os moderadores do fórum editam ou excluam um posto. Nos casos raros quando precisamos remover alguém que violou as regras muitas vezes, vamos informar aquela pessoa que o banimento foi imposto e quando vai expirar.', '2014-06-24 04:18:42', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48669),
	('forumruleschartertext2', 'ru', 'messages', 'Честность - важное качество для нашего Форума, но то, что Вы считаете правдой, может быть неправдой для других. Поэтому мы обещаем всегда публиковать общедоступную информацию о том, когда модератор редактировал или скрыл сообщение. В тех редких случаях, когда мы вынуждены банить кого-либо за повторяющиеся нарушения правил, мы информируем этого участника о о причине и сроках бана.', '2014-05-16 18:22:34', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('forumruleschartertext2', 'sr', 'messages', 'Искреност је важна вредност овог форума, али оно што верујеш да је тако, не значи да и други тако мисле. Зато обећавамо да ћемо то учинити видљивим свима ако и када уредник форума измени или обрише поруку. Реткост је да некога искључимо због поновљених кршења правила, обавестићемо ту особу од кад и до кад је избацивање на снази.', '2015-02-20 23:21:38', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('forumruleschartertext2', 'zh-hans', 'messages', '真诚是我们这个论坛的重要构成部分, 但你相信是真相的事物, 别人不一定也这样认为. 因此我们承诺, 如果以及当群主要编辑或删帖论坛的帖子, 都会是公开可见的. 极个别的情况下如果有人因反复犯规而被屏蔽, 我们也会通知当事人屏蔽决定以及期限. ', '2013-02-13 18:20:06', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37722),
	('forumruleschartertext2', 'zh-hant', 'messages', '真诚是我们这个论坛的重要构成部分, 但你相信是真相的事物, 别人不一定也这样认为. 因此我们承诺, 如果以及当群主要编辑或删帖论坛的帖子, 都会是公开可见的. 极个别的情况下如果有人因反复犯规而被屏蔽, 我们也会通知当事人屏蔽决定以及期限. ', '2013-02-13 18:20:06', '2021-05-02 07:48:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37722),
	('forumruleschartertext3', 'ca', 'messages', 'Mirem de mantenir el fòrum ordenat entre tots. Aviat oferirem una funció de cerca (mitjançant les etiquetes) de manera que se\'t faci fàcil trobar el que necessitis. Procura escriure a les categories adequades i no enviïs el mateix missatge dues vegades (enviament múltiple o <i>cross-posting</i>).', '2008-04-02 14:24:12', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('forumruleschartertext3', 'de', 'messages', 'Bitte halte das Forum so sauber und übersichtlich wie möglich. Durch unsere Suchfunktion und die Schlagwörter ist es einfach, Themen und Beiträge zu bestimmten Themen zu finden. Bitte versuche deine Nachrichten in den richtigen Kategorie zu veröffentlichen und poste nicht zweimal dieselbe Nachricht ("cross-posting").', '2007-12-14 08:23:13', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('forumruleschartertext3', 'el', 'messages', 'Όλοι θα πρέπει να προσπαθούν να διατηρούν το φόρουμ όσο πιο καθαρό γίνεται. Θα παρέχουμε μια λειτουργία αναζήτησης (μέσω της χρήσης των ετικετών) έτσι ώστε να είναι ευκολότερη η αναζήτηση. Προσπάθησε να αναρτάς στις σωστές κατηγορίες και μην αναρτάς το ίδιο μήνυμα δύο φορές (διπλοανάρτηση /cross-posting)', '2017-07-25 09:09:21', '2020-09-02 15:57:07', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('forumruleschartertext3', 'en', 'messages', 'Everybody should try to keep this forum as clean as possible.We will provide a search function (through the use of tags) so it is easier for you to find something. Try to post in the correct categories and don\'t post the same message twice (cross-posting)', '2007-11-29 20:58:32', '2019-04-23 18:16:49', '2007-12-14 08:20:06', 'no', '', 5, NULL, 91),
	('forumruleschartertext3', 'es', 'messages', 'Todas las personas deben intentar mantener el foro lo más limpio posible. Proporcionaremos una función de búsqueda (con el uso de etiquetas) para que sea más sencillo encontrar las cosas. Intenta publicar en las categorías correctas y no repitas el mismo mensaje en varios lugares.', '2008-01-03 14:40:31', '2022-07-24 11:47:45', '0000-00-00 00:00:00', 'no', '', 5, NULL, 25548),
	('forumruleschartertext3', 'fr', 'messages', 'Merci de garder ce forum aussi propre et utilisable que possible. Les étiquettes permettent d\'effectuer une recherche sur le forum, afin de retrouver plus facilement un message. Veillez à poster dans la catégorie appropriée et merci de ne pas poster le même message plusieurs fois (en anglais&nbsp;: crossposting)', '2007-12-06 22:50:32', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('forumruleschartertext3', 'gl', 'messages', 'Todo o mundo debe tratar de manter este foro tan limpo como sexa posible. Proporcionaremos unha ferramenta para buscar (por medio de etiquetas) de modo que sexa fácil para ti atopar algunha cosa. Trata de enviar as mensaxes na categoría correcta e non envíes dúas veces a mesma mensaxe', '2021-01-25 11:26:59', '2021-01-25 11:26:59', '2021-01-25 11:26:59', 'no', '', 5, NULL, 210880),
	('forumruleschartertext3', 'he', 'messages', 'נא להשאיר את הפורום נקי ככל הניתן. נספק אפשרות חיפוש (בעזרת תגיות) שתקל על מציאה של נושאים. נסו לפרסם עם בחירה נכונה של קטגוריות ונא לא לפרסם את אותה הודעה פעמיים', '2022-04-05 13:40:38', '2022-04-05 13:40:38', '2022-04-05 13:40:38', 'no', '', 5, NULL, 290109),
	('forumruleschartertext3', 'hr', 'messages', 'Svi trebamo nastojati održavati forum što čišćim. Omogućit ćemo opciju Traži (pomoću oznaka) kako bi se traženo što lakše i brže našlo. Pripazi da poruke šalješ u ispravnu kategoriju i nemoj ponavljati poruke.', '2009-08-31 15:38:45', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('forumruleschartertext3', 'it', 'messages', 'Ognuno dovrebbe cercare di tenere questo forum il più pulito possibile. Metteremo a disposizione una funzione di ricerca (tramite l’uso di tag) così sarà più facile trovare qualcosa. Cerca di scrivere i tuoi messaggi nelle categorie adeguate e non postare lo stesso messaggio due volte (cross-posting. ', '2007-12-27 19:36:47', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 103),
	('forumruleschartertext3', 'lt', 'messages', 'Kiekvienas narys turėtų stengtis nešiukšlinti forume. Kiekvienam yra suteikiama galimybę ieškotis informacijos pagal temines žymes (raktinius žodžius) - tokiu būdu yra lengviau surasti pranešimą norima tematika. Stenkites rašyti pranešimo temos atitinkančioje kategorijoje bei neskelbti to paties pranešimo dukart.', '2007-12-13 22:24:31', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('forumruleschartertext3', 'nl', 'messages', 'Er wordt verwacht dat iedereen dit forum zo ordelijk als mogelijk houdt.  We zullen een zoekfunctie voorzien (door het gebruiken van tags), zodat het makkelijker is om dingen te vinden.  Probeer je bericht in de juiste categorie te plaatsen en zeker niet meermaals hetzelfde te posten (cross-posting).', '2012-12-15 12:48:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('forumruleschartertext3', 'pl', 'messages', 'Każdy powinien dbać o porządek na forum. Możesz przeszukiwać i odnajdywać łatwo treści na forum dzięki funkcjonalności wyszukiwania (dostępnej dzięki tagowaniu). Dlatego postaraj się postować we właściwej kategorii i unikaj ponownego publikowania tych samych treści (cross-posting).', '2021-01-15 10:10:01', '2021-01-15 10:10:01', '2021-01-15 10:10:01', 'no', '', 5, NULL, 116789),
	('forumruleschartertext3', 'pt', 'messages', 'Todos devemos tentar manter este fórum tão limpo quanto possível. Disponibilizamos uma função de pesquisa (através da utilização de tags) para que seja mais fácil encontrar alguma coisa. Tentem colocar mensagens nas categorias apropriadas e evitem colocar a mesma mensagem várias vezes.', '2013-01-20 11:41:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('forumruleschartertext3', 'ru', 'messages', 'Каждый должен стараться сохранить наш форум в максимальном порядке. Мы предоставляем функцию поиска, основанную на тэгах, чтобы облегчить поиск интересующей информации. Старайтесь оставлять собщения в правильных категориях и не оставляйте одно и тоже сообщение дважды (кросс-постинг) .', '2014-05-24 06:32:58', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('forumruleschartertext3', 'sr', 'messages', 'Свако треба да одржава форум што је могуће чистијим. Обезбедићемо претрагу (помоћу коришћења ознаки) да би лакше нешто пронашли. Пробај да објављујеш у исправним категоријама и не објавњуј исту поруку два пута.', '2015-02-21 13:08:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('forumruleschartertext3', 'zh-hant', 'messages', '每個人都應該努力保持這個論壇的整潔。我們將提供搜尋功能（透過標籤使用）讓您更容易找到所需的內容。請盡量在正確的類別中發文，並且不要重複發布相同的訊息（重複發文）。', '2025-05-31 22:31:50', '2025-05-31 22:31:50', '2025-05-31 22:31:50', 'no', '', 5, NULL, 53422),
	('forumruleschartertext4', 'ca', 'messages', 'Els moderadors són persones, la feina de les quals és controlar el bon funcionament dels fòrums de tant en tant. Poden editar o suprimir articles; i blocar, desblocar, moure, suprimir o dividir temes dels fòrums que moderen. Generalment, els moderadors miren d\'evitar que la gent desbarri o que publiqui continguts abusius o ofensius.', '2008-05-15 10:00:35', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('forumruleschartertext4', 'de', 'messages', 'Moderatoren sind Personen, die sich um den täglichen Betrieb des Forums und der Gruppen kümmern. Sie können Beiträge ändern, löschen, verschieben, sperren, eine Sperre aufheben, Themen löschen und teilen. Moderatoren sind im allgemeinen dazu da, zu verhindern, dass Mitglieder innerhalb eine Diskussion vom Thema abweichen oder beleidigend, verletzend oder ausfallend schreiben.', '2007-12-14 08:29:31', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('forumruleschartertext4', 'el', 'messages', 'Οι συντονιστές είναι άτομα των οποίων η δουλειά είναι να φροντίζουν τη λειτουργεία των φόρουμ από μέρα σε μέρα. Είναι εξουσιοδοτημένοι να επεξεργάζονται ή να διαγράφουν αναρτήσεις και να κλειδώνουν, να ξεκλειδώνουν, να μετακινούν, να διαγράφουν ή να χωρίζουν θέματα στο φόρουμ. Γενικώς οι συντονιστές είναι εκεί για να αποτρέπουν τους ανθρώπους να βγαίνουν εκτός θέματος ή να αναρτούν καταχρηστικό ή προσβλητικό περιεχόμενο.', '2017-07-25 09:14:30', '2020-09-02 15:57:42', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('forumruleschartertext4', 'en', 'messages', 'Moderators are individuals whose job it is to look after the running of the forums from day to day. They have the power to edit or delete posts and lock, unlock, move, delete and split topics in the forum. Generally moderators are there to prevent people going off-topic or posting abusive or offensive material.', '2007-11-29 20:58:32', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1223),
	('forumruleschartertext4', 'es', 'messages', 'El Equipo de Moderación está formado por personas cuya función es cuidar del funcionamiento de los foros en el día a día. Tienen el poder de editar o eliminar mensajes, así como bloquear, desbloquear, mover, borrar y dividir hilos en los foros. Generalmente, la moderación está para prevenir que las personas se salgan del tema o publiquen material abusivo u ofensivo.', '2008-01-03 14:46:30', '2022-07-24 11:50:19', '0000-00-00 00:00:00', 'no', '', 5, NULL, 25548),
	('forumruleschartertext4', 'fr', 'messages', 'Les modérateurs sont des bénévoles, qui surveillent les forums au quotidien. Ils ont le pouvoir de modifier, supprimer, bloquer, déplacer ou répartir différemment les messages. Leur rôle principal est généralement d\'éviter les hors-sujet et les propos injurieux ou offensants.', '2007-12-06 22:18:44', '2022-08-31 19:53:10', '0000-00-00 00:00:00', 'no', '', 5, NULL, 168499),
	('forumruleschartertext4', 'gl', 'messages', 'As que moderan son persoas que teñen o traballo de coidar do funcionamento dos foros día a día. Teñen o poder para editar ou borrar as mensaxes, cerrar ou abrir, mover, borrar e dividir temas del foro.  Xeralmente están alí para evitar que a xente se saía dos temas ou envíen material abusivo ou ofensivo.', '2021-01-25 11:30:48', '2021-01-25 11:30:48', '2021-01-25 11:30:48', 'no', '', 5, NULL, 210880),
	('forumruleschartertext4', 'it', 'messages', 'I moderatori sono persone il cui compito è occuparsi del buon andamento del forum di giorno in giorno. Hanno il potere di modificare o cancellare messaggi e bloccare, sbloccare, spostare, cancellare e dividere delle discussioni nella parte del forum di loro competenza. Generalmente i moderatori esistono per evitare che si vada fuori tema o che si pubblichi materiale abusivo o offensivo.', '2007-12-27 19:38:10', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('forumruleschartertext4', 'lt', 'messages', 'Moderatoriai yra individai, kurių darbas yra reguliariai prižiūrėti tvarką forumuose. Jie pajėgūs redaguoti bei šalinti pranešimus; rakinti, atrakinėti, perkelinėti bei šalinti forumo temas. Bendrai, moderatoriai yra tam, kad visi pranešimai forume būtų atitinkamose temose, bei kad nebūtų įžeidžiančių kitus narius pranešimų.', '2007-12-30 17:48:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('forumruleschartertext4', 'nl', 'messages', 'Er zijn moderatoren, die verantwoordelijk zijn voor het volgen van de forums. Zij kunnen berichten wijzigen of verwijderen en onderwerpen blokkeren, deblokkeren, verplaatsen, verwijderen en opsplitsen in het forum.  Moderators zijn er om te voorkomen dat mensen van het onderwerp afwijken of onaanvaardbare dingen posten.', '2012-12-15 12:54:04', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('forumruleschartertext4', 'pl', 'messages', 'Moderatorzy to osoby, których zadaniem jest dbanie o codzienne funkcjonowanie forum. Mają uprawnienia do edycji i usuwania postów,, zamykania, ponownego otwierania, usuwania i rozdzielania tematów na forum. Co do zasady rolą moderatorów jest dbanie, by ludzie trzymali się tematu wątku i nie zamieszczali obraźliwych treści.', '2021-01-15 10:07:06', '2021-01-15 10:07:06', '2021-01-15 10:07:06', 'no', '', 5, NULL, 116789),
	('forumruleschartertext4', 'pt', 'messages', 'Os moderadores são pessoas que têm o trabalho de tomar conta dos fóruns diariamente. Têm o poder de editar ou apagar mensagens e bloquear, desbloquear, mover, apagar e separar tópicos no fórum. Geralmente os moderadores estão lá para prevenir o descarrilar da discussão bem como o uso de linguagem obscena ou ofensiva.', '2013-01-16 20:08:37', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('forumruleschartertext4', 'ru', 'messages', 'Модераторы - это люди, чья работа состоит в том, чтобы присматривать за Форумом изо дня в день. У них есть полномочия редактировать или удалять сообщения либо блокировать, разблокировать, удалять и разделять темы Форума. Основная функция модераторов - предотвращать оффтопик и публикацию агрессивных и оскорбительных материалов.', '2014-05-03 07:17:29', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('forumruleschartertext4', 'sr', 'messages', 'Уредници су појединци чији је посао да прате рад форума. Они имају моћ да измене или обришу поруку, и да закључају, откључају, помере, обришу и раздвоје теме на форуму. Уредници су ту да спрече људе да постављају промашене теме, злоупотребљив или увредљив материјал.', '2015-02-21 12:37:28', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('forumruleschartertext4', 'zh-hant', 'messages', '版主是負責日常管理論壇運作的人員。他們有權編輯或刪除貼文，以及鎖定、解鎖、移動、刪除和分割論壇中的主題。一般而言，版主的存在是為了防止人們離題或發布辱罵或冒犯性的內容。', '2025-05-31 22:31:32', '2025-05-31 22:31:32', '2025-05-31 22:31:32', 'no', '', 5, NULL, 53422),
	('forumruleschartertext5', 'ca', 'messages', 'Evita difondre continguts que siguin clarament falsos i/o difamatoris, inacurats, abusius, vulgars, que incitin a l\'odi, assetjadors, obscens, grollers, amenaçadors, que envaeixin la intimitat d\'altri o que incompleixin alguna llei. Això també implica que no difonguis dades personals d\'altri sense el seu consentiment. Lògicament, es pot estar en desacord amb les opinions d\'altres persones, i pots dir-ho sense ésser maleducat. També és important que escriguis els textos tu mateix, és a dir, que no facis un retalla-i-enganxa dels textos d\'altres persones, tinguin drets d\'autor o no. No hi ha cap problema si inclous parts de l\'article al qual respons al teu comentari, però evita els plagis i la publicació d\'informació que se t\'hagi enviat de manera confidencial.', '2008-05-21 09:26:52', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('forumruleschartertext5', 'de', 'messages', '(a) Unerwünscht und verboten sind Beiträge, die wissentlich falsch und/oder verleumderisch, fehlerhaft, beleidigend, vulgär, hasserfüllt, belästigend, obszön, lästerlich oder bedrohend sind, in die Privatsphäre anderer eingreifen oder in anderer Weise geltendes Recht verletzen. Das inkludiert, ist aber nicht beschränkt auf, die Veröffentlichung persönlicher Daten anderer im Forum ohne vorher deren Zustimmung erhalten zu haben. Natürlich kannst du eine andere Meinung zu Beiträgen haben und darfst entsprechend in der Diskussion antworten. Wir erwarten aber, dass  du dies höflich und den Regeln entsprechend tust. \r\n\r\n(b) Wir verlangen, dass die Texte für deine Beiträge von dir selbst geschrieben werden. Das heißt, es darf kein kopiertes Material anderer enthalten, egal ob dieses urheberrechtlich geschützt ist oder nicht. Natürlich darfst du in der Diskussion Stellen aus einem vorherigen Beitrag zitieren, aber plagiieren und das Veröffentlichen vertraulicher Mitteilungen wird nicht akzeptiert. Kopiere keine Inhalte von persönlichen Seiten anderer Mitglieder (z.B. Profile, Blogs etc.) in das Forum ohne deren explizite Zustimmung. Du kannst jedoch auf solche Inhalte verweisen, indem du einen Link auf die entsprechende Seite im Forum postest.\r\n\r\n(c) Es ist nur erlaubt aus einem anderen Forumsthema ("Thread") zu zitieren, wenn deine Nachricht gleichzeitig auch einen Link auf den ursprünglichen Thread enthält, sodass alle den Kontext des ursprünglichen Beitrags einfach nachlesen können.', '2007-12-14 08:48:07', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('forumruleschartertext5', 'el', 'messages', '(α) Μην αναρτάς οποιοδήποτε υλικό το οποίο είναι εν γνώσει σου μη αληθές και/ή συκοφαντικό, ανακριβές, υβριστικό, χυδαίο, παρενοχλητικό, βλάσφημο, απειλητικό, παρεμβατικό στην ιδιωτικότητα κάποιου, που εκφράζει μίσος, ή με κάποιον άλλο τρόπο παραβιάζει οποιοδήποτε νόμο. Αυτό συμπεριλαμβάνει αλλά δεν περιορίζεται στο ότι δε μπορείς να αναρτήσεις προσωπικά δεδομένα για άλλους ανθρώπους χωρίς τη συγκατάθεσή τους. Είναι απολύτως αποδεκτό να διαφωνήσεις με κάποια άλλη δημοσίευση; ζητούμε μόνο να το κάνεις δίχως αγένεια.\r\n\r\n(β) Ζητούμε επίσης οι αναρτήσεις να γίνονται με δικά σου λόγια - δηλαδή, μην κάνεις αντιγραφή και επικόλληση το υλικό άλλων, είτε είναι κατοχυρωμένο είτε όχι. Φυσικά, και δεν πειράζει το να συμπεριλαμβάνεις κομμάτια αναρτήσεων στις οποίες αναφέρεσαι, αλλά μην κάνεις λογοκλοπή και μην αναρτάς πράγματα που σου απεστάλησαν εμπιστευτικά. Δε μπορεί να μεταφερθεί περιεχόμενο από σελίδες άλλων μελών (π.χ. προφίλ, ιστολόγιο, κτλ) στο φόρουμ χωρίς τη σαφή συγκατάθεση του δημιουργού του περιεχομένου. Μπορείς να αναφερθείς σε τέτοιου είδους περιεχόμενα βάζοντας στα φόρουμ ένα σύνδεσμο προς τη σελίδα τους.\r\n\r\n(γ) Μπορείς να παραθέσεις κείμενο από άλλο νήμα του φόρουμ, αν βάλεις και ένα σύνδεσμο πίσω στο αρχικό νήμα, έτσι ώστε να παρέχεις στο κόσμο εύκολη πρόσβαση στο νόημα της αρχικής ανάρτησης.', '2017-07-25 09:26:35', '2020-09-02 15:59:28', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('forumruleschartertext5', 'en', 'messages', '(a) Refrain from posting any material which is knowingly false and/or defamatory, inaccurate, abusive, vulgar, hateful, harassing, obscene, profane, threatening, invasive of a person\'s privacy, or otherwise in violation of any law. This includes but is not limited to that you may not post personal data about other people without their consent. It is absolutely fine to disagree with another poster; we only ask that you do so without resorting to rudeness.\r\n\r\n(b) We also require that posts be in your own words -- i.e., no cutting and pasting of other people\'s material, copyrighted or not. It is of course ok to include parts of posts that you\'re referring to, but do not plagiarise and do not post things that have been sent to you in confidentiality. No contents may be transferred from other individual member pages (e.g. profiles, blogs, etc.) to the forums without explicit consent from the author of the content. You may refer to such contents by linking to the page from the forums.\r\n\r\n(c) You may only quote from a different forum thread, if you provide a link back to the original thread to allow people to easily access the context of the original post.', '2007-11-29 20:58:32', '2019-04-23 18:16:49', '2012-11-18 09:13:35', 'no', '', 5, NULL, 26819),
	('forumruleschartertext5', 'es', 'messages', '(a) Evita publicar cualquier material que sea falso y/o difamatorio, inexacto, abusivo, vulgar, generador de odio, acoso, obsceno, irreverente, amenazador, que vulnere la privacidad de una persona, o que viole cualquier ley en cualquier otra forma. Esto incluye, pero no está limitado a, publicar datos personales sobre la gente sin su consentimiento. Es perfectamente aceptable discrepar con otra persona; sólo pedimos que lo hagas con respeto y cordialidad. \r\n\r\n(b) También pedimos que los mensajes estén escritos en tus propias palabras, es decir, no cortar y pegar el material de otra gente, con copyright o sin él. No hay problema en incluir fragmentos de otros mensajes a los cuales estás contestando (citar), pero no plagies o publiques cosas que se te han enviado confidencialmente. No se pueden transferir contenidos desde páginas personales de otra gente (ej: perfiles, blogs, etc.) hacia el foro sin el consentimiento explícito de quien creó el contenido. Puedes hacer mención a esos contenidos poniendo un enlace a esa página desde el foro.\r\n\r\n(c) Para citar un texto que venga de otro hilo del foro, debes incluir un enlace al hilo original, para que el resto de personas puedan acceder al contexto del mensaje original.', '2008-01-09 22:52:49', '2022-07-24 12:03:15', '0000-00-00 00:00:00', 'no', '', 5, NULL, 25548),
	('forumruleschartertext5', 'fr', 'messages', '(a) Ne seront tolérés aucun post contenant des propos erronés, diffamatoires, abusifs, profanateurs, déplacés, vulgaires, haineux, obscènes, menaçants, s\'apparentant à du harcèlement, attaquant la vie privée d\'une personne ou violant la loi. Il est interdit de publier des données privées sans le consentement de la personne concernée. Les désaccords font partie de la vie d\'un forum, mais merci de les exprimer sans brutalité et de rester courtois.\r\n\r\n(b) Merci d\'utiliser vos propres mots dans vos messages et de ne pas copier du contenu, qu\'il soit protégé ou non par le copyright. Vous pouvez bien entendu inclure partiellement le message auquel vous répondez, s\'il est public, mais merci de ne pas plagier des documents et de ne pas diffuser d\'informations partagées en privé.\r\n\r\n(c) Si vous souhaitez intégrer une citation provenant d\'un autre fil de discussion, merci d\'insérer un lien vers le message d\'origine, afin que le message puisse être relu en contexte.', '2007-12-05 20:29:49', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('forumruleschartertext5', 'gl', 'messages', '(a) Abstente de publicar calquera material que saibas que é falso e/ou difamatorio, impreciso, abusivo, vulgar, de odio, ofensivo, obsceno, vulgar, ameazador, invasivo da privacidade de unha persoa, ou que de outra forma viole calquera lei. Isto inclúe, mais non se limita a, non publicar dados persoais doutras persoas sen o consentimento delas. É absolutamente correcto discordar doutro envío; pero pedimos que o fagas sen recorrer á indelicadeza.\r\n\r\n(b) Tamén exiximos que as mensaxes estean coas túas propias palabras - ou sexa, que non sexan un corta-pega do material doutras persoas, con ou sen dereitos de autoría. Está claro que non hai problema en incluír partes das mensaxes que cites, mais non plaxies nin envíes cosas que te foron enviadas confidencialmente. Ningún contido pode ser transferido doutras páxinas individuais doutras  persoas da comunidade (por exemplo, perfís, blogs, etc.) para os foros sen o consentimento explícito da persoa autora do contido. Podes referirte a tales contidos por medio dunha ligazón para a páxina dos foros.\r\n\r\n(c) Só podes citar un tópico dun foro diferente, se proporcionas unha ligazón ao tópico orixinal para permitir que se poda acceder facilmente ao contexto do envío orixinal.', '2021-01-25 15:16:03', '2021-01-25 15:16:03', '2021-01-25 15:16:03', 'no', '', 5, NULL, 210880),
	('forumruleschartertext5', 'it', 'messages', '(a) Astieniti dal pubblicare coscientemente qualsiasi materiale falso e/o diffamatorio, abusivo, inaccurato, volgare, carico di odio, molesto, osceno, blasfemo, minatorio, invasivo della privacy di una persona o che violi una qualsiasi legge. Questo include (ma non si limita a) non pubblicare informazioni personali di altre persone senza il loro consenso. Non è un problema essere in disaccordo con un altro membro sul forum; solo ti chiediamo di esporre le tue ragioni ed i tuoi pensieri senza risultare maleducato. \r\n\r\n(b) Ti chiediamo anche che sia tu a scrivere i messaggi che pubblichi, cioè non copiando e incollando da materiale di altre persone, coperto da copyright o no che sia. Ovviamente è consentito includere parti dei messaggi ai quali stai rispondendo, però non plagiare e non pubblicare cose che ti sono state mandate confidenzialmente. Non è consentito trasferire materiale da pagine di altri membri (ad esempio profili, blog, etc) ai forum senza un esplicito consenso dell\'autore del materiale. Puoi riferirti a questi contenuti con un link sul forum verso la pagina corrispondente.\r\n\r\n(c) Puoi citare da un\'altra discussione sul forum soltanto se metti un link alla discussione originale in modo che le persone possano facilmente vedere il contesto del post originale.', '2007-12-28 17:57:27', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('forumruleschartertext5', 'lt', 'messages', 'Susilaikykite nuo skelbimo bet kokios medžiagos, kuri yra sąmoningai neteisinga ir/ar įžeidžianti, netiksli, vulgari, neapkenčiama, erzinanti, šlykšti, šventvagiška, grasinanti, pažeidžia asmens privatumą ar kitaip laužo egzistuojančius įstatymus. Tai reiškia, kad neturėtumėte skelbti asmeninių kitų individų duomenų arba jokios kitokios jautrios asmeninės informacijos be šių asmenų sutikimo. Yra visiškai normalu, jei nesutinkate su kitu forumo pranešimu; mes tiktai prašome jūsų rašyti taip, kad nebūtų griebiamasi šiurkštumo. Mes taip pat reikalaujame, kad jūsų pranešimai būtų rašomi jūsų pačių žodžiais, minimaliai įtraukiant kitų asmenų tekstus. Žinoma, viskas tvarkoje, jei įtraukiate pranešimo dalį, į kurią atsakote, - tačiau neplagijuokite ir neskelbkite materialo, kuris buvo atsiųstas jums konfidencialiai.', '2007-12-31 01:07:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('forumruleschartertext5', 'nl', 'messages', '(a) Post geen materiaal dat onjuist of lasterlijk, onnauwkeurig, kwetsend, vulgair, haatdragend, beschuldigend, obsceen of bedreigend is, iemands privacy schendt of in overtreding is van enige wet.  Dit houdt ook in (maar is niet beperkt tot) dat je geen persoonlijke gegevens over andere mensen mag posten zonder de toestemming van die andere persoon. Het is absoluut in orde niet akkoord te gaan met iemand, maar we vragen te discussiëren zonder grof te zijn.\r\n\r\n(b) We eisen ook dat je je gedachten uitdrukt in je eigen woorden – dat je geen materiaal kopieert en plakt van anderen (al dan niet beschermd door copyright).  Het is natuurlijk in orde om delen van berichten van anderen in te sluiten om ernaar te verwijzen, maar pleeg geen plagiaat of post geen dingen die je privé hebt ontvangen. Er mag geen inhoud van de  persoonlijke gegevens van andere leden (profiel, blog, enz) verplaatst worden, zonder expliciete toestemming van die persoon. Je kan wel naar die inhoud refereren door links naar die pagina’s te plaatsen.\r\n\r\n(c) Je mag alleen van een andere discussie dingen citeren als je een link toevoegt van de originele discussie, zodat mensen makkelijk de context kunnen achterhalen van het citaat.\r\n', '2012-12-15 13:13:49', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40169),
	('forumruleschartertext5', 'pl', 'messages', '(a) Powstrzymaj się od publikowania jakichkolwiek materiałów, które są świadomie fałszywe i / lub zniesławiające, niezgodne z prawdą, obraźliwe, wulgarne, nienawistne, napastliwe, obsceniczne, bluźniercze, zawierające groźby, naruszające prywatność osoby lub w inny sposób łamiące jakiekolwiek prawo. Ten zakaz obejmuje  między innymi publikowanie danych osobowych innych osób bez ich zgody. Absolutnie nie mamy nic przeciwko różnicom zdań z innymi postującymi; oczekujemy jednak dyskusji wolnych od wulgarności i wrogości.\r\n\r\n(b) Wymagamy również, aby posty były napisane własnymi słowami - na przykład bez przeklejania materiałów innych osób, chronionych prawami autorskimi lub nie. Oczywiście dołączanie fragmentów postów, do których się odnosisz, jest w porządku, ale nie plagiatuj i nie publikuj informacji, które zostały do ​​Ciebie wysłane poufnie. Żadne treści nie mogą być przenoszone ze stron (np. profili, blogów itp.) innych członków na fora bez wyraźnej zgody autora treści. Możesz odnieść się do takich treści, linkując daną stronę na forum.\r\n\r\n(c) Fragmenty innego wątku na forum można cytować tylko z linkiem do oryginalnego wątku, aby inni użytkownicy i użytkowniczki mieli łatwy dostęp do oryginalnego posta i jego kontekstu.', '2021-01-16 23:23:51', '2021-01-16 23:23:51', '2021-01-16 23:23:51', 'no', '', 5, NULL, 116789),
	('forumruleschartertext5', 'pt', 'messages', '(b) Abstenha-se de publicar material que saiba ser falso e/ou difamatório, inexato, abusivo, vulgar, de ódio, assédio, obsceno, profano, ameaçador, invada a privacidade de alguém ou que viole a lei. Isto inclui, mas não está limitado à publicação de dados pessoais de outras pessoas sem o seu consentimento. É perfeitamente natural não concordar com a mensagem de outro utilizador; pedimos apenas que o faça sem ser rude.\r\n\r\n(b) Também pedimos que escreva sempre usando as suas próprias palavras -- isto é, nada de copiar material de outras pessoas, esteja ou não protegido por copyright. Claro que é aceitável incluir partes das mensagens às quais se refere, mas sem plagiar nem colocar coisas que lhe foram ditas em confidência. Nenhum conteúdo pode ser transferido das páginas de outros membros (ex: perfis, blogs, etc) para os fórum sem o acordo explícito de autor desse conteúdo. Pode-se referir a esse conteúdo criando uma ligação nas suas mensagens nos fóruns para essas páginas.\r\n\r\n(c) Só pode citar de um outro tópico do fórum se incluir uma ligação para a página desse tópico, de forma a que as pessoas possam aceder facilmente ao conteúdo da mensagem original.', '2013-01-26 17:04:35', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('forumruleschartertext5', 'ru', 'messages', '(a) Воздерживайтесь от публикации любых материалов, о которых заранее известно, что они являются ложными и/или дискредитирующими, неточными, оскорбительными, вульгарными, вызывающими ненависть, непристойными, оскверняющими, угрожающими, нарушающими частную жизнь тем или иным способом. Это также включает (но не ограничивает) запрет на публикацию персональных сведений без согласия соответствующего человека. Абсолютно нормально выражать несогласие в свои сообщениях; мы просим, чтобы это происходило без перехода на грубость. \r\n\r\n(b) Мы также просим, чтобы Ваши сообщения содержали Ваши собственные мысли, т.е. не допускается копипаст из материалов других людей, вне зависимости, защищены они авторскими правами или нет. Конечно, нормально вставлять в Ваше сообщение части сообщений, на которые Вы ссылаетесь, но не занимайтесь плагиатом и не публикуйте сообщения, которые были отправлены Вам лично. Не нужно вставлять сообщения с персональных страниц других участников (профилей, блогов и прочее) в форум без явного одобрения авторов контента. Вы можете сослаться на этот контент, вставив ссылку на данную страницу в форуме.. \r\n\r\n(c) Вы можете вставлять комментарий с другой ветви форума, только если Вы вставите ссылку обратно на оригинальную ветку, чтобы обеспечить остальным простой доступ к оригинальному сообщению.', '2014-05-11 07:53:34', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('forumruleschartertext5', 'sr', 'messages', '(а) Суздржите се од постављања материјала који се зна да је лажан и/или клеветнички, нетачан, увредљив, вулгаран, пун мржње, узнемирујући, непристојан, претећи, угрожава приватност неке особе, или на други начин у супротности са било којим законом. Ово укључује, али се не ограничава на које не можете постављати личне податке о другим људима без њиховог пристанка. Апсолутно је у реду да се не слажете са другом особом; ми само тражимо да то урадите без непристојности.\r\n\r\n(б) Ми такође захтевамо да поруке пишете својим речима - тј, без копирања материјала других људи, заштићених ауторским правима или не. То је, наравно, у реду да укључите делове порука на које мислите, али не да копирате и да не постављати ствари које су вам послате у поверењу. Без објављивања садржаја са других страница неког члана Н (нпр профили, блогови, итд) на форумима без изричите сагласности од стране аутора садржаја. Можете усмерити линком ка страници са тим садржајима.\r\n\r\n(в) Можете само цитирати из другог форума поруку, ако обезбедите линк ка одговарајућој теми, да би омогућили људима да лако приступе садржају оригиналне поруке.', '2015-02-22 00:05:47', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('forumruleschartertext5', 'zh-hant', 'messages', '(a) 請勿發布任何明知是虛假及/或誹謗、不準確、辱罵、粗俗、仇恨、騷擾、淫穢、褻瀆、威脅、侵犯他人隱私，或以其他方式違反任何法律的內容。這包括但不限於，未經他人同意，您不得發布他人的個人資料。與其他發文者意見相左是絕對可以的；我們只要求您在表達不同意見時，避免使用粗魯的言詞。\r\n\r\n(b) 我們也要求您的發文須為您自己的原創內容 — 也就是說，請勿剪貼他人受版權保護或未受版權保護的資料。當然，您可以引用您所指的貼文部分內容，但請勿抄襲，也請勿發布以機密形式傳送給您的內容。未經內容作者明確同意，不得將其他個別成員頁面（例如：個人資料、部落格等）的內容轉移到論壇。您可以透過在論壇中連結到該頁面來引用這些內容。\r\n\r\n(c) 您只能在引用不同論壇討論串的內容時，提供原始討論串的連結，以便人們輕鬆查閱原始貼文的上下文。', '2025-05-31 22:31:12', '2025-05-31 22:31:12', '2025-05-31 22:31:12', 'no', '', 5, NULL, 53422),
	('forumruleschartertext6', 'ca', 'messages', 'Si trobes un missatge o una resposta que incompleixi les normes d\'ús, posa\'t en contacte amb nosaltres i indica\'ns la categoria del fòrum i el títol del missatge; hi farem una ullada. Seria preferible que NO afegissis comentaris a un missatge dubtós o qüestionable.', '2008-04-02 11:32:13', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('forumruleschartertext6', 'de', 'messages', 'Falls du einen Beitrag liest, der die hier aufgeführten Verhaltensregeln verletzt, dann melde diesen Beitrag bitte an die Moderatoren, indem du auf den Link "an Moderator melden" unterhalb der Nachricht klickst. Bitte schreibe KEINE weiteren Antworten zu einem anstößigen und unerwünschten Beitrag.', '2007-12-14 08:54:08', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('forumruleschartertext6', 'el', 'messages', 'Αν αντιληφθείς ένα μήνυμα ή μια απάντηση που παραβιάζει τους κανόνες συμπεριφοράς, ανάφερέ το στην ομάδα συντονιστών του φόρουμ κάνοντας κλικ στο σύνδεσμο Αναφορά στο συντονιστή κάτω από την ανάρτηση. Θα προτιμούσαμε να ΜΗΝ προσθέσεις περισσότερα σχόλια σε ανάρμοστο μήνυμα.', '2017-07-25 09:42:32', '2020-09-02 15:59:57', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('forumruleschartertext6', 'en', 'messages', ' If you see a message or reply that violates our rules of conduct, please refer the message to the forum moderators team by clicking the Report to moderator link underneath the post.  We would prefer that you NOT add further comments to an objectionable message.', '2007-11-29 20:58:32', '2019-04-23 18:16:49', '2012-11-18 07:01:07', 'no', '', 5, NULL, 26819),
	('forumruleschartertext6', 'es', 'messages', 'Si ves algún mensaje o respuesta que viola las reglas de conducta, por favor repórtarlo a los moderadores usando el enlace Reportar que aparece al pie de ese post. Preferimos que NO respondas de ninguna manera a un mensaje considerado cuestionable. ', '2007-12-31 16:30:30', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 554),
	('forumruleschartertext6', 'fr', 'messages', 'Si un message ou une réponse ne respecte pas les règles de conduite, merci de contacter les modérateurs en cliquant sur «&nbsp;Signaler&nbsp;», en-dessous du post. Il est préférable de ne pas alimenter une polémique et de ne pas répondre directement sur le forum.', '2007-12-05 20:18:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('forumruleschartertext6', 'gl', 'messages', 'Se ves unha mensaxe o contestación que incumpre nosas regras de conduta, por favor refire a mensaxe ao equipo moderador do foro pinchando a ligazón "Informar ao moderador/a" ao pé da mensaxe. Preferiríamos que NON engadas máis comentarios a unha mensaxe desagradable.', '2021-01-25 15:21:03', '2021-01-25 15:21:03', '2021-01-25 15:21:03', 'no', '', 5, NULL, 210880),
	('forumruleschartertext6', 'it', 'messages', 'Se vedi un messaggio o una risposta che viola le nostre regole di condotta, riporta la violazione al team dei moderatori cliccando sul pulsante sotto al post Segnala al moderatore. Preferiremmo che tu NON aggiunga commenti ad un messaggio dal contenuto discutibile.', '2007-12-27 19:39:23', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('forumruleschartertext6', 'lt', 'messages', 'Jei pamatysite pranešimą, kuris pažeidžia elgesio forume taisykles, susisiekite su mumis, pranešdami tiksliai, kurioje forumo kategorijoje bei kokioje temoje yra pažeidimas - mes jį ištyrinėsime. Pageidautume, kad jūs nerašytumėte tolimesnių komentarų prie pažeidžiančių taisykles pranešimų.', '2007-12-30 17:23:49', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('forumruleschartertext6', 'nl', 'messages', 'Als je een bericht, of reactie op een bericht ziet dat in strijd is met de gedragsregels, meld het dan aan de moderators door te klikken op de knop ‘aan moderator rapporteren’ die je onder elk bericht vindt.  We prefereren dat je NIET verder ingaat op een aanstotelijk bericht.', '2012-12-15 13:21:18', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('forumruleschartertext6', 'pl', 'messages', 'Jeżeli zobaczysz wiadomość, lub odpowiedź na nią, która łamie regulamin, zgłoś ją zespołowi moderatorów forum klikając link „zgłoś moderatorowi”, który znajdziesz pod postem. Optymalnie jeśli NIE dodasz żadnych własnych komentarzy do zgłaszanego materiału.', '2021-01-15 09:58:50', '2021-01-15 09:58:50', '2021-01-15 09:58:50', 'no', '', 5, NULL, 116789),
	('forumruleschartertext6', 'pt', 'messages', 'Se vir uma mensagem ou resposta que viole as nossas regras de conduta, por favor, reencaminhe a mensagem para a equipa de moderadores do fórum clicando na ligação Denunciar a um moderator, sob a mensagem. Preferimos que NÃO deixe qualquer outro tipo de comentários a mensagens questionáveis.', '2013-01-08 15:06:36', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('forumruleschartertext6', 'ru', 'messages', 'Если Вы видите сообщение или ответ на сообщение, кторый нарушает наши правила поведения, пожалуйста, сообщите об этом модераторам форума, нажав на ссылку "Сообщить модераторам" под данным сообщением. Нам бы очень хотелось, чтобы Вы НЕ добавляли своих комментариев к данному нежелательному сообщению.', '2014-05-11 08:05:24', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('forumruleschartertext6', 'sr', 'messages', 'Ако видите неку поруку која крши наша правила, молимо да нас упутите на ту поруку кликом на "Пријави уреднику" испод поруке. Волели би смо да НЕ одговарате даље на таквој поруци.', '2015-02-20 23:25:51', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('forumruleschartertext6', 'zh-hant', 'messages', '如果您看到任何違反我們行為規範的訊息或回覆，請點擊貼文下方的「檢舉給版主」連結，將該訊息呈報給論壇版主團隊。我們建議您不要對不當訊息追加任何評論。', '2025-05-31 22:30:00', '2025-05-31 22:30:00', '2025-05-31 22:30:00', 'no', '', 5, NULL, 53422),
	('forumrulesdiscussiongroups', 'de', 'messages', 'Regeln für die Gruppen', '2018-09-13 11:44:02', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 172939),
	('forumrulesdiscussiongroups', 'el', 'messages', 'Κανόνες για τις Ομάδες Συζήτησης', '2020-07-24 11:39:22', '2020-07-24 11:39:22', '2020-07-24 11:39:22', 'no', '', 5, NULL, 266544),
	('forumrulesdiscussiongroups', 'en', 'messages', 'Rules for Discussion Groups', '2018-06-13 19:29:51', '2019-12-26 09:49:40', '2018-06-13 19:29:51', 'no', 'Headline for the section about discussion groups on the forum rules', 5, NULL, 1223),
	('forumrulesdiscussiongroups', 'es', 'messages', 'Normas para Grupos de Debate', '2020-12-04 03:06:21', '2020-12-04 03:06:21', '2020-12-04 03:06:21', 'no', '', 5, NULL, 25548),
	('forumrulesdiscussiongroups', 'fr', 'messages', 'Règles de discussion des groupes', '2019-02-21 21:03:02', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('forumrulesdiscussiongroups', 'gl', 'messages', 'Regras para os Grupos de Debate', '2021-01-25 12:03:03', '2021-01-25 12:03:03', '2021-01-25 12:03:03', 'no', '', 5, NULL, 210880),
	('forumrulesdiscussiongroups', 'it', 'messages', 'Regole per i gruppi di discussione', '2018-12-12 20:46:29', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 13993),
	('forumrulesdiscussiongroups', 'nl', 'messages', 'Regels voor discussiegroepen', '2020-09-24 12:28:15', '2020-09-24 12:28:15', '2020-09-24 12:28:15', 'no', '', 5, NULL, 21169),
	('forumrulesdiscussiongroups', 'pl', 'messages', 'Zasady grup dyskusyjnych', '2021-01-13 23:54:27', '2021-01-13 23:54:27', '2021-01-13 23:54:27', 'no', '', 5, NULL, 116789),
	('forumrulesdiscussiongroups', 'pt', 'messages', 'Regras para Grupos de Discussão', '2018-07-10 14:37:48', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('forumrulesdiscussiongroups', 'ru', 'messages', 'Правила дискуссионных групп', '2025-03-22 18:26:19', '2025-03-22 18:26:19', '2025-03-22 18:26:19', 'no', '', 5, NULL, 519603),
	('forumrulesdiscussiongroups', 'zh-hant', 'messages', '討論群組規範', '2025-05-31 22:21:33', '2025-05-31 22:21:33', '2025-05-31 22:21:33', 'no', '', 5, NULL, 53422),
	('forumrulesdiscussiongroupstext', 'de', 'messages', '<p>BeWelcome möchte seine Mitglieder ermutigen, eine aktive und vielfältige Gemeinschaft zu sein. Deswegen unterstützen wir unter anderem das Erstellen von Diskussionsgruppen. Diese Gruppen werden von den Mitgliedern erstellt und geprägt und können sich sowohl auf bestimmte Orte als auch auf bestimmte Interessen oder Aktivitäten beziehen.<br />\r\n<br/>\r\nWer eine Gruppe erstellt, sollte sich einige Gedanken zum Zweck und den zukünftigen Aktivitäten der neuen Gruppe machen. (Man sollte sich z. B. fragen, ob es bereits eine Gruppe mit demselben oder einem ähnlichen Zweck gibt.) Einer oder mehrere Administratoren müssen für die Gruppe festgelegt werden. Die Gruppe - einschließlich aller Beiträge - wird moderiert werden und muss sich nach den Nutzungsbedingungen von BeWelcome richten.<br/>\r\nInsbesondere ist zu beachten:    \r\n<ul list-style="a">\r\n        <li>Zusätzlich zu allen untenstehenden Anforderungen müssen alle Gruppennamen, Beschreibungen, Beiträge und Aktivitäten den Nutzungsbedingungen von BeWelcome und den Forumregeln entsprechen.</li>\r\n        <li>Die Gruppe muss mindestens eine/n aktive/n Gruppenadministrator/in haben, der oder die als Kontaktperson für die Gruppe dient.</li>\r\n        <li>Der Gruppenname sollte kurz und aussagekräftig sein. Er wird auf den öffentlichen BeWelcome-Seiten gezeigt und darf deshalb allgemein nicht beleidigend oder unhöflich sein.</li>\r\n        <li>Die Gruppenbeschreibung sollte den Zweck der Gruppe wiedergeben, der - allgemein - mit BeWelcome kompatibel sein sollte.</li>\r\n        <li>Gruppen, die Intoleranz oder Diskriminierung fördern, sind nicht erlaubt.</li>\r\n        <li>Gruppen, die aus "kommerziellen" Interessen oder zu Werbezwecken gegründet werden, sind nicht erlaubt.</li>\r\n    </ul>\r\n    Wenn eine Gruppe i) diese Regeln bricht oder ii) inaktiv wird, kann sie nach angemessener Ankündigung/Warnung aus dem Forum gelöscht werden.</p>', '2018-11-21 17:11:55', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 25410),
	('forumrulesdiscussiongroupstext', 'el', 'messages', '<p>Το BeWelcome προσδοκά τη δημιουργία μίας ενεργής και ποικιλόμορφης κοινότητας για τα μέλη της. Ως εκ τούτου, ενθαρρύνουμε τη δημιουργία ομάδων συζήτησης. Τέτοιες ομάδες καθορίζονται από τα μέλη και μπορούν να περιέχουν ομάδες σχετικά με έναν τόπο όπως και ομάδες με συγκεκριμένα ενδιαφέροντα ή δραστηριότητες.<br/>\r\n<br/>\r\nΚατά τη δημιουργία μίας ομάδας, θα πρέπει να αναλογιστούν το σκοπό ύπαρξης και τη μελλοντική δραστηριότητα της ομάδας. (Για παράδειγμα, μήπως υπάρχει ήδη κάποια ομάδα με τον ίδιο ή σχετικά παρόμοιο σκοπό;) Θα πρέπει να  υπάρχουν ένας ή περισσότεροι διαχειριστές της ομάδας η οποία -συμπεριλαμβανομένων των δημοσιεύσεων - θα συντονίζεται και θα πρέπει να συμμορφώνεται με τους Όρους Χρήσης του BeWelcome Terms of Use.<br/>\r\n<br/>\r\nΕιδικότερα:\r\n<ul list-style="a">\r\n<li>Πέρα από επιπρόσθετες απαιτήσεις παρακάτω, όλα τα ονόματα, αντικείμενα, δημοσιεύσεις και δραστηριότητες της ομάδας πρέπει να συμφωνούν με τους Όρους Χρήσης του BeWelcome καθώς και τους Κανόνες του Φόρουμ.</li>\r\n<li>T Η ομάδα θα πρέπει να έχει τουλάχιστον έναν ενεργό διαχειριστή, που θα αναλάβει το ρόλο του υπεύθυνου επικοινωνίας.</li>\r\n<li>T Το όνομα της ομάδας θα πρέπει να είναι σύντομο και ξεκάθαρο. Θα αναρτηθεί στις δημόσιες σελίδες του BW, γι\'αυτό δεν θα πρέπει να είναι επιθετικό, αγενές ή προσβλητικό.</li>\r\n<li>Οι στόχοι της ομάδας θα πρέπει να φαίνονται από τους σκοπούς της, που θα πρέπει να είναι σύμφωνοι με το BW.</li>\r\n<li>Δεν θα επιτρέπονται ομάδες που δεν προωθούν την ανεκτικότητα και την ισότητα.</li>\r\n<li>Δεν θα επιτρέπονται ομάδες δημιουργημένες για \'εμπορικούς\' σκοπούς ή τη προώθηση διαφημίσεων.</li>\r\n</ul>\r\nΑν κάποια ομάδα i) παραβιάσει τους κανόνες ή ii) γίνει ανενεργή, τότε, με κατάλληλες ενημερώσεις/προειδοποιήσεις, ίσως αφαιρεθεί από το Φόρουμ.</p>', '2020-08-22 14:29:00', '2020-09-03 11:21:06', '2020-08-22 14:29:00', 'no', '', 5, NULL, 266544),
	('forumrulesdiscussiongroupstext', 'en', 'messages', '<p>BeWelcome wishes to encourage an active and diverse community amongst our membership. As part of this, we encourage the setting up of discussion groups. Such groups are member-defined and can include groups related to localities as well as groups related to specific interests or activities.<br/>\r\n<br/>\r\nWhen setting up a group, members should give some thought to the purpose and future activity of the new group. (For instance, is there already a group with the same or sufficiently similar purpose?) One or more Group Administrators need to be identified and the group - including any posts - will be moderated and will need to conform to the BeWelcome Terms of Use.<br/>\r\n<br/>\r\nIn particular:\r\n<ul list-style="a">\r\n<li>In addition to any specific requirements below, all group names, objects, posts and activities must conform to the BeWelcome Terms of Use and the Forum Rules.</li>\r\n<li>The group must have at least one active Group Administrator, who will act as the contact person for the group.</li>\r\n<li>The group name should be short and descriptive. It will be displayed on public BW pages, so should not be generally offensive, rude or insulting.</li>\r\n<li>The group objects should reflect the group\'s purpose, which should be - broadly - compatible with BW.</li>\r\n<li>Groups which promote intolerance or discrimination will not be allowed.</li>\r\n<li>Groups which are set up for \'commercial\' reasons or to carry adverts will not be allowed.</li>\r\n</ul>\r\nIf any group i) breaches these rules or ii) becomes inactive then, with appropriate notice/warnings, it may be removed from the Forum.</p>\r\n\r\n', '2018-06-13 19:32:51', '2019-12-26 09:49:40', '2018-06-13 19:32:51', 'no', 'Rules laid out for discussion groups on the forum rules page', 5, NULL, 1223),
	('forumrulesdiscussiongroupstext', 'es', 'messages', '<p>BeWelcome desea fomentar una comunidad activa y diversa entre nuestros miembros. Como parte de esto, fomentamos la creación de grupos de discusión. Dichos grupos son definidos por los miembros y pueden incluir grupos relacionados con las localidades, así como grupos relacionados con intereses o actividades específicas.</p><p>A la hora de crear un grupo, los miembros deben reflexionar sobre la finalidad y la actividad futura del nuevo grupo. (Por ejemplo, ¿existe ya un grupo con la misma finalidad o suficientemente similar?). Es necesario identificar a una o varias personas para que se encarguen de la administración del grupo. El grupo -incluidas las publicaciones- será moderado y deberá ajustarse a las condiciones de uso de BeWelcome.</p><p>En particular:</p><ul><li>Además de los requisitos específicos que se indican a continuación, todos los nombres, objetivos, publicaciones y actividades del grupo deben ajustarse a las condiciones de uso de BeWelcome y a las normas del foro.</li><li>El grupo debe tener al menos una persona activa encargada de la administración del grupo activo, que actuará como persona de contacto del grupo.</li><li>El nombre del grupo debe ser corto y descriptivo. Se mostrará en las páginas públicas de BW, por lo que no debe ser ofensivo, grosero o insultante.</li><li>Los objetivos del grupo deben reflejar la esencia del grupo.</li><li>Los objetivos del grupo deben reflejar el propósito del grupo, que debe ser -en líneas generales- compatible con BW.</li><li>No se permitirán grupos que promuevan la intolerancia o la discriminación.</li><li>No se permitirán los grupos que se creen por motivos "comerciales" o para hacer publicidad.</li></ul><p>Si algún grupo i) incumple estas normas o ii) se vuelve inactivo, entonces, con la debida notificación/advertencia, podrá ser eliminado del Foro.</p>', '2022-04-02 13:17:21', '2022-04-02 14:16:29', '2022-04-02 13:17:21', 'no', '', 5, NULL, 48548),
	('forumrulesdiscussiongroupstext', 'fr', 'messages', '<p>BeWelcome espère que ses membres créeront une communauté active et diverse. Pour ce faire, nous vous invitons à créer des groupes de discussion, qui s\'autodétermineront en fonction d\'activités communes, du lieu de vie de ses membres ou de leurs centres d\'intérêt.<br><br>Merci de bien vérifier l\'utilité du groupe que vous souhaitez créer (ex : existe-t-il déjà un groupe sur le même thème ou sur un thème similaire ?). Veillez à bien identifier un ou plusieurs administrateurs pour le groupe. Le groupe et ses commentaires seront modérés et devront se conformer aux conditions d\'utilisation de BeWelcome.<br><br>En particulier&nbsp;:</p><ul><li>Tous les noms de groupes, leur objectif, leurs commentaires et activités doivent respecter les conditions d\'utilisation de BW, en plus des conditions mentionnées ci-dessous.</li><li>Le groupe doit être composé d\'au moins un administrateur actif, qui sera la personne à contacter.</li><li>Le nom du groupe doit rester bref et descriptif. Il apparaîtra sur les pages publiques de BW – merci de vous assurer qu\'il n\'est pas blessant, agressif ou insultant.</li><li>Le thème du groupe doit refléter son objectif, qui doit – dans l\'ensemble – être compatible avec BW.</li><li>Les groupes qui font la promotion d\'idées intolérantes et de discriminations seront fermés.</li><li>Les groupes qui poursuivent un objectif commercial ou qui diffusent des publicités seront fermés.</li></ul><p>Si un groupe i) ne respecte par ces conditions ii) devient inactif, il pourra être retiré du forum, après avoir été averti dans des délais appropriés.</p><p>&nbsp;</p>', '2019-02-21 21:02:23', '2021-07-25 16:00:33', '0000-00-00 00:00:00', 'no', '', 5, NULL, 168499),
	('forumrulesdiscussiongroupstext', 'gl', 'messages', '<p>BeWelcome desexa incentivar unha comunidade activa e diversa entre as persoas que facemos parte dela. Para iso, animamos a que se abran grupos de debate. Eses grupos son definidos polas persoas que os forman e poden incluír grupos relacionados con localidades así como grupos relativos a intereses específicos ou actividades.<br/>\r\n<br/>\r\nCando creen un grupo, as persoas que fan parte do mesmo deben dar algunha idea do propósito e da actividade futura do novo grupo. (Por exemplo, hai xa algún grupo co mesmo ou moi similar propósito?). É necesario identificar a unha o máis persoas que administren o grupo e o grupo -incluíndo calquera mensaxe- será moderado e  terá que cumprir cos Termos de Uso de BeWelcome.<br/>\r\n<br/>\r\nEn particular:\r\n<ul list-style="a">\r\n<li>Ademais de calquera requirimento específico sinalado debaixo, todos os nomes de grupo, obxetivos, envíos e actividades deben cumprir cos Termos de Uso de BeWelcome e coas Regras do Foro.</li>\r\n<li>O grupo debe ter cando menos unha persoa que o administre que actuará como persoa de contacto para o grupo.</li>\r\n<li>O nome do grupo debe ser curto e descritivo. Amosarase publicamente nas paxinas de BW, e non debe ser en xeral ofensivo, maleducado ou insultante.</li>\r\n<li>Os obxectivos do grupo deben reflectir o propósito do grupo, que debe ser, nun sentido amplo, compatible con BW.</li>\r\n<li>Os grupos que promovan a intolerancia ou a discriminación non serán autorizados.</li>\r\n<li>os grupos que se establezan con fins "comerciais" ou para poñer publicidade non serán permitidos.</li>\r\n</ul>\r\nSe calquera grupo i) incumpre estas regras ou ii) se fai inactivo entón, con suficiente aviso previo, podería ser eliminado do Foro.</p>', '2021-01-25 12:02:41', '2021-02-03 11:52:45', '2021-01-25 12:02:41', 'no', '', 5, NULL, 210880),
	('forumrulesdiscussiongroupstext', 'it', 'messages', '<p> BeWelcome desidera incoraggiare una comunità attiva e diversificata tra i nostri membri. Inoltre, incoraggiamo la creazione di gruppi di discussione. Tali gruppi sono definiti dai membri e possono includere gruppi relativi alle varie località nonché gruppi relativi a interessi o attività specifici. <br/>\r\n<br/>\r\nDurante la creazione di un gruppo, i membri dovrebbero riflettere sullo scopo e l\'attività futura del nuovo gruppo. (Ad esempio, esiste già un gruppo con lo stesso o sufficientemente simile scopo?).\r\nUno o più amministratori di gruppo devono essere identificati e il gruppo - compresi eventuali post - sarà moderato e dovrà conformarsi ai Termini d\'uso di BeWelcome. <br/>\r\n<br/>\r\nIn particolare:\r\n<ul list-style = "a">\r\n<li> Oltre a tutti i requisiti specifici indicati di seguito, tutti i nomi, gli oggetti, i post e le attività dei gruppi devono essere conformi ai Termini di Utilizzo di BeWelcome e alle Regole del forum. </li>\r\n<li> Il gruppo deve avere almeno un amministratore di gruppo attivo, che fungerà da referente per il gruppo. </li>\r\n<li> Il nome del gruppo deve essere breve e descrittivo. Verrà visualizzato su pagine BeWelcome pubbliche, quindi non dovrebbe essere generalmente offensivo, maleducato o offensivo. </li>\r\n<li> Gli oggetti del gruppo dovrebbero riflettere lo scopo del gruppo, che dovrebbe essere - sostanzialmente - compatibile con BeWelcome. </li>\r\n<li> I gruppi che promuovono l\'intolleranza o la discriminazione non saranno ammessi. </li>\r\n<li> I gruppi creati per motivi "commerciali" o per la pubblicità non saranno ammessi. </li>\r\n</ Ul>\r\nSe un gruppo i) viola queste regole o ii) diventa inattivo, con opportuni avvisi / avvisi, può essere rimosso dal Forum. </p>', '2020-05-28 16:42:21', '2020-05-28 16:42:21', '2020-05-28 16:42:21', 'no', '', 5, NULL, 261434),
	('forumrulesdiscussiongroupstext', 'nl', 'messages', '<p>BeWelcome wil een actieve en diverse gemeenschap onder onze leden aanmoedigen.  Als deel hiervan moedigen we het opzetten van discussiegroepen aan.  Zulke groepen worden door leden aangemaakt en kunnen groepen zijn verbonden aan plaatsen, maar ook groepen gerelateerd aan bepaalde interessen of activiteiten.<br/>\r\n<br/>\r\nBij het opzetten van een groep moeten leden nadenken over het doel en toekomstige activiteit van de nieuwe groep.  (Bijvoorbeeld: is er al een groep met hetzelfde of gelijkaardig doel?)  Één of meer groepsadministratoren moeten aangewezen worden en de groep – inclusief alle berichten – wordt gemodereerd en moet voldoen aan de Gebruiksvoorwaarden van BeWelcome.<br/>\r\n<br/>\r\n In het bijzonder:\r\n<ul list-style="a">\r\n<li>Bijkomend bij meer specifieke eisen verderop, moeten alle groepsnamen, onderwerpen, berichten en activiteiten voldoen aan de Gebruiksvoorwaarden van BeWelcome en de Forumregels.</li>\r\n<li>De groep moet minstens één actieve Groepsadministrator hebben, die als contactpersoon van de groep kan optreden.</li>\r\n<li>De groepsnaam moet kort en beschrijvend zijn.  Deze zal getoond worden op publieke pagina’s van BW, dus mag niet algemeen aanvallend, grof of beledigend zijn.</li>\r\n<li>De groepsobjecten moeten het doel van de groep spiegelen, en deze moet – grofweg – compatibel zijn met BW.</li>\r\n<li>Groepen die intolerantie of discriminatie bevorderen zijn niet toegestaan.</li>\r\n<li>Groepen die opgezet zijn voor ‘commerciële’ redenen of om reclame te bevatten zijn niet toegestaan.</li>\r\n</ul>\r\nAls een groep i) deze regels overtreedt of ii) inactief wordt, dan kan deze, met passende waarschuwing, verwijderd worden van het Forum.</p>', '2020-09-24 12:39:26', '2020-10-06 12:41:57', '2020-09-24 12:39:26', 'no', '', 5, NULL, 1223),
	('forumrulesdiscussiongroupstext', 'pl', 'messages', '<p>BeWelcome zależy, by jego społeczność była jak najbardziej aktywna i różnorodna, dlatego bardzo zachęcamy do tworzenia grup dyskusyjnych. Ich treść zależy wyłącznie od tworzących je członków i członkiń; może dotyczyć lokalnych spraw, jak i tematów związanych z konkretnymi zainteresowaniami czy aktywnościami.<br/>\r\n<br/>\r\nZakładając grupę warto zastanowić się nad jej celem i przyszłą działalnością. (Na przykład, czy nie istnieje już grupa o tym samym lub podobnym celu?) Należy wyznaczyć przynajmniej jednego administratora lub administratorkę grupy, zaś sama grupa - w tym wszelkie w niej posty - będą moderowane i muszą przestrzegać Warunków korzystania z BeWelcome.<br/>\r\n<br/>\r\nW szczególności:\r\n<ul list-style="a">\r\n<li>Oprócz określonych poniżej wymagań, wszystkie nazwy grup, cele, posty i działania muszą być zgodne z Warunkami korzystania z BeWelcome i Regulaminem forum. </li>\r\n<li>Grupą musi mieć co najmniej jednego aktywnego administratora, który będzie też pełnił rolę osoby kontaktowej.</li>\r\n<li>Nazwa grupy powinna być krótka i opisowa. Będzie ona wyświetlana na ogólnodostępnych stronach BW, więc nie może być obraźliwa, napastliwa ani wulgarna. </li>\r\n<li>Cele grupy powinny odzwierciedlać jej założenia, które z kolei muszą być zgodne z ideami BW.</li>\r\n<li>Zakazane są grupy promujące jakąkolwiek nietolerancję lub dyskryminację. </li>\r\n<li>Grupy utworzone w celach „komercyjnych” lub w których będą dystrybuowane reklamy, są niedozwolone. </li>\r\n</ul>\r\nJeśli jakakolwiek grupa i) naruszy te zasady lub ii) stanie się nieaktywna, po odpowiednim powiadomieniu / ostrzeżeniu może zostać usunięta z Forum. </p>', '2021-01-17 04:38:49', '2021-01-17 04:38:49', '2021-01-17 04:38:49', 'no', '', 5, NULL, 116789),
	('forumrulesdiscussiongroupstext', 'pt', 'messages', '<p>O BeWelcome procura encorajar uma comunidade ativa e diversificada entre os seus membros. Como factor para isto, encorajamos a criação de grupos de discussão. Estes grupos são definidos pelos seus membros e podem iincluir grupos associados a localidades ou grupos associados a interesses ou atividades específicos.<br/> \r\n<br/> \r\nAo criar um grupo, os membros devem ponderar o objetivo e futura atividade do novo grupo. (Por exemplo, já existe algum grupo com um objetivo idêntico ou suficientemente parecido?) É necessário identificar um ou mais Administradores de Grupo e o grupo - incluindo quaisquer mensagens - será moderado e precisa de estar em conformidade com as Condições de Utilização do BeWelcome.<br/> \r\n<br/> \r\nEm particular: \r\n<ul list-style="a"> \r\n<li>Para além de quaisquer requisitos específicos abaixo indicados, todos os nomes de grupo, objetivos, mensagens e atividades, devem estar em conformidade com as condições de utilização do BeWelcome e as Regras do Fórum.</li> \r\n<li>O grupo deve ter pelo menos um Administrador de Grupo ativo, que funcionará como a pessoa de contacto para o grupo.</li> \r\n<li>O nome do grupo deve ser curto e descritivo. Será exibido nas páginas públicas do BW, portanto não deve ser geralmente ofensivo, rude ou insultuoso.</li> \r\n<li>Os objetivos do grupo devem refletir o seu propósito que deve ser - em geral - compatível com o BW.</li> \r\n<li>Não serão permitidos grupos que promovam a intolerância ou discriminação.</li> \r\n<li>Não serão permitidos grupos criados com motivos \'comerciais\' ou para publicação de anúncios.</li> \r\n</ul> \r\nSe algum grupo i) quebrar estas regras ou ii) ficar inativo, então, com as devidas notificações / avisos, pode ser removido do Forum.</p> ', '2018-11-05 20:18:52', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('forumrulesdiscussiongroupstext', 'ru', 'messages', '<p>BeWelcome стремится поощрять активное и разнообразное сообщество среди наших членов. В рамках этого мы поощряем создание дискуссионных групп. Такие группы определяются участвующими и могут включать группы, связанные с местностями, а также с определенными интересами или видами деятельности.</p><p>&nbsp;</p><p>При создании группы ее членам следует задуматься о целях и будущей деятельности новой группы. (Например, существует ли уже группа с такой же или достаточно похожей целью?) Необходимо определить одного или нескольких администрующих, и группа, включая любые сообщения, будет модерироваться и должна будет соответствовать Условиям использования BeWelcome.</p><p>&nbsp;</p><p>В частности:</p><ul><li>В дополнение к любым конкретным требованиям ниже, все названия групп, объекты, сообщения и действия должны соответствовать Условиям использования BeWelcome и Правилам форума.</li><li>Групп должна администрироваться хотя бы одним активным участвующим - контактным лицом группы.</li><li>Название группы должно быть коротким и описательным. Оно будет отображаться на публичных страницах BW, поэтому не должно быть в целом оскорбительным, грубым или обидным.</li><li>Объекты группы должны отражать цель группы, которая должна быть - в целом - совместима с BW.</li><li>Группы, пропагандирующие нетерпимость или дискриминацию, не будут разрешены.</li><li>Группы, созданные в «коммерческих» целях или для размещения рекламы, не будут разрешены.<br>&nbsp;</li></ul><p>Если какая-либо группа i) нарушает эти правила или ii) становится неактивной, то с соответствующим уведомлением/предупреждением она может быть удалена с форума.</p>', '2025-03-25 15:13:51', '2025-03-25 15:15:06', '2025-03-25 15:13:51', 'no', '', 5, NULL, 519603),
	('forumrulesdiscussiongroupstext', 'zh-hant', 'messages', '<p>BeWelcome 旨在鼓勵會員之間建立活躍且多元的社群。為此，我們鼓勵成立討論群組。這些群組由會員自行定義，可包括與地點相關的群組，以及與特定興趣或活動相關的群組。</p><p>在建立群組時，會員應仔細思考新群組的目的和未來活動。（例如，是否已有目的相同或足夠相似的群組？）需要指定一名或多名群組管理員，且該群組（包括任何貼文）將會受到管理，並需符合 BeWelcome 的使用條款。</p><p>特別是：</p><ul><li>除了以下任何特定要求外，所有群組名稱、宗旨、貼文和活動都必須符合 BeWelcome 的使用條款和論壇規範。</li><li>群組必須至少有一名活躍的群組管理員，作為群組的聯絡人。</li><li>群組名稱應簡短且具描述性。它將顯示在 BeWelcome 的公開頁面上，因此不應普遍具有冒犯性、粗魯或侮辱性。</li><li>群組宗旨應反映群組的目的，且此目的應與 BeWelcome 大致相符。</li><li>不允許成立宣揚不寬容或歧視的群組。</li><li>不允許成立基於「商業」目的或刊登廣告的群組。</li></ul><p>如果任何群組 i) 違反這些規範或 ii) 變得不活躍，在適當的通知/警告後，該群組可能會從論壇中移除。</p>', '2025-05-31 22:35:11', '2025-05-31 22:35:11', '2025-05-31 22:35:11', 'no', '', 5, NULL, 53422),
	('forumrulesdiscussiongroupstext1', 'de', 'messages', 'BeWelcome möchte seine Mitglieder ermutigen, eine aktive und vielfältige Gemeinschaft zu sein. Deswegen unterstützen wir unter anderem das Erstellen von Diskussionsgruppen. Diese Gruppen werden von den Mitgliedern erstellt und geprägt und können sich sowohl auf bestimmte Orte als auch auf bestimmte Interessen oder Aktivitäten beziehen.\r\n', '2018-09-17 12:47:37', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 172939),
	('forumrulesdiscussiongroupstext1', 'el', 'messages', 'Το BeWelcome, μεταξύ άλλων παροχών στα μέλη του, ενθαρρύνει και τη δημιουργία μίας ενεργής και ποικιλόμορφης κοινότητας. Με αφορμή αυτό, ενθαρρύνουμε τη δημιουργία ομάδων συζήτησης. Τέτοιες ομάδες διαμορφώνονται από τα μέλη και μπορούν να περιέχουν ομάδες σχετικές με περιοχές ή συγκεκριμένα ενδιαφέροντα ή δραστηριότητες.', '2020-07-24 07:11:18', '2020-07-24 07:11:53', '2020-07-24 07:11:18', 'no', '', 5, NULL, 266544),
	('forumrulesdiscussiongroupstext1', 'en', 'messages', 'BeWelcome wishes to encourage an active and diverse community amongst our membership. As part of this, we encourage the setting up of discussion groups. Such groups are member-defined and can include groups related to localities as well as groups related to specific interests or activities.', '2018-06-13 19:39:35', '2019-12-26 09:49:40', '2018-06-13 19:39:35', 'no', 'Paragraph in forum rules section about discussion groups', 5, NULL, 1223),
	('forumrulesdiscussiongroupstext1', 'es', 'messages', 'BeWelcome desea fomentar una comunidad activa y diversa entre nuestros miembros. Como parte de esto, fomentamos la creación de grupos de discusión. Dichos grupos son definidos por los miembros y pueden incluir grupos relacionados con las localidades, así como grupos relacionados con intereses o actividades específicas.', '2022-04-02 17:08:01', '2022-04-02 17:08:01', '2022-04-02 17:08:01', 'no', '', 5, NULL, 48548),
	('forumrulesdiscussiongroupstext1', 'fr', 'messages', 'BeWelcome espère que ses membres créeront une communauté active et diverse. Pour ce faire, nous vous invitons à créer des groupes de discussion, qui s\'autodétermineront en fonction d\'activités communes, du lieu de vie de ses membres ou de leurs centres d\'intérêt.', '2019-02-21 20:57:38', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('forumrulesdiscussiongroupstext1', 'gl', 'messages', 'BeWelcome desexa incentivar unha comunidade activa e diversa entre as persoas que facemos parte dela. Para iso, animamos a que se abran grupos de debate. Eses grupos son definidos polas persoas que os forman e poden incluír grupos relacionados con localidades así como grupos relativos a intereses específicos ou actividades.', '2021-02-03 11:54:41', '2021-02-03 11:54:41', '2021-02-03 11:54:41', 'no', '', 5, NULL, 210880),
	('forumrulesdiscussiongroupstext1', 'it', 'messages', 'BeWelcome vuole incoraggiare una comunità attive e con differenti interessi nell\'ambito dei nostri membri. Come parte di questo incoraggiamo la creazione di gruppi di discussione. Questi gruppi sono definiti dai membri e possono includere gruppi relativi a località come pure gruppi relativi a interessi specifici o a attività.', '2018-12-13 00:19:21', '2021-02-28 19:47:19', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160610),
	('forumrulesdiscussiongroupstext1', 'nl', 'messages', 'BeWelcome wil een actieve en diverse gemeenschap onder onze leden aanmoedigen.  Als deel hiervan moedigen we het opzetten van discussiegroepen aan.  Zulke groepen worden door leden aangemaakt en kunnen groepen zijn verbonden aan plaatsen, maar ook groepen gerelateerd aan bepaalde interessen of activiteiten.', '2020-09-24 12:33:29', '2020-09-24 12:33:29', '2020-09-24 12:33:29', 'no', '', 5, NULL, 21169),
	('forumrulesdiscussiongroupstext1', 'pl', 'messages', 'BeWelcome zależy, by społeczność była jak najbardziej aktywna i różnorodna, dlatego bardzo zachęcamy do tworzenia grup dyskusyjnych. Ich treść zależy wyłącznie od tworzących je członków i członkiń; może dotyczyć lokalnych spraw, jak i tematów związanych z konkretnymi zainteresowaniami czy aktywnościami. Wszystko w Waszych rękach!', '2021-01-16 18:04:52', '2021-01-16 18:04:52', '2021-01-16 18:04:52', 'no', '', 5, NULL, 116789),
	('forumrulesdiscussiongroupstext1', 'pt', 'messages', 'O BeWelcome deseja encorajar uma comunidade ativa e diversificada entre os nossos membros. Como parte deste objetivo, encorajamos a criação de grupos de discussão. Estes grupos são definidos pelos membros e podem incluir grupos associados a localidades assim como grupos associados a interesses ou atividades específicos.', '2018-07-10 14:39:19', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('forumrulesdiscussiongroupstext1', 'ru', 'messages', 'BeWelcome стремится поощрять активное и разнообразное сообщество среди наших членов. В рамках этого мы поощряем создание дискуссионных групп. Такие группы определяются участвующими и могут включать группы, связанные с местностями, а также с определенными интересами или видами деятельности.', '2025-03-25 10:17:36', '2025-03-25 10:17:36', '2025-03-25 10:17:36', 'no', '', 5, NULL, 519603),
	('forumrulesdiscussiongroupstext10', 'de', 'messages', 'Wenn eine Gruppe I) diese Regeln bricht oder II) inaktiv wird, kann sie nach angemessener Ankündigung/Warnung aus dem Forum gelöscht werden.', '2018-09-17 14:06:57', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 172939),
	('forumrulesdiscussiongroupstext10', 'el', 'messages', 'Αν οποιαδήποτε ομάδα i) παραβιάσει τους κανόνες ii) γίνει ανενεργή, κατόπιν σχετικών παρατηρήσεων/ προειδοποιήσεων, ίσως αφαιρεθεί από το Φόρουμ.', '2020-08-10 13:51:17', '2020-08-10 13:51:17', '2020-08-10 13:51:17', 'no', '', 5, NULL, 266544),
	('forumrulesdiscussiongroupstext10', 'en', 'messages', 'If any group i) breaches these rules or ii) becomes inactive then, with appropriate notice/warnings, it may be removed from the Forum.', '2018-06-13 19:44:16', '2019-12-26 09:49:40', '2018-06-13 19:44:16', 'no', 'Conclusion of the rules for discussion groups.', 5, NULL, 1223),
	('forumrulesdiscussiongroupstext10', 'es', 'messages', 'Si algún grupo i) incumple estas normas o ii) se vuelve inactivo, entonces, con la debida notificación/advertencia, podrá ser eliminado del Foro.', '2022-04-02 17:05:04', '2022-04-02 17:05:04', '2022-04-02 17:05:04', 'no', '', 5, NULL, 48548),
	('forumrulesdiscussiongroupstext10', 'fr', 'messages', 'Si un groupe i) ne respecte par ces conditions ii) devient inactif, il pourra être retiré du forum, après avoir été averti dans des délais appropriés.', '2019-02-21 20:13:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('forumrulesdiscussiongroupstext10', 'gl', 'messages', 'Se calquera grupo i) incumpre estas regras ou ii) se fai inactivo entón, con suficiente aviso previo, podería ser eliminado do Foro.', '2021-02-03 11:39:14', '2021-02-03 11:39:14', '2021-02-03 11:39:14', 'no', '', 5, NULL, 210880),
	('forumrulesdiscussiongroupstext10', 'it', 'messages', 'Se un gruppo i) viola queste regole o ii) diventa inattivo, con opportuni avvisi / avvertenze, potrà essere rimosso dal Forum.', '2020-05-28 16:35:08', '2020-05-28 16:35:08', '2020-05-28 16:35:08', 'no', '', 5, NULL, 261434),
	('forumrulesdiscussiongroupstext10', 'nl', 'messages', 'Als een groep i) deze regels overtreedt of ii) inactief wordt, dan kan deze, met passende waarschuwing, verwijderd worden van het Forum.', '2020-09-24 11:36:24', '2020-09-24 11:36:24', '2020-09-24 11:36:24', 'no', '', 5, NULL, 21169),
	('forumrulesdiscussiongroupstext10', 'pl', 'messages', 'Jeśli jakaś grupa i) naruszy te zasady lub i) stanie się nieaktywna, wtedy, po odpowiednim powiadomieniu lub ostrzeżeniu, może zostać usunięta z Forum.', '2021-01-14 23:31:22', '2021-01-14 23:31:22', '2021-01-14 23:31:22', 'no', '', 5, NULL, 116789),
	('forumrulesdiscussiongroupstext10', 'pt', 'messages', 'Se algum grupo i) quebrar estas regras ou ii) ficar inativo então, após os avisos devidos, pode ser removido do fórum.', '2018-07-10 14:33:58', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('forumrulesdiscussiongroupstext2', 'de', 'messages', 'Wer eine Gruppe erstellt, sollte sich einige Gedanken zum Zweck und den zukünftigen Aktivitäten der neuen Gruppe machen. (Man sollte sich z. B. fragen, ob es bereits eine Gruppe mit demselben oder einem ähnlichen Zweck gibt.) Einer oder mehrere Administratoren müssen für die Gruppe festgelegt werden. Die Gruppe - einschließlich aller Beiträge - wird moderiert werden und muss sich nach den Nutzungsbedingungen von BeWelcome richten.', '2018-09-17 12:57:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 172939),
	('forumrulesdiscussiongroupstext2', 'el', 'messages', 'Κατά τη δημιουργία μίας ομάδας, τα μέλη θα πρέπει να σκεφτούν το λόγο ύπαρξης όπως και τη μελλοντική δραστηριότητα της. (Για παράδειγμα, την ύπαρξη ομάδας με τον ίδιο ή σχετικά παρόμοιο σκοπό;). Θα πρέπει να υπάρχει ένας ή περισσότεροι Διαχειριστές της Ομάδας και η ομάδα -συμπεριλαμβανομένων των δημοσιεύσεων- θα πρέπει να συντονίζεται και να συμμορφώνεται με τους Όρους Χρήσης του BeWelcome.', '2020-08-10 14:10:09', '2020-08-27 13:52:12', '2020-08-10 14:10:09', 'no', '', 5, NULL, 266544),
	('forumrulesdiscussiongroupstext2', 'en', 'messages', 'When setting up a group, members should give some thought to the purpose and future activity of the new group. (For instance, is there already a group with the same or sufficiently similar purpose?) One or more Group Administrators need to be identified and the group - including any posts - will be moderated and will need to conform to the BeWelcome Terms of Use.', '2018-06-13 19:40:04', '2019-12-26 09:49:40', '2018-06-13 19:40:04', 'no', 'Second paragraph in forum rules section about discussion groups', 5, NULL, 1223),
	('forumrulesdiscussiongroupstext2', 'es', 'messages', 'A la hora de crear un grupo, los miembros deben reflexionar sobre la finalidad y la actividad futura del nuevo grupo. (Por ejemplo, ¿existe ya un grupo con la misma finalidad o suficientemente similar?). Es necesario identificar a una o varias personas para que se encarguen de la administración del grupo. El grupo -incluidas las publicaciones- será moderado y deberá ajustarse a las condiciones de uso de BeWelcome.', '2022-04-02 17:08:18', '2022-04-02 17:08:18', '2022-04-02 17:08:18', 'no', '', 5, NULL, 48548),
	('forumrulesdiscussiongroupstext2', 'fr', 'messages', 'Merci de bien vérifier l\'utilité du groupe que vous souhaitez créer (ex&nbsp;: existe-t-il déjà un groupe avec sur le même thème ou sur un thème similaire&nbsp;?). Veillez à bien identifier un ou plusieurs administrateurs pour le groupe. Le groupe et ses commentaires seront modérés et devront se conformer aux conditions d\'utilisation de BeWelcome.', '2019-02-21 20:37:57', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('forumrulesdiscussiongroupstext2', 'gl', 'messages', 'Cando creen un grupo, as persoas que fan parte do mesmo deben dar algunha idea do propósito e da actividade futura do novo grupo. (Por exemplo, hai xa algún grupo co mesmo ou moi similar propósito?). É necesario identificar a unha o máis persoas que administren o grupo e o grupo -incluíndo calquera mensaxe- será moderado e terá que cumprir cos Termos de Uso de BeWelcome.', '2021-02-03 11:51:53', '2021-02-03 11:51:53', '2021-02-03 11:51:53', 'no', '', 5, NULL, 210880),
	('forumrulesdiscussiongroupstext2', 'it', 'messages', 'Durante la creazione di un gruppo, i membri dovrebbero riflettere sullo scopo e l\'attività futura del nuovo gruppo. (Ad esempio, esiste già un gruppo con lo stesso o con un sufficientemente simile scopo?).\r\nÈ necessario identificare uno o più amministratori per il gruppo e il gruppo, inclusi eventuali post, sarà moderato e dovrà conformarsi ai Termini di Utilizzo di BeWelcome.', '2020-05-28 16:37:50', '2020-05-28 16:37:50', '2020-05-28 16:37:50', 'no', '', 5, NULL, 261434),
	('forumrulesdiscussiongroupstext2', 'nl', 'messages', 'Bij het opzetten van een groep moeten leden nadenken over het doel en toekomstige activiteit van de nieuwe groep.  (Bijvoorbeeld: is er al een groep met hetzelfde of gelijkaardig doel?)  Één of meer groepsadministratoren moeten aangewezen worden en de groep – inclusief alle berichten – wordt gemodereerd en moet voldoen aan de Gebruiksvoorwaarden van BeWelcome.', '2020-09-24 12:30:08', '2020-09-24 12:30:08', '2020-09-24 12:30:08', 'no', '', 5, NULL, 21169),
	('forumrulesdiscussiongroupstext2', 'pl', 'messages', 'Zakładając nową grupę członkowie powinni zastanowić się nad jej celem i przyszłą aktywnością tej nowej mikrospołeczności. ( Na przykład: czy nie istnieje już przypadkiem grupa o tym samym, lub wystarczająco podobnym celem?). Ponadto przynajmniej jeden administrator musi być określony dla każdej grupy, a ta - łącznie z postami - musi być stałe moderowana oraz być zgodna z warunkami użytkowania BeWelcome.', '2021-01-14 23:43:06', '2021-01-14 23:43:06', '2021-01-14 23:43:06', 'no', '', 5, NULL, 116789),
	('forumrulesdiscussiongroupstext2', 'pt', 'messages', 'Ao criar um grupo, os seus membros devem pensar um pouco no seu objetivo e na atividade futura do novo grupo. (Por exemplo, já há algum grupo com o mesmo objetivo ou similar?) É preciso identificar um ou mais administradores de Grupo e o grupo - incluindo quaisquer mensagens - será moderado e precisa de respeitar as Condições de Utilização do BeWelcome.', '2018-07-10 14:40:53', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('forumrulesdiscussiongroupstext2', 'ru', 'messages', 'При создании группы ее членам следует задуматься о целях и будущей деятельности новой группы. (Например, существует ли уже группа с такой же или достаточно похожей целью?) Необходимо определить одного или нескольких администрующих, и группа, включая любые сообщения, будет модерироваться и должна будет соответствовать Условиям использования BeWelcome.', '2025-03-25 04:17:40', '2025-03-25 04:17:40', '2025-03-25 04:17:40', 'no', '', 5, NULL, 519603),
	('forumrulesdiscussiongroupstext3', 'de', 'messages', 'Insbesondere ist zu beachten:', '2018-09-17 13:02:27', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 172939),
	('forumrulesdiscussiongroupstext3', 'el', 'messages', 'Ειδικότερα:', '2020-07-24 07:02:00', '2020-07-24 07:02:00', '2020-07-24 07:02:00', 'no', '', 5, NULL, 266544),
	('forumrulesdiscussiongroupstext3', 'en', 'messages', 'In particular:', '2018-06-13 19:40:44', '2019-12-26 09:49:40', '2018-06-13 19:40:44', 'no', 'Third paragraph in forum rules section about discussion groups', 5, NULL, 1223),
	('forumrulesdiscussiongroupstext3', 'es', 'messages', 'En particular:', '2020-12-07 12:25:44', '2020-12-07 12:25:44', '2020-12-07 12:25:44', 'no', '', 5, NULL, 25548),
	('forumrulesdiscussiongroupstext3', 'fr', 'messages', 'En particulier&nbsp;:', '2019-02-21 20:19:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('forumrulesdiscussiongroupstext3', 'gl', 'messages', 'En particular:', '2021-02-03 11:50:07', '2021-02-03 11:50:07', '2021-02-03 11:50:07', 'no', '', 5, NULL, 210880),
	('forumrulesdiscussiongroupstext3', 'it', 'messages', 'In particolare:', '2018-12-12 20:46:04', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 13993),
	('forumrulesdiscussiongroupstext3', 'nl', 'messages', 'In het bijzonder:', '2020-09-24 11:33:07', '2020-09-24 11:33:07', '2020-09-24 11:33:07', 'no', '', 5, NULL, 21169),
	('forumrulesdiscussiongroupstext3', 'pl', 'messages', 'W szczególności:', '2021-01-14 21:19:13', '2021-01-14 21:19:13', '2021-01-14 21:19:13', 'no', '', 5, NULL, 116789),
	('forumrulesdiscussiongroupstext3', 'pt', 'messages', 'Em particular:', '2018-07-10 14:36:57', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('forumrulesdiscussiongroupstext4', 'de', 'messages', '(a) Zusätzlich zu allen untenstehenden Anforderungen müssen alle Gruppennamen, Beschreibungen, Beiträge und Aktivitäten den Nutzungsbedingungen von BeWelcome und den Forumregeln entsprechen.', '2018-09-17 13:05:46', '2021-01-12 23:16:00', '0000-00-00 00:00:00', 'no', '', 5, NULL, 347),
	('forumrulesdiscussiongroupstext4', 'el', 'messages', '(α) Πέρα από τα παρακάτω προαπαιτούμενα, όλα τα ονόματα των ομάδων, οι περιγραφές, οι δημοσιεύσεις και οι δραστηριότητες θα πρέπει να συμμορφώνονται με τους Όρους Χρήσης του BeWelcome και τους Κανόνες του Φόρουμ.', '2020-07-24 07:01:45', '2021-05-04 22:16:46', '2020-07-24 07:01:45', 'no', '', 5, NULL, 266502),
	('forumrulesdiscussiongroupstext4', 'en', 'messages', '(a) In addition to any specific requirements below, all group names, descriptions, posts and activities must conform to the BeWelcome Terms of Use and the Forum Rules.', '2018-06-13 19:41:34', '2020-10-06 09:44:11', '2020-10-06 09:44:11', 'no', 'First entry in list about discussion groups', 5, 0, 21169),
	('forumrulesdiscussiongroupstext4', 'es', 'messages', '(a) Además de los requisitos específicos que se indican a continuación, todos los nombres, objetivos, publicaciones y actividades del grupo deben ajustarse a las condiciones de uso de BeWelcome y a las normas del foro.', '2022-04-02 17:07:33', '2022-04-02 17:07:33', '2022-04-02 17:07:33', 'no', '', 5, NULL, 48548),
	('forumrulesdiscussiongroupstext4', 'fr', 'messages', '(a) Tous les noms de groupes, leur objectif, leurs commentaires et activités doivent respecter les conditions d\'utilisation de BeWelcome et les règles du forum, en plus des conditions mentionnées ci-dessous.', '2019-02-21 20:09:57', '2020-11-29 21:40:06', '0000-00-00 00:00:00', 'no', '', 5, NULL, 168499),
	('forumrulesdiscussiongroupstext4', 'gl', 'messages', '(a) Ademais de calquera requirimento específico sinalado debaixo, todos os nomes de grupo, descricións, envíos e actividades deben cumprir cos Termos de Uso de BeWelcome e coas Regras do Foro.', '2021-02-03 11:49:44', '2021-02-03 11:49:44', '2021-02-03 11:49:44', 'no', '', 5, NULL, 210880),
	('forumrulesdiscussiongroupstext4', 'it', 'messages', '(a) Oltre a tutti i requisiti specifici indicati di seguito, tutti i nomi dei gruppi, le descrizioni, gli articoli pubblicati e le attività devono essere conformi ai Termini di Utilizzo di BeWelcome e alle Regole del forum.', '2020-05-28 16:36:09', '2020-11-23 20:00:47', '2020-05-28 16:36:09', 'no', '', 5, NULL, 160610),
	('forumrulesdiscussiongroupstext4', 'nl', 'messages', '(a) Bijkomend bij meer specifieke eisen verderop, moeten alle groepsnamen, beschrijvingen, berichten en activiteiten voldoen aan de Gebruiksvoorwaarden van BeWelcome en de Forumregels.', '2019-05-09 13:04:36', '2020-10-06 09:44:44', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('forumrulesdiscussiongroupstext4', 'pl', 'messages', '(a) Niezależnie od wszelkich dodatkowych wymagań wymienionych poniżej, wszystkie nazwy, opisy, posty i aktywności w grupach muszą być zgodne z zasadami forum i warunkami użytkowania (Terms of Use) Be Welcome.', '2021-01-14 23:18:59', '2021-01-14 23:22:50', '2021-01-14 23:18:59', 'no', '', 5, NULL, 116789),
	('forumrulesdiscussiongroupstext4', 'pt', 'messages', '(a) Para além dos requisitos específicos abaixo mencionados, todos os nomes de grupos, descrições, mensagens e atividades devem respeitar as Condições de Utilização do BeWelcome e as regras dos fórums.', '2018-07-10 14:33:04', '2021-04-06 04:25:12', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('forumrulesdiscussiongroupstext5', 'de', 'messages', '(b) Die Gruppe muss mindestens eine/n aktive/n Gruppenadministrator/in haben, der oder die als Kontaktperson für die Gruppe dient.', '2018-09-17 13:06:54', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 172939),
	('forumrulesdiscussiongroupstext5', 'el', 'messages', '(b) Η ομάδα θα πρέπει να έχει έναν τουλάχιστον ενεργό Διαχειριστή Ομάδας, που θα λειτουργεί ως υπεύθυνος επικοινωνίας της ομάδας.', '2020-07-24 06:58:17', '2020-07-24 06:58:17', '2020-07-24 06:58:17', 'no', '', 5, NULL, 266544),
	('forumrulesdiscussiongroupstext5', 'en', 'messages', '(b) The group must have at least one active Group Administrator, who will act as the contact person for the group. ', '2018-06-13 19:42:01', '2019-12-26 09:49:40', '2018-06-13 19:42:01', 'no', 'Second entry in list about discussion groups', 5, NULL, 1223),
	('forumrulesdiscussiongroupstext5', 'es', 'messages', '(b) El grupo debe tener al menos una persona activa encargada de la administración del grupo, que actuará como persona de contacto del grupo.', '2022-04-02 17:07:00', '2022-04-02 17:07:00', '2022-04-02 17:07:00', 'no', '', 5, NULL, 48548),
	('forumrulesdiscussiongroupstext5', 'fr', 'messages', '(b) Le groupe doit être composé d\'au moins un administrateur actif, qui sera la personne à contacter.', '2019-02-21 20:04:37', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('forumrulesdiscussiongroupstext5', 'gl', 'messages', '(b) O grupo debe ter cando menos unha persoa que o administre que actuará como persoa de contacto para o grupo.', '2021-02-03 11:48:16', '2021-02-03 11:48:16', '2021-02-03 11:48:16', 'no', '', 5, NULL, 210880),
	('forumrulesdiscussiongroupstext5', 'it', 'messages', '(b) Il gruppo deve avere almeno un Amministyratore attivo, che sarà la persona di contatto per il gruppo.', '2019-01-21 16:28:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 13993),
	('forumrulesdiscussiongroupstext5', 'nl', 'messages', '(b) De groep moet minstens één actieve Groepsadministrator hebben, die als contactpersoon van de groep kan optreden.', '2020-09-24 12:31:58', '2020-09-24 12:37:03', '2020-09-24 12:31:58', 'no', '', 5, NULL, 21169),
	('forumrulesdiscussiongroupstext5', 'pl', 'messages', '(b) grupa musi mieć przynajmniej jednego aktywnego administratora, który będzie jednocześnie kontaktową osobą w grupie.', '2021-01-14 23:26:47', '2021-01-14 23:26:47', '2021-01-14 23:26:47', 'no', '', 5, NULL, 116789),
	('forumrulesdiscussiongroupstext5', 'pt', 'messages', '(b) O grupo tem de ter pelo menos um Administrador de Grupo ativo, que servirá como a pessoa de contacto para o grupo.', '2018-07-10 14:30:47', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('forumrulesdiscussiongroupstext6', 'de', 'messages', '(c) Der Gruppenname sollte kurz und aussagekräftig sein. Er wird auf den öffentlichen BeWelcome-Seiten gezeigt und darf deshalb allgemein nicht beleidigend oder unhöflich sein.', '2018-09-17 13:09:33', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 172939),
	('forumrulesdiscussiongroupstext6', 'el', 'messages', '(γ) Το όνομα της ομάδας θα πρέπει να είναι σύντομο και κατατοπιστικό. Δεν θα πρέπει να είναι προσβλητικό ή χυδαίο καθώς θα εμφανίζεται στον ιστό των σελίδων του BW.', '2020-07-24 06:51:15', '2020-09-02 21:59:01', '2020-07-24 06:51:15', 'no', '', 5, NULL, 266544),
	('forumrulesdiscussiongroupstext6', 'en', 'messages', '(c) The group name should be short and descriptive. It will be displayed on public BW pages, so should not be generally offensive, rude or insulting. ', '2018-06-13 19:42:33', '2019-12-26 09:49:40', '2018-06-13 19:42:33', 'no', 'Third entry in list about discussion groups', 5, NULL, 1223),
	('forumrulesdiscussiongroupstext6', 'es', 'messages', '(c) El nombre del grupo debe ser corto y descriptivo. Se mostrará en las páginas públicas de BW, por lo que no debe ser ofensivo, grosero o insultante.', '2022-04-02 17:06:15', '2022-04-02 17:06:15', '2022-04-02 17:06:15', 'no', '', 5, NULL, 48548),
	('forumrulesdiscussiongroupstext6', 'fr', 'messages', '(c) Le nom du groupe doit rester bref et descriptif. Il apparaîtra sur les pages publiques de BW – merci de vous assurer qu\'il n\'est pas blessant, agressif ou insultant.', '2019-02-21 20:03:31', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('forumrulesdiscussiongroupstext6', 'gl', 'messages', '(c) O nome do grupo debe ser curto e descritivo. Amosarase publicamente nas paxinas de BW, polo que non debe ser en xeral ofensivo, maleducado ou insultante.', '2021-02-03 11:46:12', '2021-02-03 11:46:12', '2021-02-03 11:46:12', 'no', '', 5, NULL, 210880),
	('forumrulesdiscussiongroupstext6', 'it', 'messages', '(c) Il nome del gruppo deve essere breve e descrittivo. Sarà esposto sulle pagine pubbliche di BW, per cui non dovrà essere offensivo in generale.', '2018-12-12 20:45:35', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 13993),
	('forumrulesdiscussiongroupstext6', 'nl', 'messages', '(c) De groepsnaam moet kort en beschrijvend zijn.  Deze zal getoond worden op publieke pagina’s van BW, dus mag niet algemeen aanvallend, grof of beledigend zijn.', '2020-09-24 12:27:59', '2020-09-24 12:27:59', '2020-09-24 12:27:59', 'no', '', 5, NULL, 21169),
	('forumrulesdiscussiongroupstext6', 'pl', 'messages', '(c) nazwa grupy powinna być krótka i opisowa. Będzie publicznie wyświetlana na stronach BW, więc nie powinna być obraźliwa ani ordynarna.', '2021-01-14 23:15:50', '2021-01-14 23:15:50', '2021-01-14 23:15:50', 'no', '', 5, NULL, 116789),
	('forumrulesdiscussiongroupstext6', 'pt', 'messages', '(c) O nome do grupo deve ser curto e descritivo. Será mostrado nas páginas públicas do BW, portanto não deve ser ofensivo, rude ou insultuoso.', '2018-07-10 14:36:46', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('forumrulesdiscussiongroupstext7', 'de', 'messages', '(d) Die Gruppenbeschreibung sollte den Zweck der Gruppe wiedergeben, der - allgemein - mit BeWelcome kompatibel sein sollte.', '2018-09-17 14:02:59', '2021-01-12 23:15:16', '0000-00-00 00:00:00', 'no', '', 5, NULL, 347),
	('forumrulesdiscussiongroupstext7', 'el', 'messages', 'δ) Η περιγραφή της ομάδας θα πρέπει να αντανακλά το σκοπό της ομάδας, που θα πρέπει να είναι - ευρέως- συμβατός με το BW.', '2020-08-10 13:54:36', '2021-05-04 22:14:42', '2020-08-10 13:54:36', 'no', '', 5, NULL, 266502),
	('forumrulesdiscussiongroupstext7', 'en', 'messages', '(d) The group description should reflect the group’s purpose, which should be – broadly – compatible with BW.', '2018-06-13 19:43:42', '2020-10-06 09:41:48', '2020-10-06 09:41:48', 'no', 'Fourth entry in list about discussion groups', 5, 0, 21169),
	('forumrulesdiscussiongroupstext7', 'es', 'messages', '(d) La descripción del grupo debe reflejar la finalidad del mismo, que debe ser -en líneas generales- compatible con BW.', '2022-04-02 10:23:45', '2022-04-02 10:23:45', '2022-04-02 10:23:45', 'no', '', 5, NULL, 48548),
	('forumrulesdiscussiongroupstext7', 'fr', 'messages', '(d) La description du groupe doit refléter son objectif, qui doit – dans l\'ensemble – être compatible avec BW.', '2019-02-21 20:17:23', '2020-11-29 21:41:52', '0000-00-00 00:00:00', 'no', '', 5, NULL, 168499),
	('forumrulesdiscussiongroupstext7', 'gl', 'messages', '(d) A descrición do grupo debe reflectir o propósito do grupo, que debe ser, nun sentido amplo, compatible con BW.', '2021-02-03 11:41:33', '2021-02-03 11:46:28', '2021-02-03 11:41:33', 'no', '', 5, NULL, 210880),
	('forumrulesdiscussiongroupstext7', 'it', 'messages', '(d) L\'oggetto del gruppo deve rifletterne lo scopo, che dovrebbe essere – in generale – compatibile con BW.', '2018-12-13 00:13:43', '2020-11-23 20:02:33', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160610),
	('forumrulesdiscussiongroupstext7', 'nl', 'messages', '(d) De groepsbeschrijving moet het doel van de groep spiegelen, en deze moet – in grote lijnen – compatibel zijn met BW.', '2020-09-24 11:43:06', '2020-10-06 09:42:16', '2020-09-24 11:43:06', 'no', '', 5, NULL, 21169),
	('forumrulesdiscussiongroupstext7', 'pl', 'messages', '(d) opis grupy powinien wyjaśniać jej cel, który z kolei powinien być zgodny z szeroko rozumianą ideą BW.', '2021-01-14 23:28:28', '2021-01-14 23:28:28', '2021-01-14 23:28:28', 'no', '', 5, NULL, 116789),
	('forumrulesdiscussiongroupstext7', 'pt', 'messages', '(d) A descrição do grupo deve refletir o propósito para que foi criado, que deve ser - regra geral - compatível com o BW.', '2018-07-10 14:34:46', '2021-04-06 04:25:48', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('forumrulesdiscussiongroupstext8', 'de', 'messages', '(e) Gruppen, die Intoleranz oder Diskriminierung fördern, sind nicht erlaubt.', '2018-09-17 14:03:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 172939),
	('forumrulesdiscussiongroupstext8', 'el', 'messages', '(ε) Δεν επιτρέπονται ομάδες που προωθούν τη μισαλλοδοξία ή τη διάκριση.', '2020-07-24 06:29:41', '2020-07-24 06:29:41', '2020-07-24 06:29:41', 'no', '', 5, NULL, 266544),
	('forumrulesdiscussiongroupstext8', 'en', 'messages', '(e) Groups which promote intolerance or discrimination will not be allowed. ', '2018-06-13 19:47:52', '2019-12-26 09:49:40', '2018-06-13 19:47:52', 'no', 'Fifth entry in list about discussion groups', 5, NULL, 1223),
	('forumrulesdiscussiongroupstext8', 'es', 'messages', '(e)  No se permitirán grupos que promuevan la intolerancia o la discriminación.', '2022-04-02 17:05:41', '2022-04-02 17:05:41', '2022-04-02 17:05:41', 'no', '', 5, NULL, 48548),
	('forumrulesdiscussiongroupstext8', 'fr', 'messages', '(e) Les groupes qui font la promotion d\'idées intolérantes et de discriminations seront fermés.', '2019-02-21 20:07:43', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('forumrulesdiscussiongroupstext8', 'gl', 'messages', '(e) Os grupos que promovan a intolerancia ou a discriminación non serán autorizados.', '2021-02-03 11:37:28', '2021-02-03 11:38:12', '2021-02-03 11:37:28', 'no', '', 5, NULL, 210880),
	('forumrulesdiscussiongroupstext8', 'it', 'messages', '(e) Non saranno ammessi gruppi che promuovono intolleranza o discriminazione.', '2020-05-28 16:34:11', '2020-05-28 16:34:11', '2020-05-28 16:34:11', 'no', '', 5, NULL, 261434),
	('forumrulesdiscussiongroupstext8', 'nl', 'messages', '(e) Groepen die intolerantie of discriminatie bevorderen zijn niet toegestaan.', '2020-09-24 11:35:00', '2020-09-24 11:35:00', '2020-09-24 11:35:00', 'no', '', 5, NULL, 21169),
	('forumrulesdiscussiongroupstext8', 'pl', 'messages', '(e) Grupy promujące nietolerancję czy dyskryminacje są zabronione.', '2021-01-14 23:13:47', '2021-01-14 23:13:47', '2021-01-14 23:13:47', 'no', '', 5, NULL, 116789),
	('forumrulesdiscussiongroupstext8', 'pt', 'messages', '(e) Não serão permitidos grupos que promovam a intolerância ou discriminação.', '2018-07-10 14:31:52', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('forumrulesdiscussiongroupstext9', 'de', 'messages', '(f) Gruppen, die aus "kommerziellen" Interessen oder zu Werbezwecken gegründet werden, sind nicht erlaubt.', '2018-09-17 14:05:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 172939),
	('forumrulesdiscussiongroupstext9', 'el', 'messages', '(στ) Ομάδες που έχουν συσταθεί για \'εμπορικούς\' λόγους ή που περιέχουν διαφημίσεις δεν θα γίνονται δεκτές.', '2020-08-10 13:44:42', '2024-07-09 06:17:46', '2020-08-10 13:44:42', 'no', '', 5, NULL, 266502),
	('forumrulesdiscussiongroupstext9', 'en', 'messages', '(f) Groups which are set up for ‘commercial’ reasons or to carry adverts will not be allowed.', '2018-06-13 19:48:21', '2020-09-24 11:34:13', '2018-06-13 19:48:21', 'no', 'Sixth entry in list about discussion groups', 5, 0, 21169),
	('forumrulesdiscussiongroupstext9', 'es', 'messages', '(f) No se permitirán los grupos que se creen por motivos "comerciales" o para hacer publicidad.', '2022-04-02 17:04:40', '2022-04-02 17:04:40', '2022-04-02 17:04:40', 'no', '', 5, NULL, 48548),
	('forumrulesdiscussiongroupstext9', 'fr', 'messages', '(f) Les groupes qui poursuivent un objectif commercial ou qui diffusent des publicités seront fermés.', '2019-02-21 20:06:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('forumrulesdiscussiongroupstext9', 'gl', 'messages', '(f) Os grupos que se establezan con fins "comerciais" ou para poñer publicidade non serán permitidos.', '2021-02-03 11:36:54', '2021-02-03 11:36:54', '2021-02-03 11:36:54', 'no', '', 5, NULL, 210880),
	('forumrulesdiscussiongroupstext9', 'it', 'messages', '(f) Non sono ammessi gruppi creati a scopo commerciale o che riportino pubblicità.', '2018-12-13 00:12:15', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 13993),
	('forumrulesdiscussiongroupstext9', 'nl', 'messages', '(f) Groepen die aangemaakt zijn om ‘commerciële’ redenen of om reclame te bevatten zijn niet toegestaan.', '2020-09-24 11:33:53', '2026-02-17 09:42:23', '2020-09-24 11:33:53', 'no', '', 5, NULL, 21169),
	('forumrulesdiscussiongroupstext9', 'pl', 'messages', '(f) grupy utworzone w celach komercyjnych lub zawierające treści reklamowe są niedozwolone.', '2021-01-14 23:12:49', '2021-01-14 23:12:49', '2021-01-14 23:12:49', 'no', '', 5, NULL, 116789),
	('forumrulesdiscussiongroupstext9', 'pt', 'messages', '(f) Não são permitidos grupos criados com fins \'comerciais\' ou para envio de anúncios.', '2018-07-10 14:31:27', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('forumrulesgeneral', 'ca', 'messages+intl-icu', 'Normes per les que es regeixen els Forums i els Grups', '2022-06-16 08:44:12', '2022-06-16 08:44:12', '2022-06-16 08:44:12', 'no', '', 5, NULL, 26748),
	('forumrulesgeneral', 'de', 'messages+intl-icu', 'Regeln für Foren und Gruppen', '2020-06-06 15:20:46', '2020-06-06 15:20:46', '2020-06-06 15:20:46', 'no', '', 5, NULL, 25410),
	('forumrulesgeneral', 'el', 'messages+intl-icu', 'Ισχύοντες κανονισμοί στα Φόρουμ και τις Ομάδες', '2020-07-22 20:02:51', '2020-07-22 20:02:51', '2020-07-22 20:02:51', 'no', '', 5, NULL, 266544),
	('forumrulesgeneral', 'en', 'messages+intl-icu', 'Rules applying to Forums and Groups', '2020-05-17 18:47:28', '2020-05-17 18:47:28', '2020-05-17 18:47:28', 'no', 'Headline on /forums/rules', 5, NULL, 1),
	('forumrulesgeneral', 'es', 'messages+intl-icu', 'Normas para Foros y Grupos', '2020-12-02 18:49:42', '2020-12-02 18:49:42', '2020-12-02 18:49:42', 'no', '', 5, NULL, 25548),
	('forumrulesgeneral', 'fr', 'messages+intl-icu', 'Règles s’appliquant aux forums et groupes', '2020-05-25 21:22:12', '2020-05-25 21:22:12', '2020-05-25 21:22:12', 'no', '', 5, NULL, 29128),
	('forumrulesgeneral', 'gl', 'messages+intl-icu', 'Regras que se aplican aos Foros e Grupos', '2021-01-22 17:35:16', '2021-01-22 17:35:16', '2021-01-22 17:35:16', 'no', '', 5, NULL, 210880),
	('forumrulesgeneral', 'hu', 'messages+intl-icu', 'Fórumok és Csoportok általános szabályai', '2020-05-29 10:06:44', '2020-05-29 10:06:44', '2020-05-29 10:06:44', 'no', '', 5, NULL, 36939),
	('forumrulesgeneral', 'it', 'messages+intl-icu', 'Regole applicabili a Forum e Gruppi', '2020-05-26 10:42:44', '2020-05-26 10:42:44', '2020-05-26 10:42:44', 'no', '', 5, NULL, 261434),
	('forumrulesgeneral', 'nl', 'messages+intl-icu', 'Regels voor Forums en Groepen', '2020-09-21 19:26:35', '2020-09-21 19:26:35', '2020-09-21 19:26:35', 'no', '', 5, NULL, 21169),
	('forumrulesgeneral', 'pl', 'messages+intl-icu', 'Zasady forów i grup', '2020-10-20 23:00:02', '2020-10-20 23:00:02', '2020-10-20 23:00:02', 'no', '', 5, NULL, 116789),
