	('forumrulesshort2text', 'ca', 'messages', 'Evita els atacs personals i els comentaris destructius. El fòrum no és un judici públic.', '2008-03-30 12:40:18', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 3236),
	('forumrulesshort2text', 'de', 'messages', 'Keine Attacken oder Beleidigungen gegenüber anderen Mitgliedern. Das Forum ist kein öffentlicher Richtplatz.', '2008-03-01 22:48:20', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 3050),
	('forumrulesshort2text', 'en', 'messages', 'No personal attacks or flaming. The forum is no public trial.', '2007-12-28 03:34:40', '2019-04-23 18:16:49', '2007-12-28 03:34:40', 'no', 'No personal attacks or flaming. The forum is no public trial.', 5, 1, 601),
	('forumrulesshort2text', 'es', 'messages', 'Evitar ataques personales o mensajes insultantes o agresivos. El foro es un bien público.', '2007-12-31 16:20:39', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1328),
	('forumrulesshort2text', 'fr', 'messages', 'Pas d\'attaques personnelles ou de propos insultants destinés à alimenter des polémiques pour la polémique. Ce forum n\'est pas un endroit pour règler des comptes ni non plus un tribunal', '2008-01-04 15:04:07', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('forumrulesshort2text', 'hr', 'messages', 'Bez osobnih napada i uvreda. Forum nije  javno suđenje.', '2010-04-14 13:46:35', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 8197),
	('forumrulesshort2text', 'it', 'messages', 'Niente attacchi personali o liti. I forum non è un processo pubblico.', '2007-12-29 15:40:24', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
	('forumrulesshort2text', 'lt', 'messages', 'Jokių asmeninių atakų. Forumas nėra joks viešas teismas.', '2007-12-30 19:06:40', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 227),
	('forumrulesshort2text', 'nl', 'messages', 'Geen persoonlijke aanvallen of flames. Dit forum is geen publieke rechtszaak.', '2008-03-29 16:14:43', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 97),
	('forumrulesshort2text', 'pt', 'messages', 'Não faça ataques pessoais. O fórum não é um julgamento público.', '2013-01-26 17:16:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 38787),
	('forumrulesshort2text', 'ru', 'messages', 'Запрет на личные оскорбления или же обвинения. Форум не является публичным судом.', '2009-03-09 12:48:20', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 79),
