	('forumrulesshort4text', 'pt', 'messages', 'Acate todo e qualquer conselho e pedido dos moderadores', '2013-01-26 17:13:02', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 38787),
	('forumrulesshortintro', 'ca', 'messages', 'Ajusta\'t a les %snormes de sentit comú%s següents si vols participar als fòrums', '2008-04-02 11:36:48', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 3236),
	('forumrulesshortintro', 'de', 'messages', 'Bitte halte die folgenden %sreasonable rules% ein, wenn du beabsichtigst im Forum Einträge zu machen', '2008-03-02 00:02:14', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 15240),
	('forumrulesshortintro', 'en', 'messages', 'Please abide by the following %sreasonable rules%s if you intend to post in the forums', '2007-12-28 03:39:38', '2019-04-23 18:16:49', '2007-12-28 03:39:38', 'no', '"Please abide by the following reasonable rules if you intend to post in the forums" [Introduction text] Note: Don\'t delete the variables "%s" for links in the text. Note2: this text will be followed by two dots (":")', 5, 1, 601),
	('forumrulesshortintro', 'es', 'messages', 'Por favor sigue las siguientes %sreglas%s si intentaste publicar en los foros', '2007-12-31 16:11:56', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1328),
	('forumrulesshortintro', 'fr', 'messages', 'S\'il vous plait acceptez de vous contraindre à suivre les %srègles (raisonables)%s suivantes si vous voulez écrire dans ce forum', '2008-01-04 15:33:33', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('forumrulesshortintro', 'it', 'messages', 'Ti preghiamo di attenerti alle seguenti %sragionevoli norme%s se hai intenzione di postare nei forum', '2010-04-27 13:24:20', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 6002),
	('forumrulesshortintro', 'lt', 'messages', 'Prašom tvirtai laikykitės šių %staisyklių%s, jei ketinate rašyti forume', '2007-12-30 22:59:43', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 227),
	('forumrulesshortintro', 'pt', 'messages', 'Por favor cumpra as seguintes %s regras %s se pretende escrever para os forums', '2013-01-31 14:58:38', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 30452),
	('forumrulestext1', 'ca', 'messages', '(a) Has llegit i acceptat les normes del fòrum de BeWelcome, que són les següents:', '2008-03-03 14:34:00', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('forumrulestext1', 'de', 'messages', 'Mit dem Veröffentlichen einer Mitteilung im Forum erklärst du dich mit dem Folgenden einverstanden:\r\n\r\n(a) Du hast nachfolgende Regeln des BeWelcome Forums gelesen und akzeptiert: ', '2008-03-01 22:05:53', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 172939),
	('forumrulestext1', 'el', 'messages', 'Δημοσιεύοντας σε αυτό το φόρουμ, συμφωνείς με τα ακόλουθα:\r\n\r\n(α) Έχεις διαβάσει και αποδεχθεί τους κανόνες του φόρουμ του BeWelcome, οι οποίοι είναι οι εξής:', '2017-07-25 09:57:43', '2020-09-02 16:00:41', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('forumrulestext1', 'en', 'messages', 'By posting in the forum, you agree to the following:\r\n\r\n(a) You have read and accepted the rules of the forum of BeWelcome, which are as follows:', '2007-11-29 20:58:32', '2019-12-26 09:49:40', '2018-06-13 19:19:35', 'no', 'First part of the general rules for forum and groups', 5, NULL, 1223),
	('forumrulestext1', 'es', 'messages', '(a) Has leído y aceptado las reglas de foros de BeWelcome, que son las siguientes:	', '2007-12-31 16:32:05', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1328),
	('forumrulestext1', 'fr', 'messages', 'En prenant part aux discussions du forum, vous acceptez les conditions suivantes&nbsp;:\r\n\r\n(a) Vous avez lu et accepté les règles du forum de BeWelcome, décrites ci-dessous :', '2007-12-02 19:03:22', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('forumrulestext1', 'gl', 'messages', 'Facendo un envío ao foro, aceptas o seguinte: \r\n\r\n(a) Liches e aceptas as regras do foro de BeWelcome, que son as seguintes:', '2021-01-25 15:24:12', '2021-01-25 15:24:12', '2021-01-25 15:24:12', 'no', '', 5, NULL, 210880),
	('forumrulestext1', 'it', 'messages', 'Scrivendo nel forum accetti quanto segue:\r\n(a) Dichiari di aver letto e accettato le regole del forum di BeWelcome, che sono le seguenti:', '2007-12-28 18:16:51', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 13993),
	('forumrulestext1', 'lt', 'messages', '(a) Jūs patvirtinate, kad perskaitėte visas išvardintas žemiau BeWelcome forumo taisykles, sutinkant su šiomis sąlygomis:', '2007-12-17 05:04:56', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('forumrulestext1', 'nl', 'messages', '(a) Je hebt de volgende regels voor het forum gelezen en geaccepteerd:', '2012-12-15 13:22:58', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('forumrulestext1', 'pl', 'messages', '(a) Przeczytałeś i zaakceptowałeś poniższe zasady forum BeWelcome:', '2008-08-02 09:36:37', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 90),
	('forumrulestext1', 'pt', 'messages', 'Ao escrever no fórum concorda com o seguinte:\r\n\r\n(a) Leu e aceitou as regras do fórum de BeWelcome, que são as seguintes: ', '2009-09-08 13:44:32', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('forumrulestext1', 'ru', 'messages', '(a) Вы прочли и согласились со следующими правилами форума BeWelcome:', '2014-05-24 06:36:37', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('forumrulestext1', 'sr', 'messages', '(а) Прочитали сте и прихватили правила BeWelcome форума, која су:', '2013-01-14 12:50:44', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('forumrulestext1', 'zh-hant', 'messages', '透過在論壇發文，您同意以下事項：\r\n\r\n(a) 您已閱讀並接受 BeWelcome 論壇規範，內容如下：', '2025-05-31 22:29:16', '2025-05-31 22:29:16', '2025-05-31 22:29:16', 'no', '', 5, NULL, 53422),
	('forumrulestext10', 'ca', 'messages', 'Mantén el fòrum ordenat: escriu a la categoria més adequada', '2008-02-29 15:40:41', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('forumrulestext10', 'de', 'messages', 'Sorge für Ordnung im Forum - schreibe in die richtige Kategorie. Ein Moderator kann deine Nachricht in die richtige Kategorie verschieben, falls du sie an der falschen Stelle gepostet hast.', '2008-01-30 15:34:26', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('forumrulestext10', 'el', 'messages', 'Διατήρησε το φόρουμ σε τάξη- ανάρτησε στη σωστή κατηγορία. Κάποιος συντονιστής ίσως μετακινήσει την ανάρτησή σου στη κατάλληλη κατηγορία, αν την έβαλες σε λάθος μέρος.', '2017-07-25 10:48:56', '2020-08-26 14:31:45', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('forumrulestext10', 'en', 'messages', ' Keep the forum in order - post in the right category. A moderator may move your post to the appropriate category, if you posted it in the wrong place.', '2007-11-29 20:58:32', '2019-04-23 18:16:49', '2012-11-18 07:09:52', 'no', '', 5, NULL, 26819),
	('forumrulestext10', 'es', 'messages', 'Mantén el foro en orden - publica en la categoría correcta. Un moderador puede llegar a mover tu post hacia la categoría apropiada en caso de ser necesario.', '2007-12-14 16:21:15', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 554),
	('forumrulestext10', 'fr', 'messages', 'Merci de garder le forum ordonné - veillez à poster dans la bonne catégorie. Si vous vous êtes trompé, un modérateur peut déplacer votre message vers la catégorie appropriée.', '2007-12-02 18:57:27', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('forumrulestext10', 'gl', 'messages', 'Mantén o foro en orden. Envía as mensaxes á categoría adecuada. Un moderador podería mover a túa mensaxe á categoría apropiada se a enviaches ao lugar equivocado.', '2021-01-25 16:16:05', '2021-01-25 16:16:05', '2021-01-25 16:16:05', 'no', '', 5, NULL, 210880),
	('forumrulestext10', 'hr', 'messages', 'Održavaj urednost foruma - piši u odgovarajuću kategoriju', '2010-04-23 12:21:52', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('forumrulestext10', 'it', 'messages', 'Tieni in ordine il forum – pubblica nella categoria corretta. Un moderatore potrebbe spostare il tuo post alla categoria appropriata, se l\'hai pubblicata nel luogo sbagliato.', '2007-12-29 15:28:30', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('forumrulestext10', 'lt', 'messages', 'Laikykitės tvarkos forume - rašykite pranešimus atitinkančiose kategorijose', '2007-12-30 19:41:55', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('forumrulestext10', 'nl', 'messages', 'Hou het forum ordelijk – plaats je bericht in de juiste categorie. Een moderator kan jouw bericht verplaatsen naar de meer aangewezen categorie, als je het op de verkeerde plaats hebt gezet.', '2012-12-15 13:47:51', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('forumrulestext10', 'pl', 'messages', 'Dbaj o porządek na forum - postuj we właściwej kategorii. Moderator może przenieść Twój post do odpowiedniej kategorii, jeżeli pierwotnie została opublikowana przez Ciebie w niewłaściwym miejscu.', '2021-01-16 16:30:44', '2021-01-16 16:30:44', '2021-01-16 16:30:44', 'no', '', 5, NULL, 116789),
	('forumrulestext10', 'pt', 'messages', 'Mantenha o fórum em ordem - escreva na categoria certa. Um moderador pode mover a sua mensagem para a categoria apropriada, se a colocar no local errado.', '2012-12-28 16:15:30', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('forumrulestext10', 'ru', 'messages', 'Пожалуйста, поддерживайте порядок на форуме - выбирайте правильные категории. Если вы создадите сообщение в неверной категории, модератор может переместить его в соответствующее место.', '2007-12-16 15:45:47', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('forumrulestext10', 'sr', 'messages', 'Одржавајте форум уредним, пишите у одговарајућој категорији. Уредник може да премести вашу поруку у одговарајућу категорију ако сте писали на погрешном месту.', '2013-01-14 12:45:11', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('forumrulestext10', 'zh-hant', 'messages', '請保持論壇秩序 — 在正確的類別中發文。如果您發文位置錯誤，版主可能會將您的貼文移至適當的類別。', '2025-05-31 22:36:38', '2025-05-31 22:36:38', '2025-05-31 22:36:38', 'no', '', 5, NULL, 53422),
	('forumrulestext11', 'ca', 'messages', 'Sigues entenedor', '2008-02-29 15:39:40', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('forumrulestext11', 'cs', 'messages', 'Ať je to čitelné.', '2014-01-30 11:52:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('forumrulestext11', 'de', 'messages', 'Sorge für Lesbarkeit. ', '2008-03-01 21:46:26', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('forumrulestext11', 'el', 'messages', 'Διατήρησε το φόρουμ ευκολοδιάβαστο.', '2017-07-25 10:17:14', '2020-08-26 14:34:02', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('forumrulestext11', 'en', 'messages', 'Keep it readable.', '2007-11-29 20:58:32', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 347),
	('forumrulestext11', 'es', 'messages', 'Mantenlo legible', '2007-12-31 04:16:15', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1328),
	('forumrulestext11', 'fr', 'messages', 'Merci d\'écrire des messages lisibles.', '2007-12-01 21:36:32', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('forumrulestext11', 'gl', 'messages', 'Manteno lexible.', '2021-01-25 16:16:41', '2021-01-25 16:16:41', '2021-01-25 16:16:41', 'no', '', 5, NULL, 210880),
	('forumrulestext11', 'hr', 'messages', 'Neka bude čitljiv', '2010-02-24 15:25:53', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('forumrulestext11', 'it', 'messages', 'Mantienilo leggibile', '2007-12-31 13:45:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 103),
	('forumrulestext11', 'lt', 'messages', 'Rašykite taip, kad jūsų pranešimas būtų lengvai skaitomas ir suprantamas', '2007-12-30 19:43:29', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('forumrulestext11', 'nl', 'messages', 'Houd het leesbaar.', '2008-03-29 17:24:54', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('forumrulestext11', 'pl', 'messages', 'Utrzymuj je czytelnym.', '2021-01-16 16:31:07', '2021-01-16 16:31:07', '2021-01-16 16:31:07', 'no', '', 5, NULL, 116789),
	('forumrulestext11', 'pt', 'messages', 'Mantenha as coisas legíveis ', '2012-08-03 11:38:33', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('forumrulestext11', 'ru', 'messages', 'Пожалуйста, заботьтесь об удобстве чтения', '2007-12-16 15:46:29', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 79),
	('forumrulestext11', 'sr', 'messages', 'Нека буде читљиво.', '2013-01-14 12:45:26', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('forumrulestext11', 'zh-hant', 'messages', '保持易讀性。', '2025-05-31 22:36:23', '2025-05-31 22:36:23', '2025-05-31 22:36:23', 'no', '', 5, NULL, 53422),
	('forumrulestext12', 'ca', 'messages', '(c) Acceptes que el fòrum de BeWelcome tingui moderadors/es i que, si incompleixes les normes o no t\'ajustes a les normes d\'ús, les intervencions seran revisades pels moderadors/es.', '2008-03-03 15:09:52', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('forumrulestext12', 'de', 'messages', '(c) Du akzeptierst, dass das Forum von BeWelcome moderiert wird und dass Verstöße gegen die Regeln und Zuwiderhandlung gegen die Richtlinien zur Folge haben, dass du eine Verwanrung erhältst und schließlich vom Forum ausgeschlossen werden kannst.', '2008-03-01 23:55:31', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('forumrulestext12', 'el', 'messages', '(γ) Δέχεσαι ότι το φόρουμ του BeWelcome συντονίζεται, και ότι η παραβίαση των κανόνων ή η μη ακολούθηση των οδηγιών θα οδηγήσει σε επίσημες προειδοποιήσεις και τελικώς σε αποκλεισμό από το φόρουμ.', '2017-07-25 10:03:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 64914),
	('forumrulestext12', 'en', 'messages', '(c) You accept that the forum of BeWelcome is moderated, and breaking the rules or failing to follow the guidelines will lead to formal warnings and ultimately a forum ban.', '2007-11-29 20:58:32', '2019-04-23 18:16:49', '2012-11-18 07:11:03', 'no', '', 5, NULL, 26819),
	('forumrulestext12', 'es', 'messages', '(c) Al hacer uso del mismo aceptas que el foro de BeWelcome está moderado, y que romper las reglas o el no poder seguir las pautas dará lugar a advertencias por parte de los moderadores y en última instancia a un baneo del foro. ', '2007-12-31 16:45:16', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 554),
	('forumrulestext12', 'fr', 'messages', '(c) Vous comprenez et acceptez que le forum de BeWelcome soit un forum avec modérateur. En cas de non-respect des règles ou des lignes de conduite, les contributions seront modérées, les membres recevront une mise en garde et, si besoin, seront bannis du forum.', '2007-12-05 20:12:39', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('forumrulestext12', 'gl', 'messages', '(c) Acepta que o foro de BeWelcome está moderado, e romper as regras ou deixar de seguir as directrices te conducirá a un aviso formal e finalmente á expulsión do foro.', '2021-01-25 16:19:34', '2021-01-25 16:19:34', '2021-01-25 16:19:34', 'no', '', 5, NULL, 210880),
	('forumrulestext12', 'it', 'messages', '(c) Accetti che il forum di BeWelcome sia moderato, e che violare le regole o non seguire le linee guida porterà a degli avvertimenti formali ed eventualmente anche ad essere bandito dal forum.', '2007-12-28 17:46:59', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('forumrulestext12', 'lt', 'messages', '(c) Jūs sutinkate, kad BeWelcome forumas yra moderuojamas, ir taisyklių laužymas ar nurodymų ignoravimas gali baigtis tuo, kad jūsų pranešimai bus (pre)moderuojami.', '2007-12-30 22:30:58', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('forumrulestext12', 'nl', 'messages', '(c) Je accepteert dat de fora van BeWelcome gemodereerd worden, en dat inbreuken op de regels en de richtlijnen van het forum zullen leiden tot formele verwittigingen en uiteindelijk tot verbanning van het forum.', '2012-12-15 13:50:14', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 22382),
	('forumrulestext12', 'pl', 'messages', '(c) Zgadzasz się na to, że forum jest moderowane i że łamanie jego zasad lub nieprzestrzeganie wytycznych prowadzi najpierw do oficjalnego ostrzeżenia, a następnie do zbanowania.', '2021-01-16 16:27:09', '2021-01-16 16:27:09', '2021-01-16 16:27:09', 'no', '', 5, NULL, 116789),
	('forumrulestext12', 'pt', 'messages', '(c) Aceita que o fórum BeWelcome é moderado, e que quebrar as regras ou não seguir as normas levará a avisos e, em último caso, a um afastamento do fórum.', '2012-12-28 16:14:41', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('forumrulestext12', 'ru', 'messages', '(c) Вы соглашаетесь с тем, что форум BeWelcome модерируется, и нарушение правил или отклонение от данного руководства ведет к официальному предупреждению и, в конечном счете, к бану.', '2014-05-11 07:58:16', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('forumrulestext12', 'sr', 'messages', '(в) Прихватате да се форум уређује, и било какво кршење правила ће водити ка званичном упозорењу, и у најгорем случају избацивање са форума.', '2015-02-12 21:31:04', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('forumrulestext12', 'zh-hant', 'messages', '(c) 您同意 BeWelcome 論壇設有版主管理，若違反規定或未能遵守準則，將會收到正式警告，並最終導致論壇封禁。', '2025-05-31 22:25:02', '2025-05-31 22:25:02', '2025-05-31 22:25:02', 'no', '', 5, NULL, 53422),
	('forumrulestext13', 'ca', 'messages', '(d) En casos de problemes freqüents, els moderadors/es poden marcar totes les teves intervencions perquè siguin revisades (en aquest cas, cada intervenció serà aprovada individualment abans que sigui visible al fòrum); i en casos extrems, els moderadors/es tenen la possibilitat de prohibir a un membre la participació al fòrum.', '2008-03-03 15:16:52', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('forumrulestext13', 'de', 'messages', '(d) Falls du dich auch nach einer Verwarnung nicht an die Regeln hältst, wirst du vorübergehend oder dauerhaft vom Forum ausgeschlossen. Vorübergehende Ausschlüsse werden für folgende limitierte Zeiträume ausgesprochen: zuerst 3 Tage, dann 7 Tage, dann 30 Tage und wenn nötig 360 Tage. ', '2008-03-01 23:51:21', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('forumrulestext13', 'el', 'messages', '(δ) Ότι αν αποτύχεις να συμμορφωθείς με τους κανόνες αφού έχεις προειδοποιηθεί από συντονιστή, θα αποκλειστείς προσωρινά ή μόνιμα από τα φόρουμ. Οι προσωρινοί αποκλεισμοί έχουν ισχύ περιορισμένου χρόνου: πρώτα ένας 3-ήμερος αποκλεισμός, μετά ένας 7μερος, ένας 30μερος και αν χρειαστεί ένας 360μερος.', '2017-07-25 10:21:33', '2020-09-02 15:24:34', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('forumrulestext13', 'en', 'messages', '(d) That if you fail to comply with the rules after having been formally warned by a moderator, you will be banned temporarily or permanently from the forums. Temporary bans are valid for a limited period: first a 3-day ban, then a 7-day ban, a 30-day ban and if necessary a 360-day ban.', '2007-11-29 20:58:32', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 347),
	('forumrulestext13', 'es', 'messages', '(d) Que en el caso de fallar en respetar las reglas, luego de haber sido formalmente advertido por un moderador, serás baneado temporal o permanentemente de los foros. Los baneos temporarios son válidos por un determinado período: primero 3 días, luego 7 días, 30 días en tercera instancia y de ser necesario una suspensión de 360 días será aplicada.', '2007-12-31 16:48:52', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 554),
	('forumrulestext13', 'fr', 'messages', '(d) En cas de non respect des règles malgré les mises en gardes, les modérateurs peuvent soumettre les messages d\'un membre à une modération systématique, chaque message devant alors être approuvé individuellement avant d\'être ajouté au forum. Dans les cas extrêmes, les modérateurs peuvent bannir un membre du forum pour une période limitée (3 jours, 7 jours, 30 jours, 1 an) ou de manière définitive.', '2007-12-06 22:15:47', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('forumrulestext13', 'gl', 'messages', '(d) Se non cumpres as regras despois de seres avisado por alguén da moderación, serás expulsado temporalmente ou permanentemente dos foros. As expulsións temporais son para un período limitado: a primeira por 3 días, a segunda por 7 días, despois por 30 días, e se fose necesario por 360 días.', '2021-01-25 16:23:47', '2021-01-25 16:23:47', '2021-01-25 16:23:47', 'no', '', 5, NULL, 210880),
	('forumrulestext13', 'it', 'messages', '(d) Che in caso di mancato rispetto del regolamento dopo un richiamo formale da parte di un moderatore, sarai bandito in maniera temporanea o permanente dai forum. Un bando temporaneo è valido per un periodo limitato di tempo: prima un bando di 3 giorni, poi di 7, poi di 30, e laddove necessario, un bando di 360 giorni.', '2007-12-28 17:46:25', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('forumrulestext13', 'lt', 'messages', '(d) Kad pakartotinių pažeidimų atvejais moderatoriai gali (pre)moderuoti visus jūsų forumo pranešimus (tai reiškia, kiekvienas jūsų išsiųstas forumo pranešimas prieš atsiduriant viešai forume turės būti patvirtintas individualiai vieno iš moderatorių), ir kad ypač retais atvejais moderatoriai gali pasinaudoti galimybe uždrausti nariui skelbtis forume.', '2007-12-30 22:40:15', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('forumrulestext13', 'nl', 'messages', '(d) Nadat je een formele verwittiging hebt gekregen van de moderator en je blijft ingaan tegen de regels en richtlijnen, kan je tijdelijk of definitief verbannen worden van de fora.  Een tijdelijke verbanning kan zijn: eerst gedurende 3 dagen, dan gedurende 7 dagen, dan 30 dagen en als nodig gedurende 360 dagen.', '2012-12-15 13:54:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('forumrulestext13', 'pl', 'messages', '(d) Jeśli nie zastosujesz się do zasad po formalnym ostrzeżeniu od moderatora, zostaniesz tymczasowo lub na stałe zbanowany na forach. Zakazy czasowe mają ograniczoną długość: najpierw 3-dniowy, następnie 7-dniowy, 30-dniowy i w razie potrzeby 360-dniowy.', '2021-01-17 00:22:43', '2021-01-17 00:22:43', '2021-01-17 00:22:43', 'no', '', 5, NULL, 116789),
	('forumrulestext13', 'pt', 'messages', '(d) Que se não obedecer às regras depois de ter sido formalmente avisado por um moderador, será afastado/a temporária ou permanentemente dos fóruns. Afastamentos temporários são válidos por um período limitado: primeiro um afastamento de 3 dias, depois de 7 dias, 30 dias e, se necessário, um afastamento por 360 dias.', '2012-12-28 16:13:46', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('forumrulestext13', 'ru', 'messages', '(d) В случае, если Вы нарушаете правила после того, как официально получили предупреждение от модератора, Вас могут забанить на форуме временно или постоянно. Временный бан может быть установлен на период: первый - на 3 дня, затем на 7 дней, 30 дней и при необходимости на 360 дней.', '2014-05-10 12:40:56', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('forumrulestext13', 'sr', 'messages', '(г) Ако се не повинујете правилима наког упозорења уредника, бићете привремено или трајно искључени са форума. Привремене забране могу трајати 3, 7, 30 и ако треба 360 дана.', '2015-02-01 21:31:43', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('forumrulestext13', 'zh-hant', 'messages', '(d) 若您在收到版主正式警告後仍未能遵守規範，將會被暫時或永久禁止進入論壇。暫時禁止進入的期限如下：初犯為三天，之後依序為七天、三十天，必要時可達三百六十天。', '2025-05-31 22:24:30', '2025-05-31 22:24:30', '2025-05-31 22:24:30', 'no', '', 5, NULL, 53422),
	('forumrulestext14', 'ca', 'messages', '(e) Els moderadors/es són l\'autoritat al fòrum i, per tant, tenen l\'última paraula a totes les disputes del fòrum.', '2008-03-03 15:19:36', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('forumrulestext14', 'de', 'messages', '(e) Moderatoren haben volle Handlungsbefugnis in diesem Forum und deshalb haben sie das letzte Wort bei allen Auseinandersetzungen in diesem Forum. Öffentliche Aufrufe, gemeinsam gegen die Entscheidungen der Moderatoren anzukämpfen, werden nicht toleriert.', '2008-03-01 23:34:30', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('forumrulestext14', 'el', 'messages', '(ε) Ότι οι συντονιστές είναι υπεύθυνοι του φόρουμ και συνεπώς έχουν το τελευταίο λόγο σε κάθε διαμάχη εκεί. Η δημόσια σύγκρουση με τις αποφάσεις των συντονιστών δεν θα γίνει ανεκτή.', '2017-07-25 10:31:48', '2020-08-26 14:33:15', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('forumrulestext14', 'en', 'messages', '(e) That moderators are the authority in the forum and hence have the last word in any and all disputes in the forum. Public rallying against moderator decisions will not be tolerated.', '2007-11-29 20:58:32', '2019-04-23 18:16:49', '2012-11-18 07:12:57', 'no', '', 5, NULL, 26819),
	('forumrulestext14', 'es', 'messages', '(e) Los moderadores son la autoridad en el foro y por lo tanto tienen la última palabra en cualquier conflicto que se presente. Protestas públicas contra las decisiones de los moderadores no serán toleradas.', '2007-12-31 16:55:18', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 554),
	('forumrulestext14', 'fr', 'messages', '(e) Les modérateurs ont pleine autorité et auront le dernier mot en cas de conflit sur le forum. Merci de ne pas créer de coalition publique contre la décision d\'un modérateur.', '2007-12-05 20:10:05', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('forumrulestext14', 'gl', 'messages', '(e) O equipo de moderación son a autoridade no foro e polo tanto teñen a última palabra en calquera disputa no foro. As manifestacións públicas contra as decisións dunha persoa moderadora non serán toleradas.', '2021-01-25 16:26:19', '2021-01-25 16:26:19', '2021-01-25 16:26:19', 'no', '', 5, NULL, 210880),
	('forumrulestext14', 'it', 'messages', '(e) Che i moderatori hanno autorità nel forum e dunque hanno l’ultima parola in ogni disputa nel forum. L\'unirsi in massa contro le decisioni di un moderatore non sarà tollerato.', '2007-12-28 17:40:19', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('forumrulestext14', 'lt', 'messages', '(e) Kad moderatoriai yra įgalioti teisingų ir objektyvių sprendimų vykdytojai šiame forume, ir, vadinasi, turi paskutinį žodį bet kokiuose (visuose) forumo disputuose.', '2007-12-30 22:22:25', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('forumrulestext14', 'nl', 'messages', 'De moderators zijn gezaghebbend op de fora en zij hebben het laatste woord in een geschil. Het publiek ophitsen tegen een beslissing genomen door een moderator wordt niet getolereerd.', '2012-12-15 13:59:04', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('forumrulestext14', 'pl', 'messages', '(e) moderatorzy są osobami odpowiedzialnymi za forum i dlatego mają ostatnie słowo w każdej dyskusji, która się tam odbywa. Publiczne sprzeciwianie się moderatorowi nie będzie tolerowane.', '2021-01-16 16:24:57', '2021-01-16 16:24:57', '2021-01-16 16:24:57', 'no', '', 5, NULL, 116789),
	('forumrulestext14', 'pt', 'messages', '(e) Que os moderadores são a autoridade no fórum e, portanto, têm a última palavra sobre qualquer disputa no fórum. Não serão tolerados boicotes públicos às decisões do moderador.', '2012-12-28 16:11:54', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('forumrulestext14', 'ru', 'messages', '(e) Модераторы - представители администрации на форуме и, следовательно, их слово является последним во всех дискуссиях на форуме. Общественные аппеляции к решению модераторов не допускаются.', '2014-05-11 07:56:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('forumrulestext14', 'sr', 'messages', '(д) Уредници су заон на форуму и због тога имају последњу реч за све спорове на форуму. Јавна протести против уредникових одлука се неће толерисати.', '2015-02-12 21:25:30', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('forumrulestext14', 'zh-hant', 'messages', '(e) 版主是論壇中的最高權限，因此在論壇中的任何爭議都擁有最終決定權。公開反對版主決策的行為將不被容忍。', '2025-05-31 22:23:51', '2025-05-31 22:23:51', '2025-05-31 22:23:51', 'no', '', 5, NULL, 53422),
	('forumrulestext15', 'ca', 'messages', '(f) Els moderadors/es tenen l\'opció de bloquejar o esborrar temes del fòrum si incompleixen les normes, si es descontrolen, si queden desfasats, si són enviaments múltiples (<i>crossposting</i>) o si són atacs al fòrum.', '2008-03-03 15:24:06', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('forumrulestext15', 'de', 'messages', '(f) Moderatoren haben die Möglichkeit Themen zu sperren oder zu löschen, wenn sie gegen die Regeln verstoßen, außer Kontrolle geraten, veraltet sind, es sich dabei um das nochmalige Posten desselben Themas handelt ("cross-posting") oder wenn sie aus anderen Gründen in Widerspruch mit dem Forum stehen.', '2008-03-01 23:37:31', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('forumrulestext15', 'el', 'messages', '(στ) Ότι οι συντονιστές έχουν την επιλογή να κλειδώσουν ή να διαγράψουν νήματα αν αυτά παραβιάζουν τους κανόνες, καθίστανται μη ελεγχόμενα, δεν ισχύουν πια, είναι  διπλο-αναρτημένα ή δημιουργούν με άλλους τρόπους δυσαρμονία στο φόρουμ.', '2017-07-25 10:36:01', '2020-08-26 14:32:25', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('forumrulestext15', 'en', 'messages', '(f) That moderators have the option to lock or delete threads if they are breaking the rules, getting out of control, outdated, cross-postings or in other ways at odds with the forum.', '2007-11-29 20:58:32', '2019-04-23 18:16:49', '2008-08-09 12:30:44', 'no', '', 5, NULL, 101),
	('forumrulestext15', 'es', 'messages', '(f) Los moderadores tienen la opción de bloquear o suprimir los hilos o enlaces sí están rompiendo las reglas, saliéndose de control, usando mensajes cruzados o de cualquier otra forma fuera de lugar en el foro.', '2007-12-31 16:54:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 554),
	('forumrulestext15', 'fr', 'messages', '(f) Les modérateurs peuvent bloquer ou effacer une série de messages qui violeraient les règles, seraient hors-sujet, pollueraient ou nuiraient au forum.', '2007-12-06 21:55:39', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('forumrulestext15', 'gl', 'messages', '(f) As persoas moderadoras teñen a opción de pechar ou borrar fíos se rompen as regras, están fora de control, desfasados, duplicados ou dalgún modo fora de lugar no foro.', '2021-01-25 16:29:35', '2021-01-25 16:29:35', '2021-01-25 16:29:35', 'no', '', 5, NULL, 210880),
	('forumrulestext15', 'it', 'messages', '(f) I moderatori hanno la possibilità di bloccare o cancellare discussioni se esse violano le regole, escono da ogni controllo, sono datate o piene di riferimenti ad altre discussioni o per altri motivi sono estranee al forum.', '2007-12-28 17:41:56', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 13861),
	('forumrulestext15', 'lt', 'messages', '(f) Kad moderatoriai turi teisę užrakinti arba pašalinti tam tikras forumo temas, jei yra taisyklių pažeidimų, arba jei situacija jose tampa nekontroliuojama, jei tema yra visiškai neaktuali ir neturi jokios vertės, besikartojanti, arba kitaip neatitinka tvarkos forume nurodymų.', '2007-12-30 22:28:04', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('forumrulestext15', 'nl', 'messages', '(f) Moderators kunnen discussies sluiten of verwijderen als ze in strijd zijn met de regels of richtlijnen, als ze uit de hand lopen, verouderd zijn, of als ze op enige manier tot spanningen leiden op het forum.', '2012-12-15 14:05:42', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('forumrulestext15', 'pl', 'messages', '(f) Moderatorzy mają możliwość blokowania lub usuwania wątków, które łamią zasady, wymykają się spod kontroli, zdezaktualizowały się, zawierają crossposting lub w inny sposób są sprzeczne z forum.', '2021-01-17 00:18:50', '2021-01-17 00:18:50', '2021-01-17 00:18:50', 'no', '', 5, NULL, 116789),
	('forumrulestext15', 'pt', 'messages', '(f) Que os moderadores têm a opção de bloquear ou eliminar segmentos de discussões que estiverem a quebrar regras, houver descontrole expresso, desactualizados, fora de contexto ou de outra maneira serem desadequadas ao forum. ', '2013-01-16 20:00:41', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 36712),
	('forumrulestext15', 'ru', 'messages', '(f) Этот модератор имеет возможность блокировать или удалить ветку Форума, если она нарушает его правила, выходит из-под контроля, устарела или другим образом не соответствует Форуму.', '2014-05-20 18:58:52', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('forumrulestext15', 'sr', 'messages', '(ђ) Уредници имају могућност да закључају или обришу тему ако крше правила, измичу контроли или другачије ометају форум.', '2015-02-12 21:28:04', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('forumrulestext15', 'zh-hant', 'messages', '(f) 版主有權鎖定或刪除討論串，如果這些討論串違反規定、失控、過時、重複發文，或以其他方式與論壇宗旨不符。', '2025-05-31 22:22:13', '2025-05-31 22:22:13', '2025-05-31 22:22:13', 'no', '', 5, NULL, 53422),
	('forumrulestext2', 'ca', 'messages', 'Evita els atacs personals i els comentaris destructius.', '2008-03-03 14:36:23', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('forumrulestext2', 'de', 'messages', 'Kein Attackieren oder Beschimpfen anderer Mitglieder. Das beinhaltet auch Nachrichten, die eine andere Person nicht direkt benennen, aber sich auf andere Weise auf sie beziehen.', '2008-03-01 22:09:41', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('forumrulestext2', 'el', 'messages', 'Όχι προσωπικές επιθέσεις ή εχθρικά μηνύματα. Αυτό συμπεριλαμβάνει το να αναφέρεσαι σε ανθρώπους αποκαλώντας τους κάτι άλλο πέραν του ονόματος τους.', '2017-07-25 10:11:09', '2020-09-02 16:02:31', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('forumrulestext2', 'en', 'messages', 'No personal attacks or flaming. This also includes referring to people while identifying them by other means than their names.', '2007-11-29 20:58:32', '2019-04-23 18:16:49', '2012-11-18 07:03:47', 'no', '', 5, NULL, 26819),
	('forumrulestext2', 'es', 'messages', 'No ataques personales o mensajes agresivos u ofensivos. Esto incluye referirse a personas identificándolas de otra manera que no sea usando su nombre.', '2007-12-31 16:32:53', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 554),
	('forumrulestext2', 'fr', 'messages', 'Merci d\'éviter les attaques personnelles, les campagnes de dénigrement ou les insultes. Merci de ne pas faire référence aux membres en les identifiant autrement que par leur nom.', '2007-12-05 20:15:57', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('forumrulestext2', 'gl', 'messages', 'Sen ataques persoais ou mensaxes hostís. Isto tamén inclúe referirse a outras persoas identificándoas por outros medios distintos aos seus nomes.', '2021-01-25 15:25:52', '2021-01-25 15:25:52', '2021-01-25 15:25:52', 'no', '', 5, NULL, 210880),
	('forumrulestext2', 'it', 'messages', 'Niente attacchi personali o messaggi offensivi. Questo include anche il riferimento a persone identificandole in altri modi che usando il loro nome/il loro nome utente.', '2007-12-29 15:41:08', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('forumrulestext2', 'lt', 'messages', 'Jokių asmeninių atakų', '2007-12-17 04:58:10', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('forumrulestext2', 'nl', 'messages', 'Geen persoonlijke aanvallen of agressieve taal.  Ook niet zonder mensen bij naam te noemen, maar zo te verwijzen dat ze identificeerbaar zijn.', '2012-12-15 13:33:33', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('forumrulestext2', 'pl', 'messages', 'Żadnych osobistych ataków i flejmów. To także dotyczy odnoszenia się do ludzi inaczej niż za pomocą ich nazw użytkownika / imion.', '2021-01-15 09:52:19', '2021-01-15 09:52:19', '2021-01-15 09:52:19', 'no', '', 5, NULL, 116789),
	('forumrulestext2', 'pt', 'messages', 'Não faça ataques pessoais nem difame. Isto inclui referências a pessoas identificando-as de outra forma que não os seus nomes.', '2009-09-08 13:45:11', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('forumrulestext2', 'ru', 'messages', 'Запрещаются персональные нападки или флейм. Запрещается обращаться к другим участникам иным образом, кроме как по имени.', '2014-05-11 08:00:59', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('forumrulestext2', 'sr', 'messages', 'Без нападања и вређања. Ово такође укључује наивање људи разноразним именима.', '2015-02-12 18:31:42', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('forumrulestext2', 'zh-hant', 'messages', '請勿進行人身攻擊或引戰。這也包括不以姓名，而是透過其他方式指稱他人。', '2025-05-31 22:29:00', '2025-05-31 22:29:00', '2025-05-31 22:29:00', 'no', '', 5, NULL, 53422),
	('forumrulestext3', 'ca', 'messages', 'El fòrum NO ÉS un judici públic, ni cal deixar ningú com un drap brut. (Això quant a les persones, naturalment es permet tota discussió de problemes generals o d\'abusos)', '2008-03-03 14:45:42', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('forumrulestext3', 'de', 'messages', 'Dieses Forum ist KEIN öffentlicher Richtplatz. Stelle niemand an den Pranger (dies gilt für andere Personen - jegliche allgemeine Diskussion über Probleme oder Missstände ist natürlich erlaubt).', '2008-03-01 23:14:49', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('forumrulestext3', 'el', 'messages', 'Το φόρουμ ΔΕΝ αποτελεί δημόσια δίκη. ΔΕΝ κρεμάμε ανθρώπους να στεγνώσουν δημοσίως (αυτό σχετίζεται ΚΑΘΑΡΑ  με συγκεκριμένα άτομα- οποιαδήποτε γενική συζήτηση προβλημάτων ή κακοποίησης επιτρέπεται).', '2017-07-25 10:14:21', '2020-08-26 14:35:45', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('forumrulestext3', 'en', 'messages', 'The forum is NOT a public trial. NO hanging people out to dry publicly (this is PURELY in relation to persons - any general discussions of problems or abuse is allowed).', '2007-11-29 20:58:32', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 347),
	('forumrulestext3', 'es', 'messages', 'Los foros NO son lugar para hacer juicios públicos. Nada de linchamientos a personas para dejarlas en evidencia ante el resto (esto aplica únicamente a nivel personal; cualquier debate general sobre problemas o abusos está permitido).', '2008-01-09 19:16:34', '2020-11-30 01:44:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 25548),
	('forumrulestext3', 'fr', 'messages', 'Le forum n\'est pas un tribunal. Merci de ne pas lyncher un membre ou une personne extérieure au réseau (cette remarque ne concerne que les individus - tout débat autour d\'un problème ou d\'un abus est autorisé)', '2007-12-05 20:15:12', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('forumrulestext3', 'gl', 'messages', 'O foro NON é un xuízo público.  NON sacar a relucir os trapos sucios doutras persoas (isto é ESTRITAMENTE en relación ás persoas, se permite calquera discusión de problemas ou abusos).', '2021-01-25 15:30:44', '2021-01-25 15:30:44', '2021-01-25 15:30:44', 'no', '', 5, NULL, 210880),
	('forumrulestext3', 'it', 'messages', 'Il forum NON è un processo pubblico. Quindi NON è consentito il linciaggio pubblico di altre persone (questo SOLO in relazione ad altre persone – qualsiasi discussione generale di problemi ed abusi è ammessa).', '2007-12-28 17:48:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 13861),
	('forumrulestext3', 'lt', 'messages', 'Forumas NĖRA viešasis teismas. Negalima teisti ar užgaulioti kitus narius (tai galioja asmenų aptarimui ir tik dalinai įtraukia bendras diskusijas dėl tam tikrų problemų ar piktnaudžiavimo)', '2007-12-31 00:09:31', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('forumrulestext3', 'nl', 'messages', 'Het forum is GEEN publiek proces van mensen. Er worden geen mensen aan de schandpaal genageld (dit gaat ALLEEN over mensen – alle discussies over inhoud en problemen van misbruik is toegelaten).', '2012-12-15 13:37:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40169),
	('forumrulestext3', 'pl', 'messages', 'Forum NIE jest publicznym procesem. NIE zajmujemy się tu linczowaniem osób.  (Zasada ta odnosi się WYŁĄCZNIE do osób - wszelkie dyskusje o ogólnych problemach czy nadużyciach są dozwolone).', '2021-01-17 00:27:34', '2021-01-17 00:27:34', '2021-01-17 00:27:34', 'no', '', 5, NULL, 116789),
	('forumrulestext3', 'pt', 'messages', 'O fórum NÃO é um julgamento na praça pública. NÃO serão aceites enxovalhos nem injúrias (isto é APENAS no que diz respeito a pessoas - qualquer discussão sobre problemas ou abuso é permitida).', '2013-01-08 15:22:36', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('forumrulestext3', 'ru', 'messages', 'Форум - НЕ общественный суд. НЕ ДОПУСКАЕТСЯ выставлять кого-либо на общественное обсуждение (это правило распространяется только на конкретных людей; допускается общие обсуждения проблем и злоупотреблений).', '2014-05-10 12:46:19', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('forumrulestext3', 'sr', 'messages', 'Форум НИЈЕ јавни суд. Не вешамо јавно људе. Дискусије о проблемима и злоупотребама су дозвољене.', '2015-02-12 21:33:39', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('forumrulestext3', 'zh-hant', 'messages', '本論壇並非公開審判庭。嚴禁公開羞辱他人（這僅限於針對個人的行為—任何關於問題或濫用行為的普遍性討論是允許的）。', '2025-05-31 22:28:45', '2025-05-31 22:28:45', '2025-05-31 22:28:45', 'no', '', 5, NULL, 53422),
	('forumrulestext4', 'ca', 'messages', 'Evita el correu brossa i els enviaments múltiples (<i>crossposting</i>).', '2008-03-03 14:49:27', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('forumrulestext4', 'de', 'messages', 'Kein Spamming, kein Veröffentlichung von Nachrichten an mehreren Stellen ("cross-posting"). Cross-posting kann in Einzelfällen in Ordnung sein, wenn du deine Nachricht nur in einigen wenigen Gruppen veröffentlichst für die sie jedenfalls relevant ist.', '2008-03-01 23:59:49', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('forumrulestext4', 'el', 'messages', 'Δεν κάνουμε άσχετες ή υπερβολικά πολλές αναρτήσεις, δεν διπλο-αναρτούμε. Η διπλο-ανάρτηση μπορεί να είναι αποδεκτή αν αναρτάς σε περιορισμένο αριθμό ομάδων και η ανάρτησή σου είναι σχετική με όλες τους.', '2017-07-25 11:03:22', '2020-09-02 15:36:10', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('forumrulestext4', 'en', 'messages', 'No spamming, no cross-posting. Cross-posting may be acceptable if you post to a limited number of groups and your post is relevant to all of them.', '2007-11-29 20:58:32', '2019-04-23 18:16:49', '2012-11-18 07:04:19', 'no', '', 5, NULL, 26819),
	('forumrulestext4', 'es', 'messages', 'No mensajes basura (Spam) o envíos cruzados (crossposting). Envíos cruzados pueden ser aceptables si se trata de envíos limitados a distintos grupos y los mismos son relevantes en todos ellos.', '2007-12-31 16:38:06', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 554),
	('forumrulestext4', 'fr', 'messages', 'Les spams et le crossposting (multiplication des messages) sont interdits. Le crossposting est toléré si vous postez dans un nombre limité de groupes et que les messages sont pertinents dans chacun des groupes.', '2007-12-01 21:38:57', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('forumrulestext4', 'gl', 'messages', 'Non enviar mensaxes non desexadas, no duplicar as mensaxes. O duplicado de mensaxes podería ser aceptable se os envías a un número limitado de grupos e as túas mensaxes son relevantes para todos eles.', '2021-01-25 15:32:27', '2021-01-25 15:32:27', '2021-01-25 15:32:27', 'no', '', 5, NULL, 210880),
	('forumrulestext4', 'it', 'messages', 'Niente spam, e niente crossposting (pubblicare ripetutamente lo stesso contenuto in gruppi diversi). La pubblicazione ripetuta può essere tollerata se pubblichi in un numero limitato di gruppi e il tuo post è rilevante per ognuno di essi.', '2007-12-31 13:27:20', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('forumrulestext4', 'lt', 'messages', 'Jokių elektroninių šiukšlių, jokio tarpteminio siuntimo (t.y. to paties pranešimo siuntimo į daugelį forumo temų)', '2007-12-30 23:05:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('forumrulestext4', 'nl', 'messages', 'Geen spam, geen crossposts.  Cross-posten kan aanvaardbaar zijn als je naar een beperkt aantal groepen stuurt en je bijdrage voor elk van deze groepen relevant is.', '2008-04-04 17:09:25', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('forumrulestext4', 'pl', 'messages', 'Zakaz spamowania i crosspostowania. Crosspost może być akceptowane tylko w przypadku gdy zamieszczasz swój post w ograniczonej liczbie grup i w każdej z nich jest on uzasadniony tematycznie.', '2021-01-16 16:35:45', '2021-01-16 16:35:45', '2021-01-16 16:35:45', 'no', '', 5, NULL, 116789),
	('forumrulestext4', 'pt', 'messages', 'Nada de publicidade nem de colocar a mesma mensagem em vários grupos. Este último caso pode ser aceitável se a mensagem for colocada num número limitado de grupos e for relevante em todos eles.', '2012-12-28 16:16:54', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('forumrulestext4', 'ru', 'messages', 'Запрещаются спам и кросс-посты.Крос-постинг допустим, если вы оставляеете сообщения в ограниченном количестве групп и сообщение применимо ко всем этим группам.', '2007-12-16 15:45:19', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('forumrulestext4', 'sr', 'messages', 'Не спамујте, не објављујте поруке са других тема. Објава порука са других тема је прихватљива ако се то ради у ограниченом броју и ако је та порука битна осталима.', '2015-02-21 12:54:22', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('forumrulestext4', 'zh-hant', 'messages', '請勿濫發訊息，請勿重複發文。重複發文在某些情況下可被接受，但僅限於您發布到數量有限的群組，並且您的貼文與所有這些群組都相關。', '2025-05-31 22:28:19', '2025-05-31 22:28:19', '2025-05-31 22:28:19', 'no', '', 5, NULL, 53422),
	('forumrulestext5', 'ca', 'messages', 'No facis pública informació personal d\'altres persones.', '2008-03-03 14:49:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('forumrulestext5', 'cs', 'messages', 'Žádné publikování osobních údajů dalších lidí. To zahrnuje parafrázování podstatných částí jejich profilu.', '2014-01-30 12:00:06', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('forumrulestext5', 'de', 'messages', 'Kein Veröffentlichen persönlicher Informationen über andere Leute. Das inkludiert das Posten (wörtlich oder umschreibend) von wesentlichen Teilen des Profils anderer Personen.', '2008-02-10 12:19:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('forumrulestext5', 'el', 'messages', 'Δεν αναρτούμε προσωπικές πληροφορίες άλλων. Αυτό περιλαμβάνει επίσης και το να παραφράζουμε σημαντικά κομμάτια των προφίλ τους.', '2017-07-25 10:58:27', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 64914),
	('forumrulestext5', 'en', 'messages', 'No posting personal info on other people. This also includes paraphrasing significant parts of their profiles.', '2007-11-29 20:58:32', '2019-04-23 18:16:49', '2012-11-18 07:06:27', 'no', '', 5, NULL, 26819),
	('forumrulestext5', 'es', 'messages', 'No publicar información personal sobre otras personas. Esto incluye citar partes significantes de sus perfiles.', '2007-12-31 16:38:42', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 554),
	('forumrulestext5', 'fr', 'messages', 'Merci de ne pas poster de données personnelles sur d\'autres personnes - la paraphrase de portions importantes d\'un profil ne sera pas tolérée.', '2007-12-01 21:39:38', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('forumrulestext5', 'gl', 'messages', 'No enviar información persoal doutra xente. Isto inclúe parafrasear partes significativas dos seus perfís.', '2021-01-25 15:33:32', '2021-01-25 15:33:32', '2021-01-25 15:33:32', 'no', '', 5, NULL, 210880),
	('forumrulestext5', 'hr', 'messages', 'Bez objavljivanja osobnih podataka drugih osoba', '2010-02-24 15:25:35', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('forumrulestext5', 'it', 'messages', 'Non pubblicare informazioni personali riguardanti altre persone. Questo include parafrasare parti significative dei loro profili.', '2007-12-29 15:44:33', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('forumrulestext5', 'lt', 'messages', 'Jokio kitų žmonių asmeninės informacijos skelbimo ', '2007-12-30 18:55:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('forumrulestext5', 'nl', 'messages', 'Er wordt geen informatie over andere mensen gepost.  Dit betreft ook het parafraseren van delen van hun profiel.', '2012-12-15 13:39:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('forumrulestext5', 'pl', 'messages', 'Zabronione jest prostowanie osobistych informacji o innych osobach. Dotyczy to też parafrazowania znaczących części ich profilów.', '2021-01-16 16:33:05', '2021-01-16 16:33:05', '2021-01-16 16:33:05', 'no', '', 5, NULL, 116789),
	('forumrulestext5', 'pt', 'messages', 'Não publique dados pessoais de outras pessoas. Isto inclui citar partes significativas dos seus perfis.', '2012-12-28 16:17:36', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('forumrulestext5', 'ru', 'messages', 'Запрещается выкладывать личную информацию других людей. Это также относится к пересказу существенных частей из их профилей.', '2007-12-16 15:44:59', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('forumrulestext5', 'sr', 'messages', 'Без објављивања личних информација других људи. То такође укључује преписивање битних делова са њихових профила.', '2015-02-21 12:56:14', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('forumrulestext5', 'zh-hant', 'messages', '請勿發布他人的個人資訊。這也包括改述其個人資料中的重要部分。', '2025-05-31 22:27:54', '2025-05-31 22:27:54', '2025-05-31 22:27:54', 'no', '', 5, NULL, 53422),
	('forumrulestext6', 'ca', 'messages', 'Segueix els consells i les peticions dels moderadors.', '2008-03-03 14:50:54', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 3236),
	('forumrulestext6', 'de', 'messages', 'Ein Mitglied hat das Recht, sich an das <a href="wiki/Who_does_what">Moderations-Team</a> zu wenden und ihm Gründe zu nennen, warum es eine Entscheidung überdenken sollte. Wenn das Team bei seiner Entscheidung bleibt, kann beim Ombudsmann Widerspruch eingelegt werden. Wenn es keinen Ombudsmann gibt oder falls ein Mitglied den Eindruck hat, dass der Ombudsmann eine falsche Entscheidung getroffen hat, kann ein endgültiger Widerspruch beim Vorstand eingelegt werden.\r\n\r\nDie Korrespondenz zwischen dem Mitglied und dem Moderator, dem Moderations-Team, dem Ombudsmann oder dem Vorstand ist persönlich. Es ist nicht erlaubt, den Schriftwechsel ganz oder teilweise im Forum oder auf anderen Seiten darzustellen. Die Übermittlung von Informationen aus der Korrespondenz an dritte Parteien ist inakzeptabel und kann eine Beendigung der Mitgliedschaft zur Folge haben. Während der gesamten Zeit des Widerspruchs gilt die ursprüngliche Entscheidung des Moderations-Teams.', '2008-02-10 12:21:24', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 172939),
	('forumrulestext6', 'el', 'messages', 'Τα μέλη έχουν το δικαίωμα να προσεγγίσουν τη <a href="wiki/Who_does_what">συντονιστική ομάδα (moderation team)</a> με σκοπό την επανεξέταση μιας απόφασης από την ομάδα. Αν η ομάδα παραμείνει στην αρχική της απόφαση, τότε η απόφαση αυτή μπορεί να εξεταστεί από το Διαμεσολαβητή. Σε περίπτωση απουσίας του Διαμεσολαβητή, ή αν ένα μέλος νιώθει ότι ο Διαμεσολαβητής πήρε λανθασμένη απόφαση,  μπορεί να γίνει μια τελική έφεση προς το Διοικητικό Συμβούλιο.\r\n\r\nΗ αλληλογραφία μεταξύ του μέλους και του συντονιστή της συντονιστικής ομάδας, του διαμεσολαβητή ή του Διοικητικού Συμβουλίου είναι προσωπική. Μερική ή ολική έκθεση της αλληλογραφίας στο φόρουμ ή σε άλλους ιστοτόπους δεν επιτρέπεται. Η μετάδοση πληροφοριών από την αλληλογραφία σε τρίτους είναι μη αποδεκτή και μπορεί να οδηγήσει σε διαγραφή του μέλους. Καθ όλη τη διάρκεια της έφεσης, η απόφαση της συντονιστικής ομάδας παραμένει σε ισχύ.', '2017-07-25 11:08:58', '2020-09-02 15:37:19', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('forumrulestext6', 'en', 'messages', 'A member has the right to approach the <a href="wiki/Who_does_what">moderation team</a> with reasons why the team should reconsider a decision. If the team sticks with the decision, that decision can be appealed to the Ombudsman. In case of the absence of an Ombudsman, or if a member feels the Ombudsman has reached an incorrect decision, a final appeal can be made to the Board of Directors.\r\n\r\nCorrespondence between the member and moderator, the moderation team, the ombudsman or the Board of Directors is personal. Partial or full displaying of correspondence on the forum or other sites is not permitted.The transmission of information from the correspondence to third parties is unacceptable and can result in the termination of membership. The entire time of the appeal, the decision of the moderation team stays in place.', '2007-11-29 20:58:32', '2019-04-23 18:16:49', '2015-04-11 11:17:44', 'no', '', 0, NULL, 42397),
	('forumrulestext6', 'es', 'messages', 'Preste atención a cualquier consejo y petición de los moderadores. Los ataques personales hacia moderadores no serán tolerados. Ante una disidencia con la decision de un moderador, puede contactar al <a href="wiki/Who_does_what">equipo de moderadores</a>. La decision resuelta por el equipo de moderadores ante tal caso es final e inapelable.', '2007-12-31 16:37:05', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 554),
	('forumrulestext6', 'fr', 'messages', 'Les membres peuvent contacter <a href="wiki/Who_does_what">les modérateurs</a> pour s\'expliquer et tenter de les convaincre de revenir sur leur décision. Si l’équipe maintient sa décision, il est possible de faire appel auprès d\'un ombudsman. En cas d’indisponibilité d’un ombudsman, ou si le membre pense que l\'ombudsman a pris une mauvaise décision, il est possible de faire appel une dernière fois auprès du Conseil d\'administration.\r\n\r\nLes échanges entre les membres, modérateurs, ombudsmans et conseil d’administration sont strictement personnels. Il est interdit de diffuser les échanges, de manière partielle ou dans leur intégralité, sur les forums ou sur d\'autres sites que BeWelcome. Il est également interdit de transmettre à des tiers des données issues de ces échanges. Tout manquement pourra aboutir à la résiliation des droits d\'adhésion du membre. Durant le temps de l’appel, la décision initiale des modérateurs reste valide et opérationnelle.', '2007-12-02 19:00:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 56017),
	('forumrulestext6', 'gl', 'messages', 'Unha persoa da comunidade ten o dereito de dirixirse ao <a href="wiki/Who_does_what">equipo de moderación</a> coas razóns polas que o equipo debería reconsiderar unha decisión. Se o equipo se mantén firme coa decisión, esa decisión poderá apelarse a mediación. No caso de que non haxa unha persoa mediadora, ou a persoa afectada sente que a persoa mediadora tomo unha decisión incorrecta, pódese facer unha apelación final á Xunta Directiva.\r\n\r\nA correspondencia entre a persoa afectada, o moderador/a, o equipo de moderación, a persoa mediadora, ou a Xunta Directiva é persoal. Non está permitido mostrar a correspondencia parcial ou totalmente no foro ou noutros sitios . El envío de información da correspondencia a terceiras persoas é inaceptable e pode dar lugar á conclusión da condición de persoa pertencente á comunidade. Durante todo o período de apelación, a decisión do equipo de moderación é firme.', '2021-01-25 15:44:41', '2021-01-25 15:44:41', '2021-01-25 15:44:41', 'no', '', 5, NULL, 210880),
	('forumrulestext6', 'hr', 'messages', 'Pridržavaj se svih savjeta i zahtjeva moderatora', '2010-04-23 12:23:06', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 8197),
	('forumrulestext6', 'it', 'messages', 'Un membro ha il diritto di appellarsi alla <a href="wiki/Who_does_what">squadra dei moderatori</a> con le ragioni per le quali la squadra dovrebbe riconsiderare una decisione. Se la squadra riafferma la decisione, contro tale decisione può essere presentato ricorso al Mediatore. In caso di assenza di un Mediatore o se un membro ritiene che il Mediatore abbia preso una decisione sbagliata, un appello finale può essere rivolto al Consiglio di Amministrazione.\r\n\r\nLa corrispondenza tra membro e moderatore, la squadra dei moderatori, il mediatore o il Consiglio di Amministrazione è personale. Parziale o totale visualizzazione della corrispondenza nel forum o in altri siti non è permessa. La trasmissione di informazioni circa la corrispondenza a terzi è inaccettabile e può comportare l\'esclusione dalla comunità. Per tutto il tempo del ricorso, la decisione della squadra dei moderatori continua ad esser valida.', '2007-12-31 13:33:44', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 95970),
	('forumrulestext6', 'lt', 'messages', 'Paisykite visų moderatorių patarimų ir prašymų', '2007-12-30 18:50:11', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 227),
	('forumrulestext6', 'nl', 'messages', 'Een lid heeft het recht om het <a href="wiki/Who_does_what">forum beheerteam</a> te benaderen met argumenten waarom het team een beslissing zou moeten heroverwegen. Als het team bij de beslissing blijft, dan kan de beslissing aanhangig gemaakt worden bij de Ombudsman. Als er geen Ombudsman is, of als een lid vindt dat de Ombudsman een verkeerde beslissing heeft genomen, dan kan een laatste bezwaar worden ingediend bij de Raad van Bestuur.\r\n\r\nCorrespondentie tussen het lid en de moderator, het beheerteam, de Ombudsman en de Raad van Bestuur is persoonlijk. Geheel of gedeeltelijke publicatie van zulke correspondentie op het forum of andere websites is niet toegestaan. De overdracht van informatie uit de correspondentie naar derden is onacceptabel en kan leiden in be-eindiging van het lidmaatschap. Zolang de procedure van bezwaar voortduurt, bljft de beslissing die is genomen door het beheerteam gelden.', '2012-12-15 13:44:35', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 40169),
	('forumrulestext6', 'pl', 'messages', 'Każdy członek i członkini ma prawo zwrócić się do <a href="wiki/Who_does_what">zespołu moderującego</a>, podając powody, dla których zespół powinien ponownie rozważyć decyzję. Jeśli zespół będzie się trzymał swojej pierwotnej decyzji, można się od niej odwołać do Ombudsmana. W przypadku nieobecności Ombudsmana lub gdy uważasz, że Ombudsman podjął niewłaściwą decyzję, można wnieść ostateczne odwołanie do Board of Directors.\r\n\r\nKorespondencja między członkiem a moderatorem, zespołem moderującym, Ombudsmanem lub Board of Directors ma charakter prywatny. Częściowe lub pełne wyświetlanie korespondencji na forum lub na innych stronach jest niedozwolone, a przekazywanie informacji z korespondencji osobom trzecim jest niedopuszczalne i może skutkować wypowiedzeniem członkostwa. Przez cały czas trwania odwołania decyzja moderatorów jest obowiązująca.', '2021-01-17 00:09:11', '2021-01-17 00:09:11', '2021-01-17 00:09:11', 'no', '', 5, NULL, 116789),
	('forumrulestext6', 'pt', 'messages', 'Um membro tem o direito a abordar a <a href="wiki/Who_does_what">equipa de moderação</a> com argumentos sobre o motivo pelo qual devem reconsiderar uma decisão. Se a equipa decidir manter a decisão, pode haver recurso dessa decisão para um Provedor. Caso não haja um Provedor, ou se um membro achar que o Provedor decidiu erradamente, pode ser feito um recurso final à Direção.\r\n\r\nA correspondência entre o membro e o moderador, a equipa de moderação, o provedor ou a Direção é pessoal. Não é permitida a publicação - mesmo que parcial - dessas comunicações num fórum ou noutros sites. A transmissão dessa informação a terceiras partes é inaceitável e pode conduzir ao cancelamento da inscrição no site. Enquanto os recursos estiverem a ser apreciados, a decisão da equipa de moderação mantém-se em vigor.', '2013-01-26 16:58:32', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 38787),
	('forumrulestext6', 'pt-BR', 'messages', 'Um membro tem o direito de solicitar ao <a href="wiki/Who_does_what">time de moderação</a> motivos para reconsiderarem a decisão. Se o time manter a decisão, esta decisão pode ser apelada à Ouvidoria. Em caso de ausência de um membro da Ouvidoria, ou se o membro achar que este tomou uma decisão incorreta, um apelo final pode ser feito ao Quadro de Diretores.\r\n\r\nMensagens entre o membro e o moderador, equipe de moderadores, oouvidoria e Quadro de Diretores são pessoais. Exibição parcial ou total destas correspondências no fórum ou outros sites não é permitida. A transmissão de informações dessas correspondências à terceiros não é aceita e pode resultar no cancelamento do cadastro. Durante a apelação, a decisão da moderação será mantida.', '2016-12-18 02:46:22', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160059),
	('forumrulestext6', 'ru', 'messages', 'Следовать советам и выполнять требования модераторов. Не допускаются споры с модераторами. Если у Вас есть какие-либо претензии к модератору, обратитесь в <a href="wiki/Who_does_what">команду модераторов форума</a>. Решение, принимаемое командой модераторов форума, является окончательным.', '2007-12-16 15:44:32', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 73061),
	('forumrulestext6', 'sr', 'messages', 'Обратите пажњу на савете и захтеве уредника. Лични напади на уреднике се неће толерисати. Ако имаш проблем са одлуком уредника, упути захтев <a href="wiki/Who_does_what">тиму уредника форума</a>. Одлука донета од стране тима уредника је коначна.', '2015-02-21 13:01:10', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 39772),
	('forumrulestext6', 'zh-hant', 'messages', '<p>成員有權向<a href="https://www.bewelcome.org/wiki/Who_does_what">版主團隊</a>提出理由，說明為何團隊應重新考慮某項決定。如果團隊堅持原判，該決定可上訴至<strong>監察員</strong>。如果沒有監察員，或者成員認為監察員做出了不正確的決定，可以向<strong>理事會</strong>提出最終上訴。</p><p>成員與版主、版主團隊、監察員或理事會之間的通訊均屬個人性質。不允許在論壇或其他網站上部分或完整公開通訊內容。將通訊資訊傳遞給第三方是不可接受的行為，並可能導致會籍終止。在上訴期間，版主團隊的決定維持不變。</p>', '2025-05-31 22:27:34', '2025-05-31 22:27:34', '2025-05-31 22:27:34', 'no', '', 5, NULL, 53422),
	('forumrulestext7', 'ca', 'messages', '(b) Has llegit i acceptat les normes d\'ús del fòrum, que són les següents:', '2008-03-03 14:52:49', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('forumrulestext7', 'de', 'messages', '(b) Du hast folgende Richtlinien des Forums und der Gruppen gelesen und akzeptiert:', '2008-03-01 23:29:54', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('forumrulestext7', 'el', 'messages', '(β) Έχεις διαβάσει και αποδεχθεί τις οδηγίες του φόρουμ του BeWelcome, οι οποίες είναι οι εξής:', '2017-07-25 09:58:53', '2020-09-02 16:00:53', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
