	('forumrulestext8', 'sr', 'messages', 'Не досађујте.', '2013-01-14 12:42:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('forumrulestext8', 'zh-hant', 'messages', '請勿挑釁。', '2025-05-31 22:41:08', '2025-05-31 22:41:08', '2025-05-31 22:41:08', 'no', '', 5, NULL, 53422),
	('forumrulestext9', 'ca', 'messages', 'Mira de no ésser barroer: hi ha persones més sensibles que d\'altres i cal tenir-ho present.', '2008-03-03 14:54:41', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('forumrulestext9', 'de', 'messages', 'Halte das Froum sauber - manche Personen sind sensibler als andere, respektiere das.', '2008-03-01 23:27:48', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('forumrulestext9', 'el', 'messages', 'Διατήρησε το φόρουμ καθαρό - κάποιοι είναι πιο ευαίσθητοι από άλλους, σεβάσου το.', '2017-07-25 10:50:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 64914),
	('forumrulestext9', 'en', 'messages', 'Keep it clean - some people are more sensitive than others, respect that.', '2007-11-29 20:58:32', '2019-04-23 18:16:49', '2007-11-29 20:58:32', 'no', '', 5, NULL, 1),
	('forumrulestext9', 'es', 'messages', 'Mantenlo limpio - algunas personas son más sensible que otras, toma en cuenta esto y respétalo.', '2007-12-31 16:40:34', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1328),
	('forumrulestext9', 'fr', 'messages', 'Merci de garder le forum propre&nbsp;: certaines personnes y sont attachées - merci de le respecter.', '2007-12-01 21:37:44', '2022-08-31 19:56:07', '0000-00-00 00:00:00', 'no', '', 5, NULL, 168499),
	('forumrulestext9', 'gl', 'messages', 'Mantén o respecto; algunhas persoas son máis sensibles que outras, respecta isto.', '2021-01-25 16:14:34', '2021-01-25 16:14:34', '2021-01-25 16:14:34', 'no', '', 5, NULL, 210880),
	('forumrulestext9', 'it', 'messages', 'Usa un linguaggio pulito – ci sono persone che sono più sensibili di altre, rispetta questa cosa.', '2007-12-29 15:29:14', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 103),
	('forumrulestext9', 'lt', 'messages', 'Laikykitės "švarumo" forume, t.y. nešiukšlinkite: nerašykite beprasmių ir niekam nereikalingų pranešimų - gerbkite kitų narių laiką, ir turėkite omenyje, kad kai kurie nariai gali būti labiau jautrūs šiukšlinimui forume', '2007-12-30 19:54:34', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('forumrulestext9', 'nl', 'messages', 'Hou het deftig. Sommige mensen zijn gevoeliger dan anderen, respecteer dat.', '2012-12-15 13:46:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('forumrulestext9', 'pl', 'messages', 'Dbaj o jego czystość - jedni ludzie są bardziej wrażliwi niż inni. Uszanuj to.', '2021-01-16 16:28:39', '2021-01-16 16:28:39', '2021-01-16 16:28:39', 'no', '', 5, NULL, 116789),
	('forumrulestext9', 'pt', 'messages', 'Mantém o respeito - algumas pessoas são mais sensíveis do que outras, respeita isso. ', '2013-01-16 20:02:33', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 36712),
	('forumrulestext9', 'ru', 'messages', 'Сохраняйте порядок - некоторые люди более восприимчивы к этому,чем другие, отнеситесь к ним с уважением.', '2014-05-24 06:34:51', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('forumrulestext9', 'sr', 'messages', 'Пазите на језик, неки људи су осетљивији од других, поштујте то.', '2013-01-14 12:43:28', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('forumrulestext9', 'zh-hant', 'messages', '保持言論潔淨 — 有些人較為敏感，請尊重這一點', '2025-05-31 22:38:19', '2025-05-31 22:38:19', '2025-05-31 22:38:19', 'no', '', 5, NULL, 53422),
