	('galleryoverview', 'ca', 'messages', 'Benvingut a la galeria! Aquí pots compartir les teves experiències de viatge amb la comunitat, penjar les teves millors fotos i comentar les fotografies d\'altres viatgers.', '2021-11-29 12:44:45', '2021-11-29 12:44:46', '2021-11-29 12:44:46', 'no', '', 5, NULL, 304193),
	('galleryoverview', 'de', 'messages', 'Willkommen in der Foto-Galerie! Teile deine besten Reiseerlebnisse mit der Community, lade deine besten Schnappschüsse hoch und kommentiere die Fotos anderer ...', '2009-10-31 11:50:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 91),
	('galleryoverview', 'el', 'messages', 'Καλώς ήρθες στη συλλογή! Μοιράσου τις ταξιδιωτικές σου εμπειρίες με τη κοινότητα, μεταφόρτωσε τις καλύτερες λήψεις σου και σχολίασε τις φωτογραφίες των άλλων...', '2020-08-15 08:37:05', '2020-08-28 07:52:52', '2020-08-15 08:37:05', 'no', '', 5, NULL, 266544),
	('galleryoverview', 'en', 'messages', 'Welcome to the gallery! Feel free to share your travel experiences with the community, upload your best shots and comment on the pictures of others…', '2009-10-31 09:50:49', '2019-04-23 18:16:49', '2009-10-31 09:52:50', 'no', 'Gallery introduction text', 0, NULL, 21169),
	('galleryoverview', 'es', 'messages', 'Bienvenido a la galería! No dude en compartir sus experiencias de viaje con la comunidad, subir sus mejores fotos y hacer comentarios sobre las fotos de los demás ...', '2011-11-19 09:20:54', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 8437),
	('galleryoverview', 'fr', 'messages', 'Bienvenue dans la galerie&nbsp;! Vous pouvez partager vos voyages avec la communauté, mettre vos meilleures photos en ligne et donner votre avis.', '2012-01-01 13:00:11', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 56017),
	('galleryoverview', 'gl', 'messages', 'Benvid@ á galería! Podes compartir as túas experiencias de viaxe coa comunidade, cargar as túas mellores fotos e comentar as fotos de outras persoas...', '2021-03-31 13:24:57', '2021-03-31 13:42:22', '2021-03-31 13:24:57', 'no', '', 5, NULL, 210880),
	('galleryoverview', 'it', 'messages', 'Benvenuto nella galleria fotografica! Sentiti libero di condividere le tue esperienze di viaggio con la comunità, carica i tuoi migliori scatti e commenta le foto degli altri...', '2012-10-18 07:42:13', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 44692),
	('galleryoverview', 'nl', 'messages', 'Welkom in de gallerij!  Voel je vrij om je reiservaringen te delen met de gemeenschap, je beste kiekjes te uploaden en commentaar te geven op de foto’s van anderen…', '2015-10-24 15:37:56', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 21169),
	('galleryoverview', 'pl', 'messages', 'Witaj w galerii! Podziel się swoimi doświadczeniami z podróży, załaduj ujęcia, które lubisz, komentuj fotografie innych!', '2021-01-13 19:26:41', '2021-01-13 19:26:41', '2021-01-13 19:26:41', 'no', '', 5, NULL, 116789),
	('galleryoverview', 'pt', 'messages', 'Bem-vindo/a à galeria. Esteja à vontade para partilhar as suas experiências de viagem com a comunidade, envie as suas últimas fotos e comente as imagens de outros...', '2014-01-08 18:48:37', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 38787),
	('galleryoverview', 'pt-BR', 'messages', 'Bem vindo à galeria! Fique a vontade para compartilhar suas experiências de viagem com a comunidade, enviar suas melhores fotos e comentar na fotografia de outros...', '2016-12-17 22:02:14', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160059),
	('galleryoverview', 'ru', 'messages', 'Добро пожаловать в галерю! С удовольствием делитесь Вашими впечатлениями от путешествий, загружайте лучшие снимки и комментируйте фотографии других участников...', '2014-05-17 18:12:44', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 73061),
	('galleryoverview', 'sr', 'messages', 'Добродошли у галерију! Поделите са заједницом искуства са своји путовања, поставите своје најбоље фотке и коментаришите слике других корисника...', '2013-07-19 16:50:56', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 52973),
