	('getactivedevinfo', 'pl', 'messages', '<a href="http://trac.bewelcome.org/">trac</a> &#124; kontakt: <a href="members/OctoberTales">OctoberTales</a>', '2021-03-20 21:29:49', '2021-03-20 21:30:13', '2021-03-20 21:29:49', 'no', '', 5, NULL, 116789),
