	('getactivedonationtitle', 'es', 'messages', 'Financiando la organización', '2009-07-15 11:59:49', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1328),
	('getactivedonationtitle', 'eu', 'messages', 'Erakundea finantziatu', '2013-04-20 11:22:34', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11907),
	('getactivedonationtitle', 'fa', 'messages', 'تامین بودجه‌ی سازمان', '2015-06-11 17:24:43', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 41992),
