	('getactivedonationtitle', 'gl', 'messages', 'Financiamento da organización', '2021-01-13 15:44:36', '2021-01-13 16:02:01', '2021-01-13 15:44:36', 'no', '', 5, NULL, 210880),
	('getactivedonationtitle', 'he', 'messages', 'מימון הארגון', '2022-04-06 16:47:21', '2022-04-06 16:47:21', '2022-04-06 16:47:21', 'no', '', 5, NULL, 290109),
