	('getactivedonationtitle', 'hu', 'messages', 'A szervezet finanszirozása', '2018-03-05 15:01:13', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 58692),
	('getactivedonationtitle', 'hy', 'messages', 'Կազմակերպության ֆինանսավորումը', '2025-07-20 11:56:20', '2025-07-20 11:56:20', '2025-07-20 11:56:20', 'no', '', 5, NULL, 519603),
