	('getactivemodinfos', 'es', 'messages', '<a href="wiki/moderation_team">wiki</a> &#124; <a href="wiki/Forum_Moderator_Application">cómo aplicar</a> &#124; <a href="groups">grupo</a>', '2021-02-04 11:48:17', '2021-02-04 11:48:17', '2021-02-04 11:48:17', 'no', '', 5, NULL, 25548),
