	('getactiveprinfos', 'ru', 'messages', '<p><a href="https://www.bewelcome.org/groups/64/wiki">Вики </a>| <a href="https://www.bewelcome.org/groups/64">группа</a></p><p>&nbsp;</p>', '2025-03-21 18:42:17', '2025-03-21 18:42:17', '2025-03-21 18:42:17', 'no', '', 5, NULL, 519603),
	('getactiveprtext', 'ar', 'messages', 'أتحب التواصل مع الناس وتريد للمساعدة في تعزيز المشروع للجمهور؟ لديك فكرة عظيمة لحملة ملصقات أو الأسبوعية؟ مرحبا بكم في <a href="http://www.bewelcome.org/groups/64"> مجموعة الاتصالات </a>!', '2014-04-22 13:15:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 48359),
	('getactiveprtext', 'ca', 'messages', 'T\'encanta comunicar-te amb la gent i vols ajudar a promoure el projecte al públic? Tens una idea genial per un pòster o una campanya de relacions públiques? Benvingut al <a href="http://www.bewelcome.org/groups/64">grup de comunicacions</a>! ', '2009-08-24 12:50:52', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 5533),
	('getactiveprtext', 'cs', 'messages', 'Miluješ komunikovat s lidmi a chceš pomoci projekt propagovat? Máš skvělý nápad na plakát nebo kampaň? Vítej v <a href="http://www.bewelcome.org/groups/64">komunikační skupině</a>!', '2014-02-04 23:25:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 34292),
	('getactiveprtext', 'de', 'messages', 'Kommunikation ist deine Stärke? Du möchtest das Projekt bekannter machen? Du hast eine großartige Idee für ein Poster oder eine unkonventionelle Werbemaßnahme? Lass es uns wissen im <a href="http://www.bewelcome.org/groups/64">Team für Kommunikation</a>! Du hast Erfahrung in der Kommunikation mit neuen Medien, in sozialen Netzwerken oder über Newslettern? Du kennst Dich mit SEO oder Branding aus? Willkommen im Team für Kommunikation!', '2009-12-05 01:31:10', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 25410),
	('getactiveprtext', 'el', 'messages', '<p>Σου αρέσει να επικοινωνείς με ανθρώπους και θέλεις να βοηθήσεις στη προώθηση του project Bewelcome παγκόσμια; Έχεις μια πολύ καλή ιδέα για αφίσα ή για μια εκστρατεία δημοσίων σχέσεων; Καλώς όρισες στην <a href="groups/64">ομάδα επικοινωνίας</a>! Αν έχεις εμπειρία στη δημιουργία Δελτίων Τύπου, Social Media, SEO, Branding και/ή Επικοινωνία Μέσων, σε περιμένουμε &nbsp;να γίνεις μέλος στην ομάδα επικοινωνίας.</p>', '2013-03-01 02:13:39', '2024-07-26 17:12:38', '0000-00-00 00:00:00', 'no', '', 0, NULL, 266502),
	('getactiveprtext', 'en', 'messages', 'Do you love to communicate with people and want to help promote the BeWelcome project wordwide? Do you have a great idea for a poster or a Public Relations campaign? Welcome to the <a href="groups/64">communications team</a>! If you have experience in doing Newsletters, Social Media, SEO, Branding and/or Media communication, you are welcome to join the communications team.', '2009-07-05 09:51:37', '2020-12-15 18:58:10', '2016-01-09 17:35:54', 'no', 'Description text joining communications group', 0, 0, 2208),
	('getactiveprtext', 'eo', 'messages', 'Ĉu vi ŝatas komuniki kun homoj kaj volas promocii la projekton al ektera publiko? Ĉu vi eventuale havas grandiozajn ideojn por afiŝoj aŭ kampanjoj? Estu bonvena al la <a href="http://www.bewelcome.org/groups/64">komunika grupo</a>!', '2013-03-14 06:07:28', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 47220),
	('getactiveprtext', 'es', 'messages', '¿Te gusta comunicarte con la gente y quieres ayudar a promocionar el proyecto BeWelcome en todo el mundo? ¿Tienes una gran idea para un poster o campaña de comunicación? Bienvenido al <a href="http://www.bewelcome.org/groups/64">equipo de comunicación</a>! Si tienes experiencia en Newsletters, Social Media, SEO, Branding y/o Media communication, eres bienvenido/a a unirte al equipo de Comunicación.', '2010-09-02 12:26:50', '2020-12-15 19:12:30', '0000-00-00 00:00:00', 'no', '', 0, NULL, 2208),
	('getactiveprtext', 'eu', 'messages', 'Gainontzekoekin komunikatzea duzu gustoko eta projektua ezagutzera eman nahi duzu? Poster edo kanpaina baterako ideiarik duzu? Ongi etorri <a href="http://www.bewelcome.org/groups/64">komunikazio taldera</a>!', '2013-04-20 11:41:22', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 11907),
	('getactiveprtext', 'fr', 'messages', 'Vous aimez communiquer avec le monde entier et vous avez envie de promouvoir le projet BeWelcome ? Vous avez des idées pour un poster ou une campagne ? Bienvenue dans le groupe anglophone <a href="http://www.bewelcome.org/groups/64">Communications team</a>&nbsp;! Si vous avez de l\'expérience avec la rédaction de newsletters, les réseaux sociaux, le SEO, le branding et/ou la communication, nous vous accueillons avec plaisir dans l\'équipe de communication.', '2010-01-05 18:14:47', '2020-12-15 19:02:34', '0000-00-00 00:00:00', 'no', '', 0, NULL, 2208),
	('getactiveprtext', 'gl', 'messages', 'Gústache comunicarte coas persoas e queres axudar a promover o proxecto BeWelcome en todo o mundo? Tes una gran idea para un cartel ou para unha campaña de Relacións Públicas? Dámosche a benvida ao <a href="groups/64">equipo de comunicación</a>! Se tes experiencia en facer boletíns informativos, redes sociais, optimización para motores de busca, marcas e/ou Medios de comunicación, dámosche a benvida ao equipo de comunicación.', '2021-01-13 15:14:08', '2021-01-13 15:14:08', '2021-01-13 15:14:08', 'no', '', 5, NULL, 210880),
	('getactiveprtext', 'hr', 'messages', 'Voliš komunicirati s ljudima i želiš upoznati javnost sa ovim projektom? Imaš super ideju za poster ili PR kampanju ? Dobrodošao/la u <a href="http://www.bewelcome.org/groups/64">ekipu za komunikaciju</a>! ', '2009-09-05 17:24:41', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 8197),
	('getactiveprtext', 'hu', 'messages', 'Imádsz kommunikálni és szeretnél segíteni, hogy a BeWelcome világszerte ismertebb legyen? Van egy remek poszter, vagy marketing kampány ötleted? Üdvözlünk a <a href="groups/64">kommunikációs csapatban</a>! Ha van tapasztalatod hírlevelek készítésében, közösségi médiában, SEO-ban, márkaépítésben és/vagy médiakommunikációban, örömmel várunk a kommunikáció és PR csapatában.', '2020-07-04 11:24:05', '2020-07-04 11:25:58', '2020-07-04 11:24:05', 'no', '', 5, NULL, 265911),
	('getactiveprtext', 'it', 'messages', 'Ami comunicare con le persone e vuoi aiutare a far conoscere il progetto di BeWelcome in tutto il mondo? Hai qualche grande idea per un manifesto o per una campagna di comunicazione? Benvenuto nella <a href="groups/64">Squadra Comunicazione</a>!  Se hai esperienza nel fare Newsletter, social media, SEO, Branding e/o comunicazione mediale, sei benvenuto a unirti alla Squadra Comunicazioni.', '2010-06-02 14:44:32', '2021-03-21 11:08:25', '0000-00-00 00:00:00', 'no', '', 0, NULL, 160610),
	('getactiveprtext', 'lt', 'messages', '<p>Ar jums patinka bendrauti su žmonėmis ir norėtumėte padėti reklamuoti BeWelcome visame pasaulyje? Gal turite gerą idėją plakatui ar viešųjų ryšių kampanijai? Sveiki atvykę į <a href="https://www.bewelcome.org/groups/64">komunikacijos komandą</a>! Jei turite patirties kurdami naujienlaiškius, mokate dirbti su socialine medija, brandingu, medijos komunikacija ar žinote ką reiškia būti SEO, esate laukiami mūsų komandoje!</p>', '2023-08-14 09:53:59', '2023-08-14 09:54:47', '2023-08-14 09:53:59', 'no', '', 5, NULL, 285578),
	('getactiveprtext', 'nl', 'messages', '<p>Hou je ervan om met mensen te communiceren en het project bij het grote publiek te promoten? &nbsp;Heb je een goed idee voor een poster of PR-campagne? Welkom in de <a href="http://www.bewelcome.org/groups/64">communicatiegroep</a>! &nbsp;Als je ervaring hebt met het maken van nieuwsbrieven, sociale media, zoekmachineoptimalisatie, reclame of perswerk, nodigen we je uit ons communicatieteam te versterken.</p>', '2011-12-03 23:38:17', '2025-12-20 17:17:02', '0000-00-00 00:00:00', 'no', '', 0, NULL, 21169),
	('getactiveprtext', 'pl', 'messages', '<p>Lubisz komunikować się z ludźmi i chcesz pomóc w promocji BeWelcome na świecie? Masz pomysł na plakat lub kampanię marketingową? Witamy w <a href="groups/64">Zespole Komunikacji</a>! Masz wprawę w tworzeniu newsletterów, obsłudze mediów społecznościowych, SEO, brandingu lub komunikacji medialnej? Zapraszamy!</p>', '2020-07-29 11:50:01', '2021-06-13 19:14:25', '2020-07-29 11:50:01', 'no', '', 5, NULL, 116789),
	('getactiveprtext', 'pt', 'messages', 'Adora comunicar com pessoas e quer ajudar a divulgar o projeto BeWelcome ao resto do mundo? Tem uma grande ideia para um poster ou uma campanha de marketing? Bem-vindo/a à <a href="groups/64">equipa de comunicações</a>! Se tem experiência a criar Newsletters, com Social Media, SEO, Branding e/ou comunicação com os Media, está convidado/a a juntar-se à equipa de comunicações.', '2012-12-09 18:13:14', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 38787),
	('getactiveprtext', 'pt-BR', 'messages', 'Você gosta de se comunicar com pessoas e quer ajudar promover o projeto BeWelcome mundo afora? Tem uma grande ideia para um pôster ou campanha de marketing? Seja bem-vindo(a) à <a href="groups/64">equipe de comunicações</a>! Se você tem experiência em boletins de notícias (newsletter), redes sociais, otimização de ferramentas de busca (SEO), gestão de marcas e/ou comunicação midiática, seja bem-vindo(a) à equipe de comunicações.', '2014-06-11 06:47:51', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 0, NULL, 160059),
	('getactiveprtext', 'ro', 'messages', '<p>Îți place să comunici cu oamenii și vrei să ajuți la promovarea proiectului BeWelcome în lumea întreagă. Ai o idee grozavă pentru un poster sau o campanie de Relații Publice? Bine ai venit în <a href="groups/64">echipa de comunicații</a>! Dacă ai experiență în crearea de știri, Social Media, SEO, Branding și/sau comunicare Media, ești binevenit(ă) să te alături echipei de comunicații.</p>', '2024-01-25 01:58:44', '2024-01-25 01:58:44', '2024-01-25 01:58:44', 'no', '', 5, NULL, 471388),
	('getactiveprtext', 'ru', 'messages', 'Вы любите взаимодействовать с другими людьми и хотите продвигать проект? У вас есть замечательная идея для постера или пиар-компании? Добро пожаловать в <a href="http://www.bewelcome.org/groups/64">Группу Коммуникаций</a>! Если у Вас есть опыт в области Рассылок, Социальных Медиа, SEO, Брендинга и\\или прочих коммуникаций - добро пожаловать к нашу Группу Коммуникаций.', '2014-05-02 13:26:04', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 73061),
	('getactiveprtext', 'sr', 'messages', 'Волиш да комуницираш са људима и желиш да помогнеш у промоцији BeWelcome-а у јавности? Имаш супер идеју за постер или ПР кампању? Добродошао/Добродошла у <a href="http://www.bewelcome.org/groups/64"> комуникацијуску групу</a>! ', '2013-01-11 18:51:29', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 35032),
	('getactiveprtext', 'sv', 'messages', 'Älskar du att kommunicera med människor och vill hjälpa till att nå ut med projektet till allmännheten? Du har kanske en fantastisk idé till en affisch eller PR-kampanj? Välkommen till Kommunikationsgruppen!', '2012-09-28 19:15:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 33693),
	('getactiveprtext', 'tr', 'messages', 'İnsanlarla iletişim kurmayı seviyor musunuz ve projemizi toplumunuza tanıtmak ister misiniz? Harika bir afiş fikriniz veya halkla ilişkiler kampanyanız mı var? <a href="http://www.bewelcome.org/groups/64">İletişim grubuna</a> hoşgeldiniz!', '2012-11-30 21:35:47', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 35699),
	('getactiveprtext', 'uk', 'messages', '<p>Ви любите спілкуватися з людьми і хочете допомогти просувати проект BeWelcome по всьому світу? У вас є чудова ідея для плакату або PR кампанії? Ласкаво просимо до <a href="groups/64">команди комунікацій</a>! Якщо у вас є досвід у створенні інформаційних бюлетенів, соціальних мережах, SEO, брендингу та/або медіа-комунікаціях, запрошуємо приєднатися до команди комунікацій.</p>', '2026-04-03 19:50:12', '2026-04-03 19:50:12', '2026-04-03 19:50:12', 'no', '', 5, NULL, 573491),
	('getactiveprtext', 'zh-hans', 'messages', '你喜欢与人交流并想为项目的推动出一份力？你有海报设计或公关活动的好创意？欢迎加入<a href="http://www.bewelcome.org/groups/64">传播团队</a>！', '2010-10-11 23:32:49', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 0, NULL, 11819),
	('getactiveprtext', 'zh-hant', 'messages', '您是否喜歡與人溝通，並希望在全球範圍內促進BeWelcome項目？ 您對海報或營銷活動有很好的主意嗎？ 歡迎加入<a href="groups/64">通訊團隊</a>！ 如果您有做新聞通訊，社交媒體，SEO，品牌和/或媒體交流的經驗，歡迎您加入溝通團隊。', '2010-10-11 23:32:49', '2021-05-02 07:48:37', '0000-00-00 00:00:00', 'no', '', 0, NULL, 53422),
	('getactiveprtitle', 'ar', 'messages', 'العلاقات العامة والاتصالات', '2014-04-11 09:37:27', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 48359),
