	('getactivesuggestionsinfos', 'es', 'messages', '<a href="suggestions/team">cómo unirse</a> &#124; <a href="groups/1582">grupo</a>', '2021-02-04 11:47:03', '2021-02-04 11:47:03', '2021-02-04 11:47:03', 'no', '', 5, NULL, 25548),
