	('getactivetestinginfos', 'gl', 'messages', '<a href="groups/62">group</a> &#124; <a href="https://alpha.bewelcome.org">alfa</a> &#124; <a href="https://beta.bewelcome.org">beta</a> &#124; <a href="http://trac.bewelcome.org/">trac</a>', '2021-02-03 12:04:31', '2021-02-03 12:04:31', '2021-02-03 12:04:31', 'no', '', 5, NULL, 210880),
	('getactivetestinginfos', 'it', 'messages', '<a href="groups/62">gruppo</a> &#124; <a href="https://alpha.bewelcome.org">alpha</a> &#124; <a href="https://beta.bewelcome.org">beta</a> &#124; <a href="http://trac.bewelcome.org/">trac</a>', '2021-01-23 19:23:54', '2021-01-23 19:23:54', '2021-01-23 19:23:54', 'no', '', 5, NULL, 160610),
	('getactivetestinginfos', 'nl', 'messages', '<a href="groups/62">groep</a> | <a href="https://alpha.bewelcome.org">alfa</a> | <a href="https://beta.bewelcome.org">bèta</a> | <a href="http://trac.bewelcome.org/">trac</a>', '2021-01-26 19:23:21', '2021-01-26 19:23:21', '2021-01-26 19:23:21', 'no', '', 5, NULL, 21169),
	('getactivetestinginfos', 'pl', 'messages', '<a href="groups/62">grupa</a> &#124; <a href="https://alpha.bewelcome.org">alfa</a> &#124; <a href="https://beta.bewelcome.org">beta</a> &#124; <a href="http://trac.bewelcome.org/">trac</a>', '2021-03-20 21:28:36', '2021-03-20 23:45:06', '2021-03-20 21:28:36', 'no', '', 5, NULL, 116789),
	('getactivetestinginfos', 'pt', 'messages', '<a href="groups/62">grupo</a> &#124; <a href="https://alpha.bewelcome.org">alpha</a> &#124; <a href="https://beta.bewelcome.org">beta</a> &#124; <a href="http://trac.bewelcome.org/">trac</a>', '2019-04-30 14:23:18', '2019-04-30 14:23:18', '2019-04-30 14:23:18', 'no', '', 5, NULL, 38787),
	('getactivetestingtext', 'ar', 'messages', 'من الذي يأكد من أن كل شيء يعمل بسلاسة؟ <a href="http://www.bewelcome.org/groups/62/wiki">فريق التفحص والتجربة! </a> المبدعين يريدون بإحساس للحصول على التفاصيل!', '2014-04-22 13:08:36', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 48359),
	('getactivetestingtext', 'ca', 'messages', 'Qui s\'encarrega de que tot funcioni correctament? L\' <a href="http://alpha.bewelcome.org/groups/62">equip de proves</a>, una gent creativa buscada pels seus sentits del detall!', '2009-08-24 12:48:45', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 12861),
	('getactivetestingtext', 'cs', 'messages', 'Kdo zajišťuje, že vše běží plynule?  <a href="http://www.bewelcome.org/groups/62/wiki">Testovací tým!</a> Chceme kreativní lidi se smyslem pro detaily! ', '2013-10-16 20:46:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 34292),
	('getactivetestingtext', 'de', 'messages', 'Wer sorgt dafür, dass alles wie erwartet funktioniert? <a href="http://www.bewelcome.org/groups/62/wiki">Das Team der Tester</a>! Hier werden kreative Leute mit Gespür für Details gesucht! Technisches Wissen muss nicht vorhanden sein. Dies kann ein guter Start sein, um bei BeWelcome einbezogen zu werden. ', '2009-06-26 09:26:06', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 108706),
	('getactivetestingtext', 'el', 'messages', 'Ποιος διασφαλίζει πως όλα κυλούν ομαλά; Η ομάδα δοκιμών! Ζητούνται δημιουργικά άτομα που εστιάζουν στη λεπτομέρεια - δεν απαιτούνται ειδικές τεχνικές γνώσεις. Ίσως αυτό να\'ναι ένα μια καλή αρχή για να γνωρίσεις το BeWelcome!', '2013-03-01 01:22:18', '2020-09-02 10:05:16', '0000-00-00 00:00:00', 'no', '', 0, NULL, 266544),
	('getactivetestingtext', 'en', 'messages', 'Who makes sure everything works smoothly? The testing team! Creative people wanted with a sense for details – no special technical knowledge required. This might be a good starting point for you to get involved in BeWelcome!', '2009-06-23 21:43:36', '2021-01-24 09:43:29', '2009-12-19 13:24:17', 'no', 'on get active page, about the testing team', 0, 0, 21169),
	('getactivetestingtext', 'eo', 'messages', 'Kiu kontrolas ĉu ĉio funkcias glate? <a href="http://www.bewelcome.org/groups/62/wiki">La testa teamo! </a> Kreativaj personoj kun zorgo pri detaloj!', '2013-03-14 06:21:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 47220),
	('getactivetestingtext', 'es', 'messages', '¿Quién se asegura de que todo funcione sin problemas? ¡El equipo de pruebas! Se busca gente creativa, cuidadosa con los detalles. No se requiere ningún conocimiento técnico especializado. Este puede ser un buen punto de partida para involucrarse en BeWelcome!', '2010-09-02 11:46:04', '2023-06-01 10:55:57', '0000-00-00 00:00:00', 'no', '', 0, NULL, 25548),
	('getactivetestingtext', 'fr', 'messages', 'Qui s’assure que tout tourne rond ? <a href="http://www.bewelcome.org/groups/62">L’équipe de test</a>&nbsp;! On cherche des gens créatifs, qui ont le sens du détail !  Aucune compétence particulière n\'est requise. Cette équipe est probablement un bon point de départ pour s\'impliquer au service de la communauté BeWelcome !', '2009-06-29 16:08:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 56017),
	('getactivetestingtext', 'gl', 'messages', 'Quen comproba que todo vai ben? O equipo de probas! Buscamos persoas creativas que presten atención aos detalles. Non se precisan coñecementos técnicos. Este podería ser un bo punto de partida para colaborar con BeWelcome!', '2021-01-12 17:57:41', '2021-01-12 17:57:41', '2021-01-12 17:57:41', 'no', '', 5, NULL, 210880),
	('getactivetestingtext', 'he', 'messages', 'מי מבטיח שהכל רץ בצורה חלקה? צוות הבדיקות! אנשים יצירתיים עם חוש לפרטים - אין צורך בידע טכני מסוים. זו יכולה להיות נקודת התחלה מעולה להיות מעורב/ת באתר!', '2022-04-06 16:44:12', '2022-04-06 16:44:12', '2022-04-06 16:44:12', 'no', '', 5, NULL, 290109),
	('getactivetestingtext', 'hr', 'messages', 'Tko je "urar" koji pazi da sve radi kao švicarski sat? <a href="http://www.bewelcome.org/groups/62/wiki">Ekipa za testiranje! </a>  Traže se kreativni ljudi sa smislom za detalje! ', '2009-09-01 14:43:26', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 8197),
	('getactivetestingtext', 'hu', 'messages', 'Ki gondoskodik róla, hogy minden simán menjen az oldalon? A tesztelő csapat! Kreatívokat keresünk, akiknek van érzéke az aprólékos munkához: nincs szükség egyedi technikai tudásra. Ez jó kiindulópont lehet, ha komolyabban meg akarod ismerni a BeWelcome-ot!', '2020-07-04 11:17:33', '2020-07-04 11:17:33', '2020-07-04 11:17:33', 'no', '', 5, NULL, 265911),
	('getactivetestingtext', 'it', 'messages', 'Chi si assicura che il sito funzioni senza intoppi? Il team di collaudo! Cercasi persone creative attente ai dettagli, non è richiesta alcuna competenza tecnica particolare. Questo potrebbe essere un ottimo punto di partenza per partecipare a BeWelcome!', '2010-05-18 14:23:38', '2020-10-09 14:10:45', '0000-00-00 00:00:00', 'no', '', 0, NULL, 160610),
	('getactivetestingtext', 'lt', 'messages', 'Kas pasirūpina, jog viskas veiktų sklandžiai? Testavimo komanda! Ieškomi kūrybingi žmonės su pajauta detalėms - nereikalingas joks techninis išmanymas. Tai gali būti geras pirmas žingsnis norint įsitraukti į BeWelcome veiklą!', '2023-08-14 09:48:38', '2023-08-14 09:48:38', '2023-08-14 09:48:38', 'no', '', 5, NULL, 285578),
	('getactivetestingtext', 'nl', 'messages', 'Wie zorgt ervoor dat alles vlotjes loopt?  Het testteam!  We zoeken creatieve personen met oog voor details – geen specifieke technische kennis vereist.  Dit zou een goed beginpunt kunnen zijn om bij BeWelcome betrokken te raken!', '2011-12-03 23:24:16', '2025-11-13 09:35:51', '0000-00-00 00:00:00', 'no', '', 0, NULL, 21169),
	('getactivetestingtext', 'pl', 'messages', 'Kto dba o to, aby wszystko działało bezproblemowo? Zespół Testujący! Poszukujemy do niego ludzie kreatywnych i przywiązujących wagę do szczegółów. By zacząć działać z nami, nie potrzebujesz żadnej specyficznej wiedzy technicznej. To może być świetne miejsce na początek Twojej pracy dla BeWelcome.', '2013-01-05 14:23:48', '2021-03-29 01:02:56', '0000-00-00 00:00:00', 'no', '', 0, NULL, 116789),
	('getactivetestingtext', 'pt', 'messages', 'Quem garante que tudo funciona sem problemas? A equipa de testes! Pessoas criativas precisam-se, com atenção aos detalhes - não é preciso nenhum conhecimento tecnológico especial. Este pode ser um bom ponto de partida para se envolver no BeWelcome!', '2009-09-01 19:49:27', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 38787),
	('getactivetestingtext', 'pt-BR', 'messages', 'Quem se certifica que tudo funciona bem?  <a href="http://www.bewelcome.org/groups/62/wiki">A equipe de testes!</a>! Precisamos de pessoas criativas e com atenção a detalhes - não há exigência de conhecimento técnico específico. Isto pode ser um bom ponto de partida para você se envolver no BeWelcome!', '2014-06-11 06:35:05', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 0, NULL, 88781),
	('getactivetestingtext', 'ro', 'messages', 'Cine vrea să se asigure că totul merge cum trebuie? Echipa de testare! Se caută oameni creativi cu atenție la detalii - niciun fel de cunoștiințe tehnice necesare. Acesta ar putea fi un punct de start bun pentru a te implica în BeWelcome!', '2024-01-25 01:37:44', '2024-01-25 01:37:44', '2024-01-25 01:37:44', 'no', '', 5, NULL, 471388),
	('getactivetestingtext', 'ru', 'messages', 'Кто гарантирует, что все будет работать хорошо? Команда Тестирования!  Разыскиваются креативные люди, уделяющие внимание деталям! Никаких специальных технических знаний не требуется. Для тех, кто хочет участвовать в жизни BeWelcome - это хорошая стартовая точка! ', '2014-05-02 13:14:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 73061),
	('getactivetestingtext', 'sr', 'messages', 'Ко је тај који чини да све функционише супер и без застоја? Пробни тим! Потребни креативни људи са осећајем за детаље!', '2013-01-11 19:17:15', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 39772),
	('getactivetestingtext', 'sv', 'messages', 'Vem ser till så att allt fungerar ordentligt? Test-teamet! Kreativa personer sökes med sinne för detaljer!', '2012-09-28 19:00:36', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 33693),
	('getactivetestingtext', 'tr', 'messages', 'Herşeyin yolunda gitmesini kim sağlıyor? <a href="http://www.bewelcome.org/groups/62/wiki">Değerlendirme ekibi! </a> Yaratıcı ve detaycı kişiler arıyoruz!', '2012-11-30 19:53:31', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 35699),
	('getactivetestingtext', 'uk', 'messages', 'Хто стежить за тим, щоб все працювало без збоїв? Тестувальна команда! Потрібні креативні люди з увагою до деталей – спеціальні технічні знання не потрібні. Це може бути гарною відправною точкою для вас, щоб долучитися до BeWelcome!', '2026-04-03 19:43:09', '2026-04-03 19:43:09', '2026-04-03 19:43:09', 'no', '', 5, NULL, 573491),
	('getactivetestingtext', 'zh-hans', 'messages', '谁来保证一切运作正常？测试团队！队员招募中 -- 无需任何专业技能，只须注重细节而又富创造性。这也许是参与 BeWelcome 的最好切入点了！', '2010-10-11 23:26:49', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 0, NULL, 37722),
	('getactivetestingtext', 'zh-hant', 'messages', '誰能保證各項工作順利進行？ <a href="http://www.bewelcome.org/groups/62/wiki">測試團隊</a>！具有細節敏感性的創新人才，我們需要你！', '2010-10-11 23:26:49', '2021-05-02 07:48:37', '0000-00-00 00:00:00', 'no', '', 0, NULL, 53422),
	('getactivetestingtitle', 'ar', 'messages', 'التجربة', '2013-11-08 14:18:47', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48359),
	('getactivetestingtitle', 'ca', 'messages', 'Proves', '2009-07-15 20:15:07', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 5533),
	('getactivetestingtitle', 'cs', 'messages', 'Testování', '2013-10-16 20:44:14', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('getactivetestingtitle', 'de', 'messages', 'Tester', '2009-06-18 22:09:59', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3050),
	('getactivetestingtitle', 'el', 'messages', 'Έλεγχος', '2013-02-28 16:08:04', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39089),
