	('getactivetranslateinfos', 'fr', 'messages', '<a href="groups/60/wiki">comment nous rejoindre</a> &#124; <a href="groups/60">groupe</a>', '2021-04-11 18:17:57', '2021-04-11 18:17:57', '2021-04-11 18:17:57', 'no', '', 5, NULL, 168499),
	('getactivetranslateinfos', 'gl', 'messages', '<a href="groups/60/wiki">como unirse</a> &#124; <a href="groups/60">grupo</a>', '2021-01-27 17:08:40', '2021-01-27 17:09:36', '2021-01-27 17:08:40', 'no', '', 5, NULL, 210880),
	('getactivetranslateinfos', 'hy', 'messages', '<p><a href="https://beta.bewelcome.org/groups/60/wiki">ինչպես միանալ</a> | <a href="https://beta.bewelcome.org/groups/60">խումբ</a></p>', '2025-04-06 11:29:51', '2025-04-06 11:29:51', '2025-04-06 11:29:51', 'no', '', 5, NULL, 519603),
	('getactivetranslateinfos', 'it', 'messages', '<a href="groups/60/wiki">come aderire</a> &#124; <a href="groups/60">gruppo</a>', '2021-01-23 19:26:17', '2021-01-23 19:26:17', '2021-01-23 19:26:17', 'no', '', 5, NULL, 160610),
	('getactivetranslateinfos', 'nl', 'messages', '<a href="groups/60/wiki">hoe deelnemen</a> | <a href="groups/60">groep</a>', '2021-01-26 19:18:04', '2021-01-26 19:18:04', '2021-01-26 19:18:04', 'no', '', 5, NULL, 21169),
	('getactivetranslateinfos', 'pl', 'messages', '<a href="groups/60/wiki">jak dołączyć</a> &#124; <a href="groups/60">grupa</a>', '2021-03-18 00:29:58', '2021-03-20 23:45:55', '2021-03-18 00:29:58', 'no', '', 5, NULL, 116789),
	('getactivetranslateinfos', 'pt', 'messages', '<a href="groups/60/wiki">como se inscrever</a> &#124; <a href="groups/60">grupo</a>', '2019-04-30 14:21:40', '2019-04-30 14:21:40', '2019-04-30 14:21:40', 'no', '', 5, NULL, 38787),
	('getactivetranslateinfos', 'ru', 'messages', '<p><a href="https://www.bewelcome.org/groups/60/wiki">как присоединиться</a> | <a href="https://www.bewelcome.org/groups/60">группа</a></p><p>&nbsp;|&nbsp;</p>', '2025-03-21 18:47:44', '2025-03-21 18:47:44', '2025-03-21 18:47:44', 'no', '', 5, NULL, 519603),
	('getactivetranslatetext', 'ar', 'messages', '<a href="http://www.bewelcome.org/groups/60">فريق الترجمة</a>  يريد تسهيل عملية الولوج للموقع للزائرين والأعضاء المحتملين حول العالم بصرف النظر عن مهاراتهم باللغة الانكليزية. هدفنا هو ترجمة كل الموقع إلى كافة اللغات الممكنة، بدءاً من أكثرها استخداما من قبل أعضائنا.', '2014-04-22 13:05:54', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 48937),
	('getactivetranslatetext', 'ca', 'messages', 'L\'<a href="http://www.bewelcome.org/groups/60">Equip de traducció</a> vol oferir un bon servei arreu del món, sense que el nivell d\'anglès d\'un membre sigui un problema. Això significa que la nostra meta és traduir tot el text del Web - començant per les més importants - a tots els idiomes possibles.', '2009-06-23 18:20:58', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 11944),
	('getactivetranslatetext', 'cs', 'messages', '<a href="http://www.bewelcome.org/groups/60">Tým překladatelů</a> chce poskytnout dobrou službu po celém světě, bez ohledu na znalost angličtiny potenciálního člena. To znamená, že naším cílem je přeložit všechen text na těchto stránkách -- začínáme s tím nejdůležitějším -- do tolika jazyků, jak to jen bude možné.', '2014-02-04 23:22:42', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 34292),
	('getactivetranslatetext', 'de', 'messages', 'Das <a href="http://www.bewelcome.org/groups/60">Übersetzungs-Team</a> arbeitet daran, diese Seite weltweit zugänglich zu machen, unabhängig von den Englischkenntnissen eines potentiellen Mitglieds. Unser Ziel ist es, alle Texte dieser Seite - angefangen bei den wichtigsten - in so viele Sprachen wie möglich zu übersetzen. Möchtest Du BeWelcome in Deiner Muttersprache sehen? Mit Deiner Hilfe kann das Wirklichkeit werden!', '2009-06-26 11:29:36', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 25410),
	('getactivetranslatetext', 'el', 'messages', 'Η <a href="https://www.bewelcome.org/groups/60"> Ομάδα Μεταφραστών</a> θέλει να διευκολύνει την πρόσβαση στον ιστοχώρο από επισκέπτες και πιθανά μέλη σε όλο τον κόσμο, ανεξάρτητα από τις γλωσσικές τους δεξιότητες στα Αγγλικά. Ο στόχος μας είναι να μεταφράσουμε πλήρως τον ιστοχώρο σε όσο το δυνατόν περισσότερες γλώσσες, ξεκινώντας από αυτές που ομιλούνται περισσότερο από τα μέλη μας. Θέλεις να δεις το BeWelcome και στη γλώσσα σου; Βοήθησε να γίνει πραγματικότητα!', '2013-03-01 01:58:48', '2020-09-02 10:03:24', '0000-00-00 00:00:00', 'no', '', 0, NULL, 266544),
	('getactivetranslatetext', 'en', 'messages', 'The <a href="groups/60">Translation Team</a> wants to ease the access to our website for members and visitors, regardless of their English skills. Our goal is to translate the complete site to as many languages as possible, starting with the most spoken languages of our members. Want to see BeWelcome in your own language? Please give a hand to make it come true!', '2009-06-20 12:10:15', '2019-04-23 18:16:49', '2009-06-20 12:10:15', 'no', 'Text for Translation Team Description on GetActive page', 0, NULL, 42397),
	('getactivetranslatetext', 'eo', 'messages', 'La <a href="http://www.bewelcome.org/groups/60">Traduka Teamo</a> volas garantii bonan servon tutmonde al ĉiuj, sendepende de ilia kono de la angla. Tio signifas, ke nia celo estas traduki ĉiujn tekstojn de la retejo - ekde la plej gravaj - al tiom multaj lingvoj, kiel eblas.', '2013-03-13 23:08:15', '2020-05-31 14:33:28', '0000-00-00 00:00:00', 'no', '', 0, NULL, 261823),
	('getactivetranslatetext', 'es', 'messages', '<p>El <a href="groups/60">Equipo de Traducción</a> quiere facilitar el acceso a nuestro sitio web para miembros y visitantes, sin importar el nivel de inglés. Nuestra meta es traducir el sitio a tantos idiomas como sea posible, comenzando con los idiomas más hablados por nuestros miembros. ¿Quieres ver BeWelcome en tu propio idioma? ¡Echa una mano para hacerlo realidad!</p>', '2010-09-02 11:43:04', '2021-06-26 20:21:11', '0000-00-00 00:00:00', 'no', '', 0, NULL, 25548),
	('getactivetranslatetext', 'eu', 'messages', '<a href="http://www.bewelcome.org/groups/60">Itzulpen taldeak</a> mundu osoari zerbitzu bikaina eman nahi dio, bakoitzaren ingeles maila edozein dela ere. Horrexegatik, webgunearen testu guztia (garrantzitsuenetatik hasita) ahal den eta hizkuntza gehienetan itzultzea dugu helburu.', '2013-04-20 11:29:21', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 11907),
	('getactivetranslatetext', 'fr', 'messages', '<a href="http://www.bewelcome.org/groups/60">L’équipe de traduction</a> cherche à rendre le site accessible au maximum de personnes, pour que la maîtrise de l’anglais ne soit plus un pré-requis pour devenir membre. Notre but est de traduire le site en autant de langues que possible, en commençant par les plus utilisées.', '2009-06-29 16:12:27', '2020-06-15 21:15:31', '0000-00-00 00:00:00', 'no', '', 0, NULL, 56017),
	('getactivetranslatetext', 'gl', 'messages', 'O <a href="groups/60">Equipo de Tradución</a> quere facilitar o acceso á nosa páxina web á comunidade e visitantes, independentemente das súas habilidades co idioma inglés. O noso obxectivo é traducir o sitio web completo a tantas linguas como sexa posible, comezando cas linguas  más faladas polas persoas da comunidade BeWelcome. Queres ver BeWelcome na túa propia lingua? Por favor axúdanos a facelo realidade!', '2021-01-13 14:44:33', '2021-01-13 14:44:33', '2021-01-13 14:44:33', 'no', '', 5, NULL, 210880),
	('getactivetranslatetext', 'hr', 'messages', '<a href="http://www.bewelcome.org/groups/60">Prevoditeljska ekipa </a> želi želi dobru ponudu usluga u cijelom svijetu, bez obzira koliko član/ica dobro zna engleski. Ukratko - naš cilj je prevesti sav tekst s naših stranica - počevši s onim najvažnijim - na što je više jezika moguće. ', '2009-09-05 17:36:43', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 8197),
	('getactivetranslatetext', 'hu', 'messages', 'A <a href="groups/60">Fordítói Csapat</a> azt szeretné, hogy az oldal használata könnyű legyen, mind a tagok, mind a látogatók számára, az angoltudásuk szintjétől függetlenül. A célunk az, hogy az egész oldalt a lehető legtöbb nyelvre lefordítsuk: a tagjaink által leginkább beszélt nyelvekkel kezdjük a munkát. Szeretnéd a BeWelcome-ot a saját nyelveden olvasni? Gyere, segíts, hogy ez valóra váljon!', '2020-07-02 09:08:49', '2020-07-04 10:45:20', '2020-07-02 09:08:49', 'no', '', 5, NULL, 265911),
	('getactivetranslatetext', 'hy', 'messages', '<p><a href="https://www.bewelcome.org/groups/60">Թարգմանիչների թիմը</a> ուզում է հեշտացնել մեր կայք մուտք գործելը այն հասանելի դարձնելով անդամների և այցելուների համար՝ անկախ նրանց անգլերենի իմացությունից: Մեր նպատակն է ամբողջական կայքը թարգմանել որքան հնարավոր է շատ լեզուներով՝ սկսած մեր անդամների կողմից ամենաշատ խոսվող լեզուներից: Ցանկանո՞ւմ եք տեսնել ԲիՎելքմը ձեր լեզվով: Խնդրում ենք օգնել, որպեսզի այն իրականություն դառնա:</p>', '2026-01-12 16:32:00', '2026-01-12 16:33:42', '2026-01-12 16:32:00', 'no', '', 5, NULL, 519603),
	('getactivetranslatetext', 'it', 'messages', 'La <a href="groups/60">squadra traduzioni</a> vuole semplificare l\'accesso al nostro sito sia ai membri che ai visitatori, indipendentemente dalla loro conoscenza dell\'inglese. Il nostro obiettivo è di tradurre l\'intero sito nel maggior numero di linguaggi possibile, a cominciare da quelli più parlati dai nostri membri. Vuoi poter vedere BeWelcome nella tua lingua? Per favore contribuisci anche tu!', '2010-06-02 14:47:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 44692),
	('getactivetranslatetext', 'lt', 'messages', '<a href="http://www.bewelcome.org/groups/60">Vertimų komanda</a> nori palengvinti pasiekti BeWelcome paslaugas visiems žmonėms visame pasaulyje - nepriklausomai nuo nario anglų kalbos žinių lygio. Tai reiškia, kad mūsų tikslas yra išversti visus svetainės tekstus - pradedant nuo svarbiausių - į tiek kalbų, kiek tai tik yra įmanoma.', '2009-08-10 01:50:02', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 227),
	('getactivetranslatetext', 'nl', 'messages', 'Het <a href="groups/60">vertaalteam</a> wil toegang tot de website makkelijker maken voor bezoekers en potentiële leden over de hele wereld, onafhankelijk van hun beheersing van de Engelse taal.  Ons doel is om de volledige site te vertalen in zo veel mogelijk talen, te beginnen met de talen die door onze leden het meeste gesproken worden.  Wil je BeWelcome in je eigen taal gebruiken?  Draag een steentje bij om dat waar te maken!', '2011-12-03 23:34:57', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 21169),
	('getactivetranslatetext', 'pl', 'messages', '<a href="groups/60">Zespół Tłumaczy</a> chce ułatwić wszystkim dostęp do naszej witryny internetowej, niezależnie od ich stopnia znajomości języka angielskiego. Chcemy przetłumaczyć całą stronę na jak najwięcej języków, zaczynając od tych najczęściej używanych przez naszych członków i członkinie. Chcesz zobaczyć BeWelcome w Twoim języku? Pomóż nam w tłumaczeniach!', '2020-07-29 11:30:15', '2021-03-29 01:04:48', '2020-07-29 11:30:15', 'no', '', 5, NULL, 116789),
	('getactivetranslatetext', 'pt', 'messages', 'A <a href="groups/60">Equipa de Tradução</a> quer tornar o site acesível a visitantes e membros em todo o mundo, independentemente da sua fluência em inglês. O nosso objetivo é traduzir todo o texto no site em tantas línguas quanto possível, a começar pelas línguas mais faladas pelos nossos membros. Quer ver o BeWelcome na sua língua? Por favor, ajude-nos a tornar isso uma realidade!', '2012-12-09 01:55:31', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 38787),
	('getactivetranslatetext', 'pt-BR', 'messages', 'A <a href="http://www.bewelcome.org/groups/60">Equipe de Tradução</a> quer tornar o acesso ao site mais fácil para visitantes e membros em potencial de todo o mundo, independentemente de sua aptidão em inglês. Nosso objetivo é traduzir o site inteiro para tantas línguas quanto possível, começando com as línguas mais faladas pelos nossos membros. Quer ver o BeWelcome no seu próprio idioma? Por favor, nos dê uma mão e vamos concretizar isso!', '2014-06-06 05:17:18', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 0, NULL, 160059),
	('getactivetranslatetext', 'ro', 'messages', '<p><a href="groups/60">Echipa de traduceri</a> dorește ca site-ul să fie ușor de accesat de membri și vizitatorii noștri, indiferent de nivelul de limba engleză știut. Scopul nostru este să finalizăm site-ul în cât mai multe limbi posibil, începând cu cele mai vorbite de către membrii noștri. Vrei să vezi BeWelcome în limba ta maternă? Te rog oferă-ne o mână de ajutor pentru a face asta realitate!</p>', '2024-01-25 01:55:26', '2024-01-25 01:55:26', '2024-01-25 01:55:26', 'no', '', 5, NULL, 471388),
	('getactivetranslatetext', 'ru', 'messages', '<a href="a href="groups/60">Команда Перевода</a> стремится обеспечить простой доступ к сайту для посетителей сайта и потенциальных участников по всему миру, вне зависимости от их знания английского языка. Это означает, что наша цель - перевести всю информацию на сайте на столько языков, на сколько это возможно, начав с самых популярных. Хочешь увидеть BeWelcome на своем родном языке? Приложи к этому свои силы!', '2014-05-02 13:21:52', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 73061),
	('getactivetranslatetext', 'sk', 'messages', '<a href="http://www.bewelcome.org/groups/60">Prekladateľský tím</a> chce poskytnúť dobrú službu pre celý svet, bez ohľadu na úroveň angličtiny potenciálneho člena. To znamená, že našim cieľom je preložiť všetok text na webstránke - počnúc najdôležitejšími - do toľkých jazykov, ako je to len možné.', '2013-05-06 18:49:02', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 48253),
	('getactivetranslatetext', 'sr', 'messages', 'Жеља <a href="http://www.bewelcome.org/groups/60">тима преводиоца</a> је да пружи добру услугу сваком посетиоцу и потенцијалном члану широм света, небитно њиховом познавању енглеског језика. Циљ нам је да преведемо сајт на што више језика, почевши са највише коришћених језика наших чланова.', '2013-01-11 18:58:55', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 39772),
	('getactivetranslatetext', 'sv', 'messages', 'Översättningsteamet vill kunna erbjuda god service över hela världen, oavsett hur duktig den potentiella medlemmen är på engelska. Det betyder att vårt mål är att översätta alla texter på hemsidan - till en början de viktigaste - till så många språk som möjligt.', '2012-09-28 19:11:31', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 33693),
	('getactivetranslatetext', 'tr', 'messages', '<a href="http://www.bewelcome.org/groups/60">Çeviri takımı</a> olası bir üyeye, İngilizce becerilerine bakılmaksızın, dünyanın her tarafında iyi bir hizmet sunma arzusundadır. Bu, amacımızın sitedeki bütün metinleri mümkün olduğunca çok dile (önemli olanlardan başlayarak) çevirmek olduğu anlamına gelir.', '2012-11-30 21:00:44', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 35699),
	('getactivetranslatetext', 'uk', 'messages', '<p><a href="groups/60">Команда перекладачів</a> хоче полегшити доступ до нашого веб-сайту для користувачів та відвідувачів, незалежно від їхніх навичок англійської мови. Наша мета - перекласти весь сайт на якомога більше мов, починаючи з найбільш поширених мов наших користувачів. Хочете бачити BeWelcome своєю рідною мовою? Будь ласка, допоможіть зробити це реальністю!</p>', '2026-04-03 19:48:00', '2026-04-03 19:48:34', '2026-04-03 19:48:00', 'no', '', 5, NULL, 573491),
	('getactivetranslatetext', 'zh-hans', 'messages', '<a href="http://www.bewelcome.org/groups/60">翻译团队</a>志愿为世界范围内无论英语水平如何的访客及潜在成员提供访问我们网站的便利。我们的目标是把整个网站从最多成员使用的英语翻译成越多越好的语言版本。想看到 BeWelcome 用你的母语显示吗？加入志愿行列来帮助我们把这实现吧！', '2010-10-11 23:29:35', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 0, NULL, 37722),
	('getactivetranslatetext', 'zh-hant', 'messages', '<a href="groups/60">翻譯團隊</a>希望無論成員和訪客的英語程度如何，都簡化他們對我們網站的訪問。 我們的目標是從會員最常用的語言開始，將整個網站翻譯成盡可能多的語言。 想要用自己的語言觀看BeWelcome嗎？ 請幫忙我們一起實現它！', '2010-10-11 23:29:35', '2021-05-02 07:48:37', '0000-00-00 00:00:00', 'no', '', 0, NULL, 53422),
	('getactivetranslatetitle', 'ar', 'messages', 'الترجمة', '2013-11-08 14:18:15', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48359),
	('getactivetranslatetitle', 'ca', 'messages', 'Traducció', '2009-07-15 20:14:58', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 5533),
	('getactivetranslatetitle', 'cs', 'messages', 'Překlad', '2013-10-16 20:40:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('getactivetranslatetitle', 'de', 'messages', 'Übersetzen', '2009-06-18 22:09:41', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3050),
	('getactivetranslatetitle', 'el', 'messages', 'Μετάφραση', '2013-02-28 20:05:20', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39089),
