	('group.create.check.double', 'de', 'messages', 'Wir haben ein paar existierende Gruppen gefunden, die (teilweise) mit dem Namen deiner Gruppe übereinstimmen. Vielleicht möchtest du überprüfen, ob du wirklich eine neue Gruppe benötigst?', '2020-06-09 19:15:40', '2020-06-09 19:15:40', '2020-06-09 19:15:40', 'no', '', 5, NULL, 111),
	('group.create.check.double', 'el', 'messages', 'Βρήκαμε μερικές ομάδες που έχουν (εν μέρει) το ίδιο όνομα με την ομάδα σου. Ίσως θα πρέπει να ελέγξεις αν χρειάζεται πραγματικά μία νέα ομάδα:', '2020-08-10 14:39:06', '2020-08-10 14:39:06', '2020-08-10 14:39:06', 'no', '', 5, NULL, 266544),
	('group.create.check.double', 'en', 'messages', 'We found a few existing groups that match (part) of your group\'s name. You might want to check if you really need a new group:', '2019-01-25 19:35:11', '2019-01-25 19:35:11', '0000-00-00 00:00:00', 'no', 'Text is shown when someone wants to create a group that might already exist.', 5, NULL, 1),
	('group.create.check.double', 'es', 'messages', 'Hemos encontrado algunos grupos cuyo nombre coincide (o en parte) con el nombre de tu grupo. Quizás quieras comprobar si realmente necesitas un nuevo grupo:', '2020-12-04 01:19:24', '2020-12-04 01:19:24', '2020-12-04 01:19:24', 'no', '', 5, NULL, 25548),
