	('group.create.check.double', 'gl', 'messages', 'Atopamos varios grupos existentes que coinciden (en parte) co teu nome do grupo. Quizais queiras comprobar se realmente necesitas un novo grupo:', '2021-01-28 11:55:19', '2021-01-28 11:55:19', '2021-01-28 11:55:19', 'no', '', 5, NULL, 210880),
	('group.create.check.double', 'it', 'messages', 'Abbiamo trovato alcuni gruppi già esistenti che corrispondono (in parte) al nome del tuo gruppo. Rifletti se hai davvero bisogno di un nuovo gruppo:', '2020-05-28 12:57:55', '2020-05-28 12:57:55', '2020-05-28 12:57:55', 'no', '', 5, NULL, 261434),
	('group.create.check.double', 'nl', 'messages', 'We hebben een aantal bestaande groepen gevonden die (deels) overeenkomen met je groepsnaam.  Misschien wil je even controleren of je echt een nieuwe groep nodig hebt:', '2020-09-22 18:33:42', '2020-09-22 18:33:42', '2020-09-22 18:33:42', 'no', '', 5, NULL, 21169),
	('group.create.check.double', 'pl', 'messages', 'Znaleźliśmy kilka już istniejących grup, które nazywają się podobnie, jak Twoja. \r\nMoże sprawdzisz najpierw, czy na pewno musisz tworzyć nową:', '2021-01-13 23:34:17', '2021-01-13 23:34:17', '2021-01-13 23:34:17', 'no', '', 5, NULL, 116789),
	('group.create.check.double', 'pt', 'messages', 'Encontrámos vários grupos com (parte do) nome parecido com o seu. Pode querer confirmar se precisa mesmo de um novo grupo:', '2019-02-07 14:39:46', '2019-02-07 14:39:46', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('group.create.description.hint', 'ca', 'messages', 'Incloeu el propòsit del grup o les principals característiques que té.', '2021-10-05 21:37:39', '2021-10-05 21:37:39', '2021-10-05 21:37:39', 'no', '', 5, NULL, 304193),
	('group.create.description.hint', 'de', 'messages', 'Bitte den Zweck der Gruppe oder die wesentlichen Merkmale angeben.', '2019-04-30 10:31:53', '2019-04-30 10:31:53', '2019-04-30 10:31:53', 'no', '', 5, NULL, 2208),
	('group.create.description.hint', 'el', 'messages', 'Πρόσθεσε τους σκοπούς της ομάδας ή τα βασικά χαρακτηριστικά του μέρους με το οποίο σχετίζεται η ομάδα.', '2020-07-23 17:46:58', '2020-08-27 07:42:10', '2020-07-23 17:46:58', 'no', '', 5, NULL, 266544),
	('group.create.description.hint', 'en', 'messages', 'Include the purpose of the group or the main features of the place covered by the group.', '2019-01-25 19:35:11', '2019-01-25 19:35:11', '0000-00-00 00:00:00', 'no', 'Tips for using a logic description of the group', 5, NULL, 1),
	('group.create.description.hint', 'es', 'messages', 'Incluye el propósito del grupo, las características principales o las áreas que cubre el grupo.', '2020-12-04 01:24:55', '2020-12-04 01:24:55', '2020-12-04 01:24:55', 'no', '', 5, NULL, 25548),
	('group.create.description.hint', 'fr', 'messages', 'Merci d\'indiquer l\'objectif et les caractéristiques principales du groupe, ainsi que la zone couverte par le groupe.', '2019-02-19 12:51:46', '2019-02-19 12:51:46', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('group.create.description.hint', 'gl', 'messages', 'Inclúe o propósito do grupo o as principais características do lugar cuberto polo grupo.', '2021-01-25 10:40:27', '2021-01-25 10:40:27', '2021-01-25 10:40:27', 'no', '', 5, NULL, 210880),
	('group.create.description.hint', 'it', 'messages', 'Inserite lo scopo del gruppo o le caratteristiche principali del luogo coperto dal gruppo.', '2019-02-22 09:34:37', '2019-02-22 09:34:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 13993),
	('group.create.description.hint', 'nl', 'messages', 'Neem het doel van de groep of de belangrijkste kenmerken van de plaats waarvoor de groep gedacht is, op.', '2020-09-22 18:44:17', '2020-09-22 18:44:17', '2020-09-22 18:44:17', 'no', '', 5, NULL, 21169),
	('group.create.description.hint', 'pl', 'messages', 'Opisz cel grupy albo cech miejsca, którego dotyczy.', '2021-01-13 23:39:47', '2021-01-13 23:39:47', '2021-01-13 23:39:47', 'no', '', 5, NULL, 116789),
	('group.create.description.hint', 'pt', 'messages', 'Inclua o propósito do grupo ou os marcos principais do local coberto pelo grupo.', '2019-02-07 14:30:46', '2019-02-07 14:30:46', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('group.create.description.hint', 'zh-hant', 'messages', '請包含群組的宗旨或該地區的主要特色。', '2025-05-31 22:04:18', '2025-05-31 22:04:18', '2025-05-31 22:04:18', 'no', '', 5, NULL, 53422),
	('group.create.name.hint', 'ca', 'messages', 'Per a grups locals, incloeu el país (per exemple, Lloc, País), perquè això ajudarà les cerques.', '2021-10-05 21:35:23', '2021-10-05 21:35:23', '2021-10-05 21:35:23', 'no', '', 5, NULL, 304193),
	('group.create.name.hint', 'de', 'messages', 'Für örtliche Gruppen bitte das Land hinzufügen (z.B. Ort, Land) damit sie leichter zu finden sind.', '2019-04-30 10:24:55', '2019-04-30 10:24:55', '2019-04-30 10:24:55', 'no', '', 5, NULL, 2208),
	('group.create.name.hint', 'el', 'messages', 'Για τοπικές ομάδες, συμπερίλαβε και τη χώρα (π.χ. Περιοχή, Χώρα) καθώς βοηθά στην αναζήτηση.', '2020-07-23 17:48:19', '2020-07-23 17:48:19', '2020-07-23 17:48:19', 'no', '', 5, NULL, 266544),
	('group.create.name.hint', 'en', 'messages', 'For local groups, include the country (e.g. Place, Country) as this will help with searches.', '2019-01-25 19:35:11', '2019-01-25 19:35:11', '0000-00-00 00:00:00', 'no', 'Tips for naming the group logically', 5, NULL, 1),
	('group.create.name.hint', 'es', 'messages', 'Para grupos locales, incluye la localización (por ejemplo: Lugar, País) ya que ayudará con las búsquedas.', '2020-12-04 01:23:49', '2020-12-04 01:23:49', '2020-12-04 01:23:49', 'no', '', 5, NULL, 25548),
	('group.create.name.hint', 'fr', 'messages', 'Pour les groupes régionaux, merci de préciser le pays (ex : ville, pays) afin d\'aider l\'affichage des résultats.', '2019-02-19 12:50:09', '2020-11-29 21:45:19', '0000-00-00 00:00:00', 'no', '', 5, NULL, 168499),
	('group.create.name.hint', 'gl', 'messages', 'Para os grupos locais, inclúe o país (p.ex. Lugar, País) dado que isto axudará coas buscas.', '2021-01-25 10:39:26', '2021-01-25 10:39:26', '2021-01-25 10:39:26', 'no', '', 5, NULL, 210880),
	('group.create.name.hint', 'it', 'messages', 'Per i gruppi locali, includi la nazione (ad es. Città, Nazione) poiché ciò ti aiuterà nelle ricerche.', '2020-05-28 12:55:40', '2020-05-28 12:55:40', '2020-05-28 12:55:40', 'no', '', 5, NULL, 261434),
	('group.create.name.hint', 'nl', 'messages', 'Voor lokale groepen, neem het land (bv. Plaats, Land) op, dit zal helpen bij zoekopdrachten.', '2020-09-22 18:42:11', '2020-09-22 18:42:11', '2020-09-22 18:42:11', 'no', '', 5, NULL, 21169),
	('group.create.name.hint', 'pl', 'messages', 'W przypadku grup lokalnych dodaj też nazwę kraju (np. Miejsce, Kraj), bo to znacznie ułatwi wyszukiwanie.', '2021-01-14 21:33:19', '2021-01-14 21:33:19', '2021-01-14 21:33:19', 'no', '', 5, NULL, 116789),
	('group.create.name.hint', 'pt', 'messages', 'Para grupos locais, inclua o país (ex: Local, País) pois isto ajuda nas pesquisas.', '2019-02-07 14:36:21', '2019-02-07 14:36:21', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('group.create.name.hint', 'zh-hant', 'messages', '對於當地群組，請包含國家（例如：地點，國家），這將有助於搜尋。', '2025-05-31 22:05:16', '2025-05-31 22:05:16', '2025-05-31 22:05:16', 'no', '', 5, NULL, 53422),
	('group.create.successful', 'de', 'messages', 'Du hast eine Anfrage zur Erstellung der Gruppe %name% auf BeWelcome erstellt. Diese Anfrage wird von einem BeWelcome-Moderator überprüft. Er wird dich dazu schnellstmöglich kontaktieren.', '2020-06-07 20:25:03', '2020-06-07 20:25:03', '2020-06-07 20:25:03', 'no', '', 5, NULL, 347),
	('group.create.successful', 'el', 'messages', 'Έχεις υποβάλλει αίτημα δημιουργίας %name% στο Bewelcome. Το αίτημα θα εξεταστεί από τους διαχειριστές του BW οι οποίοι θα έρθουν σε επαφή μαζί σου το συντομότερο δυνατό.', '2020-07-28 15:52:39', '2020-08-27 13:38:38', '2020-07-28 15:52:39', 'no', '', 5, NULL, 266544),
	('group.create.successful', 'en', 'messages', 'You have submitted a request to set up a group %name% on BeWelcome. This request will be reviewed by the BW Moderators and you will be contacted as quickly as possible.', '2019-01-25 19:35:10', '2019-01-25 19:35:10', '0000-00-00 00:00:00', 'no', 'Flash notice after creating a new group. Make sure to keep the %name% tag.', 5, NULL, 1),
	('group.create.successful', 'es', 'messages', 'Has enviado una solicitud para configurar el grupo %name% en BeWelcome. Esta solicitud será revisada por los Moderadores de BW y se pondrán en contacto contigo lo antes posible.', '2020-12-04 03:03:52', '2020-12-04 03:03:52', '2020-12-04 03:03:52', 'no', '', 5, NULL, 25548),
	('group.create.successful', 'fr', 'messages', 'Votre demande de création du groupe BeWelcome %name% a été envoyée. Elle sera traitée par les modérateurs BW et vous serez contacté·e prochainement.', '2019-02-19 13:30:11', '2019-02-19 13:30:11', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('group.create.successful', 'gl', 'messages', 'Remitiches unha solicitude para crear un grupo %name% en BeWelcome. Esta solicitude será revisada polo equipo de moderación de BW e nos poñeremos en contacto contigo tan rápido como sexa posible.', '2021-01-27 17:05:38', '2021-01-27 17:05:38', '2021-01-27 17:05:38', 'no', '', 5, NULL, 210880),
	('group.create.successful', 'it', 'messages', 'Avete presentato una richiesta per attivare un gruppo denominato %name% su BeWelcome. la vostra richiesta verrà vagliata dai moderatori di BW e verrete contattati appena possibile.', '2019-02-22 09:32:58', '2021-08-14 11:12:56', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160610),
	('group.create.successful', 'nl', 'messages', 'Je hebt een verzoek ingediend om de groep %name% op te zetten op BeWelcome.  Dit verzoek zal bekeken worden door de Moderatoren van BW en er zal zo snel mogelijk contact met je opgenomen worden.', '2020-09-24 11:32:25', '2020-09-24 11:32:25', '2020-09-24 11:32:25', 'no', '', 5, NULL, 21169),
	('group.create.successful', 'pl', 'messages', 'Wysłano zgłoszenie o stworzenie grupy %name% na BeWelcome. Twoją prośbę ocenią moderatorzy BeWelcome i skontaktują się z Tobą najszybciej, jak to możliwe.', '2021-01-14 21:18:51', '2021-01-14 21:18:51', '2021-01-14 21:18:51', 'no', '', 5, NULL, 116789),
	('group.create.successful', 'pt', 'messages', 'Submeteu um pedido para criar um grupo %name% no BeWelcome. Este pedido será apreciado pelos moderadores do BW que entrarão em contacto assim que possível.', '2019-02-07 14:07:59', '2019-02-07 14:07:59', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('group.create.warning', 'de', 'messages', 'Wir freuen uns, dass du eine neue Gruppe gründen willst, aber leider mögen Spammer sie auch. Die Gruppe muss deshalb noch von einem BW Foren-Moderator aktiviert werden. Lies bitte auch die %link_start%Regeln für Gruppen%link_end% für die Wahl des Gruppennamens und der Beschreibung.', '2019-04-30 10:20:22', '2019-04-30 10:20:22', '2019-04-30 10:20:22', 'no', '', 5, NULL, 2208),
	('group.create.warning', 'el', 'messages', 'Χαιρόμαστε που θέλεις να δημιουργήσεις μια νέα ομάδα, επειδή όμως τις λατρεύουν και οι spammers, παρακαλώ σημειώστε ότι το γκρουπ χρειάζεται να ενεργοποιηθεί από τους Διαχειριστές του BW Φόρουμ. Διάβασε επίσης τους %link_start%Rules για Groups%link_end% για να σε βοηθήσουν με το όνομα και τη περιγραφή της νέας ομάδας.', '2020-07-25 12:01:54', '2024-07-19 20:36:28', '2020-07-25 12:01:54', 'no', '', 5, NULL, 266502);
INSERT INTO `word` (`code`, `ShortCode`, `domain`, `Sentence`, `created`, `updated`, `majorupdate`, `donottranslate`, `Description`, `TranslationPriority`, `isarchived`, `author_id`) VALUES
	('group.create.warning', 'en', 'messages', 'We’re happy that you want to open a new group, but unfortunately spammers like to do that as well, so please note that the group will need to be activated by the BW Forum Moderators. Please also read the %link_start%Rules for Groups%link_end% when thinking about the new group’s name and description.', '2019-01-25 19:35:11', '2020-09-22 18:41:15', '0000-00-00 00:00:00', 'no', 'A warning text that members should check if the group already exists and that the new groups will be checked and possibly deleted by the forum moderators', 5, 0, 21169),
	('group.create.warning', 'es', 'messages', 'Nos alegra que quieras crear un nuevo grupo, pero, desafortunadamente, a los spammers también les gusta hacerlo, por lo cual debes tener en cuenta que el grupo necesitará ser activado por los Moderadores de Foro de BW. Por favor, lee también las %link_start%Normas para Grupos%link_end% antes de pensar el nombre y la descripción del nuevo grupo.', '2020-12-04 01:22:23', '2020-12-04 01:22:23', '2020-12-04 01:22:23', 'no', '', 5, NULL, 25548),
	('group.create.warning', 'fr', 'messages', 'Nous sommes ravi·e·s de voir que vous souhaitez ouvrir un nouveau groupe. Malheureusement, comme les spammers adorent aussi ouvrir des groupes, les modérateurs du forum BeWelcome doivent approuver manuellement chaque nouvelle demande. Profitez-en pour lire les %link_start%règles des groupes%link_end% pour vous aider à choisir un nom et une description.', '2019-02-19 12:48:32', '2019-02-19 12:48:32', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('group.create.warning', 'gl', 'messages', 'Encántanos que queiras abrir un novo grupo, pero desafortunadamente as persoas que envían correos non desexados tamén queren facelo. Por favor ten en conta que o grupo necesita que o activen as persoas que fan parte do Foro de Moderación de BW. Por favor, tamén le %link_start%as regras para grupos%link_end% cando penses no nome e descrición dun novo grupo.', '2021-01-25 10:35:32', '2021-01-25 10:39:36', '2021-01-25 10:35:32', 'no', '', 5, NULL, 210880),
	('group.create.warning', 'it', 'messages', 'Siamo lieti che tu voglia aprire un nuovo gruppo, ma purtroppo questo piace anche agli spammer, quindi tieni presente che il moderatore del forum BW dovrà attivare il gruppo. Leggi anche le %link_start% Regole per i gruppi %link_end% quando pensi al nome e alla descrizione del nuovo gruppo.', '2020-05-28 12:56:49', '2020-05-28 12:56:49', '2020-05-28 12:56:49', 'no', '', 5, NULL, 261434),
	('group.create.warning', 'nl', 'messages', 'We vinden het fijn dat je een nieuwe groep wil aanmaken, maar helaas houden spammers hier ook van, dus merk op dat de groep geactiveerd moet worden door de forummoderators van BW.  Lees ook de %link_start%Regels voor groepen%link_end% tijdens het nadenken over de naam en beschrijving van de nieuwe groep.', '2020-09-22 18:35:52', '2026-02-22 21:01:40', '2020-09-22 18:35:52', 'no', '', 5, NULL, 21169),
	('group.create.warning', 'pl', 'messages', 'Super, że chcesz stworzyć grupę, ale spamerzy też lubią to robić. Pamiętaj więc, że nasi moderatorzy będą ją musieli aktywować. Przeczytaj też proszę %link_start%Rules for Groups%link_end% zastanawiając się nad nową nazwą grupy i jej opisem.', '2021-01-14 21:28:02', '2021-01-14 21:28:02', '2021-01-14 21:28:02', 'no', '', 5, NULL, 116789),
	('group.create.warning', 'pt', 'messages', 'Ficamos contentes por querer criar um novo grupo, mas infelizmente também há pessoas com más intenções que gostam deles. Portanto, tenha em atenção que o grupo precisa de ser ativado pelos moderadores do Fórum BW. Leia também as %link_start%Regras para Grupos%link_end% ao pensar no nome e descrição do novo grupo.', '2019-02-07 15:00:51', '2019-02-07 15:00:51', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('group.create.warning', 'zh-hant', 'messages', '我們很高興您想建立一個新群組，但不幸的是，垃圾郵件發送者也喜歡這麼做，因此請注意，新群組需要由 BW 論壇管理員進行審核啟用。請在思考新群組名稱和描述時，也務必閱讀 %link_start%群組規則%link_end%。', '2025-05-31 22:07:47', '2025-05-31 22:07:47', '2025-05-31 22:07:47', 'no', '', 5, NULL, 53422),
	('group.decline.invitation', 'ca', 'messages+intl-icu', 'Fes clic a “{decline}” per avisar l\'administrador del grup que no hi estàs interessat,', '2021-12-02 15:33:51', '2021-12-02 15:33:51', '2021-12-02 15:33:51', 'no', '', 5, NULL, 304193),
	('group.decline.invitation', 'da', 'messages+intl-icu', 'Klik på "{decline}", for at fortælle administratorerne af gruppen, at du ikke er interesseret.', '2022-08-14 18:00:52', '2022-08-14 18:01:15', '2022-08-14 18:00:52', 'no', '', 5, NULL, 274594),
	('group.decline.invitation', 'el', 'messages+intl-icu', 'Πααρακαλουμε πατήστε στο "{decline}" για να πείτε στον διαχειριστή αυτής της ομάδας ότι δεν ενδιαφέρεστε.', '2023-01-29 08:57:48', '2023-01-29 08:57:48', '2023-01-29 08:57:48', 'no', '', 5, NULL, 266502),
	('group.decline.invitation', 'en', 'messages+intl-icu', 'Please click on “{decline}” to tell the administrator(s) of this group that you’re not interested.', '2020-10-01 19:18:57', '2020-10-13 08:35:58', '2020-10-01 19:18:57', 'no', 'Make sure to keep the \'\'{decline}\'\' tag.\r\n\r\nThis is linked to \'group.email.decline\' so please translate that as well.', 5, 0, 21169),
	('group.decline.invitation', 'es', 'messages+intl-icu', 'Pincha en “{decline}” para comunicar a la administración de este grupo que no es de tu interés.', '2020-11-30 03:10:11', '2020-11-30 03:10:11', '2020-11-30 03:10:11', 'no', '', 5, NULL, 25548),
	('group.decline.invitation', 'fr', 'messages+intl-icu', 'Cliquez sur «{decline}» pour signifier à l\'administrateur de ce groupe que vous n\'êtes pas intéressé·e.', '2020-10-16 19:52:52', '2020-10-16 19:52:52', '2020-10-16 19:52:52', 'no', '', 5, NULL, 168499),
	('group.decline.invitation', 'gl', 'messages+intl-icu', 'Por favor pincha “{decline}” para dicir ás persoas que administran o grupo que non tés interese en xuntarte ao mesmo.', '2021-01-20 18:20:47', '2021-09-02 07:42:10', '2021-01-20 18:20:47', 'no', '', 5, NULL, 210880),
	('group.decline.invitation', 'hy', 'messages+intl-icu', 'Խնդրում ենք սեղմել «{decline}» կոճակը՝ այս խմբի ադմինիստրատոր(ներ)ին տեղեկացնելու համար, որ դուք հետաքրքրված չեք։', '2026-03-06 06:50:48', '2026-03-06 06:54:47', '2026-03-06 06:50:48', 'no', '', 5, NULL, 519603),
	('group.decline.invitation', 'it', 'messages+intl-icu', 'Per piacere fai click su “{decline}” per far sapere all\'amministratore/i di questo gruppo che non sei interessato.', '2020-11-23 20:06:19', '2020-11-23 20:17:15', '2020-11-23 20:06:19', 'no', '', 5, NULL, 160610),
	('group.decline.invitation', 'nl', 'messages+intl-icu', 'Klik op “{decline}” om de beheerder(s) van deze groep te laten weten dat je niet geïnteresseerd bent.', '2020-10-13 08:35:34', '2026-02-04 19:49:27', '2020-10-13 08:35:34', 'no', '', 5, NULL, 21169),
	('group.decline.invitation', 'pl', 'messages+intl-icu', 'Kliknij “{odrzuć}” aby poinformować administratora (ów) tej grupy że nie jesteś zainteresowany/a.', '2020-10-22 19:09:46', '2020-10-22 19:09:46', '2020-10-22 19:09:46', 'no', '', 5, NULL, 37896),
	('group.decline.invitation', 'pt', 'messages+intl-icu', 'Clique em “{decline}” para indicar ao(s) administrador(es) deste grupo que não está interessado/a.', '2020-11-24 12:58:53', '2020-11-24 12:58:53', '2020-11-24 12:58:53', 'no', '', 5, NULL, 38787),
