	('groupdesc_hospitalityclub', 'ro', 'messages', 'Acest grup este pentru membri Hospitality Club ce doresc să-şi afişeze userul HC precum şi alte detalii ale activităţii lor acolo.', '2007-08-30 17:47:04', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1081),
	('groupdesc_hospitalityclub', 'ru', 'messages', 'Эта группа для членов Hospitality Club, для тех, которые хотят указать свое имя пользователя в HC, а также другие детали, связанные с их членством в данном клубе. ', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 79),
	('groupdesc_hospitalityclub', 'tr', 'messages', 'Bu grup aynı zamanda Hospitality Club üyesi olup, HC kullanıcı adlarını ve HC\'daki aktivitelerini paylaşmak isteyen üyelerimiz içindir.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 140),
