	('groupjoinsuccess', 'zh-hant', 'messages', '成功加入群组', '2013-02-05 13:08:55', '2021-05-02 07:48:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37722),
	('groupleavefail_resignadminfirst', 'ca', 'messages', 'No pots abandonar el grup. Si us plau, renuncia a ser l\'administrador del grup i assigna un altre membre com a nou administrador.', '2021-11-29 12:50:21', '2021-11-29 12:50:21', '2021-11-29 12:50:21', 'no', '', 5, NULL, 304193),
	('groupleavefail_resignadminfirst', 'cs', 'messages', 'Tuto skupinu nemůžeš opustit. Buď rezignuj na pozici administrátora skupiny nebo jmenuj jiného administrátora.', '2015-08-05 12:33:29', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('groupleavefail_resignadminfirst', 'de', 'messages', 'Du kannst diese Gruppe nicht verlassen. Bitte lege zuerst deine Rolle als Gruppenadministrator nieder und ernenne ein anderes Mitglied zum Administrator.', '2012-12-14 21:23:25', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('groupleavefail_resignadminfirst', 'el', 'messages', 'Δεν μπορείς να εγκαταλείψεις την ομάδα. Παραιτήσου από διαχειριστής της ομάδας και όρισε κάποιο άλλο μέλος ως νέο διαχειριστή.', '2020-08-14 18:20:42', '2020-08-14 18:20:58', '2020-08-14 18:20:42', 'no', '', 5, NULL, 266544),
	('groupleavefail_resignadminfirst', 'en', 'messages', 'You can\'t leave the group. Please resign as group administrator and assign another member as new administrator.', '2012-12-14 15:22:14', '2019-04-23 18:16:49', '2012-12-14 15:22:14', 'no', 'You can\'t leave the group. Please resign as group administrator and assign another member as new administrator.', 5, NULL, 554),
	('groupleavefail_resignadminfirst', 'es', 'messages', 'No puedes abandonar el grupo. Por favor cambia tu estatus de administrador y asigna otro miembro como nuevo administrador.', '2013-11-08 11:18:54', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40088),
	('groupleavefail_resignadminfirst', 'fr', 'messages', 'Vous ne pouvez pas quitter ce groupe. Veuillez désigner une nouvelle personne pour administrer le groupe avant de renoncer à le faire vous-même en quittant le groupe.', '2012-12-27 10:04:25', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('groupleavefail_resignadminfirst', 'gl', 'messages', 'Ti non podes deixar o grupo. Por favor dimite da administración do grupo e asigna outra persoa membro como nova administradora.', '2021-03-10 11:15:11', '2021-03-10 11:15:11', '2021-03-10 11:15:11', 'no', '', 5, NULL, 210880),
	('groupleavefail_resignadminfirst', 'it', 'messages', 'Non puoi lasciare il gruppo. Per favore dimettiti da amministratore di gruppo e contrassegna un\'altro membro come nuovo amministratore.', '2012-12-27 10:39:18', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 33078),
	('groupleavefail_resignadminfirst', 'nl', 'messages', 'Je kan de groep niet verlaten.  Gelieve eerst ontslag te nemen en iemand anders aan te stellen  als groepsmoderator.', '2012-12-15 18:34:38', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 22382),
	('groupleavefail_resignadminfirst', 'pl', 'messages', 'Nie możesz opuścić grupy. Zrezygnuj z administrowania nią i wyznacz nową administratorkę lub administratora.', '2021-01-13 19:52:52', '2021-01-13 19:52:52', '2021-01-13 19:52:52', 'no', '', 5, NULL, 116789),
	('groupleavefail_resignadminfirst', 'pt', 'messages', 'Não pode deixar o grupo. Por favor, desista do seu cargo de administrador do grupo e atribua essa responsabilidade a um outro membro.', '2012-12-28 15:50:34', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('groupleavefail_resignadminfirst', 'ru', 'messages', 'Вы не можете покинуть группу. Пожалуйста, войдите как администратор и назначьте другого участника в качестве администратора группы.', '2014-05-10 12:54:42', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('groupleavefail_resignadminfirst', 'sr', 'messages', 'Не можеш напустити групу. Молимо да даш оставку као админстратор групе и именуј другог члана као новог администратора.', '2015-02-15 14:12:21', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('groupleavefail_resignadminfirst', 'zh-hans', 'messages', '你不能离开这个群组. 请先辞去你的群组管理员身份并指派新的管理员.', '2013-02-05 13:13:39', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37722),
