	('groupsmygroupsnoresults', 'br', 'messages', 'Você ainda não entrou em nenhum grupo. Tente %sprocurar grupos%s para falar sobre interesses em comum ou %scrie um novo grupo%s.', '2020-10-01 10:53:50', '2020-10-01 10:56:31', '2020-10-01 10:53:50', 'no', '', 5, NULL, 2208),
	('groupsmygroupsnoresults', 'de', 'messages', 'Du bist noch keiner Gruppe beigetreten. %sSuche nach Gruppen%s, um über gemeinsame Interessen zu sprechen oder %sgründe eine neue Gruppe%s.', '2013-06-21 07:55:22', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('groupsmygroupsnoresults', 'el', 'messages', 'Δεν υπάρχουν ομάδες ακόμα που να γίνατε μέλος. Δοκίμασε να %ssearch για groups%s για να μιλήσετε για τα κοινά σας ενδιαφέροντα, ή να %screate μια καινούρια ομάδα.%s', '2017-07-21 08:23:49', '2023-06-10 05:53:02', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266502),
	('groupsmygroupsnoresults', 'en', 'messages', 'You have not joined any groups yet. Try to %ssearch for groups%s to talk about common interests or %screate a new group%s.', '2013-05-03 08:42:28', '2026-02-04 19:50:14', '0000-00-00 00:00:00', 'no', 'Show in /mygroups page for new members without joined groups yet. The %s creates a link and needs to be inserted BEFORE and AFTER the phrase which should be converted to a link. There will be 2 links to /groups/search and /groups/new. So check if you have 4 times %s in your translation.', 5, 0, 21169),
	('groupsmygroupsnoresults', 'es', 'messages', 'Todavía no te has unido a ningún grupo. %sBusca algún grupo%s para hablar sobre intereses comunes o %screa un nuevo grupo.%s', '2014-09-30 13:16:31', '2020-10-01 10:31:02', '0000-00-00 00:00:00', 'no', '', 5, NULL, 2208),
	('groupsmygroupsnoresults', 'fa', 'messages', 'امتحان کنید %screate a new group.%s را برای گفت‌گو درباره‌ی علاقه‌مندی مشترک یا %ssearch for groups%s هنوز گروهی وجود ندارد. ', '2015-06-11 17:59:40', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 41992),
	('groupsmygroupsnoresults', 'fr', 'messages', 'Vous n\'avez pas encore rejoint de groupe. Veuillez %schercher un groupe%s pour échanger sur un thème en particulier ou %scréer un nouveau groupe%s, s\'il n\'existe pas encore.', '2017-01-18 22:55:19', '2020-09-26 08:15:27', '0000-00-00 00:00:00', 'no', '', 5, NULL, 2208),
	('groupsmygroupsnoresults', 'gl', 'messages', 'Aínda non fas parte dos grupos. Trata de %sbuscar grupos%s para falar de intereses comúns ou %screa un novo grupo.%s', '2021-03-02 14:43:22', '2021-03-02 14:43:22', '2021-03-02 14:43:22', 'no', '', 5, NULL, 210880),
	('groupsmygroupsnoresults', 'it', 'messages', 'Non sei ancora iscritto a nessun gruppo. Prova a %cercare per gruppi% per parlare di interessi in comune o %crea un nuovo gruppo.%s', '2013-05-15 09:30:23', '2020-10-01 10:31:58', '0000-00-00 00:00:00', 'no', '', 5, NULL, 2208),
	('groupsmygroupsnoresults', 'nl', 'messages', 'Je bent nog niet lid van een groep.  Probeer %sgroepen te zoeken%s om over gemeenschappelijke interesses te praten of %smaak een nieuwe groep aan%s.', '2013-06-03 18:04:49', '2026-02-04 19:53:33', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('groupsmygroupsnoresults', 'pl', 'messages', 'Nie ma Cię jeszcze w żadnej grupie. Spróbuj %sposzukać grup%s, gdzie porozmawiacie o wspólnych zainteresowaniach, albo utwórz własną.', '2021-01-14 18:11:04', '2021-01-14 18:11:04', '2021-01-14 18:11:04', 'no', '', 5, NULL, 116789),
