	('groupsmygroupsnoresults', 'ru', 'messages', 'Пока еще нет групп. Попробуйте %sнайти группу%s для обсуждения общих интересов или %sсоздайте новую группу%s.', '2014-05-02 11:55:25', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
