	('help.admin.faq.category.translation.id', 'hy', 'messages', 'Հաճախ տրվող հարց ու պատասխան կատեգորիայի համար օգտագործվող բառային կոդը: (\'faq_cat_\'-ը ավտոմատ կավելացվի սկզբում)', '2025-04-06 13:35:43', '2025-04-06 13:35:43', '2025-04-06 13:35:43', 'no', '', 5, NULL, 519603),
