	('help.admin.faq.category.translation.id', 'pt', 'messages', 'O código para ser usado por esta categoria de FAQ. (\'faq_cat\' é automaticamente adicionado ao início)', '2019-03-25 15:29:42', '2019-03-25 15:29:42', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('help.admin.faq.category.translation.id', 'uk', 'messages', 'Словесний код для використання в категорії FAQ. (\'faq_cat_\' буде автоматично додано на початку.)', '2026-04-01 23:17:31', '2026-04-01 23:17:31', '2026-04-01 23:17:31', 'no', '', 5, NULL, 573491),
	('help.birthdate', 'da', 'messages+intl-icu', 'Din fødselsdag vises aldrig til andre medlemmer. Men du kan vælge at vise din alder på din profil og på søgeresultatene.', '2024-07-05 18:46:21', '2024-07-05 18:46:21', '2024-07-05 18:46:21', 'no', '', 5, NULL, 479317),
	('help.birthdate', 'el', 'messages+intl-icu', 'Η ημερομηνία γέννησής σας δεν εμφανίζεται ποτέ σε άλλα μέλη. Μπορείτε όμως να επιλέξετε να εμφανίζεται η ηλικία σας στο προφίλ και στα αποτελέσματα αναζήτησης.', '2024-06-02 05:24:58', '2024-06-02 05:24:58', '2024-06-02 05:24:58', 'no', '', 5, NULL, 266502),
	('help.birthdate', 'en', 'messages+intl-icu', 'Your date of birth is never shown to other members. But you can choose to show your age on your profile and in search results.', '2024-05-06 18:42:14', '2024-10-15 07:15:31', '2024-05-15 19:39:35', 'no', 'Help text for the birth date field.', 5, 0, 21169),
	('help.birthdate', 'es', 'messages+intl-icu', 'Tu fecha de nacimiento nunca se muestra a otras personas. Sin embargo, puedes seleccionar que se muestre tu edad en tu perfil y en los resultados de búsquedas.', '2024-11-13 15:49:14', '2024-11-13 15:49:14', '2024-11-13 15:49:14', 'no', '', 5, NULL, 25548),
	('help.birthdate', 'fr', 'messages+intl-icu', 'Votre date de naissance n’est jamais visible par d’autres membres. Mais vous pouvez choisir d’afficher votre âge sur votre profil et dans les résultats de recherche.', '2025-03-22 13:20:16', '2025-03-22 13:20:16', '2025-03-22 13:20:16', 'no', '', 5, NULL, 168499),
	('help.birthdate', 'gl', 'messages+intl-icu', 'A túa data de nacemento nunca se mostra a outras persoas membro. Pero podes escoller amosar a túa idade no perfil e nos resultados da busca.', '2024-08-05 11:50:17', '2024-08-05 11:50:17', '2024-08-05 11:50:17', 'no', '', 5, NULL, 210880),
	('help.birthdate', 'it', 'messages+intl-icu', 'La tua data di nascita non viene mai mostrata agli altri membri. Ma puoi scegliere di mostrare la tua età sul profilo e nei risultati di ricerca.', '2024-08-28 17:37:11', '2024-08-28 17:37:11', '2024-08-28 17:37:11', 'no', '', 5, NULL, 160610),
	('help.birthdate', 'nl', 'messages+intl-icu', 'Je geboortedatum wordt nooit aan andere leden getoond.  Je kan er echter voor kiezen om je leeftijd te laten zien in zoekresultaten en op je profiel.', '2024-10-15 07:14:58', '2024-10-23 16:01:16', '2024-10-15 07:14:58', 'no', '', 5, NULL, 21169),
	('help.birthdate', 'pt', 'messages+intl-icu', 'A sua data de nascimento nunca é mostrada a outros membros. Mas pode optar por apresentar a sua idade no seu perfil e nos resultados de pesquisa.', '2024-12-31 18:54:12', '2024-12-31 18:54:12', '2024-12-31 18:54:12', 'no', '', 5, NULL, 38787),
	('help.birthdate', 'uk', 'messages+intl-icu', 'Ваша дата народження ніколи не показується іншим учасникам. Але ви можете вибрати показувати свій вік у своєму профілі та в результатах пошуку.', '2026-04-01 21:50:26', '2026-04-01 21:50:26', '2026-04-01 21:50:26', 'no', '', 5, NULL, 573491),
	('help.email', 'el', 'messages+intl-icu', 'Το BeWelcome χρησιμοποιεί τη διεύθυνση ηλεκτρονικού ταχυδρομείου σας για να προωθεί μηνύματα από μέλη και να στέλνει άλλες ειδοποιήσεις. Η ίδια η διεύθυνση δεν είναι ορατή σε άλλα μέλη.', '2024-06-02 05:27:06', '2024-06-02 05:27:06', '2024-06-02 05:27:06', 'no', '', 5, NULL, 266502),
	('help.email', 'en', 'messages+intl-icu', 'BeWelcome uses your email address to forward messages from members and to send other notifications. The address itself is not visible to other members.', '2024-05-06 18:42:14', '2024-05-06 18:42:14', '2024-05-06 18:42:14', 'no', 'Help text for the email address field.', 5, NULL, 1),
	('help.email', 'es', 'messages+intl-icu', 'BeWelcome usa tu correo electrónico para hacerte llegar mensajes de otras personas y para remitirte otras notificaciones. Tu dirección no es visible para el resto de personas.', '2024-11-13 15:44:07', '2024-11-13 15:44:07', '2024-11-13 15:44:07', 'no', '', 5, NULL, 25548),
	('help.email', 'fr', 'messages+intl-icu', 'BeWelcome utilise votre adresse email pour vous faire suivre les messages d’autres membres et pour vous envoyer des notifications. Votre adresse ne sera pas visible par les autres membres.', '2025-03-22 13:30:30', '2025-03-22 13:30:30', '2025-03-22 13:30:30', 'no', '', 5, NULL, 168499),
	('help.email', 'gl', 'messages+intl-icu', 'BeWelcome usa o teu enderezo de correo electrónico para reenviar mensaxes das persoas membro e para enviar outras notificacións. O enderezo non é visible para as demais persoas membro.', '2024-08-05 12:16:20', '2024-08-05 12:16:20', '2024-08-05 12:16:20', 'no', '', 5, NULL, 210880),
	('help.email', 'it', 'messages+intl-icu', 'BeWelcome usa il tuo indirizzo email per inoltrare messaggi dai membri e per inviare altre notifiche. L\'indirizzo stesso non è visibile agli altri membri.', '2024-08-28 17:58:58', '2024-08-28 17:58:58', '2024-08-28 17:58:58', 'no', '', 5, NULL, 160610),
	('help.email', 'nl', 'messages+intl-icu', 'BeWelcome gebruikt je e-mailadres om berichten door te sturen van andere leden en om andere notificaties te sturen.  Het adres zelf is niet zichtbaar voor andere leden.', '2024-10-21 18:44:01', '2024-10-21 18:44:01', '2024-10-21 18:44:01', 'no', '', 5, NULL, 21169),
	('help.email', 'pt', 'messages+intl-icu', 'O BeWelcome usa o seu endereço de correio eletrónico para reencaminhar mensagens de outros membros e para lhe enviar outras notificações. O endereço não é visível por outros membros.', '2024-12-31 18:45:24', '2024-12-31 18:45:24', '2024-12-31 18:45:24', 'no', '', 5, NULL, 38787),
	('help.email', 'uk', 'messages+intl-icu', 'BeWelcome використовує вашу електронну адресу для пересилання повідомлень від учасників та для надсилання інших сповіщень. Сама електронна адреса ніколи не показується іншим учасникам.', '2026-04-01 21:54:57', '2026-04-01 21:54:57', '2026-04-01 21:54:57', 'no', '', 5, NULL, 573491),
	('help.gender', 'ca', 'messages+intl-icu', 'Ocultem el teu gènere, però pots fer que es mostri als resultats de cerca i al teu perfil.', '2025-06-14 17:49:26', '2025-06-14 17:49:26', '2025-06-14 17:49:26', 'no', '', 5, NULL, 306997),
	('help.gender', 'da', 'messages+intl-icu', 'Dit køn er skjult efter tilmeldelsen, men du kan vise det i søgeresultaterne og på din profil.', '2024-07-05 18:48:53', '2024-07-05 18:48:53', '2024-07-05 18:48:53', 'no', '', 5, NULL, 479317),
	('help.gender', 'el', 'messages+intl-icu', 'Το φύλο σας είναι κρυφό μετά την εγγραφή, αλλά μπορείτε να το ενεργοποιήσετε ώστε να εμφανίζεται στα αποτελέσματα αναζήτησης και στο προφίλ σας.', '2024-06-02 05:45:24', '2024-06-02 05:45:24', '2024-06-02 05:45:24', 'no', '', 5, NULL, 266502),
	('help.gender', 'en', 'messages+intl-icu', 'Your gender is hidden after signup but you can enable it to be shown in search results and on your profile.', '2024-05-06 18:42:14', '2024-05-06 18:42:14', '2024-05-06 18:42:14', 'no', 'Help text for the gender field.', 5, NULL, 1),
	('help.gender', 'es', 'messages+intl-icu', 'Tu género quedará oculto tras registrarte, pero puedes activar que se muestre en tu perfil y en los resultados de búsquedas.', '2024-11-13 15:50:32', '2024-11-13 15:50:32', '2024-11-13 15:50:32', 'no', '', 5, NULL, 25548),
	('help.gender', 'fr', 'messages+intl-icu', 'Votre sexe est caché par défaut, mais vous pouvez choisir de le rendre visible sur votre profil et dans les résultats de recherche.', '2025-03-22 13:18:19', '2025-03-22 13:18:19', '2025-03-22 13:18:19', 'no', '', 5, NULL, 168499),
