	('home.abstract.bewelcome.cultural', 'ca', 'messages', 'BeWelcome et permet compartir casa teva, trobar-te amb altres viatgers, i trobar un allotjament per al teu viatge.', '2021-10-05 13:43:34', '2021-10-05 13:43:34', '2021-10-05 13:43:34', 'no', '', 5, NULL, 304193),
	('home.abstract.bewelcome.cultural', 'de', 'messages', 'Mit BeWelcome kannst du eine Unterkunft teilen, mit Reisenden in Kontakt treten, dich treffen und auf Reisen eine Unterkunft finden.', '2020-10-11 16:04:29', '2020-10-18 20:34:43', '2020-10-11 16:04:29', 'no', '', 5, NULL, 2208),
	('home.abstract.bewelcome.cultural', 'el', 'messages', 'Συνδεθείτε και μείνετε με σπουδαίους ανθρώπους και προσφέρετε στους ταξιδιώτες ένα δωρεάν μέρος για να μείνουν.', '2020-07-23 17:51:04', '2023-06-01 17:00:12', '2020-07-23 17:51:04', 'no', '', 5, NULL, 266502),
	('home.abstract.bewelcome.cultural', 'en', 'messages', 'Join the 230.000 members of BeWelcome, the largest free hospitality community.', '2019-01-25 19:35:11', '2024-07-18 19:52:57', '2024-07-06 15:50:58', 'no', 'Abstract on the home page. Accompanied by home.headline.bewelcome.cultural.', 5, 0, 2208),
	('home.abstract.bewelcome.cultural', 'eo', 'messages', 'BeWelcome permesas al vi dividi lokon por restado, konektiĝi kun vojaĝantoj, renkontiĝi kaj trovi restadejon dum via vojaĝo.', '2020-10-29 15:27:29', '2020-10-29 15:27:29', '2020-10-29 15:27:29', 'no', '', 5, NULL, 47526),
	('home.abstract.bewelcome.cultural', 'es', 'messages', 'Únete a las 230.000 personas que formamos BeWelcome, la mayor comunidad libre y gratuita de hospitalidad.', '2020-10-18 20:45:04', '2024-11-13 15:19:31', '2020-10-18 20:45:04', 'no', '', 5, NULL, 25548),
	('home.abstract.bewelcome.cultural', 'fr', 'messages', 'Rejoignez les 230.000 membres de BeWelcome, la plus grande communauté d’hospitalité gratuite.', '2019-02-19 11:39:15', '2026-04-25 13:30:17', '0000-00-00 00:00:00', 'no', '', 5, NULL, 168499),
	('home.abstract.bewelcome.cultural', 'gl', 'messages', 'Xúntate ás  230.000 persoas de BeWelcome, a máis grande comunidade de hospitalidade libre e gratuíta.', '2021-01-21 10:23:42', '2024-08-06 08:07:00', '2021-01-21 10:23:42', 'no', '', 5, NULL, 210880),
	('home.abstract.bewelcome.cultural', 'hu', 'messages', 'A BeWelcome-on keresztül lehetőséged van szállást adni és kérni, világutazókkal találkozni és akár világutazóvá válni is!', '2020-06-05 07:35:34', '2020-06-05 07:35:34', '2020-06-05 07:35:34', 'no', '', 5, NULL, 36939),
	('home.abstract.bewelcome.cultural', 'hy', 'messages', 'Միացի՛ր ԲիՎելքմի 230000 անդամներին՝ ամենամեծ անվճար հյուրընկալության համայնքին:', '2025-04-06 12:41:20', '2025-08-28 12:31:15', '2025-04-06 12:41:20', 'no', '', 5, NULL, 519603),
	('home.abstract.bewelcome.cultural', 'it', 'messages', 'BeWelcome ti consente di condividere un posto dove stare, entrare in contatto con i viaggiatori, incontrarti e trovare un alloggio durante il tuo viaggio.', '2020-05-28 12:47:22', '2020-10-04 20:57:44', '2020-05-28 12:47:22', 'no', '', 5, NULL, 2208),
	('home.abstract.bewelcome.cultural', 'nl', 'messages', 'Doe mee met de 230.000 leden van BeWelcome, de grootste gratis gastvrijheidsgemeenschap.', '2019-03-10 09:59:01', '2025-01-30 20:14:33', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('home.abstract.bewelcome.cultural', 'pl', 'messages', 'Dzięki BeWelcome znajdziesz miejsce do przenocowania, podzielisz się swoją kanapą, poznasz innych podróżników i wspaniałych lokalsów.', '2021-01-13 22:58:48', '2021-01-13 22:58:48', '2021-01-13 22:58:48', 'no', '', 5, NULL, 116789),
	('home.abstract.bewelcome.cultural', 'pt', 'messages', 'O BeWelcome permite-lhe partilhar um lugar para ficar, ligar-se a viajantes, combinar encontros e encontrar acomodação na sua viagem.', '2019-02-07 15:52:04', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('home.abstract.bewelcome.cultural', 'rm', 'messages', 'BeWelcome permetta a tai da parter in albiert,  sa colliar cun viagaturAs, sa scuntrar e chattar in albiert sin tes viadi.', '2020-06-07 20:47:46', '2020-06-07 20:48:53', '2020-06-07 20:47:46', 'no', '', 5, NULL, 662),
	('home.abstract.bewelcome.cultural', 'ru', 'messages', 'Присоединяйтесь к 230 000 участвующим в крупнейшем бесплатном сообществе в сфере гостеприимства  BeWelcome.', '2020-06-09 21:36:30', '2025-03-22 16:29:45', '2020-06-09 21:36:30', 'no', '', 5, NULL, 519603),
	('home.abstract.bewelcome.cultural', 'uk', 'messages', 'Приєднуйтесь до 230.000 користувачів BeWelcome, найбільшої безкоштовної спільноти гостинності.', '2026-04-03 17:45:40', '2026-04-03 17:46:01', '2026-04-03 17:45:40', 'no', '', 5, NULL, 573491),
	('home.abstract.bewelcome.cultural', 'zh-hant', 'messages', '與提供住宿的人們聯繫，向旅行的人們提供免費住宿。', '2023-10-24 20:14:15', '2023-10-24 20:14:15', '2023-10-24 20:14:15', 'no', '', 5, NULL, 53422),
	('home.bewelcome.free', 'ca', 'messages', 'És i sempre serà una comunitat gratuïta, de codi obert, sense ànim de lucre i democràtica.', '2021-10-05 13:44:25', '2023-05-18 16:42:31', '2021-10-05 13:44:25', 'no', '', 5, NULL, 38787),
	('home.bewelcome.free', 'de', 'messages', 'Es ist und bleibt kostenfrei, Open Source, nicht gewinnorientiert und demokratisch.', '2020-10-07 17:02:57', '2023-05-18 16:42:04', '2020-10-07 17:02:57', 'no', '', 5, NULL, 38787),
	('home.bewelcome.free', 'el', 'messages', 'Μείνετε με ντόπιους, φιλοξενήστε ταξιδιώτες στο σπίτι σας, γνωρίστε κόσμο, κάντε νέους φίλους σε όλο τον κόσμο και μοιραστείτε αυθεντικές ταξιδιωτικές εμπειρίες.', '2020-08-19 20:03:09', '2024-07-09 05:57:10', '2020-08-19 20:03:09', 'no', '', 5, NULL, 266502),
	('home.bewelcome.free', 'en', 'messages', 'Stay with locals, host travelers in your home, meet people, make new friends all over the world and share authentic travel experiences.', '2019-01-25 19:35:11', '2024-07-18 19:59:09', '2024-07-06 15:52:28', 'no', 'Second part of the subtext shown on the homepage below the Join button', 5, 0, 2208),
	('home.bewelcome.free', 'eo', 'messages', 'Ĝi estas kaj ĉiam restos senpaga, liberfonta, neprofitcela, demokratia komunumo.', '2020-10-29 15:29:06', '2023-05-18 16:44:57', '2020-10-29 15:29:06', 'no', '', 5, NULL, 38787),
	('home.bewelcome.free', 'es', 'messages', 'Hospédate con personas locales, ofrece alojamiento en tu casa, conoce gente, haz amistades de todo el mundo y comparte auténticas experiencias de viaje.', '2020-10-18 20:49:48', '2024-11-13 15:21:46', '2020-10-18 20:49:48', 'no', '', 5, NULL, 25548),
	('home.bewelcome.free', 'fr', 'messages', 'Séjournez chez l\'habitant, hébergez des voyageurs chez vous, rencontrez des gens, faites-vous des amis partout dans le monde et partagez des expériences de voyage authentiques.', '2019-02-19 11:42:16', '2026-04-25 13:33:31', '0000-00-00 00:00:00', 'no', '', 5, NULL, 168499),
	('home.bewelcome.free', 'gl', 'messages', 'Fica coa veciñanza dos lugares onde viaxes, hospeda persoas viaxeiras na túa casa, coñece xente, fai novas amizades en todo o mundo e comparte experiencias de viaxe auténticas.', '2021-01-21 10:27:32', '2024-08-05 12:19:46', '2021-01-21 10:27:32', 'no', '', 5, NULL, 210880),
	('home.bewelcome.free', 'hu', 'messages', 'A közösségi tagság ingyenes és az is marad, nyílt forráskóddal, nem haszonszerzés céljából, demokratikus keretek között.', '2020-06-05 07:37:54', '2023-05-18 16:43:55', '2020-06-05 07:37:54', 'no', '', 5, NULL, 38787),
	('home.bewelcome.free', 'hy', 'messages', 'Մնա՛ տեղացիների մոտ, հյուրընկալի՛ր ճամփորդներին ձեր տանը, ծանոթացի՛ր նոր մարդկանց հետ, ձեռք բերելով նոր ընկերներ ամբողջ աշխարհով մեկ և կիսվի՛ր իրական ճամփորդական փորձառություններով:', '2025-04-06 17:11:58', '2025-04-06 17:11:58', '2025-04-06 17:11:58', 'no', '', 5, NULL, 519603),
	('home.bewelcome.free', 'it', 'messages', 'È e  sarà sempre una comunità democratica gratuita, open source, no profit.', '2020-05-28 12:48:17', '2023-05-18 16:39:48', '2020-05-28 12:48:17', 'no', '', 5, NULL, 38787),
	('home.bewelcome.free', 'nl', 'messages', 'Verblijf bij inwoners, ontvang reizigers bij jou thuis, ontmoet mensen, maak nieuwe vrienden van over de hele wereld en deel authentieke reiservaringen.', '2019-03-11 11:48:27', '2025-01-30 20:14:05', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('home.bewelcome.free', 'pl', 'messages', 'To jest i zawsze będzie oparta na otwartym oprogramowaniu, non profit, a przede wszystkim demokratyczna i wolna społeczność.', '2021-01-14 21:54:29', '2023-05-18 16:39:04', '2021-01-14 21:54:29', 'no', '', 5, NULL, 38787),
	('home.bewelcome.free', 'pt', 'messages', 'O BeWelcome é e será sempre de utilização livre e gerido democraticamente por voluntários. Junte-se à nossa comunidade em rápido crescimento, com mais de 220.000 membros em todo o mundo.', '2019-02-06 20:12:32', '2023-05-30 12:25:27', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('home.bewelcome.free', 'rm', 'messages', 'Nus essan e restain adina ina cuminanza libra, open source, senza finamira da gudogn e democratica.', '2020-06-23 14:24:39', '2023-05-18 16:49:54', '2020-06-23 14:24:39', 'no', '', 5, NULL, 38787),
	('home.bewelcome.free', 'ru', 'messages', 'Останавливайтесь у местных, принимайте путешествующих у себя дома, знакомьтесь, заводите новых друзей по всему миру и делитесь настоящими впечатлениями от путешествий.', '2020-06-09 21:42:12', '2025-03-22 16:40:23', '2020-06-09 21:42:12', 'no', '', 5, NULL, 519603),
	('home.bewelcome.free', 'uk', 'messages', 'Залишайтеся з місцевими, приймайте мандрівників у своєму домі, зустрічайте людей, заводьте нових друзів по всьому світу та діліться автентичними враженнями від подорожей.', '2026-04-03 17:45:54', '2026-04-03 17:46:12', '2026-04-03 17:45:54', 'no', '', 5, NULL, 573491),
	('home.bewelcome.free', 'zh-hant', 'messages', 'BeWelcome  是個在全球擁有超過 220,000 名會員且快速發展的社群，始終不收費，並由全球自發性的志工朋友們，用民主式的方式發展與維護。', '2023-10-24 20:24:05', '2023-10-24 20:24:05', '2023-10-24 20:24:05', 'no', '', 5, NULL, 53422),
