	('home.title.onestep', 'ca', 'messages', 'El món és a només una passa de distància', '2021-10-05 13:38:41', '2021-10-05 13:38:41', '2021-10-05 13:38:41', 'no', '', 5, NULL, 304193),
	('home.title.onestep', 'da', 'messages', 'Åben din dør for verden!', '2023-04-01 06:38:05', '2023-04-01 06:38:05', '2023-04-01 06:38:05', 'no', '', 5, NULL, 274594),
	('home.title.onestep', 'de', 'messages', 'Die ganze Welt ist nur einen Schritt entfernt', '2020-06-06 15:29:18', '2020-06-06 15:29:18', '2020-06-06 15:29:18', 'no', '', 5, NULL, 25410),
	('home.title.onestep', 'el', 'messages', 'Άνοιξε την πόρτα σου στον κόσμο!', '2020-07-23 18:00:01', '2023-05-29 13:40:52', '2020-07-23 18:00:01', 'no', '', 5, NULL, 266502),
	('home.title.onestep', 'en', 'messages', 'Open your door to the world!', '2019-01-25 19:35:11', '2023-01-16 21:42:25', '0000-00-00 00:00:00', 'no', 'Header on the opening page just before entering a username or location to invite to signup', 5, 0, 2208),
	('home.title.onestep', 'eo', 'messages', 'La mondo situas nur unu paŝon de ĉi tie', '2020-10-29 15:24:58', '2020-10-29 15:24:58', '2020-10-29 15:24:58', 'no', '', 5, NULL, 47526),
	('home.title.onestep', 'es', 'messages', '¡Abre tu puerta al mundo!', '2020-11-30 17:17:14', '2023-05-29 10:47:51', '2020-11-30 17:17:14', 'no', '', 5, NULL, 25548),
	('home.title.onestep', 'fr', 'messages', 'Ouvrez votre porte sur le monde!', '2019-02-19 12:32:16', '2023-12-30 10:49:00', '0000-00-00 00:00:00', 'no', '', 5, NULL, 168499),
	('home.title.onestep', 'gl', 'messages', 'Abre a túa porta ao mundo!', '2021-01-21 10:54:19', '2023-10-26 08:40:02', '2021-01-21 10:54:19', 'no', '', 5, NULL, 210880),
	('home.title.onestep', 'hu', 'messages', 'A világ egy karnyújtásnyira van...', '2020-06-05 07:48:29', '2020-06-05 07:48:29', '2020-06-05 07:48:29', 'no', '', 5, NULL, 36939),
	('home.title.onestep', 'hy', 'messages', 'Բացի՜ր դուռդ աշխարհի առաջ։', '2025-04-08 18:33:15', '2025-04-08 18:33:15', '2025-04-08 18:33:15', 'no', '', 5, NULL, 519603),
	('home.title.onestep', 'it', 'messages', 'Il mondo è ad un solo passo da qui', '2020-05-25 21:54:43', '2020-05-25 21:54:43', '2020-05-25 21:54:43', 'no', '', 5, NULL, 261434),
	('home.title.onestep', 'nl', 'messages', 'Open je deur naar de wereld!', '2020-06-08 18:59:14', '2023-09-23 17:58:58', '2020-06-08 18:59:14', 'no', '', 5, NULL, 21169),
	('home.title.onestep', 'pl', 'messages', 'Cały świat jest tylko o krok stąd.', '2021-01-13 23:21:54', '2021-01-13 23:21:54', '2021-01-13 23:21:54', 'no', '', 5, NULL, 116789),
	('home.title.onestep', 'pt', 'messages', 'O mundo está a um passo daqui', '2019-02-07 14:58:47', '2019-02-07 14:58:51', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('home.title.onestep', 'ru', 'messages', 'Откройте свои двери миру!', '2025-03-21 17:25:17', '2025-03-21 17:25:17', '2025-03-21 17:25:17', 'no', '', 5, NULL, 519603),
	('home.title.onestep', 'uk', 'messages', 'Відкрийте свої двері світу!', '2026-04-03 17:50:38', '2026-04-03 17:51:29', '2026-04-03 17:50:38', 'no', '', 5, NULL, 573491),
	('home.title.onestep', 'zh-hant', 'messages', '開啟你通往世界的門!', '2023-10-24 20:32:22', '2023-10-24 20:32:22', '2023-10-24 20:32:22', 'no', '', 5, NULL, 53422),
	('home.title.onestep.sub', 'ca', 'messages', 'Creiem que compartir crea un món millor. Pots deixar que la gent es quedi a casa o mostrar-los el teu entorn. És fàcil i es diu hospitalitat.', '2021-10-05 13:39:49', '2021-10-05 13:39:49', '2021-10-05 13:39:49', 'no', '', 5, NULL, 304193),
	('home.title.onestep.sub', 'de', 'messages', 'Wir glauben fest daran, dass teilen zu einer besseren Welt führt. Du kannst Leute zum übernachten einladen oder Ihnen deine Umgebung zeigen. Es ist ganz einfach und wir nennen es Gastfreundschaft.', '2020-06-07 21:02:47', '2020-06-07 21:02:47', '2020-06-07 21:02:47', 'no', '', 5, NULL, 347),
	('home.title.onestep.sub', 'el', 'messages', 'Πιστεύουμε πως το να μοιράζεσαι κάνει καλύτερο το κόσμο μας. Μπορείς να κοιμήσεις κόσμο στο σπίτι σου ή να τους ξεναγήσεις. Είναι κάτι εύκολο και λέγεται φιλοξενία.', '2020-07-23 18:07:35', '2020-08-27 07:44:27', '2020-07-23 18:07:35', 'no', '', 5, NULL, 266544),
	('home.title.onestep.sub', 'en', 'messages', 'We believe that sharing creates a better world. You can let people stay over or show them around. It’s easy and it’s called hospitality.', '2019-01-25 19:35:11', '2020-06-08 19:01:44', '0000-00-00 00:00:00', 'no', 'Sub-header on the opening page before chosing a username to signup', 5, 0, 21169),
	('home.title.onestep.sub', 'eo', 'messages', 'Ni kredas ke dividado kreas pli bonan mondon. Vi povas gastigi homojn, aŭ montri al ili vian regionon. Tio facilas, kaj oni nomas ĝin gastamo.', '2020-10-29 15:35:48', '2020-10-29 15:35:48', '2020-10-29 15:35:48', 'no', '', 5, NULL, 47526),
	('home.title.onestep.sub', 'es', 'messages', 'Creemos que compartir crea un mundo mejor. Puedes ofrecer a personas pasar la noche en tu casa o hacerles de guía. Es sencillo y se llama hospitalidad.', '2020-11-30 17:38:48', '2020-11-30 17:38:48', '2020-11-30 17:38:48', 'no', '', 5, NULL, 25548),
	('home.title.onestep.sub', 'fr', 'messages', 'Nous pensons qu\'en partageant, nous créons un monde meilleur. Vous pouvez héberger des voyageurs ou leur montrer les environs. C\'est plus simple que vous ne le pensez !', '2019-02-19 12:33:58', '2020-06-20 10:54:46', '0000-00-00 00:00:00', 'no', '', 5, NULL, 168499),
	('home.title.onestep.sub', 'gl', 'messages', 'Creemos que compartir crea un mundo mellor. Podes acoller xente na casa ou facerlles de guía. É doado e chámase hospitalidade.', '2021-01-21 10:57:54', '2021-01-21 10:57:54', '2021-01-21 10:57:54', 'no', '', 5, NULL, 210880),
	('home.title.onestep.sub', 'hu', 'messages', 'Hiszünk benne, hogy együtt építjük a világot. Vendégelj meg valakit, adj neki szállást, és ismerkedjetek össze! Utazz Te is és élvezd a BeWelcome tagok vendégszeretetét!', '2020-06-05 07:50:45', '2020-06-05 07:50:45', '2020-06-05 07:50:45', 'no', '', 5, NULL, 36939),
	('home.title.onestep.sub', 'hy', 'messages', 'Մենք հավատում ենք, որ ունեցածով կիսվելը ստեղծում է ավելի լավ աշխարհ: Դու կարող ես մեկին գիշերակաց առաջարկել կամ ցույց տալ շրջակայքը: Դա հեշտ է և կոչվում է հյուրընկալություն:', '2025-04-08 18:38:00', '2025-04-08 18:38:00', '2025-04-08 18:38:00', 'no', '', 5, NULL, 519603),
	('home.title.onestep.sub', 'it', 'messages', 'Crediamo che la condivisione crei un mondo migliore. puoi ospitare persone o mostrargli i luoghi che conosci. è facile ed è chiamata ospitalità!', '2020-05-25 21:54:28', '2020-05-25 21:54:28', '2020-05-25 21:54:28', 'no', '', 5, NULL, 261434),
	('home.title.onestep.sub', 'nl', 'messages', 'Wij geloven erin dat delen een betere wereld creëert.  Je kan mensen laten overnachten of hen de omgeving tonen.  Het is makkelijk en het heet gastvrijheid.', '2020-06-08 19:01:20', '2026-03-09 20:14:07', '2020-06-08 19:01:20', 'no', '', 5, NULL, 21169),
	('home.title.onestep.sub', 'pl', 'messages', 'Wierzymy, że dzięki dzieleniu się twórzmy lepszy świat. Możesz pozwolić ludziom przespać się u Ciebie, albo tylko wypić razem kawę, czy pokazać im okolicę. To proste, cudowne i nazywa się gościnność.', '2021-01-13 23:29:48', '2021-01-13 23:29:48', '2021-01-13 23:29:48', 'no', '', 5, NULL, 116789),
	('home.title.onestep.sub', 'pt', 'messages', 'Acreditamos que a partilha cria um mundo melhor. Pode deixar pessoas ficar consigo ou mostrar-lhes a sua cidade. É fácil e chama-se hospitalidade.', '2019-02-07 14:53:35', '2019-02-07 14:53:35', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('home.title.onestep.sub', 'ru', 'messages', 'Мы верим, что делиться значит делать мир лучше. Вы можете позволить людям остаться ночевать у себя или показать им окрестности. Это легко, и называется гостеприимством.', '2025-03-22 16:09:55', '2025-03-22 16:09:55', '2025-03-22 16:09:55', 'no', '', 5, NULL, 519603),
	('home.title.onestep.sub', 'uk', 'messages', 'Ми віримо, що ділитися чимось робить світ кращим. Ви можете дозволити людям залишитися у вас або показати їм околиці. Це просто і називається гостинністю.', '2026-04-03 17:51:20', '2026-04-03 17:51:20', '2026-04-03 17:51:20', 'no', '', 5, NULL, 573491),
	('home.title.onestep.sub', 'zh-hant', 'messages', '我們相信，分享打造更美好的世界，從提供住宿給旅人或帶他們參觀，這很簡單，也是稱為款待（Hospitality）。', '2023-10-24 20:47:44', '2023-10-24 20:47:44', '2023-10-24 20:47:44', 'no', '', 5, NULL, 53422),
	('home.username', 'ca', 'messages', 'Tria el nom d\'usuari!', '2021-10-05 13:34:59', '2021-10-05 13:34:59', '2021-10-05 13:34:59', 'no', '', 5, NULL, 304193),
