	('home.username.subheader', 'en', 'messages', 'and start meeting people from everywhere.', '2019-01-25 19:35:11', '2019-01-25 19:35:11', '0000-00-00 00:00:00', 'no', 'Text after the invitation \'Choose your username!\'', 5, NULL, 1),
	('home.username.subheader', 'eo', 'messages', 'kaj komencu renkonti homojn de ĉie.', '2020-10-29 15:37:35', '2020-10-29 15:37:35', '2020-10-29 15:37:35', 'no', '', 5, NULL, 47526),
	('home.username.subheader', 'es', 'messages', 'y empieza a conocer personas de todo el mundo.', '2020-11-30 17:41:23', '2020-11-30 17:41:23', '2020-11-30 17:41:23', 'no', '', 5, NULL, 25548),
	('home.username.subheader', 'fr', 'messages', 'pour rencontrer des voyageurs du monde entier.', '2019-02-19 12:35:20', '2019-02-19 12:35:20', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('home.username.subheader', 'gl', 'messages', 'E comeza a achegarte a xente de calquera lugar.', '2021-01-21 11:02:23', '2021-01-21 11:02:23', '2021-01-21 11:02:23', 'no', '', 5, NULL, 210880),
	('home.username.subheader', 'hu', 'messages', '...és nyiss a világ felé!', '2020-06-05 07:52:46', '2020-06-05 07:52:46', '2020-06-05 07:52:46', 'no', '', 5, NULL, 36939),
	('home.username.subheader', 'hy', 'messages', 'և սկսի՛ր ծանոթանալ տարբեր տեղերից մարդկանց հետ:', '2025-04-08 18:49:13', '2025-04-08 18:49:13', '2025-04-08 18:49:13', 'no', '', 5, NULL, 519603),
	('home.username.subheader', 'it', 'messages', 'e inizia a incontrare persone che provengono da tutte le parti del mondo.', '2020-05-25 21:53:01', '2020-05-25 21:53:01', '2020-05-25 21:53:01', 'no', '', 5, NULL, 261434),
	('home.username.subheader', 'nl', 'messages', 'en ontmoet mensen van over de hele wereld.', '2020-06-08 19:03:08', '2020-06-08 19:03:43', '2020-06-08 19:03:08', 'no', '', 5, NULL, 21169),
	('home.username.subheader', 'pl', 'messages', 'i zacznij spotykać ludzi z całego świata.', '2021-01-13 23:23:45', '2021-01-13 23:23:45', '2021-01-13 23:23:45', 'no', '', 5, NULL, 116789),
	('home.username.subheader', 'pt', 'messages', 'e comece a conhecer pessoas de todo o lado.', '2019-02-07 14:52:28', '2019-02-07 14:52:28', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('home.username.subheader', 'ru', 'messages', 'и начните знакомиться с людьми отовсюду.', '2025-03-22 17:49:29', '2025-03-22 17:49:29', '2025-03-22 17:49:29', 'no', '', 5, NULL, 519603),
