	('iamawareofspamcheckingrules', 'en', 'messages', 'I confirm that I have read the <a target="new" href="http://www.bevolunteer.org/wiki/index.php/Spam_Info_Page">information about spam</a> and agree with it.', '2007-08-23 19:09:30', '2019-04-23 18:16:49', '2010-04-18 20:53:39', 'no', 'This is the text beside the check box a member as to tick before sending a message to another member', 5, 1, 101),
