	('iamawareofspamcheckingrules', 'es', 'messages', 'Confirmo que he leído la <a target="new" href="http://www.bevolunteer.org/wiki/index.php/Spam_Info_Page">Información sobre Spam</a> y la acepto.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 554),
	('iamawareofspamcheckingrules', 'fi', 'messages', 'Vakuutan, että olen lukenut roskapostin tarkistukseen liittyvät säännöt (jos vastaanottaja niin haluaa tai jos automaattinen roskapostin tarkistus viestin merkitsee, vapaaehtoistyöntekijä saattaa tarkastaa lähettämäni viestin).', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 72),
	('iamawareofspamcheckingrules', 'fr', 'messages', 'Je confirme avoir lu et approuvé les règles anti-spam. \r\n(<a target="new" href="http://www.bevolunteer.org/wiki/index.php/Spam_Info_Page">En savoir plus…</a>)', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 9823),
