	('indexpagespecial', 'de', 'messages', 'Wir haben gelernt, uns getroffen und uns ausgetauscht - bei der Helfer Konferenz in Antwerpen, Belgien 18-20 Januar!', '2008-03-01 23:05:40', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 3050),
	('indexpagespecial', 'en', 'messages', 'We learned, we met, we shared - at the volunteers conference in Antwerp, Belgium, 18-20 January!', '2008-01-15 19:14:36', '2019-04-23 18:16:49', '2008-01-22 00:04:39', 'no', 'Special title on the teaser of the startpage - this will change always again when there\'s a new event we want to tell our visitors about.', 5, 1, 71),
