	('indexpagespecial', 'fr', 'messages', 'Nous avons appris, rencontré, partagé - à la conférence des volontaires, à Anvers (Belgique), du 18 au 20 Janvier !', '2008-01-16 23:05:40', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 452),
	('indexpagespecial', 'it', 'messages', 'Abbiamo imparato tante cose, ci siamo incontrati, abbiamo condiviso tante cose  -  alla conferenza ddei volontari ad Anversa, Belgio, 18-20 gennaio!', '2008-04-13 11:16:45', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
