	('indexpageword_plan', 'zh-hant', 'messages', '让你旅行更精彩', '2010-02-20 11:31:51', '2021-05-02 07:48:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 9518),
	('indexpageword_plantext', 'ar', 'messages', 'دع الآخرين يعرفون بأنك ستمر من عندهم. خطط لرحلتك و انضم للفعاليات و النشاطات المحلية', '2009-03-09 23:14:07', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 7013),
	('indexpageword_plantext', 'ca', 'messages', 'Fes saber als altres per on passaràs. Planifica el viatge i uneix-te a activitats locals!', '2008-09-07 12:40:57', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('indexpageword_plantext', 'cs', 'messages', 'Dej ostatním vědět, že projíždíš. Naplánuj svou cestu a zapoj se do místního dění a aktivit.', '2013-01-04 13:36:51', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 33091),
	('indexpageword_plantext', 'da', 'messages', 'Lad andre vide når du kommer forbi. Planlæg din tur og tag del i lokale aktiviteter!', '2009-01-03 14:49:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 74),
	('indexpageword_plantext', 'de', 'messages', 'Lass andere wissen, wann du vorbeikommst. Plane deine Reise und nimm an Aktivitäten vor Ort teil! ', '2008-09-01 16:35:32', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('indexpageword_plantext', 'el', 'messages', 'Ενημέρωσε τους άλλους για το πότε θα περάσεις από το μέρος τους. Σχεδίασε το ταξίδι σου και λάβε μέρος σε τοπικές δραστηριότητες!', '2013-10-05 11:55:49', '2020-08-25 16:35:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('indexpageword_plantext', 'en', 'messages', 'Let others know when you\'re passing by. Plan your trip and join local activities!', '2008-08-27 17:46:26', '2019-04-23 18:16:49', '2008-08-29 13:03:54', 'no', 'text under subtitle on startpage', 2, NULL, 97),
	('indexpageword_plantext', 'eo', 'messages', 'Sciigu aliajn ke vi alvenas. Planu vian vojaĝon kaj partoprenu en lokaj eventoj!', '2008-09-09 08:01:05', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 47220),
	('indexpageword_plantext', 'es', 'messages', 'Informar otros cuando estas paseando en sus regiones. Planear tu viaje y reunate a actividades locales!', '2008-09-13 21:12:37', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 135),
	('indexpageword_plantext', 'eu', 'messages', 'Jakinarazi itzazu beste kideak noiz egongo zaren non. Bidaia antolatu eta parte hartu tokiz tokiko ekitaldietan!', '2012-11-30 19:02:35', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11907),
	('indexpageword_plantext', 'fa', 'messages', 'بگذارید دیگران بدانند چه وقت از آنجا عبور میکنید. برنامه سفر خود را بریزید و در رویدادهای محلی شرکت کنید', '2012-08-26 17:12:42', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11950),
	('indexpageword_plantext', 'fi', 'messages', 'Anna muidenkin tietää, että olet käymässä. Suunnittele matkaasi ja liity mukaan paikalliseen toimintaan.', '2009-06-21 09:36:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 525),
	('indexpageword_plantext', 'fr', 'messages', 'Faites savoir quand vous bougez. Planifiez vos voyages et participez aux activités locales&nbsp;!', '2008-08-28 09:13:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 9823),
	('indexpageword_plantext', 'gl', 'messages', 'Deixa que outras persoas saiban onde vas pasar. Planea a túa viaxe e únete ás actividades locais!', '2021-12-07 09:18:50', '2021-12-07 09:18:50', '2021-12-07 09:18:50', 'no', '', 5, NULL, 210880),
	('indexpageword_plantext', 'hr', 'messages', 'Javi ostalima da ćeš im biti u blizini. Planiraj svoje putovanje i sudjeluj u lokalnim aktivnostima!', '2009-09-01 21:02:13', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('indexpageword_plantext', 'hu', 'messages', 'Tudasd a többiekkel mikor nem vagy otthon. Tervezd meg a túrád és vegyél részt a helyi programokban!', '2009-05-06 06:46:44', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 6582),
	('indexpageword_plantext', 'hy', 'messages', 'Այլոց հաղորդեք, թե երբ եք անցնելու իրենց մոտով: Պլանավորեք ձեր ուղևորությունները և միացեք տեղական միջոցառումներին!', '2013-06-24 22:33:43', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 22128),
	('indexpageword_plantext', 'it', 'messages', 'Fai sapere agli altri quando passerai. Pianifica il tuo viaggio e unisciti alle attività locali!', '2008-09-28 17:54:30', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 103),
	('indexpageword_plantext', 'lt', 'messages', 'Leisk kitiems žinoti, kada busi netoliese. Planuok savo kelionę ir prisijunk prie vietinių įvykių! ', '2009-08-09 13:44:18', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('indexpageword_plantext', 'ms', 'messages', 'Biarkan orang lain tahu apabila anda melalui. Merancang perjalanan anda dan menyertai aktiviti-aktiviti tempatan!', '2013-01-15 04:16:56', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 26658),
	('indexpageword_plantext', 'nl', 'messages', 'Laat anderen weten dat je op doortocht bent. Plan je reis en neem deel aan plaatselijke activiteiten!', '2008-09-12 08:28:52', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 69),
	('indexpageword_plantext', 'pl', 'messages', 'Powiadom innych, kiedy będziesz w okolicy. Zaplanuj swoją podróż i włącz się w lokalne wydarzenia!', '2012-12-17 01:35:10', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 35248),
	('indexpageword_plantext', 'pt', 'messages', 'Deixe os outros saberem quando você está passando. Planeje sua viagem e participar de atividades locais!', '2009-09-01 11:02:53', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 9030),
	('indexpageword_plantext', 'pt-BR', 'messages', 'Avise quando você estiver por perto. Planeje sua viagem e fique por dentro do que rola na cidade!', '2010-01-25 14:10:24', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 9607),
	('indexpageword_plantext', 'ru', 'messages', 'Расскажите другим, что будете в их краях - планируйте свой маршрут и участвуйте в местных событиях!', '2009-03-09 12:16:14', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 79),
	('indexpageword_plantext', 'sk', 'messages', 'Daj ostatným vedieť, keď pôjdeš okolo. Naplánuj si cestu a zúčastni sa miestnych aktivít!', '2013-03-25 12:22:19', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48253),
	('indexpageword_plantext', 'sr', 'messages', 'Нека други знају кад пролазиш кроз њихово место. Испланирај своје путовање и придружи се локалним активностима!', '2013-01-16 17:32:38', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 60746),
	('indexpageword_plantext', 'sv', 'messages', 'Låt andra veta när du passerar. Planera din tur och ta del i lokal aktiviteter!', '2012-03-15 15:41:11', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 23263),
