	('indexpageword_sharetext', 'sk', 'messages', 'Zdieľaj svoj príbytok s cestovateľom, alebo si nájdi ubytovanie pre seba.', '2013-03-25 12:19:26', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48253),
