	('indexpageword_sharetext', 'zh-hans', 'messages', '为驴子打开家门, 或到别人家去看看!', '2010-02-20 11:45:44', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37722),
