	('indexpageword1', 'bg', 'messages', 'Писнало ли ти е да откриваш нови хоризонти пред телевизора?', '2007-07-05 22:48:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 851),
	('indexpageword1', 'ca', 'messages', 'En tens prou de conèixer el món a través de la tele?', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 177),
	('indexpageword1', 'da', 'messages', 'Er du træt af kun at opdage nye horisonter gennem dit fjernsyn?', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 74),
	('indexpageword1', 'de', 'messages', 'Bist du es leid, neue Horizonte nur vor deinem Fernseher zu entdecken?', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 15240),
	('indexpageword1', 'en', 'messages', 'Are you tired of only discovering new horizons  from behind a TV screen?', '2008-04-11 17:20:08', '2019-04-23 18:16:49', '2008-04-13 16:16:26', 'no', 'this is one of the words on the index page.', 5, 1, 97),
	('indexpageword1', 'eo', 'messages', 'Ĉu vi lacas de malkovri novaĵojn nur per televidilo?', '2007-09-11 20:13:27', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1769),
	('indexpageword1', 'es', 'messages', '¿Estás cansado de descubrir nuevos horizontes en frente de la TV?', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1328),
	('indexpageword1', 'fi', 'messages', 'Oletko kyllästynyt tutustumaan uusin horisontteihin vain TV:n välityksellä?', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 72),
	('indexpageword1', 'fr', 'messages', 'En avez vous assez de ne découvrir de nouveaux horizons qu\'à la télévision ?', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 67),
	('indexpageword1', 'hr', 'messages', 'Je li te već umorilo otkrivanje novih horizonata preko TV ekrana?', '2009-09-19 14:37:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 8197),
	('indexpageword1', 'hu', 'messages', 'Többre vágysz a tévé előtt szerzett utazási élményeknél?', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 468),
	('indexpageword1', 'id', 'messages', 'Anda capek meluaskan wawasan hanya lewat televisi?', '2007-11-05 17:40:36', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 2019),
	('indexpageword1', 'it', 'messages', 'Sei stanco di conoscere nuovi orrizonti solo stando davanti al tuo televisore?', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
	('indexpageword1', 'lt', 'messages', 'Pavargai atradinėti naujus horizontus sėdėdamas priešais televizorių?', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 227),
	('indexpageword1', 'lv', 'messages', 'Tev ir apnicis atklāt jaunus apvāršņus tikai pie sava televizora?', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 375),
	('indexpageword1', 'nl', 'messages', 'Ben je het zat om de wereld van achter je TV te bekijken?', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 138),
	('indexpageword1', 'pl', 'messages', 'Jesteś już zmęczony poszerzaniem swoich horyzontów tylko przed telewizorem?', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 213),
	('indexpageword1', 'pt', 'messages', 'Está farto de apenas descobrir novos horizontes em frente à sua TV?', '2007-07-09 20:11:45', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 752),
	('indexpageword1', 'pt-BR', 'messages', 'Você está cansado de descobrir novos horizontes apenas em frente à sua TV?', '2007-08-07 13:05:39', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, 1, 144),
	('indexpageword1', 'ro', 'messages', 'Te-ai săturat să descoperi noi orizonturi doar din faţa televizorului?', '2007-08-30 17:54:41', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1081),
	('indexpageword1', 'ru', 'messages', 'Вам надоело открывать мир только через экран телевизора? ', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 79),
	('indexpageword1', 'sr', 'messages', 'Да ли ти је досадило да откриваш нове хоризонте само преко ТВ-а?', '2013-08-24 21:18:56', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 39772),
	('indexpageword1', 'tr', 'messages', 'Yeni ufukları keşfetmek için sadece TV karşısında oturmaktan yoruldunuz mu? ', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 95),
	('indexpageword10', 'bg', 'messages', 'Можеш да предложиш своя дом, колкото и да е малък да е той. Членовете на BeWelcome са приспособими: за повечето от тях не е проблем да спят на матрак, канапе или дори на пода. Докосни се до други пътешественици и открий света на взаимното гостоприемство!', '2007-07-05 22:52:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 851),
	('indexpageword10', 'ca', 'messages', 'Si tens un lloc, pots oferir-lo a algú altre! Tant si és un llit, un matalàs o un trosset de terra, pots ajudar altres persones mentre viatgen!', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 177),
	('indexpageword10', 'cs', 'messages', 'Je zcela na tobě, zda chceš nabídnout místo pro přespaní ostatním členům. Stačí matrace, pohovka, malý prostor v koutku na zemi nebo i místo pro stan na tvojí zahradě! Členové BeWelcome jsou plně flexibilní a vystačí si i se studenou zemí nebo travnatým paloučkem. Uvítej další cestovatele a objev svět vzájemné pohostinnosti!', '2008-07-30 17:07:57', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 34292),
	('indexpageword10', 'da', 'messages', 'Har du plads tilovers kan du tilbyde at have nogen på besøg hos dig. Om det er en seng, en madras eller bare lidt gulvplads er ligegyldigt - du kan let hjælpe andre på rejse.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 74),
	('indexpageword10', 'de', 'messages', 'Du kannst Gästen einen Platz in deinem Zuhause anbieten, egal wie klein er auch sein mag? Die Mitglieder von BeWelcome sind flexibel: Die meisten sind bereit auf einer Matratze, einem Sofa oder sogar auf dem Fußboden zu schalfen. Reiche den Reisenden dieser Welt deine Hand und entdecke die Welt der Gastfreundschaft.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 3050),
	('indexpageword10', 'en', 'messages', 'You can offer to share your home no matter how small it may be. BeWelcome members are flexible: most are willing to sleep on a mattress, a couch or even the floor.  Reach out to other travellers and discover the world of hospitality exchange! ', '2007-08-23 10:42:18', '2019-04-23 18:16:49', '2008-08-17 14:14:20', 'no', 'this is one of the words on the index page.', 5, 1, 101),
	('indexpageword10', 'eo', 'messages', 'Eĉ se estas nek grandas nek grandiozas, vi povas oferti gastigi en vian hejmon. Membroj de BeWelcome flekseblas: la plejparto pretas dormi sur matraco, sofo aŭ eĉ planko. Ekkontaktiĝu kun aliaj vojaĝantoj kaj malkovru tutan mondon de intergastiĝaj ebloj!', '2007-09-12 00:10:38', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1769),
	('indexpageword10', 'es', 'messages', 'Si tienes algun espacio libre, puedes ofrecer alojar a alguien en tu casa. No importa si es una cama, un colchon o espacio en el suelo - puedes ayudar facilmente a otros en sus viajes. Descubre el mundo del <b>intercambio<b> de <b>hospitalitad</b>! <font color=white>esto se llama hospitality exchange</font>', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('indexpageword10', 'fi', 'messages', 'Jos sinulla on vähän tyhjää tilaa, voit tarjoutua majoittamaan jonkun kotonasi. Ei ole väliä onko sinulla lisävuode, -patja tai pelkästään tilaa lattialla - voit helposti auttaa muita heidän matkoillaan.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 72),
	('indexpageword10', 'fr', 'messages', 'Si vous avez un peu d\'espace libre, vous pouvez offrir d\'héberger quelqu\'un chez vous. Que ce soit un lit, un matelas ou quelques mètres carrés de carrelage - vous pouvez aider les autres simplement, et découvrir le monde de l\'échange d\'hospitalité.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 757),
	('indexpageword10', 'hr', 'messages', 'Svoj dom možeš ponuditi bez obzira na njegovu veličinu. Članovi BeWelcomea su fleksibilni - većina će pristati na madrac, kauč pa čak i pod. Pomozi ostalim putnicima i uđi u svijet razmjene gostoprimstava!', '2010-03-22 14:20:36', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 8197),
	('indexpageword10', 'hu', 'messages', 'Ha van egy kis hely a lakásodban, elszállásolhatsz valakit. Mindegy, hogy az egy ágy,matrac vagy csak a padló-a lényeg, hogy könnyűszerrel segíthetsz másoknak utazásuk alatt. Ismerd meg a kölcsönös vendégfogadás világát <font color=white>ezt nevezik kölcsönös vendégfogadásnak</font>', '2007-07-27 18:47:33', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 805),
	('indexpageword10', 'id', 'messages', 'Cobalah untuk membuka rumah anda bagi para petualang, sekecil apapun luasnya. Anggota BeWelcome bersedia tidur diatas dipan sekalipun, sofa, bahkan dilantai. Melalui tangan terbuka anda, anda dapat menemui cakrawala baru dalam bersilahturahmi dengan banyak orang di dunia.', '2007-11-05 17:45:55', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 2019),
	('indexpageword10', 'it', 'messages', 'Puoi offire di dividere la tua casa, non importa quanto sia piccola. I membri di BeWelcome sono flessibili: molti sono disposti a dormire su un materasso, un divano o anche sul pavimento. Raggiungi altri viaggiatori e scopri il mondo dello scambio d\'ospitalità! ', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
	('indexpageword10', 'ja', 'messages', '狭くても大丈夫です。BeWelcomeのメンバーたちの中には柔軟な方が多いので、ベッド、布団、ソファ、畳、床など、どこにでも構わず寝ちゃいます。さあ、あなたも旅人たちに手を差し伸べてホスピタリティ交換の世界にのめり込もう!', '2007-11-09 11:29:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1834),
	('indexpageword10', 'lt', 'messages', 'Jei turite nors truputį vietos savo namuose, galite pasisiūlyti priimti keliautojus. Ne taip jau ir svarbu, ar tai yra patogi lova, ar čiužinys, ar kušetė, ar tiesiog šiek tiek vietos ant grindų - BeWelcome nariai yra lankstūs. Užmegzkite ryšius su kitais keliautojais ir atraskite apsikeitimo svetingumu pasaulį! ', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 227),
	('indexpageword10', 'lv', 'messages', 'Tu vari piedāvāt dalīties ar savu mājasvietu, lai vai cik tā būtu maza. BeWelcome biedri ir fleksibli: lielākā daļa ir ar mieru gulēt uz matrača, dīvāna vai pat grīdas. Saskaries ar citiem ceļotājiem un atklāj hospitality apmaiņas pasauli!', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 375),
	('indexpageword10', 'nl', 'messages', 'Wanneer je wat ruimte over hebt, als je iemand een slaapplaats kunt bieden in je huis. Het maakt niet uit of het een bed, een matras, of gewoon een plekje op de vloer is - je kunt anderen gemakkelijk helpen op hun reizen!', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 138),
	('indexpageword10', 'pl', 'messages', 'Jeśli masz trochę wolnego miejsca, możesz kogoś ugościć u siebie. Nie ważne czy to łóżko, materac czy tylko miejsce na podłodze - bardzo łatwo możesz pomóc komuś innemu w podróży. ', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 213),
	('indexpageword10', 'pt', 'messages', 'Pode oferecer-se para partilhar a sua casa, não interessa o seu tamanho. Os membros do BeWelcome são flexíveis: muitos estão dispostos a dormir num colchão, num sofá ou mesmo no chão. Contacte outros viajantes e descubra o mundo da troca de hospitalidade!', '2012-12-27 19:19:48', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 38787),
	('indexpageword10', 'pt-BR', 'messages', 'Se você tem algum espaço livre, você pode oferecê-lo para hospedar alguém em sua casa. Não importa se é uma cama, um colchão ou apenas um espaço no chão, você pode ajudar outros a viajarem de uma forma mais fácil. Descubra o mundo da troca de hospidalidade! <font color=white>isto é chamado de troca de hospitalidade</font>', '2007-08-07 13:31:45', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, 1, 144),
	('indexpageword10', 'ro', 'messages', 'Îţi poţi oferi casa indiferent cât de mică este. Membrii BeWelcome sunt flexibili: majoritatea sunt dispuşi să doarmă pe o saltea, o canapea sau chiar pe podea. Deschide-te călătorilor şi descoperă lumea schimbului de ospitalitate!', '2007-08-30 18:31:04', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1081),
	('indexpageword10', 'ru', 'messages', 'Если у вас есть немного места, вы можете дать другим людям возможность переночевать у вас. Неважно, можете ли вы предложить кровать, матрас или место на полу - вы легко можете помочь другим путешествовать. Встречайтесь с другими путешественниками и открывайте мир обмена гостеприимством!', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 79),
	('indexpageword10', 'tr', 'messages', 'Biraz boş yeriniz varsa, birilerini konuk edebilirsiniz. Yatak olmasa bile, kanepe veya yerde boş bir yer vererek, konuğunuzun seyahatini kolaylaştırmış ve yardımcı olmuş olursunuz.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 140),
	('indexpageword11', 'bg', 'messages', 'Докосни се до други култури', '2007-07-05 22:47:07', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 851),
	('indexpageword11', 'ca', 'messages', 'Entra en contacte amb altres cultures', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 177),
