	('indexpageword11', 'de', 'messages', 'Lerne andere Kulturen kennen', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 3050),
	('indexpageword11', 'en', 'messages', 'Get in touch with other cultures', '2008-04-13 16:15:10', '2019-04-23 18:16:49', '2008-04-13 16:16:26', 'no', 'this is one of the words on the index page.', 5, 1, 1),
