	('indexpageword15', 'pt-BR', 'messages', 'Seu <i>feedback</i> é necessário', '2007-08-07 13:26:45', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, 1, 144),
	('indexpageword15', 'ro', 'messages', 'Feedback-ul tău ne este de folos', '2007-08-30 17:53:35', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1081),
	('indexpageword15', 'ru', 'messages', 'Ваше мнение очень важно для нас', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 79),
	('indexpageword15', 'tr', 'messages', 'Geribildirimlerinizi bekliyoruz', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 140),
	('indexpageword16', 'bg', 'messages', 'Би искал да знаеш повече за взаимното гостоприемство? Помогни ни да подобрим сайта. Твоите коментари и предложения са добре дошли! \r\n<a href="feedback.php">Пиши ни!</a>', '2007-07-05 23:04:27', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 851),
	('indexpageword16', 'ca', 'messages', 'Qualsevol comentari o suggerència seran benvinguts! Ajuda\'ns a millorar el lloc web :-)\r\n \r\n<a href="feedback.php">Contacta amb nosaltres</a>', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 177),
	('indexpageword16', 'cs', 'messages', 'Chceš vědět více o vzájemné pohostinnosti? Pomoz nám vylepšit stránku. Tvoje zpětná vazba a návrhy jsou vítány: <a href="feedback.php">kontaktuj nás</a>! ', '2013-10-17 21:34:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 34292),
	('indexpageword16', 'da', 'messages', 'Din feedback og dine ideer er velkomne! Hjælp os med at forbedre siderne :-)\r\n<a href="feedback.php">Kontakt os</a>', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 74),
	('indexpageword16', 'de', 'messages', 'Du willst mehr über Hospitality Exchange wissen? \r\nHilf uns die Webseite zu verbessern.\r\nFür Anregungen und Kritik sind wir immer dankbar! Erzähl uns, wie wir die Website weiter verbessern können! <a href="feedback.php">Schreib uns eine Nachricht!</a>', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 76),
	('indexpageword16', 'en', 'messages', 'Want to know more about hospitality exchange? Help us improve the site. Your feedback and suggestions are welcome: <a href="feedback.php">contact us</a>!', '2008-03-05 17:42:16', '2019-04-23 18:16:49', '2008-04-13 16:16:26', 'no', 'this is one of the words on the index page.', 5, 1, 125),
	('indexpageword16', 'eo', 'messages', 'Ĉu vi volas plu eklerni pri intergastiĝo? Bonvole helpu nin plibonigi la retpaĝaron per opinio kaj sugestoj. <a href="feedback.php">Kontaktu nin</a>, ni petas!', '2007-09-12 00:18:55', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1769),
	('indexpageword16', 'es', 'messages', '¿Quieres saber más sobre intercambio de hospitalidad? Tus comentarios y sugerencias son bienvenidos ¡<a href="feedback.php">Contáctanos</a>!', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1328),
	('indexpageword16', 'fi', 'messages', 'Palautteesi ja ehdotuksesi ovat tervetulleita! Auta meitä parantamaan sivustoa :-)\r\n<a href="feedback.php">Ota yhteyttä</a>', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 72),
	('indexpageword16', 'fr', 'messages', 'Vos avis et suggestions sont les bienvenus ! Aidez-nous à améliorer le site et à faire vivre ce projet d\'échange d\'hospitalité :-) : <a href="feedback.php">Contactez nous</a>', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 452),
	('indexpageword16', 'hr', 'messages', 'Želiš naučiti više o razmjeni gostoprimstva? Pomozi nam poboljšati ove stranice. Tvoja povratna informacija i prijedlozi više su nego dobrodošli: <a href="feedback.php">piši nam</a>! ', '2010-03-22 14:26:08', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 8197),
	('indexpageword16', 'hu', 'messages', 'Szeretnél többet megtudni a hospitalexchangeről? Visszajelzéseidet és javaslataidat szeretettel várjuk! Segíts nekünk fejleszteni az oldalt :-) \r\n<a href="feedback.php">Kapcsolatfelvétel</a>', '2007-07-27 12:27:58', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 805),
	('indexpageword16', 'id', 'messages', 'Ingin tahu lebih banyak tentang pertukaran silahturahmi? Bantu kami untuk memperindah halaman ini. Tanggapan dan saran anda sangat kami hargai!<br><a href="feedback.php"> Hubungi kami</a>', '2007-11-05 18:11:40', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 2019),
	('indexpageword16', 'it', 'messages', 'Vuoi sapere di più sullo <b>scambio d\'ospitalità</b>?  Aiutaci a miglioare il sito:-)\r\nl tuo feedback e i tuoi suggerimenti sono graditi! <a href="feedback.php">Contattaci</a>', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
	('indexpageword16', 'lt', 'messages', 'Norite sužinoti daugiau apie <b>apsikeitimą svetingumu</b>? Padėkite mums patobulinti svetainę! Laukiame jūsų pastebėjimų bei pasiūlymų: <a href="feedback.php">susisiekite su mumis</a>!', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 227),
	('indexpageword16', 'lv', 'messages', 'Tu vēlies vairāk uzzināt par <b>hospitalityexchange</b>? Palīdzi mums uzlabot šo lapu. Tavi komentāri un ieteikumi ir laipni gaidīti!  \r\n<a href="feedback.php">Sazinies ar mums</a>', '2007-08-10 11:55:42', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 375),
	('indexpageword16', 'nl', 'messages', 'Je feedback en suggesties zijn welkom! Help ons de site te verbeteren :-)\r\n<a href="feedback.php">Contacteer ons</a>', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 138),
	('indexpageword16', 'pl', 'messages', 'Twoje uwagi i sugestie są bardzo mile widziane! Pomóż nam usprawnić tę strone :-)\r\n<a href="feedback.php">Contact us</a>', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 213),
	('indexpageword16', 'pt', 'messages', 'Quer saber mais sobre troca de hospitalidade? Ajude-nos a melhorar o website. A sua opinião e sugestões são bem-vindas: <a href="feedback.php">contacte-nos</a>!', '2013-01-06 23:27:15', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 38787),
