	('inviteafriend', 'sk', 'messages', 'Pozvi si priateľa!', '2013-03-23 23:49:45', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48253),
	('inviteafriend', 'sr', 'messages', 'Позови пријатеља!', '2012-12-18 14:00:05', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('inviteafriend', 'sv', 'messages', 'Bjuda in en vän!', '2012-03-24 21:22:51', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 23263),
	('inviteafriend', 'tr', 'messages', 'Bir arkadaş davet et!', '2012-11-29 14:15:34', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 35699),
	('inviteafriend', 'zh-hans', 'messages', '邀请朋友', '2010-02-20 09:06:13', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 9518),
	('inviteafriend', 'zh-hant', 'messages', '邀請朋友', '2010-02-20 09:06:13', '2021-05-02 07:48:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 68078),
	('inviteafriendinfo', 'ar', 'messages', 'هل يعجبكم "بي ويلكم"؟ تعتقدون أنه مشروع جيد؟ يمكن أن يعجب أصدقاءكم به أيضاً! يمكنكم <a href="/invite" title="إرسال دعوة لأحدهم">أرسلوا لهم دعوة بريدية</a>, مع شرح بسيط عن الالموقع ورابط عن ملفكم الشخصي - كما يمكنكم تعديل الرسالة كما ترونها مناسبة. ', '2013-06-27 06:54:39', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48937),
	('inviteafriendinfo', 'ca', 'messages', 'T\'agrada BeWelcome? Creus que és un bon projecte? Potser a algunes de les teves amistats també els hi agradarà! Pots <a href="/invite" tPtle="enviar una invitació a BeWelcome a algú qui coneixes">. Envia\'ls un correu convidant-los-hi, amb una breu descripció del web i un enllaç al teu perfil o personalitzant el correu tant com vulguis.', '2011-09-02 23:46:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 12861),
	('inviteafriendinfo', 'cs', 'messages', 'Máš rád(a) BeWelcome? Myslíš, že je to dobrý projekt? Možná si ho někteří tví kamarádi také oblíbí! Můžeš <a href="/invite" title="Poslat pozvánku na BeWelcome někomu, koho znáš">jim e-mailem poslat pozvánku na BeWelcome</a> s krátkým popisem stránek a odkazem na tvůj profil -- nebo můžeš upravit email tak, jak uznáš za vhodné.', '2013-10-17 20:00:10', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('inviteafriendinfo', 'de', 'messages', 'Gefällt dir BeWelcome? Du glaubst es ist ein gutes Projekt? Vielleicht könnte es einigen deiner Freunde auch gefallen! Du kannst sie <a href="/invite" title="Lade deine Freunde per E-Mail ein">direkt per E-Mail einladen</a> mit einer kurzen Beschreibung der Seite und einem Link zu deinem Profil. Selbstverständlich kannst du die E-Mail auch nach deinen Wünschen anpassen.', '2010-05-15 10:39:27', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 347),
	('inviteafriendinfo', 'el', 'messages', 'Σ\'αρέσει το BeWelcome; Το θεωρείς καλή ιδέα; Ίσως να αρέσει και σε μερικούς φίλους σου! Μπορείς να <a href="/invite" title="Send someone you know an invite to BeWelcome"> τους στείλεις με e-mail μία πρόσκληση για το BeWelcome</a>, με μια σύντομη περιγραφή της σελίδας κι έναν σύνδεσμο προς το προφίλ σου, ή μπορείς να προσαρμόσεις το e-mail όπως σ\'αρέσει.', '2012-10-08 18:49:37', '2020-08-24 19:28:07', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('inviteafriendinfo', 'en', 'messages', 'Do you like BeWelcome? Think it\'s a good project? Perhaps some of your friends might like it too! You can <a href="/invite" title="Send someone you know an invite to BeWelcome">send them an invitation email to BeWelcome</a>, with a quick description of the site and a link to your profile on it - or you can customise the email as you see fit.', '2010-01-23 20:40:47', '2019-04-23 18:16:49', '2010-04-17 17:03:39', 'no', 'Brief description on front page about the Invite A Friend option', 5, NULL, 101),
	('inviteafriendinfo', 'eo', 'messages', 'Ĉu vi ĝuas BeWelcome? Konsideras ĝin utilan? Verŝajne ĝi povas same plaĉi ankaŭ al viaj amikoj! Nun vi povas <a href="/invite" title="Sendu inviton al BeWelcome al viaj geamikoj"> inviti ilin aliĝi al la komunumo BeWelcome</a>, liverante mallongan priskribon de la retejo kaj direktan ligilon al via profilo!', '2013-03-13 19:04:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 47220),
	('inviteafriendinfo', 'es', 'messages', '¿Te gusta BeWelcome? ¿Piensas que es un buen proyecto? ¡Tal vez también le guste a algunos de tus amigos! Puedes <a href="/invite" title="Enviar a un amigo una invitación a BeWelcome">enviar un correo de invitación a BeWelcome</a>, con una breve descripción del sitio y un enlace a tu perfil, o puedes personalizar el correo como lo creas más conveniente.', '2010-09-03 12:01:54', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37864),
	('inviteafriendinfo', 'eu', 'messages', 'Gustoko al duzu BeWelcome? Projektu ona dela uste duzu? Agian zure lagun batzuei ere gustatuko zaie! <a href="/invite" title="Send someone you know an invite to BeWelcome">BeWelcome-ko gonbidapen mezua bidali diezaiekezu</a>, webgunearen deskribapenarekin eta zure profilerako esteka batekin. Edota mezua zeure gustora pertsonalizatu dezakezu.', '2013-01-05 13:32:26', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11907),
	('inviteafriendinfo', 'fi', 'messages', 'Pidätkö BeWelcomesta? Ehkä ystäväsi saattaisivat myös tykätä siitä! Voit <a href="/invite" title="Lähetä ystävällesi kutsu BeWelcomeen">lähettää heille kutsun sähköpostitse BeWelcomeen</a> valmiilla kutsutekstillä ja linkillä profiiliisi, tai muokata viestiä sellaiseksi kuin itse haluat.', '2010-07-18 12:45:18', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8268),
	('inviteafriendinfo', 'fr', 'messages', 'Vous aimez BeWelcome ? Vos ami⋅e⋅s pourraient être intéressé⋅e⋅s&nbsp;? <a href="/invite" title="envoyer une invitation à rejoindre BeWelcome à l’une vos connaissances">Envoyez-leur une invitation</a>, avec une description du projet et un lien vers votre profil, ou bien rédigez un message personnalisé.', '2010-01-31 19:45:22', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('inviteafriendinfo', 'gl', 'messages', 'Gustas de BeWelcome? Pensas que é un bo proxecto? Quizais algunha amizade túa gustaría tamén del! Podes <a href="/invite" title="Send someone you know an invite to BeWelcome">enviar a alguén que coñezas unha invitación a BeWelcome</a>, con unha rápida descrición do sitio web e unha ligazón ao teu perfil nel, ou podes modificar o correo electrónico como creas necesario.', '2021-03-23 10:44:51', '2021-03-23 10:44:51', '2021-03-23 10:44:51', 'no', '', 5, NULL, 210880),
	('inviteafriendinfo', 'hu', 'messages', 'Szereted a BeWelcome-ot? Szerinted ez egy jó projekt? Talán néhány barátodnak is tetszene!  <a href="/invite" title="Send someone you know an invite to BeWelcome">Itt tudsz nekik küldeni </a> meghívót a BeWelcome-ra, amelyben található egy rövid leírás az oldalról, illetve egy link a profilodhoz. Ne feledd hogy lehetőséged van az üzenet testreszabására is.', '2012-09-23 21:00:20', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34314),
	('inviteafriendinfo', 'it', 'messages', 'Ti piace BeWelcome? Credi che sia un progetto valido? Magari potrebbe piacere anche a qualcuno dei tuoi amici! Puoi <a href="/invite" title="Send someone you know an invite to BeWelcome"> mandargli un messaggio di invito a BeWelcome via email</a>, contenente una descrizione veloce del sito e un link al tuo profilo - oppure puoi personalizzare il messaggio nella maniera che ti pare più adatta.', '2010-04-23 21:46:21', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 6002),
	('inviteafriendinfo', 'ku', 'messages', 'BeWelcome li xweşîya te hat? Belkî hin hevalên te jî li xweşîya wan wer e! Tu dikarî <a href="/invite" title="Send someone you know an invite to BeWelcome">ji wan re bangekê bişînî</a>, tê de: ji wan re li ser BeWelcome bi kurtayî binivsîne û girêka kurtjiyannameya xwe – an wek ku tu bixwazî ji wan re bişîne.', '2013-11-22 21:32:55', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48359),
	('inviteafriendinfo', 'lt', 'messages', 'Ar tau patinka BeWelcome? Manai, kad tai geras projektas? Galbūt kai kuriems tavo draugams taip pat patiks šis projektas! Gali <a href="/invite" title="Send someone you know an invite to BeWelcome">išsiųsti draugui pakvietimo į BeWelcome laišką</a> su trumpu svetainės aprašymu bei nuoroda į tavo profilį - arba gali parašyti laišką taip, kaip tau atrodo tinkamiausia.', '2011-08-15 18:06:04', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('inviteafriendinfo', 'nl', 'messages', 'Vind je BeWelcome wel wat?  Denk je dat het een goed project is?  Misschien vinden je vrienden dat ook wel!  Je kan <a href="/invite" title="Iemand die je kent een uitnodiging voor BeWelcome sturen">iemand een uitnodigingsmail voor BeWelcome sturen</a>, met een korte beschrijving van de site en een verwijzing naar jouw profiel – of een aangepaste mail, zoals jij hem wilt.', '2011-12-13 09:36:02', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('inviteafriendinfo', 'pl', 'messages', 'Lubisz BeWelcome? Uważasz, że to dobry projekt? Być może któremuś z Twoich znajomych również się spodoba! Możesz <a href="/invite" title="Send someone you know an invite to BeWelcome">wysłać im email z zaproszeniem do BeWelcome</a>, z krótkim opisem strony i linkiem do Twojego profilu - albo możesz edytować email w całości.', '2014-09-03 05:37:13', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 64183),
	('inviteafriendinfo', 'pt', 'messages', 'Gosta do BeWelcome? Acha que é um bom projeto? Talvez alguns dos seus amigos gostassem também! Pode <a href="/invite" title="Send someone you know an invite to BeWelcome">enviar-lhes um convite para o BeWelcome</a>, com uma descrição rápida do site e um ligação ao seu perfil - ou pode personalizar a mensagem como achar melhor.', '2012-12-09 09:03:28', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('inviteafriendinfo', 'pt-BR', 'messages', 'Você gosta do BeWelcome? Considera-o um bom projeto? Talvez alguns dos seus amigos gostem também! Você pode <a href="/invite" title="Enviar um convite do BeWelcome para um amigo">enviar um convite do BeWelcome para eles</a> com uma breve descrição do site e um link para o seu perfil - ou você pode personalizar a mensagem como achar melhor.', '2010-02-23 00:46:50', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15566),
	('inviteafriendinfo', 'ru', 'messages', 'BeWelcome отличный проект, правда? Мы тоже его любим.\r\nМожно <a href="/invite" title="Пригласить друзей">пригласить друзей</a>, чтобы <nobr>и они порадовались —</nobr> всегда радостно, когда хороших людей становится больше!\r\nВ письмо автоматически добавится ссылка на профиль, чтобы <nobr>никто не запутался, </nobr>а сам текст письма можно отредактировать <nobr>по своему желанию.</nobr>\r\nВ общем, приглашать друзей через сайт удобно. Вперед! ;)', '2011-04-26 21:37:15', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 13725),
	('inviteafriendinfo', 'sk', 'messages', 'Páči sa ti BeWelcome? Myslíš si, že to je dobrý projekt? Možno by sa mohol zapáčiť tiež niektorým z tvojich priateľov. Môžeš <a href="/invite" title="Poslať pozvánku na BeWelcome niekomu koho poznáš">im poslať pozývací e-mail na BeWelcome</a>, so stručným popisom stránky a odkazom na tvoj profil na nej - alebo si môžeš prispôsobiť e-mail ako si želáš.', '2013-03-25 19:06:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48253),
	('inviteafriendinfo', 'sr', 'messages', 'Свиђа ти се BeWelcome? Мислиш да је добар пројекат? Можда ће се допасти и твојим пријатељима! Можеш им послати <a href="/invite" title="Пошаљи позивницу за BeWelcome">позивницу</a>, са кратким описом сајта и линком ка твом профилу, или можеш прилагодити поруку како ти одговара.', '2012-12-22 10:39:45', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('inviteafriendinfo', 'tr', 'messages', 'BeWelcome\'dan hoşlandınız mı? Bunun iyi bir proje olduğunu mu düşünüyorsunuz? Belki arkadaşlarınızın bazıları da sevebilir!<a href="/davet et" title="Tanıdıklarınızı BeWelcome\'a davet edin">Onlara sitenin kısa bir tarifi ve profilinize bir bağlantıyla birlikte BeWelcome davetiyesi yollayın</a>,  - veya davetiyeyi istediğiniz gibi şekillendirin.', '2012-11-29 23:19:59', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 35699),
	('inviteafriendinfo', 'zh-hans', 'messages', '喜欢BeWelcome吗？觉得这个项目很不错吧？也许你的朋友也会喜欢哦！你可以<a href="/invite" title="Send someone you know an invite to BeWelcome">给他们发送BeWelcome的邀请信</a>并附上网站简介和你个人主页的链接，或撰写你觉得合适的个性化邮件内容。', '2010-09-09 12:18:41', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37722),
	('inviteafriendinfo', 'zh-hant', 'messages', '喜欢BeWelcome吗？觉得这个项目很不错吧？也许你的朋友也会喜欢哦！你可以<a href="/invite" title="Send someone you know an invite to BeWelcome">给他们发送BeWelcome的邀请信</a>并附上网站简介和你个人主页的链接，或撰写你觉得合适的个性化邮件内容。', '2010-09-09 12:18:41', '2021-05-02 07:48:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37722),
	('inviteafriendpage', 'ar', 'messages', 'ادعو صديق', '2008-02-11 08:16:37', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 2702),
