	('invitesubjectdesc', 'ar', 'messages', 'اختر لغة مختلفة في التذييل لتغيير لغة النص أيضاً، أو عرفه بنفسك.', '2013-11-07 17:23:38', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48359),
	('invitesubjectdesc', 'ca', 'messages', 'Escull un idioma diferent al peu de pàgina per canviar l\'idioma d\'aquest text bàsic, també. O el pots modificar tu mateix.', '2009-08-24 13:08:12', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 5533),
	('invitesubjectdesc', 'de', 'messages', 'Um die Sprache dieses Standardtextes zu ändern, wähle bitte eine andere Sprache weiter unten aus. Du kannst den Text auch selbst anpassen.', '2009-07-28 18:37:58', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 71),
	('invitesubjectdesc', 'el', 'messages', 'Επίλεξε μια άλλη γλώσσα στο υποσέλιδο για να αλλάξει και η γλώσσα του βασικού κειμένου. Ή τροποποίησε την εσύ.', '2020-08-15 08:41:44', '2020-09-03 08:43:14', '2020-08-15 08:41:44', 'no', '', 5, NULL, 266544),
	('invitesubjectdesc', 'en', 'messages', 'Choose a different language in the footer to change the language of this basic text, too. Or modify it yourself.', '2009-07-28 18:32:54', '2019-04-23 18:16:49', '2009-07-28 18:32:54', 'no', 'Description for text field on invite page', 5, NULL, 111),
	('invitesubjectdesc', 'es', 'messages', 'Elige un idioma distinto en el pie de la página para cambiar el idioma de este texto básico, o bien puedes modificarlo directamente.', '2010-09-03 12:04:53', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 554),
	('invitesubjectdesc', 'fr', 'messages', 'Pour changer la langue du texte, sélectionnez en une autre en bas de la page. Vous pouvez également modifier le texte vous-même.', '2010-01-23 21:22:44', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('invitesubjectdesc', 'gl', 'messages', 'Escolle unha lingua diferente ao pé para cambiar a lingua no texto básico tamén. O modifícaa ti mesma/o.', '2021-03-31 13:47:09', '2021-03-31 13:47:09', '2021-03-31 13:47:09', 'no', '', 5, NULL, 210880),
	('invitesubjectdesc', 'hr', 'messages', 'Da promijeniš tekst pozivnog pisma promijeni jezik u izborniku niže. ili izmijeni tekst sam/a.', '2009-08-19 12:16:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('invitesubjectdesc', 'hu', 'messages', 'Válasz egy másik nyelvet a fejlécben, ha azt akarod hogy az üzeneted szövege is megváltozzon vagy írd át te magad, ahogyan szeretnéd.', '2012-09-23 17:10:15', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34314),
	('invitesubjectdesc', 'it', 'messages', 'Scegli una lingua diversa nel banner in alto per cambiare la lingua di default per scrivere testi. O modificala da solo.', '2012-10-18 07:39:06', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 33078),
	('invitesubjectdesc', 'lt', 'messages', 'Pakeisk šio pagrindinio teksto kalbą pasirinkdama(s) kitą kalbą poraštėje. Arba pakeisk tekstą savuoju.', '2011-08-15 18:12:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('invitesubjectdesc', 'nl', 'messages', 'Kies een andere taal in de voettekst om de taal van deze basistekst te veranderen, of pas deze zelf aan.', '2011-12-21 15:23:56', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('invitesubjectdesc', 'pl', 'messages', 'W stopce poniżej możesz zmienić język tego podstawowego tekstu, albo zmodyfikować zaproszenie osobiście.', '2021-01-14 17:37:08', '2021-01-14 17:37:08', '2021-01-14 17:37:08', 'no', '', 5, NULL, 116789),
	('invitesubjectdesc', 'pt', 'messages', 'Escolha um idioma diferente no rodapé para alterar também a língua em que este texto de exemplo aparece escrito. Ou altere-o você mesmo/a.', '2012-12-13 13:50:31', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('invitesubjectdesc', 'pt-BR', 'messages', 'Escolha um outro idioma no rodapé para mudar a língua deste texto (ou modifique-o você mesmo).', '2013-05-20 13:09:15', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 50982),
	('invitesubjectdesc', 'ru', 'messages', 'Выберите другой язык внизу страницы, чтобы изменить язык этого текста. Либо измените его самостоятельно.', '2014-05-17 18:20:46', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('invitesubjectdesc', 'sk', 'messages', 'Zvoľ si iný jazyk v pätke stránky, aby sa zmenil aj jazyk tohto základného textu. Alebo si ho uprav podľa ľubovôle.', '2013-03-25 19:10:24', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48253),
	('invitesubjectdesc', 'sr', 'messages', 'Изабери други језик у футеру да би променио језик основног текста. Или измени лично.', '2013-01-20 00:01:24', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('invitesubjectdesc', 'zh-hans', 'messages', '在页脚中选择不同的语言可以改变文本框中显示的基本语言，或者你也可自己修改。', '2010-09-09 12:05:41', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11819),
