	('login.username.or.email', 'zh-hant', 'messages', '帳號名稱 或 電子郵件', '2010-02-20 11:53:06', '2023-10-24 21:05:13', '0000-00-00 00:00:00', 'no', '', 5, NULL, 53422),
	('loginerrormailtoconfirm', 'cs', 'messages', 'Tvá emailová adresa ještě nebyla potvrzena. Pokud jsi neobdržel(a) svůj konfirmační email, můžeš ho %2$s%1$s%3$s . Pokud to také selže, prosím <a href="feedback?IdCategory=3">kontaktuj tým podpory</a>.', '2014-08-20 18:47:12', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 34292),
	('loginerrormailtoconfirm', 'de', 'messages', 'Deine E-Mail-Adresse ist noch nicht bestätigt. Bitte schau in deinem Posteingang oder dem Spamverdacht nach einer E-Mail von BeWelcome und klicke auf den Aktivierungslink in der Nachricht.\r\n\r\nWenn du keine Bestätigungs-E-Mail erhalten hast, kannst du sie jetzt noch einmal %2$s%1$s%3$s. Wenn das auch nicht klappt,  <a href="feedback?IdCategory=3">kontaktiere das Support Team</a>.', '2014-04-27 14:06:39', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 172939),
	('loginerrormailtoconfirm', 'el', 'messages', 'Δεν έχει επιβεβαιωθεί ακόμα η διεύθυνση ηλεκτρονικού ταχυδρομείου. Έλεγχε τα εισερχόμενα ή το φάκελο ανεπιθύμητων για μηνύματα από το BeWelcome και κάνε  κλικ στο σύνδεσμο ενεργοποίησης στο μήνυμα.\r\n\r\nΑν δεν έχεις λάβει ακόμη το email επιβεβαίωσης, μπορείς  %2$s%1$s%3$s. Αν ούτε αυτό δεν είναι δυνατό <a href="feedback?IdCategory=3">επικοινώνησε με την ομάδα υποστήριξης</a>.', '2020-08-20 08:20:20', '2020-08-28 17:50:32', '2020-08-20 08:20:20', 'no', '', 5, NULL, 266544),
	('loginerrormailtoconfirm', 'en', 'messages', 'Your email address has not yet been confirmed. Please check your inbox or spam folder for a message from BeWelcome and click on the activation link in the message.\r\n\r\nIf you haven\'t received your confirmation email, you can %2$s%1$s%3$s. If that also fails, please <a href="feedback?IdCategory=3">contact the support team</a>.', '2013-10-01 11:57:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', 'Message shown when a user who has status \'MailToConfirm\' tries to login.\r\n\r\n%1$s is replaced with the content of LoginErrorMailToConfirmHere\r\n%2$s is the link pointing to the website where the mail can be resent\r\n%3$s is the end tag ', 0, NULL, 42397),
	('loginerrormailtoconfirm', 'es', 'messages', 'Tu dirección de correo no está confirmada. Si no has recibido tu correo de confirmación, puedes %2$s%1$s%3$s. Si esto también falla, <a href="feedback?IdCategory=3">contacta con el equipo de soporte</a>. ', '2014-01-06 11:10:10', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 40088),
	('loginerrormailtoconfirm', 'fr', 'messages', 'Vous n\'avez pas encore confirmé votre adresse e-mail. Veuillez consulter votre boîte de réception ou vos spams et merci de cliquer sur le lien d\'activation contenu dans l\'e-mail envoyé par BeWelcome. \r\n\r\nSi vous n\'avez pas reçu l\'e-mail de confirmation, vous pouvez le %2$s%1$s%3$s. Si cela ne fonctionne pas, merci de <a href="feedback?IdCategory=3">contacter l\'équipe d\'assistance</a>. ', '2014-02-21 23:14:47', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 56017),
	('loginerrormailtoconfirm', 'gl', 'messages', 'O teu enderezo de correo-e aínda non foi confirmado. Por favor procura na túa caixa de entrada ou na carpeta de correos non desexados e pincha na ligazón de activación na mensaxe.\r\n\r\nSe non recibiches o teu correo de confirmación, podes %2$s%1$s%3$s. Se iso tamén falla, por favor <a href="feedback?IdCategory=3">contacta co equipo de axuda</a>.', '2021-02-07 14:01:40', '2021-02-07 14:01:40', '2021-02-07 14:01:40', 'no', '', 5, NULL, 210880),
	('loginerrormailtoconfirm', 'it', 'messages', 'Il tuo indirizzo di posta non è ancora stato confermato. Controlla la tua mail o la cartella Spam per un messaggio di BeWelcome e clicca nel link di attivazione nel messaggio.\r\n\r\nSe non hai ricevuto la tua mail di conferma, puoi %2$%1$s%3$slo. Se nemmeno questo funziona, per favore <a href="feedback?IdCategory=3">contatta il team di supporto</a>', '2014-03-04 00:43:08', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 14616),
	('loginerrormailtoconfirm', 'nl', 'messages', 'Je e-mailadres is nog niet bevestigd.  Controleer je inbox of ongewensteberichtenmap of er een bericht van BeWelcome bij zit en klik op de bevestigingskoppeling in het bericht.\r\n\r\nAls je geen bevestigingsmail gekregen hebt, kan je %2$s%1$s%3$s. Als dat ook mislukt, <a href="feedback?IdCategory=3">contacteer dan het ondersteuningsteam</a>.', '2013-10-04 16:14:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 21169),
	('loginerrormailtoconfirm', 'pl', 'messages', 'Twój adres email nie został jeszcze potwierdzony. Poszukaj w Twojej skrzynce odbiorczej lub folderze ze spamem wiadomości od nas i kliknij link aktywacyjny, który znajdziesz w treści maila.\r\n\r\nJeśli nie otrzymałaś/eś potwierdzenia adresu, możesz  %2$s%1$s%3$s. Jeśli i to nie zadziała, prosimy o <a href="feedback?IdCategory=3">kontakt z Zespołem Wsparcia</a>.', '2021-01-14 20:01:24', '2021-01-14 20:08:19', '2021-01-14 20:01:24', 'no', '', 5, NULL, 116789),
	('loginerrormailtoconfirm', 'pt', 'messages', 'O seu endereço de correio eletrónico ainda não está confirmado. Por favor, confira a sua caixa de entrada de correio eletrónico ou pasta de SPAM, procure uma mensagem do BeWelcome e clique na ligação dessa mensagem para ativar a sua conta.\r\n\r\nSe não recebeu a mensagem de confirmação pode %2$s%1$s%3$s. Se isso falhar, por favor, <a href="feedback?IdCategory=3">contacte a Equipa de Apoio</a>.', '2013-10-01 14:46:55', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 38787),
	('loginerrormailtoconfirm', 'pt-BR', 'messages', 'Seu endereço de email ainda não foi confirmado. Por favor, verifique a caixa de entrada ou os SPAMs de seu email, pois o email de confirmação contém um link para ativação da conta.\r\n\r\nSe você ainda não recebeu seu email de confirmação, você pode %2$s%1$s%3$s. Se isso não funcionar, por favor <a href="feedback?IdCategory=3">contate a equipe de suporte</a>. ', '2014-02-21 21:00:42', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 0, NULL, 160059),
	('loginerrormailtoconfirm', 'ru', 'messages', 'Ваш электронный адрес еще не подтвержден. Если Вы не получили подтверждающего письма, Вы можете %2$s%1$s%3$s его. Если это не помогло, пожалуйста, <a href="feedback?IdCategory=3">свяжитесь с командой поддержки</a>. ', '2014-03-30 17:50:31', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 73061),
	('loginerrormailtoconfirm', 'sr', 'messages', 'Ваша имејл адреса још није потврђена. Ако нисте добили ваш потврдни мејл, можете га %2$s%1$s%3$s. Ако ни то не успе, молимо вас контактирајте <a href="feedback?IdCategory=3">техничку подршку</a>.', '2014-03-28 03:30:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 35032),
