	('loginpage', 'tr', 'messages', 'Oturum açma sayfası', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1),
	('loginpreferredlanguageset', 'cs', 'messages', 'Protože sis nevybral(a) svůj upřednostňovaný jazyk, změnili jsme ho na základě jazyka tvého prohlížeče (\'%1$s\'). Můžeš si ho <a href="/mypreferences">změnit</a>.', '2014-01-23 21:08:42', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('loginpreferredlanguageset', 'de', 'messages', 'Da du noch keine bevorzugte Sprache gewählt hast, haben wir die Sprache deines Browsers (\'%1$s\') als Voreinstellung übernommen. Du kannst sie in deinen <a href="/mypreferences">Einstellungen</a> ändern.', '2014-04-27 20:47:35', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('loginpreferredlanguageset', 'el', 'messages', 'Επειδή δεν επέλεξες κάποια γλώσσα προτίμησης, την προσαρμόσαμε στη γλώσσα του προγράμματος περιήγησης που χρησιμοποιείς(\'%1$s\'). Μπορείς να τη ρυθμίσεις βάσει της δικής σου<a href="/mypreferences"> προτίμησης</a>.', '2013-10-07 19:31:57', '2020-08-25 16:46:08', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('loginpreferredlanguageset', 'en', 'messages', 'Since you have not set your preferred language, we did change it to match your browser\'s language (\'%1$s\'). You can set it to your own <a href="/mypreferences">preference</a>.', '2013-10-03 09:54:19', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', 'Flashnotice shown after the (first - for new signups) login if no preferred language has been set yet.\r\n\r\n%1$s is replaced with the language set. Make sure to include it.', 5, NULL, 40169),
	('loginpreferredlanguageset', 'es', 'messages', 'Como no has indicado un idioma, lo hemos cambiado para  que coincida con el idioma de tu navegador (\'%1$s\'). Puedes cambiarlo según tus <a href="/mypreferences"> preferencias</a>. ', '2014-09-30 10:55:43', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 85785),
	('loginpreferredlanguageset', 'fr', 'messages', 'Comme vous n\'avez pas indiqué de langue préférée pour l\'affichage, nous avons automatiquement choisi celle de votre navigateur (%1$s). Vous pouvez la modifier manuellement dans vos <a href="/mypreferences">préférences</a>.', '2017-01-18 23:08:59', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('loginpreferredlanguageset', 'gl', 'messages', 'Dado que ti non estableciches a túa lingua preferida, a cambiamos para que coincida coa lingua do teu navegador (\'%1$s\'). Podes establecer a da túa propia <a href="/mypreferences">preferencia</a>.', '2021-02-07 13:41:53', '2021-02-07 13:41:53', '2021-02-07 13:41:53', 'no', '', 5, NULL, 210880),
	('loginpreferredlanguageset', 'it', 'messages', 'Dato che non hai settato la tua lingua preferita, l\'abbiamo cambiata per abbinarla con la lingua del tuo browser (\'%1$s\'). Puoi settarla nelle tue  <a href="/mypreferences">preferenze</a>', '2013-10-10 09:10:16', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 33078),
	('loginpreferredlanguageset', 'nl', 'messages', 'Aangezien je geen voorkeur hebt ingesteld voor de taal van de website, hebben we die aangepast aan de taal van je browser (\'%1$s\'). Je kan het zelf aanpassen aan je eigen <a href="/mypreferences">voorkeuren</a>. ', '2013-10-04 15:16:48', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40169),
	('loginpreferredlanguageset', 'pl', 'messages', 'Ponieważ nie ustawiłaś/eś preferowanego języka, zrobiliśmy to za Ciebie tak, aby był zgodny z językiem Twojej przeglądarki (\'%1$s\'). Możesz ustawić własne <a href="/mypreferences">preferencje</a>.', '2021-01-14 20:36:47', '2021-01-14 20:36:47', '2021-01-14 20:36:47', 'no', '', 5, NULL, 116789),
	('loginpreferredlanguageset', 'pt', 'messages', 'Uma vez que não indicou o seu idioma preferido alterámo-lo para corresponder ao idioma do seu browser ("%1$s"). Pode alterá-lo de acordo com a sua <a href="/mypreferences">preferência</a>.', '2014-01-02 22:50:34', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('loginpreferredlanguageset', 'pt-BR', 'messages', 'Como você não definiu um idioma de preferência, nós alteramos para combinar com o idioma do seu navegador (\'%1$s\'). Você pode sefinir para o seu próprio em <a href="/mypreferences">preferências</a>.', '2016-12-21 01:05:05', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160059),
	('loginpreferredlanguageset', 'ru', 'messages', 'Так как Вы не указали предпочитаемый язык, мы установилли его в соотвествиии с насройками Вашего интернет-обозревателя (\'%1$s\'). Вы можете изменить этот параметр в <a href="/mypreferences">настройках</a>.', '2014-04-10 14:49:45', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('logout', 'ar', 'messages', 'تسجيل الخروج', '2008-02-11 08:33:43', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48359),
