	('mailbot_joinsendermail', 'ro', 'messages', 'Poţi răspunde direct lui <b>%s</b>, adresa email este: %s', '2007-09-20 22:40:48', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1081),
	('mailbot_joinsendermail', 'ru', 'messages', 'Вы можете ответить <b>%s</b> напрямую по адресу: %s', '2007-09-06 19:38:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 79),
	('mailbot_joinsendermail', 'sr', 'messages', 'Можеш дирекктно одговорити <b>%s</b> на мејл: %s', '2013-08-01 19:00:08', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('mailbot_joinsendermail', 'sw', 'messages', 'Unaweza kujibu moja kwa moja <b>%s</b> barua pepe ni : %s ', '2009-03-30 09:59:06', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1399),
	('mailbot_localvol_info', 'ca', 'messages', 'Aquest missatge va ser enviat per %s\r\nS\'ha enviat a %d membres de la teva àrea\r\nSi no vols rebre més missatges sobre esdeveniments locals a la teva àrea, vés a %s i canvia la preferència per %s', '2009-06-23 14:40:40', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, 1, 5533),
	('mailbot_localvol_info', 'de', 'messages', 'Diese Nachricht wurde von %s verschickt.\r\nEs wurde an %s Mitglieder in deiner Umgebung geschickt.\r\nWenn du keine weiteren Nachrichten über Aktivitäten in deiner Umgebung erhalten möchtest, dann gehe zu %s und ändere die Einstellung für %s.', '2009-02-26 17:39:27', '2009-02-26 17:39:27', '0000-00-00 00:00:00', 'no', '', 5, 1, 3050),
	('mailbot_localvol_info', 'en', 'messages', 'This message was sent by %s\r\nIt is sent to %d members in your local area\r\nIf you don\'t want to receive more messages about local event in your area, go to %s and change your preference for %s', '2009-02-25 20:11:09', '2009-02-25 20:11:09', '2009-02-25 20:11:09', 'no', 'This is the string which is appended to a message sent by a local volunteers\r\nFirst %s parameter is the username of the sender (usually a local volunter)\r\nSecond %d parameter is the count of memembers who will receive the message\r\nThe third %s parameter will be a link (already translated) to mypreferences\r\nFourth parameter is the name of the preference which allow to disbale the receive of such messages', 5, 1, 1),
	('mailbot_localvol_info', 'es', 'messages', 'Este mensaje fue enviado por %s\r\nFue enviado al miembro %d en tu área local\r\nSi no deseas recibir más mensajes sobre los eventos locales en tu área, ve a %s y cambia tu preferencia por %s', '2009-04-08 13:12:57', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, 1, 1328),
	('mailbot_localvol_info', 'fr', 'messages', 'Ce message a été envoyé par  %s\r\n%d membres dans habitant dans la même zone que vous sont susceptibles de le recevoir\r\nSi vous ne voulez plus recevoir de messages de BeWelcome à propos des évènements locaux dans votre zone, allez à %s et changer votre préférence %s ', '2009-02-25 20:16:13', '2009-02-25 20:16:13', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('mailbot_localvol_info', 'it', 'messages', 'Questo messaggio è stato mandato da %s .\r\nE\' stato inviato a tutti i membri della tua zona. Se non vuoi più ricevere messaggi sugli eventi locali della tua zona, vai in %s e modifica le tue preferenze sulle %s', '2011-09-28 14:28:13', '2011-09-28 14:28:37', '0000-00-00 00:00:00', 'no', '', 5, 1, 16084),
	('mailbot_localvol_info', 'sr', 'messages', 'Ова порука је послата од стране %s \r\nОна се шаље члановима %d у Вашој околини\r\nУколико не желите више да примате поруке о догађајима у Вашој околини, идите на %s и промените подешавања за %s', '2013-07-19 16:28:55', '2013-07-19 16:28:55', '0000-00-00 00:00:00', 'no', '', 5, 1, 52973),
	('mailbot_youvegotamailtext', 'ca', 'messages', 'Hola %s:\r\n\r\nHas rebut aquest missatge de part de %s:\r\n<hr>\r\n%s\r\n<hr>\r\nQuè vols ver?\r\n\r\n<a href="%s">Respondre al missatge.</a>\r\n<a href="http://www.bewelcome.org/bw/member.php?cid=%s">Veure el perfil de %s.</a>\r\n<a href="http://www.bewelcome.org/bw/mymessages.php">Veure els missatges que he rebut a BeWelcome.</a>\r\n\r\nQue tinguis un bon dia!', '2007-09-02 20:37:34', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('mailbot_youvegotamailtext', 'cs', 'messages', 'Ahoj %s,\r\n\r\nObdržel(a) jsi následující zprávu od %s:\r\n<hr>\r\n%s\r\n<hr>\r\nCo chceš dělat teď?\r\n\r\n<a href="%s">Odpovědět</a>\r\n<a href="http://www.bewelcome.org/members/%s">Navštívit profil %s</a>\r\n<a href="http://www.bewelcome.org/messages">Zkontrolovat schránku na BeWelcome</a>', '2014-01-23 20:55:19', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('mailbot_youvegotamailtext', 'de', 'messages', 'Hallo %s,\r\n\r\nDu hast folgende Nachricht von %s erhalten:\r\n<hr>\r\n%s\r\n<hr>\r\nWas willst Du als nächstes tun?\r\n\r\n<a href="%s">Auf die Nachricht antworten</a>\r\n<a href="http://www.bewelcome.org/member.php?cid=%s">Das Profil von %s besuchen</a>\r\n<a href="http://www.bewelcome.org/mymessages.php">Deinen BeWelcome-Posteingang öffnen</a>', '2007-09-19 09:01:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('mailbot_youvegotamailtext', 'el', 'messages', 'Γεια σου%s,\r\n\r\nΈχεις λάβει το ακόλουθο μήνυμα από %s:\r\n<hr>\r\n%s\r\n<hr>\r\nΤι θέλεις να κάνεις μετά;\r\n\r\n<a href="%s">Απάντησε στο μήνυμα</a>\r\n<a href="http://www.bewelcome.org/members/%s">Επισκέψου το προφίλ του %s</a>\r\n<a href="http://www.bewelcome.org/messages">Έλεγξε τα εισερχόμενα σου στο BeWelcome </a>', '2020-08-20 11:30:23', '2020-08-28 17:55:39', '2020-08-20 11:30:23', 'no', '', 5, NULL, 266544),
	('mailbot_youvegotamailtext', 'en', 'messages', 'Hello %s,\r\n\r\nYou have received the following message from %s:\r\n<hr>\r\n%s\r\n<hr>\r\nWhat do you want to do next?\r\n\r\n<a href="%s">Reply to the message</a>\r\n<a href="http://www.bewelcome.org/members/%s">Visit the profile of %s</a>\r\n<a href="http://www.bewelcome.org/messages">Check your BeWelcome Inbox</a>', '2007-08-31 13:55:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', 'This is what encapsulate the new text of the content of an incoming mail when a member receive a mail from another.\r\nThe first %s stand for the name of the receiver of the mail\r\nthe second is the username of the sender\r\nthe third %s stand for the text of the mail (as the sender enter it)\r\nThe fourth %s will be replace by the link to directly reply to this mail\r\nThe Fifth and the sixth %s are again the Username of the sender\r\n\r\n@Translator : please dont forget any of these %s !', 5, NULL, 15240),
	('mailbot_youvegotamailtext', 'es', 'messages', 'Hola %s,\r\n\r\nHas recibido el siguiente mensaje de %s: \r\n<hr> \r\n%s \r\n<hr>\r\n¿ Qué deseas hacer ahora?\r\n<a href="%s">Responder mensaje</a> \r\n<a href="http://www.bewelcome.org/member.php?cid=%s">Visitar el perfil de %s</a> \r\n<a href="http://www.bewelcome.org/mymessages.php">Revisa tus mensajes en BeWelcome </a> \r\n\r\n¡Qué tengas un buen día!', '2007-10-28 14:52:27', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1328),
	('mailbot_youvegotamailtext', 'fi', 'messages', 'Hei %s,\r\n\r\nOlet saanut seuraavan viestin jäseneltä %s:\r\n<hr>\r\n%s\r\n<hr>\r\nMitä haluat tehdä seuraavaksi?\r\n\r\n<a href="%s">Vastaa viestiin</a>\r\n<a href="http://www.bewelcome.org/members/%s">Katso jäsenen %s profiilia</a>\r\n<a href="http://www.bewelcome.org/messages">Katso BeWelcome viestisi</a> ', '2012-05-20 20:31:59', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 72),
	('mailbot_youvegotamailtext', 'fr', 'messages', 'Bonjour %s,\r\n\r\n%s vous a envoyé le message suivant&nbsp;:\r\n<hr>\r\n%s\r\n<hr>\r\nQue voulez-vous faire&nbsp;?\r\n\r\n<a href="%s">Répondre au message</a>\r\n<a href="http://www.bewelcome.org/bw/member.php?cid=%s">Voir le profil de %s</a>\r\n<a href="http://www.bewelcome.org/bw/mymessages.php">Vérifier vos derniers messages reçus sur BeWelcome</a>', '2007-08-31 14:28:54', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('mailbot_youvegotamailtext', 'gl', 'messages', '<p>Ola %s,</p><p>Recibiches a seguinte mensaxe de %s: %s Que queres facer agora?</p><p><a href="https://beta.bewelcome.org/%25s">Contesta a mensaxe</a> <a href="http://www.bewelcome.org/members/%25s">Visita o perfil de %s</a> <a href="http://www.bewelcome.org/messages">Mira a túa caixa de entrada de BeWelcome</a></p>', '2022-03-29 09:42:18', '2022-03-29 09:42:18', '2022-03-29 09:42:18', 'no', '', 5, NULL, 210880),
	('mailbot_youvegotamailtext', 'hr', 'messages', 'Bok%s!\r\n\r\nYStigla ti je poruka od %s:\r\n<hr>\r\n%s\r\n<hr>\r\nŠto sada želiš učiniti?\r\n\r\n<a href="%s">Odgovoriti</a>\r\n<a href="http://www.bewelcome.org/members/%s">Pogledati profil %s</a>\r\n<a href="http://www.bewelcome.org/messages">provjeriti svoj poštanski sandučić</a>\r\n\r\nŽelimo ti ugodan dan! ', '2010-04-14 11:44:59', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('mailbot_youvegotamailtext', 'it', 'messages', 'Ciao %s, \r\nhai ricevuto il seguente messaggio da parte di   %s:\r\n<hr>\r\n%s\r\n<hr> \r\nCosa vuoi fare?\r\n\r\n<a href="%s">Rispondi al messaggio</a>\r\n<a href="http://www.bewelcome.org/member.php?cid=%s">Guarda il profilo di %s</a>\r\n<a href="http://www.bewelcome.org/mymessages.php">Controlla la tua posta in entrata su Bewelcome</a>\r\n\r\nBuona giornata!', '2007-09-02 18:36:59', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 103),
	('mailbot_youvegotamailtext', 'lt', 'messages', 'Ku-ku, %s, \r\n\r\njūs gavote žinutę nuo %s: \r\n<hr>\r\n%s\r\n<hr>\r\nKą norite daryti? \r\n\r\n<a href="%s">Atsakyti į žinutę</a>\r\n<a href="http://www.bewelcome.org/member.php?cid=%s">Peržiūrėti nario %s anketą</a>\r\n<a href="http://www.bewelcome.org/mymessages.php">Eiti į savo "Gautų žinučių" aplanką</a>\r\n\r\nGeros dienos!', '2007-12-17 04:26:08', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('mailbot_youvegotamailtext', 'lv', 'messages', 'Sveiks %s,\r\n\r\nTu esi saņēmis turpmāko vēstuli no biedra %s:\r\n<hr>\r\n%s\r\n<hr>\r\nKo tu vēlies darīt tālāk?\r\n\r\n<a href="%s">Atbildēt uz vēstuli</a>\r\n<a href="http://www.bewelcome.org/member.php?cid=%s">Aplūkot profilu %s</a>\r\n<a href="http://www.bewelcome.org/mymessages.php">Pārbaudīt savu BeWelcome pastkasti</a>\r\n\r\nJauku atlikušo dienu!', '2007-09-02 13:32:29', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 375),
	('mailbot_youvegotamailtext', 'nl', 'messages', 'Hello %s, \r\n\r\nJe hebt het volgende bericht gekregen van %s: \r\n<hr> \r\n%s \r\n<hr> \r\nWat wil je nu doen? \r\n\r\n<a href="%s">Beantwoord het bericht</a> \r\n<a href="http://www.bewelcome.org/members/%s">Bezoek het profiel van %s</a> \r\n<a href="http://www.bewelcome.org/messages">Bekijk je BeWelcome inbox</a>', '2007-09-15 21:09:51', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 42397),
	('mailbot_youvegotamailtext', 'pl', 'messages', 'Witaj %s,\r\n\r\nOtrzymałeś następującą wiadomość od %s:\r\n<hr>\r\n%s\r\n<hr>\r\nCo chcesz teraz zrobić?\r\n\r\n<a href="%s">Odpowiedz</a>\r\n<a href="http://www.bewelcome.org/member.php?cid=%s">Zobacz profil %s</a>\r\n<a href="http://www.bewelcome.org/mymessages.php">Sprawdź  wiadomości przychodzące</a>\r\n\r\nMiłego dnia!\r\n', '2007-09-20 14:59:13', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1554),
	('mailbot_youvegotamailtext', 'pt', 'messages', 'Olá %s,\r\n\r\nRecebeu a seguinte mensagem de %s:\r\n<hr>\r\n%s\r\n<hr>\r\nO que pretende fazer a seguir?\r\n\r\n<a href="%s">Responder à mensagem</a> \r\n<a href="http://www.bewelcome.org/members/%s">Visitar o perfil de %s</a> \r\n<a href="http://www.bewelcome.org/messages">Ver a sua caixa de mensagens BeWelcome</a>', '2013-01-09 14:08:12', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('mailbot_youvegotamailtext', 'ru', 'messages', 'Доброго времени суток, %s,\r\n\r\n%s отсправил(а) вам следующее сообщение:\r\n<hr>\r\n%s\r\n<hr>\r\nВаш следующий шаг?\r\n\r\n<a href="%s">Ответить на сообщение</a>\r\n<a href="http://www.bewelcome.org/member.php?cid=%s">Посмотреть профиль %s</a>\r\n<a href="http://www.bewelcome.org/mymessages.php">Войти в папку Входящие на BeWelcome</a>', '2007-09-06 19:40:57', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 79),
	('mailbot_youvegotamailtext', 'sr', 'messages', 'Здраво %s, \r\n\r\nСтигла ти је порука од %s: \r\n<hr> \r\n%s \r\n<hr> \r\nШта желиш да урадиш? \r\n\r\n<a href="%s">Одговори на поруку</a> \r\n<a href="http://www.bewelcome.org/members/%s">Посети %s профил</a> \r\n<a href="http://www.bewelcome.org/messages">Провери своје BeWelcome сандуче</a>', '2015-02-05 20:15:21', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('mailbotdisablegroup', 'cs', 'messages', 'Vypnout upozornění od skupiny (jen pro tuto skupinu, dočasně)', '2015-10-02 09:39:39', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
