	('mailinviteafriendsubject', 'lv', 'messages', 'Ziņkārīgs par pasauli un tās cilvēkiem? Tevi ir uzaicinājis %s (%s) pievienoties BeWelcome!', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 375),
	('mailinviteafriendsubject', 'nl', 'messages', 'Benieuwd naar de wereld? BeWelcome – je bent uitgenodigd door %s (%s) om lid te worden.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('mailinviteafriendsubject', 'pl', 'messages', 'Ciekawy świata? BeWelcome - zostałeś zaproszony przez %s(%s).', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 90),
