	('mailinviteafriendtext', 'sr', 'messages', 'Порука од %s \r\n%s', '2013-03-11 20:57:53', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('mailinviteafriendtext', 'sw', 'messages', 'Ujumbe kutoka %s\r\n%s ', '2009-04-11 13:49:47', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1399),
	('mailinviteafriendtext', 'tr', 'messages', '%s size mesaj gönderdi %s', '2009-11-01 19:17:07', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 95),
	('mailmyrelationtext', 'ca', 'messages', 'Hola %s!\r\n%s declara tenir una relació especial amb tu.\r\n\r\nAl seu perfil diu:\r\n<b>%s</b>\r\n\r\nSi confirmes aquesta relació, podràs declarar (o actualitzar si ja ho has fet) una relació semblant amb aquesta persona. Fes-ho des d\'<a href="%s">aquí</a>.\r\nSi confirmes la relació, serà visible als vostres perfils.', '2007-09-03 19:57:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 177),
	('mailmyrelationtext', 'de', 'messages', 'Hallo %s,\r\n%s hat angegeben, einen besonderen Beziehung zu dir zu haben.\r\n\r\nHier siehst, du was er/sie in sein Profil geschrieben hat:\r\n<b>%s</b>\r\n\r\nBitte bestätige die Beziehung <a href="%s">hier</a>. Nach der Bestätigung, wird eure Beziehung zueinander auf beiden Profilen sichtbar. ', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('mailmyrelationtext', 'el', 'messages', 'Γεια σου %s, \r\nΤο μέλος  %s έχει δηλώσει πως έχει ένα ξεχωριστό δεσμό μαζί σου.\r\n\r\nΈγραψε στο προφίλ σου :\r\n<b>%s</b>\r\n\r\nΕπιβεβαίωσε πως ο δεσμός σου είναι αυτός που δηλώνει αυτό το άτομο <a href="%s">εδώ</a>.\r\nΚατόπιν επιβεβαίωσης, η σχέση σου με αυτό το άτομο θα γίνει ορατή και στα δύο προφίλ.', '2020-08-20 12:50:34', '2020-08-20 12:50:34', '2020-08-20 12:50:34', 'no', '', 5, NULL, 266544),
	('mailmyrelationtext', 'en', 'messages', 'Hello %s, \r\nThe member %s has declared having a special relationship with you.\r\n\r\nThey wrote in their profile :\r\n<b>%s</b>\r\n\r\nPlease confirm that you have a similar relationship with this member <a href="%s">here</a>.\r\nAfter confirmation, your relationship with this person will become visible on both profiles.', '2007-09-16 09:38:38', '2019-04-23 18:16:49', '2008-04-13 16:16:26', 'no', 'Text of the mail sent to the member a user create a relation with (with myrelations)', 5, NULL, 612),
	('mailmyrelationtext', 'es', 'messages', 'Hola %s,\r\nEl miembro %s ha declarado tener una relación especial contigo.\r\n\r\nEscribió en su perfil:\r\n<b>%s</b>\r\n\r\nPor favor confirma que tienes una relación similar con este miembro <a href="%s">aquí</a>.\r\nDespués de confirmar, la relación entre ese usuario y tu serán visibles en los perfiles de ambos.', '2007-11-17 02:55:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1328),
	('mailmyrelationtext', 'fr', 'messages', 'Bonjour %s,\r\n%s a indiqué faire partie de vos proches. \r\n\r\nSon profil définit votre relation comme&nbsp;:\r\n<b>%s</b>\r\n\r\nVeuillez confirmer <a href="%s">ici</a> cette relation. Une fois confirmée, cette information apparaîtra sur vos profils.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('mailmyrelationtext', 'gl', 'messages', '<p>Ola %s, A persoa membro %s manifestou que ten una relación especial contigo.&nbsp;</p><p>Escribiu o seu perfil en: <strong>%s</strong></p><p>Por favor confirma que tes unha relación similar con esta persoa membro <a href="https://beta.bewelcome.org/%25s">aquí</a>. Despois de confirmalo, a túa relación con esta persoa será visible en ambos perfís.&nbsp;</p>', '2022-03-18 15:40:39', '2022-03-18 15:40:39', '2022-03-18 15:40:39', 'no', '', 5, NULL, 210880),
	('mailmyrelationtext', 'it', 'messages', 'Ciao %s, \r\nIl membro %s ha dichiarato di avere una relazione speciale con te.\r\n\r\nHa scritto sul suo profilo:\r\n<b>%s</b> \r\n\r\nPer favore, conferma di avere una simile relazione con questo membro <a href="%s">qui</a>. \r\nCon la tua conferma, questa relazione sarà visibile su entrambi i vostri profili.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 16084),
	('mailmyrelationtext', 'lt', 'messages', 'Sveiki, %s,\r\nNarys %s teigia turįs ypatingą santykį su jumis.\r\n\r\nSavo anketoje jis/ji parašė:\r\n<b>%</b>\r\n\r\nJei jūs su tuo sutinkate, galite taip pat apibrėžti (ar atnaujinti, jei jau apibrėžėte) panašų santykį su šiuo nariu <a href="%s">čia</a>. \r\nJei tai padarysite, šis santykis bus matomas jūsų abiejų anketose.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 80),
	('mailmyrelationtext', 'lv', 'messages', 'Sveiks %s\r\nBiedrs %s paziņo, ka viņam ir īpašās attiecības ar tevi.\r\n\r\nSavā profilā viņi rakstīja:\r\n<b>%s</b>\r\n\r\nLūdzu, apstiprini, ka tev ir līdzīgas attiecības ar šo biedru <a href="%s">here</a>. \r\nPēc šo attiecību ar šo personu apstiprināšanas tas būs redzams abos profilos.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 375),
	('mailmyrelationtext', 'nl', 'messages', 'Hallo %s,\r\nHet lid %s heeft aangegeven een speciale relatie met jou te hebben.\r\n\r\nHij/zij schreef in zijn/haar profiel:\r\n<b>%s</b> \r\n\r\nAls je dit bevestigt, kun je <a href="%s">hier</a> een vergelijkbare relatie met dit lid aangeven (of bijwerken, als je dit al gedaan had). Als je dit doet zal de relatie te zien zijn op beide profielen.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40169),
	('mailmyrelationtext', 'pl', 'messages', 'Witaj %s,\r\n%s przypisał(a) ci szczególny rodzaj relacji.\r\n\r\nNapisał(a) w swoim profilu:\r\n<b>%s</b>\r\n\r\nPotwierdź proszę, że ty masz taki sam rodzaj relacji z tą osobą, <a href="%s">klikając tutaj</a>.\r\nPo potwierdzeniu, ten rodzaj relacji będzie widoczny w obu waszych profilach. ', '2007-10-13 17:15:34', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1554),
	('mailmyrelationtext', 'pt', 'messages', 'Olá %s,\r\nO membro %s declarou ter uma relação especial consigo.\r\n\r\nEscreveu no seu perfil:\r\n<b>%s</b>\r\n\r\nPor favor, confirme que tem esta relação com essa pessoa <a href="%s">aqui</a>. Depois da confirmação a sua relação com essa pessoa ficará visível nos dois perfis.', '2013-01-11 17:10:35', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('mailmyrelationtext', 'ru', 'messages', 'Здравствуйте, %s,\r\n%s хочет внести вас в список своих особых отношений.\r\n\r\nОн(а) написал(а) в своем профиле следующее:\r\n<b>%s</b>\r\n\r\nПожалуйста, подтвердите этот запрос <a href="%s">тут</a>.\r\nПосле этого информация об отношениях появится на обоих профилях', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 79),
	('mailmyrelationtitle', 'ca', 'messages', '%s diu que té una relació especial amb tu.', '2007-08-30 22:14:29', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('mailmyrelationtitle', 'cs', 'messages', 'Člen %s si tě přidal jako zvláštní vztah.', '2014-02-04 23:28:38', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
