	('message_profile_comment', 'cs', 'messages', 'Ahoj %s,\r\n\r\nPrávě o tobě %s napsal(a) komentář. Pokud si chceš přečíst nový komentář, klikni na následující odkaz: %s\r\n\r\nMěj se pěkně!\r\n\r\nTvůj Tým BeWelcome', '2014-01-30 13:24:26', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 34292),
	('message_profile_comment', 'de', 'messages', 'Hallo %s,\r\n\r\ndu hast gerade einen Kommentar von %s erhalten. Wenn du den neuen Kommentar lesen möchtest, klicke auf folgenden Link: %s\r\n\r\nViel Spaß!\r\n\r\nDein BeWelcome-Team\r\n', '2011-12-14 18:35:28', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 15240),
	('message_profile_comment', 'en', 'messages', 'Hi %s,\r\n\r\nYou just got a comment from %s. If you would like to read the new comment, click the following link: %s\r\n\r\nHave a great time!\r\n\r\nYour BeWelcome team\r\n', '2011-12-13 21:04:36', '2019-04-23 18:16:49', '2011-12-17 21:50:55', 'no', '', 5, 1, 202),
	('message_profile_comment', 'es', 'messages', 'Hola %s,\r\n\r\n%s dejó un comentario acerca de ti. Si deseas ver tus comentarios pica el siguiente link: %s\r\n\r\nQue tengas un gran dia!\r\n\r\nEl equipo de BeWelcome\r\n', '2011-12-14 20:20:25', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 202),
	('message_profile_comment', 'fr', 'messages', 'Bonjour %s,\r\n\r\nVous venez de recevoir un commentaire de <b>%s</b>. Pour voir ce commentaire, cliquez sur ce lien&nbsp;: %s.\r\n\r\nÀ bientôt !\r\n\r\nVotre équipe BeWelcome\r\n', '2011-12-18 08:54:08', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 9823),
	('message_profile_comment', 'hr', 'messages', 'Bok %s,\r\n\r\nUpravo si dobio-la komentar od %s. Ako želiš pročitati komentar, klikni na poveznicu: %s\r\n\r\nUživaj!\r\nTvoj BeWelcome tim', '2012-09-19 19:50:28', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 24014),
	('message_profile_comment', 'it', 'messages', 'Ciao %s,\r\n\r\nHai appena ricevuto un commento da %s. Puoi leggere il nuovo commento qui: %s\r\n\r\nBuon divertimento!\r\n\r\nIl team di BeWelcome\r\n', '2011-12-14 09:26:39', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 202),
	('message_profile_comment', 'nl', 'messages', 'Hoi %s, \r\n\r\nJe  hebt zonet een commentaar gekregen van %s. Je kan dit commentaar via deze link lezen: %s \r\n\r\nVeel plezier! \r\n\r\nJe BeWelcome-team ', '2011-12-19 23:11:53', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 21169),
	('message_profile_comment', 'pt', 'messages', 'Olá %s,\r\n\r\nAcabou de receber um comentário de %s. Se quiser ler o novo comentário, siga esta ligação: %s\r\n\r\nDivirta-se!\r\n\r\nA equipa BeWelcome', '2012-12-28 16:07:33', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 38787),
	('message_profile_comment', 'ru', 'messages', 'Привет, %s!\r\n\r\nТолько что %s оставил(а) комментарий в Вашем профиле. Чтобы прочесть новые комментарии, нажмите на ссылку: %s.\r\n\r\nУдачного дня!\r\nВаша Команда BeWelcome', '2014-05-17 04:11:25', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 73061),
	('message_profile_comment_subject', 'ca', 'messages', 'Nou comentari al perfil', '2012-07-22 22:18:24', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11944),
