	('message_profile_comment_update', 'cs', 'messages', 'Ahoj %s,\r\n\r\n%s právě aktualizoval(a) svůj komentář o tobě. Pokud se chceš podívat na své komentáře, klikni na následující odkaz: %s\r\n\r\nMěj se pěkně!\r\n\r\nTvůj Tým BeWelcome', '2014-01-30 13:23:08', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 34292),
	('message_profile_comment_update', 'de', 'messages', 'Hallo %s,\r\n\r\n%s hat gerade einen Kommentar über dich aktualisiert. Wenn du deine Kommentare sehen möchtest, klicke folgenden Link: %s\r\n\r\nViel Spaß!\r\n\r\nDein BeWelcome-Team\r\n', '2011-12-14 18:37:22', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 202),
	('message_profile_comment_update', 'en', 'messages', 'Hi %s,\r\n\r\n%s just updated a comment about you. If you would like to view your comments, click the following link: %s\r\n\r\nHave a great time!\r\n\r\nYour BeWelcome team\r\n', '2011-12-13 21:06:26', '2019-04-23 18:16:49', '2011-12-17 21:48:05', 'no', '', 5, 1, 202),
	('message_profile_comment_update', 'eo', 'messages', 'Saluton %s, \r\n\r\n%s ĵus aktualigis komenton pri vi. Se vi deziras vidi viajn komentojn, alklaku jenan ligilon: %s \r\n\r\nFartu bone! \r\n\r\nVia teamo de BeWelcome', '2013-04-10 14:07:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 47526),
	('message_profile_comment_update', 'es', 'messages', 'Hola %s,\r\n\r\n%s dejó un nuevo comentario acerca de ti. Si deseas ver tus comentarios pica el siguiente link: %s\r\n\r\nQue tengas un gran dia!\r\n\r\nEl equipo de BeWelcome\r\n', '2011-12-14 20:17:19', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 554),
	('message_profile_comment_update', 'eu', 'messages', '%s-(e)k zuri buruzko iruzkin bat eguneratu du. Zure iruzkinak ikusi nahi badituzu, esteka hau sakatu: %s\r\n\r\nOndo izan!\r\n\r\nZure BeWelcome taldea', '2012-12-23 20:58:59', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 11907),
	('message_profile_comment_update', 'fr', 'messages', 'Bonjour %s,\r\n\r\n%s vient de modifier un commentaire sur votre profil. Pour voir ce commentaire, cliquez sur ce lien : %s\r\n\r\nÀ bientôt !\r\n\r\nVotre équipe BeWelcome', '2011-12-18 08:53:26', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 202),
	('message_profile_comment_update', 'hr', 'messages', 'Bok %s,\r\n\r\n%s je upravo updejtao komentar o tebi. Ako želiš vidjeti svoje komentare, klikni na poveznicu: %s\r\n\r\nUživaj!\r\n\r\nTvoj BeWelcome tim ', '2012-09-19 19:48:24', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 24014),
	('message_profile_comment_update', 'it', 'messages', 'Ciao %s,\r\n\r\n%s ha appena modificato un commento su di te. Puoi vedere i tuoi commenti qui: %s\r\n\r\nBuon divertimento!\r\n\r\nIl team di BeWelcome', '2011-12-14 09:28:18', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 202),
	('message_profile_comment_update', 'nl', 'messages', 'Hoi %s, \r\n\r\n%s heeft zonet een commentaar over jou aangepast. Als je dit wenst te lezen, kan je hier klikken: %s \r\n\r\nVeel plezier! \r\n\r\nJe BeWelcome-team ', '2011-12-19 23:13:26', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 21169),
	('message_profile_comment_update', 'pt', 'messages', 'Olá %s,\r\n\r\n%s atualizou um comentário sobre si. Se quer ver os seus comentários siga a ligação seguinte: %s\r\n\r\nDivirta-se!\r\n\r\nA equipa BeWelcome', '2012-12-28 16:08:24', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 38787),
	('message_profile_comment_update', 'ru', 'messages', 'Привет, %s!\r\n\r\n%s только что обновил(а) комментарий о Вас. Если Вы хотите увидеть комменатрий, нажмите на ссылку: %s .\r\n\r\nУдачного дня!\r\nВаша команда BeWelcome', '2014-05-17 04:13:22', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 73061),
