	('mustbeloggedtoseealldata', 'ru', 'messages', 'Вы должны быть войти на сайт, чтобы видеть всю информацию', '2007-09-09 07:56:32', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 79),
	('mustbeloggedtoseealldata', 'sr', 'messages', 'Морате се пријавити да би сте видели све податке', '2013-03-11 20:55:43', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('mustbeloggedtoseealldata', 'tr', 'messages', 'Bilgileri görmek için oturum açmalısınız', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1),
	('mustprovidetherightcaptcha', 'ca', 'messages', 'El codi que has introduït no correspon, cal que introdueixis el correcte per prevenir abusos amb correu brossa.', '2009-06-23 14:43:28', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('mustprovidetherightcaptcha', 'cs', 'messages', 'Omlouváme se, tvou zpráva nešlo odeslat. Prosím kontaktuj <a href="/about/feedback">tým podpory</a>, aby mohli problém napravit.', '2017-02-03 07:06:36', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('mustprovidetherightcaptcha', 'de', 'messages', 'Leider konnte Deine Nachricht nicht gesendet werden. Bitte wende Dich an das <a href="/about/feedback">Support-Team</a>, damit sie das Problem lösen.', '2009-02-23 12:33:26', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 25410),
	('mustprovidetherightcaptcha', 'el', 'messages', 'Συγγνώμη, το μήνυμά σου δεν μπόρεσε να αποσταλεί. Eπικοινώνησε με την <a href="/about/feedback">ομάδα υποστήριξης</a> ώστε να διορθώσουν το πρόβλημα.', '2015-11-10 15:10:35', '2020-08-26 12:21:10', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('mustprovidetherightcaptcha', 'en', 'messages', 'Sorry, your message could not be sent. Please contact the <a href="/about/feedback">support team</a> so that they can fix the problem.', '2009-02-19 10:13:12', '2019-12-26 09:49:40', '2015-10-31 08:02:25', 'no', 'This is the text which is displayed when a member is required to fill a Captcha and doesn\'t provide teh right value', 5, NULL, 1223),
	('mustprovidetherightcaptcha', 'es', 'messages', 'Lo sentimos, el código que ha introducido no coincide. Proporcione el código correctamente. Esto es para prevenir el abuso de spam.', '2011-11-19 09:19:15', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8437),
	('mustprovidetherightcaptcha', 'fr', 'messages', 'Désolé, votre message n\'a pas été envoyé. Veuillez contacter <a href="/about/feedback">l\'équipe d\'assistance</a> pour qu\'elle jette un œil au problème.', '2009-02-19 10:13:55', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('mustprovidetherightcaptcha', 'gl', 'messages', '<p>Sentímolo, mais a túa mensaxe non puido ser enviada. &nbsp;Por favor contacta co <a href="https://beta.bewelcome.org/about/feedback">equipo de apoio</a> para que podan arranxar o problema.</p>', '2021-11-19 09:55:55', '2021-11-19 09:55:55', '2021-11-19 09:55:55', 'no', '', 5, NULL, 210880),
	('mustprovidetherightcaptcha', 'it', 'messages', 'Spiacente, il tuo messaggio non è stato spedito. Contatta il <a href="/about/feedback">team di Supporto</a> perchè possano risolvere il problema.', '2010-04-29 13:48:13', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('mustprovidetherightcaptcha', 'nl', 'messages', 'Helaas, je bericht kon niet verstuurd worden.  Contacteer het <a href="/about/feedback">ondersteuningsteam</a> opdat zij het probleem kunnen oplossen.', '2014-01-13 14:30:25', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('mustprovidetherightcaptcha', 'pl', 'messages', 'Niestety, nie udało się wysłać Twojej wiadomości. Skontaktuj się proszę z naszym <a href="/about/feedback">wsparciem</a>. Postaramy się rozwiązać jak najszybciej problem.', '2021-01-14 17:21:07', '2021-01-14 17:21:07', '2021-01-14 17:21:07', 'no', '', 5, NULL, 116789),
	('mustprovidetherightcaptcha', 'pt', 'messages', 'Lamentamos, mas a sua mensagem não pôde ser enviada. Por favor, contacte a <a href="/about/feedback">Equipa de Suporte</a> para que possam corrigir o problema.', '2013-01-17 18:59:04', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('mustprovidetherightcaptcha', 'pt-BR', 'messages', 'Desculpe, sua mensagem não pôde ser enviada. Por favor, entre em contato com a <a href="/about/feedback">equipe de suporte</a> para que eles verifiquem este problema.', '2016-12-17 21:54:18', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160059),
	('mustprovidetherightcaptcha', 'ru', 'messages', 'Сожалеем, код, который Вы ввели, не походит. Попробуйте ввести его правильно. Это предназначено для фильтрации спама.', '2014-05-18 11:25:14', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('mustprovidetherightcaptcha', 'sr', 'messages', 'Нажалост, код који сте унели се не поклапа. Морате да унесете адекватан код. \r\nНа овај начин спречавамо злоупотребе слањем непожељне поште', '2013-07-19 16:25:31', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 52973),
	('mycomments', 'ca', 'messages', 'Comentaris que he escrit', '2009-06-23 14:37:56', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 5533),
