	('myforumpostspagepublic', 'eu', 'messages', '"Foroko mezuak"-en ikusgarritasuna profilaren bisitarientzat', '2013-05-11 11:47:21', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11907),
