	('myforumpostspagepublic', 'gl', 'messages', 'Visibilidade das "Mensaxes ao Foro" para visitantes do teu perfil', '2021-01-19 08:29:24', '2021-01-19 08:29:24', '2021-01-19 08:29:24', 'no', '', 5, NULL, 210880),
	('myforumpostspagepublic', 'hu', 'messages', '\'Fórum Posztok\' láthatósága a profil látogatóknak', '2014-08-15 20:51:29', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 58692),
	('myforumpostspagepublic', 'hy', 'messages', '«Ֆորումի գրառումների» տեսանելիությունը պրոֆիլիս այցելուների համար', '2025-08-14 04:00:10', '2025-08-14 04:00:10', '2025-08-14 04:00:10', 'no', '', 5, NULL, 519603),
