	('mynotes', 'zh-hant', 'messages', '我的筆記', '2014-06-14 04:52:09', '2021-05-02 07:48:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 68078),
	('mynotesnonotes', 'ar', 'messages', 'لم تكتب أي ملاحظات خاصة. لا تتردد في تصفح الملفات الشخصية للأعضاء الآخرين وإضافة ملاحظات خاصة.', '2013-10-31 13:25:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48359),
	('mynotesnonotes', 'bg', 'messages', 'Не сте написали никакви лични бележки. Можете да разгледате профилите на други хора и да добавите лични бележки.', '2014-01-15 13:53:07', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 61231),
	('mynotesnonotes', 'ca', 'messages', 'No has escrit cap nota privada. Sent-te lliure de navegar pels perfils d\'altres membres i deixar-los notes privades.', '2021-10-04 23:37:22', '2021-10-04 23:37:22', '2021-10-04 23:37:22', 'no', '', 5, NULL, 304193),
	('mynotesnonotes', 'cs', 'messages', 'Nenapsal(a) jsi žádné soukromé poznámky. Neváhej procházet profily jiných členů a přidávat poznámky.', '2013-10-25 22:07:10', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('mynotesnonotes', 'da', 'messages', 'Du har ikke skrevet nogle private noter endnu. Du kan se på andres profiler og skrive private noter om dem.', '2022-08-14 21:07:15', '2022-08-14 21:07:15', '2022-08-14 21:07:15', 'no', '', 5, NULL, 274594),
	('mynotesnonotes', 'de', 'messages', 'Du hast noch keine privaten Notizen gemacht. Du kannst jederzeit andere Profile anschauen und dort private Notizen machen.', '2013-03-22 14:26:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('mynotesnonotes', 'el', 'messages', 'Δεν έχεις προσωπικές σημειώσεις. Μπορείς να περιηγηθείς στα προφίλ άλλων μελών και να προσθέσεις προσωπικές σημειώσεις.', '2013-07-22 15:54:30', '2020-09-02 11:01:22', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('mynotesnonotes', 'en', 'messages', 'You have not written any private notes. Feel free to browse other members\' profiles and add private notes.', '2013-03-19 21:16:27', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', 'Shown when you did not saved any notes of other members.', 5, NULL, 347),
	('mynotesnonotes', 'eo', 'messages', 'Vi ne faris notojn antaŭe. Vi povas libere esplori profilojn de aliaj membroj kaj aldoni privatajn notojn.', '2013-03-20 14:42:40', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 47220),
	('mynotesnonotes', 'es', 'messages', 'No has escrito notas privadas todavía. Navega por los perfiles de otros miembros y podrás agregar notas privadas.', '2013-03-28 14:48:39', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 554),
	('mynotesnonotes', 'fa', 'messages', 'شما هنوز هیچ یادداشت شخصی‌ای ندارید. با خیال راحت نمایه‌ی دیگر کاربرها را مرور کرده و یادداشت‌های شخصی خود را بیافزایید', '2015-06-11 17:57:24', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 41992),
	('mynotesnonotes', 'fr', 'messages', 'Aucune note enregistrée.</br>N’hésitez pas à vous rendre sur le profil d\'un membre et à utiliser cet outil, pour garder des informations à portée de clic.', '2013-04-06 09:07:31', '2020-07-13 13:40:39', '0000-00-00 00:00:00', 'no', '', 5, NULL, 168499),
	('mynotesnonotes', 'gl', 'messages', 'Non escribiches ningunha nota privada. Podes navegar polos perfís doutras persoas da comunidade e engadir notas privadas.', '2021-01-15 18:01:13', '2021-01-15 18:01:13', '2021-01-15 18:01:13', 'no', '', 5, NULL, 210880),
	('mynotesnonotes', 'hi', 'messages', 'आपने कोई निजी नोट नहीं लिखा है। बेझिझक अन्य सदस्यों की प्रोफ़ाइल देखें और निजी नोट्स जोड़ें।', '2021-08-12 15:09:19', '2021-08-12 15:09:19', '2021-08-12 15:09:19', 'no', '', 5, NULL, 308954),
	('mynotesnonotes', 'hr', 'messages', 'Nema privatnih bilješki. Slobodno pretražuj profile i dodaj svoje bilješke.', '2013-10-03 19:41:08', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('mynotesnonotes', 'hu', 'messages', 'Itt jelennek meg az egyes felhasználók adatlapjához írt jegyzeteid.', '2020-05-25 10:44:38', '2020-05-25 10:44:38', '2020-05-25 10:44:38', 'no', '', 5, NULL, 36939),
	('mynotesnonotes', 'hy', 'messages', 'Դուք դեռևս չեք արել ոչ մի անձնական նշում: Ազատ զգացեք՝ դիտել այլ օգտատերերի էջերն ու ավելացնել անձնական նշումներ:', '2013-09-19 20:48:47', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 22128),
	('mynotesnonotes', 'it', 'messages', 'Non hai scritto nessuna nota privata. Sei libero di navigare tra i profili degli altri membri ed aggiungere annotazioni private.', '2013-07-07 22:13:05', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 44692),
	('mynotesnonotes', 'ku', 'messages', 'Te ti mijarên taybet ne nivîsandine. Azad hestbike ku tu kurtjîyannameyên endaman serdanbikî û têbînên taybet pêtirbikî.', '2013-11-24 10:28:04', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48359),
	('mynotesnonotes', 'nl', 'messages', 'Je hebt nog geen persoonlijke notities gemaakt.  Voeg gerust enkele persoonlijke notities to bij het bekijken van profielen van andere leden.', '2013-03-19 22:29:19', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('mynotesnonotes', 'pl', 'messages', 'Nie napisałeś jeszcze żadnych prywatnych notatek. Możesz przeglądać profile innych użytkowników i dodawać prywatne notatki.', '2014-09-03 06:35:19', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 64183),
	('mynotesnonotes', 'pt', 'messages', 'Ainda não escreveu notas privadas. Percorra os perfis dos outros membros e adicione as suas notas privadas.', '2013-06-26 17:52:33', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('mynotesnonotes', 'pt-BR', 'messages', 'Você ainda não escrevi nenhumas notas privadas. Fique vontade para navegar perfiles dos outros membros e adicionar notas privadas. ', '2014-06-06 05:24:27', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48669),
	('mynotesnonotes', 'ru', 'messages', 'У вас нет ни одной личной заметки. Просматривайте профили других участников и добавляйте личные заметки.', '2014-05-02 12:34:16', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 88228),
	('mynotesnonotes', 'sk', 'messages', 'Zatiaľ si si nezapísal(a) žiadne súkromné poznámky. Kľudne si poprezeraj profily ostatných členov a zapíš si potrebné súkromné poznámky.', '2013-03-26 23:09:52', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48253),
	('mynotesnonotes', 'sl', 'messages', 'Do sedaj še nisi napisal nobenega zasebnega zapiska. Naj ti ne bo nerodno brskati po profilih drugih uporabnikov in dodajati zasebne zapiske.', '2019-03-21 22:41:14', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 106553),
	('mynotesnonotes', 'sr', 'messages', 'Још немаш ниједну приватну белешку. Слободно погледај профиле осталих чланова и додај приватну белешку.', '2013-03-29 19:00:13', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('mynotesnonotes', 'sv', 'messages', 'Du har inte skrivit några privata noteringar. Känn dig fri att bläddra i andra medlemmars profiler och lägga till privata noteringar.', '2013-03-27 17:24:46', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 23263),
	('mynotesnonotes', 'tr', 'messages', 'Özel bir not yazmadınız. Diğer üyelerin profillerinden bir fikir alıp siz de özel bir not yazabilirsiniz.', '2014-07-20 21:41:29', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21566),
	('mynotesnonotes', 'zh-hant', 'messages', '您尚未寫任何私人筆記。 隨意瀏覽其他成員的個人資料並添加私人註釋。', '2020-06-23 22:15:31', '2021-05-02 07:48:37', '2020-06-23 22:15:31', 'no', '', 5, NULL, 53422),
