	('newsletter.receive', 'pt', 'messages+intl-icu', 'Está a receber esta mensagem de correio eletrónico porque é membro da comunidade BeWelcome de viajantes e anfitriões.', '2021-04-19 18:40:44', '2021-04-19 18:40:44', '2021-04-19 18:40:44', 'no', '', 5, NULL, 38787),
	('newsletter.receive', 'uk', 'messages+intl-icu', 'Ви отримали цей електронний лист, бо маєте сторінку на BeWelcome - спільноті мандрівників та господарів житла.', '2026-04-24 21:51:41', '2026-04-24 21:51:41', '2026-04-24 21:51:41', 'no', '', 5, NULL, 573491),
	('newsletter.regular.unsubscribe', 'ca', 'messages+intl-icu', 'En cas que ja no vulgueu rebre aquests correus electrònics, feu clic.', '2022-04-11 22:40:57', '2022-04-11 22:40:57', '2022-04-11 22:40:57', 'no', '', 5, NULL, 304193),
	('newsletter.regular.unsubscribe', 'de', 'messages+intl-icu', 'Um diese E-Mails in Zukunft nicht mehr zu erhalten, einfach hier klicken.', '2021-08-11 07:55:14', '2021-08-11 07:55:14', '2021-08-11 07:55:14', 'no', '', 5, NULL, 2208),
	('newsletter.regular.unsubscribe', 'el', 'messages+intl-icu', 'Σε περίπτωση που δεν θέλετε πλέον να λαμβάνετε αυτά τα email απλά κάντε κλικ.', '2022-07-20 04:23:05', '2022-07-20 04:23:05', '2022-07-20 04:23:05', 'no', '', 5, NULL, 266502),
	('newsletter.regular.unsubscribe', 'en', 'messages+intl-icu', 'In case you no longer want to receive these emails just click.', '2021-04-19 17:01:57', '2021-04-19 17:01:57', '2021-04-19 17:01:57', 'no', 'Text at the end of a newsletter allowing members to easily unsubscribe', 5, NULL, 1223),
	('newsletter.regular.unsubscribe', 'eo', 'messages+intl-icu', 'Se vi ne plu deziras ricevi ĉi-tiajn retleterojn, simple alklaku.', '2025-09-12 21:19:49', '2025-09-12 21:19:49', '2025-09-12 21:19:49', 'no', '', 5, NULL, 47526),
	('newsletter.regular.unsubscribe', 'es', 'messages+intl-icu', 'En caso de que no desees seguir recibiendo estos correos, haz clic.', '2021-08-02 15:37:46', '2021-08-02 15:37:46', '2021-08-02 15:37:46', 'no', '', 5, NULL, 25548),
	('newsletter.regular.unsubscribe', 'fr', 'messages+intl-icu', 'Si vous ne voulez plus recevoir ces e-mails, cliquez sur le lien.', '2021-04-19 19:54:12', '2021-04-19 19:54:12', '2021-04-19 19:54:12', 'no', '', 5, NULL, 168499),
	('newsletter.regular.unsubscribe', 'gl', 'messages+intl-icu', 'No caso que non queiras recibir máis estes correos simplemente pincha aquí.', '2021-05-19 09:10:29', '2021-05-19 09:10:29', '2021-05-19 09:10:29', 'no', '', 5, NULL, 210880),
	('newsletter.regular.unsubscribe', 'hy', 'messages+intl-icu', 'Եթե ​​էլ չես ուզում ստանալ այս էլ. նամակները, ուղղակի սեղմի՛ր։', '2025-09-13 03:01:00', '2025-09-13 03:01:00', '2025-09-13 03:01:00', 'no', '', 5, NULL, 519603),
	('newsletter.regular.unsubscribe', 'it', 'messages+intl-icu', 'Se non vuoi più ricevere queste email clicca qui.', '2021-04-20 18:32:38', '2021-04-20 18:32:38', '2021-04-20 18:32:38', 'no', '', 5, NULL, 160610),
	('newsletter.regular.unsubscribe', 'nl', 'messages+intl-icu', 'Als je deze berichten niet meer wenst te ontvangen, klik dan hier.', '2021-04-22 19:44:23', '2021-04-22 19:44:23', '2021-04-22 19:44:23', 'no', '', 5, NULL, 21169),
	('newsletter.regular.unsubscribe', 'pl', 'messages+intl-icu', 'Kliknij, jeśli nie chcesz otrzymywać podobnych wiadomości.', '2021-04-20 14:06:30', '2021-04-20 14:06:53', '2021-04-20 14:06:30', 'no', '', 5, NULL, 116789),
	('newsletter.regular.unsubscribe', 'pt', 'messages+intl-icu', 'Se não pretende continuar a receber estas mensagens, clique aqui.', '2021-04-19 18:41:04', '2021-04-19 18:41:04', '2021-04-19 18:41:04', 'no', '', 5, NULL, 38787),
	('newsletter.unsubscribe.confirmation', 'ca', 'messages+intl-icu', '<p>Hola {username},<br><br>Has rebut un butlletí de bewelcome.org i ens voldries demanar que no t\'enviessim més? Si us plau, pitja "Confirmar" aquí sota.<br><br>Si canvies d\'opinió sempre pots anar a ‘Les meves preferències’, obrir ‘Pàgina web’ i canvia ‘Vull rebre notícies de BeWelcome regularment per correu electrònic’ a sí. No oblidis guardar.</p>', '2022-05-19 11:23:27', '2022-05-19 11:23:27', '2022-05-19 11:23:27', 'no', '', 5, NULL, 26748),
	('newsletter.unsubscribe.confirmation', 'da', 'messages+intl-icu', '<p>Kære {username},</p><p>&nbsp;</p><p>Du har modtaget nyhedsbreve fra BeWelcome og har fortalt os, at du ikke længere ønsker at modtage disse.</p><p>&nbsp;</p><p>Klik venligst på "Bekræft afmelding" nedenfor.</p><p>&nbsp;</p><p>Skulle du fortryde, kan du altid tilmelde dig igen på hjemmesiden under indstillinger.</p><p>&nbsp;</p><p>Husk at trykke på gem til sidst.</p>', '2022-08-14 19:58:12', '2022-08-14 19:58:12', '2022-08-14 19:58:12', 'no', '', 5, NULL, 274594),
	('newsletter.unsubscribe.confirmation', 'de', 'messages+intl-icu', '<p>Hallo {username},<br><br>Du hast einen Newsletter von Bewelcome.org bekommen und möchtest zukünftig keinen mehr bekommen? Bitte klick unten auf "Bestätigen".<br><br>Falls du deine Meinung änderst kannst du den Newsletter in deinem Profil unter "Meine Einstellungen &gt;"Homepage" &gt;"Ich möchte BeWelcome Newsletter per E-Mail erhalten" wieder bestellen. &nbsp;Vergiss nicht, deine Änderung zu speichern.</p>', '2022-10-26 21:53:46', '2022-10-26 21:53:46', '2022-10-26 21:53:46', 'no', '', 5, NULL, 29715),
	('newsletter.unsubscribe.confirmation', 'el', 'messages+intl-icu', '<p>Γεια σας {username},</p><p>&nbsp;</p><p>Έχετε λάβει ένα ενημερωτικό δελτίο από το bewelcome.org και θα θέλατε να μας πείτε ότι δεν το θέλετε πλέον; Παρακαλώ κάντε κλικ στο "Επιβεβαίωση" παρακάτω.</p><p>&nbsp;</p><p>Σε περίπτωση που αλλάξετε γνώμη, μπορείτε πάντα να μεταβείτε στις "Προτιμήσεις μου", να ανοίξετε τoν " Ιστότοπος" και να ρυθμίσετε το "Θέλω να λαμβάνω περιοδικά νέα για το BeWelcome μέσω ηλεκτρονικού ταχυδρομείου" σε ναι. Μην ξεχάσετε να αποθηκεύσετε.</p>', '2023-06-10 05:43:04', '2023-06-10 05:43:04', '2023-06-10 05:43:04', 'no', '', 5, NULL, 266502),
	('newsletter.unsubscribe.confirmation', 'en', 'messages+intl-icu', '<p>Hello {username},<br><br>You have received a newsletter from bewelcome.org and would like to tell us that you do not want these anymore? Please click on “Confirm” below.<br><br>In case you change your mind you can always go to ‘My Preferences’, open ‘Website’ and set ‘I want to receive periodic news about BeWelcome by e-mail’ to yes. Don’t forget to save.</p>', '2021-04-19 08:25:42', '2025-09-23 19:24:08', '2021-04-19 08:25:42', 'no', 'Information to the user that they are going to be unsubscribed from a newsletter if they confirm.', 5, 0, 21169),
	('newsletter.unsubscribe.confirmation', 'es', 'messages+intl-icu', '<p>Hola {username},<br><br>¿Has recibido un boletín de noticias desde bewelcome.org y quieres comunicarnos que no deseas volver a recibirlo? Si es así, pincha abajo en "Confirmar".<br><br>En caso de que cambies de idea, siempre puedes ir a "Mis preferencias", abrir "Página Web" y marcar "Sí" en "Deseo recibir periódicamente noticias sobre BeWelcome por correo electrónico". No olvides pinchar en "Guardar".</p>', '2021-08-02 15:14:43', '2025-12-22 20:03:18', '2021-08-02 15:14:43', 'no', '', 5, NULL, 25548),
	('newsletter.unsubscribe.confirmation', 'fr', 'messages+intl-icu', '<p>Bonjour {username},<br><br>Vous avez reçu une newsletter de BeWelcome et vous voulez nous signaler de ne plus en envoyer ? Merci de cliquer sur confirmer ci-dessous.<br><br>Si vous changez d’avis, vous pourrez toujours changer vos paramètres dans le menu « Préférences », section « site web », en cochant l’option « Recevoir la newsletter de BeWelcome par e-mail » (n’oubliez pas d’enregistrer ensuite).<br><br>&nbsp;</p>', '2021-04-30 18:27:13', '2024-01-27 21:35:37', '2021-04-30 18:27:13', 'no', '', 5, NULL, 168499),
	('newsletter.unsubscribe.confirmation', 'gl', 'messages+intl-icu', '<p>Ola {username},</p><p>Recibiches unha nova de bewelcome.org e gustaríache dicirnos que non queres recibilas máis? Por favor, pincha na ligazón de máis abaixo.</p><p>No caso de que cambies de idea sempre podes ir ás "Miñas Preferencias" despregar "Páxina Web" e marcar "si" en "Quero recibir novas periódicas sobre BeWelcome por correo-e." (non esquezas gardar os cambios).</p><p>&nbsp;</p>', '2021-06-07 13:55:05', '2022-05-03 14:43:49', '2021-06-07 13:55:05', 'no', '', 5, NULL, 210880),
	('newsletter.unsubscribe.confirmation', 'hy', 'messages+intl-icu', '<p>Բարև, {username},</p><p>&nbsp;</p><p>Ստացել ես bewelcome.org կայքից նորություններ և ուզում ես տեղեկացնել մեզ, որ էլ չես ցանկանում դրանք ստանալ: Խնդրում ենք սեղմել ստորև «Հաստատել»:</p><p>&nbsp;</p><p>Եթե միտքդ փոխես, միշտ կարող ես մտնել «Իմ նախընտրությունները» բաժինը բացելով Կայքը և «Ուզում եմ պարբերաբար նորություններ ստանալ ԲիՎելքմի մասին էլ․ փոստով» նախընտրանքը դնել «Այո» տարբերակի վրա: Չմոռանա՛ս պահպանել:</p><p>&nbsp;</p><p>&nbsp;</p>', '2025-09-13 03:11:08', '2025-10-03 06:19:24', '2025-09-13 03:11:08', 'no', '', 5, NULL, 519603),
	('newsletter.unsubscribe.confirmation', 'it', 'messages+intl-icu', '<p>Ciao {username},<br>\r\n<br>\r\nHai ricevuto un notiziario da bewelcome.org e vorresti farci sapere che non sei interessato? Per piacere per piacere clicca su conferma, sotto.<br>\r\n<br>\r\nSe dovessi cambiare idea potrai sempre andare andare su \'Preferenze\', aprire la sezione \'Sito web\' e impostare \'Vorrei ricevere i notiziari periodici su BeWelcome via email\' a sì (non dimenticare di salvare).<br>\r\n<br>', '2021-04-20 18:39:26', '2021-04-20 18:40:29', '2021-04-20 18:39:26', 'no', '', 5, NULL, 160610),
	('newsletter.unsubscribe.confirmation', 'nl', 'messages+intl-icu', '<p>Dag {username},<br><br>Je ontving een nieuwsbrief van bewelcome.org en wil ons vertellen dat je deze niet meer wil? &nbsp;Klik “bevestigen” hieronder.<br><br>Als je je bedenkt kan je altijd naar ‘Mijn instellingen’ gaan, ‘Website’ openen en ‘Ik wil periodiek nieuws over BeWelcome krijgen per mail’ op ja zetten. &nbsp;Vergeet niet op te slaan.</p>', '2021-07-03 16:04:24', '2025-09-24 20:04:45', '2021-07-03 16:04:24', 'no', '', 5, NULL, 21169),
	('newsletter.unsubscribe.confirmation', 'pl', 'messages+intl-icu', '<p>Cześć {username},<br>\r\n<br>\r\nPrzyszedł do Ciebie newsletter z BeWelcome.org i chcesz nam powiedzieć, że nie życzysz sobie takich wiadomości? Potwierdź, klikając poniżej. <br>\r\n<br>\r\nJeśli zmienisz zdanie, możesz zawsze w sekcji „Ustawienia” przejść do zakładki „Strona domowa” i przy pozycji „Chcę otrzymywać newsletter BeWelcome” wybrać „tak” ( nie zapomnij zapisać zmian). <br>\r\n<br>', '2021-04-20 14:22:35', '2021-04-20 14:22:35', '2021-04-20 14:22:35', 'no', '', 5, NULL, 116789),
	('newsletter.unsubscribe.confirmation', 'pt', 'messages+intl-icu', '<p>Olá, {username},&nbsp;</p><p>Recebeu uma newsletter de bewelcome.org e veio dizer-nos que já não as pretende receber mais? Por favor, clique na confirmação em baixo.&nbsp;</p><p>Caso mude de ideias pode sempre ir a \'Minhas preferências\' e abrir \'Página Web\' e passar a sim a opção \'Quero receber notícias periódicas sobre o BeWelcome por correio eletrónico\' (não se esqueça de gravar).</p>', '2021-04-19 18:49:06', '2021-04-21 19:32:53', '2021-04-19 18:49:06', 'no', '', 5, NULL, 38787),
	('newsletter.unsubscribe.confirmation', 'zh-hans', 'messages+intl-icu', '<p>&lt;p&gt;你好 {username},&lt;br&gt;&lt;br&gt;你收到 bewelcome.org 的时事通讯，但想告诉我们你不希望再收到这样的讯息了？请点击下方的 "确认"键。&lt;br&gt;&lt;br&gt;要是你改变主意，你可以随时到个人档案里的 "偏好设置"，打开 "网站"，然后将 "我想收到BeWelcome的定期最新消息" 设置为 "是"。别忘记保存修改哦！&lt;/p&gt;</p>', '2022-02-23 14:56:10', '2022-02-23 14:57:09', '2022-02-23 14:56:10', 'no', '', 5, NULL, 37722),
	('newsletter.unsubscribe.failed', 'ca', 'messages+intl-icu', '<p>Malauradament, hi ha hagut algun error mentre t\'intentàvem donar de baixa al butlletí. Si us plau <a href="https://beta.bewelcome.org/feedback">contacta\'ns</a>.</p>', '2022-04-19 13:22:27', '2022-04-19 13:22:27', '2022-04-19 13:22:27', 'no', '', 5, NULL, 26748),
	('newsletter.unsubscribe.failed', 'el', 'messages+intl-icu', '<p>Δυστυχώς κάτι πήγε λάθος ενώ προσπαθούσαμε να διακόψουμε τη συνδρομή σας από τα &nbsp;newsletters. Παρακαλούμε <a href="/feedback">επικοινωνηστε μαζί μας</a>.</p>', '2022-11-05 15:32:09', '2022-11-05 15:35:50', '2022-11-05 15:32:09', 'no', '', 5, NULL, 266502),
	('newsletter.unsubscribe.failed', 'en', 'messages+intl-icu', '<p>Unfortunately something went wrong while we tried to unsubscribe you from our newsletters. Please <a href="/feedback">contact us</a>.</p>', '2021-07-30 12:52:16', '2021-07-30 12:59:52', '2021-07-30 12:52:16', 'no', 'Shown if something went wrong during the unsubscribe action', 5, 0, 2208),
	('newsletter.unsubscribe.failed', 'es', 'messages+intl-icu', '<p>Desafortunadamente ha ocurrido algún error mientras intentábamos cancelar tu suscripción a nuestros boletines de noticias. Puedes <a href="https://beta.bewelcome.org/feedback">contactarnos</a>.</p>', '2021-08-02 15:27:22', '2021-08-10 15:02:44', '2021-08-02 15:27:22', 'no', '', 5, NULL, 25548),
	('newsletter.unsubscribe.failed', 'fr', 'messages+intl-icu', '<p>Malheureusement, il y a eu un problème lors de votre désinscription à la newsletter. Merci de <a href="/feedback">nous contacter</a>.</p>', '2021-07-31 14:32:49', '2021-07-31 14:32:49', '2021-07-31 14:32:49', 'no', '', 5, NULL, 168499),
	('newsletter.unsubscribe.failed', 'gl', 'messages+intl-icu', '<p>Desafortunadamente algo foi mal mentres tratabamos de darte de baixa da subscrición do boletín de novas.&nbsp;Por favor <a href="https://www.bewelcome.org/feedback">contacta con nós</a>.</p>', '2021-08-02 11:45:04', '2022-05-03 14:48:21', '2021-08-02 11:45:04', 'no', '', 5, NULL, 210880),
	('newsletter.unsubscribe.failed', 'it', 'messages+intl-icu', '<p>&lt;p&gt;Sfortunatamente qualcosa è andato storto mentre stavamo cercando di annullare la tua sottoscrizione ai nostri notiziari. Per piacere &lt;a href="/feedback"&gt;contattaci&lt;/a&gt;.&lt;/p&gt;</p>', '2021-08-01 09:02:01', '2021-08-01 09:02:01', '2021-08-01 09:02:01', 'no', '', 5, NULL, 160610),
	('newsletter.unsubscribe.failed', 'nl', 'messages+intl-icu', '<p>Er ging helaas iets mis toen we je probeerden uit te schrijven van onze nieuwsbrieven. &nbsp;<a href="https://beta.bewelcome.org/feedback">Contacteer ons</a>.</p>', '2021-08-11 10:20:48', '2021-08-11 10:20:48', '2021-08-11 10:20:48', 'no', '', 5, NULL, 21169),
	('newsletter.unsubscribe.failed', 'pl', 'messages+intl-icu', '<p>&lt;p&gt;Niestety coś poszło nie tak podczas próby wypisania Cię z Biuletynów. Prosimy &lt;a href="/feedback"&gt;naisz do nas&lt;/a&gt;.&lt;/p&gt;</p>', '2022-12-26 14:13:21', '2022-12-26 14:13:21', '2022-12-26 14:13:21', 'no', '', 5, NULL, 37896),
	('newsletter.unsubscribe.failed', 'pt', 'messages+intl-icu', '<p>Infelizmente algo correu mal enquanto tentávamos cancelar a sua subscrição dos nossos boletins informativos. Por favor, <a href="/feedback">contacte-nos</a>.</p>', '2021-08-02 17:07:57', '2021-08-02 17:07:57', '2021-08-02 17:07:57', 'no', '', 5, NULL, 38787),
	('newsletter.unsubscribe.failed', 'zh-hans', 'messages+intl-icu', '<p>真遗憾，我们在尝试为你取消订阅时有地方出错了。请&lt;a href="/feedback"&gt;联系我们&lt;/a&gt;。&lt;/p&gt;</p>', '2022-02-23 15:06:12', '2022-02-23 15:06:12', '2022-02-23 15:06:12', 'no', '', 5, NULL, 37722),
	('newsletter.unsubscribe.local.confirmation', 'el', 'messages+intl-icu', 'Έχετε διαγραφεί από τα τοπικά ενημερωτικά δελτία. Εάν αποφασίσετε να εγγραφείτε ξανά, παρακαλούμε ορίστε την αντίστοιχη προτίμηση.', '2023-05-13 16:28:29', '2023-05-13 16:28:29', '2023-05-13 16:28:29', 'no', '', 5, NULL, 266502),
	('newsletter.unsubscribe.local.confirmation', 'en', 'messages+intl-icu', 'You have unsubcribed from local newsletters. If you decide to subscribe again, please set the according preference.', '2023-05-07 08:44:25', '2023-05-07 08:44:25', '2023-05-07 08:44:25', 'no', 'Information text when a member unsubscribes from local newsletters from the unsubscribe link in the newsletter email.', 5, NULL, 1),
	('newsletter.unsubscribe.local.confirmation', 'es', 'messages+intl-icu', 'Has cancelado tu suscripción a los boletines locales. Si decides suscribirte de nuevo, configura las preferencias correspondientes.', '2023-05-23 10:35:02', '2023-05-23 10:35:02', '2023-05-23 10:35:02', 'no', '', 5, NULL, 25548),
	('newsletter.unsubscribe.local.confirmation', 'fr', 'messages+intl-icu', 'Vous vous êtes désabonné·e des newsletters locales. Vous pouvez vous réabonner en allant dans vos préférences.', '2023-05-14 12:39:53', '2023-05-14 12:39:53', '2023-05-14 12:39:53', 'no', '', 5, NULL, 168499),
	('newsletter.unsubscribe.local.confirmation', 'gl', 'messages+intl-icu', 'Cancelaches a subscrición aos boletíns locais. Se decides subscribirte de novo, por favor axusta a preferencia correspondente.', '2023-05-12 08:19:55', '2023-05-12 08:19:55', '2023-05-12 08:19:55', 'no', '', 5, NULL, 210880),
	('newsletter.unsubscribe.local.confirmation', 'hy', 'messages+intl-icu', 'Դու հրաժարվեցիր տեղական նորությունների բաժանորդագրությունից։ Եթե որոշես կրկին բաժանորդագրվել, խնդրում ենք նշել համապատասխան նախընտրությունը։', '2026-01-30 03:59:03', '2026-01-30 03:59:03', '2026-01-30 03:59:03', 'no', '', 5, NULL, 519603),
	('newsletter.unsubscribe.local.confirmation', 'it', 'messages+intl-icu', 'Hai annullato l\'iscrizione ai notiziari locali. Se decidi di iscriverti di nuovo, cambia la preferenza corrispondente.', '2023-06-06 20:34:48', '2023-06-06 20:34:48', '2023-06-06 20:34:48', 'no', '', 5, NULL, 160610),
	('newsletter.unsubscribe.local.confirmation', 'nl', 'messages+intl-icu', 'Je hebt je uitgeschreven van lokale nieuwsbrieven.  Als je ervoor kiest om je weer in te schrijven, pas dan de overeenkomstige voorkeur aan.', '2023-06-08 19:15:47', '2023-06-08 19:15:47', '2023-06-08 19:15:47', 'no', '', 5, NULL, 21169),
	('newsletter.unsubscribe.local.confirmation', 'pl', 'messages+intl-icu', 'Usunięto subskrypcję lokalnego biuletynu. Aby ponownie zasubskrybować, musisz ustawić odpowiednie preferencje.', '2023-09-22 16:06:45', '2023-09-22 16:06:45', '2023-09-22 16:06:45', 'no', '', 5, NULL, 97577),
	('newsletter.unsubscribe.local.confirmation', 'pt', 'messages+intl-icu', 'Cancelou a subscrição de boletins informativos locais. Se pretender subscrevê-los novamente, por favor, altere as suas preferências em conformidade.', '2023-05-13 10:12:12', '2023-05-13 10:12:12', '2023-05-13 10:12:12', 'no', '', 5, NULL, 38787),
	('newsletter.unsubscribe.local.confirmation', 'ru', 'messages+intl-icu', 'Вы отписались от рассылок новостей. Если вы решите снова подписаться, установите соответствующие настройки.', '2025-04-01 11:38:46', '2025-04-01 11:38:46', '2025-04-01 11:38:46', 'no', '', 5, NULL, 519603),
	('newsletter.unsubscribe.local.failed', 'ca', 'messages+intl-icu', '<p>Malauradament hi ha hagut algun problema quan intentàvem desinscriure\'t dels butlletins.</p><p>Si us plau <a href="https://beta.bewelcome.org/feedback">contacta\'ns</a>.</p>', '2022-05-19 11:18:49', '2022-05-19 11:18:49', '2022-05-19 11:18:49', 'no', '', 5, NULL, 26748),
	('newsletter.unsubscribe.local.failed', 'da', 'messages+intl-icu', '<p>Noget gik desværre galt, da vi forsøgte at afmelde dig vores nyhedsbreve.</p><p>&nbsp;</p><p>Prøv at <a href="/feedback">kontakte os</a>.</p>', '2022-08-14 18:55:37', '2022-08-14 18:55:37', '2022-08-14 18:55:37', 'no', '', 5, NULL, 274594),
	('newsletter.unsubscribe.local.failed', 'el', 'messages+intl-icu', '<p>Δυστυχώς κάτι πήγε στραβά όταν προσπαθήσαμε να σας διαγράψουμε από τα ενημερωτικά μας δελτία.<br>Παρακαλούμε <a href="/feedback">επικοινωνήστε μαζί μας</a>.</p>', '2023-06-10 05:40:28', '2023-06-10 05:40:28', '2023-06-10 05:40:28', 'no', '', 5, NULL, 266502),
	('newsletter.unsubscribe.local.failed', 'en', 'messages+intl-icu', 'Unfortunately something went wrong while we tried to unsubscribe you from our newsletters.\r\n\r\nPlease <a href="/feedback">contact us</a>.', '2021-04-19 09:05:42', '2021-04-19 09:06:19', '2021-04-19 09:05:42', 'no', 'Shown if something went wrong during the unsubscribe action', 5, 0, 1223),
	('newsletter.unsubscribe.local.failed', 'es', 'messages+intl-icu', '<p>Desafortunadamente ha ocurrido algún error mientras intentábamos cancelar tu suscripción a nuestros boletines de noticias.&nbsp;</p><p>Puedes <a href="https://beta.bewelcome.org/feedback">contactarnos</a>.</p>', '2021-08-02 15:30:21', '2021-08-02 15:30:21', '2021-08-02 15:30:21', 'no', '', 5, NULL, 25548),
	('newsletter.unsubscribe.local.failed', 'fr', 'messages+intl-icu', 'Malheureusement, nous avons rencontré un problème pour vous désinscrire de nos newsletters.\r\n\r\nMerci de <a href="/feedback">nous contacter</a>.', '2021-04-28 20:32:34', '2021-04-28 20:32:34', '2021-04-28 20:32:34', 'no', '', 5, NULL, 168499),
	('newsletter.unsubscribe.local.failed', 'gl', 'messages+intl-icu', '<p>Desafortunadamente algo foi mal cando trataches de darte de baixa da subscrición das nosas novas.&nbsp;</p><p>&nbsp;</p><p>Por favor <a href="https://beta.bewelcome.org/feedback">contáctanos</a>.</p>', '2021-06-07 13:49:14', '2021-09-02 07:32:57', '2021-06-07 13:49:14', 'no', '', 5, NULL, 210880),
	('newsletter.unsubscribe.local.failed', 'hy', 'messages+intl-icu', '<p>Ցավոք, ինչ-որ սխալ &nbsp;տեղի ունեցավ, երբ մենք փորձում էինք չեղարկել մեր նորությունները ստանալու քո բաժանորդագրությունը։</p><p>Խնդրում ենք <a href="https://www.bewelcome.org/feedback">կապվել մեզ հետ</a>։</p>', '2026-01-30 03:54:45', '2026-01-30 03:54:45', '2026-01-30 03:54:45', 'no', '', 5, NULL, 519603),
	('newsletter.unsubscribe.local.failed', 'it', 'messages+intl-icu', 'Sfortunatamente qualcosa è andato storto mentre stavamo cercando di disiscriverti dai nostri notiziari.\r\n\r\nPer piacere <a href="/feedback">contattaci</a>.', '2021-04-20 18:33:49', '2021-04-20 18:33:49', '2021-04-20 18:33:49', 'no', '', 5, NULL, 160610),
	('newsletter.unsubscribe.local.failed', 'nl', 'messages+intl-icu', '<p>Er ging helaas iets mis toen we je probeerden uit te schrijven van onze nieuwsbrieven.</p><p>&nbsp;</p><p><a href="/feedback">Neem contact op</a>.</p>', '2021-06-07 18:43:21', '2021-06-07 18:43:21', '2021-06-07 18:43:21', 'no', '', 5, NULL, 21169),
	('newsletter.unsubscribe.local.failed', 'pl', 'messages+intl-icu', 'Niestety coś poszło nie tak, gdy próbowaliśmy anulować Twoją subskrypcję naszych newsletterów.\r\n<a href="/feedback">Skontaktuj się z nami</a>.', '2021-04-20 14:14:02', '2021-04-20 14:14:02', '2021-04-20 14:14:02', 'no', '', 5, NULL, 116789),
	('newsletter.unsubscribe.local.failed', 'pt', 'messages+intl-icu', '<p>Infelizmente algo correu mal enquanto tentávamos cancelar a sua subscrição das nossas newsletters.&nbsp;</p><p>Por favor, &lt;a href="/feedback"&gt;contacte-nos&lt;/a&gt;.</p>', '2021-04-19 18:50:52', '2021-04-21 19:23:35', '2021-04-19 18:50:52', 'no', '', 5, NULL, 38787),
	('newsletter.unsubscribe.local.failed', 'zh-hans', 'messages+intl-icu', '<p>真遗憾，我们在尝试为你取消订阅时有地方出错了。请&lt;a href="/feedback"&gt;联系我们&lt;/a&gt;。&lt;/p&gt;</p>', '2022-02-23 15:09:43', '2022-02-23 15:09:43', '2022-02-23 15:09:43', 'no', '', 5, NULL, 37722),
