	('notallowedtopostinforum', 'de', 'messages', 'Entschuldigung, Du darfst nicht in den BW-Foren posten, da die Forumsmoderatoren Dich gesperrt haben.', '2015-01-21 20:26:08', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 92901),
	('notallowedtopostinforum', 'el', 'messages', 'Δυστυχώς, δεν επιτρέπεται να δημοσιεύσεις στα φόρουμ του BW εξαιτίας του αποκλεισμού σου από τους διαχειριστές του φόρουμ.', '2020-07-24 10:48:19', '2020-07-24 10:48:19', '2020-07-24 10:48:19', 'no', '', 5, NULL, 266544),
	('notallowedtopostinforum', 'en', 'messages', 'Sorry, but you\'re not allowed to post in the BW forums due to a ban issued by the forum moderators.', '2014-10-07 21:29:20', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', 'Message shown to a banned member.', 5, NULL, 1),
	('notallowedtopostinforum', 'es', 'messages', 'Lo sentimos, el foro de moderadores te ha inhabilitado para realizar comentarios en los foros de BW', '2014-12-20 09:57:58', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 85785),
	('notallowedtopostinforum', 'fr', 'messages', 'Désolé, mais vous ne pouvez pas publier sur les forums BW - les modérateurs vous en ont interdit l\'accès.', '2015-07-27 19:37:34', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('notallowedtopostinforum', 'gl', 'messages', 'Síntoo, pero non tes permitido enviar mensaxes aos foros de BW debido a un veto do equipo de moderación do Foro.', '2021-02-03 17:42:31', '2021-02-03 17:42:31', '2021-02-03 17:42:31', 'no', '', 5, NULL, 210880),
	('notallowedtopostinforum', 'it', 'messages', 'Ci dispiace, ma non puoi postare nei Forum BW a causa di un bando emanato dal forum moderatori.', '2015-01-05 12:44:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('notallowedtopostinforum', 'nl', 'messages', 'Sorry, maar je kan niet schrijven in de BW fora omdat je door de forum moderators gebannen bent ', '2014-11-25 14:06:05', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 22382),
	('notallowedtopostinforum', 'pl', 'messages', 'Przykro nam, ale nie możesz zamieszczać postów w związku baneem nałożonym przez moderatora tego forum.', '2021-01-14 00:03:09', '2021-01-14 00:03:09', '2021-01-14 00:03:09', 'no', '', 5, NULL, 116789),
	('notallowedtopostinforum', 'pt', 'messages', 'Desculpe, mas não está autorizado/a a escrever nos fórums BW por ter sido banido/a pelos moderadores do fórum.', '2014-10-23 10:28:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
