	('onepreferenceupdated', 'gl', 'messages', '<p>A túa preferencia <strong>%s</strong> foi actualizada ao valor <strong>%s</strong></p>', '2022-09-12 08:00:41', '2022-09-12 08:00:41', '2022-09-12 08:00:41', 'no', '', 5, NULL, 210880),
