	('onepreferenceupdated', 'lt', 'messages', 'Jūsų nustatymai <b>%s</b> yra atnaujinti. Dabartinis statusas: <b>%s</b>', '2007-08-29 04:23:22', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('onepreferenceupdated', 'lv', 'messages', 'Tava izvēle <b>%s</b> tika labota uz <b>%s</b>', '2007-09-02 13:47:51', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 375),
	('onepreferenceupdated', 'nl', 'messages', 'Je voorkeur <b>%s</b> werd geupdate tot de waarde <b>%s</b>', '2007-09-15 21:13:41', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 69),
	('onepreferenceupdated', 'pl', 'messages', 'Twoje preferencje dotyczące <b>%s</b> Zostały zmienione na <b>%s</b>', '2021-01-16 15:32:24', '2021-01-16 15:32:24', '2021-01-16 15:32:24', 'no', '', 5, NULL, 116789),
	('onepreferenceupdated', 'pt', 'messages', 'A sua preferência <b>%s</b> foi atualizada para o valor <b>%s</b>', '2013-01-14 12:08:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('onepreferenceupdated', 'ro', 'messages', 'Preferinţele tale <b>%s</b> au fost reactualizate ca <b>%s</b>', '2007-09-20 22:36:20', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1081),
	('onepreferenceupdated', 'ru', 'messages', 'Вашей настройке <b>%s</b> было установлено значение <b>%s</b>', '2014-05-24 06:40:11', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('onlineprivateprofilesarenotdisplayed', 'ca', 'messages', 'Hola! No estàs connectat com a membre i per això només pots veure el perfil dels contactes que permeten visualitzar-lo a usuaris no connectats.\r\n\r\nPots connectar-te <a href="http://www.bewelcome.org">aquí</a> o <a href="http://www.bewelcome.org/signup.php">crear-te un perfil</a> i fer-te membre de BeWelcome.', '2007-08-30 20:51:30', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 177),
	('onlineprivateprofilesarenotdisplayed', 'de', 'messages', 'Hallo, du bist derzeit nicht in unserem Netzwerk angemeldet, dadurch werden dir nur Mitglieder angezeigt, die ihr Profil als öffentlich zugänglich eingestellt haben.\r\nDu kannst dich <a href="http://www.bewelcome.org">hier mit deinem Benutzernamen anmelden</a> oder (falls du noch kein Mitglied bist) <a href="http://www.bewelcome.org/signup.php">dein Mitgliedsprofil erstellen</a> und bei BeWelcome mitmachen.', '2007-08-29 14:21:21', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('onlineprivateprofilesarenotdisplayed', 'el', 'messages', 'Γεια σου, δεν έχεις συνδεθεί ως μέλος αυτή τη φορά και γι\'αυτό μπορείς να δεις μόνο τα μέλη που έχουν επιλέξει να κάνουν το προφίλ τους δημόσιο.\r\nΜπορείς να συνδεθείς <a href="http://www.bewelcome.org">εδώ</a> ή<a \r\nhref="http://www.bewelcome.org/signup.php">δημιούργησε ένα προφίλ</a> και γίνε μέλος του BeWelcome.', '2020-08-21 20:10:01', '2020-08-21 20:10:01', '2020-08-21 20:10:01', 'no', '', 5, NULL, 266544),
	('onlineprivateprofilesarenotdisplayed', 'en', 'messages', 'Hello, you are not logged in as a member right now so you will only see the members displayed who chose to make their profile public.\r\nYou can log in <a href="http://www.bewelcome.org">here</a> or <a href="http://www.bewelcome.org/signup.php">create a profile</a> and become a member of BeWelcome.', '2007-07-12 13:49:16', '2019-04-23 18:16:49', '2007-07-17 19:27:31', 'no', 'This is the message which is displayed when a user who is not logged in is accessing the whoisonline page', 5, NULL, 1),
	('onlineprivateprofilesarenotdisplayed', 'es', 'messages', 'Hola, no has iniciado sesión como miembro en estos momentos, de esta manera sólo verás los perfiles de quienes lo tienen de tipo público.\r\nPuedes iniciar sesión <a href="http://www.bewelcome.org">aquí</a> o <a href="http://www.bewelcome.org/signup.php">crear un perfil</a> y ser parte de BeWelcome.', '2007-12-31 04:36:54', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1328),
	('onlineprivateprofilesarenotdisplayed', 'fr', 'messages', 'Vous n\'êtes pas connecté. Ne sont visibles que les membres connectés qui ont choisi d\'avoir un profil public.\r\n\r\nVous pouvez vous identifier <a href="http://www.bewelcome.org">ici</a>, ou <a href="http://www.bewelcome.org/signup.php">créer un profil</a> pour devenir membre de BeWelcome.', '2007-07-12 13:59:29', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('onlineprivateprofilesarenotdisplayed', 'gl', 'messages', '<p>Ola, non accediches como persoa membro agora mesmo polo que só verás ás persoas membro que escolleron amosar o seu perfil publicamente. Podes acceder <a href="http://www.bewelcome.org">aquí</a> ou <a href="http://www.bewelcome.org/signup.php">crear un perfil</a> e facerte membro de BeWelcome.</p>', '2022-09-09 11:52:16', '2022-09-09 11:52:16', '2022-09-09 11:52:16', 'no', '', 5, NULL, 210880),
	('onlineprivateprofilesarenotdisplayed', 'he', 'messages', '<p>אינך פעיל כעת כחבר לכן תוכל לראות רק חברים שבחרו שהפרופיל שלהם יהיה ציבורי. ניתן להתחבר לאתר כאן <a href="http://www.bewelcome.org/">http://www.bewelcome.org/&nbsp;</a></p><p>או להרשם לאתר כאן <a href="http://www.bewelcome.org/signup.php">http://www.bewelcome.org/signup.php</a></p>', '2022-07-11 17:59:40', '2022-07-11 17:59:40', '2022-07-11 17:59:40', 'no', '', 5, NULL, 290109),
	('onlineprivateprofilesarenotdisplayed', 'it', 'messages', 'Ciao, attualmente non sei loggato come membro, potrai vedere solo i membri che hanno deciso di rendere il loro profilo pubblico. Puoi loggarti <a href="http://www.bewelcome.org">qui</a> oppure <a href="http://www.bewelcome.org/signup.php">creare un profilo</a>  e diventare membro di BeWelcome.', '2007-08-02 08:33:02', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 103),
	('onlineprivateprofilesarenotdisplayed', 'lt', 'messages', 'Laba, jūs nesate prisijungę kaip narys, tad matysite tik tuos narius, kurie pasirinko viešinti savo anketą ir ne BeWelcome nariams. Galite prisijungti <a href="http://www.bewelcome.org">čia</a>, arba <a href="http://www.bewelcome.org/signup.php">sukurti savo anketą</a> bei tapti BeWelcome nariu.', '2007-08-29 04:29:15', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('onlineprivateprofilesarenotdisplayed', 'lv', 'messages', 'Sveiks, pašreiz tu neesi ielogojies kā biedrs, tāpēc tu vari redzēt tikai tos biedrus, kas ir izvēlējušies izveidot savus profilus publiski pieejamus.\r\nTu vari ielogoties <a href="http://www.bewelcome.org">here</a> vai <a href="http://www.bewelcome.org/signup.php">create a profile</a> un kļūt par BeWelcome biedru.', '2007-08-05 13:29:58', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 375),
	('onlineprivateprofilesarenotdisplayed', 'nl', 'messages', 'Hallo, je bent momenteel niet ingelogd als lid, dus kan je alleen die leden zien die gevraagd hebben om een publiek profiel te hebben. \r\nJe kan <a href="http://www.bewelcome.org">hier</a> inloggen of <a href="http://www.bewelcome.org/signup.php">een profiel aanmaken</a> als je nog geen lid bent van BeWelcome.', '2007-09-17 14:43:42', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40169),
	('onlineprivateprofilesarenotdisplayed', 'pl', 'messages', 'Witaj, nie jesteś obecnie zalogowany jako członek. W związku z tym będziesz mógł zobaczyć profile tylko tych użytkowników, którzy je udostępnili.\r\nMożesz się zalogować  <a href="http://www.bewelcome.org">tutaj</a> albo <a href="http://www.bewelcome.org/signup.php">utworzyć profil</a> i zostać członkiem BeWelcome.', '2007-09-20 14:29:34', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1554),
	('onlineprivateprofilesarenotdisplayed', 'pt', 'messages', 'Olá, não está registado/a como membro neste momento de modo que só verá o perfil de membros que escolheram ter o seu perfil público.\r\nPode identificar-se <a href="http://www.bewelcome.org">aqui</a> ou <a href="http://www.bewelcome.org/signup.php">criar um perfil</a> e tornar-se membro do BeWelcome. ', '2013-01-16 19:23:24', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('onlineprivateprofilesarenotdisplayed', 'ru', 'messages', 'Привет! Вы не вошли на наш сайт и поэтому можете видеть только профили участников, настроенные как "публичные".\r\nВы можете <a href="http://www.bewelcome.org">войти на сайт</a> или <a href="http://www.bewelcome.org/signup.php">создать свой профиль</a> и стать полноправным участником BeWelcome.', '2014-05-24 06:39:26', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('onlineprivateprofilesarenotdisplayed', 'sr', 'messages', 'Здраво, тренутно се ниси пријавио као члан, и зато можеш видети само јавне профиле. Можеш се <a href="http://www.bewelcome.org">прјавити</a> или да <a href="http://www.bewelcome.org/signup.php">направиш профил</a> и постанеш BeWelcome члан.', '2015-05-18 12:05:06', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('onlyactivememberscanverifyeachother', 'ca', 'messages', 'Ho sentim, només els membres els perfils dels quals han estats activats per altres voluntaris poden verificar-se mútuament.', '2011-09-03 22:16:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 11944),
	('onlyactivememberscanverifyeachother', 'de', 'messages', 'Es tut uns leid, aber nur Mitglieder, deren Profile bereits durch unsere eherenamtlichen Mitarbeiter aktiviert wurden, können einander verifizieren.', '2012-09-25 18:33:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 15240),
	('onlyactivememberscanverifyeachother', 'en', 'messages', 'Sorry, only members whose profiles have already been activated by our volunteers can verify each other. ', '2010-05-02 14:50:13', '2019-04-23 18:16:49', '2010-05-02 14:50:13', 'no', '', 5, 1, 5499),
	('onlyactivememberscanverifyeachother', 'es', 'messages', 'Lamentablemente solo los miembros que han sido habilitados por nuestros voluntarios pueden verificar a otros.', '2011-11-08 14:41:24', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 554),
	('onlyactivememberscanverifyeachother', 'fr', 'messages', 'Désolé, seul les membres dont les profils sont actifs et acceptés peuvent procéder à une vérification mutuelle', '2011-11-01 20:19:48', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 68),
	('onlyactivememberscanverifyeachother', 'hr', 'messages', 'Žao nam je, ali samo oni članovi koje su naši volonteri aktivirali mogu potvrđivati jedan drugog.', '2012-08-22 19:05:54', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 8197),
	('onlyactivememberscanverifyeachother', 'it', 'messages', 'Ci dispiace, ma solo membri che hanno il profilo giá attivato da nostri volontari si possono verificare a vicenda.', '2010-05-18 06:28:06', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
	('onlyactivememberscanverifyeachother', 'lt', 'messages', 'Atsiprašome, tačiau tik tie nariai, kurių profiliai yra jau suaktyvinti mūsų savanorių, galėtų tvirtinti kitus narius.', '2011-09-04 00:15:12', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 227),
	('onlyactivememberscanverifyeachother', 'pt', 'messages', 'Desculpe, mas apenas os membros cujos perfis já foram ativados pelos nossos voluntários é que podem verificar outros membros.', '2013-01-26 17:29:16', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 38787),
