	('please.enter.a.message', 'da', 'messages', 'Indtast beskeden her.', '2022-08-02 20:56:21', '2022-08-02 20:56:21', '2022-08-02 20:56:21', 'no', '', 5, NULL, 274594),
	('please.enter.a.message', 'de', 'messages', 'Bitte gib eine Nachricht ein.\r\n\r\nTeile aus Datenschutz- und Sicherheitsgründen in deiner ersten Nachricht KEINE PERSÖNLICHEN DATEN wie Telefonnummern, E-Mail-Adressen oder Social-Media-Daten.', '2022-10-26 21:47:18', '2026-05-17 12:32:57', '2022-10-26 21:47:18', 'no', '', 5, NULL, 2208),
	('please.enter.a.message', 'el', 'messages', 'Παρακαλώ, εισάγετε ένα μήνυμα.', '2022-09-12 21:53:42', '2022-09-12 21:53:42', '2022-09-12 21:53:42', 'no', '', 5, NULL, 266502),
	('please.enter.a.message', 'en', 'messages', 'Please enter a message.\r\n\r\nFor privacy and safety DO NOT SHARE CONTACT INFORMATION such as phone numbers, email addresses or social media in your first message.', '2020-09-20 08:28:43', '2026-05-17 12:29:56', '2020-09-20 08:28:43', 'no', 'Placeholder in textarea', 5, 0, 2208),
	('please.enter.a.message', 'eo', 'messages', 'Bonvolu enigi mesaĝon.', '2025-09-11 08:13:00', '2025-09-11 08:13:00', '2025-09-11 08:13:00', 'no', '', 5, NULL, 47526),
	('please.enter.a.message', 'es', 'messages', 'Escribe un mensaje.\r\n\r\nPor razones de privacidad y seguridad, NO COMPARTES DATOS DE CONTACTO tal como números de teléfono, direcciones de correo electrónico ni datos de redes sociales en tu primer mensaje.', '2020-11-30 03:31:16', '2026-05-17 12:34:29', '2020-11-30 03:31:16', 'no', '', 5, NULL, 2208),
