	('preferenceinspamfolder', 'sk', 'messages', 'Adresár pre spam', '2013-03-24 13:37:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48253),
	('preferenceinspamfolder', 'sr', 'messages', 'Спам фолдер', '2012-12-18 14:22:07', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('preferenceinspamfolder', 'sv', 'messages', 'Skräppost Mapp', '2012-04-17 21:16:40', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 23263),
	('preferenceinspamfolder', 'tr', 'messages', 'Spam dizini', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 95),
	('preferenceinspamfolder', 'zh-hans', 'messages', '垃圾邮件', '2010-09-11 03:59:19', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11819),
	('preferenceinspamfolder', 'zh-hant', 'messages', '垃圾郵件資料夾', '2010-09-11 03:59:19', '2021-05-02 07:48:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 53422),
	('preferenceinspamfolderdesc', 'ar', 'messages', 'إن استقبلت الرسائل المزعجة سيتم الاحتفاظ بها في مجلد الرسائل غير المرغوب بها لمدة شهر واحد إن اخترت <b>نعم</b> أو عدم الاحتفاظ بها إن اخترت <b>لا</b>.', '2013-11-07 19:06:26', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48359),
	('preferenceinspamfolderdesc', 'bg', 'messages', 'Ако, за съжаление получите спам съобщения, те ще се пазят във Вашата спам папка за месец ако изберете <b>Да</b> или ще бъдат изхвърлени ако изберете <b>Не</b>', '2007-09-24 19:19:58', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 401),
	('preferenceinspamfolderdesc', 'ca', 'messages', 'Si reps correu brossa, es desarà a l\'apartat de correu brossa durant un mes si esculls <b>Sí</b> o s\'eliminarà si selecciones <b>No</b>.', '2007-09-06 17:42:54', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('preferenceinspamfolderdesc', 'cs', 'messages', 'Pokud se bohužel stane, že obdržíš nějaký spam, ten bude uschován ve spamové složce po dobu jednoho měsíce v případě, že zvolíš možnost <b>Ano</b> nebo okamžitě smazán, pokud zvolíš <b>Ne</b>. ', '2012-09-25 19:21:30', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 33091),
	('preferenceinspamfolderdesc', 'da', 'messages', '<p>Hvis du er uheldig at modtage spam (enten opdaget automatisk eller manuelt af de frivillige spamtjekkere, hvis du har valgt ja ovenfor), vil det blive opbevaret i en spam-mappe i en måned, hvis du vælger <strong>Ja,</strong> eller slettet hvis du vælger <strong>Nej</strong>.</p>', '0000-00-00 00:00:00', '2022-08-03 11:16:14', '0000-00-00 00:00:00', 'no', '', 5, NULL, 274594),
	('preferenceinspamfolderdesc', 'de', 'messages', 'Solltest du bedauerlicherweise einmal Spam-Nachrichten erhalten, so werden diese bei <b>Ja</b> für einen Monat gespeichert oder bei <b>Nein</b> verworfen.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3050),
	('preferenceinspamfolderdesc', 'el', 'messages', 'Αν επιλέξεις <b>Ναι</b> τα ανεπιθύμητα μηνύματα θα φυλάσσονται στον φάκελο ανεπιθύμητης αλληλογραφίας σας για ένα μήνα, αν επιλέξεις <b> Όχι</b> θα διαγράφονται.', '2012-10-08 11:07:18', '2020-08-29 06:14:05', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('preferenceinspamfolderdesc', 'en', 'messages', 'If, unfortunately, you receive some spam messages they will be kept in your spam folder for one month if you choose <b>Yes</b> or discarded if you choose <b>No</b>.', '2007-05-02 12:26:02', '2019-04-23 18:16:49', '2008-04-13 16:16:26', 'no', '', 5, NULL, 79),
	('preferenceinspamfolderdesc', 'eo', 'messages', 'Se, bedaŭrinde, vi ricevas rubmesaĝojn, ili restos en via amasmesaĝujo por unu monate se vi elektas <b>Jes</b> aŭ tuj forviŝita se vi elektas <b>Ne</b>. ', '2008-09-16 16:12:39', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1769),
	('preferenceinspamfolderdesc', 'es', 'messages', 'Si desafortunadamente recibes algunos mensajes no deseados, estos serán guardados en tu carpeta de \'Spam\' por un mes si seleccionas <b>Sí</b> o serán descartados si seleccionas <b>No</b>.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 12861),
	('preferenceinspamfolderdesc', 'eu', 'messages', 'Mezu baztergarriren bat jasotzen baduzu (spam), <b>bai</b> aukeratuz zure baztergarrien karpetan hilabetez mantenduko dira. <b>Ez</b> aukeratzen baduzu, ezabatuak izango dira.', '2012-11-30 17:52:06', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11907),
	('preferenceinspamfolderdesc', 'fa', 'messages', 'اگر باعرض تأسف هرزنامه‌ای دریافت کردید، با انتخاب <b>بله</b> آن‌ها برای یک ماه در پوشه هرزنامه‌ها باقی می‌مانند. اگر را انتخاب کنید <b>خیر</b> از بین خواهند رفت ', '2013-02-02 19:48:54', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 41992),
	('preferenceinspamfolderdesc', 'fi', 'messages', 'Jos valitettavasti saat joitakin roskaposteja (joko automaattisesti tai roskapostivastaavien toimesta huomattuja) niitä säilytetään roskapostikansiossasi yksi kuukausi, jos valitset <b>Kyllä</b> tai tuhotaan, jos valitset <b>Ei</b>.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 525),
	('preferenceinspamfolderdesc', 'fr', 'messages', 'La messagerie BeWelcome détecte automatiquement les spams. Si vous choisissez <b>Oui</b>, ils seront conservés dans un dossier spam pendant un mois. Si vous cochez <b>Non</b>, ils seront supprimés.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('preferenceinspamfolderdesc', 'gl', 'messages', 'Si, desafortunadamente, recibes algunha mensaxe non desexada serán mantidas na carpeta de mensaxes non desexadas durante un mes se escolles <b>Si</b> ou descartada se escolles <b>Non</b>', '2021-01-19 08:24:04', '2021-01-19 08:24:04', '2021-01-19 08:24:04', 'no', '', 5, NULL, 210880),
	('preferenceinspamfolderdesc', 'he', 'messages', '<p>אם לרוע הזמל קיבלת הודעת ספאם, היא תשאר בתיבת הספאם למשך חודש אם תבחר \'כן\', ותמחק מייד אם תבחר \'לא\'</p>', '2022-07-11 17:30:31', '2022-07-11 17:30:31', '2022-07-11 17:30:31', 'no', '', 5, NULL, 290109),
	('preferenceinspamfolderdesc', 'hr', 'messages', 'Ako odabereš <b>Da</b> islučajno dobiješ neželjenu poštu, ona će se nalaziti u mapi za neželjenu poštu mjesec dana , a ako odabereš <b>Ne</b>. odmah će se izbrisati.', '2009-08-17 18:32:56', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('preferenceinspamfolderdesc', 'hu', 'messages', 'Ha véletlen spam üzenetet kapnál, akkor az a spam mappában lesz eltárolva egy hónapig ha az <b>Igen</b>t választod, viszont ha a <b>Nem</b>et választod, akkor a spam üzeneteid azonnal törlődnek.', '2007-09-06 19:09:59', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34314),
	('preferenceinspamfolderdesc', 'id', 'messages', 'Jika anda memilih <b>Yes</b> spam yang tersaring dalam kotak spam akan tersimpan didalam kotak spam selama satu bulan, jika anda memilih <b>No</b>. maka akan langsung kami hapus', '2007-11-07 20:40:15', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 2019),
	('preferenceinspamfolderdesc', 'it', 'messages', 'Qualora sfortunatamente dovessi ricevere qualche messaggio spam, esso sarà conservato nella tua cartella spam per un mese se scegli <b>Sì</b>, o cancellato se scegli <b>No</b>.', '0000-00-00 00:00:00', '2020-10-09 13:23:58', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160610),
	('preferenceinspamfolderdesc', 'ku', 'messages', 'Heger tu nameyên nebaş werdigrî, ew name wê di kaxizhilgira nameyên nebaş de bên ezberekirin ta mehekê heger tu <b>Erê</b> hibijêrî, an wan ezbereneke heger tu <b>Na</b> hibijêrî.', '2013-11-10 17:41:55', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48359),
	('preferenceinspamfolderdesc', 'lt', 'messages', 'Jei kartais gautumėte kažkiek nepageidaujamų žinučių, jos bus laikomos brukalų aplanke vieną mėnesį jums pasirinkus <b>Taip</b>, arba jos automatiškai bus ištrintos iškart - jums pasirinkus <b>Ne</b>.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('preferenceinspamfolderdesc', 'lv', 'messages', 'Ja tomēr tu saņem kādas spam vēstules, tās tiks noglabātas tavā spama mapē uz mēnesi, ja tu izvēlies <b>Yes</b> vai izdzēstas, ja tu izvēlies <b>No</b>', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 375),
	('preferenceinspamfolderdesc', 'nl', 'messages', 'Mocht je onverhoopt toch spamberichten ontvangen (ofwel automatisch gedetecteerd, ofwel door de vrijwilligers in het geval je ons dat gevraagd hebt), dan worden ze één maand bewaard in je spammap als je <b>ja</b> kiest, of verwijderd als je <b>nee</b> kiest.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('preferenceinspamfolderdesc', 'pl', 'messages', 'Jeśli, niestety, otrzymasz spam będzie on przechowywany w Folderze spam przez miesiąc jeśli wybierzesz <b>Tak</b> lub usuwany jeśli wybierzesz <b>Nie</b>.', '0000-00-00 00:00:00', '2020-12-02 20:34:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37896),
	('preferenceinspamfolderdesc', 'pt', 'messages', 'Ao receber mensagens de SPAM, se escolheres <b>Sim</b> estas serão guardadas na pasta SPAM por um mês ou eliminadas imediatamente se escolheres <b>Não</b>.', '2007-07-01 09:38:05', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 752),
	('preferenceinspamfolderdesc', 'pt-BR', 'messages', 'Se, infelizmente, você receber mensagens de spam, estas serão mantidas por um mês na sua pasta de spam se você escolher <b>Sim</b> ou apagadas se você escolher <b>Não</b>.', '2007-09-19 15:50:25', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15566),
	('preferenceinspamfolderdesc', 'ro', 'messages', 'Dacă, din păcate, primeşti vreun mesaj spam, acesta va fi reţinut în folderul spam timp de o lună dacă alegi <b>Da</b> sau va fi şters dacă alegi <b>Nu</b>.', '2007-09-17 17:59:51', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1081),
	('preferenceinspamfolderdesc', 'ru', 'messages', 'Если вы получите спам, эти сообщения будут храниться в вашей папке "спам" в течение одного месяца, если вы нажмете на <b>да</b> или будут автоматически удалены, если вы нажмете на <b>нет</b>.', '2007-09-09 07:58:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('preferenceinspamfolderdesc', 'sr', 'messages', 'Ако нажалост примиш неку нежељену поруку, налазиће се у твом спам фолдеру један месец ако изабереш <b>Да</b> или одбачена ако изабереш <b>Не</b>', '2012-12-18 14:21:29', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 35032),
	('preferenceinspamfolderdesc', 'sv', 'messages', 'Om cu får några spam meddelanden kommer de att förvaras i din skräppostmapp en månad om du väljer <b>Ja</b> eller kasseras om du väljer <b>Nej</b>.', '2012-04-17 21:18:21', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 23263),
	('preferenceinspamfolderdesc', 'tr', 'messages', 'Eğer herhangi bir şekilde size istenmeyen(spam) bir mesaj gelirse,(otomatik olarak spam kabul edilen veya spam kontrol gönüllüleri tarafından mesajlarınızın kontrol edilmesini istediğiniz takdirde, spam olarak kabul edilen) bu seçenekte, Evet\'i seçerseniz, bu mesajlar bir ay boyunca spam klasörünüzde tutulacaktır. Hayır\'ı seçerseniz mesajlar silinecektir.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 140),
	('preferenceinspamfolderdesc', 'zh-hans', 'messages', '如果你收到了垃圾邮件，选择“是”则它们会在你的垃圾邮件文件夹中保存一个月，选择“否”则会被丢弃。', '2010-09-11 04:04:17', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11819),
	('preferenceinspamfolderdesc', 'zh-hant', 'messages', '如果不幸您收到一些垃圾郵件，如果您選擇<b>是</b>，它們將在垃圾郵件文件夾中保存一個月，或者如果您選擇<b>否</b>，則將其丟棄。。', '2010-09-11 04:04:17', '2021-05-02 07:48:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 53422),
	('preferenceitemsperpagedesc', 'cs', 'messages+intl-icu', 'Zvolený počet bude aplikován na všechny stránky, které nabízí možnost alterace počtu výsledků na jednu stránku. To sníží objem dat načtených serverem najednou', '2023-01-03 16:19:33', '2023-01-03 16:19:33', '2023-01-03 16:19:33', 'no', '', 5, NULL, 389575),
	('preferenceitemsperpagedesc', 'el', 'messages+intl-icu', 'Ο αριθμός που επιλέγετε εδώ χρησιμοποιείται σε όλες τις σελίδες που προσφέρουν σελιδοποίηση για τη μείωση του όγκου των δεδομένων που φορτώνονται από τον διακομιστή με μία μόνο κίνηση.', '2022-11-19 05:48:01', '2022-11-19 05:48:01', '2022-11-19 05:48:01', 'no', '', 5, NULL, 266502),
	('preferenceitemsperpagedesc', 'en', 'messages+intl-icu', 'The number you select here is used on all pages that offer pagination to reduce the amount of data loaded by the server in a single go.', '2022-11-14 20:01:59', '2022-11-14 20:01:59', '2022-11-14 20:01:59', 'no', 'Help text for the preference \'Items shown per page\'', 5, NULL, 1),
	('preferenceitemsperpagedesc', 'es', 'messages+intl-icu', 'El número que se selecciona aquí se usa en todas las páginas que tiene paginación para reducir la cantidad de datos que el servidor carga en una única vez.', '2022-12-06 16:11:44', '2022-12-06 16:11:44', '2022-12-06 16:11:44', 'no', '', 5, NULL, 48548),
	('preferenceitemsperpagedesc', 'fr', 'messages+intl-icu', 'Le paramètre que vous réglez ici affecte toutes les pages sur lesquelles une pagination est utilisée pour réduire la quantité de données chargées par le serveur en une seule fois.', '2023-05-14 12:44:25', '2023-05-14 12:44:25', '2023-05-14 12:44:25', 'no', '', 5, NULL, 168499),
	('preferenceitemsperpagedesc', 'gl', 'messages+intl-icu', 'O número seleccionado aquí úsase en todas as páxinas que ofrecen paxinación para reducir a cantidade de dados cargados polo servidor dunha soa vez.', '2022-11-28 09:44:46', '2022-11-28 09:44:46', '2022-11-28 09:44:46', 'no', '', 5, NULL, 210880),
	('preferenceitemsperpagedesc', 'hy', 'messages+intl-icu', 'Այստեղ ընտրված թիվը կիրառվում է էջադրում առաջարկող բոլոր էջերում սերվերի կողմից միանգամից բեռնված տվյալների քանակը նվազեցնելու համար:', '2025-09-03 03:47:39', '2025-09-03 03:47:39', '2025-09-03 03:47:39', 'no', '', 5, NULL, 519603),
	('preferenceitemsperpagedesc', 'it', 'messages+intl-icu', 'Il numero che selezioni qui è usato in tutte le pagine che offrono una paginazione per ridurre la quantità di dati caricata dal server.', '2022-11-20 15:33:56', '2022-11-20 15:33:56', '2022-11-20 15:33:56', 'no', '', 5, NULL, 160610),
	('preferenceitemsperpagedesc', 'nl', 'messages+intl-icu', 'Het getal dat je hier kiest wordt gebruikt op alle pagina’s die paginatie aanbieden om de hoeveelheid gegevens te beperken die door de server in één keer gedownload wordt.', '2022-11-15 19:13:09', '2022-11-15 19:13:09', '2022-11-15 19:13:09', 'no', '', 5, NULL, 21169),
	('preferenceitemsperpagedesc', 'pl', 'messages+intl-icu', 'Wybrana liczba zostanie zastosowana do wszystkich list z podziałem na strony, aby ograniczyć ilość danych ładowanych jednocześnie przez serwer.', '2022-11-20 20:58:41', '2022-11-20 20:58:41', '2022-11-20 20:58:41', 'no', '', 5, NULL, 97577),
	('preferenceitemsperpagedesc', 'pt', 'messages+intl-icu', 'O número que escolher aqui será usado em todas as páginas que tenham paginação, para reduzir a quantidade de dados transferidos de uma vez a partir do servidor.', '2022-11-27 22:25:29', '2022-11-27 22:25:29', '2022-11-27 22:25:29', 'no', '', 5, NULL, 38787),
	('preferenceitemsperpagedesc', 'ru', 'messages+intl-icu', 'Выбранное здесь число используется на всех страницах, предлагающих пагинацию, чтобы сократить объем данных, загружаемых сервером за один заход.', '2025-03-21 16:55:36', '2025-03-21 16:59:19', '2025-03-21 16:55:36', 'no', '', 5, NULL, 519603),
	('preferenceitemsperpagedesc', 'uk', 'messages+intl-icu', 'Число, яке ви вибираєте тут, використовується на всіх сторінках, які пропонують пагінацію, щоб зменшити обсяг даних, завантажуваних сервером за один раз.', '2026-04-03 18:52:59', '2026-04-03 18:52:59', '2026-04-03 18:52:59', 'no', '', 5, NULL, 573491),
	('preferenceitemsperpagedesc', 'zh-hant', 'messages+intl-icu', '您在此處選擇的數字將用於所有提供分頁的頁面，以減少伺服器一次性載入的資料量。', '2023-10-29 03:54:43', '2023-10-29 03:54:43', '2023-10-29 03:54:43', 'no', '', 5, NULL, 53422),
	('preferencelanguage', 'ar', 'messages', 'اللغة المفضلة', '2008-02-12 12:03:48', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48937),
	('preferencelanguage', 'bg', 'messages', 'Предпочитан език', '2007-07-05 13:27:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 851),
	('preferencelanguage', 'ca', 'messages', 'Llengua preferida', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 177),
