	('preferencelocalevent', 'zh-hant', 'messages', '當地活動的通知', '2010-09-11 04:44:25', '2021-05-02 07:48:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 53422),
	('preferencelocaleventdesc', 'ar', 'messages', 'BeWelcome هي عبارة عن منصة صممت لتتيح للناس للتفاعل في الحياة الحقيقية في جميع أنحاء العالم. أحياناً، قد يرسل المتطوعين المحليين رسائل إلى عدة أشخاص في موقعك.\r\nهذه الإشعارات ليست بالتجارية، فهي عن حياة أعضاء BeWelcome في منطقتك أو حول مواضيع تبادل الضيافة.\r\nاختيار <b> لا</b> إن كنت لا ترغب في تلقي هذه الإشعارات عن طريق البريد.', '2013-11-10 12:34:11', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48359),
	('preferencelocaleventdesc', 'ca', 'messages', 'BeWelcome és una platarforma dissenyada per ajudar a la gent a interactuar en el món real arreu del món. En algun moment, voluntaris locals enviaran missatges a diverses persones al teu voltant.\r\nAquestes notificacions no són per a fins comercials, sinó sobre la vida dels membres de BeWelcome a la teva àrea o sobre temes de intercanvi hospitalari.\r\nEscull <strong>No</strong> si no vols rebre aquestes notificacions per defecte.', '2009-08-24 12:17:14', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 5533),
	('preferencelocaleventdesc', 'cs', 'messages', 'BeWelcome je platforma určená k tomu, aby lidé mohli interagovat živě po celém světě. Někdy mohou místní dobrovolníci poslat maily několika lidem ve tvé lokalitě.\r\nTyto upozornění nejsou komerční, jsou o životě členů BeWelcome ve tvé lokalitě nebo o tématech souvisejících se vzájemnou pohostinností.\r\nVyber <b>Ne</b> pokud nechceš dostávat tato upozornění emailem.', '2015-08-05 12:40:02', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('preferencelocaleventdesc', 'da', 'messages', '<p>BeWelcome er en platform, som er designet til at få mennesker til at interagere i virkeligheden, rundt omkring i verden. Sommetider kan lokale frivillige sende e-mails til personer i dit område.</p><p>Disse notifikationer indeholder ikke kommercielt indhold, de omhandler livet for medlemmer af BeWelcome i dit lokale område.</p><p>Vælg <strong>Nej</strong> hvis du ikke ønsker at modtage disse informationer.</p>', '2022-08-14 20:54:11', '2022-08-14 20:54:11', '2022-08-14 20:54:11', 'no', '', 5, NULL, 274594),
	('preferencelocaleventdesc', 'de', 'messages', 'BeWelcome ist eine Plattform, die es dir ermöglicht mit anderen Leuten aus aller Welt, in Kontakt zu treten. Manchmal verschicken unsere freiwillige Helfer vor Ort, Nachrichten, an Mitglieder in deiner Gegend. Diese Nachrichten sind keine kommerzielle Werbung, sondern haben einen Bezug zu Gastfreundschaft und dem realen Leben der Mitgliedern von BeWelcome in deiner Gegend.\r\nWähle <b>Nein</b>, wenn du keine solcher Nachrichten erhalten möchtest.', '2009-02-26 17:49:15', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3050),
	('preferencelocaleventdesc', 'el', 'messages', '<p>Το BeWelcome είναι μία πλατφόρμα σχεδιασμένη να επιτρέπει στους ανθρώπους να αλληλεπιδρούν στη πραγματική ζωή, ανά τον κόσμο. Μερικές φορές, τοπικοί εθελοντές μπορεί να στείλουν μηνύματα σε πολλά μέλη στην περιοχή σου. Αυτές οι ειδοποιήσεις δεν είναι εμπορικές. Αφορούν στη ζωή των μελών του BeWelcome στη περιοχή σου, ή σε θέματα ανταλλαγής φιλοξενίας. Επίλεξε <strong>Όχι</strong> αν δε θέλεις να λαμβάνεις αυτές τις ειδοποιήσεις μέσω mail.</p>', '2013-12-07 13:36:15', '2024-07-15 14:48:57', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266502),
	('preferencelocaleventdesc', 'en', 'messages', '<p>BeWelcome is a platform designed to allow people to interact in real life across the world. Sometime, local volunteers may send emails to several members in your location. These notifications are not commercial stuff, they are about the life of BeWelcome members in your area or about hospitality exchange subjects. Choose <strong>No</strong> if you do not want to receive these notifications by email.</p>', '2009-02-25 17:38:01', '2022-11-14 21:22:14', '2009-02-26 07:52:26', 'no', 'This is the description of the preference which allows to receive the email notification of events send by local volunteers', 5, 0, 2208),
	('preferencelocaleventdesc', 'eo', 'messages', 'BeWelcome estas platformo projektita por ebligi al homoj tutmonde interagi en la reala vivo.\r\nFoje lokaj volontuloj povas sendi mesaĝojn al pluraj personoj en via regiono. Tiuj sciigoj ne estas komercaj reklamoj, ili pritraktas la socian vivon de la komunmo BeWelcome en via proksimeco aŭ traktas pri la gastigado.\r\nElektu <b>Ne</b> se vi ne volas ricevi ajnajn sciigojn per retpoŝto.', '2013-03-13 13:31:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 47220),
	('preferencelocaleventdesc', 'es', 'messages', '<p>BeWelcome es una plataforma diseñada para permitir a la gente interaccionar en la vida real a lo largo del mundo. En ocasiones, las personas voluntarias locales pueden enviar e-mails a cierto número de personas de tu zona. Estas notificaciones no tienen carácter comercial, sino que tratan sobre la vida de miembros de BeWelcome en tu área o sobre asuntos relativos al intercambio de hospitalidad. Escoge <strong>No</strong> si no quieres recibir estas notificaciones por e-mail.</p>', '2010-10-19 18:54:29', '2023-05-29 11:16:16', '0000-00-00 00:00:00', 'no', '', 5, NULL, 25548),
	('preferencelocaleventdesc', 'fi', 'messages', 'BeWelcome on suunniteltu niin, että ihmiset voivat olla tekemisissä toistensa kanssa päivittäisessä elämässä ympäri maailman. Joskus paikalliset vapaaehtoistyöntekijät saattavat lähettää viestejä useille ihmisille sinun alueellasi. Nämä viestit eivät ole kaupallisia, vaan ne kertovat BeWelcome-tapahtumista alueellasi tai vieraanvaraisuuteen liittyvistä asioista. \r\nValitse <b>Ei</b> jos et halua vastaanottaa näitä viestejä sähköpostiisi.', '2009-06-21 09:01:19', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 525),
	('preferencelocaleventdesc', 'fr', 'messages', '<p>Les membres BeWelcome organisent parfois des événements pour permettre à la communauté de se rencontrer dans la vie réelle. Ils peuvent alors diffuser l\'information par e-mail auprès des membres vivant dans la région. Aucun message ne sera à caractère commercial. Si vous ne voulez pas être averti par e-mail, choisissez <strong>Non</strong>.</p>', '2009-02-26 07:50:59', '2023-12-30 11:05:28', '0000-00-00 00:00:00', 'no', '', 5, NULL, 168499),
	('preferencelocaleventdesc', 'gl', 'messages', '<p>BeWelcome é unha plataforma deseñada para que a xente interactúe na vida real en todo o mundo. As veces, o voluntariado local pode enviar correos a varias persoas na túa localización. Estes avisos non son publicidade comercial, son sobre a vida das persoas da comunidade de BeWelcome na túa área ou sobre asuntos de intercambio de hospitalidade. Escolle "<strong>Non</strong>" se ti non queres recibir estes avisos por correo.</p>', '2021-01-19 08:49:37', '2023-12-29 09:12:09', '2021-01-19 08:49:37', 'no', '', 5, NULL, 210880),
	('preferencelocaleventdesc', 'hr', 'messages', 'BeWelcome je platforma osmišljena da omogući interakciju ljudi u stvarnom životu i po cijelom svijetu. Ponekad lokalni volonteri pošalju poruku ljudima na tvojoj lokaciji.\r\nTe poruke nisu komercijalnog tipa već govore o životu članova BeWelcomea na tvom području, a mogu biti i o gostoprimstvu.\r\nOdaberi <b>Ne</b>ako ne želiš primati te poruke emailom. ', '2011-07-25 18:51:15', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('preferencelocaleventdesc', 'hy', 'messages', '<p>ԲիՎելքմը հարթակ է, որը նախատեսված է աշխարհով մեկ մարդկանց իրական կյանքում փոխգործակցելու հնարավորություն տալու: Երբեմն, տեղացի կամավորները կարող են էլ․ նամակներ ուղարկել գտնվելուդ վայրի մի քանի անդամի: Այս ծանուցումները առևտրային չեն, դրանք վերաբերում են քո տարածքում գտնվող ԲիՎելքմի &nbsp;անդամների կյանքին կամ հյուրընկալության փոխանակման թեմաներին: Ընտրի՛ր <strong>Ոչ</strong>, եթե չես ցանկանում այս ծանուցումները ստանալ էլ.փոստով:</p>', '2025-09-03 03:41:29', '2025-09-03 03:41:29', '2025-09-03 03:41:29', 'no', '', 5, NULL, 519603),
	('preferencelocaleventdesc', 'it', 'messages', 'BeWelcome è una piattaforma realizzata per dar modo alle persone di interagire nella vita reale. A volte, dei volontari locali potrebbero mandare messaggi a vari membri nella zona dove vivi.\r\nQuesti messaggi non sono commerciali, ma riguardano la vita dei membri di BeWelcome nella tua zona o lo scambio d\'ospitalità.\r\nScegli <b>No</b> se non vuoi ricevere questi messaggi.', '2010-05-18 06:50:47', '2020-10-09 13:22:42', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160610),
	('preferencelocaleventdesc', 'ku', 'messages', 'BeWelcome sewkîyeke çalakîya jîyanê ye dihêle ku mirov hev li der dora cîhanê nasbikin, di be ku bidilkar e-pryamanan ji mirovên nêzîkî hirêma wan bişînin.\r\nEv bangna ne reklemin, ema li ser jîyana endamên BeWelcome’in yên di hirêma te de û li ser berdêlkirina mêvanperwerîyê ne.\r\n<b>Na</b>hibijêre heger tu naxwazî van bangna werbigrî.\r\n', '2013-11-24 10:25:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48359),
	('preferencelocaleventdesc', 'lt', 'messages', 'BeWelcome yra platforma, leidžianti žmonėms bendrauti realiame gyvenime visame pasaulyje. Vietiniai savanoriai kartais gali siųsti laiškus keliems nariams tavo vietovėje. \r\nŠie pranešimai nėra komerciniai, o daugiausia liečia BeWelcome narių gyvenimą ir bendras jų veiklas tavo vietovėje - šios žinutės praktiškai visada liečia apsikeitimo svetingumu temą. \r\nPasirink <b>Ne</b> jei vis tik nenori gauti šių pranešimų elektroniniu paštu.', '2009-08-08 23:38:13', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('preferencelocaleventdesc', 'nl', 'messages', '<p>Bewelcome is een platform ontworpen om mensen de mogelijkheid te geven over de hele wereld met elkaar in contact te komen. Soms kunnen plaatselijke vrijwilligers e-mail sturen naar leden in hun stad of gebied. Deze berichten zullen nooit een commercieel doel hebben, maar gaan over het leven van leden van BeWelcome in je gebied of over onderwerpen gerelateerd aan gastvrijheidsuitwisseling. Kies <strong>Nee</strong> als je deze berichten niet wil ontvangen in je mail.</p>', '2009-07-12 11:10:17', '2025-03-13 19:55:31', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('preferencelocaleventdesc', 'pl', 'messages', 'BeWelcome jest platformą stworzoną, by umożliwić ludziom na całym świecie rzeczywisty kontakt poza siecią. Czasem lokalni wolontariusze mogą wysyłać wiadomości do osób znajdujących się w Twoim regionie.\r\nTe powiadomienia nie mają charakteru komercyjnego, dotyczą życia członków społeczności BeWelcome w Twoim regionie lub są związane z tematyką wymiany gościnności. Wybierz <b>Nie</b> jeśli nie chcesz otrzymywać tych powiadomień poprzez e-mail.', '2012-12-15 13:28:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 35248),
	('preferencelocaleventdesc', 'pt', 'messages', 'BeWelcome é uma plataforma projetada para permitir que as pessoas interagem na vida real em todo o mundo. pontualmente, os voluntários locais podem enviar mensagens para várias pessoas no local. \r\nEstas comunicações não são comerciais, eles são sobre a vida de memmbros do BeWelcome na sua área ou sobre assuntos de troca de hospitalidade. \r\nEscolha Não se você não quiser receber essas notificações por e-mail.', '2009-09-01 10:37:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 9030),
	('preferencelocaleventdesc', 'pt-BR', 'messages', 'O BeWelcome é uma plataforma designada para permitir que as pessoas interajam na vida real por todo o mundo. Ocasionalmente, voluntários podem enviar email para várias pessoas na sua localidade. \r\nEssas notificações não são comerciais, elas são sobre a vida dos membros do BeWelcome na sua área ou sobre assuntos relacionados à troca de hospitalidade.\r\nEscolha <b>Não</b> se você não quiser receber essas notificações por email.', '2011-09-27 22:52:53', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15566),
	('preferencelocaleventdesc', 'ru', 'messages', 'BeWelcome создана для того, чтобы помогать людям со всего света общаться в реальной жизни. Иногда локальные волонтеры посылают сообщения сразу нескольким людям, живущим в вашем городе/области. Эти уведомления не являются коммерческой рекламой, в них рассказывается о жизни местных членов BeWelcome members или же темах, связанных с обменом гостеприимоством. Вы можете выбрать  <b>НЕТ</b>, если вы не хотите получать такие сообщения. ', '2009-03-09 10:27:40', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 79),
	('preferencelocaleventdesc', 'sl', 'messages', 'BeWelcome je orodje zasnovano omogočiti ljudem interakcijo v resničnem svetu in po celem svetu. Občasno lahko lokalni prostovoljci pošljejo sporočila nekaj ljudem v tvoji okolici.\r\nTa sporočila niso komercialne narave, temveč o življenju uporabnikov BeWelcome v tvoji okolici ali drugih subjektih vpletenih v izmenjavo gostoljubnosti.\r\nIzberi <b>Ne</b> v kolikor ne želiš prejemati tovrstnih sporočil prek elektronske pošte.', '2019-05-05 19:49:15', '2019-05-05 20:01:07', '2019-05-05 19:49:15', 'no', '', 5, NULL, 106553),
	('preferencelocaleventdesc', 'sr', 'messages', 'BeWelcome је платформа направљена да омогући људима да остваре уживо контакт са другим људима из целог света. Понекада, локални волонтери могу послати мејлове неколицини особа из вашег места.\r\nТа обавештења нису комерцијалне природе, већ о животу чланова BeWelcome који су из ваше земље или се тичу генерално о размени гостопримства.\r\nИзаберите <b>Не</b> ако не желите да добијате оваква обавештења у мејл.', '2013-01-11 01:06:36', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 35032),
	('preferencelocaleventdesc', 'sv', 'messages', 'BeWelcome är en plattform utformad för att tillåta människor att interagera i verkliga livet över hela världen. Någon gång kan lokala volontärer skicka e-post till flera personer i din plats.\r\nDessa meddelanden är inte kommersiella, de är om livet av BeWelcome medlemmar i ditt område eller om gästfrihet utbyte ämnen.\r\nVälj <b>Nej</b> Om du inte vill få dessa meddelanden per post.', '2012-04-17 21:39:52', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 23263),
	('preferencelocaleventdesc', 'tr', 'messages', 'BeWelcome dünyanın çeşitli yerlerindeki insanları gerçek hayatta etkileşime geçirmek için tasarlanmış bir platformdur. Bazen, yerel gönüllüler bulunduğunuz yerdeki bir çok kişiye mail gönderebilirler.\r\nBu bildirimler ticari içerikli değildir. Bölgenizdeki BeWelcome üyelerinin hayatları hakkında ya da misafirperverlik-değişim konuları hakkındadır.\r\nEğer bu bildirimleri mail yoluyla almak istemiyorsanız <b>Hayır</b>\'ı seçin.', '2013-01-25 16:23:45', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21566),
	('preferencelocaleventdesc', 'uk', 'messages', '<p>BeWelcome - це платформа, створена для того, щоб люди могли взаємодіяти в реальному житті по всьому світу. Іноді місцеві волонтери можуть надсилати електронні листи кільком користувачам у вашому регіоні. Ці сповіщення не є комерційними, вони стосуються життя користувачів BeWelcome у вашій місцевості або тем обміну гостинністю. Виберіть <strong>Ні</strong>, якщо ви не хочете отримувати ці сповіщення електронною поштою.</p>', '2026-04-03 18:52:09', '2026-04-03 18:52:09', '2026-04-03 18:52:09', 'no', '', 5, NULL, 573491),
	('preferencelocaleventdesc', 'zh-hans', 'messages', 'BeWelcome是一个让世界各地的人们在现实生活中实现互动的平台。有时，你所在地的志愿们会给本地的一些成员发送邮件。这些通知不是商业性的，而是关于当地BeWelcome成员的生活以及交流接待的主题。\r\n如果你不想收到此类信件，请选择“否”。', '2010-09-11 05:05:00', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11819),
	('preferencelocaleventdesc', 'zh-hant', 'messages', 'BeWelcome是一个让世界各地的人们在现实生活中实现互动的平台。有时，你所在地的志愿们会给本地的一些成员发送邮件。这些通知不是商业性的，而是关于当地BeWelcome成员的生活以及交流接待的主题。\r\n如果你不想收到此类信件，请选择“否”。', '2010-09-11 05:05:00', '2021-05-02 07:48:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11819),
	('preferencelocaleventno', 'ar', 'messages', 'لا', '2013-11-07 20:32:30', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48359),
	('preferencelocaleventno', 'ca', 'messages', 'No', '2009-06-23 18:05:44', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 5533),
	('preferencelocaleventno', 'cs', 'messages', 'Ne', '2012-09-25 18:56:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 33091),
	('preferencelocaleventno', 'da', 'messages', 'Nej', '2022-08-14 20:51:58', '2022-08-14 20:51:58', '2022-08-14 20:51:58', 'no', '', 5, NULL, 274594),
	('preferencelocaleventno', 'de', 'messages', 'Nein', '2009-06-12 21:58:04', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3050),
	('preferencelocaleventno', 'el', 'messages', 'Όχι', '2012-10-07 13:22:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 16526),
