	('preferencelocaleventno', 'eo', 'messages', 'Ne', '2013-03-13 10:52:35', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 47220),
	('preferencelocaleventno', 'es', 'messages', 'No', '2009-07-15 12:12:19', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1328),
	('preferencelocaleventno', 'eu', 'messages', 'Ez', '2012-11-30 17:32:30', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11907),
	('preferencelocaleventno', 'fa', 'messages', 'خیر', '2012-06-11 18:07:53', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 29537),
	('preferencelocaleventno', 'fi', 'messages', 'Ei', '2009-06-21 08:58:15', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 525),
	('preferencelocaleventno', 'fr', 'messages', 'Non', '2009-06-18 08:59:44', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 757),
