	('preferencepublicprofile', 'ru', 'messages', 'Публичный профиль\r\n', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1),
	('preferencepublicprofile', 'sk', 'messages', 'Verejný profil', '2013-03-23 02:24:48', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48253),
	('preferencepublicprofile', 'sr', 'messages', 'Јавни профил', '2012-12-18 10:01:46', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('preferencepublicprofile', 'sv', 'messages', 'Offentlig profil', '2012-04-17 21:12:30', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 23263),
	('preferencepublicprofile', 'tr', 'messages', 'Profil herkese açık?', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 95),
	('preferencepublicprofile', 'zh-hans', 'messages', '资料公开', '2010-09-10 12:33:24', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11819),
	('preferencepublicprofile', 'zh-hant', 'messages', '资料公开', '2010-09-10 12:33:24', '2021-05-02 07:48:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11819),
	('preferencepublicprofiledesc', 'ar', 'messages', 'إذا اخترت <b>نعم<b/> فإن الملف الشخصي يصبح عاماً، ويمكن الولوج إليه عن طريق الانترنت (متضمنا غوغل أيضاً). ملاحظة: في هذه الحالة، فإن أية معلومات شخصية ستبقى مخفية عن الأشخاص الذين ليسوا أعضاء في بي ويلكم.\r\nإذا اخترت <b>لا<b/> (القيمة الافتراضية) فلا يمكن إلا للأعضاء أن يقرؤوا ملف الشخصي.', '2013-04-15 12:15:18', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48937),
	('preferencepublicprofiledesc', 'bg', 'messages', 'Ако изберете <b>Да</b>, Вашият профил ще бъде свободно достъпен в интернет (включително и Google!). Забележка: в този случай, личната информация ще бъде скрита за нечленовете. Ако изберете <b>Не</b> (стойност по подразбиране) само членовете ще могат да преглеждат профила Ви.', '2007-09-24 19:29:48', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 401),
	('preferencepublicprofiledesc', 'ca', 'messages', 'Si selecciones <b>Sí</b>, el perfil serà accessible a través de la web (també des de Google).\r\nNota: en aquest cas, la informació personal encara no es mostrarà a les persones que no siguin membres.\r\nSi selecciones <b>No</b> (valor per defecte), només els membres podran llegir el teu perfil.', '2007-09-06 18:17:05', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 5533),
	('preferencepublicprofiledesc', 'cs', 'messages', 'Pokud zvolíš možnost <b>Ano</b>, tvůj profil bude veřejně dostupný na webu (včetně Google vyhledávače). \r\nPoznámka: V tomto případě budou všechny osobní údaje stále skryty nezaregistorvaným členům.\r\nPokud zvolíš možnost <b>Ne</b> (Výchozí nastavení), tvůj profil bude dostupný pouze zaregistrovaným členům.', '2012-09-25 19:04:02', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 33091),
	('preferencepublicprofiledesc', 'da', 'messages', 'Hvis du vælger <b>Ja</b> vil din profil være offentligt tilgængelig på nettet (inklusiv via søgemaskiner som Google). Læg mærke til, at adresser, tlf.numre, samt chat id kun vises til medlemmer, der er logget på.\r\nHvis du vælger <b>Nej</b> (valgt som standard) kan kun medlemmer se din profil.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1),
	('preferencepublicprofiledesc', 'de', 'messages', 'Bei <b>Ja</b> wird dein Profil öffentlich zugänglich sein (auch bei Google). Hinweis: In diesem Fall werden natürlich immer noch sämtliche persönlichen Daten (Adresse, Telefonnummer, etc.) für nicht eingeloggte Mitglieder verborgen. Wählst du <b>Nein</b> (Standardeinstellung), können ausschließlich angemeldete Mitglieder dein Profil ansehen.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 76),
	('preferencepublicprofiledesc', 'el', 'messages', 'Εάν επιλέξεις <b>Ναι</b> , το προφίλ σου θα είναι δημόσια προσβάσιμο στον ιστό (και στο Google). Σημείωση: Σε αυτή την περίπτωση, οποιαδήποτε προσωπική πληροφορία θα συνεχίσει να μην εμφανίζεται σε μη μέλη. Εαν επιλέξεις <b>Όχι</b> (προκαθορισμένη επιλογή) μόνο τα μέλη θα μπορούν να διαβάσουν το προφίλ σου.', '2012-12-23 12:30:05', '2020-09-02 08:43:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('preferencepublicprofiledesc', 'en', 'messages', 'If you choose <b>Yes</b>, your profile will be publically accessible on the web (including on Google). Note: In this case, any personal information will still be hidden from non-members.\r\nIf you choose <b>No</b> (default value) only members will be able to read your profile. ', '2007-08-22 22:29:02', '2019-04-23 18:16:49', '2009-07-06 01:54:49', 'no', '', 5, NULL, 71),
	('preferencepublicprofiledesc', 'eo', 'messages', 'Se vi elektos <b>Jes</b>, la profilo estos publike atingebla en interreto (inkluzive de Google).\r\nAtentu: En tiu kazo ĉiuj personaj informoj restos tamen daŭre kaŝitaj al ĉiuj ne-membroj.\r\nSe vi elektos <b>Ne</b> (implicita agordo) nur membroj povos legi vian profilon.', '2013-03-13 08:57:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 47220),
	('preferencepublicprofiledesc', 'es', 'messages', 'Si escoges <b>Sí</b> tu perfil podrá ser accedido públicamente en la web (incluyendo Google y otros buscadores). \r\nNota: en este caso, cualquier información personal será oculta para quienes no son miembros de BW.\r\nSi escoges <b>No</b> (valor por defecto) sólo miembros podrán acceder a leer tu perfil.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 12861),
	('preferencepublicprofiledesc', 'eu', 'messages', '<b>Bai</b> aukeratzen baduzu, zure profila interneten publikoki eskuragarria izango da (Google barne). <em>Oharra</em>: Kasu honetan informazio pertsonala ez-kideentzat ezkutatuta jarraituko du.\r\n<b>Ez</b> aukeratzen baduzu (lehenetsia), kideak direnak baino ezin izango dute zure profila ikusi.', '2012-11-21 18:43:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11907),
	('preferencepublicprofiledesc', 'fa', 'messages', 'اگر بله را انتخاب کنید <b>بله</b>، پروفایل شما به صورت عمومی در سطح اینترنت در دسترس خواهد بود. (که این شامل گوگل هم می‌شود)ه\r\nتوجه: در این‌صورت، هر اطلاعات شخصی‌ای که شما داشته باشید، برای کسانی که عضو نیستند، هم‌چنان مخفی خواهند ماند\r\nاگر خیر را انتخاب کنید <b>خیر</b> (انتخاب پیش‌فرض) تنها عضوها می‌توانند که پروفایل شما را بخوانند', '2013-02-02 19:45:15', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 41992),
	('preferencepublicprofiledesc', 'fi', 'messages', 'Jos valitset <b>Kyllä</b>, profiilisi tulee olemaan internetissä julkisesti näkyvillä (myös Googlelle). \r\nHuomaa, että tässä tapauksessa osoitteet, puhelinnumerot sekä pikaviestin tunnukset eivät tule olemaan näkyvillä ei-kirjautuneille jäsenille.\r\nJos valitset <b>Ei</b> (Oletus), vain jäsenet voivat nähdä profiilisi.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 72),
	('preferencepublicprofiledesc', 'fr', 'messages', 'Si vous choisissez <b>Oui</b>, votre profil sera accessible publiquement sur le web (y compris depuis Google). \r\nNotez que même dans ce cas, vos adresse, numéro de téléphone et identifiant de chat ne seront <b>pas</b> affichés publiquement. \r\nSi vous choisissez <b>Non</b> (valeur par défaut), seuls les membres connectés au site auront accès à votre profil.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 9823),
	('preferencepublicprofiledesc', 'gl', 'messages', '<p>Se escolles <strong>Si</strong>, o teu perfil será accesible publicamente na web (incluíndo en Google). Nota: Neste caso, calquera información persoal aínda quedará oculta para as persoas non membro. Se escolles <strong>No</strong> (valor por defecto) só as persoas membro poderán ler o teu perfil.</p>', '2022-03-29 10:20:36', '2022-03-29 10:20:36', '2022-03-29 10:20:36', 'no', '', 5, NULL, 210880),
	('preferencepublicprofiledesc', 'he', 'messages', '<p>אם תבחר/י \'כן\', הפרופיל שלך יהיה נגיש באופן ציבורי במרשתת (כולל בגוגל).</p><p>הערה: במקרה זה, כל מידע פרטי עדיין יהיה נסתר ממי שאינו חבר באתר.&nbsp;</p><p>אם תבחר/י \'לא\' (ברירת המחדל), רק חברים באתר יוכלו לצפות בפרופיל שלך.</p>', '2022-07-11 18:42:26', '2022-07-11 18:42:26', '2022-07-11 18:42:26', 'no', '', 5, NULL, 290109),
	('preferencepublicprofiledesc', 'hr', 'messages', 'Ako odabereš <b>Da</b>, tvoj profil će biti javan i dostupan na Internetu (uključujući Google). Imaj na umu: U tom slučaju, svi osobni podaci će i tada biti skriveni ne-članovima. \r\nAko odabereš <b>Ne</b> (zadana vrijednost) samo će članovi moći vidjeti tvoj profil. ', '2009-08-17 18:21:21', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('preferencepublicprofiledesc', 'hu', 'messages', 'Ha az <b>Igen</b>t választod, a profilod a weben publikus lesz (beleértbe a Google-t is). Figyelmeztetés: ebben az esetben bármilyen személyes információ rejtve lesz azok elől, akik nem tagok. Ha a <b>Nem</b>et választod (alapértelmezett), akkor csak regisztrált tagok láthatják a profilodat.', '2007-09-06 19:08:02', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 58692),
	('preferencepublicprofiledesc', 'id', 'messages', 'Jika anda memilih <b>Yes</b>, maka biodata anda dapat dilihat oleh umum, bahkan google. \r\nPerhatian: dalam hal ini, semua informasi pribadi akan tersembunyikan dari bukan anggota.\r\nJika anda memilih <b>No</b> (pilihan utama), hanya para anggota yang dapat melihat biodata anda.', '2007-11-07 20:48:08', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 2019),
	('preferencepublicprofiledesc', 'it', 'messages', 'Scegliendo <b>Sì</b> il tuo profilo sarà reso pubblicamente visibile su internet (Google incluso). Nota bene che, in questo caso, tutte le informazioni personali non saranno comunque visibili a chi non è membro. Se scegli <b>No</b> (valore di base) solo i membri potranno leggere il tuo profilo.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 13861),
	('preferencepublicprofiledesc', 'ku', 'messages', 'Heger tu <b>Erê</b> hibijêrî, kurtjîyanname ya te wê bibe gelemper û her kes li ser înternêtê dikare têkeve (Di google de jî). Têbîn: ev tê wate ku her agahîk taybetî wê veşartî bimîne ji yên ku ne endamin di BeWelcome de.\r\nHeger tu <b>Na</b> hibijêrî wek (Nira rêwaj) tenê endam dikarin kurtjîyanname ya te bixwînin.', '2013-11-10 15:49:45', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48359),
	('preferencepublicprofiledesc', 'lt', 'messages', 'Jei pasirinksi <b>Taip</b>, tavo profilis bus viešai prieinamas internete (įskaitant Google paieškos rezultatus), nors svarbiausią tavo asmeninę informaciją matys tik BeWelcome nariai. \r\nJei pasirinksi <b>Ne</b> (profilio statusas pagal nutylėjimą),  tavo profilį matys tik BeWelcome nariai.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('preferencepublicprofiledesc', 'lv', 'messages', 'Ja tu izvēlies <b>Jā</b>, tavs profils būs pieejams publiski tīklā (ieskaitot Google).\r\nAtceries, ka šajā gadījumā personiskā informācija netiks rādīta personām, kas nav biedri.\r\nJa tu izvēlies <b>Nē</b> (parastais iestatījums), tikai biedri varēs izlasīt tavu profilu.', '2007-08-05 16:18:26', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 375),
	('preferencepublicprofiledesc', 'nl', 'messages', 'Als je <b>ja</b> kiest zal je profiel publiek toegankelijk zijn op het internet (inclusief Google).\r\nWees gerust: je adres, telefoonnummer en chat-id zullen niet worden weergegeven aan niet-leden.\r\nAls je <b>nee</b> kiest (standaard) kunnen alleen leden je profiel zien.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('preferencepublicprofiledesc', 'pl', 'messages', 'Wybierając <b>Tak</b> Twój profil będzie publicznie dostępny w internecie (także w Google). Zauważ, że w tym przypadku osobiste informacje nadal nie będą dostępne dla niezalogowanych członków. \r\nWybierając <b>Nie</b> (domyślnie) tylko członkowie będą mogli czytać Twój profil. ', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 64183),
	('preferencepublicprofiledesc', 'pt', 'messages', 'Se escolher <b>Sim</b> o seu perfil será publicamente acessível na web (incluíndo no Google).\r\nNote que neste caso, moradas, números de telefone e ID de chat não estarão disponíveis a membros não logados.\r\nSe escolher <b>Não</b> (por defeito) apenas os membros do site poderão ler o seu perfil.', '2007-07-01 09:47:29', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 9030),
	('preferencepublicprofiledesc', 'pt-BR', 'messages', 'Se você escolher <b>Sim</b>, o seu perfil ficará publicamente acessível na internet (incluindo Google). \r\nNota: nesse caso, qualquer informação pessoal fica escondida para não-membros. Se você escolher <b>Não</b> (valor padrão), só membros poderão ler o seu perfil.', '2007-10-27 15:15:33', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15566),
	('preferencepublicprofiledesc', 'ro', 'messages', 'Dacă alegi <b>Da</b>, profilul tău va fi accesibil publicului prin intermediul internetului (inclusiv Google). Notă: În acest caz, orice informaţie personală va fi ascunsă celor ce nu sunt membri. Dacă alegi <b>Nu</b> (opţiunea implicită), numai membri vor putea să-ţi citească profilul.', '2007-09-17 17:58:45', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1081),
	('preferencepublicprofiledesc', 'ru', 'messages', 'Выбрав <b>да</b>, вы делаете свой профиль доступным для всех пользователей сети Интернет и поисковых машин (например, Google).\r\nОбращаем ваше внимание на то, что в этом случае персональная информация, указанная в профиле, не будет доступна для неавторизованных пользователей.\r\nПри выборе варианта <b>нет</b> (по умолчанию) вы позволяете видеть свой профиль только участникам.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 89307),
	('preferencepublicprofiledesc', 'sr', 'messages', 'Ако изабереш <b>Да</b>, профил ће ти бити јавно видљив на интернету (укључујући и на Гуглу), али твоје личне информације ће свакако остати сакривене.\r\nАко изабереш <b>Не</b> (подразумевано), само чланови ће моћи да прочитају твој профил.', '2012-12-19 11:57:58', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('preferencepublicprofiledesc', 'sv', 'messages', 'Om du väljer <b>Ja</b>, kommer din profil vara offentligt tillgänglig på webben (inklusive Google). Obs: I detta fall kommer all personlig information fortfarande vara dold från icke-medlemmar.\r\nOm du väljer <b>Nej</b> (standardvärde) kommer endast medlemmar kunna läsa din profil.', '2012-04-17 21:14:57', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 23263),
	('preferencepublicprofiledesc', 'tr', 'messages', 'Eğer <b>Evet</b> tercih ederseniz, profiliniz (Google dahil) internette alenen erişilebilir olur. Not: Bu durumda yine herhangi bir kişisel bilgi, üye olmayanlara saklı olacaktır. \r\nEğer <b>Hayır</b> (seçili değer) tercih ederseniz, yalnızca üye olanlar profilinizi okuyabilecektir.', '2012-11-29 21:58:41', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 35699),
	('preferencepublicprofiledesc', 'zh-hans', 'messages', '如果选择是，则资料会在网上公开（包括Google）。注意：在这种情况下，任何个人信息都将仍然对非成员隐藏。\r\n如果选择否（默认），只有成员们才能看到你的信息。', '2010-09-11 03:56:16', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11819),
	('preferencepublicprofiledesc', 'zh-hant', 'messages', '如果选择是，则资料会在网上公开（包括Google）。注意：在这种情况下，任何个人信息都将仍然对非成员隐藏。\r\n如果选择否（默认），只有成员们才能看到你的信息。', '2010-09-11 03:56:16', '2021-05-02 07:48:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11819),
	('preferenceshowmap', 'ca', 'messages', 'Mostra el mapa a "Troba membres"', '2021-10-04 23:41:28', '2021-10-04 23:41:28', '2021-10-04 23:41:28', 'no', '', 5, NULL, 304193),
	('preferenceshowmap', 'da', 'messages', 'Vis kort på find medlemmer', '2022-08-14 20:56:24', '2022-08-14 20:56:24', '2022-08-14 20:56:24', 'no', '', 5, NULL, 274594),
	('preferenceshowmap', 'de', 'messages', 'Zeige die Karte bei der Mitgliedersuche', '2021-01-29 22:44:50', '2021-01-29 22:44:50', '2021-01-29 22:44:50', 'no', '', 5, NULL, 347),
	('preferenceshowmap', 'el', 'messages', 'Εμφάνιση χάρτη στο βρείτε μέλη', '2022-12-05 06:51:12', '2022-12-05 06:51:12', '2022-12-05 06:51:12', 'no', '', 5, NULL, 266502),
	('preferenceshowmap', 'en', 'messages', 'Show map on find members', '2021-01-26 20:53:32', '2021-01-26 20:53:32', '2021-01-26 20:53:32', 'no', 'Preference\'s title on /mypreferences', 5, NULL, 1223),
	('preferenceshowmap', 'es', 'messages', 'Mostrar mapa en búsqueda de miembros', '2021-02-04 11:54:10', '2021-02-04 11:54:10', '2021-02-04 11:54:10', 'no', '', 5, NULL, 25548),
	('preferenceshowmap', 'fr', 'messages', 'Recherche de membres&nbsp;: afficher la carte', '2021-02-07 15:24:32', '2021-02-07 15:24:32', '2021-02-07 15:24:32', 'no', '', 5, NULL, 168499),
	('preferenceshowmap', 'gl', 'messages', 'Amosar o mapa para atopar persoas membro', '2021-01-27 15:06:58', '2021-01-27 15:06:58', '2021-01-27 15:06:58', 'no', '', 5, NULL, 210880),
