	('preferencestylesheet', 'tr', 'messages', 'Stil sayfası', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('preferencestylesheetdesc', 'ca', 'messages', 'Aquí pots triar entre uns quants fulls d’estil.  Escull el que més t’agradi (i no t’oblidis de refrescar el teu navegador una vegada que hagis enviat els canvis)', '2007-10-01 11:51:30', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 3236),
	('preferencestylesheetdesc', 'da', 'messages', 'Her kan du vælge mellem forskellige stylesheets, dvs. forskellige BeWelcome-layouts. (Husk at genopfriske din browsers cache efter du har skiftet stylesheet)', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 74),
	('preferencestylesheetdesc', 'de', 'messages', 'Hier kannst du zwischen verschiedenen Layouts wählen. Nimm einfach das, welches dir am besten gefällt. (Vergiss nach dem Speichern nicht, F5 zu drücken, damit das neue Layout geladen wird.)', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 15240),
	('preferencestylesheetdesc', 'en', 'messages', 'Here you will be able to choose among several style sheets, just take the one you prefer (do not forget to press F5 to refresh your browser after having submitted your new preferences)', '2007-07-19 15:44:29', '2019-04-23 18:16:49', '2008-04-13 16:16:26', 'no', '', 5, 1, 91),
	('preferencestylesheetdesc', 'eo', 'messages', 'Ĉi tie vi povas elekti de inter pluraj stiloj. Elektu la preferatan (ne forgesu klaki F5 por refreŝigi memoron de via ttt-rigardilo).', '2013-03-14 21:05:52', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 47220),
	('preferencestylesheetdesc', 'es', 'messages', 'Aquí puedes elegir entre diversos estilos de hojas, sólo tienes que escoger la que más te guste (no olvides pulsar F5 para actualizar tu  navegador después de haber enviado tus nuevas preferencias)', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1328),
	('preferencestylesheetdesc', 'fi', 'messages', 'Täältä voit valita yhden useista tyylitiedostoista. Valitse mistä tykkäät. (Älä unohda painaa F5 välimuistin päivittämiseksi tallennettuasi valinnat)', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 72),
	('preferencestylesheetdesc', 'fr', 'messages', 'Ici vous pouvez choisir parmi plusieurs feuilles de style, choisissez celle que vous préférez (n\'oubliez pas d\'appuyer sur F5 pour actualiser l\'affichage après avoir choisi votre nouveau style)', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 757),
	('preferencestylesheetdesc', 'hr', 'messages', 'Ovdje možeš odabrati neku od stilskih stranica, jednostavno odaberi jednu i nemoj zaboraviti pritisnuti F5 nakon unosa željenih postavki.', '2009-09-19 16:49:48', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 8197),
	('preferencestylesheetdesc', 'it', 'messages', 'Qui puoi scegliere tra diversi fogli di stile, scegli quello che preferisci.\r\n(Non dimenticare di cliccare F5 per aggiornare la pagina dopo aver inserito le tue nuove preferenze)', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
	('preferencestylesheetdesc', 'lt', 'messages', 'Čia jūs galite pasirinkti vieną iš kelių svetainės stiliaus variantų. Pasirinkite tą, kuris jums labiausiai patinka (nepamirškite atnaujinti savo naršyklės lango spausdami F5 po to, kai pasirinksite tam tikrą naują variantą).', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 227),
	('preferencestylesheetdesc', 'lv', 'messages', 'Šeit tev būs iespēja izvēlēties starp vairākām stila lapām, izvēlies sev vēlamo (pēc savas izvēles apstiprināšanas neaizmirsti nospiest F5, lai atjaunotu savu browser)', '2007-08-12 12:05:56', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 375),
	('preferencestylesheetdesc', 'nl', 'messages', 'Hier kun je kiezen tussen verschillende stijlen voor de website, kies gewoon degenen die je het leukst vind. (Vergeet niet om op F5 te drukken om je cache te verversen nadat je je nieuwe voorkeuren hebt ingevoerd)', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 138),
	('preferencestylesheetdesc', 'pl', 'messages', 'Tu możesz wybrać skórkę która najbardziej Ci odpowiada. \r\n(Nie zapomnij odświeżyć strony - F5 - gdy już wybierzesz)', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 213),
	('preferencestylesheetdesc', 'pt', 'messages', 'Aqui poderá escolher entre várias Style Sheets, use a que preferir\r\n(Não se esqueca de carregar em F5 para refrescar a sua Cache depois de ter feito a sua escolha)', '2007-07-01 09:39:52', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 752),
	('preferencestylesheetdesc', 'ro', 'messages', 'Aici poţi alege unul dintre multele stiluri diferite (nu uita să apeşi F5 pentru a reîncărca pagina după ce ai trimis preferinţele).', '2007-09-17 17:57:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1081),
	('preferencestylesheetdesc', 'ru', 'messages', 'Тут вы можете выбрать тот стиль сайта, который вам больше нравится. (Не забудьте нажать F5, чтобы обновить страницу после изменения настроек).', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 79),
