	('prefererenceverificationb', 'pt', 'messages', 'Todos os membros', '2013-01-26 17:32:54', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 38787),
	('prefererenceverificationb', 'pt-BR', 'messages', 'Todos os membros', '2011-09-27 22:27:12', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, 1, 15566),
	('prefererenceverificationb', 'sr', 'messages', 'Сви чланови', '2013-03-29 19:32:26', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 39772),
	('prefererenceverificationc', 'ca', 'messages', 'Membres aprovats', '2011-12-07 12:10:02', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 11944),
	('prefererenceverificationc', 'de', 'messages', 'Bestätigte Mitglieder', '2011-09-21 19:29:26', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1066),
	('prefererenceverificationc', 'en', 'messages', 'Approved members', '2011-09-10 09:40:39', '2019-04-23 18:16:49', '2011-09-10 13:17:08', 'no', 'This is a preference choice. Be careful not to pretend that volunteers are certifying name and addresses, keep in mind that they are just checking if it is a plausible one', 5, 1, 68),
	('prefererenceverificationc', 'es', 'messages', 'Sólo miembros aprobados', '2011-09-19 15:38:20', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 554),
	('prefererenceverificationc', 'fi', 'messages', 'Hyväksytyt jäsenet', '2012-05-20 20:20:33', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 72),
	('prefererenceverificationc', 'fr', 'messages', 'Seulement les membres approuvés', '2011-09-10 13:19:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 9823),
	('prefererenceverificationc', 'hr', 'messages', 'Odobreni članovi', '2012-08-22 19:11:19', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 8197),
	('prefererenceverificationc', 'it', 'messages', 'Membri approvati', '2011-09-20 09:48:14', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 16084),
	('prefererenceverificationc', 'nl', 'messages', 'Goedgekeurde leden', '2011-12-12 12:01:37', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 21169),
	('prefererenceverificationc', 'pt', 'messages', 'Membros aprovados', '2013-01-21 19:15:20', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 38787),
	('prefererenceverificationc', 'pt-BR', 'messages', 'Membros aprovados', '2011-09-27 22:27:30', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, 1, 15566),
	('prefererenceverificationc', 'sr', 'messages', 'Прихваћени чланови', '2013-03-29 19:32:37', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 39772),
	('prefererenceverificationd', 'en', 'messages', 'Who have read my profile', '2011-09-10 09:37:50', '2019-04-23 18:16:49', '2011-09-10 13:16:24', 'yes', 'I want the people who are contacting me to fill a mandatory Sentence they can find on my profile (so they must read it)', 5, 1, 68),
	('prefererenceverificationd', 'pt', 'messages', 'Que leram o meu perfil', '2019-04-30 18:19:49', '2023-09-20 05:40:14', '2019-04-30 18:19:49', 'yes', '', 5, 1, 38787),
	('prefererenceverificationdesc', 'ca', 'messages', 'Escull <b>tots els membres</b>si no tens inconvenient a ser contactat per membres que han deixat la seva adreça o nom en blanc. Escull<b>membres aprovats</b> si prefereixes ser contactat només per persones que han facilitat una identitat completa. Ves en compte, ja que BW no pot garantir al 100% que la identitat és real.', '2011-12-07 12:13:30', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 11944),
	('prefererenceverificationdesc', 'de', 'messages', 'Wähle <b>Alle Mitglieder</b>,  wenn es dir nichts ausmacht, wenn dich neue Mitglieder kontakten, die vielleicht die Adress- oder Namensfelder leergelassen haben.<br/>Wähle <b>Bestätigte Mitglieder</b> wenn du es vorziehst, nur von Mitglieder kontaktiert zu werden, die eine vollständige Identität angegeben haben. Sei aber gewarnt, denn BW kann nicht garantieren, das die Identität real ist.', '2011-09-21 19:33:54', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1066),
	('prefererenceverificationdesc', 'en', 'messages', 'Choose <b>All members</b> if you don\'t mind being contacted by just subscribed members who might have left their addresses or name empty<br/>Choose <b>Approved members</b> if you prefer being only contacted by people who have provided a full identity. Be warned that BW cannot fully guarantee that the identity is real.', '2011-09-10 09:36:44', '2019-04-23 18:16:49', '2011-09-10 13:23:48', 'no', 'This is a preference description, the one which define the criteria a member wants  the other people contacting him to match\r\n\r\nUse the same wording for bold words as for the possible preference choices\r\n', 5, 1, 70),
	('prefererenceverificationdesc', 'es', 'messages', 'Elige <b>Todos los miembros</b> si deseas ser contactado por miembros que recién se inscribieron y pueden no haber completado su nombre o dirección. <br/>Elige Choose <b>Sólo miembros aprobados</b> si prefieres ser contactado solo por aquellos que han completado su información de identidad. Ten en cuenta que de todos modos BW no puede garantizar que la identidad provista es la real. ', '2011-09-19 15:41:05', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 8437),
	('prefererenceverificationdesc', 'fr', 'messages', 'Choisissez <b>Tous les membres</b> si cela ne vous gêne pas d\'être contacté par des membres récemment inscrits qui n\'auraient pas renseigné leur adresse ou leur nom<br />Choisissez <b>Membres approuvés</b> si vous préferez n\'être sollicité que par des personnes ayant saisi une identité complète. Soyez cependant avertis que BeWelcome ne peut pas garantir que cette identité soit exacte.', '2011-09-10 13:22:22', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 9823),
	('prefererenceverificationdesc', 'it', 'messages', 'Scegli <b>Tutti i membri</b> per essere contattato anche da nuovi membri che possono avere lasciato incompleti i dati relativi all\'indirizzo e al nome.<br/>Scegli <b>Membri approvati</b> se preferisci essere contattato solo da chi ha fornito dati completi. Attenzione: BW non può garantire la vera identità dei membri.  ', '2011-09-20 10:29:45', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 16084),
	('prefererenceverificationdesc', 'nl', 'messages', 'Kies <b>Alle leden</b> als je het niet erg vind om gecontacteerd te worden door leden die nog maar net zijn ingeschreven en die misschien hun adres of naam leeg hebben gelaten.<br/>\r\nKies <b>Goedgekeurde leden</b> als je enkel gecontacteerd wilt worden door mensen die hun volledige identiteit hebben bekendgemaakt.  Wees ervan bewust dat BW niet kan garanderen dat die identiteit echt is.', '2011-12-12 15:08:13', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 21169),
	('prefererenceverificationdesc', 'pt-BR', 'messages', 'Escolha <b>Todos os membros</b> se você não se importa em ser contatado por membros que acabaram de se inscrever e que podem ter deixados seus endereços ou nomes em branco.</br>Escolha <b>Membros aprovados</b> se você preferir ser contatado apenas por pessoas que forneceram suas identidades completas. Mas saiba que o BW não pode garantir inteiramente que a identidade fornecida é real.', '2011-09-27 22:48:43', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, 1, 15566),
	('preferredlanguagesetflashnotice', 'ca', 'messages', 'S\'ha canviat el teu idioma de preferència.', '2022-03-30 13:10:07', '2022-03-30 13:10:07', '2022-03-30 13:10:07', 'no', '', 5, NULL, 26748),
