	('profile_uploadwarning', 'zh-hans', 'messages', '可接受 jpg、gif 及 png 格式. 请勿上传大于%s的文档.', '2012-12-20 15:26:50', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37722),
