	('profile.accommodation.hes.boost', 'es', 'messages', 'Muéstrame en la parte superior de los resultados de búsqueda', '2020-01-24 20:08:34', '2020-01-24 20:08:34', '2020-01-24 20:08:34', 'no', '', 5, NULL, 75125),
	('profile.accommodation.hes.boost', 'fr', 'messages', 'Afficher mon profil dans les premiers résultats de recherche', '2019-02-19 11:53:24', '2019-02-19 11:53:24', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('profile.accommodation.hes.boost', 'gl', 'messages', 'Amósame na parte alta dos resultados da procura', '2021-01-27 15:31:16', '2021-01-27 15:31:16', '2021-01-27 15:31:16', 'no', '', 5, NULL, 210880),
	('profile.accommodation.hes.boost', 'it', 'messages', 'mettimi all\'inizio della lista dei risultati della ricerca', '2019-02-20 20:28:28', '2019-02-20 20:28:28', '0000-00-00 00:00:00', 'no', '', 5, NULL, 13993),
	('profile.accommodation.hes.boost', 'nl', 'messages', 'Mij bovenaan de zoekresultaten tonen', '2020-09-21 19:29:08', '2020-09-21 19:29:08', '2020-09-21 19:29:08', 'no', '', 5, NULL, 21169),
	('profile.accommodation.hes.boost', 'pl', 'messages', 'Wyświetl mój profil na szczycie listy wyników wyszukiwania.', '2021-01-13 23:08:08', '2021-01-13 23:08:33', '2021-01-13 23:08:08', 'no', '', 5, NULL, 116789),
	('profile.accommodation.hes.boost', 'pt', 'messages', 'Mostrar-me com os primeiros resultados de pesquisa', '2019-02-07 12:28:56', '2019-02-07 12:28:56', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('profile.accommodation.hes.helptext', 'el', 'messages', 'Μπορείτε να επηρεάσετε τη θέση σας στα αποτελέσματα αναζήτησης επιλέγοντας μια ημερομηνία στο μέλλον. Όσο πιο μακριά είναι η ημερομηνία τόσο λιγότερο υψηλή γίνεται η ώθησή σας (μέγιστο 30 ημέρες). Μπορείτε επίσης να αποφασίσετε να εμφανίζεστε στο τέλος της λίστας αντί για αυτό, απενεργοποιώντας το πλαίσιο ελέγχου.', '2023-01-23 22:46:13', '2023-01-23 22:46:13', '2023-01-23 22:46:13', 'no', '', 5, NULL, 266502),
	('profile.accommodation.hes.helptext', 'en', 'messages', 'You can influence your position in search results by selecting a date in the future. The further away the date is the less high your boost becomes (maximum of 30 days). You can also decide to be shown at the end of the list instead by un-ticking the checkbox.', '2019-01-25 19:35:11', '2019-01-25 19:35:11', '0000-00-00 00:00:00', 'no', 'Help text for the hosting eagerness slider.', 5, NULL, 1),
	('profile.accommodation.hes.helptext', 'es', 'messages', 'Puedes influir en tu posición en los resultados de búsqueda seleccionando una fecha futura. Cuanto más lejana sea la fecha, menos subirás (máximo de 30 días). También puedes decidir que se te muestre al final de la lista en lugar de desmarcar la casilla.', '2020-12-04 00:46:16', '2020-12-04 00:46:16', '2020-12-04 00:46:16', 'no', '', 5, NULL, 25548),
	('profile.accommodation.hes.helptext', 'fr', 'messages', 'Vous pouvez modifier votre position dans les résultats de recherche. Pour cela, choisissez une date – plus elle est éloignée (maximum 30 jours), plus vous apparaîtrez bas dans les résultats de recherches. Vous pouvez également décider d\'apparaître dans les derniers résultats – pour cela, ne cochez pas la case.', '2019-02-19 11:58:33', '2019-02-19 11:58:33', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('profile.accommodation.hes.helptext', 'gl', 'messages', 'Pode influenciar na súa posición nos resultados da busca, seleccionando unha data no futuro. Canto máis afastada estea a data, máis se reducira o teu posicionamiento (máximo de 30 días). Tamén podes decidir aparecer no final da lista, en vez diso, desmarcando a caixa de verificación.', '2021-01-27 15:40:40', '2021-01-27 15:40:40', '2021-01-27 15:40:40', 'no', '', 5, NULL, 210880),
	('profile.accommodation.hes.helptext', 'it', 'messages', 'Potete influire sulla vostra posizione rei risultati di una ricerca inserendo una data nel futuro, per indicare per quanto tempo volete questa evidenza. Quanto più in avanti è la data, quanto minore però è la spinta in su che ricevete. Allo stesso modo potete chiedere di andare in fondo alla lista se cancellate la spunta alla casella ', '2019-02-20 21:32:14', '2019-02-20 21:32:14', '0000-00-00 00:00:00', 'no', '', 5, NULL, 13993),
	('profile.accommodation.hes.helptext', 'nl', 'messages', 'Je kan je positie in zoekresultaten beïnvloeden door een datum in de toekomst te kiezen.  Hoe verder weg de datum is hoe minder hoog je zetje (maximaal 30 dagen).  Je kan er ook voor kiezen om op het einde van de lijst getoond te worden door het vakje uit te vinken.', '2020-09-21 19:36:01', '2020-09-21 19:36:01', '2020-09-21 19:36:01', 'no', '', 5, NULL, 21169),
	('profile.accommodation.hes.helptext', 'pl', 'messages', 'Możesz wpłynąć na swoją pozycję w rezultatach wyszukiwania poprzez zaznaczenie daty w przyszłości. Im odleglejsza jest data (maks.30 dni), tym wyższe pozycjonowanie. Możesz też zdecydować o wyświetlaniu Twojego profilu na końcu listy, w tym celu odznacz okienko.', '2021-01-16 17:59:16', '2021-01-16 17:59:16', '2021-01-16 17:59:16', 'no', '', 5, NULL, 116789),
	('profile.accommodation.hes.helptext', 'pt', 'messages', 'Pode influenciar a sua posição nos resultados de pesquisa, escolhendo uma data no futuro. Quanto mais distante a data, menor o incentivo dado à sua posição (máximo de 30 dias). Pode também optar por ficar para o fim da lista, desmarcando a caixa de seleção.', '2019-02-07 13:18:17', '2019-02-07 13:18:17', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('profile.accommodation.hes.helptext', 'uk', 'messages', 'Ви можете повпливати на своє місце в результатах пошуку, вибравши дату в майбутньому. Чим далі дата, тим менше ви підійметесь в результатах (максимум 30 днів). Ви також можете вирішити, щоб вас показували в кінці списку, знявши позначку з чекбокса.', '2026-04-01 23:19:08', '2026-04-01 23:19:08', '2026-04-01 23:19:08', 'no', '', 5, NULL, 573491),
