	('profile.report.text', 'it', 'messages+intl-icu', '<p>Si prega di completare questo messaggio al Team di Sicurezza senza sovrascrivere il testo precompilato:&nbsp;</p><p>Sto segnalando il profilo ‘%s’ perché credo violi i Termini d\'Uso per i seguenti motivi:</p><p>&nbsp;</p>', '2021-04-10 11:39:14', '2024-08-28 13:48:56', '2021-04-10 11:39:14', 'no', '', 5, NULL, 2208),
