	('profilecellphonenumber', 'zh-hant', 'messages', '手機', '2010-03-09 15:02:35', '2021-05-02 07:48:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 53422),
	('profiledeleteinfo', 'de', 'messages', 'Hallo %s,\r\n\r\nWenn du BeWelcome endgültig verlassen möchtest, fülle bitte das Textfeld aus (optional) und klicke dann auf den Knopf "Profil löschen". Wenn du dein Profil nur vorübergehend deaktivieren möchtest, verwenden stattdessen bitte die Funktion "<a href="http://www.bewelcome.org/setprofileinactive">Deaktivieren</a>".', '2014-04-27 18:03:13', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('profiledeleteinfo', 'el', 'messages', 'Γεια σου, %s,\r\n\r\nΣε περίπτωση που θέλεις να εγκαταλείψεις οριστικά το BeWelcome, συμπλήρωσε το παρακάτω πλαίσιο σχολίων (προαιρετικά) και κάνε κλικ στο κουμπί «Διαγραφή προφίλ». Αν απλώς θέλεις να απενεργοποιήσεις προσωρινά το προφίλ σου, χρησιμοποίησε τη λειτουργία «<a href="https://www.bewelcome.org/setprofileinactive">Απενεργοποίηση</a>» .', '2015-08-20 08:38:58', '2020-08-26 11:52:55', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('profiledeleteinfo', 'en', 'messages', '<p>Hello %s, In case you want to leave BeWelcome completely, please fill in the comment box below (optional) and click the “Delete profile” button. If you just want to temporarily deactivate your profile, please use the “<a href="http://www.bewelcome.org/setprofileinactive">set inactive</a>” function instead.</p>', '2014-01-11 11:47:12', '2026-02-03 08:56:58', '2014-01-11 12:29:22', 'no', 'Informative text shown when a member opens the delete profile page\r\n\r\nIt contains the username so make sure to include %s where appropiate', 5, 0, 21169),
	('profiledeleteinfo', 'es', 'messages', '<p>Hola %s,&nbsp;</p><p>Si quieres abandonar BeWelcome definitivamente, por favor rellena el formulario que encontrarás a continuación (opcional) y pincha el botón "Eliminar perfil". Si sólo quieres desactivar tu perfil temporalmente, por favor utiliza la opción "<a href="http://www.bewelcome.org/setprofileinactive">pasar a inactividad</a>".</p>', '2014-02-16 20:40:19', '2023-06-18 15:35:09', '0000-00-00 00:00:00', 'no', '', 5, NULL, 25548),
	('profiledeleteinfo', 'fr', 'messages', 'Bonjour %s,\r\n\r\nSi vous décidez de quitter définitivement BeWelcome, nous vous prions de bien vouloir nous informer de la raison de votre départ, puis de cliquer sur le bouton « Supprimer mon profil ». Si vous préférez désactiver temporairement votre profil, vous pouvez choisir la <a href="http://www.bewelcome.org/setprofileinactive">fonction de désactivation</a>.', '2014-07-20 16:21:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('profiledeleteinfo', 'gl', 'messages', 'Ola %s,\r\n\r\nNo caso de que queiras deixar BeWelcome completamente, por favor completa a caixa de comentarios de máis abaixo (optional) e pincha no botón "Borrar perfil". Se só queres desactivar temporalmente o teu perfil, por favor usa no seu lugar a función "<a href="http://www.bewelcome.org/setprofileinactive">deixar inactivo</a>".', '2021-02-05 16:01:23', '2021-02-05 16:01:23', '2021-02-05 16:01:23', 'no', '', 5, NULL, 210880),
	('profiledeleteinfo', 'it', 'messages', 'Ciao %s,\r\n\r\nnel caso tu voglia lasciare BeWelcome completamente, per favore compila la casella qui sotto e clicca su "Cancella profilo". Se vuoi invece disattivare solo temporaneamente il tuo profilo, per favore usa invece la funzione "<a href="http://www.bewelcome.org/setprofileinactive">Disattiva profilo</a>".', '2014-02-22 10:50:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 44692),
	('profiledeleteinfo', 'nl', 'messages', '<p>Hallo %s,</p><p>Als je BeWelcome definitief wil verlaten, vul dan het commentaarveld hieronder in en klik op “Profiel verwijderen”. &nbsp;Wil je je profiel echter enkel tijdelijk inactief maken, gebruik dan de functie “<a href="http://www.bewelcome.org/setprofileinactive">Inactief maken</a>”.</p>', '2014-01-11 20:51:46', '2026-02-03 12:23:22', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('profiledeleteinfo', 'pl', 'messages', 'Cześć %s,\r\n\r\nJeżeli chcesz opuścić definitywnie BeWelcome, wypełnij proszę pole komentarza (opcjonalnie) i kliknij przycisk "Usuń profil". Jeśli jednak chcesz tylko zdezaktywować czasowo swój profil, użyj zamiast tego funkcji "<a href="http://www.bewelcome.org/setprofileinactive">ustaw jako nieaktywny</a>".', '2021-01-14 20:45:55', '2021-01-14 20:45:55', '2021-01-14 20:45:55', 'no', '', 5, NULL, 116789),
	('profiledeleteinfo', 'pt', 'messages', 'Olá %s,\r\n\r\nCaso pretenda deixar o BeWelcome por completo, por favor, preencha a caixa de comentários em baixo (opcional) e clique no botão "Apagar perfil". Se pretende apenas desativar temporariamente o seu perfil, por favor, use antes a funcionalidade de "<a href="http://www.bewelcome.org/setprofileinactive">desativar perfil</a>.', '2014-01-11 22:13:33', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('profiledeleteinfo', 'pt-BR', 'messages', 'Caso você queira deixar o BeWelcome completamente, por favor, preencha o campo de comentário abaixo (opcional) e clique em "Excluir Perfil". Se você só deseja desativar temporariamente sua conta, por favor, use a opção  "<a href="http://www.bewelcome.org/setprofileinactive">definir conta como inativa</a>".', '2016-12-20 16:18:15', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160059),
	('profiledeleteinfo', 'ru', 'messages', 'Привет, %s.\r\nЕсли Вы покидаете BeWelcome навсегда, пожалуйста, заполните поле для комментария ниже (это не обязательно) и нажмите кнопку "Удалить профиль". Если Вы просто ходите деактивировать свой профиль на некоторое время, пожалуйста, используйте функцию <a href="http://www.bewelcome.org/setprofileinactive">Сделать неактивным</a>.', '2014-03-29 18:21:43', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('profiledeleteinfo', 'sr', 'messages', 'У случају да пожелите да у потпуности напустите BeWelcome, молимо вас, попуните простор за коментар испод (необавезно) и кликните "обриши профил". Ако желите да привремено деактивирате свој профиле, онда кликните на "<a href="http://www.bewelcome.org/setprofileinactive">set inactive</a>" дугме.', '2014-03-14 00:05:20', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 35032),
