	('profilenotecategoryunclear', 'fr', 'messages', 'Merci de choisir une catégorie dans la liste ou d\'en créer une nouvelle. Vous avez fait les deux - merci de choisir une seule option.', '2013-04-06 08:47:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
