	('profilesetinactive', 'hu', 'messages', 'Inaktiválás', '2018-02-15 22:57:56', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15734),
	('profilesetinactive', 'hy', 'messages', 'ապաակտիվացնել', '2025-09-08 17:15:33', '2025-09-08 17:15:33', '2025-09-08 17:15:33', 'no', '', 5, NULL, 519603),
	('profilesetinactive', 'it', 'messages', 'Disattiva', '2014-02-19 13:11:49', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 44692),
	('profilesetinactive', 'nl', 'messages', 'Op inactief zetten', '2014-01-11 13:13:50', '2026-04-07 13:49:59', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('profilesetinactive', 'pl', 'messages', 'Ustaw jako nieaktywny', '2021-01-14 00:16:01', '2021-01-14 00:16:01', '2021-01-14 00:16:01', 'no', '', 5, NULL, 116789),
	('profilesetinactive', 'pt', 'messages', 'Desativar', '2014-01-02 23:49:37', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('profilesetinactive', 'pt-BR', 'messages', 'Definir como inativo', '2016-12-20 16:25:28', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160059),
	('profilesetinactive', 'ru', 'messages', 'Сделать неактивным', '2014-03-29 18:25:37', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('profilesetinactive', 'sr', 'messages', 'Деактивирај', '2014-03-14 00:09:39', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 35032),
	('profilesetinactive', 'zh-hans', 'messages', '设为闲置', '2017-05-19 05:13:47', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37722),
	('profilesetinactive', 'zh-hant', 'messages', '設定為靜默狀態', '2022-10-18 19:31:09', '2022-10-18 19:31:09', '2022-10-18 19:31:09', 'no', '', 5, NULL, 53422),
	('profilesetinactiveinfo', 'cs', 'messages', 'Když klikneš na ‚Nastavit jako neaktivní‘, tvé členství bude přepnuto na „tiché“ (shlédni <a href="/terms">Podmínky používání</a>). Tvůj profil nebude viditelný dalším členům a neobdržíš žádná upozornění z našich stránek.\r\n\r\nMůžeš se kdykoliv navrátit k aktivnímu členství, ale navrácení zpět k tichému členství bude možné až po dvou týdnech.', '2014-01-13 10:25:22', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('profilesetinactiveinfo', 'de', 'messages', 'Wenn du auf "Profil deaktivieren" klickst, wird deine Mitgliedschaft auf "still" gesetzt (siehe  <a href="/terms">Nutzungsbedingungen</a>). Dein Profil ist dann nicht mehr für andere Mitglieder sichtbar und du bekommst auch keine E-Mail-Benachrichtigungen von der Webseite mehr.\r\n\r\nDu kannst dein Profil jederzeit wieder aktivieren, eine neuerliche Deaktivierung ist jedoch erst zwei Wochen später wieder möglich.', '2014-04-27 17:54:44', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('profilesetinactiveinfo', 'el', 'messages', 'Μόλις κάνεις κλικ στην «Απενεργοποίηση», το προφίλ σου θα μετατραπεί σε «αόρατο» (δες τους <a href="/terms">Όρους Χρήσης</a>: Silent membership). Το προφίλ σου δεν θα είναι πλέον ορατό στα άλλα μέλη και δε θα λαμβάνεις πια ειδοποιήσεις από τον ιστότοπο.\r\n\r\nΜπορείς να επιστρέψεις στην Ενεργή κατάσταση οποτεδήποτε, αλλά το να επιστρέψεις πάλι πίσω στην αόρατη ιδιότητα, θα είναι εφικτό μόνο μετά από δύο εβδομάδες.', '2015-08-20 08:45:08', '2020-09-02 14:32:17', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('profilesetinactiveinfo', 'en', 'messages', 'When you click on \'Set inactive\' your membership is switched to "silent" (see <a href="/terms">Terms of Use</a>). Your profile will no longer be visible to other members and you will not get any notifications from the website anymore.\r\n\r\nYou can switch back to active membership anytime but switching back to silent membership will only be possible after two weeks.', '2013-12-27 09:05:51', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', 'Informative text shown on the set inactive page.', 5, NULL, 15240),
	('profilesetinactiveinfo', 'es', 'messages', 'Cuando desactivas tu perfil, tu perfil pasa a estar oculto (ver <a href="/terms">Condiciones de uso</a>). Tu perfil no será visible y no recibirás ningún tipo de modificación.\r\n\r\nPuedes activar tu perfil en cualquier momento. Luego deberás esperar dos semanas para poder desactivarlo.', '2014-01-06 11:35:02', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40088),
	('profilesetinactiveinfo', 'fr', 'messages', 'Il est possible de désactiver son profil (voir les <a href="/terms">conditions d\'utilisation</a>). Cette fonction permet de masquer le profil sur le réseau et de ne plus recevoir de notifications de la part du site.\r\n\r\nUn compte désactivé peut être réactivé à tout moment. S\'en suit une période de deux semaines avant de pouvoir à nouveau désactiver le profil.', '2015-08-09 20:07:14', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('profilesetinactiveinfo', 'gl', 'messages', 'Cando pinchas en "Desactivar" o teu perfil de persoa membro cambia a "silenciado" (ver <a href="/terms">Termos de Uso</a>). O teu perfil non será xa visible para outras persoas membro e non obterás notificacións do sitio web nunca máis. \r\n\r\nPodes cambialo de novo a perfil activo en calquera momento pero silencialo de novo só será posible pasadas dúas semanas.', '2021-02-06 21:24:57', '2021-02-06 21:24:57', '2021-02-06 21:24:57', 'no', '', 5, NULL, 210880),
	('profilesetinactiveinfo', 'it', 'messages', 'Quando clicchi su "Disattiva", questo verrà reso "silente" (vedi le <a href="/terms">Condizioni d\'uso</a> alla voce <i>Silent membership</i>). Il tuo profilo non sarà più visibile altri membri e non riceverai più alcuna notifica dal sito.\r\n\r\nPuoi riattivare il tuo profilo in ogni momento, ma per silenziarlo di nuovo dovrai aspettare due settimane.', '2014-02-22 10:44:11', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 44692),
	('profilesetinactiveinfo', 'nl', 'messages', 'Als je klikt op ‘Op inactief zetten’ wordt je lidmaatschap omgezet naar inactief (zie ook de <a href="/terms">Gebruiksvoorwaarden</a>). Je profiel zal niet langer zichtbaar zijn voor andere leden en je zal geen notificaties meer krijgen.\r\n\r\nJe kan terugschakelen naar een actief lidmaatschap op ieder gewenst moment, maar nogmaals terugschakelen naar inactief zal slechts mogelijk zijn na twee weken.', '2014-01-10 20:00:32', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('profilesetinactiveinfo', 'pl', 'messages', 'Po kliknięciu „Ustaw jako nieaktywne” zostaniesz czasowo „cichym” członkiem lub członkiną (zobacz <a href="/terms">Warunki użytkowania</a>). Twój profil przestanie być widoczny dla innych i nie będziesz już otrzymywać żadnych powiadomień ze strony internetowej.\r\n\r\nMożesz ponownie aktywować profil w dowolnym momencie, ale wtedy powrót do trybu „cichego” będzie możliwy dopiero po upływie dwóch tygodni.', '2021-01-17 10:16:08', '2021-01-17 10:16:08', '2021-01-17 10:16:08', 'no', '', 5, NULL, 116789),
	('profilesetinactiveinfo', 'pt', 'messages', 'Quando clicar em "Desativar" a sua inscrição passa ao estado silencioso (ver <a href="/terms">Condições de Utilização</a>). O seu perfil deixará de aparecer a outros membros e não receberá mais notificações.\r\n\r\nPode voltar a uma inscrição ativa a qualquer altura mas voltar ao modo silencioso só será possível após mais duas semanas.', '2014-01-02 23:51:43', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('profilesetinactiveinfo', 'ru', 'messages', 'Как только Вы нажмете "Сделать неактивным", Ваш профиль станет неактивным (подробнее в <a href="/terms">Правилах Использования</a>). Ваш профиль не будет виден другим участникам, и Вы больше не сможете получать сообщения с нашего сайта.\r\nВы можете активировать Ваш профиль в любое время, но повторная деактивация будет доступна только через две недели.', '2014-03-27 19:48:05', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('profilesetinactiveinfo', 'sr', 'messages', 'Кликом на "деактивирај" ваше чланство се пребацује у "тихи" модалитет (погледајте <a href="/terms">Услове коришћења</a>). Ваш профил више неће бити видљив другим члановима и више нећете добијати обавештења у вези сајта.\r\n\r\nМожете се било кад вратити у "активне" кориснике, али повратак у "тихи" модалитет рада ће поново бити могућ тек после две недеље.', '2014-03-28 14:49:24', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 35032),
	('profilesetinactiveinfo', 'zh-hans', 'messages', '点击 “设置为闲置状态” 会将你的用户状态切换乘 “缄默”（见<a href="/terms">使用条款</a>）。你的档案将不在对其他用户可见，你也不会再收到来自网站的讯息。\r\n你可以随时将用户状态切换为活跃，但若想重新切换到缄默状态则需要在两周后才能进行。', '2017-05-19 05:12:25', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37722),
	('profilesetinactiveinfo', 'zh-hant', 'messages', '<p>當您點擊“設為靜默狀態”時，您的會員資格將切換為“靜默”（請參閱<a href="/terms">使用條款</a>）。 您的個人資料將不再對其他會員可見，並且您將不再收到來自該網站的任何通知。</p><p>您可以隨時切換回活躍會員，但 &nbsp;<strong>兩週後 &nbsp;</strong>才能切換回靜默會員。</p>', '2022-10-18 19:30:12', '2022-10-18 19:34:23', '2022-10-18 19:30:12', 'no', '', 5, NULL, 53422),
	('profilesetinactivenotallowed', 'cs', 'messages', 'Nemůžeš se přepnout na neaktivní profil protože poslední přepnutí bylo dostatečně dávno. (Mezi přepnutími musí uplynout alespoň dva týdny. Poslední přepnutí bylo %1$s).', '2015-04-30 18:24:42', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('profilesetinactivenotallowed', 'de', 'messages', 'Du kannst dein Profil derzeit nicht deaktivieren, da die letzte Aktivierung noch nicht lange genug her ist (es müssen zwei Wochen ab der Aktivierung vergehen, bevor du das Profil wieder deaktivieren kannst; die letzte Aktivierung war am %1$s).', '2014-04-27 18:10:11', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('profilesetinactivenotallowed', 'el', 'messages', 'Δεν μπορείς να επιστρέψεις σε ανενεργή κατάσταση αυτή τη στιγμή καθώς η τελευταία αλλαγή σε ενεργή ήταν πρόσφατη (πρέπει να μεσολαβήσουν δύο εβδομάδες μεταξύ των αλλαγών, τελευταία αλλαγή %1$s).', '2020-08-20 08:12:50', '2020-08-28 17:51:34', '2020-08-20 08:12:50', 'no', '', 5, NULL, 266544),
	('profilesetinactivenotallowed', 'en', 'messages', 'You can\'t switch to inactive at the moment as the last switch to active didn\'t happen long enough ago (two weeks have to elapse between switches; last switch on %1$s).', '2013-12-27 09:55:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', 'Informative text shown if a member can\'t switch to silent membership at the moment as the waiting time hasn\'t elapsed yet.\r\n\r\nContains the date and time of the last switch. Make sure to include the %1$s for that.', 5, NULL, 1223),
	('profilesetinactivenotallowed', 'es', 'messages', 'No puedes desactivar tu perfil ahora mismo. El último cambio se produjo hace poco tiempo (deben pasar dos semanas entre cada cambio).', '2014-01-06 11:31:48', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40088),
	('profilesetinactivenotallowed', 'fr', 'messages', 'Vous ne pouvez pas encore désactiver votre compte, car votre dernière réactivation date de moins de deux semaines (réactivation effectuée le %1$s).', '2015-08-09 20:34:52', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('profilesetinactivenotallowed', 'gl', 'messages', 'Non podes cambiar o perfil a inactivo neste momento xa que o último cambio a activo non aconteceu fai bastante tempo (deben pasar dúas semanas entre cambios; o último cambio foi o %1$s).', '2021-02-06 21:12:26', '2021-02-06 21:12:26', '2021-02-06 21:12:26', 'no', '', 5, NULL, 210880),
	('profilesetinactivenotallowed', 'it', 'messages', 'Non puoi disattivare il tuo profilo in questo momento, poiché non è trascorso abbastanza tempo dall\'ultima volta (devo passare almeno due settimane; l\'ultima modifica risale al %1$s).', '2014-02-22 11:11:37', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 44692),
	('profilesetinactivenotallowed', 'nl', 'messages', 'Op dit moment kan je jouw profiel (nog) niet op \'inactief\' zetten omdat je laatste omschakeling naar \'actief\' nog niet lang genoeg geleden is ( er moet twee weken zitten tussen elke omschakeling : jouw laatste omschakeling was op %1$s).', '2014-01-11 13:06:10', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 22382),
	('profilesetinactivenotallowed', 'pl', 'messages', 'W tej chwili nie możesz przełączyć się na nieaktywny, ponieważ ostatnie przełączenie na aktywny nie nastąpiło wystarczająco dawno temu (między przełączeniami muszą upłynąć dwa tygodnie; ostatnia zmiana %1$s).', '2021-01-16 23:00:52', '2021-01-16 23:00:52', '2021-01-16 23:00:52', 'no', '', 5, NULL, 116789),
	('profilesetinactivenotallowed', 'pt', 'messages', 'Não pode mudar para modo inativo de momento uma vez que a última ativação ainda não aconteceu há tempo suficiente (devem passar pelo menos duas semanas entre mudanças de estado; última mudança de estado em %1$s).', '2014-01-02 23:53:42', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('profilesetinactivenotallowed', 'pt-BR', 'messages', 'Você não pode mudar para inativo no momento pois você acabou de mudar para ativo (são necessárias duas semanas para mudar de status; última mudança de status em %1$s).', '2016-12-21 12:02:40', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160059),
	('profilesetinactivenotallowed', 'ru', 'messages', 'Вы не можете деактивировать свой профиль в данный момент, так как с момента последней активации прошло недостаточно времени (между переключениями должно пройти две недели, последнее переключение состоялось %1$s).', '2014-03-29 19:16:37', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('profilesetinactivenotallowed', 'sr', 'messages', 'Не можете се сада пребацити у "неактивне" пошто сте се недуго пребацили у "активне! (потребно је да прођу две недеље између два пребацивања: последње се десило %1$s).', '2014-03-28 20:55:08', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 35032),
	('profilesetinactivesuccess', 'cs', 'messages', 'Tvůj stav členství je teď ‚tichý‘.', '2014-08-01 06:59:19', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('profilesetinactivesuccess', 'de', 'messages', 'Deine Mitgliedschaft ist jetzt stillgelegt.', '2014-04-27 18:07:45', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('profilesetinactivesuccess', 'el', 'messages', 'Βρίσκεσαι σε \'αόρατη\' λειτουργία μέλους.', '2020-07-24 11:20:00', '2020-07-24 11:21:03', '2020-07-24 11:20:00', 'no', '', 5, NULL, 266544),
	('profilesetinactivesuccess', 'en', 'messages', 'Your membership status is now \'silent\'.', '2014-01-11 10:47:08', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', 'Flash notice shown when a user switch to \'silent\' membership.', 5, NULL, 1223),
	('profilesetinactivesuccess', 'es', 'messages', 'Tu perfil está ahora en modo silencioso', '2014-09-12 10:25:53', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40088),
	('profilesetinactivesuccess', 'fr', 'messages', 'Vous êtes désormais un membre «&nbsp;silencieux&nbsp;».', '2015-08-09 20:31:39', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('profilesetinactivesuccess', 'gl', 'messages', 'O teu estado de persoa membro é agora "silenciado"', '2021-02-05 16:02:18', '2021-02-05 16:02:18', '2021-02-05 16:02:18', 'no', '', 5, NULL, 210880),
