	('proposesendagainmailtoconfirm', 'ar', 'messages', 'لتحصل على الرسالة الالكترونية مجددا و بها رابط تأكيد بريدك الألكترونى أضغط\r\n<a href="http://www.bewelcome.org/resendconfirmyourmail.php">here</a> \r\nهذه الرسالة تعرض للعضو ان يستقبل مرة اخرى بريد تأكيد طلب العضوية اذا ما فاته البريد اول مرة', '2008-02-11 05:56:30', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 2702),
	('proposesendagainmailtoconfirm', 'ca', 'messages', 'Per tornar a rebre el correu amb l\'enllaç que et permet de confirmar l\'adreça de correu electrònic, fes clic <a href="http://www.bewelcome.org/resendconfirmyourmail.php">aquí</a>.', '2007-08-29 22:20:11', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 3236),
	('proposesendagainmailtoconfirm', 'cs', 'messages', 'Abys obdržel(a) email s odkazem pro potvrzení tvé emailové adresy, prosím klikni <a href="http://www.bewelcome.org/resendconfirmyourmail.php">sem</a>.', '2014-08-01 06:33:26', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 34292),
	('proposesendagainmailtoconfirm', 'de', 'messages', 'Um eine weitere E-Mail anzufordern, durch die du deine E-Mail-Adresse bestätigen kannst, klicke <a href="http://www.bewelcome.org/resendconfirmyourmail.php">hier</a>.', '2007-07-01 09:41:05', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 15240),
	('proposesendagainmailtoconfirm', 'en', 'messages', 'To receive an e-mail with the link to confirm your e-mail address again, please click <a href="http://www.bewelcome.org/resendconfirmyourmail.php">here</a>.', '2007-05-27 15:34:16', '2019-04-23 18:16:49', '2008-04-13 16:16:26', 'no', 'This is the message proposing the member to receive again the  signup request confirm mail if he miss the previous one', 5, 1, 15240),
	('proposesendagainmailtoconfirm', 'es', 'messages', 'Para recibir otra vez el mensaje con el enlace de confirmación de correo electrónico, sólo haz click <a href="http://www.bewelcome.org/resendconfirmyourmail.php">aquí</a>', '2007-11-17 03:09:35', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 27050),
	('proposesendagainmailtoconfirm', 'fr', 'messages', 'Pour recevoir à nouveau l\'email où nous vous demandons de confirmer votre adresse <a href="http://www.bewelcome.org/resendconfirmyourmail.php">cliquez ici</a>', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('proposesendagainmailtoconfirm', 'hr', 'messages', 'Da ti ponovno pošaljemo e-mail s poveznicom za potvrdu tvoje e-mail adrese, klikni <a href="http://www.bewelcome.org/resendconfirmyourmail.php">ovdje</a> ', '2010-01-15 21:18:08', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 8197),
	('proposesendagainmailtoconfirm', 'it', 'messages', 'Per ricevere nuovamente la mail con il link per confermare il tuo indirizzo e-mail, clicca <a href="http://www.bewelcome.org/resendconfirmyourmail.php">qui</a>', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
	('proposesendagainmailtoconfirm', 'lt', 'messages', 'Jei norite dar kartą gauti el. laišką su nuoroda el. pašto adresui patvirtinti, spustelėkite <a href="http://www.bewelcome.org/resendconfirmyourmail.php">čia </a>', '2007-08-28 08:38:20', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 80),
	('proposesendagainmailtoconfirm', 'lv', 'messages', 'Lai vēlreiz saņemtu epastu ar linku tavas epasta adreses apstiprināšanai, noklikšķini uz <a href="http://www.bewelcome.org/resendconfirmyourmail.php">here</a>', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 375),
	('proposesendagainmailtoconfirm', 'nl', 'messages', 'Om de e-mail met de link om je e-mailadres te bevestigen opnieuw te ontvangen, klik <a href="http://www.bewelcome.org/resendconfirmyourmail.php">hier</a>.', '2007-09-01 19:29:28', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 40169),
	('proposesendagainmailtoconfirm', 'pl', 'messages', 'Aby ponownie otrzymać wiadomość z linkiem potwierdzającym twój adres e-mail kliknij  <a href="http://www.bewelcome.org/resendconfirmyourmail.php">tutaj</a>', '2007-09-20 14:31:53', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1554),
	('proposesendagainmailtoconfirm', 'pt', 'messages', 'Para receber novamente a mensagem com a ligação para confirmar o endereço de correio eletrónico, clique <a href="http://www.bewelcome.org/resendconfirmyourmail.php">aqui</a>', '2007-08-07 18:14:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 38787),
