	('quicksearchmembersnoresults', 'el', 'messages', 'Δεν βρέθηκαν αποτελέσματα στη γρήγορη αναζήτηση σου για  <b>%s</b> (μέρη, χρήστες).\r\n\r\nΊσως να δοκίμαζες το %s', '2020-08-20 07:08:05', '2020-08-20 07:08:05', '2020-08-20 07:08:05', 'no', '', 5, NULL, 266544),
