	('quicksearchmembersnoresults', 'fr', 'messages', 'Il n’y a pas de résultats pour la recherche «&nbsp;<b>%s</b>&nbsp;» (pas de lieu ni d’utilisateur avec ce nom).\r\n\r\nVous aurez peut-être plus de chance en cherchant %s.\r\n<br/>\r\n<br/>', '2009-06-28 10:49:47', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 9823),
