	('relationtext', 'lt', 'messages', 'Aprašykite čia savo santykį su nariu. Šis tekstas kartu su šio nario nuotrauka pasirodys jūsų anketoj.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('relationtext', 'lv', 'messages', 'Šeit tu vari aprakstīt savas attiecības ar biedru. Šis teksts parādīsies tavā profilā kopā ar biedra bildi.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 375),
