	('resetpassword', 'zh-hans', 'messages', '重置密码', '2015-06-16 08:19:49', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 12497),
	('resetpasswordbody', 'cs', 'messages', 'Ahoj %2$s,\r\nZde je tvé nové heslo k přihlášení se na BeWelcome: %1$s\r\n\r\nDoporučujeme, aby ses <a href="http://www.bewelcome.org">přihlásil(a)</a> ihned a <a href="http://www.bewelcome.org/user/password">změnil(a) si heslo</a> na něco, co si dokážeš zapamatovat.\r\n\r\nPokud ti přišel tento e-mail bez toho, abys zažádal(a) o změnu hesla, dej nám prosím vědět na <a href="http://www.bewelcome.org/feedback">stránce pro zpětnou vazbu</a>.\r\n\r\nS pozdravem,\r\nDobrovolníci', '2014-01-30 13:43:17', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1223),
	('resetpasswordbody', 'de', 'messages', 'Hallo %2$s,\r\n\r\nHier ist dein neues Passwort, um dich bei BeWelcome anzumelden: \r\n\r\n<strong>%1$s</strong>\r\n\r\nWir empfehlen, dass du dich gleich <a href="http://www.bewelcome.org">anmeldest</a> und <a href="www.bewelcome.org/mypreferences">dein Passwort änderst</a>, damit du es dir leichter merken kannst.\r\n\r\nFalls du diese E-Mail erhältst, obwohl du kein neues Passwort beantragt hast, schick uns bitte eine Nachricht über das <a href="http://www.bewelcome.org/feedback">Feedback-Formular</a>.\r\n\r\nViele Grüßen von den freiwilligen Helfern!', '2013-03-22 15:05:37', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 172939),
	('resetpasswordbody', 'el', 'messages', 'Γεια σου, %2$s,\r\nΑυτός είναι ο καινούριος κωδικός πρόσβασης στο BeWelcome:\r\n\r\n«<strong>%1$s</strong>» (αντίγραψέ τον χωρίς τα εισαγωγικά)\r\n\r\nΠροτείνουμε να <a href="http://www.bewelcome.org">συνδεθείς (login)</a> αμέσως και να <a href="http://www.bewelcome.org/mypreferences">αλλάξεις το κωδικό σου</a> σε κάτι που θα μπορείς να θυμάσαι.\r\n\r\nΑν έλαβες αυτό το ηλεκτρονικό μήνυμα χωρίς να έχεις ζητήσει αλλαγή του κωδικού σου, ενημέρωσέ μας μέσω της <a href="http://www.bewelcome.org/feedback">σελίδας επικοινωνίας</a>.\r\n\r\nΧαιρετισμούς από τους Εθελοντές', '2017-07-20 17:29:49', '2020-09-02 14:42:28', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('resetpasswordbody', 'en', 'messages', 'Hello %2$s, \r\nHere is your new password to login to BeWelcome:\r\n\r\n"<strong>%1$s</strong>" (copy without the quotes)\r\n\r\nWe recommend that you <a href="http://www.bewelcome.org">login</a> immediately and <a href="http://www.bewelcome.org/mypreferences">change your password</a> to something that you will be able to remember.\r\n\r\nIf you received this email without asking for your password to be changed, please let us know through our <a href="http://www.bewelcome.org/feedback">feedback page</a>.\r\n\r\nGreetings from the Volunteers', '2013-02-28 07:16:20', '2019-12-26 09:49:40', '2014-07-06 21:06:56', 'no', 'Message sent to member when a new password is requested.', 5, NULL, 1223),
	('resetpasswordbody', 'es', 'messages', 'Hola %2$s, \r\nAquí tienes tu nueva contraseña para BeWelcome: %1$s\r\n\r\nTe recomendamos <a href="http://www.bewelcome.org">entrar</a> iinmediatamente y <a href="http://www.bewelcome.org/user/password">cambiar tu contraseña</a> por una que puedas recordar con facilidad.\r\n\r\nSi has recibido este mensaje sin haber solicitado una nueva contraseña, puedes comunicarlo a través de nuestra <a href="http://www.bewelcome.org/feedback">página de contacto</a>.\r\n\r\nSaludos de los voluntarios!', '2013-11-08 12:17:55', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40088),
	('resetpasswordbody', 'fr', 'messages', 'Bonjour %2$s,\r\n\r\nVoici votre nouveau mot de passe BeWelcome&nbsp;: \r\n\r\n<strong>%1$s</strong>\r\n\r\nPour des raisons de sécurité, nous vous recommandons de vous <a href="http://www.bewelcome.org">connecter</a> immédiatement et de <a href="http://www.bewelcome.org/user/password">modifier votre mot de passe</a>.\r\n\r\nSi vous avez reçu cet e-mail sans avoir demandé à modifier votre mot de passe, <a href="http://www.bewelcome.org/feedback">contactez-nous</a>.\r\n\r\nBonne journée !', '2013-02-28 18:52:53', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('resetpasswordbody', 'gl', 'messages', 'Ola %2$s, \r\nAquí está o teu novo contrasinal  para acceder a BeWelcome: \r\n\r\n"<strong>%1$s</strong>" (cópiao sen as aspas)\r\n\r\nRecomendámosche que <a href="http://www.bewelcome.org">accedas</a> inmediatamente e <a href="http://www.bewelcome.org/mypreferences">cambies o teu contrasinal</a> a algo do que sexas capaz de lembrar. \r\n\r\nSe recibes este correo sen ter pedido cambiar o contrasinal, por favor, fáinolo saber a través da nosa <a href="http://www.bewelcome.org/feedback">páxina de comentarios</a>.\r\n\r\nSaúdos do Voluntariado', '2021-03-02 15:15:46', '2021-03-02 15:15:46', '2021-03-02 15:15:46', 'no', '', 5, NULL, 210880),
	('resetpasswordbody', 'hr', 'messages', 'Bok %2$s,\r\nOvdje je nova zaporka kojom ćeš se prijaviti u BeWelcome: %1$s\r\n\r\nPreporučamo da se odmah <a href="http://www.bewelcome.org">prijaviš</a> i <a href="http://www.bewelcome.org/mypreferences">promijeniš zaporku</a> u neku koju ćeš moći lakše zapamtiti.\r\n\r\nAko te ovaj mail iznenadio jer nisi tražio/la promjnu zapork, molimo te da nas o tom obavijestiš <a href="http://www.bewelcome.org/feedback">ovdje</a>.\r\n\r\nPozdrav od volontera', '2014-07-07 19:26:36', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('resetpasswordbody', 'hu', 'messages', 'Kedves Hello %2$s!\r\n\r\nA bejelentkezéshez szükséges új jelszavad:\r\n<strong>%1$s</strong>\r\n\r\nKérjük, <a href="http://www.bewelcome.org">jelentkezz be</a> most, és <a href="http://www.bewelcome.org/mypreferences">változtasd meg jelszavad</a> valami általad megjegyezhetőre.\r\n\r\nAmennyiben nem kérted jelszavad megváltoztatását, kérjük, írj nekünk a <a href="http://www.bewelcome.org/feedback">fkapcsolat oldalon</a>. \r\n\r\nÜdvözlettel,\r\nA BeWelcome önkéntes csapata', '2017-10-19 21:15:20', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15734),
	('resetpasswordbody', 'it', 'messages', 'Ciao %2$s,\r\nquesta è la tua nuova password per accedere a BeWelcome: \r\n\r\n%1$s\r\n\r\nTi raccomandiamo di <a href="https://www.bewelcome.org">accedere</a> immediatamente e <a href="https://www.bewelcome.org/mypreferences">cambiare la tua password</a> in qualcosa che tu possa ricordare.\r\n\r\nSe hai ricevuto questa mail senza aver richiesto il cambiamento della tua password, informaci attraverso la nostra <a href="https://www.bewelcome.org/about/feedback">pagina di feedback</a>. \r\n\r\nSaluti dai volontari!', '2014-08-29 17:08:26', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 13993),
	('resetpasswordbody', 'nl', 'messages', 'Hallo %2$s,\r\n\r\nDit is je nieuwe wachtwoord om je aan te melden bij BeWelcome:\r\n\r\n<strong>%1$s</strong>\r\n\r\nWe raden je aan je onmiddellijk <a href="http://www.bewelcome.org">aan te melden</a> en je wachtwoord te <a href="http://www.bewelcome.org/mypreferences">wijzigen</a>.\r\n\r\nHeb je deze e-mail ontvangen zonder dat je ons gevraagd hebt je wachtwoord te veranderen, laat ons dit dan alsjeblieft weten via de <a href="http://www.bewelcome.org/feedback">contactpagina</a>.\r\n\r\nGroeten van de vrijwilligers', '2013-02-28 19:00:54', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 42397),
	('resetpasswordbody', 'pl', 'messages', 'Witaj %2$s, \r\nOto Twoje nowe hasło do logowania na BeWelcome:\r\n\r\n"<strong>%1$s</strong>" (skopiuj bez cudzysłowów)\r\n\r\nRekomendujemy Ci <a href="http://www.bewelcome.org">zalogowanie</a> od razu i <a href="http://www.bewelcome.org/mypreferences">zmianę hasła</a> na jakieś możliwe do zapamiętania przez Ciebie.\r\n\r\nJeśli otrzymałaś/eś ten mail, mimo że nie prosiłaś/eś o zmianę hasła, skontaktuj się z nami przez naszą stronę z <a href="http://www.bewelcome.org/feedback">feedbackami</a>.\r\n\r\nSerdecznie pozdrawiamy,\r\nWolontariusze BW', '2021-01-17 00:56:05', '2021-01-17 00:56:05', '2021-01-17 00:56:05', 'no', '', 5, NULL, 116789),
	('resetpasswordbody', 'pt', 'messages', 'Olá %2$s,\r\nAqui está a sua nova senha de acesso para aceder ao BeWelcome: \r\n\r\n"<strong>%1$s</strong>" (copiar sem as aspas) \r\n\r\nRecomendamos que <a href="http://www.bewelcome.org">aceda</a> imediatamente à sua conta e <a href="http://www.bewelcome.org/mypreferences">altere a sua senha de acesso</a> para algo que seja mais fácil de recordar.\r\n\r\nSe recebeu esta mensagem sem pedir para mudar a sua senha de acesso, por favor, informe-nos através da nossa <a href="http://www.bewelcome.org/feedback">página de contacto</a>.\r\n\r\nSaudações dos Voluntários', '2013-02-28 10:33:30', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('resetpasswordbody', 'pt-BR', 'messages', 'Olá %2$s,\r\nAqui está sua nova senha para acessar o BeWelcome:\r\n\r\n<strong>%1$s</strong>\r\n\r\nNós indicamos que você <a href="http://www.bewelcome.org">acesse</a> imediatamente o site e <a href="http://www.bewelcome.org/mypreferences">mude sua senha</a> para algo que você possa se lembrar.\r\n\r\nSe você recebeu esse email sem solicitar uma mudança de senha, nos informe através de nosso <a href="http://www.bewelcome.org/feedback">formulário de contato</a>.\r\n\r\nSaudações dos Voluntários.', '2016-12-10 01:34:56', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160059),
	('resetpasswordbody', 'ru', 'messages', 'Привет, %2$s, \r\nВот Ваш новый пароль для входа на BeWelcome: %1$s \r\n\r\nМы рекомендуем, чтобы Вы <a href="http://www.bewelcome.org">вошли на сайт</a> незамедлительно и  <a href="http://www.bewelcome.org/mypreferences">изменили свой пароль</a> на тот, который Вы сможете запомнить. \r\n\r\nЕсли Вы получили это письмо без запроса на смену пароля, пожалуйста, свяжитесь с нами через нашу <a href="http://www.bewelcome.org/feedback">форму обратной связи</a>. \r\n\r\nВсегда Ваши, волонтеры  BeWelcome', '2014-05-08 15:00:09', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('resetpasswordbody', 'sr', 'messages', 'Здраво %2$s, \r\nОво је Ваша нова шифра за логовање на BeWelcome: %1$s \r\n\r\nПрепоручујемо Вам да <a href="http://www.bewelcome.org">се улогујете </a> одмах и да <a href="http://www.bewelcome.org/user/password">промените своју шифру</a> тако да нову лако запамтите. \r\n\r\nУколико сте овај мејл примили, а нисте тражили да промените шифру, обавестите нас путем наше <a href="http://www.bewelcome.org/feedback">странице за фидбек</a>. \r\n\r\nПоздрав од Волонтера', '2013-07-19 17:02:52', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 52973),
	('resetpasswordbody', 'tr', 'messages', 'Merhaba %2$s, \r\nBeWelcome giriş yapmak için yeni şifren: %1$s \r\n\r\nBir an önce <a href="http://www.bewelcome.org">giriş yapmanı</a> ve hatırlayabileceğin bir taneyle <a href="http://www.bewelcome.org/mypreferences">şifreni değiştirmeni</a> öneriyoruz.\r\n\r\nEğer talep etmediğin halde şifreni değiştirmek için bu mesajı aldıysan, <a href="http://www.bewelcome.org/feedback">geri bildirim sayfasından</a> bize ulaşmalısın.\r\nGönüllülerden selamlar.', '2014-09-19 11:12:06', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 35699),
	('resetpasswordbody', 'zh-hans', 'messages', '%2$s 你好!\r\n\r\n这是你登录 BeWelcome 的新密码:  \r\n\r\n<strong>%1$s</strong> \r\n\r\n我们建议你立即 <a href="http://www.bewelcome.org">登录</a>并<a href="http://www.bewelcome.org/mypreferences">修改密码</a>为你能记住的新密码.\r\n\r\n如果你并没有要求恢复密码而收到这封邮件, 请通过 <a href="http://www.bewelcome.org/feedback">反馈页面</a>通知我们. \r\n\r\n志愿团队向你致以诚挚的问候', '2014-07-22 15:23:23', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37722),
	('resetpassworderror', 'de', 'messages', 'Wir konnten kein Mitglied mit diesem Namen oder dieser E-Mail-Adresse finden.', '2013-03-22 14:59:06', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('resetpassworderror', 'el', 'messages', 'Δεν βρέθηκε χρήστης με αυτό το όνομα ή αυτή τη διεύθυνση ηλεκτρονικού ταχυδρομείου.', '2020-08-14 17:22:13', '2020-08-14 17:22:43', '2020-08-14 17:22:13', 'no', '', 5, NULL, 266544),
	('resetpassworderror', 'en', 'messages', 'Couldn\'t find a user with that name or email address.', '2013-02-28 07:36:04', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1223),
	('resetpassworderror', 'es', 'messages', 'No hemos podido encontrar un usuario con ese nombre o dirección de correo.', '2013-11-08 12:18:28', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40088),
	('resetpassworderror', 'fr', 'messages', 'Aucun utilisateur n\'est enregistré avec cet identifiant ou cette adresse e-mail.', '2013-02-28 14:30:43', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('resetpassworderror', 'gl', 'messages', 'Non atopamos ningunha persoa usuaria con ese nome ou enderezo de correo-e.', '2021-03-02 15:09:14', '2021-03-02 15:09:14', '2021-03-02 15:09:14', 'no', '', 5, NULL, 210880),
	('resetpassworderror', 'hy', 'messages', 'Չհաջողվեց գտնել այս անունով կամ էլ. փոստի հասցեով օգտվողի:', '2022-04-05 17:14:54', '2022-04-05 17:14:54', '2022-04-05 17:14:54', 'no', '', 5, NULL, 22128),
	('resetpassworderror', 'it', 'messages', 'Non è stato trovato un utente con questo nome o indirizzo di posta elettronica.', '2015-02-09 18:47:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('resetpassworderror', 'nl', 'messages', 'Er is geen gebruiker te vinden met die gebruikersnaam of dat e-mailadres.', '2013-02-28 19:57:28', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('resetpassworderror', 'pl', 'messages', 'Nie udało się znaleźć osobno takiej nazwie użytkownika / adresie email.', '2021-01-13 20:05:08', '2021-01-13 20:05:08', '2021-01-13 20:05:08', 'no', '', 5, NULL, 116789),
	('resetpassworderror', 'pt', 'messages', 'Nenhum utilizador foi encontrado com esse nome ou endereço.', '2013-10-08 14:58:22', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('resetpassworderror', 'ru', 'messages', 'Мы не можем найти пользователя с таким именем или электронным адресом.', '2014-05-08 15:01:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('resetpassworderror', 'sr', 'messages', 'Нисмо успели да пронађемо корисника под тим именом или са том имејл адресом.', '2013-07-19 17:03:38', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 52973),
	('resetpasswordflashnotice', 'de', 'messages', '<p>Wir haben Dir soeben eine E-Mail gesendet, die Dein neues Passwort enthält.<br />Bitte gib die dort genannten Zugangsdaten und ändere anschließend sofort Dein Passwort.</p>', '2016-02-06 10:39:04', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 174),
	('resetpasswordflashnotice', 'el', 'messages', '<p>Μόλις σου στείλαμε ένα mail με το νέο κωδικό.<br />Συμπλήρωσε τα στοιχεία σου όπως σου στάλθηκαν στο mail παρακάτω και άλλαξε άμεσα το κωδικό σου.</p>', '2020-07-24 10:35:10', '2020-09-02 21:52:09', '2020-07-24 10:35:10', 'no', '', 5, NULL, 266544),
	('resetpasswordflashnotice', 'en', 'messages', '<p>We have just sent you an email containing your new password.<br />Please enter the credentials as given in the email below and change your password immediately.</p>', '2015-05-24 17:49:56', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', 'Flash notice shown after the email with the new credentials has been sent.', 5, NULL, 1),
	('resetpasswordflashnotice', 'es', 'messages', '<p>Te acabamos de enviar un correo electrónico con tu nueva contraseña.<br />Por favor, introduce tus datos debajo como aparecen en el correo, y cambia tu contraseña cuanto antes.</p>', '2020-12-04 02:56:21', '2020-12-04 02:56:21', '2020-12-04 02:56:21', 'no', '', 5, NULL, 25548),
	('resetpasswordflashnotice', 'fr', 'messages', 'Nous vous avons envoyé un e-mail avec un nouveau mot de passe.<br />Veuillez vous connecter avec les données de connexion transmises par e-mail. N\'oubliez pas de modifier votre mot de passe.</p>', '2015-07-07 11:18:12', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('resetpasswordflashnotice', 'gl', 'messages', '<p>Acabamos de enviar un correo electrónico con unha nova contrasinal.<br />Por favor introduce as credenciais como se dan no correo de máis abaixo e cambia o teu contrasinal inmediatamente.</p>', '2021-02-03 16:20:04', '2021-02-03 16:20:04', '2021-02-03 16:20:04', 'no', '', 5, NULL, 210880),
	('resetpasswordflashnotice', 'hy', 'messages', '<p>Հենց նոր ձեզ ուղարկեցինք էլ. նամակ, որը պարունակում է ձեր նոր գաղտնաբառը։<br>Խնդրում ենք մուտքագրել ստորև նշված էլ. նամակի մուտքային տվյալները և անմիջապես փոխել ձեր գաղտնաբառը։</p>', '2026-06-18 07:07:57', '2026-06-18 07:07:57', '2026-06-18 07:07:57', 'no', '', 5, NULL, 519603),
	('resetpasswordflashnotice', 'it', 'messages', '<p>Ti abbiamo appena inviato una mail con la tua nuova password.<br />Per favore inserisci le credenziali come indicate nella mail nel campo sottostante e cambia subito la tua password.</p>', '2015-07-03 11:45:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('resetpasswordflashnotice', 'nl', 'messages', '<p>We hebben je zojuist een bericht gestuurd met je nieuwe wachtwoord.<br />Voer de toegangscodes hieronder in zoals ze in het e-mailbericht staan en verander je wachtwoord onmiddellijk.</p>', '2015-06-08 06:12:20', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40169),
	('resetpasswordflashnotice', 'pl', 'messages', '<p>Właśnie wysłaliśmy Ci email z nowym hasłem.<br />wpisz proszę poniżej dane z maila i zmień od razu swoje hasło.</p>', '2021-01-14 21:08:21', '2021-01-14 21:08:21', '2021-01-14 21:08:21', 'no', '', 5, NULL, 116789),
	('resetpasswordflashnotice', 'pt', 'messages', '<p>Enviámos-lhes uma mensagem de correio eletrónico com a sua nova senha de acesso.<br/>Por favor, indique abaixo as credenciais enviadas por correio eletrónico e altere a sua senha de acesso imediatamente.</p>', '2015-05-25 17:28:59', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('resetpasswordflashnotice', 'pt-BR', 'messages', '<p>Nós acabamos de lhe enviar um email contendo sua nova senha.<br />Por favor, siga as instruções do email e altere sua senha imediatamente.</p>', '2016-12-18 02:24:36', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160059),
	('resetpasswordflashnotice', 'ru', 'messages', '<p>Мы только что отправили вам электронное письмо с вашим новым паролем.<br>Пожалуйста, введите учетные данные, указанные в электронном письме ниже, и немедленно измените свой пароль.</p>', '2025-03-25 03:53:56', '2025-03-25 04:06:52', '2025-03-25 03:53:56', 'no', '', 5, NULL, 519603),
	('resetpasswordnologin', 'cs', 'messages', 'Tvůj profil není aktivní. Heslo nelze obnovit. Prosím kontaktuj <a href="feedback?IdCategory=3">Tým podpory</a> pro bližší informace.', '2014-01-23 21:02:13', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('resetpasswordnologin', 'de', 'messages', 'Dein Profil ist nicht aktiv. Das Passwort kann nicht zurückgesetzt werden. Bitte kontaktiere das <a href="feedback?IdCategory=3">Support Team</a> für weitere Informationen.', '2013-09-01 13:25:45', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('resetpasswordnologin', 'el', 'messages', 'Το προφίλ σου δεν είναι ενεργό. Δεν μπορεί να γίνει επαναφορά του κωδικού. Επικοινώνησε με την  <a href="feedback?IdCategory=3">Ομάδα Υποστήριξης</a> για περισσότερες πληροφορίες.', '2020-08-19 21:31:49', '2020-08-28 17:29:44', '2020-08-19 21:31:49', 'no', '', 5, NULL, 266544),
	('resetpasswordnologin', 'en', 'messages', 'Your profile is not active. The password cannot be reset. Please contact the <a href="feedback?IdCategory=3">Support Team</a> for further information.', '2013-08-30 19:42:15', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', 'Error message if a member whose profile status does not allow log in (e.g. deleted profile) tries to reset the password.', 5, NULL, 15240),
	('resetpasswordnologin', 'es', 'messages', 'Tu perfil no está activo. La contraseña no puede ser restaurada. Ponte en contacto con el <a href="feedback?IdCategory=3">Equipo de Soporte</a> para más información.', '2014-09-30 12:54:19', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 85785),
	('resetpasswordnologin', 'fr', 'messages', 'Votre profil est inactif. Impossible de réinitialiser le mot de passe. Pour en savoir plus, veuillez contacter <a href="feedback?IdCategory=3">l\'équipe d\'assistance</a>.', '2017-01-18 23:15:25', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('resetpasswordnologin', 'gl', 'messages', 'O teu perfil non está activo. O contrasinal non se pode cambiar. Por favor contacta o <a href="feedback?IdCategory=3">Equipo de Axuda</a> para máis información.', '2021-02-15 16:09:40', '2021-02-15 16:09:40', '2021-02-15 16:09:40', 'no', '', 5, NULL, 210880),
	('resetpasswordnologin', 'it', 'messages', 'Il tuo profilo non è attivo. La password non può essere resettata. Per favore contatta il <a href="feedback?IdCategory=3">Team di Supporto</a> per ulteriori informazioni.', '2015-02-09 19:05:41', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
