	('rulefornevermetcomment', 'ca', 'messages', 'No escriguis un comentari positiu o neutre sobre persones que no hagis conegut mai a la vida real!', '2007-08-01 19:59:18', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('rulefornevermetcomment', 'cs', 'messages', 'Prosím nepiš pozitivní komentáře o lidech, které jsi nikdy v životě nepotkal(a).', '2014-01-16 18:58:57', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('rulefornevermetcomment', 'da', 'messages', 'Du bør ikke skrive positive eller neutrale kommentarer om personer, som du ikke har mødt ansigt til ansigt.', '2008-06-28 08:49:48', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 74),
	('rulefornevermetcomment', 'de', 'messages', 'Bitte hinterlasse für Mitglieder, die du nie persönlich getroffen hast, keine positiven Kommentare.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('rulefornevermetcomment', 'el', 'messages', 'Μη γράφεις θετικά σχόλια για άτομα που δεν έχεις συναντήσει ποτέ στη πραγματική σου ζωή.', '2020-08-16 18:10:02', '2020-09-03 09:55:01', '2020-08-16 18:10:02', 'no', '', 5, NULL, 266544),
	('rulefornevermetcomment', 'en', 'messages', 'Please do not write positive comments about people you never met in real life.', '2007-07-19 15:50:39', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', 'This is the text concerning the rule to never write a positive or neutral comment about another member which the member has never met)', 5, NULL, 15240),
	('rulefornevermetcomment', 'eo', 'messages', 'Bonvolu nek lasi Bonan nek Neŭtralan komenton al homo kiun vi neniam renkontis fizike.', '2007-10-19 18:58:48', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1769),
	('rulefornevermetcomment', 'es', 'messages', '¡Por favor no escribas un comentario Positivo en personas que no conoces en la vida real!', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 554),
	('rulefornevermetcomment', 'eu', 'messages', 'Ez idatzi iruzkin positibo edo neutralik bizitza errealean ezagutu ez duzun inori!', '2012-12-06 19:22:21', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11907),
	('rulefornevermetcomment', 'fi', 'messages', 'Älä anna Positiivista tai Neutraalia kommenttia ihmisistä, joita et ole koskaan tavannut', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 72),
	('rulefornevermetcomment', 'fr', 'messages', 'Ne laissez pas de commentaire neutre ou positif à des membres que vous n’avez jamais rencontrés dans la vie réelle !', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 9823),
	('rulefornevermetcomment', 'gl', 'messages', 'Por favor, non escrebas comentarios positivos sobre persoas coas que non te reuniches na vida real.', '2022-03-29 10:49:50', '2022-03-29 10:49:50', '2022-03-29 10:49:50', 'no', '', 5, NULL, 210880),
	('rulefornevermetcomment', 'he', 'messages', 'נא לא להשאיר הערות חיוביות על אנשים שלא פגשתם במציאות', '2022-07-11 18:35:54', '2022-07-11 18:35:54', '2022-07-11 18:35:54', 'no', '', 5, NULL, 290109),
	('rulefornevermetcomment', 'hr', 'messages', 'Molimo te da ne pišeš pozitivne komentare o ljudima koje nisi sreo/la uživo!', '2009-08-20 19:31:12', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('rulefornevermetcomment', 'id', 'messages', 'Mohon tidak menilai Positif atau Netral pada anggota yang belum pernah anda temui secara langsung!', '2007-11-07 15:23:22', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 2019),
	('rulefornevermetcomment', 'it', 'messages', 'Per favore non lasciare commenti positivi a persone che non hai mai incontrato.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 13861),
	('rulefornevermetcomment', 'lt', 'messages', 'Prašome nerašyti Teigiamų komentarų nariams, kurių nė karto nesate sutikę!', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('rulefornevermetcomment', 'lv', 'messages', 'Lūdzu, neatzīmē Pozitīvs vai Neitrāls komentārs cilvēkiem, kurus tu nekad neesi saticis reālajā dzīvē!', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 375),
	('rulefornevermetcomment', 'nl', 'messages', 'Plaats geen positieve commentaren voor mensen die je nog nooit ontmoet hebt.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('rulefornevermetcomment', 'pl', 'messages', 'Prosimy nie wystawiać pozytywnych lub neutralnych komentarzy członkom których nigdy nie spotkałeś', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 213),
