	('safety_how', 'hy', 'messages', 'Անծանոթի ներկայությունը իմ տանը կամ անծանոթների հետ մնալը ինչպե՞ս կարող է անվտանգ լինել։', '2025-04-30 11:14:54', '2025-04-30 11:14:54', '2025-04-30 11:14:54', 'no', '', 5, NULL, 519603),
