	('safety_keepitsafe', 'hy', 'messages', 'Օգնեի՛ր մեզ պահպանել ԲիՎելքմի անվտանգությունը։', '2025-06-09 16:11:34', '2025-06-09 16:11:34', '2025-06-09 16:11:34', 'no', '', 5, NULL, 519603),
