	('safety_reactive', 'es', 'messages', 'Seguridad reactiva', '2013-11-09 13:20:43', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40088),
	('safety_reactive', 'fr', 'messages', 'Réactivité et sécurité', '2017-01-18 21:07:02', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('safety_reactive', 'gl', 'messages', 'Traballo de seguridade reactivo', '2021-01-19 16:37:25', '2021-01-19 16:37:25', '2021-01-19 16:37:25', 'no', '', 5, NULL, 210880),
	('safety_reactive', 'it', 'messages', 'Attività di gestione dei problemi di sicurezza', '2013-07-07 20:54:33', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 44692),
	('safety_reactive', 'nl', 'messages', 'Reactieve veiligheidswerkzaamheden', '2013-07-04 21:53:19', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40169),
	('safety_reactive', 'pl', 'messages', 'Reaktywna praca nad bezpieczeństwem', '2021-01-13 20:36:24', '2021-01-13 20:36:24', '2021-01-13 20:36:24', 'no', '', 5, NULL, 116789),
	('safety_reactive', 'pt', 'messages', 'Trabalho de segurança reativo', '2013-08-12 11:25:14', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('safety_reactive', 'ru', 'messages', 'Корректирующая работа по безопасности', '2014-04-30 18:02:52', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('safety_reactive', 'sr', 'messages', 'Реактиван сигурносни рад', '2015-02-02 21:32:10', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('safety_reactive', 'uk', 'messages', 'Реактивна робота з безпеки', '2026-04-05 22:50:30', '2026-04-05 22:50:30', '2026-04-05 22:50:30', 'no', '', 5, NULL, 573491),
	('safety_reactive', 'zh-hant', 'messages', '被動式安全工作', '2025-05-31 18:15:54', '2025-05-31 18:15:54', '2025-05-31 18:15:54', 'no', '', 5, NULL, 53422),
	('safety_reactivetext', 'cs', 'messages', '<ul class="bullet"><li>Řešíme a vyšetřujeme nahlášení zneužití.</li><li>Kontaktujeme členy spojené s konflikty nahlášenými bezpečnostnímu týmu.</li><li>Nabízíme pomoc při psaní negativních komentářů po případech zneužití.</li><li>Bereme nezbytné kroky, abychom ujistili, že členové se chovají podle <a href="terms">Podmínek používání</a> BeWelcome.</li><li>Rozesíláme informace či oficiální varování členům, pokud nesplňují Podmínky používání.</li><li>Zakazujeme členům vstup na BeWelcome za těžké, opakované, či bezostyšné zneužívání.</li></ul>', '2014-01-18 14:13:33', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('safety_reactivetext', 'de', 'messages', '<ul class="bullet"><li>Wir kümmern uns um Missbrauchsfälle und stellen Nachforschungen an, wenn sie uns angezeigt werden.</li><li>Wir kontaktieren Mitglieder, die in die dem Sicherheitsteam angezeigten Konflikte involviert sind.</li><li>Wir bieten Unterstützung beim Verfassen von negativen Kommentaren in Missbrauchsfällen.</li><li>Wir leiten die nötigen Schritte ein, damit sich Mitglieder gemäß der <a href="terms">Nutzungsbedingungen</a> von BeWelcome verhalten.</li><li>Wir informieren oder verwarnen Mitglieder, die sich nicht an die Nutzungsbedingungen halten.</li><li>Wir beenden die Mitgliedschaft von BeWelcome Mitgliedern bei schwerem, wiederholtem oder offensichtlichem Missbrauch der Nutzungsbedingungen.</li></ul> \r\n', '2013-11-23 19:24:34', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37859),
	('safety_reactivetext', 'el', 'messages', '<ul class="bullet"><li>Χειριζόμαστε και ερευνούμε τις αναφορές κατάχρησης.</li><li>Επικοινωνούμε με μέλη που εμπλέκονται σε διαμάχες οι οποίες αναφέρονται στην ομάδα ασφαλείας.</li><li>Προσφέρουμε βοήθεια με τη συγγραφή αρνητικών σχολίων μετά από περιπτώσεις κατάχρησης.</li><li>Κάνουμε απαραίτητα βήματα για να σιγουρευτούμε ότι τα μέλη συμπεριφέρονται σύμφωνα με τους <a href="terms">όρους χρήσης</a> του BeWelcome.</li><li>Στέλνουμε πληροφορίες ή επίσημες προειδοποιήσεις σε μέλη, σε περίπτωση που δεν συμμορφώνονται με τους όρους χρήσης.</li><li>Αποκλείουμε μέλη από το BeWelcome για σοβαρή, επαναλαμβανόμενη ή καταφανή κατάχρηση.</li></ul>', '2017-08-02 16:08:13', '2020-09-02 15:33:21', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('safety_reactivetext', 'en', 'messages', '<ul><li>We handle and investigate abuse reports.</li><li>We contact members involved in conflicts reported to the safety team.</li><li>We offer help with writing negative comments in case of abuse.</li><li>We take necessary steps to make sure that member conduct complies with the <a href="terms">terms of use</a>.</li><li>We send information or official warnings to members in case they do not comply with the terms of use.</li><li>We ban members from BeWelcome for severe, repeated, or blatant abuse.</li></ul>', '2013-06-23 19:54:19', '2023-01-22 09:13:46', '0000-00-00 00:00:00', 'no', 'text on safety team page', 5, 0, 2208),
	('safety_reactivetext', 'es', 'messages', '<ul><li>Gestionamos e investigamos los informes de abuso.</li><li>Contactamos con las personas involucradas en los conflictos denunciados al equipo de seguridad.</li><li>Ofrecemos ayuda para escribir comentarios negativos en casos de abuso.</li><li>Damos los pasos necesarios para asegurar que cada miembros se comporte de acuerdo con los <a href="terms">Términos de uso</a>.</li><li>Enviamos información o advertencias oficiales para miembros que no respeten las condiciones de uso.</li><li>Expulsamos a miembros de BeWelcome por abusos graves, reincidentes o flagrantes.</li></ul>', '2013-11-09 13:25:17', '2023-05-29 10:42:07', '0000-00-00 00:00:00', 'no', '', 5, NULL, 25548),
	('safety_reactivetext', 'fr', 'messages', '<ul><li>Nous recevons les rapports concernant des abus et nous menons une enquête.</li><li>Nous contactons les membres impliqués dans les conflits signalés à l’équipe de sécurité.</li><li>Nous offrons de l’aide pour la rédaction des commentaires négatifs en cas d’abus.</li><li>Nous faisons le nécessaire pour que les membres adoptent un comportement en conformité avec les <a href="terms/fr">conditions d\'utilisation</a> de BeWelcome.</li><li>Nous envoyons des informations complémentaires et des mises en garde aux membres s’ils ne les respectent pas.</li><li>Nous bannissons les membres en cas d’abus caractérisé, grave ou répété.</li></ul>', '2017-01-18 22:46:30', '2023-12-30 10:43:18', '0000-00-00 00:00:00', 'no', '', 5, NULL, 168499),
	('safety_reactivetext', 'gl', 'messages', '<ul><li>Xestionamos e investigamos as denuncias de abusos.</li><li>Poñémonos en contacto con persoas da comunidade que están envoltas en conflitos dos que se informou ao Equipo de Seguridade.</li><li>Ofrecemos axuda para escribir comentarios negativos despois de casos de abuso.</li><li>Tomamos as medidas necesarias para garantir que a conduta das persoas da comunidade se adecúa aos <a href="terms">termos de uso</a>.</li><li>Enviamos información ou avisos oficiais ás persoas da comunidade no caso de que non cumpran cos termos de uso.&nbsp;</li><li>Expulsamos a persoas de BeWelcome por abusos severos, repetidos ou patentes.</li></ul>', '2021-01-19 16:44:05', '2023-10-26 08:34:05', '2021-01-19 16:44:05', 'no', '', 5, NULL, 210880),
	('safety_reactivetext', 'it', 'messages', '<ul class="bullet"><li>Gestiamo e verifichiamo le segnalazioni di abuso.</li><li>Contattiamo i membri coinvolti nei conflitti segnalati alla Squadra Sicurezza.</li><li>Offriamo aiuto nella stesura di commenti negativi in conseguenza a casi di abuso.</li><li>Prendiamo le misure necessarie per assicurarci che i membri si comportino confermemente alle <a href="terms">condizioni d\'uso</a> di BeWelcome.</li><li>Notifichiamo o inviamo avvertimenti ufficiali ai membri che non si adeguano alle condizioni d\'uso.</li><li>Bandiamo da BeWelcome membri che abbiamo commesso gravi, ripetuti o palesi abusi.</li></ul>', '2013-07-07 21:05:52', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 44692),
	('safety_reactivetext', 'nl', 'messages', '<ul><li>We behandelen en onderzoeken misbruikmeldingen.</li><li>We nemen contact op met leden die betrokken zijn bij conflicten die aan het veiligheidsteam gemeld worden.</li><li>We bieden hulp bij het schrijven van negatieve commentaren na gevallen van misbruik.</li><li>We nemen de noodzakelijke stappen om ervoor te zorgen dat leden zich houden aan de <a href="terms">gebruiksvoorwaarden</a>.</li><li>We sturen informatie of officiële waarschuwingen aan leden in het geval ze zich niet houden aan de gebruiksvoorwaarden.</li><li>We verbannen leden van BeWelcome voor ernstige, herhaalde of schaamteloze gevallen van misbruik.</li></ul>', '2013-07-04 21:58:32', '2023-09-23 12:38:38', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('safety_reactivetext', 'pl', 'messages', '<ul class = "bullet"> <li> Zajmujemy się zgłoszeniami nadużyć i badamy je dokładnie. </li> <li> Kontaktujemy się z członkami i członkiniami, którzy są stronami konfliktów zgłoszonych Zespołowi ds. Bezpieczeństwa. </li> <li> Proponujemy pomoc przy pisaniu negatywnych komentarzy w przypadkach nadużyć. </li> <li> Podejmujemy wszelkie niezbędne kroki, by upewnić się, że osoby należące do naszej społeczności postępują zgodnie z <a href="terms"> warunkami korzystania z </a> BeWelcome. </li> <li> Wysyłamy wiadomości lub oficjalne ostrzeżenia do członków, którzy łamią nasze warunki użytkowania. </li> <li> Wreszcie banujemy członków i członkinie BeWelcome w przypadkach poważnych, powtarzających się lub rażących nadużyć. </ li > </ul>', '2021-01-16 19:57:21', '2021-01-16 19:57:21', '2021-01-16 19:57:21', 'no', '', 5, NULL, 116789),
	('safety_reactivetext', 'pt', 'messages', '<ul><li>Lidamos com e investigamos relatórios de abuso.</li><li>Contactamos membros envolvidos em conflitos reportados à equipa de segurança.</li><li>Oferecemos ajuda a escrever comentários negativos em casos de abuso.</li><li>Tomamos os passos necessários para assegurar que os membros se comportam de acordo com as <a href="terms">condições de utilização</a>.</li><li>Enviamos informação ou avisos oficiais para membros que não respeitem as condições de utilização.</li><li>Expulsamos membros do BeWelcome que tenham abusado do sistema de forma séria, repetida ou descaradamente.</li></ul>', '2013-08-12 17:11:30', '2023-07-05 10:57:42', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('safety_reactivetext', 'ru', 'messages', '<ul class="bullet"><li>Мы изучаем и расследуем сообщения о нарушениях.</li><li>Мы контактируем с участниками, вовлеченными в конфликт, указанный в сообщении для Команды Безопасности.</li><li>Мы оказываем помощь в написании негативных комментариев по факту нарушений.</li><li>Мы предпренимаем необходимы шаги, чтобы обеспечить выполнения <a href="terms">Правила Использования BeWelcome</a>.</li><li>Мы высылаем информационные сообщения и официальные предупреждения в случае нарушения правил участниками.</li><li>Мы баним участников BeWelcome за серьезные, повторяющиеся и явные нарушения.</li></ul>', '2014-04-29 17:18:20', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('safety_reactivetext', 'sr', 'messages', '<ul class="bullet"><li>Преузимамо и испитујемо пријаве о злоупотреби.</li><li>Контактирамо чланове укључене у сукоб, који је пријављен сигурносном тиму.</li><li>Нудимо помоћ у писању негативних коментара после случаја злоупотребе.</li><li>Предузимамо неопходне кораке да би се уверили да се чланови понашају у складу са <a href="terms">условима коришћења</a>.</li><li>Шаљемо информације или званична упозорења члановима у случају да они не поштују услове коришћења.</li><li>Искључујемо чланове из BeWelcome због озбиљних, понављајућих злоупотреба или лошег понашања.</li></ul>', '2015-01-22 12:10:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('safety_reactivetext', 'uk', 'messages', '<ul><li>Ми обробляємо та розслідуємо повідомлення про зловживання.</li><li>Ми зв\'язуємося з учасниками, залученими до конфліктів, про які повідомила команда безпеки.</li><li>Ми пропонуємо допомогу у написанні негативних коментарів у разі зловживання.</li><li>Ми вживаємо необхідних заходів, щоб переконатися, що поведінка учасників відповідає <a href="terms">умовам використання</a>.</li><li>Ми надсилаємо інформацію або офіційні попередження учасникам у разі, якщо вони не дотримуються умов використання.</li><li>Ми блокуємо учасників BeWelcome за серйозні, повторювані або явні зловживання.</li></ul>', '2026-04-05 22:51:12', '2026-04-05 22:51:12', '2026-04-05 22:51:12', 'no', '', 5, NULL, 573491),
	('safety_reactivetext', 'zh-hant', 'messages', '<ul><li>我們處理並調查濫用報告。</li><li>我們聯繫涉及衝突的成員。</li><li>我們在濫用情況下，協助撰寫負面評論。</li><li>我們採取必要措施確保成員行為符合使用條款。</li><li>我們向不遵守使用條款的會員發送通知或正式警告。</li><li>對於嚴重、重複或明顯的濫用，我們會禁止該會員使用 BeWelcome。</li></ul>', '2025-05-31 18:15:33', '2025-05-31 18:15:33', '2025-05-31 18:15:33', 'no', '', 5, NULL, 53422),
