	('safety_teamintro', 'en', 'messages', 'The Safety Team takes care of member safety.', '2013-06-23 19:51:53', '2023-01-22 09:03:26', '0000-00-00 00:00:00', 'no', 'text on safety team page', 5, 0, 2208),
	('safety_teamintro', 'es', 'messages', 'El Equipo de Seguridad vela por la seguridad de las personas.', '2013-11-09 13:14:31', '2023-05-29 10:46:44', '0000-00-00 00:00:00', 'no', '', 5, NULL, 25548),
