	('safety_teamintro', 'gl', 'messages', 'O Equipo de Seguridade coida da seguridade das persoas da comunidade.', '2021-01-19 16:30:22', '2023-10-26 08:37:20', '2021-01-19 16:30:22', 'no', '', 5, NULL, 210880),
	('safety_teamintro', 'it', 'messages', 'La Squadra Sicurezza (<i>Safety Team</i>) si prende cura della sicurezza dei membri.', '2013-06-26 15:43:41', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 44692),
