	('safety_teamintro', 'pl', 'messages', 'Zespół ds. Bezpieczeństwa odpowiada za dbanie o bezpieczeństwo członków i członkiń.', '2021-01-14 18:40:49', '2021-01-14 18:40:49', '2021-01-14 18:40:49', 'no', '', 5, NULL, 116789),
