	('safety_tipsoverview', 'zh-hant', 'messages', '安全提示', '2015-11-02 15:30:49', '2021-05-02 07:48:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 68078),
	('safety_tipsoverviewtext', 'ar', 'messages', '<ul class="bullet"><li><a href="safety/faq">اقرؤوا الأسئلة التي تتردد كثيراً حول الأمان</a></li><li><a href="safety/tips#general">نصائح عامة حول الأمان</a></li><li><a href="safety/tips#female">نصائح الأمان للمسافرات الإناث</a></li></ul> ', '2013-07-09 10:38:18', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 554),
	('safety_tipsoverviewtext', 'cs', 'messages', '<ul class="bullet"><li><a href="safety/faq">Časté dotazy ohledně bezpečnostních problémů</a></li><li><a href="safety/tips#general">Obecné tipy pro vyšší bezpečnost</a></li><li><a href="safety/tips#female">Bezpečnostní tipy pro samotné cestovatelky</a></li></ul> ', '2014-01-13 10:05:41', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('safety_tipsoverviewtext', 'de', 'messages', '<ul class="bullet"><li><a href="safety/faq">Lies unsere FAQs zum Thema Sicherheit</a></li><li><a href="safety/tips#general">Allgemeine Sicherheitstipps</a></li><li><a href="safety/tips#female"">Sicherheitstipps für alleinreisende Frauen</a></li></ul>', '2013-11-18 19:02:39', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1223),
	('safety_tipsoverviewtext', 'el', 'messages', '<ul class="bullet"><li><a href="safety/faq">Διάβασε τις συνήθεις ερωτήσεις μας πάνω σε θέματα ασφαλείας</a></li><li><a href="safety/tips#general">Γενικές συμβουλές ασφαλείας</a></li><li><a href="safety/tips#female">Συμβουλές ασφαλείας για γυναίκες που ταξιδεύουν μόνες</a></li></ul>', '2015-08-10 13:43:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 64914),
