	('safety_tipsoverviewtext', 'es', 'messages', '<ul class="bullet"><li><a href="safety/faq">Lee nuestras FAQs sobre problemas de seguridad</a></li><li><a href="safety/tips#general">Consejos generales de seguridad</a></li><li><a href="safety/tips#female">Consejos de seguridad para mujeres que viajan solas</a></li></ul>', '2013-07-04 00:28:35', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 554),
