	('safety_tipsoverviewtext', 'hr', 'messages', '<ul class="bullet"><li><a href="safety/faq">Pročitajte odgovore na najčešća pitanja o sigurnosti</a></li><li><a href="safety/tips#general">Opći savjeti za sigurno putovanje</a></li><li><a href="safety/tips#female"">Savjeti za sigurno putovanje za solo putnice</a></li></ul>', '2013-10-03 19:55:08', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('safety_tipsoverviewtext', 'hu', 'messages', '<ul class="bullet"><li><a href="safety/faq">Olvasd el a GYIK biztonsági tanácsok részét</a></li><li><a href="safety/tips#general">Általános biztonsági tanácsok</a></li><li><a href="safety/tips#female">Biztonsági tanácsok egyedül utazó nőknek</a></li></ul> ', '2017-10-21 13:11:19', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15734),
	('safety_tipsoverviewtext', 'hy', 'messages', '<ul><li><a href="https://beta.bewelcome.org/safety/faq">Կարդալ մեր Հաճախ տրվող հարց ու պատասխանները անվտանգության խնդիրների մասին</a></li><li><a href="https://beta.bewelcome.org/safety/tips#general">Անվտանգության ընդհանուր խորհուրդներ</a></li><li><a href="https://beta.bewelcome.org/safety/tips#female">Անվտանգության խորհուրդներ միայնակ կին ճանապարհորդների համար</a></li></ul>', '2025-04-06 13:52:59', '2025-04-06 13:52:59', '2025-04-06 13:52:59', 'no', '', 5, NULL, 519603),
	('safety_tipsoverviewtext', 'it', 'messages', '<ul class="bullet"><li><a href="safety/faq">Leggi la FAQ sulle questioni di sicurezza</a></li><li><a href="safety/tips#general">Consigli generali per la sicurezza</a></li><li><a href="safety/tips#female">Consigli per le donne che viaggiano da sole</a></li></ul> ', '2013-07-04 10:21:18', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 554),
	('safety_tipsoverviewtext', 'nl', 'messages', '<ul class="bullet"><li><a href="safety/faq">Lees de veelgestelde vragen over veiligheidszaken</a></li><li><a href="safety/tips#general">Algemene veiligheidstips</a></li><li><a href="safety/tips#female">Veiligheidstips for vrouwen die alleen reizen</a></li></ul> ', '2013-07-10 07:02:33', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40169),
