	('safety_trustworthy', 'hu', 'messages', 'Honnan tudjam, kiben lehet megbízni?', '2018-02-15 23:02:25', '2020-05-25 14:03:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 36939),
	('safety_trustworthy', 'hy', 'messages', 'Ինչպե՞ս կարող եմ հասկանալ, արդյոք մասնակիցը վստահելի է:', '2025-06-09 16:55:33', '2025-06-09 16:55:33', '2025-06-09 16:55:33', 'no', '', 5, NULL, 519603),
