	('safety_trustworthy', 'lt', 'messages', 'Kaip galiu įvertinti, ar narys patikimas?', '2021-02-20 00:03:28', '2021-02-20 00:03:28', '2021-02-20 00:03:28', 'no', '', 5, NULL, 285578),
	('safety_trustworthy', 'nl', 'messages', 'Hoe kom ik te weten of een lid vertrouwenswaardig is?', '2013-07-05 18:30:41', '2026-02-03 13:26:12', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
