	('safety_trustworthy', 'pt', 'messages', 'Como posso saber se outro membro é de confiança?', '2013-08-12 11:32:31', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
