	('safety_uncomfortablesituation', 'en', 'messages', 'What to do in an uncomfortable situation?', '2013-06-23 17:29:41', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', 'subheading on safety main page', 5, NULL, 158),
	('safety_uncomfortablesituation', 'es', 'messages', '¿Qué hacer en una situación incómoda?', '2013-07-04 00:21:35', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 65289),
