	('safety_uncomfortablesituation', 'fr', 'messages', 'Que faire si la situation devient gênante&nbsp;?', '2013-09-02 01:34:48', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('safety_uncomfortablesituation', 'gl', 'messages', 'Que facer nunha situación incómoda?', '2021-01-12 16:15:42', '2021-01-12 16:15:42', '2021-01-12 16:15:42', 'no', '', 5, NULL, 210880),
	('safety_uncomfortablesituation', 'he', 'messages', 'מה לעשות במצב לא נעים?', '2022-03-25 12:58:42', '2022-03-25 12:58:42', '2022-03-25 12:58:42', 'no', '', 5, NULL, 290109),
	('safety_uncomfortablesituation', 'hu', 'messages', 'Mit tegyek, ha kellemetlen helyzetben találom magam?', '2018-02-15 23:02:40', '2020-05-25 11:42:43', '0000-00-00 00:00:00', 'no', '', 5, NULL, 36939),
	('safety_uncomfortablesituation', 'hy', 'messages', 'Ի՞նչ անել անհարմար իրավիճակում.', '2025-04-06 12:55:55', '2025-04-06 12:55:55', '2025-04-06 12:55:55', 'no', '', 5, NULL, 519603),
	('safety_uncomfortablesituation', 'it', 'messages', 'Cosa fare in una situazione sgradevole?', '2013-07-04 09:51:35', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 16084),
	('safety_uncomfortablesituation', 'lt', 'messages', 'Ką daryti nemalonioje situacijoje?', '2021-02-20 00:04:04', '2021-02-20 00:04:04', '2021-02-20 00:04:04', 'no', '', 5, NULL, 285578),
	('safety_uncomfortablesituation', 'nl', 'messages', 'Wat te doen in een onaangename situatie?', '2013-07-07 10:26:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('safety_uncomfortablesituation', 'pl', 'messages', 'Co zrobić w niewygodnej sytuacji?', '2020-06-08 08:55:17', '2021-03-21 17:21:14', '2020-06-08 08:55:17', 'no', '', 5, NULL, 116789),
	('safety_uncomfortablesituation', 'pt', 'messages', 'O que fazer numa situação desconfortável?', '2013-08-12 11:34:52', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('safety_uncomfortablesituation', 'pt-BR', 'messages', 'O que fazer numa situação desconfortável? ', '2014-09-06 06:52:50', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160059),
	('safety_uncomfortablesituation', 'ru', 'messages', 'Что делать в некомфортной ситуации?', '2014-05-02 08:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('safety_uncomfortablesituation', 'sl', 'messages', 'Kaj storiti ob neprijetni situaciji?', '2019-05-03 21:51:54', '2019-05-03 21:51:54', '2019-05-03 21:51:54', 'no', '', 5, NULL, 106553),
	('safety_uncomfortablesituation', 'sr', 'messages', 'Шта радити у непријатној ситуацији?', '2013-07-17 09:35:52', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('safety_uncomfortablesituation', 'sv', 'messages', 'Vad du ska göra i en obekväm situation?', '2013-07-18 16:15:48', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 23263),
	('safety_uncomfortablesituation', 'tr', 'messages', 'Rahatsız edici bir durumda ne yapmalı?', '2014-09-19 10:28:05', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 35699),
	('safety_uncomfortablesituation', 'uk', 'messages', 'Що робити в незручній ситуації?', '2026-04-03 19:11:01', '2026-04-03 19:11:01', '2026-04-03 19:11:01', 'no', '', 5, NULL, 573491),
	('safety_uncomfortablesituation', 'vi', 'messages', 'Nên làm gì trong một tình huống khó xử?', '2021-06-24 06:49:58', '2021-06-24 06:49:58', '2021-06-24 06:49:58', 'no', '', 5, NULL, 293926),
	('safety_uncomfortablesituation', 'zh-hans', 'messages', '怎么处理不自在的处境？', '2013-07-04 14:42:39', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37722),
	('safety_uncomfortablesituation', 'zh-hant', 'messages', '在感到不舒服的情況下該怎麼辦？', '2020-06-23 20:05:35', '2021-05-02 07:48:37', '2020-06-23 20:05:35', 'no', '', 5, NULL, 53422),
	('safety_uncomfortablesituationintro', 'ar', 'messages', 'قد تصبح تجربة الاستضافة غير مريحة في بعض الأحيان: لا تشعر بالراحة أو أنك تشعر بأن الأمور ليست على ما يرام؟ يمكن أن يكون مضيفك أو ضيفك يتحدث أو يتصرف بطريقة تضايقك؟  <a href="safety/whattodo#uncomfortable">اضغط هنا للحصول على نصائح حول كيفية التصرف في مثل هذه الحالات.</a> ', '2013-07-09 12:30:42', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48937),
	('safety_uncomfortablesituationintro', 'ca', 'messages', 'A vegades una experiència d\'hospitalitat pot esdevenir incòmoda: et sents incòmode o hi ha quelcom que no se sent bé? Pot ser que et molesti la forma d\'actuar o comunicar-se del teu hoste o convidat?', '2022-02-04 10:45:51', '2022-02-04 10:45:51', '2022-02-04 10:45:51', 'no', '', 5, NULL, 26748),
	('safety_uncomfortablesituationintro', 'cs', 'messages', 'Někdy se může stát zážitek s pohostinností nepohodlným: Cítíš se neklidně nebo se ti něco nezdá? Možná tvůj hostitel či host komunikuje nebo se chová způsobem, který tě irituje? <a href="safety/whattodo#uncomfortable">Přečti si tipy o tom, co dělat v takovýchto situacích.</a>', '2014-01-16 22:59:41', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('safety_uncomfortablesituationintro', 'de', 'messages', 'Manchmal kann eine Gast(geber)situation unangenehm werden: Du hast ein ungutes Gefühl, etwas scheint einfach nicht richtig zu sein? Vielleicht kommuniziert oder handelt der Gast(geber) auf eine Art, die Dich stört?', '2013-11-18 19:01:18', '2021-02-12 21:49:09', '0000-00-00 00:00:00', 'no', '', 5, NULL, 347),
	('safety_uncomfortablesituationintro', 'el', 'messages', 'Καμιά φορά, η εμπειρία της φιλοξενίας μπορεί να γίνει άβολη: Αισθάνεσαι αμήχανα ή κάτι δεν σου φαίνεται σωστό; Ίσως ο οικοδεσπότης σου ή ο φιλοξενούμενός σου επικοινωνεί ή συμπεριφέρεται με τρόπο που σε ενοχλεί;', '2015-08-10 13:33:43', '2023-06-10 05:51:32', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266502),
	('safety_uncomfortablesituationintro', 'en', 'messages', 'Sometimes a hospitality experience can become uncomfortable: You feel uneasy or something does not seem right? Maybe your host or guest communicates or acts in a way which irritates you?', '2013-06-23 18:46:54', '2020-09-26 11:43:07', '0000-00-00 00:00:00', 'no', 'text on safety main page', 5, 0, 347),
	('safety_uncomfortablesituationintro', 'es', 'messages', 'Algunas veces una experiencia de hospitalidad puede volverse incómoda: ¿Sientes intranquilidad o te parece que algo no va bien? ¿Tal vez tu huésped se comunica o actúa de una manera que te molesta?', '2013-07-04 22:11:23', '2022-07-02 13:15:19', '0000-00-00 00:00:00', 'no', '', 5, NULL, 25548),
	('safety_uncomfortablesituationintro', 'fr', 'messages', 'Parfois, l\'expérience met mal à l\'aise, la communication est difficile ou quelque chose ne tourne pas rond. Votre hôte·sse ou invité·e parle ou agit de manière désagréable ? <a href="safety/whattodo#uncomfortable">Vous trouverez ici des conseils pour bien réagir.</a>', '2013-09-02 01:49:01', '2020-06-15 21:27:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('safety_uncomfortablesituationintro', 'gl', 'messages', 'As veces unha experiencia de hospedaxe pode volverse incómoda: Sénteste desapracible ou algo parece non ir ben? Quizais o teu anfitrión ou hospede se comunica ou actúa dun xeito que te anoxa?', '2021-01-12 16:21:45', '2021-01-12 16:21:45', '2021-01-12 16:21:45', 'no', '', 5, NULL, 210880),
	('safety_uncomfortablesituationintro', 'he', 'messages', 'לעתים, אירוח יכול להפוך להיות לא נעים: מרגישים לא בנוח או משהו מרגיש לא כשורה? המארח או האורח מתקשר או מתנהג בדרך שמציקה לך?', '2022-03-25 12:59:40', '2022-03-25 12:59:40', '2022-03-25 12:59:40', 'no', '', 5, NULL, 290109),
	('safety_uncomfortablesituationintro', 'hu', 'messages', 'Ha egy vendég vagy utazás során kellemetlenségeket tapasztalsz, vagy nem érzed jól magad a bőrödben, esetleg furcsán viselkedik a vendéged/vendéglátód, <a href="safety/whattodo#uncomfortable">kattints ide néhány jó tanácsért.</a>', '2020-05-25 11:33:33', '2020-05-25 11:33:33', '2020-05-25 11:33:33', 'no', '', 5, NULL, 36939),
	('safety_uncomfortablesituationintro', 'hy', 'messages', 'Երբեմն հյուրընկալության փորձը կարող է տհաճ դառնալ. ինչ-որ բա՞ն է անհանգստացնում կամ մի բան էն չի թվու՞մ։ Գուցե հյուրընկալի կամ հյուրի շփման ձևը կամ վարքը նյարդայնացնու՞մ է։', '2025-04-30 17:32:10', '2025-05-23 08:08:52', '2025-04-30 17:32:10', 'no', '', 5, NULL, 519603),
	('safety_uncomfortablesituationintro', 'it', 'messages', 'Qualche volta un\'esperienza di ospitalità può diventare sgradevole. Non ti senti a tuo agio o qualcosa non quadra? Magari il tuo ospite comunica o agisce in un modo che ti infastidisce? <a href="safety/whattodo#uncomfortable"> Leggi i consigli su cosa fare in queste situazioni</a>. ', '2013-07-04 09:54:48', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 44692),
	('safety_uncomfortablesituationintro', 'lt', 'messages', 'Pasitaiko, kad situacija tampa nemaloni: jaučiatės nerimastingas ar kažkas atrodo ne taip. Galbūt Jus apnakvindinantis asmuo ar Jūsų svečias dirginančiai bendrauja ar elgiasi?', '2021-05-22 09:35:40', '2021-05-22 09:35:40', '2021-05-22 09:35:40', 'no', '', 5, NULL, 285578),
	('safety_uncomfortablesituationintro', 'nl', 'messages', 'Soms wordt een gastvrijheidservaring onaangenaam: je voelt je niet op je gemak of er lijkt iets niet te kloppen?  Misschien communiceert of handelt je gast of gastgever op een manier die je niet aanstaat?', '2013-07-07 10:31:37', '2026-02-05 12:46:11', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('safety_uncomfortablesituationintro', 'pl', 'messages', 'Czasem doświadczenie gościnności może stać się niewygodne: czujesz się nieswojo lub wydaje Ci się, że coś jest nie tak? Może Twoja gospodyni lub gość mówi lub zachowuje się irytująco?', '2020-06-08 09:03:12', '2021-03-21 17:25:39', '2020-06-08 09:03:12', 'no', '', 5, NULL, 116789),
	('safety_uncomfortablesituationintro', 'pt', 'messages', 'Por vezes uma experiência de hospitalidade pode tornar-se desconfortável: sente-se inseguro/a ou algo não lhe parece bem? Talvez o seu anfitrião ou convidado comunique ou aja de uma forma que o irrita? <a href="safety/whattodo#uncomfortable">Clique aqui para ler dicas sobre o que fazer nestas situações.</a>', '2013-08-12 11:36:20', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('safety_uncomfortablesituationintro', 'pt-BR', 'messages', 'As vezes, a situação entre hóspede e viajante pode ficar estranha: você se sente desconfortável ou alguma coisa não parece estar legal? O hóspede ou visitante se comunica de uma maneira não agradável? <a href="safety/whattodo#uncomfortable">Clique aqui para ver dicas sobre o que fazer nestes casos.</a>', '2014-09-06 07:13:32', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160059),
	('safety_uncomfortablesituationintro', 'ru', 'messages', 'Иногда ощущение от приема гостей или пребывания в гостях может стать неприятным: Чувствуете себя как-то не так или все идет не так как хотелось? Возможно, действия или отношения вашего гостя/хозяина раздражают Вас? <a href="safety/whattodo#uncomfortable">Кликните здесь, чтобы прочесть советы о том, как быть в такой ситуации.</a>', '2014-04-26 07:03:20', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('safety_uncomfortablesituationintro', 'sk', 'messages', 'Niekedy môže byť zážitok z pohostinstva nepríjemný: Cítite sa nepríjemne alebo niečo nie je v poriadku? Možno váš hostiteľ alebo hosť komunikuje alebo koná spôsobom, ktorý vás rozčuľuje?', '2023-06-27 19:22:20', '2023-06-27 19:22:20', '2023-06-27 19:22:20', 'no', '', 5, NULL, 42849),
	('safety_uncomfortablesituationintro', 'sl', 'messages', 'Izkušnja se lahko včasih odvije v neprijetno smer: počutite se nesproščeno ali se ne nekaj preprosti ne zdi prav. Morda se vaš gost ali gostitelj obnaša ali komunicira na način, ki vas vznemirja? <a href="safety/whattodo#uncomfortable">Kliknite za nasvete, kaj storiti v podobnih situacijah.</a>', '2019-05-03 21:54:28', '2019-05-03 21:54:28', '2019-05-03 21:54:28', 'no', '', 5, NULL, 106553),
	('safety_uncomfortablesituationintro', 'sr', 'messages', 'Некад размена гостопримства може бити непријатна, осећате се налагодно или нешто вам се не чини у реду. Можда се ваш домаћин или гост понаша онако како вам се не свиђа?  <a href="safety/whattodo#uncomfortable">Погледајте овде савете шта радити у таквим ситуацијама.</a>', '2014-06-13 14:00:13', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('safety_uncomfortablesituationintro', 'sv', 'messages', 'Ibland en upplevelse kan bli obekvämt: Du känner dig orolig eller något inte verkar rätt? Kanske din värd eller gäst kommunicerar eller agerar på ett sätt som irriterar dig? <a href="safety/whattodo#uncomfortable">Klicka för att läsa tipsen om vad man ska göra i sådana situationer.</a>', '2013-07-18 16:17:13', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 23263),
	('safety_uncomfortablesituationintro', 'tr', 'messages', 'Bazen misafirlik rahatsız edici bir hal alabilir. Rahatsız mı hissediyorsunuz ya da bir şeyler yanlış mı görünüyor? Belki de ev sahibiniz veya misafiriniz sizi rahatsız eden bir şekilde mi davranıyor?  <a href="safety/whattodo#uncomfortable">Böyle durumlarda yapılacaklar için tıklayınız.</a>', '2014-09-19 12:28:56', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 35699),
	('safety_uncomfortablesituationintro', 'uk', 'messages', 'Інколи досвід гостинності може стати незручним: ви почуваєтеся неспокійно або щось здається неправильним? Можливо, ваш господар житла або гість спілкується чи діє так, що це вас дратує?', '2026-04-03 19:11:22', '2026-04-03 19:11:22', '2026-04-03 19:11:22', 'no', '', 5, NULL, 573491),
	('safety_uncomfortablesituationintro', 'vi', 'messages', 'Đôi khi, trải nghiệm lưu trú trở nên không được thoải mái: Bạn cảm thấy khó khăn hoặc có điều gì đó dường như không đúng lắm? Có thể host hoặc khách của bạn đã giao tiếp hoặc làm gì đó theo cách gây khó chịu cho bạn?', '2021-06-24 07:01:24', '2021-06-24 07:01:24', '2021-06-24 07:01:24', 'no', '', 5, NULL, 293926),
	('safety_uncomfortablesituationintro', 'zh-hans', 'messages', '有时借宿、招待的体验会变得让人感觉不安：你觉得不舒服或者觉得有些东西不大对？ 也许主人家或客人传达或者做了一些令你感觉不快的事? <a href="safety/whattodo#uncomfortable">点击这里查看如何处理这种情形的小贴士。</a>', '2013-07-04 14:26:38', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 46333),
	('safety_uncomfortablesituationintro', 'zh-hant', 'messages', '有時，接待住宿的經歷會變得不舒服：您感到不舒服或某些事情看起來不正確？ 也許您的接待人或客人之間的溝通或的方式行事會激怒您？ <a href="safety/whattodo#uncomfortable">點擊此處，以閱讀有關在這種情況下，您可以處理的方式提示。</a>', '2020-06-23 20:11:15', '2021-05-02 07:48:37', '2020-06-23 20:11:15', 'no', '', 5, NULL, 53422),
	('safety_uncomfortablesituationtext', 'ar', 'messages', 'في بعض الأحيان يمكن أن تصبح تجربة غير مريحة الضيافة: أنت تشعر بعدم الارتياح أو لا يبدو شيئا أليس كذلك؟ ربما المضيف أو الضيف بالابلاغ أو أعمال في الطريق الذي يهيج لك؟</p><p> ننصحك معالجة الوضع فورا بأدب. في محاولة لايجاد حل من خلال التواصل بوضوح وصراحة. إذا لا يزال الوضع غير مريح، ومؤكدا لكم، وإزالة نفسك. كضيف، وترك المكان المضيف الخاص بك والبقاء في مكان آخر (دائما نسخة احتياطية!) كمضيف، نسأل الضيف لمغادرة مكانك. كنت ملزمة بأي حال من الأحوال على التمسك الخطط السابقة إذا تم تجربة الضيافة تصبح القمعية. لا تدع وضع غير مريح تصعيد لحالة طوارئ حقيقية', '2014-04-22 13:22:11', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48359),
	('safety_uncomfortablesituationtext', 'cs', 'messages', 'Někdy se může stát zážitek s pohostinností nepohodlným: Cítíš se neklidně nebo se ti něco nezdá? Možná tvůj hostitel či host komunikuje nebo se chová způsobem, který tě irituje?</p><p>Doporučujeme, abys ihned začal(a) situaci zdvořile řešit. Pokus se najít řešení komunikováním jasně a otevřeně. Pokud je situace stále nepříjemná a stresuje tě, odejdi. Pokud jsi host, opusť domov hostitele a zůstaň někde jinde (vždy měj zálohu!). Pokud jsi hostitel, požádej svého hosta, aby opustil tvůj domov. V žádném případě nemáš obligaci držet se původních plánů pokud zážitek s pohostinností se stává skličující. Nedopusť, aby nepohodlná situace vyeskalovala ve skutečnou nouzovou situaci.', '2014-01-16 23:08:58', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('safety_uncomfortablesituationtext', 'de', 'messages', '<p>Manchmal fühlt man sich in einer Gast(geber)situation nicht allzu komfortabel: man fühlt sich unwohl oder etwas scheint nicht richtig zu sein. Vielleicht kommuniziert oder benimmt sich Gast oder Gastgeber so, dass es einen irritiert?</p><p>&nbsp;</p><p>Wir empfehlen, die Situation sofort höflich anzusprechen. Versucht, in klarer und offener Kommunikation eine Lösung zu finden. Falls es bei dem unwohlen Gefühl bleibt und es dich stresst, entziehe dich der Situation. Verlasse als Gast die Wohnung des Gastgebers und übernachte woanders (hab immer einen Plan B!). Bitte als Gastgeber den Gast, die Wohnung zu verlassen. Du bist keineswegs verpflichtet, dich an Absprachen zu halten, wenn die Situation dich unter Druck setzt. Lass eine unangenehme Situation nicht in einen Notfall ausarten.</p>', '2013-11-19 20:07:05', '2026-03-12 20:54:51', '0000-00-00 00:00:00', 'no', '', 5, NULL, 510283),
	('safety_uncomfortablesituationtext', 'el', 'messages', 'Καμιά φορά, μια εμπειρία φιλοξενίας μπορεί να γίνει άβολη: Αισθάνεσαι δυσάρεστα ή σου φαίνεται ότι κάτι δεν πάει καλά; Μήπως ο οικοδεσπότης σου ή ο φιλοξενούμενός σου επικοινωνεί ή συμπεριφέρεται με τρόπο που σε ενοχλεί;</p><p>Προτείνουμε να μιλήσεις αμέσως για τη κατάσταση με ευγενικό τρόπο. Προσπάθησε να βρεις μια λύση επικοινωνώντας ξεκάθαρα και ανοιχτά. Αν η κατάσταση παραμένει άβολη και σε αγχώνει, απομακρύνσου. Ως επισκέπτης, φύγε από το σπίτι του οικοδεσπότη σου και μείνε κάπου αλλού (έχε πάντα εναλλακτική!). Ως οικοδεσπότης, ζήτησε από τον επισκέπτη να φύγει. Σε καμία περίπτωση δεν είσαι υποχρεωμένος να ακολουθήσεις προηγούμενα σχέδια, αν η εμπειρία γίνεται καταπιεστική. Μην επιτρέπεις σε μια άβολη κατάσταση να γίνει πραγματική έκτακτη ανάγκη.', '2017-07-24 12:19:32', '2020-09-02 15:22:15', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('safety_uncomfortablesituationtext', 'en', 'messages', 'Sometimes a hospitality experience can become uncomfortable: You feel uneasy or something does not seem right? Maybe your host or guest communicates or acts in a way which irritates you?</p><p>We recommend that you immediately address the situation politely. Try to find a resolution by communicating clearly and openly. If the situation remains uncomfortable and is stressing you, remove yourself. As a guest, leave your host’s place and stay somewhere else (always have a backup!). As a host, ask your guest to leave your place. You are by no means obliged to stick to previous plans if the hospitality experience is becoming oppressive. Do not let an uncomfortable situation escalate to a real emergency.\r\n', '2013-06-23 17:30:54', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', 'text on safety "basics" page', 5, NULL, 158),
	('safety_uncomfortablesituationtext', 'es', 'messages', '<p>A veces una experiencia de intercambio puede volverse incómoda: ¿Sientes incomodidad o algo no funciona correctamente?¿Quizá quien te hospeda se comunica o actúa de un modo irritante?</p><p>&nbsp;</p><p>Te recomendamos abordar la situación de una forma educada. Intenta encontrar una solución comunicándote clara y abiertamente. Si la situación no mejora y te está estresando, cámbiala. Busca otro lugar para alojarte (ten siempre una segunda opción) o pide a tu huésped que busque otro lugar para quedarse. No estás, bajo ningún concepto, en la obligación de mantener lo planificado si la experiencia está siendo opresiva. No dejes que una situación incómoda se convierta en un problema de verdad.</p>', '2013-11-09 13:12:22', '2023-06-05 12:08:26', '0000-00-00 00:00:00', 'no', '', 5, NULL, 25548),
	('safety_uncomfortablesituationtext', 'fr', 'messages', 'Parfois, la situation peut devenir inconfortable. Si vous vous sentez mal, que quelque chose ne vous paraît pas correct, que votre hôte·sse ou invité·e communique ou agit d\'une manière qui vous irrite, nous vous recommandons d\'aborder immédiatement la situation, avec toute la politesse nécessaire.</p><p> Essayez de trouver une solution en communiquant clairement et ouvertement. Si la situation reste inconfortable ou stressante et que vous séjournez chez la personne, partez (ayez toujours un plan B&nbsp;!). Demandez à la personne de partir si vous l\'hébergez. Vous n\'avez aucune obligation de respecter votre engagement si l\'expérience devient oppressante. Ne laissez pas une situation inconfortable dégénérer.', '2014-11-25 17:26:40', '2020-06-15 21:40:38', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('safety_uncomfortablesituationtext', 'gl', 'messages', 'As veces unha experiencia de intercambio de hospitalidade se fai incómoda: Sénteste molesto ou algo non vai ben? Quizais a persoa que aloxas ou anfitrioa se comunica ou actúa dun xeito que te irrita?  </p><p>Recomendámosche que abordes a situación de modo amable pero inmediato. Trata de atopar un acordo comunicándote clara e abertamente. Se a situación segue a ser incómoda e te produce estrés, cámbiaa. Como hóspede deixa o lugar da persoas anfitrioa e queda con algunha outra (ten sempre unha segunda opción!). Se es a anfitrioa, pide á hospede que marche. De ningún modo tes a obriga de manter os planes orixinais se a experiencia de hospitalidade está volvéndose opresiva. Non deixes que unha situación incómoda escale a unha emerxencia real.', '2021-01-19 09:40:34', '2021-01-19 09:40:34', '2021-01-19 09:40:34', 'no', '', 5, NULL, 210880),
	('safety_uncomfortablesituationtext', 'hu', 'messages', 'Néha nem jól sülnek el a dolgok, kényelmetlen helyzetben találjuk magunkat: valami nem stimmel, rossz érzésed van egy találkozás kapcsán, vendéged/vendéglátód zavartan, bosszantóan vagy furcsán viselkedik? </p><p> Ez esetben azt javasoljuk, hogy azonnal, de udvariasan nevezd meg a problémát. Próbálj megoldást találni nyílt és őszinte megnyilvánulásokkal. Ha továbbra is fennáll a kellemetlen helyzet, mentsd ki magad. Ha vendégeskedés során tapasztalsz ilyet, ideje az (előre megszervezett!) B tervedet életbe léptetni: hagyd el szállásadód lakóhelyét és keresd fel azt az olcsó hostelt a környéken. Ha vendége(i)d kellemetlenkednek, bátran kérd meg őket, hogy távozzanak. Semmire nem kötelezhetnek, ha saját otthonodban nem érzed velük jól magad! Ne várd meg, hogy egy kellemetlen helyzetből vészhelyzet alakulhasson ki!', '2020-05-25 20:50:05', '2020-05-25 20:50:05', '2020-05-25 20:50:05', 'no', '', 5, NULL, 36939),
	('safety_uncomfortablesituationtext', 'it', 'messages', 'Qualche volta una esperienza di scambio di ospitalità potrebbe risultare non piacevole. Non ti trovi a tuo agio o qualcosa non sembra a posto ? Forse il tuo ospite si esprime o agisce in un modo che ti irrita?</p><p>Ti raccomandiamo di sistemare la situazione in un modo educato. Prova a trovare un accordo comunicando in maniera aperta ma allo stesso tempo esplicita. Se la situazione rimanesse spiacevole e ti tensse in tensione, allontanatene. Come ospite vai via e trova un altra sistemazione (abbi sempre un piano B), come ospitante, chiedi al tuo oispite di lasciare la tua casa. In nessun caso siete obbligati a seguire pedissequamente gli accordi precedenti se la esperienza di ospitalità divenisse oppressiva. Npon lasciate che una situazione semplicemente spiacevole evolva in una emergenza di sicurezza.    \r\n\r\n\r\n\r\n', '2018-12-12 20:41:05', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 13993),
	('safety_uncomfortablesituationtext', 'nl', 'messages', 'Soms wordt een gastvrijheidservaring onaangenaam: je voelt je ongemakkelijk of iets lijkt niet te kloppen?  Misschien communiceert of handelt je gast of gastgever op een manier die irritatie opwekt?</p><p>We bevelen aan dat je de situatie onmiddellijk vriendelijk aanspreekt.  Probeer een oplossing te vinden door duidelijk en open te communiceren.  Alse de situatie onaangenaam blijft en je zorgen baart, ga dan weg.  Als gast, verlaat je de woning van je gastgever en verblijf je elders (zorg steeds voor een tweede optie!).  Als gastgever, vraag je je gast om je woning te verlaten.  Je bent geenszins verplicht om bestaande plannen te volgen als de gastvrijheidservaring bedrukkend wordt.  Voorkom dat een onaangename situatie escaleert tot een echt noodgeval.', '2013-08-01 18:56:02', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('safety_uncomfortablesituationtext', 'pl', 'messages', 'Czasami dośwadczenie gościnności może stać się niewygodne: czujesz się nieswojo lub coś wydaje się nie tak? Może Twój gospodarz lub gość komunikuje się lub działa w sposób, który Cię irytuje? </p> <p> Zalecamy natychmiastowe uprzejme podejście do sytuacji. Spróbuj znaleźć rozwiązanie, komunikując się jasno i otwarcie. Jeśli sytuacja pozostaje niewygodna i cię stresuje, odejdź. Jako gość opuść miejsce gospodarza i zostań gdzie indziej (zawsze pamiętaj o planie B!). Jako gospodarz poproś gościa, aby opuścił twój dom. Nie jesteś zobowiązany do trzymania się poprzednich planów, jeśli gościnność staje się uciążliwa. Nie pozwól, aby niewygodna sytuacja przerodziła się w prawdziwy problem.', '2020-06-09 10:17:42', '2020-06-09 10:17:42', '2020-06-09 10:17:42', 'no', '', 5, NULL, 37896),
	('safety_uncomfortablesituationtext', 'pt', 'messages', 'Por vezes uma experiência de hospitalidade pode tornar-se desconfortável: sente-se inseguro/a ou algo não lhe parece bem? Talvez o seu anfitrião ou convidado comunique ou aja de uma forma que o irrita?</p><p>Recomendamos que lide com a situação imediatamente e de forma educada. Procure chegar a uma solução comunicando clara e abertamente. Se o desconforto persistir e isso o/a deixar nervoso, saia. Enquanto convidado, deixe a casa do seu anfitrião e fique noutro local (tenha sempre uma solução de emergência!). Enquanto anfitrião peça ao seu convidado para deixar a sua casa. Não é de forma alguma obrigado a manter os seus planos originais se a experiência de hospitalidade se estiver a tornar opressiva. Não deixe uma situação de desconforto escalar para uma situação de emergência real.', '2013-08-12 17:00:24', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('safety_uncomfortablesituationtext', 'pt-BR', 'messages', 'As vezes uma experiência de hospitalidade pode ficar desconfortável. Ela faz te sentir pouco á vontade ou tem algo que não sente bem? Talvez seu anfitrião ou convidado comunica ou toma ação num jeito que te irrita? </p><p> Nós recomendamos que você faça algo para lidar a situação educadamente. Tente achar uma resolução com a comunicação clara e aberta. Se a a situação ficasse desconfortável e fizesse te ficar estressado, te removeria. Como convidado, saia da casa da anfitrião e ficar numa casa dum outro (sempre tenha uma outra opção!). Como anfitrião, pergunte seu convidado sair da sua casa. Não tenha obrigação nenhuma falando que você precisa ficar com os planos se a experiência de hospitalidade está ficando opressivo. Não deixe uma situação desconfortável ficar uma emergência real! ', '2014-09-16 20:27:20', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48669),
	('safety_uncomfortablesituationtext', 'ru', 'messages', 'Иногда впечатление от гостеприимства становиться некомфортным: Вы ощущаете сложность или понимаете, что что-то идет не так? Возможно Ваш гость/хозяин общаются или ведут себя так, что Вас это раздражает?</p><p>Мы рекомендуем разрешать эту проблему вежливо. Постарайтесь найти решения, общаясь открыто и ясно. Если ситуация остается некомфортной и все еще заставляет Вас нервничать, выйдете из нее. Ели Вы являетесь гостем, покиньте то место, где Вы находитесь, и остановитесь где-либо еще (всегда имейте запасной план!). Если Вы хозяин, попросите Вашего гостя переехать в другое место. Вы, безусловно, не обязаны следовать предыдущим планам, если ощущения от приема гостей (прибывания в гостях) становятся некомфортными. Не позволяйте некомфортным обстоятельствам перерасти в чрезвычайную ситуацию. ', '2014-05-02 07:57:49', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('safety_uncomfortablesituationtext', 'sr', 'messages', 'Понекад искуство гостопримства може бити непријатно: Осећате се нелагодно или нешто не изгледа како треба? Можда ваш гост или домаћин фовори или се понаша на начин који вам смета?</p><p>Саветујемо да одмах и учтиво скренете пажњу на проблем. Пробајте да нађете решење омоћу разговора, јасно и отворено. Ако ситуација остане непријатна и доводи вас до стреса, као гост, напустите место домаћина и идите негде другде (увек имајте резервно место), а као домаћин, тражите од госта на напусти ваше место. Нисте у обавези да се држите плана ако искуство постане непријатно. Не дозволите да се непријатна ситуација претвори у право ванредно стање.', '2015-02-01 21:11:57', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('safety_uncomfortablesituationtext', 'sv', 'messages', 'Ibland kan gästfriheten bli obekväm: Känner du dig olustig eller verkar någonting inte gå rätt till? Kanske din värd eller gäst kommunicerar eller beter sig på ett sätt som stör dig?</p><p>Vi rekommenderar att du omedelbart tar tag i saken på ett artigt sätt. Försök hitta en lösning genom att kommunicera tydligt och öppet. Om situationen fortsättningsvis känns obekväm och du blir stressad av den, avlägsna dig. Som gäst, lämna din värds hem och bo någon annanstans (ha alltid en reservplan!). Som värd, be din gäst lämna ditt hem. Du är inte på något sätt skyldig att hålla fast vid tidigare planer om situationen blir besvärande. Låt inte en obekväm situation eskalera till ett nödläge. ', '2016-02-27 20:15:08', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 93341),
	('safety_uncomfortablesituationtext', 'uk', 'messages', '<p>Іноді досвід гостинності може стати незручним: ви відчуваєте себе неспокійно або щось здається неправильним? Можливо, ваш господар або гість спілкується чи діє так, що це вас дратує?</p><p>&nbsp;</p><p>Ми рекомендуємо вам негайно ввічливо вирішити ситуацію. Спробуйте знайти рішення, спілкуючись чітко та відкрито. Якщо ситуація залишається незручною і викликає у вас стрес, вийдіть з неї. Якщо ви гість, залиште місце проживання господаря житла і зупиніться деінде (завжди майте запасний варіант!). Якщо ви господар житла, попросіть вашого гостя покинути ваше місце проживання. Ви зовсім не зобов\'язані дотримуватись попередніх планів, якщо досвід гостинності стає гнітючим. Не дозволяйте незручній ситуації перерости в справжню надзвичайну ситуацію.</p>', '2026-04-05 22:32:03', '2026-04-24 22:35:23', '2026-04-05 22:32:03', 'no', '', 5, NULL, 573491),
	('safety_uncomfortablesituationtext', 'zh-hant', 'messages', '<p>有時候，接待經驗可能會變得讓人感到不舒服：你感到不安，或是有些地方不太對勁？也許你的接待者或訪客的言行讓你感到困擾？</p><p>我們建議你立即有禮貌地處理這種情況。試著透過清楚、坦率的溝通來尋求解決方式。如果情況仍然讓你感到不自在並造成壓力，就請離開現場。作為訪客，離開接待者的住所並找其他地方住宿（務必隨時備有備案！）；作為接待者，可以請訪客離開你的住所。如果接待體驗開始讓人感到壓迫，你完全沒有義務遵守原先的計劃。不要讓一個不舒服的情況演變成真正的緊急事件。</p>', '2025-05-31 18:52:20', '2025-05-31 18:52:20', '2025-05-31 18:52:20', 'no', '', 5, NULL, 53422),
	('safety.contacttext.contact.form', 'ca', 'messages', 'formulari de contacte', '2021-10-04 20:09:37', '2021-10-04 20:09:37', '2021-10-04 20:09:37', 'no', '', 5, NULL, 304193),
	('safety.contacttext.contact.form', 'de', 'messages', 'Kontaktformular', '2021-01-25 00:19:33', '2021-01-25 00:19:33', '2021-01-25 00:19:33', 'no', '', 5, NULL, 347),
	('safety.contacttext.contact.form', 'el', 'messages', 'φόρμα επικοινωνίας', '2020-07-21 22:52:44', '2020-09-02 17:22:38', '2020-07-21 22:52:44', 'no', '', 5, NULL, 266544),
	('safety.contacttext.contact.form', 'en', 'messages', 'contact form', '2020-06-22 19:09:59', '2020-06-22 19:09:59', '2020-06-22 19:09:59', 'no', 'Link to the feedback form with category safety selected. Translation is about the link text "contact form" which will be inserted into the translation code "safety.contacttext" So please translate that in context. Best way visit www.bewelcome.org/safety to review the full paragraph.', 5, NULL, 347),
	('safety.contacttext.contact.form', 'es', 'messages', 'formulario de contacto', '2020-11-30 03:47:07', '2020-11-30 03:47:07', '2020-11-30 03:47:07', 'no', '', 5, NULL, 25548),
	('safety.contacttext.contact.form', 'fr', 'messages', 'formulaire de contact', '2020-06-28 17:01:08', '2020-06-28 17:01:08', '2020-06-28 17:01:08', 'no', '', 5, NULL, 168499),
	('safety.contacttext.contact.form', 'gl', 'messages', 'formulario de contacto', '2021-01-12 16:33:13', '2021-01-12 16:33:13', '2021-01-12 16:33:13', 'no', '', 5, NULL, 210880),
	('safety.contacttext.contact.form', 'he', 'messages', 'טופס יצירת קשר', '2022-04-04 14:53:37', '2022-04-04 14:53:37', '2022-04-04 14:53:37', 'no', '', 5, NULL, 290109),
	('safety.contacttext.contact.form', 'hy', 'messages', 'կապի ձևաթուղթ', '2025-04-29 15:26:49', '2025-04-30 13:41:21', '2025-04-29 15:26:49', 'no', '', 5, NULL, 519603),
	('safety.contacttext.contact.form', 'it', 'messages', 'Modulo di contatto', '2020-10-07 19:51:58', '2020-10-09 14:20:01', '2020-10-07 19:51:58', 'no', '', 5, NULL, 160610),
