	('safety.contacttext.contact.form', 'nl', 'messages', 'contactformulier', '2020-06-23 10:44:11', '2020-06-23 10:44:11', '2020-06-23 10:44:11', 'no', '', 5, NULL, 21169),
	('safety.contacttext.contact.form', 'pl', 'messages', 'formularz kontaktowy', '2020-07-02 18:40:50', '2020-07-02 18:40:50', '2020-07-02 18:40:50', 'no', '', 5, NULL, 37896),
	('safety.contacttext.contact.form', 'pt', 'messages', 'formulário de contacto', '2020-06-22 20:10:28', '2020-06-22 20:10:28', '2020-06-22 20:10:28', 'no', '', 5, NULL, 38787),
	('safety.contacttext.contact.form', 'ru', 'messages', 'форма обратной связи', '2025-03-20 11:47:44', '2025-03-20 11:47:44', '2025-03-20 11:47:44', 'no', '', 5, NULL, 519603),
	('safety.contacttext.contact.form', 'tr', 'messages', 'İletişim formu', '2023-07-17 17:43:14', '2023-07-17 17:43:14', '2023-07-17 17:43:14', 'no', '', 5, NULL, 318142),
