	('searchmembersinceinfo', 'zh-hant', 'messages', '加入日期: %s', '2022-02-13 18:19:13', '2022-02-13 18:19:13', '2022-02-13 18:19:13', 'no', '', 5, NULL, 53422),
	('searchmembersintro', 'ar', 'messages', 'ابحث عن اعضاء فى منطقة معينة او اعضاء بأهتمامات أو صفات معينة \r\nاستخدم قائمة الى العمل على الجانب الايسر لتستطيع الوصول لادوات بحث أكثر', '2008-02-11 08:39:22', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 2702),
	('searchmembersintro', 'bg', 'messages', 'Търсене на членове по географски региони или по определени интереси или атрибути. Използвайте лявото меню за допълнителни опции за търсене.', '2008-02-17 20:18:26', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 401),
	('searchmembersintro', 'ca', 'messages', 'Cerca i troba altres membres en una regió específica o amb interessos o criteris determinats.\r\nFes servir el menú "Accions" de l\'esquerra per accedir a més criteris de cerca.', '2008-02-18 00:11:31', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 3236),
	('searchmembersintro', 'da', 'messages', 'Find medlemmer fra specifikke geografiske regioner eller ud fra interesser og lign. Brug Handlinger-menuen til venstre for flere søge-muligheder.', '2008-03-30 16:54:25', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 74),
	('searchmembersintro', 'de', 'messages', 'Hier kannst du Mitglieder nach Ort, Interessen oder bestimmten Eigenschaften suchen. Weitere Suchoptionen findest du im Aktionsbereich am linken Seitenrand. Viel Spaß!', '2008-01-31 15:34:43', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 91),
	('searchmembersintro', 'en', 'messages', 'Find members from specific geographic regions or members with certain interests or attributes.\r\nUse the Action menu on the left to access more search options.', '2008-01-27 14:23:35', '2019-04-23 18:16:49', '2008-01-27 14:26:10', 'no', 'Teaser bar introduction to search members.', 5, 1, 601),
	('searchmembersintro', 'es', 'messages', 'Encuentra miembros de regiones geográficas específicas o con ciertos intereses o cualidades.\r\nUsa el menú de Acciones en la parte izquierda y tendrás acceso a más opciones de búsqueda.', '2008-01-28 06:16:51', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1328),
	('searchmembersintro', 'fi', 'messages', 'Etsi jäseniä tietyin hakuehdoin: esimerkiksi alueen mukaan tai jäseniä, joilla on tietynlaisia kiinnostuksen kohteita. Käytä toiminta-valikkoa vasemmalla päästäksesi valitsemaan enemmän hakukriteerejä.', '2008-02-25 15:16:38', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 525),
	('searchmembersintro', 'fr', 'messages', 'Recherchez des membres par zone géographique ou par caractéristiques (loisir, occupation ...)\r\nRegardez dans les autres options dans  menu Action', '2008-02-02 08:26:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('searchmembersintro', 'id', 'messages', 'Anda dapat melacak anggota lain melalui pencarian secara geografis, minat dan lainnya.', '2008-04-01 18:10:18', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 2019),
	('searchmembersintro', 'it', 'messages', 'Trova membri provenienti da una specifica localitá o zona geografica o membri con un interessse particolare.\r\n\r\nUsa il punto di menu Azioni sulla sinistra per accedere ad ulteriori modalità di ricerca.', '2008-02-01 14:47:16', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
	('searchmembersintro', 'lt', 'messages', 'Suraskite narius iš tam tikrų geografinių regionų, arba narius su tam tikrais interesais ir savybėmis. Naudokite VEIKSMŲ meniu (kairėje), kad praplėsti paieškos parametrus.', '2008-02-22 16:39:15', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 227),
	('searchmembersintro', 'nl', 'messages', 'Zoek leden uit specifieke geografische gebieden of leden met bepaalde interesses of kenmerken.\r\nGebruik het Actie Menu links voor meer zoekfuncties', '2008-02-03 22:10:53', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 69),
	('searchmembersintro', 'pl', 'messages', 'Szukaj członków BeWelcome w zależności od położenia geograficznego, ich zainteresowań lub opisów. \r\nUżyj menu Opcji po lewej stronie ekranu aby zawęzić kryteria wyszukiwania. ', '2008-02-02 09:30:28', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 90),
