	('signup.error.email.taken', 'ca', 'messages', 'Aquesta adreça eletrònica no es pot fer servir perquè ja existeix a la base de dades. Si us plau contacta a l\'equip de suport per poder accedir al perfil existent enlloc d\'obrir-ne un de nou.', '2022-06-16 09:14:55', '2022-06-16 09:14:55', '2022-06-16 09:14:55', 'no', '', 5, NULL, 26748),
	('signup.error.email.taken', 'de', 'messages', 'Diese E-Mail-Adresse kann nicht verwendet werden, da sie bereits in der Datenbank vorhanden ist. Bitte wende dich an unseren Support, um Zugriff auf das bestehende Profil zu erhalten, anstatt ein neues Profil zu erstellen.', '2020-06-06 21:21:39', '2020-06-06 21:21:39', '2020-06-06 21:21:39', 'no', '', 5, NULL, 111),
	('signup.error.email.taken', 'el', 'messages', 'Η διεύθυνση ηλεκτρονικού ταχυδρομείου δεν μπορεί να χρησιμοποιηθεί καθώς υπάρχει ήδη στη βάση δεδομένων. Επικοινώνησε με την υποστήριξη για να συνδεθείς στο υπάρχον προφίλ σου αντί να δημιουργήσεις νέο.', '2020-07-22 20:39:19', '2020-08-26 18:50:44', '2020-07-22 20:39:19', 'no', '', 5, NULL, 266544),
	('signup.error.email.taken', 'en', 'messages', 'This email address can\'t be used as it is already in the database. Please contact support to get access to the existing profile instead of creating a new one.', '2019-05-18 18:37:09', '2019-05-18 18:37:09', '2019-05-18 18:37:09', 'no', 'Shown when the check for the email address finds that the email address is already in use.', 5, NULL, 1223),
