	('signup.error.occured', 'hu', 'messages+intl-icu', 'Úgy látszik, valamiért nem sikerült regisztrálnod. Kérünk, hogy lépj kapcsolatba velünk!', '2020-05-29 09:01:39', '2020-05-29 09:01:39', '2020-05-29 09:01:39', 'no', '', 5, NULL, 36939),
	('signup.error.occured', 'hy', 'messages+intl-icu', 'Գրանցման ընթացքում խնդիր առաջացավ։ Խնդրում ենք կապվել աջակցության հետ:', '2025-05-21 06:57:50', '2025-05-21 06:57:50', '2025-05-21 06:57:50', 'no', '', 5, NULL, 519603),
