	('signup.error.occured', 'nl', 'messages+intl-icu', 'We zijn op een probleem gestoten bij het registratieproces.  Neem contact op met ons ondersteuningsteam.', '2020-06-08 18:44:09', '2020-06-08 18:49:28', '2020-06-08 18:44:09', 'no', '', 5, NULL, 21169),
