	('signup.finished.congrats', 'hu', 'messages+intl-icu', 'Gratulálunk, <strong>{username}</strong>, majdnem teljes a regisztrációd!', '2020-05-29 09:02:34', '2020-05-29 09:02:34', '2020-05-29 09:02:34', 'no', '', 5, NULL, 36939),
	('signup.finished.congrats', 'it', 'messages+intl-icu', 'Congratulazioni <strong>{username}</strong>, hai quasi completato la registrazione.', '2020-05-25 21:12:39', '2020-05-25 21:12:39', '2020-05-25 21:12:39', 'no', '', 5, NULL, 261434),
	('signup.finished.congrats', 'nl', 'messages+intl-icu', 'Gefeliciteerd <strong>{username}</strong>,  je hebt het aanmeldingsproces bijna afgerond.', '2020-06-23 06:58:41', '2020-06-23 06:58:41', '2020-06-23 06:58:41', 'no', '', 5, NULL, 21169),
	('signup.finished.congrats', 'pl', 'messages+intl-icu', 'Gratulacje <strong>{username}</strong>, prawie zakończyłeś/aś rejestrację.', '2020-06-26 13:05:47', '2020-06-26 13:05:47', '2020-06-26 13:05:47', 'no', '', 5, NULL, 37896),
