	('signup.resent.link', 'hy', 'messages+intl-icu', 'Մենք հենց նոր ուղարկեցինք քեզ ևս մի էլ. նամակ՝ էլ. փոստի հասցեդ հաստատելու համար անհրաժեշտ հղումով։', '2025-05-21 07:08:30', '2025-05-21 07:08:30', '2025-05-21 07:08:30', 'no', '', 5, NULL, 519603),
