	('signupbirthdate', 'zh-hant', 'messages', '生日', '2010-02-24 03:09:18', '2021-05-02 07:48:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37722),
	('signupbirthdatedescription', 'bg', 'messages', 'Въведете рожденната си дата. Ако не искате тя да се вижда на профила Ви, тикнете <b>%s</b> \r\nИзползвайте следния формат за въвеждане на рождена дата (примерно): 23-01-1975 ', '2007-07-10 23:53:43', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 851),
	('signupbirthdatedescription', 'ca', 'messages', 'Introdueix la teva data de naixement. Si no vols que sigui visible al teu perfil, selecciona <b>%s</b>.\r\n\r\nEscriu la data amb format DD-MM-AAAA.', '2007-08-28 23:03:26', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 177),
	('signupbirthdatedescription', 'da', 'messages', 'Indtast din fødselsdato her. Hvis du ikke vil have at denne skal kunne ses på din profil, så klik <b>%s</b>.\r\n\r\nDu skal følge formatet: DD-MM-ÅÅÅÅ', '2007-10-18 19:15:06', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 74),
	('signupbirthdatedescription', 'de', 'messages', 'Bitte trage hier dein Geburtsdatum ein. Wenn du nicht möchtest, dass es auf deinem Profil angezeigt wird, markiere <b>%s</b> mit einem Häkchen. \r\nGib das Datum in folgendem Format ein: TT-MM-JJJJ. Bitte beachte, dass das Datum später im Standard-ISO-Format JJJJ-MM-TT angezeigt wird.\r\n', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 15240),
	('signupbirthdatedescription', 'el', 'messages', 'Παρακαλούμε εισάγετε την ημερομηνία γέννησής σας εδώ. Εάν δεν θέλετε να εμφανίζεται στο προφίλ σας επιλέξτε <b>%s</b>.\r\n\r\nΠρέπει να εισάγετε την ημερομηνία γέννησης με το ακόλουθο σχήμα: ΗΗ-ΜΜ-ΧΧΧΧ. Η ημερομηνία μετά θα εμφανίζεται ως ΧΧΧΧ-ΜΜ-ΗΗ, που είναι το καθιερωμένο σχήμα.', '2013-10-07 19:36:15', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 25930),
	('signupbirthdatedescription', 'en', 'messages', 'Please enter your birth date here. If you do not want it to be displayed on your profile, tick <b>%s</b>.\r\n\r\nYou should write your birth date in the following format: DD-MM-YYYY. Note that the date will later be displayed  as YYYY-MM-DD, which is the standard ISO format.', '2008-03-25 17:56:28', '2019-04-23 18:16:49', '2008-04-13 16:16:26', 'no', '', 5, 1, 70),
	('signupbirthdatedescription', 'eo', 'messages', 'Bonvolu enmeti vian naskiĝdaton ĉi-tie. Se vi ne volas ke ĝi aperu sur via profilo, klaku <b>%s</b>.\r\n\r\nSkribu vian naskiĝtagon kun la jena formato : TT-MM-JJJJ. Notu ke la dato poste montriĝos kiel JJJJ-MM-TT, kiu estas la standarda ISO-formato.', '2007-09-11 16:47:58', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1769),
	('signupbirthdatedescription', 'es', 'messages', 'Ingresa la fecha de tu nacimiento. Si no quieres que aparezca en tu perfil, marca <b>%s</b>\r\n\r\nEl formato debe ser: DD-MM-AAAA\r\n', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1328),
	('signupbirthdatedescription', 'fi', 'messages', 'Ilmoitathan syntymäpäiväsi täällä. Jos et halua näyttää sitä profiilissasi, merkitse <b>%s</b>.\r\n\r\nKirjoita syntymäpäiväsi muodossa: PP-KK-VVVV.', '2007-09-19 17:26:05', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 525),
	('signupbirthdatedescription', 'fr', 'messages', 'Entrez ici votre date de naissance. \r\nSi vous ne voulez pas que celle-ci soit visible, cochez <b>%s</b>.\r\nLa date de naissance doit être dans le format 23-01-1975 (pour le 23 janvier 1975)', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 452),
	('signupbirthdatedescription', 'hr', 'messages', 'Ovdje unesi svoj datum rođenja. ako ne želiš da se vidi u tvom profilu, označi <b>%s</b>. \r\nDatum unesi u sljedećem obliku: DD-MM-GGGG. Napomena: datum će kasnije biti prikazan u obliku GGGG-MM-DD, što je standardni ISO format.', '2009-09-19 17:03:32', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 8197),
	('signupbirthdatedescription', 'hu', 'messages', 'Kérlek írd be a születési dátumod ide . Ha ezt az információt el akarod rejteni a profilodon akkor pipáld ki ezt.<b>%s</b>.\r\n\r\nA születési dátumodat a következő formában írd: NN-HH-ÉÉÉÉ. Megjegyzés: a dátum a következőekben a ÉÉÉÉ-HH-NN formátumban fog megjelenni, ami a standard ISO formátum.', '2012-11-14 13:54:02', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 34314),
	('signupbirthdatedescription', 'id', 'messages', 'Tuliskan tanggal lahir anda sbb: Tgl-Bln-Thn', '2007-11-05 17:08:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 2019),
	('signupbirthdatedescription', 'it', 'messages', 'Inserisci qui la tua data di nascita. Se non vuoi che venga visualizzata sul tuo profilo, clicca su <b>%s</b>.  Il formato della data é del tipo gg-mm-aaaa. La data sarà visualizzata nel formato AAAA-MM-GG, che è lo standard ISO.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
	('signupbirthdatedescription', 'lt', 'messages', 'Įveskite savo gimimo datą. Jei nenorite, kad ji būtų rodoma anketoje, pažymėkite <b>%s</b>.\r\n\r\nGimimo datos formato pavyzdis: 23-01-1975', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 227),
	('signupbirthdatedescription', 'lv', 'messages', 'Lūdzu ievadi savu dzimšanas datumu. Ja tu nevēlies to atainot savā profilā, atzīmē <b>%s</b>.\r\n\r\nDzimšanas datums ir jāievada turpmākajā formātā: DD-MM-GGGG', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 375),
	('signupbirthdatedescription', 'nl', 'messages', 'vul hier je geboortedatum in. Als je niet wilt dat die wordt weergegeven op je profiel, klik dan <b>%s</b>\r\nDe format is dd-mm-jjjj, bijvoorbeeld 23-01-1975', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 138),
	('signupbirthdatedescription', 'pl', 'messages', 'Wpisz tu swoją datę urodzin. Jeśli nie chcesz, żeby była widoczna w twoim profilu, kliknij <b>%s</b>.\r\n\r\nData urodzin powinna mieć następujący układ: DD-MM-YYYY', '2007-09-12 09:13:35', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1554),
	('signupbirthdatedescription', 'pt', 'messages', 'Introduza aqui a sua data de nascimento, por favor. Se deseja ocultar esta informação no seu perfil, por favor seleccione <b>%s</b>.\r\n\r\nDeve escrever a sua data de nascimento com o seguinte formato: DD-MM-YYYY. Note que a data será mostrada com o formato YYYY-MM-DD, que é o formato ISO padrão.', '2012-07-11 20:35:10', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 30452),
	('signupbirthdatedescription', 'pt-BR', 'messages', 'Por favor escreva sua data de nascimento aqui. Se você não quer que ela seja mostrada no seu perfil, marque <b>%s</b>.\r\n\r\nVocê deve escrever sua data de nascimento no seguinte formato (por exemplo): 23-01-1975', '2007-08-06 18:59:48', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, 1, 144),
	('signupbirthdatedescription', 'ru', 'messages', 'Введите дату своего рождения. Если вы не хотите, чтобы она была указана в профиле, поставьте галочку тут <b>%s</b>\r\n\r\nФормат даты: день-месяц-год\r\n', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 79),
	('signupbirthdatedescription', 'tr', 'messages', 'Lütfen doğum tarihinizi giriniz. Eğer proflinizde görünmesini istemiyorsanız, tıklayınız <b>%s</b>. ', '2008-08-27 11:32:33', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 3154),
	('signupbirthdateshape', 'bg', 'messages', 'Моля, попълнете рожденната си дата в следния вид: ДД-ММ-ГГГГ', '2007-07-10 23:54:44', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 851),
	('signupbirthdateshape', 'ca', 'messages', 'Indica la data de naixement amb el format DD-MM-AAAA.', '2007-09-02 20:16:26', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 177),
	('signupbirthdateshape', 'de', 'messages', 'Bitte gib dein Geburtsdatum im Format TT-MM-JJJJ an. Bitte beachte, dass das Datum später im Standard-ISO-Format JJJJ-MM-TT angezeigt wird.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 15240),
	('signupbirthdateshape', 'el', 'messages', 'Πρέπει να εισάγετε την ημερομηνία γέννησης με το ακόλουθο σχήμα: ΗΗ-ΜΜ-ΧΧΧΧ. Η ημερομηνία μετά θα εμφανίζεται ως ΧΧΧΧ-ΜΜ-ΗΗ, που είναι το καθιερωμένο σχήμα.', '2013-10-07 19:36:32', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 25930),
	('signupbirthdateshape', 'en', 'messages', 'Please provide your birth date in the following format: DD-MM-YYYY. Note that the date will later be displayed  as YYYY-MM-DD, which is the standard ISO format.', '2008-03-25 17:53:10', '2019-04-23 18:16:49', '2008-04-13 16:16:26', 'no', 'This is the short description of bith date to fill on signup form', 5, 1, 70),
	('signupbirthdateshape', 'eo', 'messages', 'Bonvolu provizi vian naskiĝtagon kun la jena formato : TT-MM-JJJJ. Notu ke la dato post aperos kiel JJJJ-MM-TT, laŭ normo ISO-formata.', '2007-09-11 16:49:02', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1769),
	('signupbirthdateshape', 'es', 'messages', 'Por favor ingresa tu fecha de nacimiento con el siguiente formato: DD-MM-AAAA', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1328),
	('signupbirthdateshape', 'fi', 'messages', 'Syötä syntymäaika muodossa PP-KK-VVVV', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 72),
	('signupbirthdateshape', 'fr', 'messages', 'S\'il vous plait entrez ici votre date de naissance sous la forme JJ-MM-AAAA', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 452),
	('signupbirthdateshape', 'hr', 'messages', 'Molimo te da uneseš datum svog rođenja u formatu: DD-MM-GGG. Datum će se kasnije prikazati u formatu GGG-MM-DD, što je standardni ISO format.', '2010-01-15 20:44:53', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 8197),
	('signupbirthdateshape', 'hu', 'messages', 'A születési dátumodat a következő formában írd: NN-HH-ÉÉÉÉ. Megjegyzés: a dátum a következőekben a ÉÉÉÉ-HH-NN formátumban fog megjelenni, ami a standard ISO formátum.', '2012-11-14 13:56:33', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 34314),
	('signupbirthdateshape', 'id', 'messages', 'Mohon Tuliskan tanggal lahir anda sbb: Tgl-Bln-Thn', '2007-11-05 17:08:41', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 2019),
	('signupbirthdateshape', 'it', 'messages', 'Inserisci la tua data di nascita nel formato GG-MM-AAAA. La data sarà visualizzata nel formato AAAA-MM-GG, che è lo standard ISO.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
	('signupbirthdateshape', 'ja', 'messages', '生年月日を、日(2桁)月(2桁)年(4桁)の順で記入してください。', '2007-11-09 10:12:46', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1834),
	('signupbirthdateshape', 'lt', 'messages', 'Prašome pateikti jūsų gimimo datą formatu diena-mėnuo-metai (DD-MM-YYYY)', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 227),
	('signupbirthdateshape', 'lv', 'messages', 'Lūdzu ataino savu dzimšanas datumu turpmākajā formātā: DD-MM-GGGG', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 375),
	('signupbirthdateshape', 'nl', 'messages', 'Vul je geboortedatum in onder de vorm dd-mm-jjjj', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 138),
	('signupbirthdateshape', 'pl', 'messages', 'Podaj swoją datę urodzenia w formie DD-MM-RRRR.', '2007-07-09 12:15:40', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 90),
	('signupbirthdateshape', 'pt', 'messages', 'Por favor forneca a sua data de nascimento no formato DD-MM-AAAA', '2007-07-17 23:14:31', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 752),
	('signupbirthdateshape', 'pt-BR', 'messages', 'Por favor, escreva sua data de nascimento no formato DD-MM-AAAA', '2007-08-06 18:37:20', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, 1, 144),
	('signupbirthdateshape', 'ro', 'messages', 'Te rugăm să scrii data în formatul: ZZ-LL-AAAA', '2007-09-17 18:07:38', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1081),
	('signupbirthdateshape', 'ru', 'messages', 'Пожалуйста, введите дату своего рождения в формате день-месяц-год', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 79),
	('signupbirthdateshape', 'sr', 'messages', 'Молимо да датум рођења напишете у DD-MM-YYYY формату. Датум ће се касније приказати као стандардни ISO формат YYYY-MM-DD.', '2013-01-22 23:53:18', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 39772),
	('signupbirthdateshape', 'tr', 'messages', 'Doğumgününü GG-AA-YYY biçeminde giriniz', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
