	('signupclosedtext', 'de', 'messages', 'BeWelcome bereitet derzeit die Migration auf einen neuen Server vor. Daher ist zur Zeit die Anmeldung deaktiviert,', '2020-06-06 21:03:47', '2020-06-06 21:03:47', '2020-06-06 21:03:47', 'no', '', 5, NULL, 111),
	('signupclosedtext', 'el', 'messages', 'Το BeWelcome ετοιμάζεται να μετακομίσει σε άλλον server.  Ως εκ τούτου, η εγγραφή θα απενεργοποιηθεί μέχρι τη Τετάρτη (24 Απριλίου).', '2020-07-23 10:16:39', '2020-08-26 19:08:50', '2020-07-23 10:16:39', 'no', '', 5, NULL, 266544),
	('signupclosedtext', 'en', 'messages', 'BeWelcome is currently preparing to migrate to a new server. Therefore signup will be disabled till Wednesday (April, 24th).', '2019-04-22 15:17:37', '2019-12-26 09:49:40', '2019-04-22 15:17:37', 'no', 'Text on the signup closed page', 5, NULL, 1223),
	('signupclosedtext', 'es', 'messages', 'BeWelcome se está preparando en este momento para migrar a un nuevo servidor. Por ello, el sistema de registro estará deshabilitado hasta el miércoles 24 de abril.', '2020-12-03 04:01:26', '2020-12-03 04:01:26', '2020-12-03 04:01:26', 'no', '', 5, NULL, 25548),
	('signupclosedtext', 'fr', 'messages', 'BeWelcome est en cours de préparation de migration vers un nouveau serveur. Les inscriptions sont suspendu jusqu’à Mercredi 24 avril.', '2020-05-25 23:38:20', '2020-05-25 23:38:20', '2020-05-25 23:38:20', 'no', '', 5, NULL, 29128),
	('signupclosedtext', 'gl', 'messages', 'BeWelcome está actualmente preparándose para migrar a un novo servidor. Polo tanto o rexistro estará inhabilitado ata o mércores (24 de abril).', '2021-01-25 08:30:36', '2021-01-25 08:30:36', '2021-01-25 08:30:36', 'no', '', 5, NULL, 210880),
	('signupclosedtext', 'it', 'messages', 'BeWelcome si sta attualmente preparando per migrare su un nuovo server. Pertanto l\'iscrizione sarà disabilitata fino a mercoledì (24 aprile).', '2020-05-26 11:35:49', '2020-05-26 11:35:49', '2020-05-26 11:35:49', 'no', '', 5, NULL, 261434),
	('signupclosedtext', 'nl', 'messages', 'BeWelcome bereidt zich voor om naar een nieuwe server te verhuizen.  Registreren zal daarom onmogelijk zijn tot woensdag (24 april).', '2019-12-31 14:06:06', '2019-12-31 14:06:06', '2019-12-31 14:06:06', 'no', '', 5, NULL, 21169),
	('signupclosedtext', 'pl', 'messages', 'BeWelcome przygotowuje się do przenosin na nowy serwer. Dlatego rejestracje będą niemożliwe do środy (24 kwietnia).', '2021-01-13 22:15:02', '2021-01-13 22:15:02', '2021-01-13 22:15:02', 'no', '', 5, NULL, 116789),
	('signupclosedtext', 'pt', 'messages', 'O BeWelcome está a preparar a mudança para um novo servidor. Por esse motivo, as inscrições serão suspensas até 4a feira (24 de abril).', '2019-04-25 19:24:48', '2019-04-25 19:24:48', '2019-04-25 19:24:48', 'no', '', 5, NULL, 38787),
	('signupclosedtitle', 'ca', 'messages', 'El formulari de registre no és disponible en aquests moments.', '2022-08-10 04:50:18', '2022-08-10 04:50:18', '2022-08-10 04:50:18', 'no', '', 5, NULL, 26748),
