	('signuperrorinvalidstreet', 'it', 'messages', 'Per favore inserisci la tua via', '2011-12-09 13:08:37', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 16084),
	('signuperrorinvalidstreet', 'nl', 'messages', 'Gelieve je straatnaam in te brengen', '2012-09-15 19:54:58', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 22382),
	('signuperrorinvalidstreet', 'pt', 'messages', 'Por favor, indique a sua rua', '2012-12-28 16:05:43', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 38787),
	('signuperrorinvalidzip', 'ca', 'messages', 'Si us plau, introdueix el teu codi postal', '2012-07-22 22:41:06', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 11944),
	('signuperrorinvalidzip', 'de', 'messages', 'Bitte gib deine Postleitzahl ein', '2011-12-08 14:30:37', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 111),
	('signuperrorinvalidzip', 'en', 'messages', 'Please enter your post code', '2011-12-08 14:13:11', '2019-04-23 18:16:49', '2011-12-08 14:41:28', 'no', '', 5, 1, 202),
	('signuperrorinvalidzip', 'es', 'messages', 'Por favor ingresa tu codigo postal', '2011-12-09 00:22:18', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 554),
	('signuperrorinvalidzip', 'fi', 'messages', 'Syötä postinumero', '2012-05-20 20:19:53', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 72),
	('signuperrorinvalidzip', 'fr', 'messages', 'Merci de fournir votre code postal', '2011-12-18 09:08:16', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 9823),
	('signuperrorinvalidzip', 'hr', 'messages', 'Unesi poštanski broj', '2012-09-19 19:55:31', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 24014),
	('signuperrorinvalidzip', 'it', 'messages', 'Per favore inserisci il tuo codice postale', '2011-12-09 13:07:45', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 16084),
	('signuperrorinvalidzip', 'nl', 'messages', 'gelieve je postnummer in te brengen', '2012-09-15 19:53:47', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 22382),
	('signuperrorinvalidzip', 'pt', 'messages', 'Por favor, indique o seu código postal', '2012-12-28 16:05:31', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 38787),
	('signuperrorinvalidzip', 'sr', 'messages', 'Молимо да унесете ваш поштанки код', '2013-01-24 19:30:49', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 39772),
	('signuperrorneedmorestate', 'ca', 'messages', 'Ja hi ha un perfil enregistrat amb l\'adreça %s i sembla que cal que acabis d\'emplenar-ne totes les dades. Fes una ullada a la safata d\'entrada del teu correu i completa les dades. (Són imprescindibles el teu nom complet, que estarà amagat per defecte i l\'adreça amb codi postal, que també estarà amagada per defecte)', '2008-03-03 18:36:41', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 3236),
	('signuperrorneedmorestate', 'de', 'messages', 'Sorry, du hast bereits schon ein registriertes Profil mit der E-Mail %s. Es sieht so aus, als ob du dort noch ein paar Daten vervollständigen mußt, bis wir dieses Profil freischalten können. Bitte schau in dein E-Mail Posteingang und vervollständige die benötigten Daten. Wir brauchen einen vollständigen Name (Nachname, Vorname) und eine vollständige Adresse (Straße, Hausnummer, Postleitzahl und Ort). Diese Daten sind natürlich standardmäßig nicht für andere Mitglieder einsehbar.', '2008-03-02 14:41:32', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 3050),
	('signuperrorneedmorestate', 'en', 'messages', 'Sorry, you already have a profile registered with the email address %s, it seems that we have required you to complete this profille, please look in your mail box an complete the data (full name is required (but it will be hidden by default), and, also full address with post code, which will also be hidden by default)', '2008-02-19 22:01:18', '2019-04-23 18:16:49', '2008-08-09 12:39:53', 'no', 'This is the message which is displayed at signup if a member with a profile in Needmore state allready exists for the same email.\r\nThe %s parameter stands for the email of the member', 5, 1, 101),
	('signuperrorneedmorestate', 'es', 'messages', 'Lo sentimos, ya tienes un perfil registrado con la dirección %s, parece que que te hemos pedido completar el perfil, por favor chequea en tu bandeja de entrada y completa los datos (el nombre completo y la dirección con código postal son datos que debes proporcionar obligatoriamente pero serán ocultos a menos que lo edites en tu perfil)', '2008-02-28 20:47:53', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1328),
	('signuperrorneedmorestate', 'fr', 'messages', 'Désolé, il semble que vous ayez déjà un profil en attente de complément d\'information pour cette adresse mail :%s.\r\n\r\nS\'il vous plaît, regardez votre messagerie et complètez ce profil. Un nom complet est obligatoire ainsi qu\'une adresse complète (avec code postal si cela à un sens dans votre pays et numéro de maison). Soyez sans craintes, ces informations par défaut, ne serons pas visibles pour les autres membres, sauf si vous en décidez autrement', '2008-02-19 22:04:31', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('signuperrorneedmorestate', 'hr', 'messages', 'Već imaš profil registriran s email adresom %s, čini se da smo te zatražili da dopuniš svoj profil. Molimo te provjeri svoju dolaznu poštu i dopuni podatke (puno ime -koje će biti skriveno, također punu adresu s poštanskim brojem - također će biti skrivena) ', '2012-09-19 20:46:31', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 24014),
	('signuperrorneedmorestate', 'it', 'messages', 'Ci dispiace, hai già un profilo registrato con l’indirizzo e-mail %s, sembra che ti abbiamo chiesto di completare tale profilo, per favore, dai un’occhiata nella tua casella di posta elettronica e aggiungi i dati mancanti (è richiesto il nome completo, ma sarà nascosto per default, così come anche il tuo indirizzo esatto, che pure non sarà reso invisibile).', '2008-03-15 18:03:55', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
	('signuperrorneedmorestate', 'lt', 'messages', 'Atsiprašome, bet jau turi profilį užregistruotą elektroninio pašto adresu %s, ir atrodo, kad tau reikia užpildyti šį profilį. Žvilgtelk į savo pašto dėžutę bei pateik reikiamas duomenys. Vardas ir pavardė yra būtini, nors bus paslėpti pagal nutylėjimą, Būtina taip pat pateikti pilną adresą su pašto kodu - ši informacija taip pat bus paslėpta pagal nutylėjimą', '2009-09-02 23:03:02', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 227),
	('signuperrorneedmorestate', 'pt', 'messages', 'Desculpa, mas já tem um perfil registado com o endereço de correio eletrónico %s. Parece que lhe pedimos que completasse o seu perfil. Por favor, consulte a sua caixa de correio eletrónico e complete a informação. Nome completo é obrigatório (mas será escondido por omissão) e também uma morada com código postal (que também será escondida por omissão)', '2013-01-26 17:24:32', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 38787),
	('signuperrorneedmorestate', 'ru', 'messages', 'Вы уже зарегистрировали профиль с адресом электронной почты %s. Очевидно, мы попросили вас заполнить этот профиль. Пожалуйста, проверьте вашу почту и дополните данные (требуется указать полное имя, которое будет скрыто по умолчанию, а также почтовый адрес с индексом, которые также будут скрыты по умолчанию) ', '2009-03-09 12:45:58', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 79),
	('signuperrorneedtoconfirmmail', 'ca', 'messages', 'Ja has creat un perfil, però encara no l\'has confirmat fent clic a l\'enllaç corresponent que et vam enviar a l\'adreça de correu %s. Comprova la safata d\'entrada, respon al missatge que et vam enviar i espera fins que haguem pogut revisar la sol·licitud.', '2008-03-03 18:41:29', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 3236),
	('signuperrorneedtoconfirmmail', 'cs', 'messages', 'Už sis vytvořil(a) profil, ale nepotvrdil(a) jsi ho pomocí odkazu, který jsme ti poslali na e-mailovou adresu %s.\r\n\r\nProsím, zkontroluj si schránku, odepiš na zprávu, kterou jsme ti poslali a počkej chvíli, než posoudíme tvou přihlášku', '2014-01-30 14:02:42', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 34292),
	('signuperrorneedtoconfirmmail', 'de', 'messages', 'Sorry, du hast dir bereits ein Profil erstellt, dies aber noch nicht mit dem Bestätigungslink, den wir dir an die E-Mail-Adresse %s geschickt haben, bestätigt. Bitte überprüfe deinen E-Mail Posteingang und antworte auf die E-Mail, die wir Dir geschickt haben. Gib uns dann bitte ein bischen Zeit, bis wir deinen Antrag erneut geprüft haben.', '2008-03-02 14:51:13', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 3050),
	('signuperrorneedtoconfirmmail', 'en', 'messages', 'Sorry, you have already created a profile but you have not confirmed it by clicking on the link we sent you to email address %s. \r\n\r\nPlease check your mail box, reply to the message we have sent you and then wait a bit for us to review your application', '2008-02-19 18:28:56', '2019-04-23 18:16:49', '2008-08-09 12:39:27', 'no', 'This is the error message a member can see when he has a pending application with a not confirmed email if he tries to subscribe with another Username, using the same email. The parameter stand for the email.', 5, 1, 101),
	('signuperrorneedtoconfirmmail', 'es', 'messages', 'Ya creaste un perfil pero no lo has confirmado. Hazlo haciendo clic en el enlace apropiado que enviamos a tu dirección de correo electrónico %s. Por favor verifica tu bandeja de entrada, responde al mensaje que te enviamos y luego espera un poco mientras revisamos tu aplicación.', '2008-02-28 12:48:05', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1328),
	('signuperrorneedtoconfirmmail', 'fr', 'messages', 'Désolé, vous avez déjà créé un profil avec cette adresse électronique, mais vous ne l\'avez pas encore confirmée en cliquant sur le lien envoyé sur votre messagerie à <b>%s</b>\r\n\r\nS\'il vous plaît, regardez dans votre messagerie et cliquez sur le lien joint pour que nous ayons confirmation de votre adresse mail. Nous vérifierons ensuite votre profil et vous avertirons par mail dès qu\'il sera définitivement accepté.', '2008-02-19 18:33:46', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('signuperrorneedtoconfirmmail', 'hr', 'messages', 'Već si stvorio-la profil ali ga nisi potvrdio klikanjem na poveznicu koju sčo poslali na email adresu %s.\r\nMolimo te provjeri svoju dolaznu poštu, odgovori na poruku koju smo ti poslali i daj nam čalo vremena da pregledamo tvoju prijavu.', '2012-09-19 20:37:08', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 24014),
	('signuperrorneedtoconfirmmail', 'it', 'messages', 'Ci dispiace, hai già creato un profilo però non lo hai confermato cliccando sul link che ti abbiamo mandato al tuo indirizzo di posta elettronica %s. Per favore controlla la tua posta elettronica, rispondi al messaggio che ti abbiamo mandato e poi aspetta un po’ affinché possiamo rivedere la tua richiesta di diventare membro.', '2008-03-15 18:06:49', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
	('signuperrorneedtoconfirmmail', 'lt', 'messages', 'Atsiprašome, tačiau jūs jau turite savo sukurtą anketa - jūs tiesiog dar nepatvirtinote jos: tam reikia spustelėti ant duotos nuorodos elektroniniame laiške, kurį mes nusiųntėme jums adresu %s. Prašom patikrinti savo el.pašto dėžutę, atsakyti į laišką, kurį mes jums nusiuntėme, ir paskui luktelti, kol mes peržiūrėsime jūsų paraišką.', '2008-02-22 23:22:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 227),
	('signuperrorneedtoconfirmmail', 'nl', 'messages', 'Je hebt al een profiel aangemaakt, maar je hebt het nog niet bevestigd door de klikken op de link die we gestuurd hebben aan e-mailadres: %s.\r\n\r\nControleer alsjeblieft je e-mail, antwoord op het bericht dat we je gestuurd hebben en wacht dan even tot we je aanmelding bekeken hebben.', '2014-01-13 14:15:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 40169),
	('signuperrorneedtoconfirmmail', 'pt', 'messages', 'Lamentamos, mas já criou um perfil e não chegou a confirmar através do link que lhe foi enviado para o email %s.\r\n\r\nPor favor verifique a sua caixa de email, responda á mensagem enviada e aguarde enquanto a sua candidatura é revista.', '2013-01-16 19:37:16', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 30452),
	('signuperrorneedtoconfirmmail', 'ru', 'messages', 'Вы уже создали профиль, но не активировали его, нажав на ссылку, отправленную вам письмом по адресу %s.\r\n\r\nПожалуйста, проверьте вашу почту, отправьте ответ на присланное вам сообщение, и немного подождите, пока мы подтвердим вашу заявку. ', '2009-03-09 12:19:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 79),
	('signuperrornomothertongue', 'cs', 'messages', 'Prosím, vyber mateřský jazyk', '2014-11-28 23:57:34', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('signuperrornomothertongue', 'de', 'messages', 'Bitte wähle eine Muttersprache.', '2015-01-21 20:27:54', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 92901),
	('signuperrornomothertongue', 'el', 'messages', 'Επιλογή μητρικής γλώσσας', '2017-08-31 20:27:27', '2020-08-26 15:06:32', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('signuperrornomothertongue', 'en', 'messages', 'Please select a mother tongue', '2014-10-07 21:29:19', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', 'Error message in case no mother tongue was selected', 5, NULL, 1),
	('signuperrornomothertongue', 'eo', 'messages', 'Elektu denaskan lingvon', '2020-05-31 14:31:42', '2020-05-31 14:31:42', '2020-05-31 14:31:42', 'no', '', 5, NULL, 261823),
	('signuperrornomothertongue', 'es', 'messages', 'Selecciona el idioma materno', '2014-12-20 10:40:21', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 85785),
	('signuperrornomothertongue', 'fr', 'messages', 'Veuillez choisir une langue maternelle.', '2014-11-25 12:00:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('signuperrornomothertongue', 'gl', 'messages', 'Por favor selecciona a túa lingua materna', '2021-02-03 17:58:31', '2021-02-03 17:58:31', '2021-02-03 17:58:31', 'no', '', 5, NULL, 210880),
	('signuperrornomothertongue', 'hy', 'messages', 'Խնդրում ենք ընտրել մայրենի լեզու։', '2025-06-08 02:30:45', '2025-06-08 02:30:45', '2025-06-08 02:30:45', 'no', '', 5, NULL, 519603),
	('signuperrornomothertongue', 'it', 'messages', 'Scegli una lingua madre', '2015-01-05 13:12:21', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('signuperrornomothertongue', 'nl', 'messages', 'Selecteer een moedertaal', '2015-10-10 18:04:57', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('signuperrornomothertongue', 'pl', 'messages', 'Proszę wybrać swój język ojczysty', '2019-04-14 09:50:08', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37896),
	('signuperrornomothertongue', 'pt', 'messages', 'Por favor escolha uma língua natal', '2014-10-23 10:36:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('signuperrornomothertongue', 'pt-BR', 'messages', 'Por favor, escolha seu idioma nativo', '2016-12-20 13:54:09', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160059),
	('signuperrornomothertongue', 'ru', 'messages', 'Пожалуйста, выберите родной язык', '2014-12-06 06:08:51', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('signuperrornomothertongue', 'sr', 'messages', 'Молимо да изаберете матерњи језик', '2014-11-20 11:27:08', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('signuperrorpasswordcheck', 'bg', 'messages', 'Потвърждението на паролата Ви не съвпада. Допуснали сте грешка при въвеждането на паролата си. Тя трябва да бъде поне 8 знака.', '2007-07-11 00:24:58', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 851),
	('signuperrorpasswordcheck', 'ca', 'messages', 'La contrasenya de confirmació és incorrecta. T\'has equivocat en introduir-la. Ha de tenir 8 caràcters com a mínim.', '2007-09-09 18:50:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 177),
	('signuperrorpasswordcheck', 'cs', 'messages', 'Ověření hesla nepasuje. Udělal(a) jsi chybu při vložení hesla. Musí mít alespoň 8 znaků.', '2014-01-10 09:51:16', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('signuperrorpasswordcheck', 'de', 'messages', 'Dein Bestätigungspasswort funktioniert nicht. Du scheinst einen Fehler bei der Eingabe des Passwortes gemacht zu haben. Es muss mindestens 8 Zeichen lang sein.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('signuperrorpasswordcheck', 'el', 'messages', 'Ο κωδικός επιβεβαίωσης δεν ταιριάζει. Έκανες κάποιο λάθος κατά την εισαγωγή του. Πρέπει να αποτελείται από τουλάχιστον 8 χαρακτήρες.', '2013-10-07 19:44:05', '2020-08-25 16:53:20', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('signuperrorpasswordcheck', 'en', 'messages', 'The verification password doesn\'t match. You made a mistake entering your password. It must be at least 8 characters long.', '2008-04-13 16:15:10', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', 'Error message display when entered password at subscription or change password is bad', 5, NULL, 15240),
	('signuperrorpasswordcheck', 'eo', 'messages', 'La enskribitaj pasvortoj ne kongruas. Vi mistajpis. Atentu, ke la pasvorto devas konsisti el almenaŭ 8 signoj.', '2007-09-11 18:02:15', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 47526),
	('signuperrorpasswordcheck', 'es', 'messages', 'La verificación de la contraseña no coincide.Has hecho un error al introducir tu contraseña. Debe tener al menos 8 caracteres', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 188),
	('signuperrorpasswordcheck', 'eu', 'messages', 'Berrespeneko pasahitza ez dator bat. Pasahitza idazterakoan akats bat egin duzu. Gutxienez 8 karaktere izan behar ditu.', '2012-11-21 20:02:28', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11907),
	('signuperrorpasswordcheck', 'fi', 'messages', 'Varmistussalasana ei sovi yhteen. Kirjoitit ehkä väärin salasanasi. Sen täytyy olla ainakin 8 merkkiä pitkä.', '2007-09-19 17:34:02', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 525),
	('signuperrorpasswordcheck', 'fr', 'messages', 'Les mots de passe ne correspondent pas. Merci de vérifier votre mot de passe. Il doit comporter au moins 8 caractères.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('signuperrorpasswordcheck', 'gl', 'messages', 'O contrasinal de verificación non coincide. Tiveches un erro ao introducir o teu contrasinal. Debe ter polo menos oito caracteres.', '2022-01-18 09:09:09', '2022-01-18 09:09:09', '2022-01-18 09:09:09', 'no', '', 5, NULL, 210880),
	('signuperrorpasswordcheck', 'hr', 'messages', 'Potvrda šifre nije istovjetna. Pogrešno si unijeo/la šifru. Mora imati najmanje 8 znakova', '2009-09-18 19:50:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 24014),
