	('signuperrorprovidegender', 'cs', 'messages', 'Zdá se, že jsi zapomněl(a) vybrat pohlaví. Poznámka: Na profilu si můžeš pohlaví skrýt (je to možnost v nastavení).', '2016-08-09 15:42:38', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
