	('signuperrorprovidezip', 'en', 'messages', 'Please provide your post code or Zip number (enter 0 if you have none)', '2008-04-13 16:15:10', '2019-04-23 18:16:49', '2010-04-17 17:05:15', 'no', '', 5, 1, 101),
	('signuperrorprovidezip', 'eo', 'messages', 'Bonvolu indiki vian poŝtkodon aŭ Zip-numeron (entajpu 0 se vi havas neniun)', '2007-09-11 20:09:22', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 47220),
