	('signuperrorusernamealreadytaken', 'ru', 'messages', 'Такое имя пользователя %s уже существует!', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 79),
	('signuperrorusernamealreadytaken', 'sk', 'messages', 'Prihlasovacie meno %s sa už používa!', '2013-03-30 18:31:38', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48253),
