	('signupgenderdescription', 'en', 'messages', 'enter your gender here. You can also choose to hide it', '2007-06-26 18:51:03', '2019-04-23 18:16:49', '2008-04-13 16:16:26', 'no', '', 5, 1, 1),
	('signupgenderdescription', 'eo', 'messages', 'Entajpu vian sekson ĉi tie. Vi povas ankaŭ kaŝi ĝin.', '2013-03-14 18:16:34', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 47220),
	('signupgenderdescription', 'es', 'messages', 'Ingresa tu sexo. Puedes ocultarlo si así lo deseas.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1328),
	('signupgenderdescription', 'fi', 'messages', 'Aseta sukupuolesi tähän. Tämä ei ole deittisivusto eikä tätä voi käyttää hauissa.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 72),
	('signupgenderdescription', 'fr', 'messages', 'précisez ici votre sexe. Vous pouvez aussi choisir de cacher cette information.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 452),
	('signupgenderdescription', 'hr', 'messages', 'Unesi svoj spol. Možeš odabrati da bude sakriven', '2009-09-12 16:04:11', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 8197),
	('signupgenderdescription', 'hu', 'messages', 'add meg a nemed. Ha szeretnéd láthatatlanná teheted', '2007-09-06 19:45:52', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 805),
	('signupgenderdescription', 'it', 'messages', 'Inserisci qui il genere. Puoi anche scegliere di nasconderlo.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
	('signupgenderdescription', 'lt', 'messages', 'Įveskite čia savo lytį. Jūs taip pat galite pasirinkti paslėpti ją.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 227),
	('signupgenderdescription', 'lv', 'messages', 'ievadi šeit savu dzimumu. Tu vari arī izvēlēties to nerādīt', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 375),
	('signupgenderdescription', 'nl', 'messages', 'Vul je geslacht hier in. Je kan ook kiezen dit niet zichtbaar te maken.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 22382),
	('signupgenderdescription', 'pl', 'messages', 'wpisz tu swoją płeć. Możesz też zdecydować, że nie będzie widoczna.', '2007-09-20 21:09:22', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1554),
