	('signupmailconfirmederrorwrongkey', 'en', 'messages', 'An error occurred while processing your confirmation link. The confirmation code does not match your username. If this error persists, please contact us using the feedback page and include your confirmation link in the message.', '2012-01-05 19:51:48', '2019-04-23 18:16:49', '2012-01-05 19:51:48', 'no', '', 5, 1, 202),
	('signupmailconfirmederrorwrongkey', 'fr', 'messages', 'Une erreur s’est produite lors de la création du lien de confirmation. Le code de confirmation ne correspond pas à votre nom d’utilisateur. Si cette erreur se reproduit, faites-le-nous savoir par l’intermédiaire de la page de contact en joignant le lien de confirmation à votre message.', '2012-01-06 14:19:26', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 9823),
	('signupmailconfirmederrorwrongkey', 'it', 'messages', 'Si è verificato un errore con il link di conferma. Il codice di conferma non combacia con il tuo username. Se questo errore persiste, ti preghiamo di contattarci attraverso la pagina di feedback, segnalandoci il problema e includendo il tuo link di conferma.', '2013-01-15 18:20:35', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 14616),
