	('signupresentmailtitle', 'gl', 'messages', 'Volveuse enviar a ligazón de activación', '2021-02-07 13:57:11', '2021-02-07 13:57:11', '2021-02-07 13:57:11', 'no', '', 5, NULL, 210880),
	('signupresentmailtitle', 'it', 'messages', 'Collegamento per l\'attivazione rispedito', '2014-08-29 22:29:00', '2021-02-28 19:39:09', '0000-00-00 00:00:00', 'no', '', 0, NULL, 160610),
	('signupresentmailtitle', 'nl', 'messages', 'Bevestigingskoppeling opnieuw verstuurd', '2013-10-04 16:10:11', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 21169),
	('signupresentmailtitle', 'pl', 'messages', 'Ponownie wysłano link aktywacyjny.', '2021-01-14 20:02:15', '2021-01-14 20:02:15', '2021-01-14 20:02:15', 'no', '', 5, NULL, 116789),
	('signupresentmailtitle', 'pt', 'messages', 'Ligação de ativação reenviada', '2014-01-02 22:25:57', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 38787),
	('signupresentmailtitle', 'pt-BR', 'messages', 'Link de ativação de conta enviado novamente', '2016-12-12 02:18:04', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160059),
	('signupresentmailtitle', 'ru', 'messages', 'Подтверждение отправлено заново', '2014-04-02 17:35:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 73061),
	('signupresentmailtitle', 'sr', 'messages', 'Поновно слање потврде', '2013-10-30 19:44:20', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 0, NULL, 39772),
	('signupresutltextconfimation', 'bg', 'messages', 'Поздравления,<b>%s</b>, Ващата регистрация е активирана!\r\nМоля, проверете Е-мейла си в %s след няколко минути, ще Ви изпратим Е-мейл, където ще видите линк за потвърждаване на Вашия Е-мейл. ', '2007-07-11 00:13:06', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 851),
	('signupresutltextconfimation', 'ca', 'messages', 'Enhorabona <b>%s</b>! Ja has fet el primer pas per a registrar-te!\r\n\r\nComprova el correu a %s. En uns quants minuts rebràs un missatge on hi haurà un enllaç per a confirmar l\'adreça electrònica.', '2007-09-12 20:18:32', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 177),
	('signupresutltextconfimation', 'cs', 'messages', 'Gratulujeme <b>%s</b>, tvá registrace je na cestě!\r\nProsím, zkontroluj svou schránku na %s. Během několika minut obdržíš e-mail, v kterém najdeš odkaz pro ověření tvé e-mailové adresy.', '2014-01-10 09:29:33', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('signupresutltextconfimation', 'de', 'messages', 'Herzlichen Glückwunsch <b>%s</b>, deine Anmeldung ist unterwegs!\r\nBitte überprüfe dein E-Mail-Posteingang von %s. In ein paar Minuten wirst du eine E-Mail erhalten. Dort findest du einen Link zur Bestätigung deiner E-Mail-Adresse.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3050),
	('signupresutltextconfimation', 'el', 'messages', 'Συγχαρητήρια <b>%s</b>,  η εγγραφή σου σχεδόν ολοκληρώθηκε.\r\nΈλεγξε τα εισερχόμενα στο %s. Σε λίγα λεπτά, θα λάβεις ένα email όπου θα βρεις τον σύνδεσμο επιβεβαίωσης της διεύθυνσης ηλεκτρονικού σου ταχυδρομείου.', '2020-08-20 11:44:20', '2020-08-28 17:55:44', '2020-08-20 11:44:20', 'no', '', 5, NULL, 266544),
	('signupresutltextconfimation', 'en', 'messages', 'Congratulations <b>%s</b>, your registration is on the way!\r\nPlease check your inbox at %s. In a few minutes, you will receive an email where you will find a link to confirm your email address.\r\n', '2007-08-26 10:08:55', '2019-04-23 18:16:49', '2008-04-13 16:16:26', 'no', 'This is the text which is displayed after a member has just subscribe ', 5, NULL, 612),
	('signupresutltextconfimation', 'es', 'messages', '¡Felicidades <b>%s</b>! Tu registro está en camino.\r\nPor favor revisa tu bandeja de entrada en &s. En los próximos minutos recibirás un mensaje electrónico donde deberá aparecer un enlace de confirmación de dirección electrónica.', '2007-12-30 17:46:55', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1328),
	('signupresutltextconfimation', 'fr', 'messages', 'Félicitations <b>%s</b>, votre inscription est en cours !\r\n\r\nVeuillez vérifier la boîte de réception de %s. \r\n\r\nD\'ici quelques minutes, vous devriez y recevoir un message avec un lien pour confirmer votre adresse e-mail. Cliquez sur ce lien ou collez-le dans la barre d\'adresse de votre navigateur.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('signupresutltextconfimation', 'gl', 'messages', '<p>Parabéns <strong>%s</strong>, o teu rexistro está case listo! Por favor comproba a caixa de entrada de %s. En poucos minutos, recibirás un correo onde atoparás unha ligazón para confirmar o teu enderezo de correo electrónico.&nbsp;</p>', '2022-03-29 09:50:37', '2022-03-29 09:59:25', '2022-03-29 09:50:37', 'no', '', 5, NULL, 210880),
	('signupresutltextconfimation', 'hr', 'messages', 'Čestitamo, <b>%s</b>, tvoja registracija je na putu! \r\nProvjeri poštanski sandučić na %s. Kroz nekoliko minuta ćeš dobiti e-mail s poveznicom za potvrdu svoje e-mail adrese. ', '2009-09-19 09:59:21', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('signupresutltextconfimation', 'hu', 'messages', 'Gratulálunk <b>%s</b>, a regisztrációd feldolgozás alatt van! Ellenőrizd a leveleidet itt %s. Néhány percen belül kapsz egy e-mailt, az ebben található linken keresztül megerősítheted az e-mail címedet.', '2007-09-19 12:26:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 805),
	('signupresutltextconfimation', 'it', 'messages', 'Congratulazione <b>%s</b> , la tua registrazione sta per essere completata! Per favore, tra qualche minuto controlla la tua casella di posta in entrata su %s. Entro pochi minuti riceverai un link per potere confermare il tuo indirizzo di posta elettronica.\r\n\r\n', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 103),
	('signupresutltextconfimation', 'lt', 'messages', 'Sveikiname, <b>%s</b>, jūsų registracijos duomenys jau išsiųsti! Patikrinkite neužilgo savo el. pašto dėžutę (%s) - mes išsiuntėme jums žinutę, kurioje rasite nuorodą savo el. pašto adresui patvirtinti.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('signupresutltextconfimation', 'lv', 'messages', 'Apsveicam <b>%s</b> , tava reģistrācija ir ceļā!\r\nLūdzu, pārbaudi savu epastu %s. Pēc dažām minūtēm mēs nosūtīsim tev epastu, kur tu atradīsi linku savas epasta adreses apstiprināšanai. ', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 375),
	('signupresutltextconfimation', 'nl', 'messages', 'Gefeliciteerd <b>%s</b>, je registratie is in behandeling!\r\n\r\nControleer alsjeblieft je e-mail op %s over een paar minuten, we zullen je een e-mail sturen waarin je een link zult vinden waarmee je je e-mailadres kunt bevestigen.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40169),
	('signupresutltextconfimation', 'pl', 'messages', 'Gratulacje <b>%s</b>, twoja rejestracja jest w trakcie realizowania!\r\nSprawdź swoją skrzynkę e-mailową %s. W ciągu kilku minut powinieneś otrzymać wiadomość zawierającą link potwierdzający twój adres e-mail. ', '2007-09-21 07:54:22', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1554),
	('signupresutltextconfimation', 'pt', 'messages', 'Parabéns <b>%s</b>, a sua inscrição está a caminho!\r\nPor favor verifique a sua caixa de correio eletrónico %s. Dentro de momentos, irá receber uma mensagem onde  encontra o link de confirmação do seu endereço eletrónico.', '2012-07-11 20:37:53', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('signupresutltextconfimation', 'ru', 'messages', 'Поздравляем, <b>%s</b> , ваша регистрация проходит успешно :) !\r\n\r\nПожалуйста, проверьте свой почтовый ящик на %s. Через несколько минут мы пришлем вам письмо для подтверждения адреса электронной почты.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 79),
	('signupretypeemailshortdesc', 'bg', 'messages', 'Въведете Е-мейла си повторно, за да е сигурно, че е правилен.', '2007-07-11 12:10:55', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 851),
	('signupretypeemailshortdesc', 'ca', 'messages', 'Torna a escriure l\'adreça electrònica per assegurar-te que és correcta.', '2007-08-29 22:23:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 177),
	('signupretypeemailshortdesc', 'cs', 'messages', 'Přepiš svou e-mailovou adresu, abys ověril(a), že je správně.', '2014-01-10 09:08:12', '2023-09-20 05:40:14', '0000-00-00 00:00:00', 'no', '', 5, 1, 34292),
	('signupretypeemailshortdesc', 'de', 'messages', 'Gibt deine E-Mail-Adresse noch einmal ein, um ihre Richtigkeit zu bestätigen.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 15240),
	('signupretypeemailshortdesc', 'en', 'messages', 'Retype your email address to make sure it is correct.', '2007-08-25 18:56:12', '2019-04-23 18:16:49', '2008-04-13 16:16:26', 'no', 'This is the invite forentering a copy of the previous entered mail to have less mistake', 5, 1, 612),
	('signupretypeemailshortdesc', 'es', 'messages', 'Reingresa tu correo electrónico para asegurarnos de que es correcta.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1328),
	('signupretypeemailshortdesc', 'fi', 'messages', 'Kirjoita sähköpostiosoite uudelleen varmistaaksesi sen oikeellisuuden.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 72),
	('signupretypeemailshortdesc', 'fr', 'messages', 'Re-écrivez votre e-mail, afin de s\'assurer que vous n\'avez pas fait de faute de frappe la première fois.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 452),
	('signupretypeemailshortdesc', 'hr', 'messages', 'Ponovno unesi e-mail adresu i zatim provjeri je li pravilno napisana.', '2010-01-05 10:30:37', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 8197),
	('signupretypeemailshortdesc', 'hu', 'messages', 'Add meg újra az e-mail címed, hogy biztosan jó legyen.', '2007-08-13 07:00:20', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 805),
	('signupretypeemailshortdesc', 'it', 'messages', 'Riscrivi l\'indirizzo e-mail, per assicurare che sia corretto', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
	('signupretypeemailshortdesc', 'lt', 'messages', 'Dar kartą įveskite el. pašto adresą (įsitikinimui, kad įvedėte jį teisingai).', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 227),
	('signupretypeemailshortdesc', 'lv', 'messages', 'Vēlreiz ievadi sava epasta adresi, lai pārliecinātos, ka tā ir pareiza.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 375),
	('signupretypeemailshortdesc', 'nl', 'messages', 'Tik je email adres nogmaals als controle', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('signupretypeemailshortdesc', 'pl', 'messages', 'Wpisz jeszcze raz swój adres mailowy.', '2007-07-19 14:38:56', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 90),
	('signupretypeemailshortdesc', 'pt', 'messages', 'Re-introduza o seu email e certifique-se de que esta correcto.', '2012-07-11 21:10:02', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 30452),
	('signupretypeemailshortdesc', 'pt-BR', 'messages', 'Reescreva o email para garantir que está correto.', '2007-08-08 18:37:41', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, 1, 144),
	('signupretypeemailshortdesc', 'ro', 'messages', 'Rescrie adresa ta de email pentru a fi siguri că e corectă', '2007-09-25 20:55:46', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1081),
	('signupretypeemailshortdesc', 'ru', 'messages', 'Введите адрес электронной почты еще раз, пожалуйста, чтобы избежать ошибок.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 79),
	('signupretypeemailshortdesc', 'tr', 'messages', 'E-postanızı tekrar giriniz ve doğru olduğundan emin olunuz', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('signupsecondnameoptional', 'bg', 'messages', 'Бащино име (по желание)', '2007-07-04 21:01:33', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 851),
	('signupsecondnameoptional', 'ca', 'messages', 'Segon nom (opcional)', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
