	('signupsecondnameoptional', 'de', 'messages', 'Zweiter Vorname (optional)', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('signupsecondnameoptional', 'el', 'messages', 'Μεσαίο όνομα (προαιρετικό)', '2010-05-04 21:52:39', '2020-08-24 14:04:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('signupsecondnameoptional', 'en', 'messages', 'Second name (optional)', '2008-04-13 16:15:10', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', 'This is what is displayed above the second name field in the signup page.\r\n', 5, NULL, 15240),
	('signupsecondnameoptional', 'eo', 'messages', 'Dua nomo (ne deviga)', '2007-09-12 02:05:12', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 47220),
