	('signupusername', 'sk', 'messages', 'Užívateľské meno', '2013-03-26 23:13:27', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48253),
	('signupusername', 'sl', 'messages', 'Uporabniško ime', '2019-03-30 23:53:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 106553),
