	('signupusername', 'uk', 'messages', 'Логін', '2026-04-03 16:44:46', '2026-04-03 16:44:46', '2026-04-03 16:44:46', 'no', '', 5, NULL, 573491),
	('signupusername', 'vi', 'messages', 'Tên người dùng', '2021-10-26 15:31:45', '2021-10-26 15:31:45', '2021-10-26 15:31:45', 'no', '', 5, NULL, 293926),
	('signupusername', 'zh-hans', 'messages', '用户名', '2009-11-08 17:06:43', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 9518),
	('signupusername', 'zh-hant', 'messages', '使用者名稱', '2009-11-08 17:06:43', '2021-05-02 07:48:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 53422),
	('signupusernamedescription', 'bg', 'messages', 'Това е Вашето потребителско име, с което ще Ви виждат потребителите. То може да съдържа само букви и/или цифри.', '2007-07-11 12:44:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 851),
	('signupusernamedescription', 'ca', 'messages', 'Aquest és el teu nom d\'usuari, tots els usuaris i les usuàries et veuran amb aquest nom. Només pot contenir lletres i/o xifres.', '2007-08-30 22:30:12', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 3236),
	('signupusernamedescription', 'cs', 'messages', 'Toto je tvé uživatelské jméno, pod kterým tě uvidí ostatní uživatelé. Obsahovat může pouze písmena a/nebo číslice.', '2013-03-24 17:50:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 33091),
	('signupusernamedescription', 'da', 'messages', 'Dette er dit brugernavn - det navn som de andre brugere vil se dig under. Det kan kun bestå af bogstaver og eller numre.', '2009-01-03 14:56:37', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 74),
	('signupusernamedescription', 'de', 'messages', 'Dies ist dein Benutzername, unter dem dich alle übrigen Mitglieder sehen werden.\r\nEr kann nur Buchstaben und/oder Zahlen enthalten.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 3050),
	('signupusernamedescription', 'el', 'messages', 'Αυτό είναι το όνομα χρήστη σας, το όνομα με το οποίο όλοι οι χρήστες θα σε βλέπουν. Μπορεί να περιέχει μόνο γράμματα και/ή ψηφία.', '2013-12-09 14:43:35', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 25930),
	('signupusernamedescription', 'en', 'messages', 'This is your username, the name under which all users will see you.\r\nIt can only contain letters and/or digits.', '2008-04-13 16:15:10', '2019-04-23 18:16:49', '2008-04-13 16:16:26', 'no', '', 5, 1, 1),
	('signupusernamedescription', 'eo', 'messages', 'Jen via uzantonomo, la nomo per kio ĉiuj uzantoj vidos vin. Nur estu kajaŭ leteroj kajaŭ numeroj.', '2008-09-16 06:33:11', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1769),
	('signupusernamedescription', 'es', 'messages', 'Este es tu nombre de usuario, el nombre bajo el cual todos los usuarios te verán. \r\nSolo puede contener letras y/o digitos.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1328),
	('signupusernamedescription', 'fi', 'messages', 'Tämä on käyttäjänimesi, jonka kaikki toiset käyttäjät näkevät. Se voi sisältää ainoastaan kirjaimia ja/tai numeroita. ', '2009-06-21 09:31:44', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 525),
	('signupusernamedescription', 'fr', 'messages', 'Ceci est votre nom d\'utilisateur, le nom sous lequel les autres membres vous connaîtrons.\r\nIl ne peut contenir que des lettres et des chiffres.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 9823),
	('signupusernamedescription', 'he', 'messages', 'זה שם המשתמש שלך, השם שתחתיו כל המשתמש האחרים יראו אותך. הוא יכול להכיל רק אותיות ו\\או מספרים', '2011-04-30 11:22:51', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 13904),
	('signupusernamedescription', 'hr', 'messages', 'Ovo je tvoje korisničko ime tj. ime pod kojim će korisnici vidjeti tvoj profil. Može se sastojati samo od slova i/ili brojki.', '2009-09-02 13:12:57', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 8197),
	('signupusernamedescription', 'hu', 'messages', 'Ez a felhasználóneved. Mostantól az összes többi felhasználó előtt ezen a néven fogsz szerepelni. Csak betűket és/vagy számokat tartalmazhat. ', '2007-09-19 12:32:56', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 805),
	('signupusernamedescription', 'it', 'messages', 'Questo è il tuo nome utente, il nome con cui tutti gli altri membri ti vedranno. Può contenere solo lettere e/o numeri.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 16084),
	('signupusernamedescription', 'lt', 'messages', 'Tai jūsų vartotojo vardas - vardas, kuris bus matomas visiems BW nariams.\r\nJis gali susidėti tik iš raidžių bei skaitmenų.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 80),
	('signupusernamedescription', 'lv', 'messages', 'Šis ir tavs lietotājvārds, vārds, pēc kura visi lietotāji tevi redzēs.\r\nTas var sastāvēt tikai no burtiem un/vai cipariem.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 375),
	('signupusernamedescription', 'nl', 'messages', 'Dit is je gebruikersnaam, de naam waarmee je te zien zult zijn voor andere gebruikers. Hij kan alleen maar letters en/of cijfers bevatten.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 22382),
	('signupusernamedescription', 'pl', 'messages', 'To jest Twój nick, czyli "imię", pod którym będą Cię znali inni użytkownicy. Nick może jedynie zawierać litery i/lub cyfry.', '2007-07-08 18:23:33', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 90),
	('signupusernamedescription', 'pt', 'messages', 'Este é o seu nome de usuário, o nome sob o qual todos os usuários irão vê-lo. Ela só pode conter letras e / ou dígitos.', '2009-09-01 11:31:45', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 9030),
	('signupusernamedescription', 'pt-BR', 'messages', 'Este é seu nome de usuário, pelo qual todos os usuários irão vê-lo.\r\nDeve conter apenas letras e/ou números', '2007-08-08 19:20:35', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, 1, 144),
	('signupusernamedescription', 'ro', 'messages', 'Acesta este numele tău de utilizator, numele sub care toţi ceilalţi utilizatori te vor găsi. Nu poate conţine decât litere şi/sau cifre.', '2007-09-25 21:06:46', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1081),
	('signupusernamedescription', 'ru', 'messages', 'Это ваше имя пользователя, под которым вы будете известны другим участникам сообщества. Оно может содержать только буквы и/или цифры.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 79),
	('signupusernamedescription', 'sr', 'messages', 'Ово је твоје корисничко име, име под којим ће те сви корисници видети. Може да садржи само слова и бројеве.', '2013-01-26 11:20:52', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 39772),
	('signupusernamedescription', 'sv', 'messages', 'Detta är ditt användarnamn, namnet som alla användare kommer att se. Det kan bara innehålla bokstäver och/eller siffror.', '2013-02-15 19:57:11', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 23263),
	('signupusernamedescription', 'tr', 'messages', 'Bu, diğer kullanıcıların sizi tanıyacağı kullanıcı adıdır.', '2012-12-03 22:08:43', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 35699),
	('signupusernamedescription', 'zh-hans', 'messages', '这是你的用户名，其他会员看到的名字。用户名只能由含字母和/或数字组成。', '2012-12-18 17:13:14', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, 1, 37722),
	('signupusernamedescription', 'zh-hant', 'messages', '这是你的用户名，其他会员看到的名字。用户名只能由含字母和/或数字组成。', '2012-12-18 17:13:14', '2021-05-02 07:48:37', '0000-00-00 00:00:00', 'no', '', 5, 1, 37722),
	('signupusernameshortdesc', 'bg', 'messages', 'Избери потребителско име, може да съдържа само букви и/или номера', '2007-07-05 13:31:46', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 851),
	('signupusernameshortdesc', 'ca', 'messages', 'Escull un nom d\'usuari. Només pot estar format per lletres i xifres.', '2007-08-29 21:55:31', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 177),
	('signupusernameshortdesc', 'cs', 'messages', 'Vyber si uživatelské jméno, může obsahovat jen písmena a/nebo číslice', '2013-10-17 21:59:56', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 34292),
	('signupusernameshortdesc', 'de', 'messages', 'Wähle deinen Benutzernamen. Er darf nur aus Buchstaben und/oder Zahlen bestehen.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 15240),
	('signupusernameshortdesc', 'en', 'messages', 'Choose your username, may only contain letters and/or digits', '2008-04-13 16:15:10', '2019-04-23 18:16:49', '2008-04-13 16:16:26', 'no', 'Short description of what to fill as username at signup', 5, 1, 1),
	('signupusernameshortdesc', 'es', 'messages', 'Elige tu nombre de usuario, este puede contener solo letras y digitos.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('signupusernameshortdesc', 'fi', 'messages', 'Valitse käyttäjänimi, tämä voi sisältää vain kirjaimia ja/tai numeroita.', '2007-10-17 15:44:47', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 525),
	('signupusernameshortdesc', 'fr', 'messages', 'Choisissez votre nom d\'utilisateur, il ne doit comprendre que des chiffres et des lettres', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('signupusernameshortdesc', 'hr', 'messages', 'Upiši svoje željeno korisničko ime koje smije sadržavati samo slova i/ili dvije brojke.', '2010-01-05 10:32:49', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 8197),
	('signupusernameshortdesc', 'hu', 'messages', 'Válassz egy felhasználónevet. Ez csak betűket és/vagy számokat tartalmazhat.', '2007-09-19 12:30:28', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 805),
	('signupusernameshortdesc', 'it', 'messages', 'Scegli il tuo nome utente, può contenere solo lettere e/o numeri', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
	('signupusernameshortdesc', 'lt', 'messages', 'Pasirinkite vartotojo vardą (jis gali susidėti tik iš raidžių ir skaitmenų)', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 80),
	('signupusernameshortdesc', 'lv', 'messages', 'Izvēlies savu lietotajvārdu, tas var sastāvēt tikai no burtiem un/vai cipariem', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 375),
	('signupusernameshortdesc', 'nl', 'messages', 'Kies je gebruikersnaam, hij mag alleen letters en/of cijfers bevatten.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 138),
	('signupusernameshortdesc', 'pl', 'messages', 'Wybierz swój nick. Nick może zawierać jedynie litery i cyfry.', '2007-07-08 18:22:29', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 90),
	('signupusernameshortdesc', 'pt', 'messages', 'Escolha o seu nome de utilizador, que contem apenas letras e/ou números.', '2012-07-11 21:12:26', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 30452),
	('signupusernameshortdesc', 'pt-BR', 'messages', 'Escolha seu Nome de Usuário. Deve conter apenas letras e/ou números', '2007-08-07 17:39:44', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, 1, 144),
	('signupusernameshortdesc', 'ro', 'messages', 'Alege numele de utilizator, acesta poate conţine doar litere şi/sau cifre', '2007-09-25 21:06:13', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1081),
	('signupusernameshortdesc', 'ru', 'messages', 'Введите желательное имя пользователя (пожалуйста, используйте буквы и/или цифры)', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 79),
	('signupusernameshortdesc', 'tr', 'messages', 'Kullanıcı adınızı seçin, sadece harf ve/veya sayı içerebilir', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('signupyouhavebeenaccepted', 'bg', 'messages', 'Добре дошли на борда <b>%s</b>, Вие вече сте член на <a href="%s">BeWelcome</a> ! Може да се впишете <a href="%s">тук</a>', '2007-08-05 22:13:28', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 401),
	('signupyouhavebeenaccepted', 'ca', 'messages', 'Et donem la benvinguda a bord, <b>%s</b>. Ara ja formes part de <a href="%s">BeWelcome</a>!\r\nPots connectar-te des d\'<a href="%s">aquí</a>.', '2007-08-30 22:33:43', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 177),
	('signupyouhavebeenaccepted', 'cs', 'messages', 'Vítej u nás, <b>%s</b>, teď jsi členkou/členem <a href="%s">BeWelcome</a>! Můžeš se přihlásit <a href="%s">zde</a>\r\n\r\nAž budeš přihlášen(a), zkontroluj, zda tvůj profil je kompletní. Ještě k tomu se můžeš, pokud se ti chce, představit na <a href="http://www.bewelcome.org/forums/s35">tomto jednoúčelovém vláknu fóra</a>', '2014-01-10 09:46:54', '2023-09-20 05:40:14', '0000-00-00 00:00:00', 'no', '', 5, 1, 34292),
	('signupyouhavebeenaccepted', 'de', 'messages', 'Herzlich willkommen, <b>%s</b>! Du bist nun Mitglied bei <a href="%s">BeWelcome</a>! <a href="%s">Hier</a> kannst Du Dich einloggen. \r\n\r\nWir empfehlen dir, dein Profil vollständig auszufüllen, sobald du dich eingeloggt hast. Zusätzlich gibt es im Forum einen speziellen <a href="http://www.bewelcome.org/forums/s35">Diskussionsfaden (Thread)</a>, wo du die Möglichkeit hast, dich persönlich vorzustellen. ', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 15240),
	('signupyouhavebeenaccepted', 'en', 'messages', 'Welcome on board <b>%s</b>,  you are now a member of <a href="%s">BeWelcome</a>! You can login <a href="%s">here</a>\r\n\r\nOnce you will be logged in, we suggest you to check that your profile is complete. In addition, you can also, if you want, introduce yourself in <a href="http://www.bewelcome.org/forums/s35">this dedicated forum thread</a>', '2008-03-29 16:02:42', '2019-04-23 18:16:49', '2011-07-11 19:37:53', 'no', 'This is the message that a new member receive when he his accepted as a full member of BeWelcome\r\n\r\nIt also suggest the new member to introduce himself in a dedicated forum thread', 5, 1, 111),
	('signupyouhavebeenaccepted', 'es', 'messages', 'Bienvenido a bordo <b>%s</b>, eres ahora miembro de <a href="%s">BeWelcome</a>! Puedes ingresar <a href="%s">aqui</a>', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('signupyouhavebeenaccepted', 'fi', 'messages', 'Tervetuloa mukaan <b>%s</b>, nyt olet  <a href="%s">BeWelcome</a>n jäsen! Voit kirjautua sisään <a href="%s">täällä</a>', '2007-09-18 07:16:46', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 525),
	('signupyouhavebeenaccepted', 'fr', 'messages', 'Bienvenue à bord <b>%s</b>, vous êtes maintenant membre de <a href="%s">BeWelcome</a> ! Vous pouvez vous identifier <a href="%s">ici</a>\r\n\r\nQuand vous vous serez connecté, nous vous suggérons de compléter votre profil.\r\n\r\nSi vous le voulez, vous pouvez aussi vous présenter dans le forum sur ce  <a href="http://www.bewelcome.org/forums/s35">fil de discussion dédié</a>', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('signupyouhavebeenaccepted', 'hr', 'messages', 'Dobrodošao/la <b>%s</b>! Sada si član/ica <a href="%s">BeWelcomea</a>! Prijaviti se možeš <a href="%s">ovdje</a>\r\n\r\nKada se prijaviš, predlažemo ti da odmah ispuniš svoj profil. Uz to, ako želiš možeš se predstaviti na <a href="http://www.bewelcome.org/forums/s35">stranici foruma za nove članove</a>', '2010-01-15 20:41:40', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 8197),
	('signupyouhavebeenaccepted', 'hu', 'messages', 'Üdvözlün köztünk <b>%s</b>, mostantól a <a href="%s">BeWelcome</a> tagja vagy! <a href="%s">itt</a> tudsz belépni\r\n  ', '2007-09-19 12:50:53', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 805),
	('signupyouhavebeenaccepted', 'it', 'messages', 'Benvenuto a bordo <b>%s</b>, sei ora membro di <a href="%s">BeWelcome</a> !\r\nPuoi fare login <a href="%s">qui</a>\r\n\r\nUna volta entrato, ti suggeriamo di controllare che il tuo profilo sia completo. Inoltre, se vuoi puoi presentarti agli altr membri in <a href="http://www.bewelcome.org/forums/s35">questo forum </a> ', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 16084),
	('signupyouhavebeenaccepted', 'lt', 'messages', 'Sveikiname prisijungus prie mūsų, <b>%s</b>! Jūs tapote <a href="%s">BeWelcome</a> nariu. Jūs galite prisijungti <a href="%s">čia</a>', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 80),
	('signupyouhavebeenaccepted', 'lv', 'messages', 'Laipni lūgts uz klāja <b>%s</b>, tagad tu esi <a href="%s">BeWelcome</a> biedrs! Tu vari ielogoties <a href="%s">here</a>', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 375),
	('signupyouhavebeenaccepted', 'nl', 'messages', 'Welkom bij <b>%s</b>, je bent nu een lid van <a href="%s">BeWelcome</a>! Je kunt je <a href="%s">hier</a> aanmelden.\r\n\r\nEens je aangemeld bent, raden we je aan om te controleren of je profiel compleet is.  Bovendien kan je je, als je wilt, voorstellen in <a href="http://www.bewelcome.org/forums/s35">de voorstellingsdiscussie</a>.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 21169),
	('signupyouhavebeenaccepted', 'pl', 'messages', 'Witaj wśród swoich <b>%s</b>, jesteś teraz członkiem <a href="%s">BeWelcome</a>! Możesz się zalogować klikając <a href="%s">tutaj</a>.', '2007-07-08 18:21:54', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 90),
	('signupyouhavebeenaccepted', 'pt', 'messages', 'Bem vindo a bordo <b>%s</b>, é agora um membro de <a href="%s">BeWelcome</a>! Pode conectar-se <a href="%s">aqui</a>. \r\nUma vez ligado, sugerimos-lhe que verifique se o seu perfil está completo. Pode ainda, se pretender, introduzir-se <a href="http://www.bewelcome.org/forums/s35">neste tópico dedicado do forum</a>.', '2012-07-11 20:55:49', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 30452),
	('signupyouhavebeenaccepted', 'ro', 'messages', 'Bine ai venit la bord <b>%s</b>, eşti acum un membru al <a href="%s">BeWelcome</a>! Te poţi conecta <a href="%s">aici</a>', '2007-09-25 21:05:41', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1081),
	('signupyouhavebeenaccepted', 'ru', 'messages', 'Добро пожаловать в наше сообщество <b>%s</b>, теперь вы член <a href="%s">BeWelcome</a>! Вы можете аавторизоваться <a href="%s">тут</a>', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 79),
	('signupyouhavebeenaccepted', 'tr', 'messages', 'Hosşgeldiniz <b>%s</b>, artık <a href="%s">BeWelcome</a> üyesisiniz! Buradan <a href="%s">lÃ </a> oturum açabilirsiniz. ', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('signupyouhavebeenrejected', 'bg', 'messages', 'Извинете,\r\nВашата молба за включване като %s за %s беше отхвърлена.', '2007-08-05 22:14:47', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 401),
	('signupyouhavebeenrejected', 'ca', 'messages', 'La petició com a %s per a %s ha estat desestimada.\r\n\r\nLa raó és hi ha un o alguns punts del teu registrament que no compleixen amb les nostres normes internes. Consulta les preguntes més freqüents (PMF).', '2007-09-12 20:16:14', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 177),
	('signupyouhavebeenrejected', 'cs', 'messages', 'Omlouváme se,\r\nTvoje přihláška jako %s do %s byla odmítnuta.\r\n\r\nDůvod k tomu je, že jeden či více aspektů tvé registrace není v souladu s našimi interními pravidly.\r\nProsím shlédni naše Časté dotazy.', '2014-01-10 09:49:00', '2023-09-20 05:40:14', '0000-00-00 00:00:00', 'no', '', 5, 1, 34292),
	('signupyouhavebeenrejected', 'de', 'messages', 'Dein Antrag als %s von %s wurde abgelehnt.\r\n\r\nBegründung: Eine oder mehrere Angaben deiner Anmeldung entsprechen nicht unseren internen Regeln. Bitte besuche unsere FAQ-Seite für weitere Informationen.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 15240),
	('signupyouhavebeenrejected', 'en', 'messages', 'Sorry,\r\nYour application as %s to %s has been rejected.\r\n\r\nThe reason is that one or more aspects of your registration do not comply with our internal rules.\r\nPlease refer to our FAQs.', '2007-03-24 13:44:51', '2019-04-23 18:16:49', '2008-04-13 16:16:26', 'no', '', 5, 1, 69),
	('signupyouhavebeenrejected', 'es', 'messages', 'Lo sentimos,\r\nTu aplicación como %s para %s ha sido rechazada.\r\n\r\nEl motivo es que uno o más aspectos de tu registro no cumplen con nuestras reglas internas.\r\nPor favor dirígete a nuestras Preguntas Frecuentes.', '2007-12-30 03:57:43', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1328),
	('signupyouhavebeenrejected', 'fr', 'messages', 'Désolé, votre demande d\'inscription comme %s pour %s a été rejetée. \r\n\r\nLa raison est qu\'une ou plusieures parties de votre inscription ne respectent pas nos règles internes. \r\n\r\nMerci de vous référer à notre FAQ.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 452),
	('signupyouhavebeenrejected', 'hr', 'messages', 'Žao nam je, \r\ntvoja prijava kao %s za %s je odbijena. \r\n\r\nRazlog je što jedan ili više aspekata tvoje registracije nije u skladu s našim internim pravilima. \r\nMolimo te da proučiš stranicu Najčešća pitanja.', '2010-04-04 15:32:38', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 8197),
	('signupyouhavebeenrejected', 'it', 'messages', 'Ci dispiace, la tua richiesta d\'iscrizione come %s su % è stata rifiutata.\r\nLa ragione è che uno o più punti della tua iscrizione non rispettano il nostro regolamento interno.\r\nPer favore leggi le FAQ per saperne di più.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
	('signupyouhavebeenrejected', 'lt', 'messages', 'Atsiprašome,\r\nJūsų registracijos forma vartotjo vardu %s į %s buvo atmesta.\r\n\r\nTo priežastis yra tai, kad vienas ar daugiau jūsų registracijos aspektų neatitinka mūsų svetainės vidinių taisyklių.\r\nPrašome žvilgtelėti į mūsų D.U.K. puslapį.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 80),
	('signupyouhavebeenrejected', 'lv', 'messages', 'Atvaino,\r\nTava reģistrācija kā %s uz %s ir noraidīta.\r\n\r\nTā iemesls ir viens vai vairāki tavas reģistrācijas aspekti, kas neatbilst mūsu iekšējiem noteikumiem.\r\nLūdzu, skatīt FAQ.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 375),
	('signupyouhavebeenrejected', 'nl', 'messages', 'Sorry,\r\nJe aanvraag als %s voor %s is afgewezen.\r\n\r\nDe reden is dat één of meer aspecten van je registratie niet samengaan met onze interne regels.\r\nKijk alsjeblieft in onze FAQ.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 138),
	('signupyouhavebeenrejected', 'pl', 'messages', 'Przepraszamy,\r\nTwoja aplikacja jako %s w %s została odrzucona.\r\n\r\nPowodem tego może być to, że jeden lub więcej elementów twojej aplikacji nie spełnia określonych wymogów.\r\nDowiedz się więcej czytając najczęściej zadawane pytania (FAQs).\r\n\r\n', '2007-10-13 18:15:12', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1554),
	('signupyouhavebeenrejected', 'pt', 'messages', 'Lamentamos, mas a sua candidatura como %s a %s foi rejeitada.\r\n\r\nDevido a um ou mais aspectos da sua candidatura não coincidirem com as nossas regras internas.\r\nPor favor consulte as nossas FAQs.', '2012-07-11 20:58:24', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 30452),
	('signupyouhavebeenrejected', 'ro', 'messages', 'Ne pare rău, aplicaţia ta ca %s către %s a fost respinsă.\r\n\r\nMotivul este că unul sau mai multe elemente ale cererii tale nu corespund cu regulile noastre interne.\r\nTe rugăm să citeşti mai multe în Întrebări frecvente.', '2007-09-25 21:04:58', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1081),
	('signupyouhavebeenrejected', 'ru', 'messages', 'К сожалению, ваша заявка в качестве %s в %s не была принята.\r\n\r\nОснованием для этого явилось то, что один или более аспектов вашей заявки не соответствует нашим внутренним правилам.\r\nПожалуйста, изучите наши FAQ.', '2007-09-09 08:29:18', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 79),
	('signupzip', 'bg', 'messages', 'Пощенски код', '2007-07-05 09:33:26', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 851),
