	('slogan_chinese', 'en', 'messages', '"Do not listen to what they say. Go see." Chinese proverb', '2007-07-02 10:32:06', '2007-07-19 16:15:01', '2007-07-19 16:15:01', 'no', 'Index page slogan from Chinese proverb - try to translate the meaning more than every single word', 5, 1, 91),
	('slogan_chinese', 'es', 'messages', '"No escuches lo que ellos dicen. Anda a verlo" Proverbio Chino', '2007-10-28 07:51:37', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, 1, 1328),
	('slogan_chinese', 'fr', 'messages', '"N\'écoutez pas ce qu\'ils en disent, allez plutôt le découvrir" Proverbe chinois', '2007-07-02 21:39:50', '2007-07-02 21:39:50', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('slogan_chinese', 'hr', 'messages', '"Ne slušaj što govore. Idi i vidi." kineska poslovica', '2011-12-01 17:30:57', '2011-12-01 17:30:57', '0000-00-00 00:00:00', 'no', '', 5, 1, 8197),
