	('slogan_chinese', 'it', 'messages', '"Non ascoltare quello che dicono. Vai a vedere" Chinese proverb', '2007-10-01 10:40:38', '2007-10-01 10:40:38', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
	('slogan_chinese', 'lt', 'messages', '"Neklausyk, ką tau sako. Eik pasižiūrėti pats." Kinų patarlė', '2007-08-29 04:16:56', '2008-03-03 15:32:04', '0000-00-00 00:00:00', 'no', '', 5, 1, 80),
	('slogan_chinese', 'lv', 'messages', '"Neklausies, ko citi saka. Ej apskaties." Ķīniešu paruna', '2007-08-05 12:27:03', '2007-08-05 12:27:03', '0000-00-00 00:00:00', 'no', '', 5, 1, 375),
	('slogan_chinese', 'nl', 'messages', '"Luister niet wat ze zeggen. Ga zelf kijken." Chinees spreekwoord', '2008-05-13 18:52:17', '2008-05-13 18:52:17', '0000-00-00 00:00:00', 'no', '', 5, 1, 97),
	('slogan_chinese', 'pl', 'messages', '"Nie słuchaj tego co mówią inni. Idź i sam zobacz." chińskie przysłowie', '2007-09-20 14:25:16', '2007-09-20 14:25:16', '0000-00-00 00:00:00', 'no', '', 5, 1, 1554),
	('slogan_chinese', 'pt', 'messages', '"Não acredites no que te dizem. Vai ver por ti mesmo." provérbio chinês', '2013-01-14 12:02:23', '2013-01-14 12:02:23', '0000-00-00 00:00:00', 'no', '', 5, 1, 38787),
