	('slogan_chinese', 'ru', 'messages', '"Не слушай рассказы других. Отправляйся в путь и увидь все своими глазами" - китайская пословица', '2009-03-09 12:54:36', '2009-03-09 12:54:36', '0000-00-00 00:00:00', 'no', '', 5, 1, 79),
	('slogan_chinese', 'zh-hans', 'messages', '耳听为虚, 眼见为实.', '2013-05-14 14:09:56', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, 1, 37722),
	('slogan_donttellme', 'bg', 'messages', 'Не ми се хвали колко си учил, по-добре ми кажи колко си пътувал.', '2008-04-30 15:18:31', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 851),
	('slogan_donttellme', 'ca', 'messages', 'No m\'expliquis quant has estudiat, explica\'m quant has viatjat.', '2007-10-01 11:24:12', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 177),
	('slogan_donttellme', 'de', 'messages', 'Erzähl mir nicht wie gebildet du bist, erzähl mir wieviel du gereist bist.', '2007-08-30 08:12:29', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 15240),
	('slogan_donttellme', 'en', 'messages', 'Do not tell me how educated you are, tell me how much you travelled.', '2007-08-12 10:44:13', '2019-04-23 18:16:49', '2007-08-12 10:44:13', 'no', 'This is a slogan on index page', 5, 1, 1),
	('slogan_donttellme', 'es', 'messages', 'No me digas cuán educado eres, sólo dime cuánto has viajado.', '2007-10-28 06:45:06', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1328),
	('slogan_donttellme', 'fr', 'messages', 'Ne me dites pas que vous êtes instruit, mais racontez moi plutôt ce que vous ont appris vos voyages.', '2007-08-16 12:05:23', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('slogan_donttellme', 'hr', 'messages', 'Nemoj mi pričati koliko si školovan/a, ali reci mi koliko si putovao/la.', '2009-09-19 09:28:20', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 8197),
	('slogan_donttellme', 'hu', 'messages', 'Ne azt mondd, hogy mennyire vagy képzett, hanem hogy mennyit utaztál.', '2007-08-13 06:50:14', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 805),
	('slogan_donttellme', 'it', 'messages', 'Non dirmi quanta educazione hai ricevuto, piuttosto dimmi quanto hai viaggiato.', '2007-08-19 15:40:21', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
	('slogan_donttellme', 'lt', 'messages', 'Nepasakok man apie savo išsilavinimą, bet pasakyk kiek esi nukeliavęs.', '2007-08-29 05:02:58', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 227),
	('slogan_donttellme', 'lv', 'messages', 'Nestāsti man, cik izglītots tu esi, pastāsti man, cik daudz esi ceļojis.', '2007-09-02 13:46:45', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 375),
	('slogan_donttellme', 'nl', 'messages', 'Vertel me niet hoe geleerd je bent, vertel me hoeveel je gereisd hebt.', '2008-04-11 16:11:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 97),
	('slogan_donttellme', 'pl', 'messages', 'Nie mów mi jakie masz wykształcenie, powiedz mi ile podróżowałeś.', '2007-09-20 14:44:13', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1554),
	('slogan_donttellme', 'pt', 'messages', 'Não me digas qual a tua educação, diz-me quanto viajaste.', '2013-01-14 12:08:39', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 38787),
	('slogan_donttellme', 'ro', 'messages', 'Nu-mi spune ce educaţie ai, spune-mi cât ai călătorit.', '2007-08-28 17:42:34', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1081),
	('slogan_donttellme', 'ru', 'messages', 'Не говори мне, насколько ты образован - лучше расскажи, сколько ты путешествовал', '2007-09-09 08:50:37', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 79),
	('slogan_donttellme', 'sw', 'messages', 'Usiniambia vile umesoma, niambia vile umesafiri', '2009-03-30 10:02:56', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1399),
	('slogan_einstein', 'ca', 'messages', '"M\'encanta viatjar, però odio arribar." Albert Einstein (1879 - 1955)', '2007-10-01 10:46:40', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, 1, 177),
	('slogan_einstein', 'de', 'messages', '"Ich liebe es zu reisen aber ich hasse es anzukommen." Albert Einstein (1879 - 1955)', '2007-07-27 12:02:30', '2007-07-27 12:02:30', '0000-00-00 00:00:00', 'no', '', 5, 1, 94),
	('slogan_einstein', 'en', 'messages', '"I love to travel, but I hate to arrive." Albert Einstein (1879 - 1955)', '2007-07-02 10:18:19', '2007-07-02 10:18:19', '2007-07-02 10:18:19', 'no', 'Index page slogan from Albert Einstein - try to translate the meaning more than every single word', 5, 1, 91),
	('slogan_einstein', 'es', 'messages', '"Adoro viajar, pero odio volver." Albert Einstein (1879 - 1955)', '2007-10-28 15:22:33', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, 1, 1328),
	('slogan_einstein', 'fr', 'messages', '"j\'aime voyager, mais je n\'aime pas arriver" Albert Einstein (1879 - 1955)', '2007-07-02 21:35:12', '2007-07-02 21:35:12', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('slogan_einstein', 'hr', 'messages', '"Obožavam putovati, ali mrzim stići." Albert Einstein (1879 - 1955) ', '2010-01-15 21:22:59', '2010-01-15 21:22:59', '0000-00-00 00:00:00', 'no', '', 5, 1, 8197),
	('slogan_einstein', 'hu', 'messages', '"Imádok utazni, de utálok megérkezni" Albert Einstein (1879 - 1955)', '2007-09-06 20:11:40', '2007-09-06 20:11:40', '0000-00-00 00:00:00', 'no', '', 5, 1, 805),
	('slogan_einstein', 'it', 'messages', '"Amo viaggiare, ma odio arrivare". Albert Einstein (1879 - 1955)', '2007-09-27 12:41:43', '2007-09-27 12:41:43', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
	('slogan_einstein', 'lt', 'messages', '"Dievinu kelionę, tačiau nekenčiu atvykti" Albertas Einšteinas (1879 - 1955)', '2007-08-29 04:04:32', '2008-03-03 15:27:15', '0000-00-00 00:00:00', 'no', '', 5, 1, 80),
	('slogan_einstein', 'lv', 'messages', '"Es mīlu ceļot, bet ienīstu ierasties." Alberts Einšteins (1879-1955)', '2007-08-05 12:49:45', '2007-08-05 12:49:45', '0000-00-00 00:00:00', 'no', '', 5, 1, 375),
	('slogan_einstein', 'nl', 'messages', '"Ik houd van reizen, maar ik haat arriveren." Albert Einstein (1879 - 1955)', '2008-03-29 17:29:34', '2008-03-29 17:29:34', '0000-00-00 00:00:00', 'no', '', 5, 1, 97),
	('slogan_einstein', 'pt', 'messages', '"Adoro viajar, mas detesto chegar." Albert Einstein (1879 - 1955)', '2007-07-05 11:17:29', '2007-07-05 11:17:29', '0000-00-00 00:00:00', 'no', '', 5, 1, 752),
	('slogan_einstein', 'pt-BR', 'messages', '"Adoro viajar, mas odeio xegar." Albert Einstein (1879 - 1955)', '2007-09-19 16:30:31', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, 1, 421),
	('slogan_einstein', 'ro', 'messages', '"Îmi place să călătoresc, dar nu suport să sosesc." Albert Einstein (1879 - 1955)', '2007-09-20 22:43:03', '2007-09-20 22:43:03', '0000-00-00 00:00:00', 'no', '', 5, 1, 1081),
	('slogan_einstein', 'sr', 'messages', '"Волим да путујем, али мрзим кад стигнем". Алберт Ајнштајн (1879 - 1955)', '2013-01-22 23:57:39', '2013-01-22 23:57:39', '0000-00-00 00:00:00', 'no', '', 5, 1, 39772),
	('slogan_fadiman', 'ca', 'messages', '"Quan viatgis, recorda que un país foraster no està fet per complaure\'t a tu. Està fet per a complaure als seus."  Clifton Fadiman (1904 - 1999)', '2007-10-01 10:48:19', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, 1, 177),
	('slogan_fadiman', 'de', 'messages', '"Wenn du reist, dann denke daran, dass die Lebensumstände in dem Land in dem du reist nicht dazu da sind, dass du dich wohl fühlst. Sie sind dafür da, dass sich die Einwohner dieses Landes wohl fühlen."   Clifton Fadiman (1904 - 1999)', '2007-08-30 08:19:35', '2012-09-25 19:47:50', '0000-00-00 00:00:00', 'no', '', 5, 1, 15240),
	('slogan_fadiman', 'en', 'messages', '"When you travel, remember that a foreign country is not designed to make you comfortable. It is designed to make its own people comfortable." Clifton Fadiman (1904 - 1999)', '2007-07-02 10:27:41', '2007-07-02 10:27:41', '2007-07-02 10:27:41', 'no', 'Index page slogan from Clifton Fadiman - try to translate the meaning more than every single word', 5, 1, 91),
	('slogan_fadiman', 'es', 'messages', '"Recuerda que cuando viajas un país extranjero no está diseñado para hacerte cómodo. Se diseña para hacer cómoda a su propia gente." Clifton Fadiman (1904 - 1999)', '2008-01-02 16:38:35', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, 1, 1328),
	('slogan_fadiman', 'fr', 'messages', '"lorsque vous voyager, rappelez vous que les pays étranger ne sont pas conçus pour votre confort. Ils sont conçus pour le confort de leurs habitants." Clifton Fadiman (1904 - 1999)', '2007-07-02 21:41:17', '2007-07-02 21:41:17', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('slogan_fadiman', 'hu', 'messages', '"Amikor utazol, tartsd szem előtt, hogy egy idegen országot nem azért hozták létre, hogy neked kényelmes legyen, hanem azért, hogy a lakosoknak legyen kényelmes" Clifton Fadiman (1904 - 1999)', '2007-09-06 20:10:37', '2007-09-06 20:10:37', '0000-00-00 00:00:00', 'no', '', 5, 1, 805),
	('slogan_fadiman', 'it', 'messages', '"Quando viaggi, ricordati che un paese straniero non é fatto per farti sentire a tuo agio. É fatto per fare stare la propria popolazione a suo agio" Clifton Fadiman (1904 - 1999)', '2007-10-01 10:40:08', '2007-10-01 10:40:08', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
	('slogan_fadiman', 'lt', 'messages', '"Keliaudamas atsimink: kitos šalys nėra sukurtos tavo patogumui; kiekviena šalis sukurta savo liaudies patogumui." Kliftonas Fadimanas (1904 - 1999)', '2007-08-29 04:14:53', '2008-03-03 15:31:24', '0000-00-00 00:00:00', 'no', '', 5, 1, 80),
	('slogan_fadiman', 'nl', 'messages', '“Als je reist, denk er dan aan dat een vreemd land niet is ontworpen om jou op je gemak te laten voelen.  Het is ontworpen om de inwoners zich op hun gemak te laten voelen.”  Clifton Fadiman (1904–1999)', '2011-12-21 14:30:14', '2011-12-21 14:30:14', '0000-00-00 00:00:00', 'no', '', 5, 1, 21169),
	('slogan_fadiman', 'pt', 'messages', '"Quando viajares lembra-te que um país estrangeiro não foi desenhado para te deixar confortável. Foi desenhado para deixar os seus habitantes confortáveis". Clifton Fadiman (1904-1999)', '2013-01-14 12:01:53', '2013-01-14 12:01:53', '0000-00-00 00:00:00', 'no', '', 5, 1, 38787),
	('slogan_fadiman', 'ro', 'messages', '"Atunci când călătoreşti, ia aminte că o ţară străină nu este făcută să te simţi tu bine. Ea este astfel pentru a-i face pe proprii săi locuitori să se simtă bine." Clifton Fadiman (1904 - 1999)', '2007-09-20 22:47:36', '2007-09-20 22:47:36', '0000-00-00 00:00:00', 'no', '', 5, 1, 1081),
	('slogan_kafka', 'ca', 'messages', '"Caminant es fa el camí." Franz Kafka (1883 - 1924)', '2007-10-01 10:46:58', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, 1, 177),
	('slogan_kafka', 'de', 'messages', '"Wege entstehen dadurch, dass man sie geht." Frank Kafka (1883 - 1924)', '2007-07-30 16:39:05', '2008-12-04 12:39:21', '0000-00-00 00:00:00', 'no', '', 5, 1, 3050),
	('slogan_kafka', 'en', 'messages', '"Paths are made by walking." Franz Kafka (1883 - 1924)', '2007-07-02 10:20:08', '2008-08-09 12:21:11', '2008-08-09 12:21:11', 'no', 'Index page slogan from Franz Kafka - try to translate the meaning more than every single word', 5, 1, 101),
	('slogan_kafka', 'es', 'messages', '"Los caminos se hacen caminando." Frank Kafka (1883 - 1924)', '2007-10-28 15:21:20', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, 1, 1328),
	('slogan_kafka', 'fr', 'messages', '"Les chemins se font en marchant" Frank Kafka (1883 - 1924)', '2007-07-07 17:03:30', '2007-07-07 17:03:30', '0000-00-00 00:00:00', 'no', '', 5, 1, 452),
	('slogan_kafka', 'hr', 'messages', '"Putevi su nastali hodanjem." Franz Kafka (1883 - 1924) ', '2010-01-15 21:24:12', '2010-01-15 21:24:12', '0000-00-00 00:00:00', 'no', '', 5, 1, 8197),
	('slogan_kafka', 'it', 'messages', '"I sentieri si costruiscono camminando". Frank Kafka (1883 - 1924)', '2007-09-28 10:38:39', '2007-09-28 10:38:39', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
	('slogan_kafka', 'lt', 'messages', '"Keliai išminami jais vaikštant." Francas Kafka (1883 - 1924)', '2007-12-14 19:30:22', '2008-03-03 15:28:58', '0000-00-00 00:00:00', 'no', '', 5, 1, 80),
	('slogan_kafka', 'lv', 'messages', '"Takas tiek izveidotas staigājot" Frenks Kafka (1883 - 1924)', '2007-08-10 12:31:23', '2007-08-10 12:31:23', '0000-00-00 00:00:00', 'no', '', 5, 1, 375),
	('slogan_kafka', 'nl', 'messages', '"Paden zijn gemaakt door lopen." Franz Kafka (1883 - 1924)', '2008-03-29 17:29:57', '2008-03-29 17:29:57', '0000-00-00 00:00:00', 'no', '', 5, 1, 97),
	('slogan_kafka', 'pt', 'messages', '"Caminhos fazem-se a caminhar." Frank Kafka (1883 - 1924)', '2007-07-05 11:17:25', '2014-01-03 18:20:51', '0000-00-00 00:00:00', 'no', '', 5, 1, 38787),
	('slogan_kafka', 'pt-BR', 'messages', '"Os caminhos são feitos caminhando." Frank Kafka (1883 - 1924)', '2007-09-19 16:32:27', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, 1, 421),
	('slogan_kafka', 'ro', 'messages', '"Drumurile se fac mergând." Frank Kafka (1883 - 1924)', '2007-09-20 22:43:33', '2007-09-20 22:43:33', '0000-00-00 00:00:00', 'no', '', 5, 1, 1081),
	('slogan_kafka', 'sr', 'messages', '"Путеви су прављени за шетање." Франц Кафка (1883 - 1924)', '2013-01-22 23:58:14', '2013-01-22 23:58:14', '0000-00-00 00:00:00', 'no', '', 5, 1, 39772),
	('slogan_maupassant', 'ca', 'messages', 'Fer noves coneixences fa que valgui la pena viure.', '2008-04-02 14:19:33', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, 1, 3236),
	('slogan_maupassant', 'de', 'messages', 'Der Kontakt zu Menschen macht das Leben erst lebenswert.', '2007-12-13 08:56:29', '2007-12-13 17:21:25', '0000-00-00 00:00:00', 'no', '', 5, 1, 91),
	('slogan_maupassant', 'en', 'messages', 'Meeting people is what makes life worth living.', '2007-12-08 11:31:14', '2007-12-08 13:19:30', '2007-12-08 13:19:30', 'no', 'quote from guy de maupassant', 5, 1, 1),
	('slogan_maupassant', 'es', 'messages', 'Conocer gente le da sentido a la vida.', '2007-12-31 16:21:43', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, 1, 1328),
	('slogan_maupassant', 'fr', 'messages', 'Le voyage est une espèce de porte par où l\'on sort de la réalité comme pour pénétrer dans une réalité inexplorée qui semble un rêve.', '2007-12-08 13:31:55', '2007-12-08 13:31:55', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('slogan_maupassant', 'it', 'messages', 'Incontrare persone e ciò che rende la vita degna di essere vissuta', '2007-12-24 13:34:26', '2007-12-24 13:34:26', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
	('slogan_maupassant', 'lt', 'messages', 'Naujos pažintys yra tai, kas daro gyvenimą prasmingesniu.', '2007-12-14 19:54:50', '2007-12-14 19:54:50', '0000-00-00 00:00:00', 'no', '', 5, 1, 227),
	('slogan_maupassant', 'nl', 'messages', 'Mensen ontmoeten maakt het leven de moeite waard.', '2008-03-29 18:01:15', '2008-03-29 18:01:15', '0000-00-00 00:00:00', 'no', '', 5, 1, 97),
	('slogan_maupassant', 'pt', 'messages', 'Conhecer pessoas é o que faz a vida merecer ser vivida.', '2013-01-17 20:57:34', '2013-01-17 20:57:34', '0000-00-00 00:00:00', 'no', '', 5, 1, 30452),
	('slogan_maupassant', 'ru', 'messages', 'Встречать людей, которые приносят смысл в нашу жизнь', '2007-12-16 14:51:29', '2007-12-16 14:51:29', '0000-00-00 00:00:00', 'no', '', 5, 1, 79),
	('slogan_mohammed', 'ca', 'messages', '"No m\'expliquis quant has estudiat, explica\'m quant has viatjat." Mahoma (570 - 632)', '2007-10-01 10:47:58', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, 1, 177),
	('slogan_mohammed', 'de', 'messages', '"Erzähle mir nicht wie gebildet du bist, erzähle mir wieviel du gereist bist" Muhammad (570 - 632)', '2007-07-24 21:41:27', '2007-07-24 21:41:27', '0000-00-00 00:00:00', 'no', '', 5, 1, 94),
	('slogan_mohammed', 'en', 'messages', '"Do not tell me how educated you are, tell me how much you travelled." Muhammad (570 - 632)', '2007-07-02 10:25:03', '2007-07-19 16:14:34', '2007-07-19 16:14:34', 'no', 'Index page slogan from Muhammad (take care, his name is different in nearly every language) - try to translate the meaning more than every single word', 5, 1, 91),
	('slogan_mohammed', 'es', 'messages', '"No me digas cuan educado eres, sólo dime cuánto has viajado." Muhammad (570 - 632)', '2007-10-28 15:20:32', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, 1, 1328),
	('slogan_mohammed', 'fr', 'messages', '"Ne me dites pas que vous êtes instruit, racontez-moi plutôt ce que vous ont appris vos voyages." Mahomet (570 - 632)', '2007-07-02 21:37:51', '2010-01-05 18:25:20', '0000-00-00 00:00:00', 'no', '', 5, 1, 9823),
	('slogan_mohammed', 'hr', 'messages', '"Ne pričaj mi o svom obrazovanju, već koliko si putovao/la." Muhammad (570 - 632) ', '2010-01-15 21:25:02', '2010-01-15 21:25:02', '0000-00-00 00:00:00', 'no', '', 5, 1, 8197),
	('slogan_mohammed', 'hu', 'messages', '"Ne azt mondd, hogy mennyire vagy tanult, hanem azt, hogy mennyit utaztál." Muhammad (570-632)', '2007-09-06 20:07:30', '2007-09-06 20:07:30', '0000-00-00 00:00:00', 'no', '', 5, 1, 805),
	('slogan_mohammed', 'it', 'messages', '"Non raccontarmi quanti sei educato, raccontami quanto hai viaggiato." Muhammad (570 - 632)', '2007-09-28 10:39:46', '2007-09-28 10:39:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
	('slogan_mohammed', 'lt', 'messages', '"Nepasakok man apie savo išsilavinimą, verčiau pasakyk, kiek esi nukeliavęs." Mahometas (570 - 632)', '2007-08-29 04:11:32', '2008-03-03 15:30:19', '0000-00-00 00:00:00', 'no', '', 5, 1, 80),
	('slogan_mohammed', 'lv', 'messages', '"Nestāsti man, cik izglītots tu esi, pastāsti man, cik daudz tu esi ceļojis." Muhameds (570-632)', '2007-08-05 13:14:34', '2007-08-05 13:14:34', '0000-00-00 00:00:00', 'no', '', 5, 1, 375),
	('slogan_mohammed', 'nl', 'messages', '"Vertel me niet hoe geleerd je bent, vertel me hoeveel je gereisd hebt." Mohammed (570-632)', '2008-05-13 18:51:55', '2008-05-13 18:51:55', '0000-00-00 00:00:00', 'no', '', 5, 1, 97),
	('slogan_mohammed', 'pl', 'messages', '"Nie mów mi jakie masz wykształcenie, powiedz mi ile podróżowałeś." Mohamet (570-632)', '2007-09-21 08:10:52', '2007-09-21 08:10:52', '0000-00-00 00:00:00', 'no', '', 5, 1, 1554),
	('slogan_mohammed', 'pt', 'messages', '"Não me digas qual a tua educação, diz-me quanto viajaste." Maomé (570 - 632)', '2013-01-14 11:59:30', '2013-01-14 12:00:29', '0000-00-00 00:00:00', 'no', '', 5, 1, 38787),
	('slogan_mohammed', 'ro', 'messages', '"Nu-mi spune ce educaţie ai, spune-mi cât de mult ai călătorit." Mohamed (570 - 632)', '2007-09-20 22:44:49', '2007-09-20 22:44:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1081),
	('slogan_mohammed', 'ru', 'messages', '"Не говори мне, сколько ты учился, лучше скажи, сколько ты путешествовал" Магомет (570-632)', '2007-12-16 15:00:57', '2007-12-16 15:01:04', '0000-00-00 00:00:00', 'no', '', 5, 1, 79),
	('slogan_mohammed', 'sr', 'messages', '"Не говори ми колико си образован, реци ми колико си путовао." Мухамед (570 - 632)', '2013-01-23 00:00:45', '2013-01-23 00:00:45', '0000-00-00 00:00:00', 'no', '', 5, 1, 39772),
	('slogan_pathsaremadebywalking', 'ca', 'messages', 'Caminant es fa el camí.', '2007-10-01 10:52:08', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 177),
	('slogan_pathsaremadebywalking', 'de', 'messages', 'Wege entstehen dadurch, daß man sie geht.', '2007-08-30 08:10:56', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 76),
	('slogan_pathsaremadebywalking', 'en', 'messages', 'Paths are made by walking.', '2007-08-12 10:40:38', '2019-04-23 18:16:49', '2007-08-12 10:40:38', 'no', 'This is a Slogan on the indexpage', 5, 1, 1),
	('slogan_pathsaremadebywalking', 'es', 'messages', 'Los caminos se trazan caminando', '2007-10-28 14:45:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1328),
	('slogan_pathsaremadebywalking', 'fi', 'messages', 'Polut on tehty kävelemällä.', '2008-01-22 20:37:30', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 72),
	('slogan_pathsaremadebywalking', 'fr', 'messages', 'Les chemins se font en marchant', '2007-08-16 12:04:12', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('slogan_pathsaremadebywalking', 'hr', 'messages', 'Putovi se stvaranju hodanjem.', '2009-09-19 09:29:47', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 8197),
	('slogan_pathsaremadebywalking', 'it', 'messages', 'I sentieri si formano camminando', '2007-08-19 15:41:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
	('slogan_pathsaremadebywalking', 'lt', 'messages', 'Keliai yra kuriami beeinant.', '2007-12-17 02:22:47', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 227),
	('slogan_pathsaremadebywalking', 'lv', 'messages', 'Takas tiek izveidotas staigājot.', '2007-09-02 13:27:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 375),
	('slogan_pathsaremadebywalking', 'nl', 'messages', 'Paden worden gemaakt door te lopen.', '2008-03-29 17:58:21', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 97),
	('slogan_pathsaremadebywalking', 'pt', 'messages', 'Caminhos são feitos caminhando.', '2012-07-11 21:23:33', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 30452),
	('slogan_pathsaremadebywalking', 'ro', 'messages', 'Cărările se fac mergând.', '2007-08-28 17:41:51', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1081),
	('slogan_pathsaremadebywalking', 'ru', 'messages', 'Дорогу осилит идущий', '2007-09-08 15:44:22', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 79),
	('slogan_pathsaremadebywalking', 'sr', 'messages', 'Путеви су прављени за ходање.', '2013-01-24 23:07:25', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 39772),
	('slogan_theworldisabook', 'ca', 'messages', 'El món es un llibre i qui no viatja no passa de la primera pàgina.', '2007-10-01 11:24:33', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 177),
	('slogan_theworldisabook', 'de', 'messages', 'Die Welt ist ein Buch. Wer nie reist, sieht nur eine Seite davon.', '2007-08-29 15:02:49', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 91),
	('slogan_theworldisabook', 'en', 'messages', 'The world is a book, those who do not travel read only the first page.', '2007-08-12 10:45:21', '2019-04-23 18:16:49', '2007-08-12 10:45:58', 'no', 'This is a Slogan on the index page', 5, 1, 1),
	('slogan_theworldisabook', 'es', 'messages', 'El mundo es un libro, aquellos que no han viajado leyeron sólo la primera página.', '2007-10-28 06:46:33', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1328),
	('slogan_theworldisabook', 'fr', 'messages', 'Le monde est un livre dont ceux qui n\'ont jamais voyagé ne connaissent que la première page.', '2007-08-16 12:05:46', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('slogan_theworldisabook', 'hr', 'messages', 'Svijet je knjiga, a oni koji ne putuju čitaju samo prvu stranicu.', '2010-04-14 11:39:12', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 8197),
	('slogan_theworldisabook', 'hu', 'messages', 'A világ olyan, mint egy könyv; azok, akik nem utaznak, csak az első oldalt olvassák el.', '2007-08-13 06:49:45', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 805),
	('slogan_theworldisabook', 'it', 'messages', 'Il mondo è un libro, chi non viaggia legge solo la prima pagina', '2007-08-19 15:39:33', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
	('slogan_theworldisabook', 'lt', 'messages', 'Pasaulis - tai knyga; ir tie, kurie nekeliauja, skaito tik jos pirmąjį puslapį.', '2007-08-29 05:02:26', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 227),
	('slogan_theworldisabook', 'lv', 'messages', 'Pasaule ir grāmata, tie, kuri neceļo, izlasa tikai pirmo lapu.', '2007-09-03 10:38:36', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 375),
	('slogan_theworldisabook', 'nl', 'messages', 'De wereld is een boek, zij die niet reizen lezen slechts de eerste bladzijde.', '2008-04-11 16:11:37', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 97),
	('slogan_theworldisabook', 'pl', 'messages', 'Świat jest jak książka. Ci, którzy nie podróżują, to tak jakby czytali tylko pierwszą stronę.', '2007-09-20 15:06:13', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1554),
	('slogan_theworldisabook', 'pt', 'messages', 'O mundo é um livro, aqueles que não viajam lêem apenas a primeira página.', '2013-01-09 16:20:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 38787),
	('slogan_theworldisabook', 'ro', 'messages', 'Lumea este o carte, cei care nu călătoresc îi citesc doar prima pagină.', '2007-08-28 17:35:10', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1081),
	('slogan_theworldisabook', 'ru', 'messages', 'Мир - огромная книга, и те, кто не путешествует, читают только первую страницу', '2007-09-09 08:51:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 79),
	('slogan_theworldisabook', 'tr', 'messages', 'Yeryüzü bir kitaptır. Seyahat etmeyenler sadece birinci sayfayı okurlar.', '2012-12-03 22:10:30', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 35699),
	('slogan_travellingislikeflirting', 'ca', 'messages', 'Viatjar és com lligar amb la vida.', '2007-10-01 10:52:24', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 11944),
	('slogan_travellingislikeflirting', 'de', 'messages', 'Reisen ist wie ein Flirt mit dem Leben.', '2007-08-30 08:16:30', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 3050),
	('slogan_travellingislikeflirting', 'en', 'messages', 'Travelling is like flirting with life.', '2007-08-12 10:41:30', '2019-04-23 18:16:49', '2008-08-17 14:14:42', 'no', 'This is a slogan on index page', 5, 1, 101),
	('slogan_travellingislikeflirting', 'es', 'messages', 'Viajar es como coquetearle a la vida', '2007-10-28 14:44:37', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1328),
	('slogan_travellingislikeflirting', 'fi', 'messages', 'Matkustelu on kuin elämälle flirttailua.', '2008-01-22 20:37:54', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 72),
