	('statshead', 'ca', 'messages', 'BeWelcome consisteix a compartir experiències a la vida real. No et prenguis, doncs, aquesta informació estadística molt seriosament', '2008-03-10 17:36:30', '2023-09-19 18:11:33', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11944),
	('statshead', 'da', 'messages', 'BeWelcome handler om aktiviteter og oplevelser i "det virkelige liv". Så tag ikke informationerne på disse sider for alvorligt ...', '2008-09-28 15:49:59', '2023-09-19 18:11:33', '0000-00-00 00:00:00', 'no', '', 5, NULL, 74),
	('statshead', 'de', 'messages', 'Bei BeWelcome geht es um das wirkliche Leben und Reiseerfahrungen. Nimm also die Informationen auf dieser Seite nicht zu ernst...', '2008-03-06 16:18:02', '2023-09-19 18:11:33', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('statshead', 'el', 'messages', 'Το BeWelcome αφορά δραστηριότητες της πραγματικής ζωής και τις ταξιδιωτικές εμπειρίες. Μην παίρνετε πολύ σοβαρά τις πληροφορίες σε αυτήν τη σελίδα…', '2022-07-16 22:17:13', '2024-07-21 22:11:37', '2022-07-16 22:17:13', 'no', '', 5, NULL, 266502),
	('statshead', 'en', 'messages', 'BeWelcome is about real life activity and travel experiences. Don’t take the information on this page too seriously…', '2008-03-06 14:22:48', '2023-10-24 20:44:55', '2008-09-04 08:54:42', 'no', 'Introduction to the statistics page', 5, 0, 2208),
	('statshead', 'es', 'messages', 'BeWelcome se basa en la actividad en la vida real y las experiencias de viaje. No te tomes muy en serio la información de esta página...', '2008-03-06 15:04:06', '2024-02-21 19:07:22', '0000-00-00 00:00:00', 'no', '', 5, NULL, 25548),
	('statshead', 'fi', 'messages', 'BeWelcomen juju on oikean elämän toiminnassa ja matkustuskokemuksissa. Älä ota tämän sivun tilastoja liian vakavasti...', '2009-01-10 13:21:20', '2023-09-19 18:11:33', '0000-00-00 00:00:00', 'no', '', 5, NULL, 72),
	('statshead', 'fr', 'messages', 'Ce qui est important dans BeWelcome, c’est votre activité dans la vie réelle. Ne prenez donc pas les informations de cette page trop au pied de la lettre ;-)', '2008-05-13 12:09:14', '2023-12-30 10:20:11', '0000-00-00 00:00:00', 'no', '', 5, NULL, 168499),
	('statshead', 'gl', 'messages', 'BeWelcome vai sobre actividades na vida real e experiencias de viaxe. Non tomes a información nesta páxina demasiado en serio...', '2021-01-15 17:49:33', '2023-10-25 16:12:00', '2021-01-15 17:49:33', 'no', '', 5, NULL, 210880),
	('statshead', 'hr', 'messages', 'BeWelcome je posvećen aktivnostima u stvarnom životu i iskustvima na putovanju. Za svaki slučaj, nemoj sve što ovdje pročitaš uzeti zdravo za gotovo....', '2009-08-19 13:57:28', '2023-09-19 18:11:33', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('statshead', 'hy', 'messages', 'ԲիՎելքմը իրական կյանքի գործունեության և ճամփորդական փորձառությունների մասին է: Այս էջում ներկայացված տեղեկատվությունը չափազանց լուրջ մի՛ ընդունեք…', '2025-06-17 02:54:22', '2025-06-17 02:54:22', '2025-06-17 02:54:22', 'no', '', 5, NULL, 519603),
	('statshead', 'it', 'messages', 'BeWelcome è un progetto che riguarda la vita vera e esperienze di viaggio, dunque non prendete le informazioni su questa pagina troppo seriamente.', '2008-03-13 19:37:29', '2023-09-19 18:11:33', '0000-00-00 00:00:00', 'no', '', 5, NULL, 305837),
	('statshead', 'lt', 'messages', 'BeWelcome yra viskas apie realius gyvenimo įvykius bei kelionių patirtis. Nepriimk šio puslapio informacijos per daug rimtai...', '2009-08-09 14:18:15', '2023-09-19 18:11:33', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('statshead', 'nl', 'messages', 'Bij BeWelcome gaat het over het echte leven en over reiservaringen.  Neem de informatie op deze pagina niet té serieus…', '2012-12-19 18:35:26', '2025-02-06 21:02:15', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('statshead', 'pl', 'messages', 'W BeWelcome chodzi o prawdziwe, codzienne doświadczenia podróżników. Nie traktuj informacji na tej stronie zbyt poważnie...', '2009-05-13 13:48:53', '2023-09-19 18:11:33', '0000-00-00 00:00:00', 'no', '', 5, NULL, 116789),
