	('stayloggedin', 'zh-hans', 'messages', '保持登录状态', '2013-02-05 13:04:06', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37722),
	('stayloggedin', 'zh-hant', 'messages', '保持登入狀態', '2013-02-05 13:04:06', '2023-10-24 15:38:21', '0000-00-00 00:00:00', 'no', '', 5, NULL, 53422),
	('stayloggedin_securityhint', 'de', 'messages', 'Wenn du diese Funktion aktivierst, brauchst du dich für %s Tage nicht neu anmelden. Benutze diese Funktion nicht auf öffentlichen Computern.', '2012-09-28 03:05:49', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('stayloggedin_securityhint', 'el', 'messages', 'Όταν ενεργοποιηθεί, δεν θα χρειάζεται να συνδεθείς για  %s  μέρες. Μη το χρησιμοποιείς με κοινές συσκευές.', '2020-08-20 07:17:12', '2020-08-20 07:18:40', '2020-08-20 07:17:12', 'no', '', 5, NULL, 266544),
	('stayloggedin_securityhint', 'en', 'messages', 'When activated, you won\'t need to log in for %s days. Don\'t use this on shared devices.', '2012-09-28 03:01:17', '2019-04-23 18:16:49', '2012-10-03 17:57:02', 'no', 'Explanation while hovering over the "Stay logged in" checkbox. It will be shown on the startpage (login form) and the login widget.', 5, NULL, 347),
	('stayloggedin_securityhint', 'eo', 'messages', 'Se aktiva, tiam vi ne devos ensaluti denove dum sekvaj %s tagoj. Ne uzu tiun funkcion en alies aŭ komunaj aparatoj.', '2013-03-13 08:12:07', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 47220),
	('stayloggedin_securityhint', 'es', 'messages', 'Si está activado, entrarás automáticamente durante %s días. No utilizar en equipos compartidos.', '2013-11-08 16:55:36', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40088),
	('stayloggedin_securityhint', 'eu', 'messages', 'Aktibatzerakoan ez duzu %s egunen buruan saioa hasi beharko. Ez erabili hau partekatutako ordenagailuetan.', '2012-11-18 10:52:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11907),
	('stayloggedin_securityhint', 'fr', 'messages', 'Lorsque cette option est activée, il n’est plus nécessaire de vous connecter manuellement durant %s jours. Ne l’utilisez pas sur un ordinateur ou un appareil partagé.', '2012-10-03 15:33:32', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 9823),
	('stayloggedin_securityhint', 'gl', 'messages', 'Cando estea activado, non necesitarás acceder durante %s  días. Non use isto en equipos compartidos.', '2021-03-11 17:23:14', '2021-03-11 17:23:14', '2021-03-11 17:23:14', 'no', '', 5, NULL, 210880),
	('stayloggedin_securityhint', 'hr', 'messages', 'Aktiviranjem ove opcije nećeš se morati prijavljivati sljedećih %s dana. Ovu opciju nemoj koristiti na uređajima dostupnima javnosti (u knjižnicama, internet kafićima, internet point-ovima...).', '2012-10-05 19:17:41', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 24014),
	('stayloggedin_securityhint', 'hy', 'messages', 'Ակտիվացած ժամանակ դուք կարիք չեք ունենա հավելյալ մուտք գործել կայք %s օր: Մի օգտագործեք այս պայմանը այնպիսի համակարգիչների կամ սարքավորումների վրա, որոնք հասանելի են նաև ուրիշներին:', '2013-06-24 22:29:47', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 22128),
	('stayloggedin_securityhint', 'it', 'messages', 'Una volta attivato, non dovrai connetterti per %s giorni. Non utilizzare questo pulsante nei computer condivisi.', '2012-12-28 10:46:41', '2020-12-08 13:51:31', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160610),
	('stayloggedin_securityhint', 'nl', 'messages', 'Als je dit activeert, hoef je %s dagen niet meer in te loggen. Gebruik dit niet op gedeelde toestellen.', '2012-10-01 19:56:41', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('stayloggedin_securityhint', 'pl', 'messages', 'Gdy aktywujesz, nie musisz logować się przez %s dni. Nie używaj tej funkcji na urządzeniach dzielonych z innymi.', '2021-01-16 16:53:57', '2021-01-16 16:53:57', '2021-01-16 16:53:57', 'no', '', 5, NULL, 116789),
	('stayloggedin_securityhint', 'pt', 'messages', 'Quando ativada não precisa de se identificar durante %s dias. Não use esta opção em dispositivos partilhados.', '2012-12-09 20:56:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('stayloggedin_securityhint', 'ru', 'messages', 'Если отметить, не нужно будет вводить учетные данне в течение %s дней. Не используйте на общественных устройствах.', '2014-05-16 18:32:56', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('stayloggedin_securityhint', 'zh-hans', 'messages', '若勾选, 你将在 %s 天内免登录. 不要在公用计算机上使用此功能. ', '2013-02-05 13:00:15', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37722),
