	('suggestionscreate', 'gl', 'messages', 'Crear', '2021-02-15 16:30:02', '2021-02-15 16:30:02', '2021-02-15 16:30:02', 'no', '', 5, NULL, 210880),
	('suggestionscreate', 'hr', 'messages', 'Izradi', '2013-11-11 19:57:38', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('suggestionscreate', 'hy', 'messages', 'Ստեղծել', '2025-04-09 14:06:04', '2025-04-09 14:06:04', '2025-04-09 14:06:04', 'no', '', 5, NULL, 519603),
	('suggestionscreate', 'it', 'messages', 'Crea', '2013-11-17 08:56:30', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('suggestionscreate', 'ku', 'messages', 'Afrandin', '2014-04-14 09:57:04', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48359),
	('suggestionscreate', 'nl', 'messages', 'Nieuw', '2013-10-04 15:24:36', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40169),
	('suggestionscreate', 'pl', 'messages', 'Utwórz', '2021-01-17 12:37:30', '2021-01-17 12:37:30', '2021-01-17 12:37:30', 'no', '', 5, NULL, 116789),
	('suggestionscreate', 'pt', 'messages', 'Criar', '2013-08-07 08:55:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('suggestionscreate', 'ru', 'messages', 'Создать', '2014-04-17 14:49:26', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('suggestionscreate', 'sl', 'messages', 'Ustvari', '2019-03-28 23:11:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 106553),
	('suggestionscreate', 'sr', 'messages', 'Направи', '2013-12-05 14:37:58', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 35032),
	('suggestionscreate', 'sv', 'messages', 'Skapa', '2013-12-02 11:39:10', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 23263),
	('suggestionscreate', 'tr', 'messages', 'Öneri ekle', '2013-11-28 08:29:47', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 10365),
	('suggestionscreate', 'zh-hans', 'messages', '创建提议', '2014-01-09 13:16:19', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37722),
	('suggestionscreatedescription', 'de', 'messages', 'Du kannst jederzeit eine <b>Problembeschreibung<b> einreichen. Dafür den Reiter (Tab) "Erstellen" anwählen und die Problembeschreibung eingeben. Bitte <b>keine<b> Lösungsvorschläge hier eintragen. Lösungsansätze zu finden finden im Schritt 4 statt.', '2017-02-18 10:54:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 25410),
	('suggestionscreatedescription', 'el', 'messages', 'Μπορείς να δημιουργήσεις μία  <b> περιγραφή προβλήματος </b> οποτεδήποτε. Κάνε κλικ στη καρτέλα "Δημιουργία"  που βρίσκεται πιο πάνω και πρόσθεσε τη περιγραφή του προβλήματος.  <b>Μη</b> προσθέσεις τη προτεινόμενη λύση εκεί ακόμα. Η προσθήκη των διαφορετικών προτάσεων επίλυσης του προβλήματος θα γίνει στο 4ο βήμα.', '2020-08-20 08:36:00', '2020-09-03 09:53:35', '2020-08-20 08:36:00', 'no', '', 5, NULL, 266544),
	('suggestionscreatedescription', 'en', 'messages', 'You may create a <b>problem description</b> anytime. To do so, just click on the "Create" tab above and enter your problem description there. Please do <b>not</b> enter your suggested solution there yet. Entering different suggestions to solve the problem will take place in step 4.', '2013-09-23 08:35:07', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1),
	('suggestionscreatedescription', 'es', 'messages', 'Puedes crear la <b>descripción de un problema</b> en cualquier momento. Para logralo simplemente pincha en la pestaña "Crear" e ingresa la descripción del problema. Por favor <b>no</b> ingresar tu sugerencia de solución todavía. El ingreso de diferentes soluciones para resolver el problema tiene lugar en el paso 4.', '2013-10-03 15:45:44', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 554),
	('suggestionscreatedescription', 'fr', 'messages', 'Vous pouvez créer la <b>description d\'un problème</b> à n\'importe quel moment. Il vous suffit de cliquer sur l\'onglet «&nbsp;créer&nbsp;» et d\'entrer la description du problème. À ce stade, <b>merci de ne pas entrer de suggestions</b>. L\'ajout des suggestions pour résoudre le problème à lieu lors de la quatrième étape. ', '2013-11-01 17:22:02', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('suggestionscreatedescription', 'gl', 'messages', 'Podes crear unha <b>descrición do problema</b> en calquera momento. Para facelo, pincha na lapela de encima "Crear" e introduce a descrición do teu problema alí. Por favor <b>non</b> escribas a solución á túa suxestión aínda. A introdución de diferentes suxestións para resolver o problema terá lugar no paso 4.', '2021-02-15 16:27:20', '2021-02-15 16:27:20', '2021-02-15 16:27:20', 'no', '', 5, NULL, 210880),
	('suggestionscreatedescription', 'it', 'messages', 'Puoi creare una <b>descrizione di un problema</b> in qualsiasi momento. Per farlo, clicca semplicemente sulla scheda "Crea" qui sopra e inserisci lì la tua descrizione del problema. Per favore cerca di <b>non</b> inserire lì i tuoi suggerimenti. Inserire i diversi suggerimenti per risolvere il problema sarà parte del passo 4.', '2015-02-08 10:23:05', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('suggestionscreatedescription', 'nl', 'messages', 'Je kan op elk moment een  <strong>probleembeschrijving</strong> aanmaken. Om dit te doen, klik op "Nieuw" (zie boven) en geef een beschrijving van het probleem. Beschrijf hier nog <strong>niet</strong> wat jouw voorstel tot oplossing is.  Dit gebeurt in stap 4.', '2013-10-20 13:29:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('suggestionscreatedescription', 'pl', 'messages', 'W każdej chwili możesz utworzyć <b>opis problemu</b>. Aby to zrobić, po prostu kliknij „Utwórz” powyżej i wprowadź tam opis problemu. <b>Nie</b> wprowadzaj tam jeszcze sugerowanego rozwiązania. Na wprowadzanie różnych sugestii rozwiązania problemu będzie czas w kroku 4.', '2021-01-17 16:43:18', '2021-01-17 16:43:18', '2021-01-17 16:43:18', 'no', '', 5, NULL, 116789),
	('suggestionscreatedescription', 'pt', 'messages', 'Pode criar uma <b>descrição de problema</b> em qualquer altura. Para o fazer clique na opção "Criar", em cima, e indique lá a descrição do seu problema. Por fazer <b>não</b> indique lá ainda a sua sugestão de solução. A entrada de diferentes sugestões de solução terá lugar no passo 4.', '2014-01-02 11:49:02', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('suggestionscreatedescription', 'ru', 'messages', 'Вы можете создать <b>описание проблемы</b> в любое время. Для того, чтобы селать это, кликните на  вкладке "Создать" и введите там Ваше описание проблемы. Пожалуйста, <b>не</b> вносите Ваше решение на данном этапе. Внесение предложений по решению проблемы будет необходимо на шаге 4.', '2014-04-16 18:18:27', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('suggestionscreatedescription', 'sr', 'messages', 'Можеш направити било када <b>опис проблема</b>. Све што је потребно је да се кликне на "Направи" таб и унеси тамо свој опис проблема. Молимо да <b>не</b> уненете одмах предлог решења. Унос другачијег предлога за решење се налази у кораку 4.', '2014-05-15 19:27:20', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('suggestionscreateeditinfo', 'de', 'messages', 'Bitte gib eine Problembeschreibung ein. Dieser Text wird später der <b>Einleitungstext für die Abstimmung</b> sein. Bitte versuche es zu vermeiden, diesen Text als persönliche Meinung zu formulieren (vermeide z.B. "ich" oder "meine Meinung nach"). Es sollte eine sachliche und neutrale Beschreibung eines Problems sein.\r\n\r\nDu kannst deine persönliche Meinung in die Diskussion einbringen, sobald der Vorschlag freigegeben ist. \r\n\r\nBitte gib noch <b>keine</b> Lösungsvorschläge ein. Die Eingabe von Lösungsvorschlägen ist Teil der Phase "Lösungen", die 10 Tage nach Beginn der Diskussion startet. ', '2013-11-10 19:21:12', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('suggestionscreateeditinfo', 'el', 'messages', 'Πρόσθεσε μία περιγραφή του προβλήματος εδώ.  Το κείμενο θα  <strong> αποτελέσει το εισαγωγικό κείμενο στη σελίδα ψηφοφορίας </strong> αργότερα. Προσπάθησε να αποφύγεις την υποκειμενική γνώμη (για παράδειγμα, μη χρησιμοποιείς τα "Εγώ" ή "κατά τη γνώμη μου"). Η περιγραφή του προβλήματος πρέπει να είναι αντικειμενική και ουδέτερη .\r\n\r\nΜπορείς να προσθέσεις την άποψη σου στη συζήτηση κατόπιν έγκρισης της πρότασης.\r\n\r\n<strong>μην</strong>προσθέτεις τις προτεινόμενες λύσεις ακόμη. Η προσθήκη διαφορετικών προτάσεων για την επίλυση του προβλήματος είναι μέρος του βήματος  "Προσθήκη Λύσεων" που ξεκινά 10 μέρες μετά τη συζήτηση.', '2020-08-20 08:29:15', '2020-08-20 08:29:15', '2020-08-20 08:29:15', 'no', '', 5, NULL, 266544),
	('suggestionscreateeditinfo', 'en', 'messages', 'Please enter a problem description here. This text will be the <strong>introductory text on the voting page</strong> later. Please try to avoid to formulate it as a personal opinion (for example, do not use “I” or “in my opinion”). It should be a factual and neutral description of a problem.\r\n\r\nYou can add your personal opinion to the discussion as soon as the suggestion is approved.\r\n\r\nPlease do <strong>not</strong> enter your suggested solution(s) yet. Entering different suggestions to solve the problem is part of the step “Add solutions” which starts 10 days after the discussion.', '2013-09-23 22:10:04', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', 'Info text on the suggestions/create page.', 5, NULL, 21169),
	('suggestionscreateeditinfo', 'es', 'messages', 'Describe el problema aquí. Más adelante, este texto será la <b>introducción en la página de votaciones</b>. Intenta evitar formularlo como una opinión personal (por ejemplo, no hablar en primera persona o dar tu opinión. Deberías expresar los hechos de forma objetiva.\r\n\r\nPuedes agregar una opinión personal una vez la descripción del problema sea aprobada.\r\n\r\nPor favor,<b>no</b> aportes tu solución todavía. La fase de aportar soluciones empieza 10 días después del inicio del debate.', '2013-11-11 17:23:23', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40088),
	('suggestionscreateeditinfo', 'fr', 'messages', 'Veuillez décrire ici le problème abordé. Ce texte sera utilisé comme <strong>texte d’introduction sur la page de vote</strong>. Merci de ne pas exprimer d\'opinions personnelles - par exemple, n\'employez pas « je » ou « à mon avis ". Ce devrait être une description factuelle et neutre du problème.\r\n\r\nUne fois la suggestion approuvée, vous pourrez ajouter votre avis personnel à la discussion.\r\n\r\nMerci de <strong>ne pas</strong> encore décrire la solution que vous proposez. La description des suggestions fait partie de l\'étape «&nbsp;Ajouter une solution&nbsp;», qui commence 10 jours après la discussion.\r\n', '2015-09-23 00:25:24', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('suggestionscreateeditinfo', 'gl', 'messages', 'Por favor introduce a descrición do problema aquí. Este texto será o <strong>texto introdutorio na páxina de votación</strong> despois. Por favor trata de evitar formulalo como unha opinión persoal (por exemplo, non uses "eu" ou "na miña opinión"). Debe ser unha descrición do problema baseada nos feitos e neutral.\r\n\r\nPodes engadir a túa opinión persoal no debate tan pronto como a suxestión sexa aprobada.\r\n\r\nPor favor <strong>non</strong> introduzas aínda a(s) solución(s) que ti suxires. A introdución de distintas suxestións para solucionar o problema é parte do paso “Engadir solucións” que comeza 10 días despois do debate.', '2021-02-09 11:08:07', '2021-02-09 11:13:49', '2021-02-09 11:08:07', 'no', '', 5, NULL, 210880),
	('suggestionscreateeditinfo', 'it', 'messages', 'Puoi inserire qui la descrizione di un problema. Questo testo sarà poi il <strong>testo introduttivo nella pagina di votazione</strong>. Cerca di evitare do formularlo come un\'opinione personale (ad esempio, non usare "io" o "secondo me". Dovrebbe essere una descrizione oggettiva e neutrale di un problema.\r\n\r\nPuoi aggiungere la tua opinione personale alla discussione appena il suggerimento sarà approvato.\r\n\r\nCerca di <strong>non</strong> inserire ancora i/il tuo/i suggerimenti di soluzione. Inserire diversi suggerimenti per risolvere il problema fa parte del passaggio successivo "Aggiungi soluzioni" che parte 10 giorni dopo la discussione.', '2015-02-08 10:18:51', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('suggestionscreateeditinfo', 'nl', 'messages', 'Vul hier een probleembeschrijving in.  Deze tekst zal de <strong>inleidende tekst op de stempagina</strong> worden.  Probeer te vermijden het als een persoonlijke mening te formuleren (gebruik bv. niet ‘ik’ of ‘volgens mij’).  Dit moet een feitelijke en neutrale beschrijving van het probleem zijn.\r\n\r\nJe kan je persoonlijke mening aan de discussie toevoegen van zodra de suggestie is goedgekeurd.\r\n\r\nVul nog <strong>geen</strong> voorgestelde oplossing in! Het invoeren van verschillende suggesties om het probleem op te lossen is deel van de stap “oplossingen” die 10 dagen na de discussie begint.', '2013-10-04 15:46:29', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('suggestionscreateeditinfo', 'pl', 'messages', 'Wpisz tu opis problemu. Będzie on służył jako <strong>tekst wprowadzający na stronie głosowania</strong>. Staraj się unikać formułowania go jako własnej opinii (np. nie używaj „ja” lub „moim zdaniem”). Powinien być rzeczowym i neutralnym opisem problemu.\r\n\r\nMożesz dodać własną opinię do dyskusji w kolejnym etapie, gdy tylko sugestia zostanie zatwierdzona.\r\n\r\n<strong>Nie</strong> wprowadzaj jeszcze swoich sugerowanych rozwiązań. Wprowadzanie różnych sugestii służących rozwiązania problemu to częścią kroku „Dodaj rozwiązania”, który rozpocznie się 10 dni po dyskusji.', '2021-01-17 14:22:26', '2021-01-17 14:22:26', '2021-01-17 14:22:26', 'no', '', 5, NULL, 116789),
	('suggestionscreateeditinfo', 'pt', 'messages', 'Por favor indique aqui a descrição do seu problema. Este texto será o <strong>texto introdutório na página de votação</strong>, mais tarde. Evite escrevê-lo como uma opinião pessoal (por exemplo, não use "eu" ou "na minha opinião"). Deve ser uma descrição neutra e factual de um problema.\r\n\r\nPode adicionar a sua opinião pessoal na página de discussão assim que a sugestão seja aprovada.\r\n\r\nPor favor <strong>não</strong> indique a(s) sua(s) proposta(s) de solução ainda. Entrar diferentes propostas de solução é parte do passo "Adicionar soluções" que começa 10 dias depois da discussão.', '2014-01-02 12:09:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('suggestionscreateeditinfo', 'ru', 'messages', 'Пожалуйста, опишите здесь свою проблему. Этот текст будет отображен <strong>в начале на странице голосования</strong>. Пожалуйста, не описывайте ее как персональное мнение (к примеру, не используйте “Я” или “по моему мнению”). Это должно быть конкретное и нейтральное описание проблемы. \r\n\r\nВы можете добавить свое личное мнение к дискуссии после того, как предложение будет подтверждено. \r\n\r\nПожалуйста,  <strong>не</strong> предлагайте пока своего решения проблемы. Предложение различных решений проблемы - это часть шага «Добавить решение», которая начинается через 10 дней после дискуссии.', '2014-04-03 16:57:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('suggestionscreateeditinfo', 'sr', 'messages', 'Молимо да унесете опис проблема овде. Овај текст ће касније бити <strong>уводни текст на страници за гласање</strong>. Молимо да избегавате опис као лично мишљење (нпр. не користите "ја", "мени", "ако мене питате"). Ово треба да буде неутрални опис проблема заснован на чињеницама.\r\n\r\nМожете додати своје лично мишљење након одобрења предлога.\r\n\r\nМолимо да  <strong>не уносите</strong> одмах предлог решења. Унос другачијег предлога за решење проблема је у кораку "Додај решење" који почиње 10 дана након расправе.', '2014-03-17 20:34:40', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('suggestionscreateproblemdescription', 'cs', 'messages', 'Vytvořit popis problému', '2013-11-20 14:48:19', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('suggestionscreateproblemdescription', 'de', 'messages', 'Problembeschreibung eingeben', '2013-11-10 19:12:34', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
