	('suggestionsgroupinforeply', 'de', 'messages', 'Sichtbarkeit und Sprache sind voreingestellt auf "nur Mitglieder" und "Englisch" und können nicht verändert werden.', '2014-04-27 18:28:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('suggestionsgroupinforeply', 'el', 'messages', 'Η ορατότητα και η γλώσσα ρυθμίζονται μόνο για τα  μέλη και στα Αγγλικά για την ομάδα των προτάσεων και δεν μπορεί να αλλάξει,', '2020-08-19 21:25:36', '2020-08-28 17:10:13', '2020-08-19 21:25:36', 'no', '', 5, NULL, 266544),
	('suggestionsgroupinforeply', 'en', 'messages', 'Visibility and language are set to members only and English for the suggestions group and can\'t be changed.', '2013-12-03 08:30:28', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', 'Short info text shown in the \'Suggestions\' group to inform members that visibility and language can\'t be set for this thread.', 5, NULL, 1223),
	('suggestionsgroupinforeply', 'es', 'messages', 'La visibilidad y el idioma están configurados como solo para miembros e inglés para el grupo de sugerencias y no puede cambiarse.', '2014-09-09 08:38:53', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40088),
	('suggestionsgroupinforeply', 'fr', 'messages', 'La visibilité est réservée aux membres seulement et la langue a été choisi comme Anglais pour le groupe de suggestions. Ces options ne peuvent pas être changées. ', '2015-09-23 00:02:12', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 97272),
