	('suggestionsgroupinforeply', 'nl', 'messages', 'Voor de groep \'Suggestions\' is de zichtbaarheid vastgezet op \'enkel leden\' en taal op Engels .  Dit kan niet gewijzigd worden.', '2013-12-26 14:46:56', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 22382),
	('suggestionsgroupinforeply', 'pl', 'messages', 'Widoczność i język są ustawione tylko dla członków, a angielski jest językiem domyślnym dla całej Grupy Sugestii i nie można go zmienić.', '2021-01-17 16:36:40', '2021-01-17 16:36:40', '2021-01-17 16:36:40', 'no', '', 5, NULL, 116789),
