	('suggestionsteamtasks', 'es', 'messages', 'Tareas del equipo', '2013-11-11 17:26:53', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 554),
	('suggestionsteamtasks', 'fr', 'messages', 'Missions de l\'équipe', '2015-04-27 19:26:15', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('suggestionsteamtasks', 'gl', 'messages', 'Tarefas do equipo', '2021-02-08 18:20:26', '2021-02-08 18:20:26', '2021-02-08 18:20:26', 'no', '', 5, NULL, 210880),
	('suggestionsteamtasks', 'it', 'messages', 'Incarichi della squadra', '2014-04-08 10:46:03', '2021-02-28 19:37:48', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160610),
	('suggestionsteamtasks', 'nl', 'messages', 'Taken ', '2013-10-30 11:05:12', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 45336),
	('suggestionsteamtasks', 'pl', 'messages', 'Zadania Zespołu', '2021-01-14 19:51:08', '2021-01-14 19:51:08', '2021-01-14 19:51:08', 'no', '', 5, NULL, 116789),
	('suggestionsteamtasks', 'pt', 'messages', 'Tarefas da equipa', '2014-01-02 12:09:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('suggestionsteamtasks', 'pt-BR', 'messages', 'Tarefas do time', '2016-12-22 00:54:16', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160059),
	('suggestionsteamtasks', 'ru', 'messages', 'Беседы команды', '2014-04-15 15:56:20', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('suggestionsteamtasks', 'sr', 'messages', 'Задаци тима', '2013-12-06 02:08:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 35032),
	('suggestionsteamtaskstext', 'de', 'messages', '<ul class="bullet"><li>Unterstützen des gesamten Lebenszyklus der Vorschläge, z.B.:<ul class="bullet"><li>Vorschläge nach Dopplungen und Spam durchsehen und alle anderen Vorschläge genehmigen.</li><li>Andere Teams kontaktieren, wenn ein Vorschlag sie betrifft.</li><li>Die Formulierungen der Lösungen durchsehen und Hilfe für den Entwurf der Texte anbieten.</li><li>Die monatlichen Nachrichten in die Wege leiten, um weitere Mitglieder in die Abstimmungen und Bewertung einzubeziehen.</li></li></ul><li>Mitglieder über die Entscheidungsfindung bei BeWelcome informieren (Fragen beantworten, sie an die richtige Stelle weiterleiten um dort Vorschläge einzubringen usw.)</li><li>Sicherstellen, dass die Informationen über die Prozesse im Team, Mitglieder usw. aktuell sind.</li><li>Den Prozess nach einem Jahr überprüfen und (zusammen mit der Community) Vorschläge für die Verbesserung machen.</li></ul>', '2017-08-26 22:32:38', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 172939),
	('suggestionsteamtaskstext', 'el', 'messages', '<ul class="bullet"><li>Στήριξη του κύκλου ζωής των προτάσεων, e.g.:<ul class="bullet"><li>Έλεγχος των προτάσεων για τυχόν διπλότυπα και ανεπιθύμητα και έγκριση όλων των άλλων προτάσεων.</li><li>Επικοινωνία με τις υπόλοιπες εθελοντικές ομάδες αν μία πρόταση τις επηρεάζει.</li><li>Έλεγχος της διατύπωσης των προτάσεων και προσφορά βοήθειας στη δημιουργία των προσχέδιων κειμένων.</li><li>Αποστολή μηνιαίων μηνυμάτων με στόχο την εμπλοκή και άλλων μελών στις ψήφους και τις κατατάξεις.</li></li></ul><li>Ενημέρωση των μελών για τη λήψη αποφάσεων στο BeWelcome (επίλυση αποριών, καθοδήγηση στο σωστό μέρος για να αποστείλουν προτάσεις κ.α.)</li><li>Διασφάλιση πως οι πληροφορίες για τη λειτουργία των ομάδων, των μελών κ.α. είναι ενημερωμένη.</li><li>Ετήσια αξιολόγηση λειτουργίας και λήψης αποφάσεων για βελτίωση (μαζί με τη κοινότητα).</li></ul>', '2020-08-21 20:54:56', '2020-08-21 20:54:56', '2020-08-21 20:54:56', 'no', '', 5, NULL, 266544),
	('suggestionsteamtaskstext', 'en', 'messages', '<ul class="bullet"><li>Supporting the complete life cycle of suggestions, e.g.:<ul class="bullet"><li>Reviewing suggestions for duplicates and spam and approving all other suggestions.</li><li>Contacting other volunteer teams if a suggestion affects them.</li><li>Reviewing the wording of solutions and offering help in drafting the texts.</li><li>Initiating the monthly messages to involve additional members in the votings and ranking.</li></li></ul><li>Informing members about decision making on BeWelcome (answering questions, directing them to the right place to make suggestions etc.)</li><li>Making sure that the information about team processes, members etc. is up-to-date.</li><li>Reviewing the process after one year and making suggestions for improvement (together with the community).</li></ul> ', '2013-09-23 10:54:18', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('suggestionsteamtaskstext', 'es', 'messages', '<ul class="bullet"><li>Apoyar el ciclo de vida completo de las sugerencias, p. ej.:<ul class="bullet"><li>Revisar sugerencias duplicadas y filtrar el spam, aprobar el resto de sugerencias.</li><li>Contactar con los equipos de voluntarios afectados por las sugerencias.</li><li>Revisión gramátical y apoyo en la creación de los diferentes textos.</li><li>Envio mensual de mensajes para involucrar a los miembros en las listas y votaciones.</li></li></ul><li>Informar a los miembros sobre el proceso de toma de decisiones en BeWelcome (contestar preguntas, dirigirlas al lugar correcto, etc.)</li><li>Asegurarse de que la información sobre los procesos, miembros, etc. está actualizada.</li><li>Revisar (junto a la comunidad) el proceso anualmente y presentar sugerencias para mejorarlo.</li></ul>', '2013-11-11 17:35:34', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40088),
	('suggestionsteamtaskstext', 'fr', 'messages', '<ul class="bullet"><li>Suivi du cycle de vie complet d\'une suggestion&nbsp;:<ul class="bullet"><li>Passer en revue les suggestions, écarter les doublons ou le spam et approuver toutes les autres suggestions.</li><li>Contacter les équipes de volontaires si une suggestion les concerne.</li><li>Passer en revue la formulation et offrir de l\'aide pour la rédaction.</li><li>Envoyer mensuellement des messages pour faire participer de nouveaux membres aux élections.</li></li></ul><li>Informer les membres des prises de décision sur BeWelcome, répondre aux questions, rediriger vers la bonne page pour faire des suggestions, etc.</li><li> Veiller à ce que les informations sur les processus d\'équipe ou les membres soient bien mises à jour.</li><li>Passer en revue le processus après un an et faire des suggestions pour améliorer le site et la communauté.</li></ul>', '2015-09-23 00:16:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('suggestionsteamtaskstext', 'gl', 'messages', '<ul class="bullet"><li>Apoio ao completo ciclo de vida das suxestións, p.ex.:<ul class="bullet"><li>Revisar que as suxestións non estean duplicadas ou conteñan spam y aprobar as demais suxestións.</li><li>Contactar con outras persoas voluntarias do equipo se unha suxestión lles afecta a elas.</li><li>Revisar a redacción das solucións e ofrecer axuda na redacción dos textos.</li><li>Iniciar as mensaxes mensuais para implicar membros adicionais nas votacións e na clasificación.</li></li></ul><li>Informar ás persoas membro sobre a toma de decisións en BeWelcome (contestando preguntas, encamiñándoas ao lugar adecuado para facer suxestións etc.)</li><li>Asegurándose de que a información sobre os procedementos do equipo, persoas membro etc. está actualizada.</li><li>Revisando o procedemento despois dun ano e facendo suxestións para a mellor (xunto coa comunidade).</li></ul>', '2021-02-08 18:20:04', '2021-02-08 18:20:04', '2021-02-08 18:20:04', 'no', '', 5, NULL, 210880),
	('suggestionsteamtaskstext', 'it', 'messages', '<ul class="bullet"><li>Supportare il ciclo completo del processo dei suggerimenti, ad esempio:<ul class="bullet"><li>Controllare i suggerimenti per eliminare duplicati e spam e approvare tutti gli altri suggerimenti.</li><li>Contattare altre squadre di volontari se un suggerimento li riguarda.</li><li>Controllare la formulazione delle soluzioni e offrire il proprio aiuto nella stesura dei testi.</li><li>Avviare l\'invio mensile dei messaggi per coinvolgere altri membri nel processo decisionale e nella classificazion.</li></li></ul><li>Informare membri del processo decisionale di BeWelcome (rispondere a domande, indirizzarli al posto giusto per presentare i propri suggerimenti ecc)</li><li>Garantire che le informazioni sul funzionamento del team, dei membri ecc sono aggiornate.</li><li>Ricontrollare il processo dopo un anno e fare suggerimenti (insieme alla comunità).</li></ul>', '2015-02-09 18:21:14', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('suggestionsteamtaskstext', 'nl', 'messages', '<ul class="bullet"><li>Ondersteuning bieden bij de volledige cyclus van suggesties, bv.:<ul class="bullet"><li>Suggesties controleren op duplicaten en spam en alle andere suggesties goedkeuren.</li><li>Andere vrijwilligersteams contacteren om te vragen of een suggestie hen betreft.</li><li>De formulering van oplossingen nakijken en hulp bieden bij het opstellen van de teksten.</li><li>De maandelijkse berichten versturen om meer leden bij het stemmen en rangschikken te betrekken.</li></li></ul><li>Leden informeren over besluitvorming op BeWelcome (vragen beantwoorden, hen naar de juiste plaats verwijzen om suggesties te doen enz.)</li><li>Ervoor zorgen dat de informatie over teamprocessen, leden enz. bij de tijd blijft.</li><li>Het proces na één jaar evalueren en verbeteringssuggesties aandragen (samen met de gemeenschap).</li></ul>', '2013-12-01 19:41:44', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('suggestionsteamtaskstext', 'pl', 'messages', '<ul class="bullet"><li> Obsługa pełnego cyklu życia sugestii, np .: <ul class="bullet"><li>Przeglądanie sugestii pod kątem duplikatów i spamu oraz zatwierdzanie wszystkich innych sugestii.</li> <li >Kontaktowanie się z innymi zespołami wolontariuszy, jeśli sugestia ich dotyczy.</li><li>Przeglądanie brzmienia proponowanych rozwiązań i oferowanie pomocy w redagowaniu tekstów.</li><li>Wysyłanie co miesiąc wiadomości, aby zaangażować dodatkowych członków w głosowanie i ocenę.</li></li></ul><li>Informowanie członków i członkiń o procesie podejmowania decyzji (odpowiadanie na pytania, kierowanie we właściwe miejsce, gdzie mogą zgłaszać sugestie itp.)</li><li>Upewnianie się, że informacje na temat zespołu, jego działań, członkach itp. są aktualne.</li><li>Rewizja procesu po upływie roku i zgłaszanie propozycji ulepszeń (wspólnie ze społecznością).</li></ul>', '2021-01-17 14:32:40', '2021-01-17 14:32:40', '2021-01-17 14:32:40', 'no', '', 5, NULL, 116789),
	('suggestionsteamtaskstext', 'pt', 'messages', '<ul class="bullet"><li>Apoiar o ciclo de vida completo das sugestões. Ex:<ul class="bullet"><li>Rever sugestões em busca de duplicados e lixo e aprovação das restantes sugestões.</li><li>Contactar outras equipas de voluntários se uma sugestão os afetar.</li><li>Rever a forma como são escritas as soluções e oferecer ajuda para escrever os textos.</li><li>Iniciar o envio mensal de mensagens para incluir mais membros nas votações e definição de prioridades.</li></li></ul><li>Informar membros sobre a tomada de decisões no BeWelcome (respondendo a questões, dirigindo-as para o sítio indicado para fazer sugestões, etc).</li><li>Garantir que a informações sobre os processos das equipas, membros, etc está atualizada.</li><li>Rever os processos ao fim de um ano e fazer sugestões de melhoria (em conjunto com a comunidade).</li></ul>', '2014-01-02 16:27:52', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('suggestionsteamtaskstext', 'ru', 'messages', '<ul class="bullet"><li>Поддержание полного цикла Предложений, а именно.:<ul class="bullet"><li>Контроль Предложений на дублирование и спам, одобрение всех других Предложений.</li><li>Контакт с другими Группами Волонтеров, если предложение затрагивает их деятельность.</li><li>Контроль текста решений и помощь при редактировании текстов.</li><li>Инициация ежемесячных сообщений для вовлечения дополнительных участников в голосования и ранжирование.</li></li></ul><li>Информирование участников о процессе принятия решений на BeWelcome (ответы на вопросы, перенаправлление в соответствующее место для формирования предложений и т.д.)</li><li>Обеспечение актуальности информации о процессах в команде, её участниках и прочее</li><li>Пересмотр процесса по истечении одного года и внесение предложений по его улучшению (совместно с Сообществом).</li></ul>', '2014-04-02 17:33:06', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('suggestionsteamtext', 'en', 'messages', 'The Suggestions Team is a volunteer team which supports BeWelcome\'s <a href="suggestions/process">Decision Making Process</a>.</p><p><b>Team tasks</b></p><p><ul class="bullet"><li>Supporting the complete life cycle of suggestions, e.g.:<ul class="bullet"><li>Reviewing suggestions for duplicates and spam and approving all other suggestions.</li><li>Contacting other volunteer teams if a suggestion affects them.</li><li>Reviewing the wording of solutions and offering help in drafting the texts.</li><li>Initiating the monthly messages to involve additional members in the votings and ranking.</li></li></ul><li>Informing members about decision making on BeWelcome (answering questions, directing them to the right place to make suggestions etc.)</li><li>Making sure that the information about team processes, members etc. is up-to-date.</li><li>Reviewing the process after one year and making suggestions for improvement (together with the community)</li></ul></p><p><b>Team members</b></p><p>Please visit the <a href="groups/1582">Suggestions Team group</a> to see the current team members. You may contact the Suggestions Team by sending a message through the <a href="feedback?IdCategory=7">contact form</a>.</p><p><b>Volunteering for the Suggestions Team</b></p><p>You\'d like to support BeWelcome\'s Decision Making Process by volunteering for this team?</p><p>In this case please join the Suggestions Team group (please note that this group is moderated and your membership will require approval) and send a message to the group administrator in which you describe your motivation to join the team (why this team and not another). In that message, please confirm that you accept BeWelcome\'s Volunteer Code of Conduct and that you are willing to actively participate in the team tasks and discussions on a regular basis.</p><p><i>Minimum requirements to join the team:</i></p><p><ul class="bullet"><li>Membership of at least 3 months.</li><li>A filled out profile.</li><li>No history of violating the Terms of Use (will be checked by Safety Team and Forum Moderators).</li></ul>Applications from members with at least one positive comment will be preferred.</p><p>Once you are accepted into the team you will be added to the Suggestions Team group.', '2013-09-23 10:25:41', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', 'This is the old description of the suggestion team. It is now split up into pieces.', 5, 1, 1),
	('suggestionsteamtext', 'it', 'messages', 'Il TemaSuggerimenti è un gruppo volontario che supporta il<a href="suggestions/process"> processo Decisionale di BeWelcome</a>.</p><p><b>I compiti  del gruppo</b></p><p><ul class="bullet"><li>sono quelli di supportare l\'intero ciclo di vita dei suggerimenti, es.:<ul class="bullet"><li>Filtrando i duplicati ,gli spam e approvando tutti gli altri suggerimenti.</li><li>Contattando gli altri volontari del gruppo se il suggerimento li coinvolge.</li><li>Contollando l\'ortografia delle soluzioni e offrendo aiuto nello stendere il testo.</li><li>Postando un messaggio mensile per coinvolgere ulteriori membri nel votare e definire i rank.</li></li></ul><li>Informando i membri sul processo decisionale su BeWelcome (rispondere a domande, indirizzarli verso il posto giusto per creare suggerimenti, etc)</li><li>Assicurasi che le informazioni sui procedimenti del gruppo, membri,etc siano state aggiornate.</li><li>Verificando il processo dopo un anno e sugggerendo ( congiuntamente con la comunità)dei miglioramenti</li></ul></p><p><b>Membri del gruppo</b></p><p>Per favore visita il <a href="groups/1582">Gruppo Team suggerimenti</a> per vedere quali sono gli attuali membri. Potresti contattare il Team Suggerimenti scrivenodun messaggio attraverso<a href="feedback?IdCategory=7">la pagina contatti</a>.</p><p><b>Volontariato per il Team Suggerimenti</b></p><p>Vorresti aiutare il processo decisionale di BeWelcome supportando volontariamente questo Team?</p><p>In questo caso per favore iscriviti al gruppo Team Suggerimenti (ricordati che questo gruppo è moderato e la tua iscrizione richiede un\'approvazione) e scrivi un messaggio all\'amministratore del gruppo nel quale descrivi il perchè della tua adesione ( perchè questo e non un altro). In questo messaggio, per favore conferma che accetti il Codice di Condotta del Volontario BeWelcome e che parteciperai attivamente ai compiti del Team e alle discussioni interne per definire le basi comuni.</p><p><i>Requisiti minimi per aderire al Team:</i></p><p><ul class="bullet"><li>Essere membro da almeno 3 mesi.</li><li>Profilo completo.</li><li>Nessun episodio di violazione dei Termini di Utilizzo (sarà controllato dal Team Sicurezza e moderatori dei forum).</li></ul>Le domande dai membri con almeno un commento positivo sarà preferita.</p><p>Una volta accettato nel Team sarai aggiunto nel gruppo Team Suggerimenti.\r\n\r\n\r\n', '2014-01-09 12:04:54', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 33078),
	('suggestionsteamtext', 'nl', 'messages', 'Het Suggesties Team is een vrijwilligersteam dat het <a href="suggestions/process">beslissingsproces</a> van BeWelcome ondersteunt.</p><p><b>Teamtaken</b></p><p><ul class="bullet"><li>Het ondersteunen van de complete levenscyclus van suggesties, bijv.:<ul class="bullet"><li>Het beoordelen van suggesties op dubbelen en spam en het goedkeuren van alle andere suggesties.</li><li>Contact opnemen met andere vrijwilligersteams als een suggestie op hen betrekking heeft.</li><li>Herzien van de bewoording van oplossingen en hulp aanbieden in het ontwerpen van de teksten.</li><li>Uitzenden van maandelijkse berichten om extra leden te betrekken bij het stemmen en prioriteren.</li></li></ul><li>Het informeren van leden over de besluitvorming op BeWelcome (beantwoorden van vragen, wijzen van de juiste plaats om suggesties te maken, enz.)</li><li>Zorgen dat de informatie over de procedures van het team, leden enz. actueel is.</li><li>Het proces evalueren na een jaar en (samen met de gemeenschap) suggesties voor verbetering maken)</li></ul></p><p><b>Teamleden</b></p><p>Kijk op <a href="groups/1582">Suggesties Team groepspagina</a> om te zien wie de huidige teamleden zijn. Je kan contact opnemen met het suggestie team door een bericht te sturen via het <a href="feedback?IdCategory=7">contact formulier</a>.</p><p><b>\r\n\r\nJe als vrijwilliger aanbieden voor het Suggesties Team</b></p><p>Je zou het beslisproces van BeWelcome wel willen ondersteunen door je voor dit team aan te melden?</p><p>Treed in dat geval toe tot de Suggestie Team groep (merkop dat deze groep is gemodereerd en dat je lidmaatschap eerst goedgekeurd moet worden) en stuur een bericht naar de groepsbeheerder waarin je beschrijft wat je motivatie is om tot het team toe te treden (waarom dit team en niet een ander). Bevestig in dat bericht ook dat je de gedragscode vooe BeWelcome vrijwilligers aanvaardt en dat je actief wilt deelnemen aan de taken van het team en discussies op een reguliere basis.</p><p><i>Minimum vereisten om toe te treden tot het team:</i></p><p><ul class="bullet"><li>Tenminste drie maanden lidmaatschap.</li><li>Een ingevuld profiel.</li><li>Geen verleden van overtredingen van de Gebruiksvoorwaarden (dat zal worden gecontroleerd door het veiligheidsteam en de forum moderators).</li></ul>De voorkeur gaat uit naar aanmeldingen van leden met ten minste één positief commentaar.</p><p>Zodra je toegelaten bent tot het team zal je worden toegevoegd aan de Suggesties Team groep.', '2014-01-10 15:50:36', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 40169),
	('suggestionsteamtext', 'pt', 'messages', 'A Esquipa de Sugestões é uma equipa de voluntários que apoia <a href="suggestions/process">Processo de Tomada de Decisão</a> do BeWelcome.</p><p><b>Tarefas da equipa</b></p><p><ul class="bullet"><li>Apoiar o ciclo de vida completo das sugestões. Ex:<ul class="bullet"><li>Rever sugestões em busca de duplicados e lixo e aprovação das restantes sugestões</li><li>Contactar outras equipas de voluntários se uma sugestão os afetar.</li><li>Rever a forma como são escritas as soluções e oferecer ajuda para escrever os textos.</li><li>Iniciar o envio mensal de mensagens para incluir mais membros nas votações e definição de prioridades.</li></li></ul><li>Informar membros sobre a tomada de decisões no BeWelcome (respondendo a questões, dirigindo-as para o sítio indicado para fazer sugestões, etc).</li><li>Garantir que a informação sobre os processos das equipas, membros, etc está atualizada.</li><li>Rever os processos ao fim de um ano e fazer sugestões de melhoria (em conjunto com a comunidade).</li></ul></p><p><b>Membros da Equipa</b></p><p>Por favor visite o <a href="groups/1582">grupo da Equipa de Sugestões</a> para ver quem são os membros da equipa atualmente. Pode contactar a Equipa de Sugestões enviando uma mensagem através do <a href="feedback?IdCategory=7">formulário de contacto</a>.</p><p><b>Voluntariar-se para a Equipa de Sugestões</b></p><p>Quer ajudar no Processo de Tomada de Decisão do BeWelcome, voluntariando-se para ajudar esta equipa?</p><p>Nesse caso, por favor, inscreva-se no grupo da Equipa de Sugestões (por favor tenha em atenção que este grupo é moderado e que a sua inscrição carece de aprovação) e envie uma mensagem ao administrador do grupo onde descreve a sua motivação para se juntar à equipa (porquê esta equipa e não outra). Nessa mensagem confirme que aceita o Código de Conduta dos Voluntários BeWelcome e que está disposto/a a participar ativamente nas tarefas e discussões da equipa de forma regular.</p><p><i>Requisitos mínimos para se juntar à equipa:</i></p><p><ul class="bullet"><li>Inscrição há pelo menos 3 meses.</li><li>Um perfil preenchido.</li><li>Sem histórico de violação das Condições de Utilização (será confirmado pela Equipa de Segurança e Moderadores de Fóruns).</li></ul>Aplicações de membros com pelo menos um comentário positivo terão preferência.</p><p>Assim que for aceite na equipa será adicionado ao grupo da Equipa de Sugestões.', '2014-01-02 22:10:49', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 38787),
	('suggestionsteamtextintro', 'cs', 'messages', 'Návrhový tým je tým dobrovolníků, který podporuje <a href="suggestions/process">Rozhodovací proces</a> BeWelcome.', '2014-01-17 00:13:39', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('suggestionsteamtextintro', 'de', 'messages', 'Das Vorschlagsteam ist ein Team freiwilliger Helfer, die BeWelcomes <a href="suggestions/about">Entscheidungsprozess</a> unterstützen.', '2014-04-27 14:27:49', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('suggestionsteamtextintro', 'el', 'messages', 'Η Ομάδα Προτάσεων είναι μία εθελοντική ομάδα που υποστηρίζει  <a href="suggestions/about">τη Διαδικασία Λήψης Αποφάσεων του BeWelcome</a>.', '2020-08-20 07:58:35', '2020-08-28 17:32:52', '2020-08-20 07:58:35', 'no', '', 5, NULL, 266544),
	('suggestionsteamtextintro', 'en', 'messages', 'The Suggestions Team is a volunteer team which supports BeWelcome\'s <a href="suggestions/about">Decision Making Process</a>.', '2013-09-23 10:52:48', '2019-12-26 09:49:40', '2014-04-07 17:26:42', 'no', 'Introductory message on the team page for the suggestions team. Includes a link to the process description.', 5, NULL, 1223),
	('suggestionsteamtextintro', 'es', 'messages', 'El Equipo de Sugerencias es un grupo de voluntarios que apoya el <a href="suggestions/process">Proceso de toma de decisiones</a> de BeWelcome.', '2013-11-11 17:26:42', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 27050),
	('suggestionsteamtextintro', 'fr', 'messages', 'L\'équipe de suggestion est une équipe de volontaires qui accompagne <a href="suggestions/about">la prise de décision</a> sur BeWelcome.', '2015-04-27 19:22:20', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('suggestionsteamtextintro', 'gl', 'messages', 'O Equipo de Suxestións é un equipo de persoas voluntarias que apoia a BeWelcome no seu <a href="suggestions/about">Proceso de Toma de Decisións</a>.', '2021-02-08 18:22:00', '2021-02-08 18:22:00', '2021-02-08 18:22:00', 'no', '', 5, NULL, 210880),
	('suggestionsteamtextintro', 'it', 'messages', 'Il Gruppo Suggerimenti è un gruppo volontario che supporta il<a href="suggestions/process">processo Decisionale di BeWelcome</a>.', '2014-01-09 10:59:11', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 13861),
	('suggestionsteamtextintro', 'nl', 'messages', 'Het “suggestieteam” is een groep vrijwilligers, met als doel het  <a href="suggestions/about">besluitvormingsproces </a> van BeWelcome te ondersteunen. ', '2013-10-30 11:02:46', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40169),
	('suggestionsteamtextintro', 'pl', 'messages', 'Grupa propozycyjna składa się z wolontariuszy wspomagających BeWelcome w <a href="suggestions/about">Procesie Podejmowania Decyzji</a>.', '2014-09-02 20:48:36', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 64183),
	('suggestionsteamtextintro', 'pt', 'messages', 'A Equipa de Sugestões é uma equipa de voluntários que apoia o <a href="suggestions/about">Processo de Tomada de Decisão</a> do BeWelcome.', '2014-01-02 12:09:33', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('suggestionsteamtextintro', 'pt-BR', 'messages', 'A equipe de sugestões é um time formado por voluntários que apoiam o <a href="suggestions/about">Processo de Tomada de Decisões</a> do BeWelcome.', '2016-12-20 15:56:13', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160059),
	('suggestionsteamtextintro', 'ru', 'messages', 'Команда Предложений - это команда волонтеров BeWelcome, которая поддерживает <a href="suggestions/about">Процесс Принятия Решений</a>.', '2014-04-07 17:29:32', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('suggestionsteamtextintro', 'sr', 'messages', 'Предлагачки тим је тим волонтера који пружају подршку BeWelcome-овом <a href="suggestions/process">Процесу одлучивања</a>.', '2013-12-06 02:06:29', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 35032),
