	('thepeople_picturetext1', 'ru', 'messages', 'Волонтеры на первой <a title="unconference: A meeting with a non-fixed schedule that can be changed all the time.">Неконференции</a> в Антверпене в январе 2008 года. ', '2014-05-23 16:25:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('thepeople_picturetext1', 'sr', 'messages', 'Волонтери на првој <a title="неконфренција: Састанак са слободним распоредом који се може било кад променити.">неконференцији</a> у Антверпу, јануар 2008', '2015-02-15 08:06:49', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('thepeople_picturetext1', 'uk', 'messages', '<p>Волонтери на 1-му unconference в Антверпені, січень 2008</p>', '2026-04-04 00:07:36', '2026-04-04 00:07:36', '2026-04-04 00:07:36', 'no', '', 5, NULL, 573491),
	('thepeople_picturetext1', 'zh-hans', 'messages', '2008年1月在安特卫普举办的第一届<a title="unconference: A meeting with a non-fixed schedule that can be changed all the time.">非会议</a>上的志愿者们\r\n', '2011-04-14 14:37:34', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11819),
