	('thepeople_picturetext2', 'de', 'messages', 'Für mehr Bilder, schau mal in unsere <a href="http://www.flickr.com/photos/22828233@N05/">Sammlung bei Flickr</a>.', '2008-04-22 08:36:38', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('thepeople_picturetext2', 'el', 'messages', 'Για περισσότερες εικόνες, ρίξε μία ματιά στη  <a href="http://www.flickr.com/photos/22828233@N05/">συλλογή μας στο flickr</a>.', '2020-08-21 20:27:18', '2020-08-28 18:11:10', '2020-08-21 20:27:18', 'no', '', 5, NULL, 266544),
	('thepeople_picturetext2', 'en', 'messages', 'For more pictures, have a look at our <a href="http://www.flickr.com/photos/22828233@N05/">collection on flickr</a>.', '2008-04-15 13:58:10', '2019-04-23 18:16:49', '2008-04-15 13:58:10', 'no', 'second title of the pictures on the ThePeoplePage', 5, NULL, 71),
