	('thepeople_picturetext2', 'fr', 'messages', 'Pour voir plus d’images, allez visiter notre <a href="http://www.flickr.com/photos/22828233@N05/">galerie Flickr</a>', '2008-05-29 07:12:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 9823),
	('thepeople_picturetext2', 'gl', 'messages', 'Para ver máis fotos, bota unha ollada na<a href="http://www.flickr.com/photos/22828233@N05/">colección do flickr</a>.', '2021-01-15 15:56:16', '2021-01-15 15:56:16', '2021-01-15 15:56:16', 'no', '', 5, NULL, 210880),
	('thepeople_picturetext2', 'hr', 'messages', 'Da vidiš više slika, pogledaj našu<a href="http://www.flickr.com/photos/22828233@N05/">zbirku na flickru</a>. ', '2009-09-03 15:50:06', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('thepeople_picturetext2', 'hy', 'messages', '<p>Ավելի շատ նկարներ տեսնելու համար կարող եք դիտել մեր <a href="http://www.flickr.com/photos/22828233@N05/">հավաքածուն flickr-ում</a>։</p>', '2026-02-04 04:26:11', '2026-02-04 04:26:11', '2026-02-04 04:26:11', 'no', '', 5, NULL, 519603),
	('thepeople_picturetext2', 'it', 'messages', 'Per vedere altre foto, dai un\'occhiata alla nostra <a href="http://www.flickr.com/photos/22828233@N05/">galleria su flickr</a>.', '2008-04-27 18:34:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 103),
	('thepeople_picturetext2', 'lt', 'messages', 'Žr. <a href="http://www.flickr.com/photos/22828233@N05/">Flickr kolekciją</a>, jei nori pamatyti daugiau nuotraukų.', '2009-09-03 01:05:40', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('thepeople_picturetext2', 'nl', 'messages', 'Voor meer foto\'s, kan je kijken in onze <a href="http://www.flickr.com/photos/22828233@N05/">verzameling op flickr</a>.', '2014-01-13 08:38:34', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40169),
