	('thisgroupdontneedacceptance', 'de', 'messages', 'Dein Beitritt zur Gruppe <b>%s</b> wird sofort wirksam, bitte schreibe deinen Text mit Bedacht, denn er wird auch in deinem Profil sofort sichtbar sein.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3050),
	('thisgroupdontneedacceptance', 'el', 'messages', 'Η εγγραφή σου στην ομάδα  <b>%s</b> θα πραγματοποιηθεί άμεσα. Συμπλήρωσε με προσοχή το περιεχόμενο των πεδίων παρακάτω καθώς θα εμφανίζεται στο προσωπικό σου προφίλ.', '2020-08-20 13:24:06', '2020-08-28 18:02:31', '2020-08-20 13:24:06', 'no', '', 5, NULL, 266544),
	('thisgroupdontneedacceptance', 'en', 'messages', 'Your subscription to group <b>%s</b> will be effective immediately. Please carefully fill the content of the comment box below as it will appear on your personal profile.', '2007-08-25 19:02:06', '2019-04-23 18:16:49', '2008-04-13 16:16:26', 'no', '', 5, NULL, 612),
