	('toast.requests.count', 'pt', 'messages+intl-icu', '{count, plural, =0 {Não há pedidos novos} one {Há um pedido novo} other { Há # pedidos novos}}', '2020-05-24 17:19:57', '2020-05-24 17:19:57', '2020-05-24 17:19:57', 'no', '', 5, NULL, 38787),
	('tochangelanguageclickflag', 'ar', 'messages', 'اختر لغتك المفضلة. اذا لم تجدها ربما يمكنك<a href="http://www.bevolunteer.org/forum/index.php?topic=401.0">مساعدتنا فى الترجمة اليها</a> ', '2008-02-11 08:26:30', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39579),
	('tochangelanguageclickflag', 'bg', 'messages', 'Изберете език.Ако не го намирате, можете <a href="http://www.bevolunteer.org/groups/60/wiki"> да ни помогнете с превода!</a>', '2007-07-11 12:57:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 401),
	('tochangelanguageclickflag', 'ca', 'messages', 'Selecciona el teu idioma preferit. Si no el trobes ens pots <a href="http://www.bewelcome.org/groups/60/wiki">ajudar a traduir</a>.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 12861),
	('tochangelanguageclickflag', 'cs', 'messages', 'Vyber si jazyk, který preferuješ. Pokud tvůj oblíbený jazyk není dostupný, tak nám můžeš <a href="http://www.bevolunteer.org/forum/index.php?topic=401.0">pomoci s prekladem</a>. Děkujeme! :-)', '2008-07-30 16:54:38', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('tochangelanguageclickflag', 'da', 'messages', 'Vælg dit foretrukne sprog her. Hvis du ikke kan finde det er du mere end velkommen til at <a href="http://www.bewelcome.org/groups/60/wiki">hjælpe os med at oversætte siderne</a>.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 74),
	('tochangelanguageclickflag', 'de', 'messages', 'Wähle deine bevorzugte Sprache. Ist nicht dabei? <a href="http://www.bewelcome.org/groups/60/wiki">Hilf uns beim Übersetzen!</a>', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('tochangelanguageclickflag', 'el', 'messages', 'Επίλεξε τη γλώσσα που προτιμάς. Αν δεν μπορείς να τη βρεις, μπορείς να <a href="https://www.bewelcome.org/groups/60/wiki">μας βοηθήσεις με τη μετάφραση</a>.', '2010-05-04 18:31:46', '2020-08-24 12:00:52', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('tochangelanguageclickflag', 'en', 'messages', 'Choose your preferred language. If you cannot find it, then you can <a href="http://www.bewelcome.org/groups/60/wiki">help us translate</a>.', '2007-08-25 19:03:02', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', 'This is the message which appears above the flags to propose the user to click on a flag to change the language', 5, NULL, 15240),
	('tochangelanguageclickflag', 'eo', 'messages', 'Elektu preferatan lingvon. Se vi ne povas trovi ĝin, eble vi povas <a href="http://www.bewelcome.org/groups/60/wiki">helpi traduki la retejon</a>.\r\n', '2007-09-10 22:19:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 47220),
	('tochangelanguageclickflag', 'es', 'messages', 'Escoge el idioma de tu preferencia. Si no lo encuentras puedes <a href="http://www.bevolunteer.org/groups/60/wiki">ayudarnos a traducir</a>', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 554),
	('tochangelanguageclickflag', 'et', 'messages', 'Vali keel, milles eelistad lehekülge näha. Kui soovitud keelt ei leia, <a href="http://www.bevolunteer.org/forum/index.php?topic=401.0">aita meid tõlkimisel.</a>', '2008-07-30 17:43:27', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 369),
	('tochangelanguageclickflag', 'eu', 'messages', 'Aukera ezazu zure gogoko hizkuntza. Ezin baduzu aurkitu, <a href="http://www.bewelcome.org/groups/60/wiki"><u>lagun gaitzazu itzultzen!</u></a>', '2008-06-04 12:57:28', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11907),
	('tochangelanguageclickflag', 'fa', 'messages', 'زبان دلخواه خود را انتخاب کنید. اگرنمی‌توانید آن را پیدا کنید، باز هم  می‌توانید ما را در امر <a href="http://www.bewelcome.org/groups/60/wiki"> ترجمه یاری رسانید </a>', '2009-09-09 16:01:53', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 41992),
	('tochangelanguageclickflag', 'fi', 'messages', 'Valitse haluamasi kieli. Jos sitä ei löydy, niin voit <a href="http://www.bewelcome.org/groups/60/wiki">auttaa meitä kääntämään</a> sivuston kielellesi!', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 72),
	('tochangelanguageclickflag', 'fr', 'messages', 'Choisissez votre langue. Si elle n’est pas disponible, vous pouvez <a href="http://www.bewelcome.org/groups/60/wiki"><b>participer à la traduction du site</b></a>.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('tochangelanguageclickflag', 'ga', 'messages', 'Déan an teanga is fearr leat a roghnú. Muna bhfuil tú in ann é a fháil, is féidir leat <a href="http://www.bewelcome.org/groups/60/wiki">cuidiú linn an suíomh seo a aistriú</a>', '2012-03-26 22:01:36', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 26809),
	('tochangelanguageclickflag', 'gl', 'messages', '<p>Escolle a túa lingua preferida. Se non podes atopala, podes <a href="http://www.bewelcome.org/groups/60/wiki">axudarnos a traducila</a>.</p>', '2022-03-29 10:01:21', '2022-03-29 10:01:21', '2022-03-29 10:01:21', 'no', '', 5, NULL, 210880),
	('tochangelanguageclickflag', 'he', 'messages', ':בחר את השפה המועדפת עלייך', '2008-06-10 18:27:04', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 4454),
	('tochangelanguageclickflag', 'hr', 'messages', 'Odaberite željeni jezik. Ako ga nema na popisu, pomozite nam  da ga <a href="http://www.bewelcome.org/groups/60/wiki">prevedemo </a>', '2009-08-17 17:38:35', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('tochangelanguageclickflag', 'hu', 'messages', 'Válaszd ki az anyanyelved! Nem találod? Segíts nekünk a fordításban!:)', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34314),
	('tochangelanguageclickflag', 'id', 'messages', 'Pilih Bahasa yang anda kehendaki. Jika tidak terdapat dalam pilihan, bantu kami menerjemahkannya!', '2007-11-05 17:04:15', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 2019),
	('tochangelanguageclickflag', 'it', 'messages', 'Scegli qui la tua lingua preferita. Se non la trovi puoi <a href="http://www.bewelcome.org/groups/60/wiki">aiutarci a tradurre!</a>', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('tochangelanguageclickflag', 'ja', 'messages', 'お気に入りの言語をお選んでください。お探しの言語がない場合は積極的に翻訳を手伝って下さい！', '2007-11-05 14:19:24', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15953),
	('tochangelanguageclickflag', 'lt', 'messages', 'Čia gali pasirinkti norimą kalbą. Nerandi pageidaujamos kalbos? <a href="http://www.bewelcome.org/groups/60/wiki">Padėk mums išversti</a> šią svetainę į kitas kalbas!', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('tochangelanguageclickflag', 'lv', 'messages', 'Izvēlies sev vēlamo valodu. Ja nevari atrast, tad tu vari palīdzēt mums to iztulkot!', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 375),
	('tochangelanguageclickflag', 'nl', 'messages', 'Kies je taal.  Als deze er niet bij is, kan je ons <a href="http://www.bewelcome.org/groups/60/wiki">helpen met vertalen</a>.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21169),
	('tochangelanguageclickflag', 'no', 'messages', 'Klikk på ønsket språk. Finner du ikke ditt språk? Hjelp oss med å oversette.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40402),
	('tochangelanguageclickflag', 'pl', 'messages', 'Wybierz swój język. Jeśli nie możesz go znaleźć, <a href="http://www.bevolunteer.org/forum/index.php?topic=401.0">pomóż nam tłumaczyć!</a>\r\n', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 35248),
	('tochangelanguageclickflag', 'ps', 'messages', 'په لاندنیو کښی د خوښی ژبه انتخاب کړئ ـ که نه موندل کیږۍ نو بیا مونږ سره په ژباړه کښی همکاری اوکړئ ـ', '2013-03-24 05:31:56', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 43894),
	('tochangelanguageclickflag', 'pt', 'messages', 'Escolha o seu idioma preferido. Se não o encontrar, então pode <a href="http://www.bewelcome.org/groups/60/wiki">ajudar-nos na tradução</a>', '2007-06-30 08:44:49', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('tochangelanguageclickflag', 'pt-BR', 'messages', 'Escolha sua língua preferida. Não encontrou? <a href="http://www.bewelcome.org/groups/60/wiki">Ajude-nos a traduzir.</a>', '2007-08-06 16:43:36', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 9607),
	('tochangelanguageclickflag', 'ro', 'messages', 'Alege limba ta preferată. Dacă nu o găseşti, atunci poate ne poţi ajuta la traducere!', '2007-08-30 17:28:47', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1081),
	('tochangelanguageclickflag', 'ru', 'messages', 'Выберите нужный язык. Не нашли своего? <a href="http://www.bevolunteer.org/forum/index.php?topic=401.0">Помогите нам перевести :)</a>', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 79),
	('tochangelanguageclickflag', 'sk', 'messages', 'Zvoľ si preferovaný jazyk. Pokiaľ ho nemôžeš nájsť, môžeš nám <a href="http://www.bewelcome.org/groups/60/wiki">pomôcť s prekladom</a>.', '2013-03-23 23:15:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48253),
	('tochangelanguageclickflag', 'sr', 'messages', 'Изаберите свој жељени језик. Ако не можете да га нађете, можете нам <a href="http://www.bewelcome.org/groups/60/wiki">помоћи у превођењу</a>', '2012-12-18 12:12:45', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('tochangelanguageclickflag', 'sv', 'messages', 'Välj ditt språk. Om du inte hittar det kan du <a href="http://www.bewelcome.org/groups/60/wiki"> hjälpa oss översätta </a>', '2012-03-15 15:47:50', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 33693),
	('tochangelanguageclickflag', 'tr', 'messages', 'Dilinizi seçiniz. Eğer bulamıyorsanız çeviri için <a href="http://www.bewelcome.org/groups/60/wiki">yardım edebilirsiniz</a>', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 21566),
	('tochangelanguageclickflag', 'ur', 'messages', 'اپنی پسند کی زبان کا انتخاب کریں - اگر آپ اسے اسے تلاش نہیں کر سکے تو <a href="http://www.bewelcome.org/groups/60/wiki">ترجمہ کرنے میں ہماری مدد کریں </a>', '2013-01-18 18:53:06', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39841),
	('tochangelanguageclickflag', 'zh-hans', 'messages', '选择你偏好的语言。如果找不到, 那点这里<a href="http://www.bewelcome.org/groups/60/wiki">帮我们翻译</a>吧！', '2010-02-20 06:37:06', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37722),
	('tochangelanguageclickflag', 'zh-hant', 'messages', '選擇您喜歡的語言。 如果找不到，請點選這裡<a href="http://www.bewelcome.org/groups/60/wiki">幫助我們進行翻譯</a>吧!。', '2010-02-20 06:37:06', '2021-05-02 07:48:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 53422),
