	('tour_gosignup', 'ca', 'messages', 'Que t\'agrada la idea? Participa-hi, registra\'t i informa els teus amics del projecte BeWelcome: tothom hi és benvingut!', '2008-06-29 15:24:03', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('tour_gosignup', 'de', 'messages', 'Du magst diese Idee? Werde ein Teil davon, registriere dich und erzähle deinen Freunden mehr über dieses Projekt - BeWelcome!', '2008-08-22 10:13:14', '2008-08-22 10:13:14', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3050),
	('tour_gosignup', 'el', 'messages', 'Σου αρέσει η ιδέα; Πάρε μέρος σ\' αυτήν, εγγράψου τώρα και πες στους φίλους σου για το έργο - Καλώς όρισες!', '2015-08-13 14:35:39', '2015-08-13 14:35:39', '0000-00-00 00:00:00', 'no', '', 5, NULL, 64914),
	('tour_gosignup', 'en', 'messages', 'You like the idea? Take part in it, register now and tell your friends about the project - BeWelcome!', '2008-06-04 20:07:47', '2008-06-04 20:07:47', '2008-06-04 20:07:47', 'no', 'text on last tourpage that asks the user to sign up', 5, NULL, 71),
	('tour_gosignup', 'es', 'messages', 'Te gusta la idea? Puedes involucrarte, regístrate ahora y habla con tus amigos sobre el proyecto!', '2008-09-13 23:01:57', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, NULL, 554),
	('tour_gosignup', 'eu', 'messages', 'Ideia gustoko duzu? Har ezazu parte, izena eman eta projektua zure lagunei aipa iezaiezu - Ongi etorri!', '2013-04-22 19:48:23', '2013-04-22 19:48:23', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11907),
	('tour_gosignup', 'fi', 'messages', 'Pidätkö ideasta? Ota osaa, rekisteröidy nyt ja kerro myös kavereillesi projektista - BeWelcome!', '2008-06-26 19:05:41', '2008-06-26 19:05:41', '0000-00-00 00:00:00', 'no', '', 5, NULL, 72),
	('tour_gosignup', 'fr', 'messages', 'L’idée vous plaît ? Lancez-vous, créez un profil et faites connaître le projet <b>BeWelcome</b>&nbsp;!', '2008-06-17 21:38:19', '2017-06-05 02:16:48', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('tour_gosignup', 'gl', 'messages', 'Gústache a idea? Toma parte nela, rexistrarte agora e cóntalle ás túas amizades sobre o teu proxecto - BeWelcome!', '2021-12-22 16:14:59', '2021-12-22 16:14:59', '2021-12-22 16:14:59', 'no', '', 5, NULL, 210880),
	('tour_gosignup', 'hr', 'messages', 'Sviđa ti se ideja? Sudjeluj, registriraj se i reci svojim prijateljima o projektu; BeWelcome!', '2012-10-05 18:46:27', '2012-10-05 18:46:27', '0000-00-00 00:00:00', 'no', '', 5, NULL, 24014),
	('tour_gosignup', 'hy', 'messages', 'Հավանու՞մ եք գաղափարը: Մասնակցեք, գրանցվեք հենց հիմա ու պատմեք ձեր ընկերներին այս ՚՚՚Համեցեք՚ կոչվող նախաձեռնության մասին!', '2013-06-24 22:40:00', '2013-06-24 22:40:00', '0000-00-00 00:00:00', 'no', '', 5, NULL, 22128),
	('tour_gosignup', 'it', 'messages', 'Ti piace l\'idea? Partecipa, registrati e racconta ai tuoi amici di questo progetto - BeWelcome!', '2008-12-28 17:48:26', '2008-12-28 17:48:26', '0000-00-00 00:00:00', 'no', '', 5, NULL, 103),
