	('tour_maps', 'es', 'messages', 'Mapas & información', '2008-06-10 10:41:47', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1328),
	('tour_maps', 'eu', 'messages', 'Mapak eta informazioa', '2013-04-20 12:13:25', '2013-04-20 12:13:25', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11907),
	('tour_maps', 'fr', 'messages', 'Cartes & Infos', '2008-06-17 20:50:00', '2008-06-17 20:50:00', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1),
	('tour_maps', 'gl', 'messages', 'Mapas e Informacións', '2021-12-22 16:31:28', '2021-12-22 16:31:28', '2021-12-22 16:31:28', 'no', '', 5, NULL, 210880),
	('tour_maps', 'hr', 'messages', 'Karte i Informacije', '2012-10-05 18:41:00', '2012-10-05 18:41:00', '0000-00-00 00:00:00', 'no', '', 5, NULL, 24014),
	('tour_maps', 'it', 'messages', 'Mappe e informazioni', '2008-12-28 17:41:37', '2008-12-28 17:41:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 103),
	('tour_maps', 'lt', 'messages', 'Žemėlapiai ir naudinga informacija', '2009-09-03 01:16:01', '2009-09-03 01:16:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('tour_maps', 'nl', 'messages', 'Kaarten & Info', '2008-09-12 09:07:52', '2008-09-12 09:07:52', '0000-00-00 00:00:00', 'no', '', 5, NULL, 69),
	('tour_maps', 'pl', 'messages', 'Mapy & Informacje', '2020-07-09 12:10:58', '2020-07-09 12:10:58', '2020-07-09 12:10:58', 'no', '', 5, NULL, 37896),
	('tour_maps', 'pt', 'messages', 'Mapas e Informações', '2013-01-17 18:06:48', '2013-01-17 18:06:48', '0000-00-00 00:00:00', 'no', '', 5, NULL, 30452),
	('tour_maps', 'ru', 'messages', 'Карты и информация', '2009-03-09 11:48:57', '2009-03-09 11:48:57', '0000-00-00 00:00:00', 'no', '', 5, NULL, 79),
	('tour_maps', 'sk', 'messages', 'Mapy & info', '2013-05-06 19:11:52', '2013-05-06 19:11:52', '0000-00-00 00:00:00', 'no', '', 5, NULL, 48253),
	('tour_maps', 'sr', 'messages', 'Мапе и информације', '2014-11-27 21:24:26', '2014-11-27 21:24:26', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('tour_maps', 'zh-hans', 'messages', '地图与信息', '2010-03-04 02:21:50', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37722),
	('tour_maps', 'zh-hant', 'messages', '地图与信息', '2010-03-04 02:21:50', '2021-05-02 07:48:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37722),
	('tour_maps_text1', 'ca', 'messages', 'Les pàgines de BeWelcome t\'ajudaran a preparar el viatge. Pots <a href="searchmembers">cercar membres</a> i mirar on viuen. Els mapes t\'ofereixen una visió general addicional... i continuem treballant-hi perquè siguin encara millors!', '2008-06-28 11:52:06', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('tour_maps_text1', 'de', 'messages', 'Die BeWelcome-Seiten helfen dir, deine Reise zu organisieren. Du kannst <a href="searchmembers">Mitglieder suchen</a> und sehen, wo sie wohnen. Karten geben dir dieses kleine Extra an Überblick - und wir sind ständig dabei, sie noch weiter zu verbessern!', '2008-07-03 20:41:49', '2010-04-10 21:15:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 5499),
	('tour_maps_text1', 'el', 'messages', 'Οι σελίδες του BeWelcome θα σε βοηθήσουν να σχεδιάσεις το ταξίδι σου. Μπορείς να <a href="searchmembers">ψάξεις μέλη</a> και να δεις πού μένουν. Οι χάρτες σού δίνουν αυτή τη μικρή επιπλέον σύνοψη - που εργαζόμαστε συνεχώς να βελτιώνουμε!', '2015-08-12 15:34:52', '2020-09-02 13:03:06', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('tour_maps_text1', 'en', 'messages', 'The BeWelcome pages will help you to plan your trip. You can <a href="searchmembers">search for members</a> and check where they live. Maps give you this little extra overview - and we are constantly working on making it even better!', '2008-06-04 20:08:38', '2008-06-04 20:08:38', '2008-06-04 20:08:38', 'no', 'text of a tourpage', 5, NULL, 71),
	('tour_maps_text1', 'es', 'messages', 'Las paginas de BeWelcome van a ayudarte con la planificacion de tu viaje. Puedes <a href="searchmembers">buscar miembros</a> y revisar donde viven. Los mapas te dan una visión conjunta y estamos constantemente trabajando para mejorar la pagina aun mas!', '2008-09-13 23:06:17', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, NULL, 554),
	('tour_maps_text1', 'eu', 'messages', 'BeWelcome-eko orriek bidaia antolatzen lagun diezazuke. <a href="searchmembers">Kideak bila</a> ditzakezu eta non bizi diren behatu. Mapek gainbegirada gehigarria ematen dizute, eta uneoro gabilz hauek hobetzeko lan egiten!', '2013-04-20 12:36:51', '2013-04-20 12:36:51', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11907),
	('tour_maps_text1', 'fr', 'messages', 'Le site BeWelcome vous aide à préparer votre voyage. Vous pouvez <a href="searchmembers">chercher des membres</a> et chercher dans quelle région ils habitent. Les cartes vous donnent une vue d\'ensemble et nous travaillons constamment à leur amélioration.', '2008-06-25 17:26:38', '2017-06-05 02:03:17', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('tour_maps_text1', 'gl', 'messages', '<p>As páxinas de BeWelcome axudaranche a planear a viaxe. Podes <a href="https://beta.bewelcome.org/searchmembers">buscar persoas membro</a> e comprobar onde viven. Os mapas danche esta pequena visión xeral extra e estamos constantemente traballando para facela mellor!&nbsp;</p>', '2021-12-22 16:13:25', '2021-12-22 16:13:25', '2021-12-22 16:13:25', 'no', '', 5, NULL, 210880),
	('tour_maps_text1', 'it', 'messages', 'Le pagine di BeWelcome ti aiuteranno a preparare il tuo viaggio. Puoi <a href="searchmembers">cercare membri</a> e vedere dove vivono. Le mappe ti danno una migliore visione d\'insieme- e ci continuiamo a lavorare per migliorarle ancora!', '2009-01-06 09:37:00', '2014-12-28 12:59:11', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('tour_maps_text1', 'nl', 'messages', 'De BeWelcome pagina\'s zullen je helpen om je reis te plannen.  Je kan <a href="searchmembers">zoeken naar leden</a> en opzoeken waar ze wonen.  De kaarten geven je een extra overzicht - en we zijn onophoudelijk aan het werken om het nog beter te maken!', '2012-09-16 17:18:01', '2013-02-19 11:23:46', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40169),
	('tour_maps_text1', 'pl', 'messages', 'Strony BeWelcome pomogą Ci zaplanować podróż. Możesz <a href="searchmembers"> wyszukiwać członków </a> i sprawdzać, gdzie mieszkają. Mapy dają ci ten dodatkowy przegląd - i stale pracujemy nad tym, aby było jeszcze lepiej!', '2020-07-09 12:01:36', '2020-07-09 12:01:36', '2020-07-09 12:01:36', 'no', '', 5, NULL, 37896),
	('tour_maps_text1', 'pt', 'messages', 'As páginas do BeWelcome ajudam-no/a a planear a sua viagem. Pode <a href="searchmembers">procurar por outros membros</a> e ver onde vivem. Os mapas dão-lhe uma visão global - e estamos sempre a trabalhar para nos tornar ainda melhores!', '2013-08-13 11:20:34', '2013-08-13 11:20:42', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('tour_maps_text1', 'ru', 'messages', 'Страницы BeWelcome помогут Вам запланировать свое путешествие. Вы можете <a href="searchmembers">найти других участников и узнать где они живут. Вы можете сделать это при помощи наших карт - и мы постоянно работаем над улучшением этого функционала!', '2014-05-21 16:09:49', '2014-05-21 16:09:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('tour_maps_text1', 'sr', 'messages', 'BeWelcome странице ти могу помоћи у планирању твог пута. Можеш <a href="searchmembers">претраживати чланове</a> и да преовериш где они живе. Мапе ти пружају мало бољи преглед, и стално радимо да га учинимо бољим!', '2015-03-01 13:48:02', '2015-03-01 13:48:02', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('tour_maps_text2', 'ca', 'messages', 'No has allotjat mai un desconegut? No saps si és segur fer autoestop? A les nostres <a href="faqs">PMF</a> t\'oferim informació sobre tot el que té relació amb l\'hospitalitat. Als <a href="forums">fòrums</a> els membres es poden ajudar entre ells quant a temes concrets. El novíssim <a href="ajaxchat">xat ajax</a> és la manera més directa de contactar amb nosaltres. I, finalment, el <a href="wiki"><i>wiki</i> de BeWelcome</a> és el lloc per a comprovar els desenvolupaments i les idees recents i participar a la creació d\'iniciatives noves. Anima-t\'hi, participa-hi i fes teu BeWelcome!', '2008-06-29 12:03:26', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('tour_maps_text2', 'de', 'messages', 'Du hast noch nie einen Fremden bei dir übernachten lassen? Du weißt nicht so recht, ob es sicher ist zu trampen? In unseren <a href="faqs">FAQs</a> geben wir Tipps zu allem, was mit dem Austausch von Gastfreundschaft und kostenlosem Übernachten zu tun hat. In unserem <a href="forums">Forum</a> bekommst du Hilfe zu speziellen Anfragen. Unser brandneuer <a href="ajaxchat">Ajax Chat</a> ist der direkte Weg, um mit uns zu sprechen. Und schließlich ist das <a href="wiki">BeWelcome Wiki</a> der Ort, um sich über die neuesten Entwicklungen und Ideen zu informieren und um selbst neue Initiativen anzustoßen. Los, sei dabei und mach BeWelcome zu deinem Ding!', '2008-07-03 20:47:17', '2010-04-10 21:19:52', '0000-00-00 00:00:00', 'no', '', 5, NULL, 5499),
	('tour_maps_text2', 'el', 'messages', 'Δεν έχεις φιλοξενήσει ποτέ κάποιον άγνωστο; Δεν είσαι σίγουρος αν είναι ασφαλές να κάνεις ωτοστόπ; Στις <a href="faqs">Συχνές Ερωτήσεις</a> σου δίνουμε στοιχεία για όλα όσα έχουν να κάνουν με τη φιλοξενία. Στις <a href="forums">Συζητήσεις</a> λαμβάνεις βοήθεια από τα μέλη μας πάνω σε ειδικά θέματα. Το ολοκαίνουριο <a href="ajaxchat">ajaxchat</a> είναι ένας άμεσος τρόπος να μας μιλήσεις. Και τέλος στο <a href="wiki">wiki του BeWelcome</a> βλέπεις τις πρόσφατες εξελίξεις και ιδέες, και λαμβάνεις μέρος στη δημιουργία νέων πρωτοβουλιών. Ξεκίνα τώρα, πάρε μέρος και κάνε το BeWelcome δικό σου!', '2015-08-12 15:51:52', '2020-09-02 13:02:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('tour_maps_text2', 'en', 'messages', 'You never hosted a stranger? You are not sure whether it is safe to hitchhike? In our <a href="faqs">faqs</a> we give you hints about all that has to do with hospitality. In our <a href="forums">forums</a> you get help from our members on specific subjects. Our brandnew <a href="ajaxchat">ajaxchat</a> is the direct way to talk to us. And finally the <a href="wiki">BeWelcome wiki</a> is the place to check out recent development and ideas and take part in creating new initiatives. Go, take part and make BeWelcome your own!', '2008-06-04 20:09:38', '2008-09-08 16:43:27', '2008-09-08 16:43:27', 'no', 'text of a tourpage', 5, NULL, 111),
	('tour_maps_text2', 'es', 'messages', 'Nunca has alojado antes a extraños? No estas seguro si es seguro hacer dedo? En nuestras <a href="faqs">faqs</a> te damos surgerencias sobre todo lo que tiene que ver con redes de hospitalidad. En nuestros <a href="forums">foros</a> nuestros miembros te ayudan con diferentes temas. Nuestro nuevo <a href="ajaxchat">chat</a> es una manera directa de comunicarte con nosotros y finalmente la <a href="wiki">wiki</a> es un lugar para revisar ultimos avances. Súmate y haz de BeWelcome también tu proyecto!', '2008-09-13 23:36:18', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, NULL, 554),
	('tour_maps_text2', 'eu', 'messages', 'Ez diozu ezezagun bati noiz harrera eman? Ez zaude ziur autostop egitea ziurra denentz? Gure <a href="faqs">MEG-etan</a> harrera ematearekin zerikusia duten gai ezberdinei buruzko aholkuak ematen dizkizugu. Horrez gain, gure <a href="forums">foroetan</a> kideek galdera zehatzagoak erantzuten dituzte. Berri-berria dugun <a href="ajaxchat">ajax-txata</a> gurekin zuzenean harremanetan jartzeko modua duzu. Eta azkenik, <a href="wiki">wikian</a> garapenerako ditugun azken ideiak aurki ditzakezu eta ekimen berrietan har dezakezu parte. Har ezazu parte eta egizu BeWelcome zeurea!', '2013-04-20 12:50:38', '2013-04-20 12:50:38', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11907),
	('tour_maps_text2', 'fr', 'messages', 'Vous n\'avez jamais hébergé d\'inconnus&nbsp;? Vous vous demandez s\'il est prudent de faire de l\'autostop&nbsp;? Notre <a href="faqs">foire aux questions</a> regroupe des conseils concernant les questions d’hébergement. Grâce au <a href="forums">forum</a>, vous pouvez obtenir de l’aide de la part des autres membres. La <a href="ajaxchat">salle de discussion</a> permet de discuter en temps réel, quant au <a href="wiki">wiki</a>, il permet de suivre les développements, idées et projets de BeWelcome. Vous pouvez y contribuer et faire des propositions. Faites de BeWelcome votre projet&nbsp;!', '2008-06-17 20:48:41', '2017-06-05 02:11:12', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('tour_maps_text2', 'gl', 'messages', '<p>Nunca hospedaches unha persoa estraña? Non tes certeza de se facer dedo é seguro) Nas nosas <a href="https://beta.bewelcome.org/faqs">preguntas frecuentes</a> te damos pista sobre todo o que ten que ver coa hospitalidade. Nos nosos <a href="https://beta.bewelcome.org/forums">foros</a> terás axuda sobre temas específicos por parte das persoas membro. O noso novo <a href="https://beta.bewelcome.org/ajaxchat">ajaxchat</a> é o modo de falar directamente con nós. E finalmente a <a href="https://beta.bewelcome.org/wiki">wiki de BeWelcome </a>é o lugar para comprobar os últimos avances e ideas e para crear novas iniciativas. Vai, participa e fai teu BeWelcome!</p>', '2021-12-27 08:36:30', '2021-12-27 08:36:30', '2021-12-27 08:36:30', 'no', '', 5, NULL, 210880),
	('tour_maps_text2', 'it', 'messages', 'Non hai mai ospitato un estraneo? Non sei sicuro se sia sicuro fare autostop? Nelle nostre <a href="faqs">faq</a> trovi indicazioni riguardo tutto ciò che ha a che fare con l’ospitalità. Nei nostri <a href="forums">forum</a> trovi aiuto da parte degli altri membri riguardo tematiche specifiche. La nostra nuova <a href="ajaxchat">ajaxchat</a> è una via diretta per parlare con noi. E alla fine trovi il Wiki di BeWelcome, che è lo spazio dove controllare gli sviluppi e le idee recenti e dove puoi prendere iniziative. Vai, fanne parte e rendi BeWelcome tuo!', '2009-01-06 09:38:16', '2009-01-06 09:38:16', '0000-00-00 00:00:00', 'no', '', 5, NULL, 103),
	('tour_maps_text2', 'lt', 'messages', 'Niekuomet nesate apnakvindinę nepažįstamojo? Nesate tikri, ar saugu keliauti autostopu? Mūsų <a href="faqs">DUK</a> atsakėme viską, kas susiję su svetingumu. Mūsų <a href="forums">forume</a> galite gauti pagalbos tiesiai iš kitų narių rūpimomis temomis. Mūsų visiškai naujas <a href="ajaxchat">ajaxchat</a> yra tiesioginis būdas bendrauti su mumis. Ir galiausiai <a href="wiki">BeWelcome viki</a> yra vieta, kur galite peržiūrėti naujausius plėtinius ir idėjas, ir galite prisidėti prie naujų iniciatyvų kūrimo. Pirmyn, bendradarbiaukite ir BeWelcome padarykite savo!', '2021-02-26 17:22:39', '2021-02-26 17:22:39', '2021-02-26 17:22:39', 'no', '', 5, NULL, 285578),
	('tour_maps_text2', 'nl', 'messages', 'Je hebt nog nooit een onbekende bij je laten overnachten?  Je bent niet zeker of het veilig is te liften? In onze <a href="faqs">faqs</a> geven we je tips over alles wat te maken heeft met gastvrijheid.  In onze <a href="forums">forums</a> kan je aan de andere leden  hulp vragen stellen over specifieke onderwerpen. Via onze spiksplinternieuwe <a href="ajaxchat">chat</a> kan je rechtstreeks met ons praten. En, tenslotte, is de <a href="wiki">BeWelcome wiki</a> de plaats om te ontdekken wat de nieuwe ontwikkelingen en ideeën zijn.  Participeer in het uitbouwen van nieuwe initiatieven en maak BeWelcome je eigen website! ', '2012-09-16 17:30:45', '2012-09-16 17:30:45', '0000-00-00 00:00:00', 'no', '', 5, NULL, 22382),
	('tour_maps_text2', 'pl', 'messages', 'Myślisz o tym, by pierwszy raz gościć nieznaną osobę? Nie masz pewności, czy jazda autostopem jest bezpieczna? W naszej sekcji <a href="faqs">faqs</a> dajemy wskazówki na temat wszystkiego, co dotyczy gościnności. Na naszych <a href="forums">forums</a> zawsze uzyskasz pomoc naszych członków dotyczącą konkretnych tematów. Nasz nowy <a href="ajaxchat">ajaxchat</a> jest świetny do bezpośredniego kontaktu z nami. Wreszcie <a href="wiki">BeWelcome wiki</a> to miejsce, najnowsze usprawnienia techniczne i pomysły oraz będziesz móc wziąć udział w tworzeniu nowych przedsięwzięć. Zajrzyj, zaangażuj się i zaprzyjaźnij się z BeWelcome!', '2021-01-12 23:52:10', '2021-01-12 23:52:10', '2021-01-12 23:52:10', 'no', '', 5, NULL, 116789),
	('tour_maps_text2', 'pt', 'messages', 'Nunca hospedou um estranho? Não tem a certeza se é seguro andar à boleia? Na nossa secção de <a href="faqs">perguntas frequentes</a> damos-lhe dicas sobre tudo o que esteja relacionado com a hospitalidade. Nos nossos <a href="forums">fóruns</a> pode obter ajuda dos nossos membros sobre temas específicos. A nossa nova ferramenta <a href="ajaxchat">ajaxchat</a> é a forma mais direta de falar connosco. E finalmente, a <a href="wiki">wiki BeWelcome</a> é o local para procurar informação sobre os desenvolvimentos e ideias mais recentes e tomar parte na criação de novas iniciativas. Avance, faça parte, e torne o BeWelcome também seu!', '2014-01-09 11:20:41', '2014-01-09 11:20:41', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('tour_maps_text2', 'ru', 'messages', 'Никогда не принимали у себя в гостях незнакомых людей? Не уверены, насколько безопасно путешествовать автостопом? В наших <a href="faqs">FAQ</a> мы рассказываем о том, что же делать с Гостеприимством. На наших <a href="forums">Форумах</a> Вы можете получить помощь от участников по специфическим вопросам. Наш новейший <a href="ajaxchat">чат</a> - это именно то место, где с нами можно поговорить напрямую. И наконец, <a href="wiki">BeWelcome wiki</a> - это то место, где можно узнать о новых разработках, ярких идеях и принять участие в реализации новых инициатив. Вперед, вступайте в ряды BeWelcome и внесите свою лепту в его создание!', '2014-05-18 19:15:41', '2014-05-18 19:15:41', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('tour_maps_text2', 'sr', 'messages', 'Никад ниси угостио странца? Ниси сигуран да ли је безбедно аутостопирати? У нашим <a href="faqs">често постављаним питањима</a> ти можемо дати савете о свему што се односи на гостопримство. У нашим <a href="forums">форумима</a> можеш добити помоћ од наших чланова у специфичним темама. Наш нов <a href="ajaxchat">ajaxchat</a> је начин да директно причате са нама. И коначно, <a href="wiki">BeWelcome вики</a> је место где можеш проверити најновија издања сајта и идеје, и да улествујеш у стварању нових иницијатива. Крени, учествуј и учини BeWelcome својим!', '2015-03-01 13:43:35', '2015-03-01 13:43:35', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('tour_maps_text3', 'ca', 'messages', 'T\'agrada conèixer gent i descobrir llocs amb BeWelcome i tens curiositat de saber com funciona i s\'organitza aquesta comunitat? Vols saber per què som únics com a projecte de codi obert? La propera i última parada de la visita et mostrarà com marquem la diferència.', '2008-06-29 12:07:24', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('tour_maps_text3', 'de', 'messages', 'Du liebst es, Leute zu treffen und neue Orte über BeWelcome zu entdecken, und bist neugierig, wie diese Gemeinschaft organisiert ist? Du möchtest wissen, warum wir als Open Source-Projekt so einzigartig sind? Der nächste und letzte Teil der Tour wird dir zeigen, was bei uns den Unterschied ausmacht.', '2008-07-03 20:49:50', '2011-09-02 19:49:19', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15406),
	('tour_maps_text3', 'el', 'messages', 'Σου αρέσει να γνωρίζεις ανθρώπους και να ανακαλύπτεις μέρη μέσω του BeWelcome ενώ είσαι περίεργος για το πώς δουλεύει αυτή η κοινότητα σε οργανωτικό επίπεδο; Θέλεις να ξέρεις γιατί το ανοιχτού κώδικα πρότζεκτ μας είναι πρωτοπόρο; Το επόμενο και τελευταίο βήμα της περιήγησης θα σου δείξει το πώς κάνουμε τη διαφορά.', '2015-08-12 15:55:52', '2020-09-02 13:01:34', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('tour_maps_text3', 'en', 'messages', 'You love to meet people and discover locations through BeWelcome and are curious about how this community works at an organisational level? You want to know why we are unique as an open source project? The next and last step of the tour will show you how we make the difference.', '2008-06-04 20:10:14', '2008-06-04 20:10:14', '2008-06-04 20:10:14', 'no', 'text of a tourpage', 5, NULL, 71),
	('tour_maps_text3', 'es', 'messages', 'Te encanta de encontrarse con gente y descrubrir lugares con BeWelcome y deseas saber como funciona la organización de la comunidad? Quieres saber porque trabajamos con codigo fuente abierto? El ultimo paso del tour te va mostrar como hacemos la diferencia.', '2008-09-13 23:38:15', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, NULL, 554),
	('tour_maps_text3', 'eu', 'messages', 'BeWelcome-en bidez jendea eta leku ezberdinak ezagutzea maite duzu eta jakinmina duzu erakunde mailan nola funtzionatzen garen? Iturri irekiko projektu bezala paregabeak zergatik garen jakin nahi? Azkenekoa den hurrengo pausuak azalduko dizu gure bitxitasuna zein den.', '2013-04-20 12:23:23', '2013-04-20 12:23:23', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11907),
	('tour_maps_text3', 'fr', 'messages', 'Vous aimez rencontrer des gens et découvrir des lieux uniques grâce à BeWelcome ? Vous vous demandez comment cette communauté est organisée  ou comment elle peut fonctionner ? Vous voulez savoir pourquoi ce projet open source est si original ? Cette dernière étape de notre présentation vous en donnera un aperçu.', '2008-06-12 20:09:08', '2011-09-01 20:22:44', '0000-00-00 00:00:00', 'no', '', 5, NULL, 9823),
	('tour_maps_text3', 'gl', 'messages', 'Adoras reunirte con xente e descubrir lugares a través de BeWelcome y tes curiosidade sobre como traballa esta comunidade a nivel de organización? Queres saber por que somos únicos como proxecto de código aberto? O vindeiro paso deste tour amosarache como marcamos a diferencia.', '2021-12-27 08:26:03', '2021-12-27 08:26:03', '2021-12-27 08:26:03', 'no', '', 5, NULL, 210880),
	('tour_maps_text3', 'it', 'messages', 'Ti piace incontrare persone e scoprire località attraverso BeWelcome e sei curioso riguardo a come funziona questa comunità a livello d’organizzazione? Vuoi capire come mai siamo unici come progetto open source? Il prossimo e ultimo passo di questo tour di farà vedere come facciamo la differenza.', '2009-01-06 09:39:19', '2009-01-06 09:39:19', '0000-00-00 00:00:00', 'no', '', 5, NULL, 103),
	('tour_maps_text3', 'nl', 'messages', 'Je houdt ervan mensen te ontmoeten in plaatsen te ontdekken via BeWelcome en je bent nieuwsgierig naar hoe onze gemeenschap werkt op niveau van organisatie.  Wil je weten waarom we uniek zijn als \'open source\' project?  De volgende, en laatste stap van de rondleiding zal je tonen hoe wij het verschil maken.', '2012-09-16 17:34:29', '2012-09-16 17:34:29', '0000-00-00 00:00:00', 'no', '', 5, NULL, 22382),
	('tour_maps_text3', 'pl', 'messages', 'Lubisz poznawać ludzi i odkrywać miejsca przez BeWelcome i chcesz poznać naszą organizację? Chcesz wiedzieć, czemu jesteśmy wyjątkowi jako przedsięwzięcie open source? Następny - i ostatni - krok pokaże Ci, w jaki sposób jesteśmy inni.', '2021-01-12 23:13:49', '2021-01-12 23:13:49', '2021-01-12 23:13:49', 'no', '', 5, NULL, 116789),
	('tour_maps_text3', 'pt', 'messages', 'Adora conhecer pessoas e descobrir novos locais através do BeWelcome e está curioso/a em saber como está organizada esta comunidade? Quer saber porque somos um projeto "open source" único? O próximo e último passo da nossa visita guiada vai mostrar-lhe como fazemos a diferença.', '2014-01-09 11:42:15', '2014-01-09 11:42:15', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('tour_maps_text3', 'ru', 'messages', 'Вы любите встречаться с новыми людьми и узнавать новые места с помощью BeWelcome, а также интересуетесь тем, как устроено Сообщество на организационном уровне? Вы хотите узнать, почему мы являемся уникальным проектом, основанном на открытом коде? На следующем и последнем шаге нашего тура мы покажем Вам все это.', '2014-05-21 16:01:28', '2014-05-21 16:01:28', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('tour_maps_text3', 'sr', 'messages', 'Волиш да се сретнеш са другим људима и открјеш места преко BeWelcome  и радознао си како ова заједница функционише? Хоћеш да знаш зашто смо јединствени као пројекат отвореног ко̑да? Следећи и последњи корак туре ће ти показати по чему се разликујемо.', '2015-02-22 10:04:21', '2015-02-22 10:04:21', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('tour_maps_title1', 'ca', 'messages', 'Prepara\'t bé per al viatge', '2008-06-28 11:35:05', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
