	('tour_openness', 'sr', 'messages', 'Отворено. Транспарентно. Поштено.', '2013-09-15 18:15:17', '2013-09-15 18:15:17', '0000-00-00 00:00:00', 'no', '', 5, NULL, 60746),
	('tour_openness', 'zh-hans', 'messages', '公开 透明 公平', '2013-02-11 18:22:35', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37722),
	('tour_openness', 'zh-hant', 'messages', '公开 透明 公平', '2013-02-11 18:22:35', '2021-05-02 07:48:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37722),
	('tour_openness_text1', 'ca', 'messages', 'L\'organització responsable de BeWelcome es diu BeVolunteer, és registrada a França i no té ànim de lucre. Tota la informació sobre l\'organització és disponible a la <a href="http://www.bevolunteer.org/wiki">biblioteca <i>wiki</i></a>; també pots contactar amb la <a href="http://www.bewelcome.org/bod">Junta directiva</a>, que s\'escolleix cada any, si tens cap dubte, pregunta o comentari a fer.', '2008-06-29 15:22:56', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('tour_openness_text1', 'de', 'messages', 'Die Organisation, die BeWelcome betreibt, nennt sich BeVolunteer. Sie ist ein in Frankreich registrierter Verein, der sich zu gemeinnütziger Arbeit verpflichtet hat (Non-Profit-Organisation). Sämtliche Informationen über die Organisation ist in unserer <a href="wiki"> Wiki-Bibliothek </a> verfügbar. Außerdem hast du die Möglichkeit, dich bei Fragen, Zweifeln oder für generelles Feedback an den jährlich gewählten <a href="bod">Vorstand (BoD)</a> zu wenden.', '2008-07-03 20:54:54', '2012-09-12 18:00:55', '0000-00-00 00:00:00', 'no', '', 5, NULL, 347),
	('tour_openness_text1', 'el', 'messages', 'Ο οργανισμός που διαχειρίζεται το BeWelcome ονομάζεται BeVolunteer. Είναι καταχωρημένος στη Γαλλία και δεσμευμένος σε μη κερδοσκοπική εργασία. Όλες οι πληροφορίες για τον οργανισμό είναι διαθέσιμες στη <a href="wiki">βιβλιοθήκη wiki</a> και μπορείς επίσης να απευθύνεσαι στο ετησίως εκλεγόμενο <a href="bod">Διοικητικό Συμβούλιο</a> αν έχεις ερωτήσεις, αμφιβολίες ή γενικές προτάσεις.', '2015-08-12 14:12:07', '2020-08-26 09:54:28', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('tour_openness_text1', 'en', 'messages', 'The organisation running BeWelcome is called BeVolunteer. It is registered in France and committed to non-profit work. All information about the organisation is available in our <a href="wiki"> wiki library </a> and you can also address the annually elected <a href="bod">Board of Directors</a> if you have questions, doubts or general feedback. ', '2008-06-04 20:05:27', '2011-12-01 21:37:59', '2011-12-01 21:37:59', 'no', 'text of a tourpage', 5, NULL, 111),
	('tour_openness_text1', 'es', 'messages', 'La organización que administra BeWelcome se llama BeVolunteer. Está registrada en Francia y está comprometida a trabajar sin fines de lucro. Toda la información sobre la organización esta disponible en nuestra <a href="wiki">wiki</a> y puedes dirigirte también a la <a href="http://www.bewelcome.org/wiki/Board_of_Directors">Mesa Directiva</a> si tienes preguntas, dudas o surgerencias generales.', '2008-09-13 22:30:41', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, NULL, 554),
	('tour_openness_text1', 'eu', 'messages', 'BeWelcome sortu duen erakundea BeVolunteer da. Frantzian erregistratuta dago irabazi asmorik gabeko erakunde gisa.  Honen gaineko informazio guztia <a href="wiki">wiki liburutegian</a> irakurri dezakezu eta zalantzak, galderak edota nahi duzun edozer aipatzeko, urtero hautatzen diren <a href="bod">zuzendariekin</a> jar zaitezke harremanetan.', '2013-04-20 13:30:28', '2013-04-20 13:30:28', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11907),
	('tour_openness_text1', 'fr', 'messages', 'BeWelcome s’appuie sur l\'association <b>BeVolunteer</b>, qui est dûment enregistrée en France en tant qu\'association loi 1901, à but non lucratif. Toutes les informations sur cette association sont consultables dans le <a href="http://www.bevolunteer.org/wiki">wiki</a>. Si vous avez des questions, des doutes ou des commentaires à faire, n\'hésitez pas à contacter les <a href="http://www.bewelcome.org/bod">membres du bureau</a>, élus chaque année. ', '2008-06-17 20:57:55', '2017-05-29 09:19:22', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('tour_openness_text1', 'gl', 'messages', '<p>A organización que xestiona BeWelcome chámase BeVolunteer. Está rexistrada en Francia e comprométese a traballar sen ánimo de lucro. Toda a información sobre a organización está dispoñible na nosa <a href="https://beta.bewelcome.org/wiki">bibioteca wiki </a>e podes tamén dirixirte á <a href="https://beta.bewelcome.org/bod">Xunta Directiva</a> elixida anualmente se tes algunha pregunta, dubidas ou suxestións de carácter xeral.</p>', '2021-12-22 16:29:56', '2021-12-22 16:29:56', '2021-12-22 16:29:56', 'no', '', 5, NULL, 210880),
	('tour_openness_text1', 'it', 'messages', 'L’organizzazione che dirige BeWelcome si chiama BeVolunteer. E\' registrata in Francia e si dedica al lavoro non profit. Tutte le informazioni riguardanti l’organizzazione si trovano nella nostra <a href="wiki">biblioteca wiki</a>. Se hai domande, dubbi o commenti, puoi scrivere al <a href="bod">Consiglio direttivo</a> eletto ogni anno. ', '2009-01-06 09:34:51', '2011-12-12 16:27:38', '0000-00-00 00:00:00', 'no', '', 5, NULL, 16084),
	('tour_openness_text1', 'nl', 'messages', 'De organisatie achter BeWelcome heet BeVolunteer. Ze staat geregistreerd in Frankrijk en legt zich toe op vrijwilligerswerk.  Je kan al de informatie over de organisatie vinden in onze <a href="wiki"> wiki bibliotheek </a> en je kan je ook richten tot onze, jaarlijks verkozen, <a href="bod">Raad van Bestuur</a> met alle vragen of twijfels of voor algemene feedback.', '2012-09-16 17:42:23', '2013-02-19 11:25:20', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40169),
	('tour_openness_text1', 'pl', 'messages', 'Organizacja prowadząca BeWelcome nosi nazwę BeVolunteer. Jest zarejestrowana we Francji i jest zaangażowana w działalność non-profit. Wszystkie informacje na temat organizacji są dostępne w naszej <a href="wiki"> bibliotece wiki </a>, a jeśli masz pytania, wątpliwości lub ogólne informacje zwrotne możesz również zwrócić się do <a href="bod"> Rady Dyrektorów </a>. ,', '2020-07-09 12:09:14', '2020-07-09 12:09:14', '2020-07-09 12:09:14', 'no', '', 5, NULL, 37896),
	('tour_openness_text1', 'pt', 'messages', 'A organização que gere o BeWelcome chama-se BeVolunteer. Está registada em França e obrigada a trabalho sem fins lucrativos. Toda a informação sobre a organização está disponível na nossa <a href="wiki">biblioteca wiki</a> e pode também dirigir-se à <a href="bod">Direção</a> anualmente eleita se tiver questões, dúvidas ou comentários.', '2014-01-08 17:08:15', '2014-01-08 17:08:15', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('tour_openness_text1', 'ru', 'messages', 'Организация, создавшая и управляющая BeWelcome, называется BeVolunteer. Она зарегистрирована во Франции и занимается некоммерческой деятельностью. Вся информация о данной организации доступна в <a href="wiki">wiki-библиотеке</a>. Если у Вас есть вопросы, какие-либо сомнения или общие отзывы, Вы можете обратиться к ежегодно избираемому <a href="bod">Совету Директоров</a>.', '2014-05-17 16:37:26', '2014-05-17 16:37:26', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('tour_openness_text1', 'sr', 'messages', 'Организација која покреће BeWelcome се зове BeVolunteer. Регистрована је у Француској и посвећена непрофитном раду. Све информације о организацији су допступне у нашој <a href="wiki">вики библиотеци</a>, а и такође можеш контактирати годишње изабрани  <a href="bod">Одбор директора</a> ако имаш питања, сумње или генерални фидбек.', '2015-02-24 21:50:42', '2015-02-24 21:50:42', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('tour_openness_text2', 'ca', 'messages', 'Estem molt orgullosos de contribuir al moviment de programari de codi obert. Això significa que tothom pot col·laborar-hi i ajudar-nos a construir el lloc. Si ets programador, fes una ullada a les <a href="http://trac.bewelcome.org">pàgines Rox de BeWelcome</a>! ', '2008-06-29 12:12:11', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11944),
	('tour_openness_text2', 'de', 'messages', 'Wir sind sehr stolz darauf, einen Beitrag zu der Bewegung der Open Source-Programmierung zu leisten. Das bedeutet, dass jeder mitwirken und helfen kann, diese Webseite zu gestalten. Wenn du ein Programmierer bist, dann schau mal bei <a href="http://trac.bewelcome.org">BeWelcome Rox pages</a> vorbei! ', '2008-08-22 10:05:28', '2012-09-25 20:07:45', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('tour_openness_text2', 'el', 'messages', 'Είμαστε περήφανοι για τη συνεισφορά μας στο κίνημα προγραμματισμού ανοιχτού κώδικα. Αυτό σημαίνει ότι όλοι μπορούν να συνεισφέρουν και να βοηθήσουν στο χτίσιμο του Ιστοχώρου. Αν είσαι προγραμματιστής, ρίξε μια ματιά στις σελίδες <a href="http://trac.bewelcome.org">BeWelcome Rox</a>!', '2015-08-13 14:33:52', '2015-08-13 14:34:11', '0000-00-00 00:00:00', 'no', '', 5, NULL, 64914),
	('tour_openness_text2', 'en', 'messages', 'We are very proud to contribute to the open source programming movement. This means that everybody can contribute and help build the Site. If you are a software developer have a look at the <a href="http://trac.bewelcome.org">BeWelcome Rox pages</a>!', '2008-06-04 20:06:34', '2011-12-01 21:39:20', '2011-12-01 21:39:20', 'no', 'text of a tourpage', 5, NULL, 111),
	('tour_openness_text2', 'es', 'messages', 'Estamos orgullosos de contribuir al movimiento del software libre. Eso significa que todos pueden contribuir y ayudar en la construcion de la pagina. Si eres desarrollador de software visita la pagina de <a href="http://dev.bewelcome.org">BeWelcome Rox</a>! ', '2008-09-13 22:36:54', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, NULL, 554),
	('tour_openness_text2', 'eu', 'messages', 'Iturri irekiko programazio mugimenduaren parte izateaz harro gaude. Hau da, edonork lagun gaitzake webgunea garatzen. Software garatzaile bat bazara, <a href="http://trac.bewelcome.org">BeWelcome Rox orriak</a> begira itzazu!', '2013-04-22 19:45:37', '2013-04-22 19:45:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11907),
	('tour_openness_text2', 'fr', 'messages', 'Nous sommes très fiers de contribuer au mouvement du logiciel libre (<i>open source</i>). Tous le monde peut dès lors contribuer et aider à construire ce site. Si vous êtes développeur de logiciel, vous pouvez regarder <a href="http://dev.bewelcome.org">les pages de BeWelcome Rox</a>&nbsp;!', '2008-06-17 20:52:47', '2017-05-29 09:20:17', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('tour_openness_text2', 'gl', 'messages', '<p>Temos o orgullo de contribuír ao movemento de programación de código aberto (open source). Isto significa que calquera pode contribuír a construír o Sitio web. Se desenvolves software bota unha ollada ás <a href="http://trac.bewelcome.org">Páxinas Rox de BeWelcome</a>!</p>', '2021-12-22 16:22:30', '2021-12-22 16:22:30', '2021-12-22 16:22:30', 'no', '', 5, NULL, 210880),
	('tour_openness_text2', 'it', 'messages', 'Siamo molto fieri di contribuire al movimento di programmazione open source. Questo significa che tutti possono contribuire e aiutare a costruire il sito. Se sei un programmatore dai un’occhiata alle <a href="http://trac.bewelcome.org">pagine di programmazione Rox</a>!', '2009-01-06 09:35:45', '2015-01-05 14:04:38', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('tour_openness_text2', 'lt', 'messages', 'Mes labai didžiuojamės galėdami prisidėti prie atviro kodo programų judėjimo. Tai reiškia, kad kiekvienas gali prisidėti ir padėti kurti svetainę. Jei esi programinės įrangos kūrėjas, užmesk akį į <a href="http://dev.bewelcome.org">BeWelcome Rox puslapius</a>!', '2011-08-25 15:42:03', '2011-08-25 15:42:03', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('tour_openness_text2', 'nl', 'messages', 'We zijn erg trots bij te kunnen dragen aan de beweging van de \'open source\' programmering.  Dit betekent dat iedereen kan helpen de website uit te bouwen. Ben je een software ontwikkelaar?  Kijk eens naar <a href="http://trac.bewelcome.org">BeWelcome Rox pages</a> !', '2012-09-16 17:46:43', '2013-02-19 13:29:13', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40169),
	('tour_openness_text2', 'pl', 'messages', 'Jesteśmy bardzo dumni z tego, że możemy wnosić wkład w ruch programowania open source. Oznacza to, że każdy może przyczynić się i pomóc w budowie witryny. Jeśli jesteś programistą, zajrzyj na <a href="http://trac.bewelcome.org"> strony BeWelcome Rox </a>!', '2020-07-09 12:06:48', '2020-07-09 12:06:48', '2020-07-09 12:06:48', 'no', '', 5, NULL, 37896),
	('tour_openness_text2', 'pt', 'messages', 'Estamos muito orgulhosos de contribuir para o movimento de programação open source. Isto significa que qualquer um pode contribuir para construir o site. Se for um programador, dê uma vista de olhos nas <a href="http://trac.bewelcome.org">páginas Rox BeWelcome</a>!', '2013-08-13 11:21:36', '2013-08-13 11:21:36', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('tour_openness_text2', 'ru', 'messages', 'Мы гордимся тем, что вносим свой вклад в движение открытого программного обеспечения. Это означает, что каждый может оказать свою помощь при создании нашего сайта. Если Вы разрабочик программного обеспечения, загляните на странички <a href="http://trac.bewelcome.org">BeWelcome Rox</a>!', '2014-05-17 04:18:00', '2014-05-22 18:05:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('tour_openness_text2', 'sr', 'messages', 'Веома смо поносни што доприносимо програмерском покрету отвореног ко̑да. То значи да свако може допринети и помоћи у градњи сајта. Ако си софтвер девелопер, погледај <a href="http://trac.bewelcome.org">BeWelcome Rox странице</a>!', '2015-02-24 21:52:41', '2015-02-24 21:52:41', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('tour_openness_text3', 'ca', 'messages', 'Ésser voluntari/a a BeWelcome significa escoltar més que no pas parlar, aprendre i ensenyar, respectar les opinions dels altres i tenir fermesa i èxit. La feina justa significa que no hi ha un cap, sinó un equip. No hi ha secrets ni capelletes, sinó espai per a la innovació i per a les idees. No hi ha pressió, sinó ambició i motivació.', '2008-06-29 15:28:04', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('tour_openness_text3', 'de', 'messages', 'Freiwillige Arbeit für BeWelcome bedeutet: mehr zuzuhören als zu sprechen, zu lernen und zu lehren, fremde Meinungen zu respektieren und trotzdem fest entschlossen und erfolgreich zu sein. Gerechte Arbeit bedeutet, dass es keinen Chef gibt, sondern ein Team. Es gibt keine versteckten Geheimnisse, nur Platz für innovative Ideen. Es gibt keinen Druck, dafür Ehrgeiz und Motivation.', '2008-08-22 10:11:51', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15406),
	('tour_openness_text3', 'el', 'messages', 'Το να είσαι εθελοντής στο BeWelcome σημαίνει να ακούς περισσότερο απ\'ότι να  μιλάς, να μαθαίνεις και να διδάσκεις, να σέβεσαι τη γνώμη του άλλου κι εκείνος τη δική σου και να έχεις αποφασιστικότητα και επιτυχία. Δίκαιη δουλειά σημαίνει ότι δεν υπάρχει αφεντικό, αλλά ομάδα. Δεν υπάρχουν κρυμμένα μυστικά, αλλά χώρος για καινοτόμες ιδέες. Δεν υπάρχει πίεση, αλλά φιλοδοξία και κίνητρα.', '2015-08-13 14:39:45', '2020-08-26 10:57:17', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('tour_openness_text3', 'en', 'messages', 'Volunteering for BeWelcome means to listen more than speak, to learn and teach, to respect each other\'s opinion and still be determined and successful. Fair work means there is no boss but a team. There are no hidden secrets but space for innovative ideas. There is no pressure but ambition and motivation.', '2008-06-04 20:07:06', '2019-12-26 09:49:40', '2008-06-04 20:07:06', 'no', 'text of a tourpage', 5, NULL, 15240),
	('tour_openness_text3', 'es', 'messages', 'Voluntariar para BeWelcome significa escuchar mas que hablar, aprende y enseñar, respectar otras opiniones y todavia ser determinado y exitoso. Trabajar justo significa que no hay jefes en el equipo. No hay secretos escondidos sino espacio para ideas inovativas. No hay presion sino ambición y motivación.', '2008-09-13 22:39:31', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 554),
	('tour_openness_text3', 'eu', 'messages', 'BeWelcome-eko boluntario izatea hitz egin baino gehiago entzutea esan nahi du, ikastea eta irakastea, betiere gainontzekoen iritziak errespetatuz. Bidezko lanak, buruzagirik ez, baizik eta talde bat dagoela esan nahi du. Ez dago sekreturik, baizik eta berrikuntzarako lekua. Ez dago presioa, baizik eta handinahia eta motibazioa.', '2013-04-22 19:55:07', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11907),
	('tour_openness_text3', 'fr', 'messages', 'Pour être bénévole BeWelcome, il faut savoir plus écouter que parler, pouvoir apprendre et enseigner, respecter les autres opinions tout en sachant expliquer les siennes, afin de prendre les meilleures décisions possibles. Cette organisation du travail est horizontale, avec une équipe qui travaille sans chef. Aucune information n\'est secrète et le réseau aspire à être un vaste espace de discussion, où fleurissent les idées neuves. Il n\'y a pas de pression&nbsp;! Seulement de l\'ambition et de la motivation.', '2008-06-20 07:39:42', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('tour_openness_text3', 'gl', 'messages', 'Facer voluntariado en BeWelcome significa oír máis que falar, aprender e ensinar, respectar a opinión uns dos outros e aínda ter determinación e éxito. Traballo xusto significa que non hai xefe, senón equipo. Non hai segredos, senón espazo para ideas innovadoras. Non hai presión, senón ambición e motivación.', '2021-12-22 16:18:26', '2021-12-22 16:18:26', '2021-12-22 16:18:26', 'no', '', 5, NULL, 210880),
	('tour_openness_text3', 'it', 'messages', 'Essere volontari per BeWelcome significa ascoltare più che parlare, imparare ed insegnare, rispettare le opinioni degli altri ed essere comunque determinati e attivi. Lavoro equo significa che non c\'è un capo, ma soltanto una squadra.  Non ci sono segreti nascosti ma spazio per idee innovative. Non c’è pressione ma ambizione e motivazione.', '2009-01-06 09:36:13', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('tour_openness_text3', 'nl', 'messages', 'Vrijwilliger zijn bij BeWelcome betekent meer te luisteren dan te spreken, leren en aanleren, elkaars mening respecteren en toch vastberaden en succesvol te zijn. Eerlijk werk betekent dat er geen baas is, wel een team. Er zijn geen verborgen agenda\'s maar er is wel plaats voor vernieuwende ideeën. Er is geen druk maar wel ambitie en motivatie.', '2012-09-16 17:51:46', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 22382),
	('tour_openness_text3', 'pl', 'messages', 'Wolontariat dla BeWelcome oznacza więcej słuchania niż mówienia, uczenie się i nauczanie, szanowanie wzajemnych opinii i wciąż bycie zdeterminowanym i odnoszącym sukcesy. Uczciwa praca oznacza, że nie ma szefa, tylko zespół. Nie ma ukrytych tajemnic, ale miejsce na innowacyjne pomysły. Nie ma presji, tylko ambicja i motywacja.', '2020-07-09 12:05:36', '2020-07-09 12:05:36', '2020-07-09 12:05:36', 'no', '', 5, NULL, 37896),
	('tour_openness_text3', 'pt', 'messages', 'Voluntariar-se para o BeWelcome significa ouvir mais do que falar, aprender e ensinar, respeitar a opinião dos outros e ainda ser determinado e bem sucedido. O nosso trabalho não tem um patrão mas sim uma equipa. Não há segredos escondidos mas sim espaço para ideias inovadoras. Não há pressão mas sim ambição e motivação.', '2014-01-09 11:44:48', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('tour_openness_text3', 'pt-BR', 'messages', 'Voluntariar-se para o BeWelcome significa ouvir mais do que falar, aprender e ensinar, respeitar a opinião dos outros e ainda assim ser determinado e bem sucedido. Este tipo de trabalho significa que não temos um chefe, mas uma equipe. Não existem segredos, mas espaço para ideias inovadoras. Não existe pressão, mas ambição e motivação.', '2016-12-18 14:09:44', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 160059),
	('tour_openness_text3', 'ru', 'messages', 'Быть волонтером на BeWelcome означает слушать больше, чем говорить, учиться и обучать, уважать другие мнения и быть решительным и успешным. Ясная работа означает, что в команде нет никакого начальника. Нет тайных секретов, но есть открытое пространство для инновационных идей. Нет никакого давления, а только трудолюбие и мотивация.', '2014-05-21 16:17:54', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('tour_openness_text3', 'sr', 'messages', 'Волонтирање за BeWelcome значи више слушати него причати, научити и подучити, поштовати свачије мишљење, а ипак бити одлучан и успешан. Поштен рад значи да нема шефова, него тим. Нема скривених тајни, него простор за иновативне идеје. Нема притисака, него амбиција и подстрек.', '2015-01-24 14:00:54', '2015-01-24 14:00:54', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('tour_openness_title1', 'ca', 'messages', 'Una organització transparent', '2008-06-29 12:08:58', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('tour_openness_title1', 'cs', 'messages', 'Transparentní organizace', '2014-11-07 12:21:48', '2014-11-07 12:21:48', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('tour_openness_title1', 'de', 'messages', 'Transparente Organisation', '2008-06-09 13:24:46', '2008-06-09 13:24:46', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3050),
	('tour_openness_title1', 'el', 'messages', 'Διαφανής οργάνωση', '2015-08-12 13:55:00', '2015-08-12 13:55:00', '0000-00-00 00:00:00', 'no', '', 5, NULL, 64914),
	('tour_openness_title1', 'en', 'messages', 'Transparent organisation', '2008-06-04 20:04:57', '2008-06-04 20:04:57', '2008-06-04 20:04:57', 'no', 'subtitle of a tourpage', 5, NULL, 71),
	('tour_openness_title1', 'es', 'messages', 'Organización transparente', '2008-06-10 10:42:14', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1328),
	('tour_openness_title1', 'eu', 'messages', 'Erakunde gardena', '2013-04-20 13:24:17', '2013-04-20 13:24:17', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11907),
	('tour_openness_title1', 'fi', 'messages', 'Läpinäkyvä organisaatio', '2008-06-26 19:04:14', '2008-06-26 19:04:14', '0000-00-00 00:00:00', 'no', '', 5, NULL, 72),
	('tour_openness_title1', 'fr', 'messages', 'Transparence de l’organisation', '2008-06-17 20:49:36', '2011-09-01 20:23:08', '0000-00-00 00:00:00', 'no', '', 5, NULL, 9823),
	('tour_openness_title1', 'gl', 'messages', 'Organización transparente', '2021-12-22 16:30:47', '2021-12-22 16:30:47', '2021-12-22 16:30:47', 'no', '', 5, NULL, 210880),
	('tour_openness_title1', 'hr', 'messages', 'Transparentna organizacija', '2010-04-14 14:09:37', '2010-04-14 14:09:37', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('tour_openness_title1', 'it', 'messages', 'Organizzazione trasparente', '2008-12-28 17:44:15', '2008-12-28 17:44:15', '0000-00-00 00:00:00', 'no', '', 5, NULL, 103),
	('tour_openness_title1', 'lt', 'messages', 'Skaidri organizacija', '2009-09-03 01:17:05', '2009-09-03 01:17:05', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
