	('tourpage', 'uk', 'messages', 'Що таке BeWelcome?', '2026-04-03 17:46:17', '2026-04-03 17:46:17', '2026-04-03 17:46:17', 'no', '', 5, NULL, 573491),
	('tourpage', 'zh-hans', 'messages', '什么是 BeWelcome?', '2010-02-24 03:28:47', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 37722),
	('tourpage', 'zh-hant', 'messages', '關於 BeWelcome', '2010-02-24 03:28:47', '2023-10-24 15:36:36', '0000-00-00 00:00:00', 'no', '', 5, NULL, 53422),
	('tourpage_text2', 'ca', 'messages', 'A BeWelcome, creiem que compartir fa del món un lloc millor. Compartim experiències, moments, coneixements i donem la benvinguda a convidats a casa nostra, si podem...', '2008-06-25 09:39:36', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('tourpage_text2', 'da', 'messages', 'Vi tror på at det at dele skaber en bedre verden. Vi deler oplevelser, øjeblikke, viden og byder gæster velkommen i vores hjem - hvis vi kan...', '2023-04-01 06:44:13', '2023-04-01 06:44:13', '2023-04-01 06:44:13', 'no', '', 5, NULL, 274594),
	('tourpage_text2', 'de', 'messages', 'Bei BeWelcome glauben wir, dass Teilen unsere Welt verbessert. Wir teilen Erfahrungen, Momente, Wissen und begrüßen Gäste in unserem Zuhause, wenn es möglich ist...', '2008-06-09 13:31:53', '2013-06-22 14:29:57', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('tourpage_text2', 'el', 'messages', 'Στο BeWelcome πιστεύουμε ότι το να μοιραζόμαστε δημιουργεί έναν καλύτερο κόσμο. Μοιραζόμαστε εμπειρίες, στιγμές, γνώση και καλωσορίζουμε επισκέπτες στα σπίτια μας, αν μπορούμε...', '2015-08-12 12:29:21', '2015-08-12 12:29:21', '0000-00-00 00:00:00', 'no', '', 5, NULL, 64914),
	('tourpage_text2', 'en', 'messages', 'At BeWelcome we believe sharing creates a better world. We share experiences, moments, knowledge and we welcome guests in our homes, if we can...', '2008-06-04 18:51:21', '2013-03-31 17:42:14', '0000-00-00 00:00:00', 'no', 'subtext for a tourpage on the tour overview page', 5, NULL, 15240),
	('tourpage_text2', 'eo', 'messages', 'Ĉe BeWelcome ni kredas ke intervivado plibonigas la mondon. Ni dividas spertojn, momentojn, scion kaj ni bonvenigas gastojn en niajn hejmojn, kiam eblas...', '2008-08-13 16:19:09', '2013-05-03 15:11:12', '0000-00-00 00:00:00', 'no', '', 5, NULL, 47220),
	('tourpage_text2', 'es', 'messages', 'En BeWelcome creemos que compartir crea un mundo mejor. Compartimos experiencias, momentos, conocimientos y damos la bienvenida a huéspedes en nuestras casas, si podemos ...', '2008-09-13 21:34:59', '2020-11-30 17:28:55', '0000-00-00 00:00:00', 'no', '', 5, NULL, 25548),
	('tourpage_text2', 'eu', 'messages', 'BeWelcome-en ustez partekatzeak mundu hobe bat sortzen du. Esperientziak, momentuak, ezagutzak partekatzen ditugu, eta bidaiariak etxera gonbidatzen ditugu, ahal badugu...', '2012-11-18 11:47:16', '2013-04-20 11:54:58', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11907),
	('tourpage_text2', 'fr', 'messages', 'Nous pensons que le partage contribue à rendre le monde meilleur. Nous partageons nos histoires, expériences et connaissances et accueillons d\'autres voyageurs, lorsque c\'est possible.', '2008-06-17 19:16:08', '2017-06-05 01:46:43', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('tourpage_text2', 'gl', 'messages', 'En BeWelcome cremos que compartir crea un mundo mellor. Nós compartimos experiencias, momentos e saberes e acollemos hospedes nas nosas casas, se podemos...', '2021-01-21 10:48:55', '2021-01-21 10:48:55', '2021-01-21 10:48:55', 'no', '', 5, NULL, 210880),
	('tourpage_text2', 'hr', 'messages', 'U BeWelcomeu vjerujemo da dijelje ideja stvara bolji svijet. dijelimo iskustva, trenutke, znanjete ugošćujemo ljude u svojim domovima, ako imamo mogućnost...', '2011-12-01 18:06:18', '2011-12-01 18:06:18', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('tourpage_text2', 'hu', 'messages', 'Hiszünk benne, hogy ha megosztjuk tapasztalatainkat, legszebb pillanatainkat, tudásunkat és ha vendégül látjuk a világot, jobbá tesszük azt mindenki számára.', '2020-06-05 07:44:26', '2020-06-05 07:44:26', '2020-06-05 07:44:26', 'no', '', 5, NULL, 36939),
	('tourpage_text2', 'hy', 'messages', 'ԲիՎելքմում մենք հավատում ենք, որ կիսվելը ավելի լավ աշխարհ է ստեղծում: Մենք կիսվում ենք փորձով, ուրախ պահերով, գիտելիքով և հնարավորության դեպքում հյուրեր ենք ընդունում մեր տանը...', '2025-04-08 17:50:04', '2025-05-21 03:15:06', '2025-04-08 17:50:04', 'no', '', 5, NULL, 519603),
	('tourpage_text2', 'it', 'messages', 'Noi di BeWelcome crediamo che condividere crei un mondo migliore. Condividiamo esperienze, momenti, conoscenze e diamo il benvenuto ad ospiti a casa nostra, ogni volta che possiamo...', '2008-12-25 18:49:31', '2014-12-28 12:14:27', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('tourpage_text2', 'lt', 'messages', 'Mes manome, kad apsikeitimas svetingumu prisideda prie šiek tiek geresnio pasaulio. Mes dalijamės patirtimi, gyvenimiškais momentais, žiniomis, ir, kai tik galime, priglaudžiame svečius savo namuose.', '2009-08-10 00:40:02', '2009-08-10 00:40:02', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('tourpage_text2', 'nl', 'messages', 'BeWelcome gelooft dat we een betere wereld kunnen creëren door met anderen te delen. We delen ervaringen, momenten, kennis en we verwelkomen gasten bij ons thuis als dit kan...', '2008-09-12 08:45:22', '2013-07-23 12:14:30', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40169),
	('tourpage_text2', 'pl', 'messages', 'W BeWelcome wierzymy, że dzielenie się sparawia, że świat staje się lepszy! Dzielimy się wrażeniami, chwilami, wiedzą i witamy gości w naszych domach, jeśli możemy...', '2008-09-06 22:34:33', '2008-09-06 22:34:33', '0000-00-00 00:00:00', 'no', '', 5, NULL, 392),
	('tourpage_text2', 'pt', 'messages', 'No BeWelcome acreditamos que a partilha cria um mundo melhor. Partilhamos experiências, momentos, conhecimento e acolhemos convidados em nossas casas, se pudermos...', '2012-12-11 18:30:48', '2014-01-03 17:52:45', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('tourpage_text2', 'pt-BR', 'messages', 'Aqui no BeWelcome a gente acredita que compartilhar as coisas torna o mundo melhor. A gente compartilha experiências, momentos, conhecimento... a gente também recebe visitas na nossa casa, quando dá.', '2010-01-31 20:21:43', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, NULL, 9607),
	('tourpage_text2', 'ru', 'messages', 'В BeWelcome мы верим в то, что принцип "делиться с другими" может улучшать мир. Мы делимся опытом, моментами, знаниями и мы принимаем гостей у себя дома, если мы можем...', '2012-10-03 18:51:27', '2014-05-24 08:21:41', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('tourpage_text2', 'sr', 'messages', 'У BeWelcome верујемо да дељење ствара бољи свет. Ми делимо искуства, тренутке, знање и примамо госте у наше домове, ако можемо...', '2013-11-02 23:39:14', '2013-11-02 23:39:14', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
	('tourpage_text2', 'uk', 'messages', 'В BeWelcome ми віримо, що ділитися чимось робить світ кращим. Ми ділимося досвідом, моментами, знаннями і вітаємо гостей у наших домівках, якщо можемо...', '2026-04-03 17:49:17', '2026-04-03 17:49:17', '2026-04-03 17:49:17', 'no', '', 5, NULL, 573491),
	('tourpage_text2', 'zh-hans', 'messages', '在 BeWelcome，我们相信分享可以令世界变得更美好。我们分享经验/经历、时光、知识，如可以的话还提供借宿...... ', '2010-02-24 05:21:59', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, NULL, 25117),
	('tourpage_text2', 'zh-hant', 'messages', '在 BeWelcome，我們相信分享可以創造一個更美好的世界。 我們分享經驗、時刻、知識，如果可以的話，我們甚至招待客人來到家中借宿。', '2010-02-24 05:21:59', '2023-10-24 15:43:07', '0000-00-00 00:00:00', 'no', '', 5, NULL, 53422),
	('tourpage_text3', 'ca', 'messages', 'BeWelcome va de trobar altres persones. Les pots conèixer en línia al lloc web o quedar a la vida real...', '2008-06-25 09:41:09', '2013-03-19 03:38:52', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('tourpage_text3', 'da', 'messages', 'BeWelcome handler om at møde andre. Du kan lære mennesker at kende igennem siden eller møde den i virkeligheden...', '2023-04-01 06:40:44', '2023-04-01 06:40:44', '2023-04-01 06:40:44', 'no', '', 5, NULL, 274594),
	('tourpage_text3', 'de', 'messages', 'Bei BeWelcome geht es darum, anderen zu begegnen. Du kannst Leute online über unsere Webseite kennen lernen oder sie im wirklichen Leben treffen...', '2008-07-03 20:05:13', '2012-10-05 10:24:30', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('tourpage_text3', 'el', 'messages', 'Το BeWelcome αφορά τη γνωριμία με άλλα άτομα. Μπορείς να τους γνωρίσεις διαδικτυακά μέσω του ιστοχώρου ή να τους συναντήσεις στη πραγματική ζωή...', '2015-08-12 12:51:35', '2020-09-02 13:00:38', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('tourpage_text3', 'en', 'messages', 'BeWelcome is about meeting others. You can get to know people online through the website or meet them in real life...', '2008-06-04 18:52:57', '2008-06-04 18:52:57', '2008-06-04 18:52:57', 'no', 'subtext for a tourpage on the tour overview page', 5, NULL, 71),
	('tourpage_text3', 'eo', 'messages', 'BeWelcome estas pri renkonti aliajn homojn, Vi povas renkonti homojn virtuale aŭ vizaĝe.', '2008-08-13 16:27:50', '2009-07-05 17:51:02', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1769),
