	('tourpage_text5', 'gl', 'messages', 'Queremos que compartir e achegarse sexa non só divertido senón fácil. As nosas ferramentas axudan facelo...', '2021-01-21 10:44:15', '2021-01-21 10:44:15', '2021-01-21 10:44:15', 'no', '', 5, NULL, 210880),
	('tourpage_text5', 'hr', 'messages', 'Želimo dijeljenje i susretanje učiniti ne samo zabavnima već i laganima. Naši alati i značajke će ti pomoći u tome.', '2012-10-05 17:55:22', '2012-10-05 17:58:36', '0000-00-00 00:00:00', 'no', '', 5, NULL, 24014),
