	('tourpage_text5', 'hy', 'messages', 'Մենք ուզում ենք ունեցածով կիսվելն ու նոր ծանոթությունները դարձնել ոչ միայն զվարճալի, այլև հեշտ: Մեր գործիքներն ու առանձնահատկությունները օգնում են այդ հարցում…', '2025-04-08 17:46:00', '2025-04-08 17:46:00', '2025-04-08 17:46:00', 'no', '', 5, NULL, 519603),
