	('translation.overall.count', 'ca', 'messages+intl-icu', 'Hi ha {all} elements per traduir a la base de dades (independentment de si estan arxivades o tenen la bandereta de no traduir). La taula de sota mostra la ràtio de traducció a totes les llengües respoecte aquest número.', '2021-10-05 13:10:30', '2021-10-05 13:10:30', '2021-10-05 13:10:30', 'no', '', 5, NULL, 304193),
	('translation.overall.count', 'el', 'messages+intl-icu', 'Αυτά είναι {all} στοιχεία μετάφρασης στη βάση δεδομένων (τα οποία δεν αρχειοθετούνται αλλά ανεξάρτητα από τη σημαία μη μετάφρασης). Ο παρακάτω πίνακας δείχνει την αναλογία για όλες τις γλώσσες σε σύγκριση με αυτόν τον αριθμό.', '2022-11-12 08:51:19', '2022-11-12 08:51:19', '2022-11-12 08:51:19', 'no', '', 5, NULL, 266502),
	('translation.overall.count', 'en', 'messages+intl-icu', 'There are {all} translation items in the database (which aren’t archived but regardless of the do not translate flag). The table below shows the ratio for all languages compared to this number.', '2020-12-01 18:23:02', '2020-12-01 21:00:45', '2020-12-01 18:23:02', 'no', 'Shows some information about the translations. Make sure to include {all} in the text.', 5, 0, 21169),
	('translation.overall.count', 'es', 'messages+intl-icu', 'Hay {all}  elementos de traducción en la base de datos (que no están archivados, pero excluyendo la marca de no traducir). La siguiente tabla muestra el porcentaje de cada idioma en referencia a este número total.', '2020-12-02 00:42:55', '2020-12-02 00:42:55', '2020-12-02 00:42:55', 'no', '', 5, NULL, 25548),
	('translation.overall.count', 'fr', 'messages+intl-icu', 'Il y a {all} traductions dans la base de données (sans compter celles qui sont archivées, mais sans tenir compte du signal «ne pas traduire»). Le tableau ci-dessous montre le ratio pour toutes les langues par rapport à ce nombre.', '2020-12-10 21:38:02', '2020-12-10 21:38:02', '2020-12-10 21:38:02', 'no', '', 5, NULL, 168499),
	('translation.overall.count', 'gl', 'messages+intl-icu', 'Hai {all} artigos para traducir na base de datos (que non están arquivados a pesar da bandeira non traducir). A táboa de abaixo amosa a proporción para todas as linguas comparadas con este número.', '2021-01-20 18:13:16', '2021-01-20 18:13:16', '2021-01-20 18:13:16', 'no', '', 5, NULL, 210880),
	('translation.overall.count', 'he', 'messages+intl-icu', 'ישנם {all} פריטים לתרגום במסד הנתונים (אשר אינם בארכיון וללא קשר לדגל "לא לתרגום"). הטבלה מטה מציגה את היחס למספר זה עבור כל השפות.', '2022-04-04 05:04:36', '2022-04-04 05:04:36', '2022-04-04 05:04:36', 'no', '', 5, NULL, 290109),
	('translation.overall.count', 'hy', 'messages+intl-icu', 'There are {all} translation items in the database (which aren’t archived but regardless of the do not translate flag). The table below shows the ratio for all languages compared to this number.', '2025-10-03 06:27:03', '2025-10-03 06:27:03', '2025-10-03 06:27:03', 'no', '', 5, NULL, 519603),
	('translation.overall.count', 'it', 'messages+intl-icu', 'Ci sono {all} traduzioni nella base di dati (che non vengono archiviati indipendentemente dal flag di non traduzione). La tabella seguente mostra il rapporto tra le varie lingue e questo numero.', '2020-12-05 15:33:58', '2020-12-05 15:33:58', '2020-12-05 15:33:58', 'no', '', 5, NULL, 160610),
	('translation.overall.count', 'lt', 'messages+intl-icu', 'Dumoneų bazėje yra {all} vertimų (kurie nėra archyvuoti, bet nepaisant neverstinumo žymimi). Lentelėje žemiau parodytas kiekvienos kalbos vertimų santykis su tuo skaičiumi.', '2021-02-26 18:04:43', '2021-02-26 18:04:43', '2021-02-26 18:04:43', 'no', '', 5, NULL, 285578),
	('translation.overall.count', 'nl', 'messages+intl-icu', 'Er zijn {all} te vertalen teksten in de database (die niet zijn gearchiveerd, maar onafhankelijk van het label ‘niet vertalen’).  De onderstaande tabel toont de ratio voor alle talen in vergelijking met dit aantal.', '2020-12-01 21:00:31', '2026-02-03 12:50:21', '2020-12-01 21:00:31', 'no', '', 5, NULL, 21169),
	('translation.overall.count', 'pl', 'messages+intl-icu', 'W bazie danych znajduje się {all} elementów tłumaczenia (które nie są archiwizowane, niezależnie od flagi nie tłumacz). Zestawienie przedstawia stosunek do tej liczby wartości tłumaczeń w każdym z języków.', '2021-01-17 13:35:34', '2021-01-17 13:47:28', '2021-01-17 13:35:34', 'no', '', 5, NULL, 116789),
	('translation.overall.count', 'pt', 'messages+intl-icu', 'Há {all} itens de tradução na base de dados (que não foram arquivados, mas sem contar com a flag para não traduzir). A tabela abaixo mostra o rácio para todos os idiomas comparado com este número.', '2021-04-06 05:10:41', '2021-04-06 05:10:41', '2021-04-06 05:10:41', 'no', '', 5, NULL, 38787),
	('translation.overall.count', 'ru', 'messages+intl-icu', 'В базе данных есть {all} элементов перевода (которые не архивируются  независимо от флажка «не переводить»). В таблице ниже показано соотношение для всех языков по сравнению с этим числом.', '2025-03-21 07:29:26', '2025-03-21 07:30:09', '2025-03-21 07:29:26', 'no', '', 5, NULL, 519603),
	('translation.overall.count', 'uk', 'messages+intl-icu', 'У базі даних є {all} елементів перекладу (які не архівовані, але незалежно від прапора "не перекладати"). Таблиця нижче показує співвідношення для всіх мов у порівнянні з цим числом.', '2026-04-03 16:15:29', '2026-04-03 16:15:29', '2026-04-03 16:15:29', 'no', '', 5, NULL, 573491),
