	('trip.incomplete.leg', 'ca', 'messages+intl-icu', 'Acabes d\'acceptar una invitació que és més curta que la teva estada a {location} ({arrival, date, medium} - {departure, date, medium}). Considera actualitzar el teu viatge per a que continui sent visible als altres.', '2022-05-16 09:10:59', '2022-05-16 09:10:59', '2022-05-16 09:10:59', 'no', '', 5, NULL, 26748),
	('trip.incomplete.leg', 'de', 'messages+intl-icu', 'Du hast eine Einladung angenommen, die kürzer als dein Aufenthalt in {location} ({arrival, date, medium} - {departure, date, medium}) ist. Dies führt dazu, dass dieser Teil der Reise für andere nicht mehr sichtbar ist.  Um das zu vermeiden, aktualisiere gegebenenfalls deine Reiseangaben.', '2022-09-18 14:35:54', '2022-09-18 14:35:54', '2022-09-18 14:35:54', 'no', '', 5, NULL, 29715),
	('trip.incomplete.leg', 'el', 'messages+intl-icu', 'Μόλις αποδεχτήκατε μια πρόσκληση που είναι μικρότερη από τη διαμονή σας στην τοποθεσία {location} ({arrival, date, medium} - {departure, date, medium}). Σκεφτείτε να ενημερώσετε το ταξίδι σας, καθώς αυτό θα κρύψει τη διαφορά από τους άλλους.', '2022-06-21 19:09:44', '2022-06-21 19:09:44', '2022-06-21 19:09:44', 'no', '', 5, NULL, 266502),
	('trip.incomplete.leg', 'en', 'messages+intl-icu', 'You just accepted an invitation that is shorter than your stay in {location} ({arrival, date, medium} - {departure, date, medium}). Consider updating your trip as this will hide the leg from others.', '2022-04-23 17:27:06', '2022-04-23 17:27:06', '2022-04-23 17:27:06', 'no', 'Additional flash notice shown when a user accepts an invitation that didn\\\'t cover the full leg duration', 5, NULL, 1),
	('trip.incomplete.leg', 'es', 'messages+intl-icu', 'Acabas de aceptar una invitación que es más corta que tu estancia en  {location} ({arrival, date, medium} - {departure, date, medium}). Considera la posibilidad de actualizar tu viaje, ya que esta etapa quedará oculta para otras personas.', '2022-07-17 16:24:35', '2022-07-17 16:24:35', '2022-07-17 16:24:35', 'no', '', 5, NULL, 25548),
	('trip.incomplete.leg', 'fr', 'messages+intl-icu', 'Vous venez d’accepter une invitation d’une durée plus courte que votre séjour à {location} ({arrival, date, medium} - {departure, date, medium}). Cette étape de votre voyage ne sera plus visible par les autres membres : modifiez votre voyage en créant une nouvelle étape si nécessaire.', '2022-05-22 13:17:38', '2022-05-22 13:17:38', '2022-05-22 13:17:38', 'no', '', 5, NULL, 168499),
	('trip.incomplete.leg', 'gl', 'messages+intl-icu', 'Acabas de aceptar unha invitación que é máis curta que a túa estancia en  {location} ({arrival, date, medium} - {departure, date, medium}). Sopesa actualizar a túa viaxe dado que isto ocultará a outras persoas a túa viaxe.', '2022-05-24 08:55:36', '2022-05-24 08:55:36', '2022-05-24 08:55:36', 'no', '', 5, NULL, 210880),
	('trip.incomplete.leg', 'it', 'messages+intl-icu', 'Hai appena accettato un invito che è più corto della tua permanenza in {location} ({arrival, date, medium} - {departure, date, medium}). Considera la possibilità di aggiornare il tuo viaggio perché questo nasconderà la tappa agli altri.', '2022-04-25 18:37:42', '2022-04-25 18:37:42', '2022-04-25 18:37:42', 'no', '', 5, NULL, 160610),
	('trip.incomplete.leg', 'nl', 'messages+intl-icu', 'Je hebt zonet een uitnodiging aanvaard die korter is dan je verblijf in {location} ({arrival, date, medium} - {departure, date, medium}).   Overweeg om uw tocht aan te passen, want hierdoor zal deze etappe voor anderen verborgen worden.', '2022-12-02 19:59:00', '2022-12-02 19:59:00', '2022-12-02 19:59:00', 'no', '', 5, NULL, 21169),
	('trip.incomplete.leg', 'pl', 'messages+intl-icu', 'Właśnie zaakceptowałaś/eś zaproszenie na czas krótszy niż Twój pobyt w {location} ({arrival, date, medium} - {departure, date, medium}). To ukryje ten etap podróży przed innymi, dlatego rozważ jej aktualizację.', '2023-04-14 17:07:37', '2023-04-14 17:07:59', '2023-04-14 17:07:37', 'no', '', 5, NULL, 116789),
	('trip.incomplete.leg', 'pt', 'messages+intl-icu', 'Aceitou um convite que é mais curto que a sua estadia em {location} ({arrival, date, medium} - {departure, date, medium}). Considere atualizar a sua viagem, uma vez que isto irá esconder essa etapa de outros.', '2022-05-02 19:33:39', '2022-05-02 19:33:39', '2022-05-02 19:33:39', 'no', '', 5, NULL, 38787),
