	('updateafterneedmoreconfirmed', 'ca', 'messages', 'Gràcies <b>%s</b>,\r\n\r\nun voluntari repassarà el teu perfil i l\'acceptarà si totes les dades són completes.', '2007-08-30 22:35:22', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 177),
	('updateafterneedmoreconfirmed', 'cs', 'messages', 'Díky <b>%s</b>.\r\n\r\nDobrovolník přezkoumá tvůj profil a přijme ho, pokud všechna požadovaná pole jsou vyplněna.', '2014-02-04 23:29:45', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('updateafterneedmoreconfirmed', 'de', 'messages', 'Vielen Dank <b>%s</b>.\r\n\r\nEiner unserer Helfer wird nun schnellstmöglich überprüfen, ob dein Profil nun vollständig ist.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3050),
	('updateafterneedmoreconfirmed', 'el', 'messages', 'Ευχαριστούμε <b>%s</b>.\r\n\r\nΈνας εθελοντής θα ελέγξει το προφίλ και θα το εγκρίνει αν όλα τα απαιτούμενα πεδία έχουν συμπληρωθεί.', '2020-08-20 12:46:38', '2020-08-20 12:46:38', '2020-08-20 12:46:38', 'no', '', 5, NULL, 266544),
	('updateafterneedmoreconfirmed', 'en', 'messages', 'Thanks <b>%s</b>.\r\n\r\nA volunteer will review your profile and will accept it if all required fields are complete.', '2007-09-11 19:09:25', '2019-04-23 18:16:49', '2008-04-13 16:16:26', 'no', 'this is the message which is display on screen after a new members who\'s profile was incomplete has completed his profile', 5, NULL, 612),
	('updateafterneedmoreconfirmed', 'es', 'messages', 'Gracias <b>%s</b>, un voluntario revisará pronto tu perfil y lo aceptará si todos los datos requeridos están completos', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1328),
	('updateafterneedmoreconfirmed', 'fi', 'messages', 'Kiitos <b>%s</b>.\r\n\r\nVapaaehtoinen tarkastaa profiilisi ja hyväksyy sen, jos kaikki tarvittavat kentät on täytetty.', '2010-03-11 20:49:27', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 72),
	('updateafterneedmoreconfirmed', 'fr', 'messages', 'Merci <b>%s</b>, un volontaire va vérifier très bientôt votre profil et l\'acceptera si toutes les données sont complètes.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('updateafterneedmoreconfirmed', 'gl', 'messages', '<p>Grazas <strong>%s</strong>.</p><p>Unha persoa do voluntariado revisará o teu perfil e aceptarao se todos os campos requiridos están completos.&nbsp;</p>', '2022-03-25 11:33:29', '2022-03-25 11:33:29', '2022-03-25 11:33:29', 'no', '', 5, NULL, 210880),
	('updateafterneedmoreconfirmed', 'hr', 'messages', 'Hvala <b>%s</b>. \r\nVolonter će pregledati tvoj profil i prihvatiti ga ukoliko su tražena polja ispunjena.', '2010-01-15 21:06:27', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('updateafterneedmoreconfirmed', 'it', 'messages', 'Grazie <b>%s</b>.\r\n\r\nUn volontario controllerà presto il tuo profilo e lo accetterà se tutti i dati sono completi.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('updateafterneedmoreconfirmed', 'lt', 'messages', 'Ačiū, <b>%s</b>! \r\nMūsų savanoriai artimiausiu metu peržiūrės jūsų anketą ir, jei visi duomenys bus tvarkingi, patvirtins ją.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('updateafterneedmoreconfirmed', 'lv', 'messages', 'Paldies <b>%s</b>.\r\n\r\nBrīvprātīgais pārskatīs tavu profilu un apstiprinās to, ja visi obligātie lauki būs aizpildīti.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 375),
	('updateafterneedmoreconfirmed', 'nl', 'messages', 'Dankjewel <b>%s</b>, \r\n\r\neen vrijwilliger zal spoedig je profiel bekijken en het accepteren als alle gegevens compleet zijn,', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 138),
	('updateafterneedmoreconfirmed', 'pl', 'messages', 'Dziękujemy <b>%s</b>,\r\nwkrótce wolontariusze sprawdzą Twój profil i, jeśli podałeś wszystkie dane, zostaniesz zaakceptowany.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 90),
	('updateafterneedmoreconfirmed', 'pt', 'messages', 'Obrigado <b>%s</b>.\r\n\r\nUm voluntário irá rever o seu perfil e aceitá-lo se todos os campos necessários estiverem preenchidos.', '2013-01-08 14:51:48', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('updateafterneedmoreconfirmed', 'ro', 'messages', 'Mulţumim <b>%s</b>.\r\nUn voluntar îţi va revizui profilul şi dacă toate câmpurile necesare sunt completate îl va activa.', '2007-09-25 21:26:51', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1081),
	('updateafterneedmoreconfirmed', 'ru', 'messages', 'Спасибо, <b>%s</b>,\r\n\r\nВ ближайшее время ваш профиль проверит волонтер, и примет вашу заявку, если указаны все необходимые данные', '2007-09-09 08:31:11', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 79),
	('updateafterneedmoreconfirmed', 'sr', 'messages', 'Хвала <b>%s</b>. \r\n\r\nДобровољац ће погледати твој профил и прихватиће га ако су сва неопходна поља унета.', '2013-03-14 20:21:43', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 39772),
