	('updatemandatorypage', 'tr', 'messages', 'İsim yada adres güncelle', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('updatemandatoryupdated', 'ca', 'messages', 'S\'han actualitzat les dades, però un voluntari les haurà de revisar per a fer-les efectives. No trigarà gaire.', '2007-10-01 09:21:57', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 177),
	('updatemandatoryupdated', 'da', 'messages', 'Disse data er blevet opdaterede og skal muligvis tjekkes af en frivillig for at effektueres.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 74),
	('updatemandatoryupdated', 'de', 'messages', 'Deine Daten wurden aktualisiert, müssen aber noch von einem unserer Helfer aktiviert werden, was normalerweise sehr schnell geht.', '2007-07-01 09:56:31', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 91),
	('updatemandatoryupdated', 'en', 'messages', 'Your data have been updated but must be reviewed by a volunteer to become effective, it will be done very soon', '2007-04-27 16:49:13', '2019-04-23 18:16:49', '2008-08-09 12:18:50', 'no', 'Message display when mandatory data are updated', 5, 1, 101),
	('updatemandatoryupdated', 'es', 'messages', 'Los datos se han actualizado pero deben ser revisados por un voluntario para hacerse efectivo. Esto no tadará mucho.', '2007-11-17 03:02:07', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1328),
	('updatemandatoryupdated', 'fr', 'messages', 'Vos données ont été mises à jour mais doivent être revues par un volontaire pour être prises en compte.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 452),
	('updatemandatoryupdated', 'hr', 'messages', 'Tvoji podaci su ažurirani, ali da bi bili prihvaćeni mora ih prvo pregledati volonter, što će on/a učiniti u najskorijem mogućem vremenu.', '2010-03-22 14:31:12', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 8197),
	('updatemandatoryupdated', 'it', 'messages', 'I tuoi dati sono stati modificati, dovranno però essere rivisti da un volontario prima di diventare effettivi, ciò verrà fatto presto.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 103),
	('updatemandatoryupdated', 'lt', 'messages', 'Jūsų duomenys buvo atnaujinti, bet anketoje jie bus matomi po to, kai juos peržiūrės vienas iš mūsų savanorių. Tai neturėtų užtrukti.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 80),
	('updatemandatoryupdated', 'lv', 'messages', 'Tavi dati ir mainīti, bet lai tie būtu derīgi, tie vēl ir jāpārbauda brīvprātīgajam, tas tiks drīz izdarīts', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 375),
	('updatemandatoryupdated', 'nl', 'messages', 'Je gegevens zijn geupdated maar moeten nagezien worden door een vrijwilliger om doorgevoerd te worden. Dit zal weldra gebeuren.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 273),
	('updatemandatoryupdated', 'pl', 'messages', 'Te dane były zaktualizowane i muszą byc zrewidowane przez administratora aby stać sie użytecznymi', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 213),
	('updatemandatoryupdated', 'pt', 'messages', 'Estes dados foram actualizados mas têm que ser revistos por um voluntário para serem aceites, será feito em breve', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 38787),
	('updatemandatoryupdated', 'ro', 'messages', 'Datele tale au fost reactualizate dar trebuiesc revizuite de un voluntar pentru a deveni active, se va rezolva cât de curând.', '2007-09-25 21:18:43', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1081),
	('updatemandatoryupdated', 'ru', 'messages', 'Ваши данные были обновлены, но должны быть утверждены волонтером. Это не займет много времени.', '2009-03-09 12:39:07', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 79),
	('updatemantatoryconfirm', 'ca', 'messages', 'S\'han actualitzat les dades.\r\n\r\nUn voluntari les revisarà i les activarà.', '2007-08-01 20:22:32', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11944),
	('updatemantatoryconfirm', 'cs', 'messages', 'Tvá data byla aktualizována.\r\nDobrovolník je přezkoumá a aktivuje je.', '2013-10-17 22:03:24', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('updatemantatoryconfirm', 'de', 'messages', 'Deine Daten wurden aktualisiert.\r\n\r\nEin Helfer wird die Daten überprüfen und aktualisieren.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3050),
	('updatemantatoryconfirm', 'el', 'messages', 'Έχει γίνει ενημέρωση των πληροφοριών σου.\r\n\r\nΈνας από τους εθελοντές μας θα τις αναθεωρήσει πριν τις κάνει ορατές.', '2020-08-16 18:05:06', '2020-08-28 11:27:23', '2020-08-16 18:05:06', 'no', '', 5, NULL, 266544),
	('updatemantatoryconfirm', 'en', 'messages', 'Your data has been updated.\r\n\r\nA volunteer will review this and make it active.', '2007-08-25 19:11:37', '2019-04-23 18:16:49', '2008-04-13 16:16:26', 'no', '', 5, NULL, 612),
	('updatemantatoryconfirm', 'eo', 'messages', 'Viaj datumoj estas ĝisdatigitaj.\r\n\r\nVolontulo kontrolos ilin kaj aktivigos.', '2013-03-14 21:09:22', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 47220),
	('updatemantatoryconfirm', 'es', 'messages', 'Los datos se actualizaron.\r\n\r\nUn voluntario revisará esto y lo activará.', '2007-10-30 04:52:22', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1328),
	('updatemantatoryconfirm', 'fi', 'messages', 'Tietosi on päivitetty.\r\n\r\nVapaaehtoistyöntekijä tulee tarkastamaan ja aktivoimaan ne.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 72),
	('updatemantatoryconfirm', 'fr', 'messages', 'Vos informations ont été mises à jour. \r\n\r\nUn volontaire va les examiner avant de les activer.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('updatemantatoryconfirm', 'gl', 'messages', 'Os teus datos foron actualizados. \r\n\r\nUnha persoa voluntaria revisará isto e activarao.', '2022-03-29 09:58:50', '2022-03-29 09:59:34', '2022-03-29 09:58:50', 'no', '', 5, NULL, 210880),
	('updatemantatoryconfirm', 'hr', 'messages', 'Tvoji podaci su ažurirani.\r\nVolonter će ih pregledati i aktivirati.', '2009-09-18 20:09:07', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('updatemantatoryconfirm', 'it', 'messages', 'I tuoi dati sono stati modificati.\r\nUn volontario li controllerà e li renderà attivi', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 103),
	('updatemantatoryconfirm', 'lt', 'messages', 'Jūsų duomenys atnaujinti. \r\n\r\nVienas iš mūsų savanorių juos peržiūrės ir aktyvuos pakeitimus.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('updatemantatoryconfirm', 'lv', 'messages', 'Tavi dati ir laboti.\r\n\r\nBrīvprātīgais tos pārbaudīs un aktivizēs.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 375),
	('updatemantatoryconfirm', 'nl', 'messages', 'Je gegevens zijn bijgewerkt.\r\n\r\nEen vrijwilliger zal ze bekijken om ze actief te maken.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40169),
	('updatemantatoryconfirm', 'pl', 'messages', 'Twoje dane osobowe zostały uaktualnione. \r\nMusisz poczekać aż wolontariusze przejrzą je i uaktywnią.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1),
	('updatemantatoryconfirm', 'pt', 'messages', 'Os seus dados foram atualizados.\r\n\r\nUm voluntário irá revê-los e ativar a alteração.', '2007-07-10 22:53:56', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('updatemantatoryconfirm', 'ro', 'messages', 'Datele tale au fost reactualizate.\r\nUn voluntar va revizui formularul şi-l va activa.', '2007-09-25 21:13:52', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1081),
	('updatemantatoryconfirm', 'ru', 'messages', 'Ваши данные были обновлены. \r\nВолонтер проверит их и примет изменения', '2007-09-09 08:49:14', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 79),
	('updatemantatoryconfirm', 'sr', 'messages', 'Ваши подаци су ажурирани.\r\nВолонтер ће их прегледати и активирати.', '2013-07-19 15:13:48', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 52973),
	('updatemantatoryconfirm', 'tr', 'messages', 'Bilgileriniz güncellendi. Bir Gönüllü bilgilerini izleyip etkin hale getirecek', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1),
	('updatemantatorymailconfirm', 'ca', 'messages', 'Hola %s%s%s,\r\n\r\nEls voluntaris encarregats de revisar adreces i noms processaran la petició d\'actualització ben aviat.\r\n\r\nSi les dades són correctes, trigaran fins a 2 dies.\r\n\r\nPassi-ho bé!', '2007-09-30 13:21:45', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 177),
	('updatemantatorymailconfirm', 'de', 'messages', 'Hallo %s %s %s, \r\ndeine Aktualisierung wird - sofern deine Angaben komplett sind - innerhalb von 2 Tagen von einem unserer Helfer bearbeitet.\r\n\r\nViel Spaß mit %s', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3050),
	('updatemantatorymailconfirm', 'el', 'messages', 'Γεια σου %s %s %s,\r\nτο αίτημα ενημέρωσης θα το επεξεργαστούν σύντομα οι υπεύθυνοι εθελοντές ελέγχου ενημερώσεων για διευθύνσεις και ονόματα. \r\nΑν οι πληροφορίες σου είναι πλήρως συμπληρωμένες, οι ενημερώσεις θα ολοκληρωθούν μέσα σε 2 μέρες.\r\n\r\nΝα περνάς καλά με  %s', '2020-08-20 13:21:29', '2020-09-03 10:15:34', '2020-08-20 13:21:29', 'no', '', 5, NULL, 266544),
	('updatemantatorymailconfirm', 'en', 'messages', 'Hello %s %s %s,\r\nyour update request will be processed soon by the volunteers in charge of checking addresses and names updates.\r\nIf your data is complete, updates are usually completed within 2 days.\r\n\r\nHave fun with %s\r\n', '2007-08-25 19:15:49', '2019-04-23 18:16:49', '2008-04-13 16:16:26', 'no', 'This is the confirmation mail and the message member see on screen when he has filled up an update request for his/her mandatory data', 5, NULL, 612),
	('updatemantatorymailconfirm', 'es', 'messages', 'Hola %s %s %s, \r\nLa petición de actualización será procesada rápidamente por los voluntarios a cargo de las direcciones y nombres.\r\nLas actualizaciones tardan menos de dos días en activarse.\r\n\r\n¡Diviértete con %s!', '2007-10-30 04:56:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1328),
	('updatemantatorymailconfirm', 'fr', 'messages', 'Bonjour %s %s %s, \r\nVotre demande de mise à jour va bientôt être traitée par les volontaires BeWelcome. \r\nSi les informations sont complètes, la validation est généralement effectuée sous deux jours. \r\n\r\nProfitez bien de %s !', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('updatemantatorymailconfirm', 'gl', 'messages', 'Ola %s %s %s,\r\na túa solicitude de actualización será procesada pronto polas persoas voluntarias que se ocupan de comprobar as actualizacións dos enderezos e dos nomes.\r\nSe os teus datos están completos, as actualizacións normalmente finalizan antes de dous días. \r\n\r\nDivírtete con %s', '2022-03-29 09:56:43', '2022-03-29 09:56:43', '2022-03-29 09:56:43', 'no', '', 5, NULL, 210880),
	('updatemantatorymailconfirm', 'hr', 'messages', 'Bok %s %s %s!\r\nVolonter zadužen za provjeru ažuriranih adresa i i imena tvoj će zahtjev uskoro pregledati. \r\nAko su uneseni podaci potpuni, ažuriranje je obično gotovo za 2 dana. \r\n\r\nŽelimo ti dobru zabavu s %s \r\n', '2010-01-05 10:24:57', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('updatemantatorymailconfirm', 'it', 'messages', 'Ciao %s %s %s,\r\nla tua richiesta di modifica sarà verificata al più presto dai volontari responsabili del controllo per i cambiamenti di indirizzi e nomi. Se i tuoi dati sono completi, gli aggiornamenti richiedono solitamente due giorni.\r\nBuon divertimento con %s \r\n', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 16084),
	('updatemantatorymailconfirm', 'lt', 'messages', 'Sveiki, %s %s %s,\r\njūsų naujus duomenis kaip įmanoma greičiau patikrins ir aktyvuos mūsų savanoriai, atsakingi už vardų ir adresų keitimą.\r\nJei jūsų duomenys pilni ir teisingi, pakeitimas neturėtų užtrukti ilgiau nei 2 dienas.\r\n\r\nSmagaus naudojimosi %s', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('updatemantatorymailconfirm', 'lv', 'messages', 'Sveiks %s %s %s,\r\ntavu labojuma lūgumu drīzumā apstrādās brīvprātīgais, kurš ir atbildīgs par adrešu un vārdu izmaiņām.\r\nJa tavi dati ir pareizi, labojums parasti tiek veikts 2 dienās.\r\n\r\nHave fun ar %s', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 375),
	('updatemantatorymailconfirm', 'nl', 'messages', 'Hallo %s %s %s,\r\nJe aanvraag voor bijwerking van je gegevens zal spoedig verwerkt worden door de vrijwilligers die belast zijn met het controleren van adressen en bijwerkingen van de namen.\r\nAls je gegevens volledig zijn gebeurt dit gewoonlijk in de twee volgende dagen.\r\n\r\nVeel plezier met %s ', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 138),
	('updatemantatorymailconfirm', 'pl', 'messages', 'Witaj %s %s %s,\r\ntwoja prośba o aktualizację danych będzie wkrótce rozpatrzona przez jednego z naszych wolontariuszy. Jeśli dane są kompletne, aktualizacja następuje zwykle w ciągu dwóch dni. \r\n\r\nMiłego korzystania z %s\r\n', '2007-09-21 17:37:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1554),
	('updatemantatorymailconfirm', 'pt', 'messages', 'Olá %s %s %s,\r\no seu pedido de atualização será em breve processado pelos voluntários encarregues de verificar atualizações de nomes e moradas.\r\nSe os seus dados estiverem completos, as atualizações normalmente estão prontas no prazo de 2 dias.\r\n\r\nDivirta-se com %s', '2012-12-10 11:29:06', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('updatemantatorymailconfirm', 'ru', 'messages', 'Доброго времени суток, %s %s %s,\r\nваш запрос на обновление информации будет в ближайшем времени обработан волонтерами  и проверен на корректность обновления адресов и имен.\r\nЕсли вы указали достаточные данные, обновления вступят в силу спустя 2 дня.\r\n\r\nУдачи с %s\r\n', '2007-09-09 09:59:22', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
	('updatemantatorysubj', 'ca', 'messages', 'Actualització de les dades obligatòries amb la data %s', '2007-08-30 22:03:07', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 177),
