	('volunteercoordinators', 'ru', 'messages', 'Координаторы волонтеров', '2009-03-09 12:02:52', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 79),
	('volunteercoordinators', 'zh-hans', 'messages', '志愿者协调员', '2010-09-29 14:29:14', '2021-05-02 07:48:47', '0000-00-00 00:00:00', 'no', '', 5, 1, 11819),
	('volunteercoordinators', 'zh-hant', 'messages', '志愿者协调员', '2010-09-29 14:29:14', '2021-05-02 07:48:37', '0000-00-00 00:00:00', 'no', '', 5, 1, 11819),
	('volunteercoordinatorstext', 'ca', 'messages', 'Tens dubtes sobre com esdevenir voluntari? O potser problemes amb el teu equip? La Claudia i en Florian t\'ajudaran, et donaran consells útils i resoldran problemes.<br /><br />Tots dos són voluntaris actius i, a més, actualment també són membres de la <a href="http://www.bewelcome.org/bod/">Junta directiva</a>, que s\'escull anualment.', '2008-03-01 10:42:11', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 11944),
	('volunteercoordinatorstext', 'de', 'messages', 'Fragen über das Helfen und Mitmachen? Probleme mit deinem Team? Claudia und Florian werden dir helfen und das Problem lösen. Claudia und Florian sind beide aktive Helfer und zur Zeit Mitglieder des <a href="http://www.bewelcome.org/bod/">jährlich gewählten BoD</a>', '2008-03-01 21:43:31', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 15240),
	('volunteercoordinatorstext', 'en', 'messages', 'Questions about volunteering? Problems with your team? Claudia and Florian will help you, give advice and solve problems.', '2008-02-29 10:59:34', '2019-04-23 18:16:49', '2008-09-30 17:46:54', 'no', 'Little text about volunteer coordinators at volunteer page', 5, 1, 91),
	('volunteercoordinatorstext', 'eo', 'messages', 'Demandoj pri volontulado? Problemoj kun via skipo? Claudia kaj Florian helpos al vi, donos konsilojn, kaj solvos problemojn.\r\n\r\nAmbaŭ Claudia kaj Florian estas aktivaj volontuloj kaj ankaŭ cĉijare <a href="http://www.bewelcome.org/bod/">elektitaj estraranoj</a> ', '2008-08-22 01:59:38', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1769),
	('volunteercoordinatorstext', 'es', 'messages', '¿Preguntas sobre ser voluntario, problemas con tu equipo? Claudia y Florian te ayudarán, aconcejarán y resolverán problemas. ', '2008-03-01 23:45:54', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 554),
	('volunteercoordinatorstext', 'fr', 'messages', 'Une question sur le volontariat dans BeWelcome ? des problèmes avec votre équipe ? Claudia et Florian vous aideront, vous conseilleront et essaieront de résoudre vos problèmes.\r\n', '2008-04-06 07:51:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('volunteercoordinatorstext', 'hr', 'messages', 'Imaš pitanje o volontiranju? Probleme s ekipom? Claudia i Florian će ti pomoći, savjetovati i rješiti problem.', '2009-09-06 15:48:06', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 8197),
	('volunteercoordinatorstext', 'hu', 'messages', 'Kérdésed van az önkéntességről? Problémák a csapatban? Claudia és Florian segítenek, tanácsot adnak és megoldják a problémákat.', '2011-12-09 09:06:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 23486),
	('volunteercoordinatorstext', 'it', 'messages', 'Domande in merito al lavoro di volontario? Problemi con il tuo team? Claudia e Florian ti aiuteranno, ti daranno consigli e risolveranno problemi.', '2008-04-27 11:44:29', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 16084),
	('volunteercoordinatorstext', 'lt', 'messages', 'Turi klausimų apie savanoriavimą? Atsirado problemų tavo komandoje? Claudia ir Florian patars tau ir padės išspręsti problemas.', '2008-03-03 15:44:33', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 227),
	('volunteercoordinatorstext', 'nl', 'messages', 'Vragen over vrijwilligerswerk?  Problemen met je team?  Claudia en Florian helpen je, geven advies en lossen problemen op.', '2011-12-22 16:07:25', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 21169),
	('volunteercoordinatorstext', 'pt', 'messages', 'Perguntas sobre o voluntariado? Problemas com a sua equipa? Claudia e Florian podem ajuda-lo, fornecer concelhos e resolver problemas.', '2013-01-31 15:07:16', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 30452),
	('volunteercoordinatorstext', 'pt-BR', 'messages', 'Questões relacionadas ao Volunteer? Problemas com sua equipe? Claudia e Florian vão ajudar você, dar conselhos e resolver problemas.', '2011-09-07 19:24:48', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'no', '', 5, 1, 15566),
	('volunteerdashboard', 'ca', 'messages', 'Vista general', '2008-02-29 13:41:39', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
