	('volunteertools_downloadtext2', 'ca', 'messages', 'com a nom d\'usuari / contrasenya a la finestra emergent.', '2008-07-05 14:28:44', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 3236),
