	('volunteertools_test', 'de', 'messages', 'Testumgebung - Entwickeln von neuen Ideen', '2008-03-01 22:30:02', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, NULL, 3050),
