	('volunteertools_test', 'es', 'messages', 'Probar ambiente - desarrollando nuevas ideas', '2008-02-28 12:40:06', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, NULL, 1328),
	('volunteertools_test', 'fr', 'messages', 'Environnement de test - Développer de nouvelles idées', '2008-02-25 22:37:11', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, NULL, 452),
	('volunteertools_test', 'it', 'messages', 'Area di sperimentazione - sviluppo di nuove idee', '2011-12-15 13:00:39', '2023-09-19 18:11:33', '0000-00-00 00:00:00', 'yes', '', 5, NULL, 16084),
	('volunteertools_test', 'lt', 'messages', 'Bandymų aplinka - naujų idėjų vystymas', '2008-02-25 19:27:43', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, NULL, 227),
	('volunteertools_test', 'nl', 'messages', 'Testomgeving - nieuwe ideeen ontwikkelen', '2008-03-30 10:39:55', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, NULL, 97),
	('volunteertools_test', 'pt', 'messages', 'Ambiente de testes - desenvolvimento de novas ideias', '2019-11-08 16:59:11', '2023-09-19 18:11:33', '2019-11-08 16:59:11', 'yes', '', 5, NULL, 38787),
	('volunteertools_test', 'pt-BR', 'messages', 'Ambiente de teste - desenvolvendo novas ideias', '2011-09-07 19:28:43', '2023-09-19 18:11:33', '0000-00-00 00:00:00', 'yes', '', 5, NULL, 15566),
	('volunteertools_testtext', 'ca', 'messages', 'A l\'àrea de proves, el que compta és la creativitat. És on els programadors creen i posen a prova les noves funcions de BeWelcome abans que passin a la següent fase: l\'àrea alfa...', '2008-03-01 11:11:02', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 3236),
	('volunteertools_testtext', 'de', 'messages', 'In der Testumgebung geht es um Kreativität. Dies ist der Platz an dem unsere Entwickler neue Zusatzfunktionen für BeWelcome erstellen und testen, bevor sie in die nächste Stufe kommen: Die Alpha Seite...', '2008-03-02 01:15:16', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 3050),
	('volunteertools_testtext', 'en', 'messages', 'The testing environment is all about creativity. It\'s the place where our developers create and test new features for BeWelcome before they get to the next stage: the alpha site... ', '2008-02-22 12:48:30', '2019-04-23 18:16:49', '2008-04-04 17:52:00', 'yes', '', 5, 1, 91),
	('volunteertools_testtext', 'es', 'messages', 'Las pruebas de ambiente se tratan de creatividad. Es el lugar donde nuestros promotores crean y prueban nuevas aplicaciones para BeWelcome antes de ir a la próxima faceta: el sitio alfa...', '2008-02-28 18:27:28', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 1328),
	('volunteertools_testtext', 'fr', 'messages', 'L\'environnement de test permet de laisser s\'exprimer notre créativité. C\'est l\'endroit où nos développeur créent et expérimentent les futures fonctionnalités de BeWelcome avant l\'étape suivante: le site alpha', '2009-04-14 14:47:07', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 1),
	('volunteertools_testtext', 'it', 'messages', 'L\'area di sperimentazione è dedicata alla creatività. Qui i nostri sviluppatori creano e testano le nuove funzionalità di BeWelcome che poi passano alla fase successiva: il sito Alfa.', '2011-12-15 13:02:09', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 16084),
	('volunteertools_trac', 'ca', 'messages', 'Trac: gestor de tasques i registre d\'errors', '2008-02-29 16:07:28', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 3236),
	('volunteertools_trac', 'de', 'messages', 'Trac - Aufgabenplaner und Bug Tracker', '2008-03-01 22:31:54', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 3050),
	('volunteertools_trac', 'en', 'messages', 'Trac - task manager and bug tracker', '2008-02-22 12:49:37', '2019-04-23 18:16:49', '2008-04-04 17:52:00', 'yes', '', 5, 1, 91),
	('volunteertools_trac', 'es', 'messages', 'Trac - gestor de tareas y perseguidor de bug', '2008-02-28 16:19:30', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 1328),
	('volunteertools_trac', 'fr', 'messages', 'Trac - Gestionnaire de tâches et report de <i>bugs</i>', '2008-02-25 22:34:14', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 452),
	('volunteertools_trac', 'it', 'messages', 'Trac - gestione delle mansioni e bug tracker', '2011-12-15 13:37:05', '2023-09-19 18:11:33', '0000-00-00 00:00:00', 'yes', '', 5, 1, 16084),
	('volunteertools_trac', 'lt', 'messages', 'TRAC -  užduočių tvarkyklė ir riktų „pėdsekys“', '2008-02-22 15:37:59', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 227),
	('volunteertools_trac', 'nl', 'messages', 'Trac – takenbeheerder en bugopvolger', '2008-03-29 16:18:46', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 21169),
	('volunteertools_tractext', 'ca', 'messages', 'El Trac és el nostre sistema de gestió de tasques. S\'hi introdueixen els problemes i els suggeriments de funcions noves i, posteriorment, s\'assignen a una persona. A més a més, el Trac mostra en quin punt del procés de desenvolupament del lloc ens trobem, és a dir, ens diu en què es treballa i quan estarà a punt. Tot just ara comencem a estendre el sistema Trac a tots els equips (no solament als equips tècnics), així que estigues a l\'aguait!', '2008-03-01 11:09:06', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 3236),
	('volunteertools_tractext', 'de', 'messages', 'Trac ist unser Management System. Hier werden Probleme oder Vorschläge für neue Funktionen gemeldet und einem Bearbeiter zugeordnet. Zusätzlich liefert das Trac System den aktuellen Entwicklungsstatus unserer Seite (z.B. wann welche Veröffentlichung geplant ist oder erwartet wird). Wir haben gerade damit begonnen das Trac System für alle unsere Teams zu erweitern und nicht nur für die für die technischen Bereiche zu nutzen. Bleib also dran!', '2008-03-02 13:20:11', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 3050),
	('volunteertools_tractext', 'en', 'messages', 'Trac is our task managing system. Problems or suggestions for new features are reported there and assigned to a person. Additionally, trac shows where we are in the site development process i.e. which releases are to be expected and when. We are just starting to extend the trac system for all our teams, not only the tech related ones. Stay tuned!', '2008-02-22 12:48:04', '2019-04-23 18:16:49', '2008-04-04 17:52:00', 'yes', '', 5, 1, 91),
	('volunteertools_tractext', 'es', 'messages', 'Trac es nuestro sistema de administración de tareas. Allí se reportan los problemas o las sugerencias para nuevas aplicaciones y son asignadas a una persona. Adicionalmente, trac muestra donde estamos en el proceso de desarrollo i.e. Que novedades deben espear y cuando. Apenas estamos empezando a extender el sistema de trac para todos nuestros equipos, no sólo aquellos relacionados con la tecnología ¡Sigue en sintonía!', '2008-02-28 16:34:02', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 1328),
	('volunteertools_tractext', 'it', 'messages', 'Trac è il nostro sistema di gestione delle mansioni. i problemi o i suggerimenti riguardo le nuove funzionalià sono raccolti qui e assegnati ad una persona. Inoltre, Trac mostra a che punto è il processo di sviluppo del sito, ossia quali saranno le prossime novità e quando saranno disponibili. Stiamo iniziando ad espendere il sistema per tutti i nostri gruppi di lavoro, non solo per i tecnici.\r\nSegui gli sviluppi!', '2011-12-15 13:40:13', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 16084),
	('volunteertoolsbartitle', 'ar', 'messages', 'مناطق العمل', '2008-03-03 10:17:57', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 2702),
	('volunteertoolsbartitle', 'ca', 'messages', 'Àrees de treball', '2008-02-29 15:32:13', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3236),
	('volunteertoolsbartitle', 'de', 'messages', 'Work Areas', '2008-03-01 20:56:28', '2019-12-26 09:49:40', '0000-00-00 00:00:00', 'no', '', 5, NULL, 3050),
	('volunteertoolsbartitle', 'el', 'messages', 'Τομείς Εργασίας', '2020-08-15 15:16:46', '2020-08-15 15:16:46', '2020-08-15 15:16:46', 'no', '', 5, NULL, 266544),
