	('votecommentissignificant', 'sr', 'messages', 'Свиђа ми се овај коментар', '2013-07-19 16:34:59', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 52973),
	('votecommentissignificantexplanation', 'en', 'messages', 'If you click on this link this might change the popularity of this comment.\r\nYour vote might contribute in making it to become the comment of the moment\r\nDo so if you think this comment is representative of BeWelcome purpose.', '2009-05-22 19:50:53', '2019-04-23 18:16:49', '2009-05-22 19:56:34', 'no', 'Comments vote explanation (this is the same text both for vote or delete vote).\r\nIt appears as a popup when the user put the mouse on the link used either to add a vote for a comment or to delete it', 5, 1, 1),
	('votecommentissignificantexplanation', 'es', 'messages', 'Si hace clic en este enlace esto podría cambiar la popularidad de este comentario. Su voto podría contribuir par que se convierta en el comentario del momento. Hazlo si crees que este comentario es representativo del propósito de BeWelcome.\r\n', '2011-12-01 00:02:31', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 8437),
	('votecommentissignificantexplanation', 'fr', 'messages', 'Si vous cliquez sur ce lien, vous accroitrez la popularité de ce commentaire.\r\nCela pourrai permettre de le rendre éligible en tant que commentaire du moment\r\nDonc, si vous pensez que ce commentaire est intéressant pour l\'image de BeWelcome, cliquez !', '2009-05-22 19:52:31', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 1),
	('votecommentissignificantexplanation', 'it', 'messages', 'Questo link ti permette di modificare la popolarità di questo commento.\r\nIl tuo voto può contribuire a renderlo il commento del momento.\r\nVota se pensi che questo commento ben rappresenti l\'obiettivo di BeWelcome. \r\n', '2011-09-19 09:39:02', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 16084),
	('votecommentissignificantexplanation', 'nl', 'messages', 'Als je op deze link klikt kan de populariteit van dit commentaar veranderen.  Je stem kan eraan bijdragen dat het het commentaar van het moment wordt.  Doe dit als je denkt dat dit aan het doel van BeWelcome bijdraagt.', '2011-12-22 15:55:25', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 21169),
	('votecommentissignificantremove', 'ca', 'messages', 'Elimina el meu vot d\'aquest comentari', '2009-06-23 15:00:04', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, 1, 5533),
