	('wearetotnumber', 'es', 'messages', '<p>¡BeWelcome crece cada vez mas rápido! Al momento somos %d miembros <br> ¿Deseas saber más sobre nuestros números? Chequea las <a href="http://www.bewelcome.org/statistics">estadísticas del proyecto</a>.</p><p>Actualmente están conectados:</p>', '2007-10-28 06:51:39', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 554),
	('wearetotnumber', 'fi', 'messages', 'BeWelcome kasvaa vauhdilla! Tällä hetkellä meitä on %d. Haluatko tietää enemmän luvuista? Katso <a href="http://www.bewelcome.org/statistics">projektin statistiikat</a>. <p> Tällä hetkellä kirjautuneena:', '2007-07-26 16:13:53', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 72),
	('wearetotnumber', 'fr', 'messages', 'BeWelcome compte chaque jour plus de membres ! Nous sommes actuellement <b>%d membres.</b><br /> Vous voulez en savoir plus sur ces chiffres ? Consultez <a href="http://www.bewelcome.org/statistics">les statistiques de BeWelcome</a>.<br />En ligne maintenant :', '2007-07-24 11:57:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 9823),
	('wearetotnumber', 'gl', 'messages', '<p>BeWelcome está medrando rápido! Agora mesmo somos %d persoas membro. Queres saber máis sobre os números? Visita as <a href="https://beta.bewelcome.org/statistics">estatísticas do proxecto</a>.</p><p>Actualmente en liña:</p>', '2022-03-29 10:48:09', '2022-03-29 10:48:09', '2022-03-29 10:48:09', 'no', '', 5, NULL, 210880),
	('wearetotnumber', 'he', 'messages', 'האתר שלנו גדל מהר! כרגע אנחנו %d חברים מחוברים עכשיו.\r\nרוצה לקבל עוד מספרים? הסתכל ב<a href="http://www.bewelcome.org/statistics">עמוד הסטטיסטיקה</a> שלנו.\r\n ', '2008-06-11 18:10:33', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 13904),
