	('wikiintroduction', 'de', 'messages', 'Willkommen im BeWelcome Wiki!  <a href="http://www.bewelcome.org/wiki/instructions">Lies die Bedienungsanleitung</a> und leg los! ', '2008-09-03 09:30:55', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('wikiintroduction', 'el', 'messages', 'Καλώς όρισες στο Wiki! <a href="https://www.bewelcome.org/wiki/instructions">Διάβασε τις οδηγίες</a> και ταξίδεψε!', '2013-03-13 16:08:03', '2020-08-25 08:30:04', '0000-00-00 00:00:00', 'no', '', 5, NULL, 266544),
	('wikiintroduction', 'en', 'messages', 'Welcome to our wiki! <a href="http://www.bewelcome.org/wiki/instructions">Read the instructions</a> and get going!', '2008-08-20 23:21:07', '2019-04-23 18:16:49', '2012-05-04 12:28:56', 'no', 'Short intro to the BeWelcome Wiki', 5, NULL, 69),
	('wikiintroduction', 'eo', 'messages', 'Bonvenon al vikio! <a href="http://www.bewelcome.org/wiki/instructions">Legu la instrukciojn</a> kaj agu!', '2013-03-15 05:27:51', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 47220),
	('wikiintroduction', 'es', 'messages', 'Bienvenido a nuestra wiki! <a href="http://www.bewelcome.org/wiki/instructions">Por favor, lee las instrucciones</a> y ponte manos a la obra! ', '2008-09-25 10:06:44', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 65289),
	('wikiintroduction', 'eu', 'messages', 'Ongi etorri gure wikira! <a href="http://www.bewelcome.org/wiki/instructions">Irakurri argibideak</a> eta ekiozu editatzeari!', '2012-12-06 15:45:34', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11907),
	('wikiintroduction', 'fr', 'messages', 'Bienvenue sur notre wiki ! <a href="http://www.bewelcome.org/wiki#line2">Lisez les instructions (en anglais pour le moment)</a> et faites-le vivre !', '2008-09-08 15:16:51', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 68),
	('wikiintroduction', 'gl', 'messages', '<p>Benvida/o á nosa wiki! <a href="http://www.bewelcome.org/wiki/instructions">Le as instrucións&nbsp;</a> e ponte en marcha!</p>', '2021-12-14 10:08:14', '2021-12-14 10:08:14', '2021-12-14 10:08:14', 'no', '', 5, NULL, 210880),
	('wikiintroduction', 'hr', 'messages', 'Dobrodošao/la na naš wiki!  <a href="http://www.bewelcome.org/wiki/instructions">Pročitaj upute</a> i kreni! ', '2009-09-07 18:56:13', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 8197),
	('wikiintroduction', 'hu', 'messages', 'Üdvözlünk a Wiki oldalunkon<a href="http://www.bewelcome.org/wiki/instructions">Olvasd el a tájékoztatót</a> majd indulás!', '2013-11-13 13:42:20', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 58692),
	('wikiintroduction', 'hy', 'messages', 'Բարի գալուստ մեր Վիքի! <a href="http://www.bewelcome.org/wiki/instructions">Կարդացեք հուշումներն </a>ու անցեք գործի!', '2013-06-24 18:47:51', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 22128),
	('wikiintroduction', 'id', 'messages', 'Selamat datang pada halaman wiki! <a href="http://www.bewelcome.org/wiki/instructions">Simak petunjuk pemakaian</a> dan mulai berkontribusi! ', '2013-06-11 10:49:17', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 2019),
	('wikiintroduction', 'it', 'messages', 'Benvenuto nella nostra wiki! <a href="http://www.bewelcome.org/wiki#line2">Leggi le istruzioni</a> e comincia ad usarla!', '2010-04-29 13:49:26', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 13861),
	('wikiintroduction', 'lt', 'messages', 'Tai yra BeWelcome viki puslapiai, arba puslapiai, kuriuos redaguoti gali visi. BeWelcome svetainėje mes stengiamės kuo daugiau naudoti viki tam, kad ši svetainė taptų labiau tavo ir kitų narių. Yra dalykų, kurie dar laukia savo laiko pasirodyti šioje svetainėje, nes dar turi būti sukurti programuotojų ir bei išbandyti administratorių - tačiau tu gali jau dabar pasidalinti savo žiniomis ir nuomone visur, kur tik tai yra jau įmanoma. Naudokis tuom. Tai - tavo BeWelcome!', '2009-08-09 02:17:41', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('wikiintroduction', 'nl', 'messages', 'Welkom op onze wiki! <a href="http://www.bewelcome.org/wiki/instructions">Lees de instructies</a> en ga aan de slag!', '2008-09-12 10:05:51', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11040),
