	('yourmessagefor', 'tr', 'messages', '<b>%s</b> için mesajınız', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1),
	('yourmessageforgroup', 'ca', 'messages', 'Escriu un missatge per al grup %s.\r\n\r\nAtenció: Només els membres d\'aquest grup que hagin escollit de rebre notificacions de missatges massius rebran el teu missatge.', '2007-09-12 20:20:45', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 177),
	('yourmessageforgroup', 'de', 'messages', 'Hinterlasse hier eine Nachricht für die Gruppe %s.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 15240),
	('yourmessageforgroup', 'el', 'messages', 'Πρόσθεσε εδώ το μήνυμα σου για την ομάδα %s\r\n\r\nΣημείωση: μόνο τα μέλη της ομάδας που έχουν επιλέξει να λαμβάνουν ειδοποιήσεις δημοσιεύσεων μαζικών μηνυμάτων αυτής της ομάδας θα λάβουν αυτό το μήνυμα.', '2020-08-20 11:26:27', '2020-08-20 11:27:33', '2020-08-20 11:26:27', 'no', '', 5, NULL, 266544),
	('yourmessageforgroup', 'en', 'messages', 'Enter here your message for the group %s\r\n\r\nNote: only the members of this group who have elected to receive notification of mass message postings from this group will receive this message.', '2007-09-10 23:03:47', '2019-04-23 18:16:49', '2008-04-13 16:16:26', 'no', 'This is the header which is display above the form which allow to send a message to a group', 5, NULL, 612),
	('yourmessageforgroup', 'es', 'messages', 'Ingresa aquí un mensaje para el grupo %s\r\n\r\nNota: sólo aquellos miembros de este grupo que escogieron recibir notificación de mensajes masivos recibirán este mensaje.', '2007-12-31 04:53:32', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1328),
	('yourmessageforgroup', 'fr', 'messages', 'Rédiger ici le message destiné au groupe %s\r\n\r\nNote&nbsp;: votre message sera uniquement envoyé aux membres du groupe qui ont choisi de recevoir les messages collectifs envoyés à ce groupe.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 56017),
	('yourmessageforgroup', 'gl', 'messages', 'Introduce aquí a túa mensaxe ao grupo  %s\r\n\r\nNota: só as persoas deste grupo que elixiran recibir as notificacións de envíos masivos de mensaxes deste grupo recibirán esta mensaxe.', '2022-03-29 09:28:51', '2022-03-29 09:28:51', '2022-03-29 09:28:51', 'no', '', 5, NULL, 210880),
	('yourmessageforgroup', 'it', 'messages', 'Scrivi qui il tuo messaggio per il gruppo %d \r\n\r\nNota: Solo i membri di questo gruppo che hanno accettato di ricevere messaggi di massa riceveranno il messaggio.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('yourmessageforgroup', 'lt', 'messages', 'Čia įrašykite žinutę kitiems grupės %s nariams\r\n\r\nPastaba: tik tie nariai, kurie yra pasirinkę gauti pranešimus dėl naujų šios grupės žinučių, gaus šį laišką.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 227),
	('yourmessageforgroup', 'lv', 'messages', 'Ievadi šeit savu vēstuli grupai %s\r\n\r\nPiebilde: šo vēstuli saņems tikai tie grupas biedri, kuru ir izvēlējušies  paziņojumus par masu vēstuļu ierakstu no šīs grupas saņemšanu.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 375),
	('yourmessageforgroup', 'nl', 'messages', 'Vul hier je bericht voor de groep %s in\r\n\r\nNB: alleen leden van deze groep die geaccepteerd hebben de groeps e-mails te ontvangen zullen dit bericht ontvangen.', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40169),
	('yourmessageforgroup', 'pl', 'messages', 'Wpisz tu wiadomość dla grupy %s\r\n\r\nPamiętaj: tylko ci członkowie grupy, którzy zgodzili się otrzymywać zawiadomienia o masowych postach, otrzymają tę wiadomość. \r\n', '2007-09-21 07:57:52', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1554),
	('yourmessageforgroup', 'pt', 'messages', 'Escreva aqui a sua mensagem para o grupo %s\r\n\r\nNota: apenas os membros deste grupo que aceitaram receber mensagens em massa deste grupo receberão esta mensagem', '2007-06-29 13:19:26', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 38787),
	('yourmessageforgroup', 'ru', 'messages', 'Введите сообщение для группы %s \r\n\r\nВнимание: ваше сообщение получат только те зарегистрированные члены этой группы, которые активировали опцию "получать сообщения групповой рассылки" ', '2007-09-09 09:54:26', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 79),
