	('yourmessageissavedasdraft', 'sr', 'messages', 'Радна верзија Ваше поруке је сачувана', '2013-07-19 14:24:10', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 52973),
	('yourmessageissavedasdraft', 'tr', 'messages', 'Mesajınız taslak olarak saklandı', '0000-00-00 00:00:00', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 1),
	('yourmessagewillbeprocessed', 'ca', 'messages', 'Hola <b>%s</b>,\r\n\r\nEl missatge (id #%d) s\'ha enviat correctament i el destinatari el rebrà ben aviat (pot arribar a trigar un parell d\'hores si el servidors tenen molta activitat).\r\n\r\nQuè vols fer ara?\r\n\r\nTornar al perfil del membre %s.\r\nComprovar els <a href="mymessages.php">missatges rebuts</a> .\r\n\r\n<a href="inviteafriend">Convidar un amic</a> a formar part de BeWelcome!\r\n\r\nFins aviat!', '2007-08-29 20:30:21', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 177),
	('yourmessagewillbeprocessed', 'da', 'messages', 'Hej <b>%s</b>.\r\nDin besked (id #%d) er blevet sendt og vil hurtigst muligt ankomme til modtageren (der kan dog være forsinkeler hvis presset på serveren er højt).\r\n\r\nHvis du vil kan du:\r\n\r\nFortsætte til %s\'s profil\r\nTjekke <a href="mymessages.php">din inbox</a>\r\n<a href="inviteafriend">Invitere en ven</a> til BeWelcome!\r\n\r\nHa\' en rar dag!', '2007-09-15 09:28:59', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 74),
	('yourmessagewillbeprocessed', 'de', 'messages', 'Hallo <b>%s</b>,\r\nDeine Nachricht (id #%d) wurde erfolgreich abgeschickt und wird so bald wie möglich an den Empfänger weitergeleitet (eine kurze Verzögerung von 10-20 Minuten kann, bei hoher Server-Last, durchaus vorkommen).\r\n\r\nWas möchtest Du als nächstes tun?\r\n\r\nZurück zum Profil von Mitglied %s\r\nChecke <a href="mymessages.php">Deinen Posteingang</a>\r\n<a href="inviteafriend">Lade einen Freund ein</a>, bei BeWelcome mitzumachen!\r\n\r\nViel Spaß!', '2007-08-29 10:28:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 3050),
	('yourmessagewillbeprocessed', 'en', 'messages', 'Hello <b>%s</b>,\r\nYour message (id #%d) was successfully submitted and will be sent as soon as possible. A short delay (10-20 minutes) might occur in case of high server activity.\r\n\r\nWhat do you want to do next?\r\n\r\nBack to the profile of member %s\r\nCheck <a href="mymessages.php">your messaging inbox</a>\r\n<a href="inviteafriend">Invite a friend</a> to join BeWelcome!\r\n\r\nHave a nice day!', '2008-04-11 17:24:35', '2019-04-23 18:16:49', '2010-01-24 09:28:02', 'yes', 'This word is not any more in use\r\n\r\nNotification when message has been sent to other member. The first parameter %s stands for the sending member (username), the second parameter (%s) for the receiving member (username). Please be careful not to change the position (just leave the parameters the way they are)', 5, 1, 1),
	('yourmessagewillbeprocessed', 'eo', 'messages', 'Saluton <b>%s</b>, \r\n\r\nVia mesaĝo (id #%d) sukcese alŝutiĝis kaj sendiĝos kiel eble plej rapide. Mallonga atendo (10-20 minutoj) povas okazi kiam la servilo tro aktivas.\r\n\r\nKion vi volas fari nun? \r\n\r\nReiri al la profilo de membro %s\r\nTrarigardi <a href="mymessages.php">vian mesaĝricevujon</a> aŭ\r\n<a href="inviteafriend">Inviti amikon</a> al BeWelcome! \r\n\r\nĈion Bonan!', '2007-09-10 22:33:31', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 1769),
	('yourmessagewillbeprocessed', 'es', 'messages', 'Hola <b>%s</b>,\r\nTu mensaje (id #%d) fue sometido exitosamente y será enviado lo más rápido posible (un corto retraso de algunas horas podría ocurrir en caso de que haya mucha actividad en el servidor).\r\n\r\n¿Qué quieres hacer ahora?\r\n\r\nVolver al perfil del usuario %s\r\nRevisar tus <a href="mymessages.php">mensajes enviados</a>\r\n¡<a href="inviteafriend">Invitar a un amigo</a> a unirse a BeWelcome!\r\n\r\n¡Qué tengas un buen día!', '2007-12-31 23:46:51', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 1328),
	('yourmessagewillbeprocessed', 'fi', 'messages', 'Hei <b>%s</b>,\r\nViestisi (id #%d) on onnistuneesti tallennettu ja se tullaan lähettämään ensitilassa. Jos palvelimet ovat ruuhkaisia, viive saattaa olla korkeintaan muutamia tunteja.\r\n\r\nMitä haluat tehdä seuraavaksi?\r\n\r\nTakaisin jäsenen %s profiiliin\r\nTarkista <a href="mymessages.php">saapuneet viestisi</a>\r\n<a href="inviteafriend">kutsu ystäväsi</a> BeWelcomeen!\r\n\r\nHyvää päivänjatkoa!', '2008-06-03 07:10:45', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 72),
	('yourmessagewillbeprocessed', 'fr', 'messages', 'Bonjour <b>%s</b>\r\nVotre message (id #%d) a été pris en compte et va être envoyé dès que possible (de quelques secondes à plusieurs minutes selon l\'activité des serveurs)\r\n\r\nQue désirez vous faire ensuite ?\r\n\r\nRevenir sur le profil de %s\r\nVérifier <a href="mymessages.php">vos messages</a>\r\n<a href="inviteafriend">inviter un ami</a> à rejoindre BeWelcome !\r\n\r\nBonne journée !', '2007-08-30 09:56:18', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 68),
	('yourmessagewillbeprocessed', 'hr', 'messages', 'Bok<b>%s</b>, \r\nTvoja poruka (id #%d) uspješno je zaprimljena i bit će poslana čim to okolnosti dopuste. Naime, može doći do kraćeg kašnjenja (10-20 minuta) ako je server prezauzet. \r\n\r\nŠto želiš učiniti slijedeće? \r\n\r\nVratiti se na profil %s \r\nProvjeriti svoj <a href="mymessages.php">your poštanski sandučić</a> \r\n<a href="inviteafriend">Inpozvati prijatelje</a>  da se učlane u BeWelcome! \r\n\r\nŽelimo ti dobar dan! ', '2009-09-12 16:08:30', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 8197),
	('yourmessagewillbeprocessed', 'it', 'messages', 'Ciao <b>%s</b>,  il tuo messaggio (id #%d) è stato inviato correttamente e sarà recapitato il più presto possibile (può essere possibile un ritardo di alcune ore in caso di elevata attività del server). Cosa vuoi fare ora? Torna al profilo di %s. Controlla <a href="mymessages.php">i tuoi messaggi in entrata.</a> <a href="inviteafriend">Invita un amico</a> ad iscriversi a BeWelcome! Ti auguriamo una buona giornata!', '2007-09-29 11:46:03', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 103),
	('yourmessagewillbeprocessed', 'lt', 'messages', 'Sveiki, <b>%s</b>,\r\njūsų žinutė (id #%d) buvo sėkmingai patvirtinta siuntimui ir bus išsiųsta kuo greičiau (iki kelių valandų delsimai yra imanomi aukšto aktyvumo serveryje atveju).\r\n\r\nKą norite daryti dabar?\r\n\r\nAtgal į nario %s anketą\r\nPatikrinti <a href="mymessages.php">savo pašto dėžutę</a> \r\n<a href="inviteafriend">Pakvieskite draugą</a> prisijungti prie BeWelcome!\r\n\r\nGeros dienos!\r\n', '2007-08-31 17:17:51', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 227),
	('yourmessagewillbeprocessed', 'lv', 'messages', 'Sveiks <b>%s</b>,\r\nTava vēstule (id #%d) tika veiksmīgi apstiprināta un tiks nosūtīta pēc iespējas ātrāk (neliela dažu stundu aizkavēšanās var parādīties gadījumā, ja ir augsta servera aktivitāte).\r\n\r\nKo tu vēlies darīt tālāk?\r\n\r\nAtgriezties uz biedra %s profilu\r\nPārbaudīt <a href="mymessages.php">savu vēstuļu pastkasti</a>\r\n<a href="inviteafriend">Uzaicināt draugu</a> pievienoties BeWelcome!\r\n\r\nVeiksmīgu atlikušo dienu!', '2007-09-02 13:36:48', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 375),
	('yourmessagewillbeprocessed', 'nl', 'messages', 'Hoi <b>%s</b>, \r\nJe bericht (id #%d) is correct opgeslagen en zal zo snel mogelijk verstuurd worden (soms is er een vertraging van enkele uren indien er veel verkeer is op de server). \r\n\r\nWat wil je nu doen? \r\n\r\nTerug naar het profiel van lid %s \r\nBekijk je <a href="mymessages.php">berichten</a> \r\n<a href="inviteafriend">Nodig een vriend uit </a> om BeWelcome te ontdekken! \r\n\r\nVeel plezier!', '2007-08-31 11:25:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 69),
	('yourmessagewillbeprocessed', 'pl', 'messages', 'Witaj <b>%s</b>,\r\nTwoja wiadomość (id #%d) została przyjęta do realizacji i zostanie wkrótce wysłana (w przypadku dużego obciążenia serwera może wystąpić kilkugodzinne opóźnienie). \r\n\r\nCo chcesz teraz zrobić?\r\n\r\nWrócić do profilu %s\r\nSprawdzić <a href="mymessages.php">swoją skrzynkę wiadomości</a>\r\n<a href="inviteafriend">Zaprosić przyjaciela</a> żeby dołączył do BeWelcome!\r\n\r\nMiłego dnia!', '2007-10-13 16:59:41', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 1554),
	('yourmessagewillbeprocessed', 'pt', 'messages', 'Olá <b>%s</b>,\r\nA sua mensagem (id #%d) foi submetida com sucesso e será enviada assim que possível (no caso de uma alta carga do servidor, poderá demorar umas horas).\r\n\r\nO que fazer a seguir.\r\n\r\nVoltar ao perfil de %s\r\nVer a sua <a href="mymessages.php">caixa de correio</a>\r\n<a href="inviteafriend">Convide um amigo</a> ao BeWelcome!\r\n\r\nTenha um bom dia!', '2007-09-21 05:47:22', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 752),
	('yourmessagewillbeprocessed', 'pt-BR', 'messages', '  	Olá <b>%s</b>,\r\nA sua mensagem (id #%d) foi submetida com sucesso e vai ser enviada o mais breve possível (um curto atraso de poucas horas pode acontecer caso o servidor esteja em alta actividade).\r\n\r\nO que voce quer fazer de seguida?\r\n\r\nDe volta para o perfil do membro %s\r\nChecar a <a href="mymessages.php">caixa de entrada</a>\r\n<a href="inviteafriend">Convidar um amigo</a> para se juntar ao BeWelcome!\r\n\r\nTenha um Bom dia!', '2007-10-28 06:41:23', '2021-05-02 07:49:01', '0000-00-00 00:00:00', 'yes', '', 5, 1, 421),
	('yourmessagewillbeprocessed', 'ru', 'messages', 'Доброго времени суток, <b>%s</b>,\r\nВаше сообшение (id #%d) было отправлено и будет переслано на адрес электоронной почты адресата (небольшая задержка возможна в случае высокой активности на сервере).\r\n\r\nЧто вы хотите сделать теперь?\r\n\r\nВернуться к профилю %s\r\nПроверить <a href="mymessages.php">папку входящие</a>\r\n<a href="inviteafriend">Пригласить друга</a> присоединиться к BeWelcome!\r\n\r\nВсего хорошего!', '2007-09-08 06:54:27', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'yes', '', 5, 1, 79),
	('yousenttomanymessages', 'ca', 'messages', 'Has enviat massa missatges en un breu període de temps. Si us plau, prova-ho més tard. ', '2012-07-22 21:47:01', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 11944),
	('yousenttomanymessages', 'cs', 'messages', 'Poslal(a) jsi příliš mnoho zpráv ve krátkém časovém období. Zkus to prosím znovu později.', '2014-01-18 00:09:34', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 34292),
	('yousenttomanymessages', 'de', 'messages', 'Du hast zu viele Nachrichten innerhalb einer kurzen Zeit versendet. Bitte versuche es später erneut.', '2012-04-12 17:05:34', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 202),
	('yousenttomanymessages', 'el', 'messages', 'Έστειλες πάρα πολλά μηνύματα σε σύντομο χρονικό διάστημα.Προσπάθησε ξανά αργότερα.', '2020-08-14 18:35:22', '2020-08-14 18:35:22', '2020-08-14 18:35:22', 'no', '', 5, NULL, 266544),
	('yousenttomanymessages', 'en', 'messages', 'You sent too many messages in a short period of time. Please try again later.', '2012-04-12 17:04:38', '2019-04-23 18:16:49', '2012-04-12 17:04:38', 'no', '', 5, NULL, 202),
	('yousenttomanymessages', 'es', 'messages', 'Has enviado demasiados mensajes en un periodo corto de tiempo. Inténtalo de nuevo más tarde', '2013-11-09 15:08:23', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 40088),
	('yousenttomanymessages', 'fr', 'messages', 'Vous avez envoyé trop de messages récemment. Veuillez réessayer plus tard.', '2012-04-12 21:08:19', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 9823),
	('yousenttomanymessages', 'gl', 'messages', 'Enviaches demasiadas mensaxes nun período de tempo curto. Por favor inténtao de novo máis tarde.', '2021-03-11 17:28:18', '2021-03-11 17:28:18', '2021-03-11 17:28:18', 'no', '', 5, NULL, 210880),
	('yousenttomanymessages', 'hr', 'messages', 'Poslao-la si previše poruka u kratkom roku. Molim te, pokušaj ponovno malo kasnije.', '2012-09-19 19:37:39', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 24014),
	('yousenttomanymessages', 'it', 'messages', 'Hai inviato troppi messaggi in un breve lasso di tempo. Riprova più tardi, grazie.', '2013-01-15 18:30:12', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 14616),
	('yousenttomanymessages', 'nl', 'messages', 'Je stuurde teveel berichten in korte tijd.  Probeer later opnieuw.', '2012-09-15 19:43:20', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 22382),
	('yousenttomanymessages', 'pl', 'messages', 'Wysłałaś/eś zbyt wiele wiadomości w krótkim czasie. Spróbuj ponownie później.', '2021-01-13 19:42:07', '2021-01-13 19:42:07', '2021-01-13 19:42:07', 'no', '', 5, NULL, 116789),
