	('yousenttomanymessages', 'ru', 'messages', 'Вы отправили слишком много соообщений за короткий период времени. Пожалуйста, попробуйте позднее.', '2014-05-16 18:39:12', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 73061),
