	('yousenttomanymessages', 'sv', 'messages', 'Du skickade visst lite för många meddelanden på för kort tid så vi hann inte med. Prova igen om en stund!', '2012-10-03 08:05:31', '2019-04-23 18:16:49', '0000-00-00 00:00:00', 'no', '', 5, NULL, 33693),
